def product_base_price(item: str, default: Optional[float] = None) -> float:
    """상품 기본가. 구 스케일 매직넘버(20/30/35/40/100) 대신 사다리 값을 쓴다."""
    if item in PRODUCT_BASE_PRICES:
        return float(PRODUCT_BASE_PRICES[item] or 0.0)
    if default is not None:
        return float(default)
    return 7.5


def labor_seed_wage(labor_type: str) -> float:
    return float(LABOR_TYPES.get(labor_type, LABOR_TYPES.get("미교육", 6.0)) or 6.0)


