def occupation_company_id(country_id: str, company_type: str, index: int = 0) -> str:
    """시퀀스형 법인 ID. index=0은 하위 호환용 레거시 ID와 동일."""
    base = f"co_{country_id}_{normalize_company_type(company_type).replace(' ', '_')}"
    return base if index <= 0 else f"{base}_{index}"


def retail_company_id(country_id: str, index: int = 0) -> str:
    return occupation_company_id(country_id, RETAIL_COMPANY_TYPE, index)


def normalize_company_type(company_type: str) -> str:
    """구 중소기업 타입명을 일반 직종으로 정규화."""
    return LEGACY_SME_TYPE_MAP.get(company_type, company_type)


def next_company_seq_id(world: "World", country_id: str, company_type: str) -> str:
    """국가·직종별 다음 가용 법인 ID."""
    ctype = normalize_company_type(company_type)
    idx = 0
    while True:
        cid = occupation_company_id(country_id, ctype, idx)
        if cid not in world.companies:
            return cid
        idx += 1


def company_is_listed(world: "World", company_id: str) -> bool:
    """공개 주식시장에 상장되어 매매 가능한지."""
    co = world.companies.get(company_id)
    if co is None:
        return False
    # 협력 중소기업은 항상 비상장
    if company_is_coop_partner(co):
        return False
    if int(getattr(co, "ipo_weeks_left", 0) or 0) > 0:
        return True
    if bool(getattr(co, "listed", False)):
        return company_id in world.stock_markets
    # 하위 호환: listed 미설정 + stock_markets 등록 = 상장
    if company_id in world.stock_markets and getattr(co, "listed", None) is None:
        return True
    return False


def company_can_issue_bonds(co: Optional["Company"]) -> bool:
    """회사채 발행 가능 여부. 협력 중소기업은 대출만 가능."""
    if co is None:
        return False
    if company_is_coop_partner(co):
        return False
    return True


def lock_coop_partner_financing(co: "Company") -> None:
    """협력 중소기업: 비상장·채권 발행 불가 상태를 강제."""
    if not company_is_coop_partner(co):
        return
    co.listed = False
    co.is_sme = True
    co.ipo_weeks_left = 0
    co.seasoned_weeks_left = 0
    co.corp_bond_auto_issue = False
    co.corp_bond_auto_issue_amount = 0.0
    co.corp_bond_gov_purchase_remaining = 0.0
    co.pending_bond_sell = 0.0
    co.pending_bond_issue = 0.0
    if hasattr(co, "office_pending_bond_issue"):
        co.office_pending_bond_issue = 0.0
    for fac in getattr(co, "facilities", []) or []:
        if hasattr(fac, "pending_bond_issue"):
            fac.pending_bond_issue = 0.0


