def facility_is_retail(spec: Optional[Dict] = None, facility_name: str = "") -> bool:
    if spec is None:
        spec = FACILITY_SPECS.get(facility_name) or SELF_EMP_FACILITY_SPECS.get(facility_name) or {}
    return bool(spec.get("retail"))


def facility_throughput_qty(spec: Dict) -> float:
    return float(spec.get("throughput_qty") or spec.get("output_qty") or 0.0)


def retail_store_levels(co: "Company", state_id: str = "") -> int:
    total = 0
    for fac in getattr(co, "facilities", []) or []:
        if fac.name != RETAIL_STORE_FACILITY:
            continue
        if state_id and fac.state_id != state_id:
            continue
        total += fac.active_levels()
    return total


def retail_store_throughput(
    co: "Company",
    state_id: str,
    labor_fill: float = 1.0,
    input_fill: float = 1.0,
) -> float:
    spec = FACILITY_SPECS.get(RETAIL_STORE_FACILITY, {})
    qty = facility_throughput_qty(spec)
    levels = retail_store_levels(co, state_id)
    return max(0.0, qty * levels * clamp(labor_fill, 0.0, 1.0) * clamp(input_fill, 0.0, 1.0))


def retail_companies_in_country(world: "World", country_id: str) -> List["RetailCompany"]:
    """해당 국가의 모든 소매 기업 (대표 1곳이 아님)."""
    out: List["RetailCompany"] = []
    for co in getattr(world, "companies", {}).values():
        if not isinstance(co, RetailCompany):
            continue
        cid = getattr(co, "country_id", None)
        if not cid:
            st = world.states.get(getattr(co, "home_state", None))
            cid = getattr(st, "country_id", None) if st else None
        if cid == country_id:
            out.append(co)
    out.sort(key=lambda r: str(getattr(r, "id", "")))
    return out


def retail_company_target_share(
    company: "Company",
    world: "World",
    state_id: str = "",
) -> float:
    """국가 내 소매 기업 간 목표 점유율 (매력도 비중). 피어 없으면 1."""
    cid = getattr(company, "country_id", None)
    if not cid:
        st = world.states.get(state_id or getattr(company, "home_state", None))
        cid = getattr(st, "country_id", None) if st else None
    peers = retail_companies_in_country(world, cid) if cid else []
    if not peers:
        return 1.0
    weights = [max(company_product_attractiveness(r), 1e-9) for r in peers]
    total = sum(weights)
    if total <= 1e-15:
        return 1.0 / max(len(peers), 1)
    for r, w in zip(peers, weights):
        if r.id == company.id:
            return w / total
    return 1.0 / max(len(peers) + 1, 1)


def state_retail_goods_demand(world: "World", st: "State") -> float:
    """주 소비재 소매 수요. 전주 집계가 있으면 그대로, 없으면 채널 판매량 합."""
    demand = float(getattr(st, "last_retail_goods_demand", 0.0) or 0.0)
    if demand > 1e-9:
        return demand
    commerce = (getattr(st, "self_employed", None) or {}).get(COMMERCE_SECTOR)
    demand = float(getattr(commerce, "last_goods_demand", 0.0) or 0.0) if commerce else 0.0
    if demand > 1e-9:
        return demand
    vol = 0.0
    for r in retail_companies_in_country(world, st.country_id):
        vol += float((getattr(r, "state_weekly_volume", None) or {}).get(st.id, 0.0) or 0.0)
    if commerce is not None:
        vol += float(getattr(commerce, "weekly_retail_volume", 0.0) or 0.0)
    return vol


def retail_goods_order_soft_cap(
    demand: float,
    prev_service_bought: float,
    *,
    per_goods: float = RETAIL_SERVICE_PER_GOODS,
    pass_through: float = RETAIL_SERVICE_SHORTFALL_PASS_THROUGH,
) -> float:
    """전주 소매 서비스 매수량 기준 재화 주문 soft limit.

    allowed = (1-pt)*D + pt*min(D, S_prev/per_goods)
    부족분의 pass_through 비율만 주문 축소 (예: D=100,S=50,pt=0.5 → 75).
    """
    d = max(0.0, float(demand or 0.0))
    if d <= 1e-12:
        return 0.0
    svc_cap = max(0.0, float(prev_service_bought or 0.0)) / max(float(per_goods), 1e-9)
    pt = clamp(float(pass_through), 0.0, 1.0)
    return (1.0 - pt) * d + pt * min(d, svc_cap)


def scale_order_dict(orders: Dict[str, float], scale: float) -> Dict[str, float]:
    """주문 dict를 scale배로 (양수만 유지)."""
    if scale >= 1.0 - 1e-15:
        return {k: float(v) for k, v in orders.items() if float(v) > 1e-12}
    if scale <= 1e-15:
        return {}
    out: Dict[str, float] = {}
    for k, v in orders.items():
        q = float(v) * scale
        if q > 1e-12:
            out[k] = q
    return out


def retailer_effective_state_cap(retailer: "RetailCompany", state_id: str) -> float:
    """주문 배분용 주별 소매 처리 용량. 매장 없으면 0."""
    cap = float(retailer.state_throughput(state_id) or 0.0)
    levels = retail_store_levels(retailer, state_id)
    if cap <= 1e-9 and levels <= 0:
        return 0.0
    if cap > 1e-9:
        return cap
    per = facility_throughput_qty(FACILITY_SPECS.get(RETAIL_STORE_FACILITY, {}))
    return max(per, 1.0) * max(1, levels)


def allocate_qty_by_weights(
    qty: float,
    weights: List[float],
    caps: Optional[List[float]] = None,
) -> List[float]:
    """수량 q를 비중으로 나누고, caps가 있으면 잔량을 여유 용량에 재배분."""
    n = len(weights)
    if n <= 0 or qty <= 1e-12:
        return [0.0] * n
    w = [max(0.0, float(x)) for x in weights]
    total = sum(w)
    if total <= 1e-15:
        w = [1.0] * n
        total = float(n)
    out = [qty * (wi / total) for wi in w]
    if caps is None:
        return out
    cap_v = [max(0.0, float(c)) for c in caps]
    for i in range(n):
        out[i] = min(out[i], cap_v[i])
    leftover = max(0.0, qty - sum(out))
    if leftover <= 1e-12:
        return out
    remain = [max(0.0, cap_v[i] - out[i]) for i in range(n)]
    rtot = sum(remain)
    if rtot <= 1e-12:
        return out
    for i in range(n):
        out[i] = min(cap_v[i], out[i] + leftover * (remain[i] / rtot))
    return out


def commerce_market_labor_fill(sector_obj: Optional["SelfEmployedSector"]) -> float:
    """자영 상업 노동 충족률 — 임대 규모 대비 배치 노동."""
    if sector_obj is None:
        return 1.0
    rental = float(getattr(sector_obj, "rental_filled", 0.0) or 0.0)
    if rental <= 1e-9:
        return clamp(float(getattr(sector_obj, "last_labor_fill", 1.0) or 1.0), 0.0, 1.0)
    labor_req = ("미교육", 0.7)
    spec = globals().get("SELF_EMP_ACTIVITY_SPECS") or {}
    if isinstance(spec, dict):
        labor_req = spec.get("자영 상업", {}).get("labor") or labor_req
    lqty = float(labor_req[1]) if labor_req else 0.7
    labor_cap = lqty * rental
    workers = float(getattr(sector_obj, "workers", 0.0) or 0.0)
    if labor_cap > 1e-9:
        return clamp(workers / labor_cap, 0.0, 1.0)
    return clamp(float(getattr(sector_obj, "last_labor_fill", 1.0) or 1.0), 0.0, 1.0)


def commerce_market_input_fill(sector_obj: Optional["SelfEmployedSector"]) -> float:
    if sector_obj is None:
        return 1.0
    return clamp(float(getattr(sector_obj, "last_input_fill_ratio", 1.0) or 1.0), 0.0, 1.0)


def commerce_market_retail_capacity(sector_obj: Optional["SelfEmployedSector"]) -> float:
    """소매 채널 용량 = 임대 매수 × throughput × 노동 충족."""
    if sector_obj is None:
        return 0.0
    per = float(globals().get("RE_SELF_EMP_COMMERCE_THROUGHPUT_PER_RENTAL", 24.0) or 24.0)
    spec = globals().get("SELF_EMP_ACTIVITY_SPECS") or {}
    if isinstance(spec, dict):
        per = float(spec.get("자영 상업", {}).get("throughput_per_rental", per) or per)
    rental = float(getattr(sector_obj, "rental_filled", 0.0) or 0.0)
    if rental <= 1e-9:
        rental = float(getattr(sector_obj, "rental_ordered", 0.0) or 0.0)
    labor = commerce_market_labor_fill(sector_obj)
    return max(0.0, per * rental * labor)


def commerce_market_throughput(
    sector_obj: Optional["SelfEmployedSector"],
    labor_fill: float = 1.0,
) -> float:
    """실효 처리량 = 노동 용량 × 투입 충족."""
    _ = labor_fill  # 하위 호환; 실제 노동은 commerce_market_labor_fill 사용
    return (
        commerce_market_retail_capacity(sector_obj)
        * commerce_market_input_fill(sector_obj)
    )


def is_corp_retail_buyer_id(buyer_id: str) -> bool:
    suffix = f"_{RETAIL_COMPANY_TYPE.replace(' ', '_')}"
    return bool(buyer_id) and buyer_id.startswith("co_") and buyer_id.endswith(suffix)


def is_commerce_market_actor_id(buyer_id: str) -> bool:
    parsed = parse_self_employed_actor_id(buyer_id)
    return parsed is not None and parsed[1] == COMMERCE_SECTOR


def _scale_buy_result_fill(br: "BuyResult", new_filled: float) -> None:
    old = br.filled_quantity
    br.filled_quantity = max(0.0, new_filled)
    if old <= 1e-9:
        if br.filled_quantity <= 1e-9:
            br.received_items.clear()
        return
    ratio = br.filled_quantity / old
    for tech in list(br.received_items.keys()):
        br.received_items[tech] = br.received_items[tech] * ratio


def _apply_retail_channel_buy_reserve(
    open_buys: List["BuyOrder"],
    buy_results: List["BuyResult"],
    transaction_qty: float,
) -> None:
    """소매·자영 시장 도매 매수 체결 — 자영 시장 최소 점유율 보장."""
    if transaction_qty <= 1e-9 or len(open_buys) != len(buy_results):
        return
    corp_idx: List[int] = []
    mkt_idx: List[int] = []
    corp_qty = 0.0
    mkt_qty = 0.0
    for i, bo in enumerate(open_buys):
        if is_commerce_market_actor_id(bo.buyer_id):
            mkt_idx.append(i)
            mkt_qty += bo.quantity
        elif is_corp_retail_buyer_id(bo.buyer_id):
            corp_idx.append(i)
            corp_qty += bo.quantity
    if not mkt_idx or not corp_idx or mkt_qty <= 1e-9:
        return
    current_mkt = sum(buy_results[i].filled_quantity for i in mkt_idx)
    min_mkt = min(mkt_qty, transaction_qty * RETAIL_MARKET_MIN_SHARE)
    if current_mkt >= min_mkt - 1e-9:
        return
    need = min_mkt - current_mkt
    taken = 0.0
    for i in corp_idx:
        if taken >= need - 1e-9:
            break
        take = min(need - taken, buy_results[i].filled_quantity)
        if take <= 1e-9:
            continue
        _scale_buy_result_fill(buy_results[i], buy_results[i].filled_quantity - take)
        taken += take
    if taken <= 1e-9:
        return
    remaining = taken
    for i in mkt_idx:
        if remaining <= 1e-9:
            break
        room = max(0.0, open_buys[i].quantity - buy_results[i].filled_quantity)
        add = min(remaining, room)
        if add <= 1e-9:
            continue
        _scale_buy_result_fill(buy_results[i], buy_results[i].filled_quantity + add)
        remaining -= add


def retail_logistics_infra_factor(state: "State") -> float:
    """도로·철도 여유도 → 클수록 물류 부담 감소 (하한 0.45, 상한 1.35).

    인구·공공 수요 대비 여유도 + 절대 용량을 함께 반영한다.
    """
    pops = getattr(state, "pops", None) or []
    pop_total = sum(p.total_population() for p in pops) if pops else 0.0
    gov = getattr(state, "local_government", None)
    world = getattr(gov, "_world_ref", None) if gov is not None else None
    stock = state_private_facility_stock(world, str(getattr(state, "id", "") or ""))
    road_need = max(
        PUBLIC_DEMAND_ROAD_FLOOR,
        pop_total / PUBLIC_DEMAND_ROAD_POP_DIV + stock * PUBLIC_DEMAND_ROAD_STOCK)
    rail_need = max(
        PUBLIC_DEMAND_RAIL_FLOOR,
        pop_total / PUBLIC_DEMAND_RAIL_POP_DIV + stock * PUBLIC_DEMAND_RAIL_STOCK)
    max_infra = getattr(state, "max_infrastructure", None) or {}
    infra = getattr(state, "infrastructure", None) or {}
    road = float(max_infra.get("road", infra.get("road", 0.0)) or 0.0)
    rail = float(max_infra.get("rail", infra.get("rail", 0.0)) or 0.0)
    road_ratio = clamp(road / max(road_need, 1e-9), 0.0, 2.5)
    rail_ratio = clamp(rail / max(rail_need, 1e-9), 0.0, 2.5)
    # 절대 용량 보조 (소형 주도 구분)
    road_abs = clamp(road / 120.0, 0.0, 2.0)
    rail_abs = clamp(rail / 80.0, 0.0, 2.0)
    raw = 0.35 * road_ratio + 0.25 * rail_ratio + 0.25 * road_abs + 0.15 * rail_abs
    return clamp(0.45 + 0.40 * raw, 0.45, 1.35)


def retail_market_logistics_infra_factor(infra_factor: float) -> float:
    """자영 시장 물류 인프라 계수 — 기업보다 완만하게 반영 (1.0=중립)."""
    blended = 1.0 + (infra_factor - 1.0) * RETAIL_MARKET_INFRA_SENSITIVITY
    return clamp(blended, 0.55, 1.25)


def retail_scale_factor(co: "Company") -> float:
    """전국 매장 가동단계↑ → 단위 마진 할인 (0.55~1.0)."""
    levels = float(retail_store_levels(co))
    if levels <= 1e-9:
        return 1.0
    progress = clamp(levels / max(RETAIL_SCALE_REF_LEVELS, 1.0), 0.0, 1.5)
    return clamp(1.0 - 0.45 * min(progress, 1.0), 0.55, 1.0)


def goods_glut_down_lambda(
    base_down: float,
    sd_ma: Optional[float] = None,
    *,
    glut_bonus: float = GOODS_ASK_DOWN_GLUT_BONUS,
) -> float:
    """공급과잉일수록 인하 λ를 키움. sd_ma≥1이면 base_down 유지."""
    s = 1.0 if sd_ma is None else float(sd_ma)
    glut = max(0.0, 1.0 - s)
    return clamp(float(base_down) + glut * float(glut_bonus), 0.0, 1.0)


def goods_asymmetric_mean_revert_lambda(
    price: float,
    long_ref: float,
    *,
    below_lambda: float,
    above_lambda: float,
) -> float:
    """가격이 장기 기준가보다 높을 때만 회귀를 강하게."""
    if long_ref > 1e-12 and float(price) > float(long_ref) + 1e-12:
        return clamp(float(above_lambda), 0.0, 1.0)
    return clamp(float(below_lambda), 0.0, 1.0)


def apply_asymmetric_price_rigidity(
    computed: float,
    last: Optional[float],
    *,
    up_lambda: float,
    down_lambda: float,
    sd_ma: Optional[float] = None,
    glut_bonus: float = 0.0,
) -> float:
    """계산가 ≥ 전기가 → 갭의 대부분, 계산가 < 전기가 → 갭의 일부만. 주당 % 한도 없음.

    sd_ma<1이면 인하 λ에 glut_bonus를 가산 (원가호가에 수급배수는 곱하지 않음).
    """
    computed = max(0.0, float(computed))
    last_p = float(last or 0.0)
    if last_p <= 1e-12:
        return max(computed, 1e-9)
    gap = computed - last_p
    down_eff = goods_glut_down_lambda(
        down_lambda, sd_ma, glut_bonus=glut_bonus) if gap < 0.0 else down_lambda
    lam = clamp(float(up_lambda if gap >= 0.0 else down_eff), 0.0, 1.0)
    return max(last_p + lam * gap, 1e-9)


def quote_corporate_retail_price(
    market_price: float,
    product: str,
    logistics_price: float,
    infra_factor: float,
    scale_factor: float,
    last_price: Optional[float] = None,
    sd_ma: Optional[float] = None,
) -> float:
    weight = PRODUCT_WEIGHTS.get(product, 1.0)
    margin = RETAIL_CORP_BASE_MARGIN * scale_factor
    logistics = (
        weight * RETAIL_CORP_LOGISTICS_COEFF * logistics_price
        / max(infra_factor, 1e-9)
    )
    raw = max(0.0, market_price * (1.0 + margin) + logistics)
    return apply_asymmetric_price_rigidity(
        raw, last_price,
        up_lambda=GOODS_ASK_UP_LAMBDA,
        down_lambda=GOODS_RETAIL_DOWN_LAMBDA,
        sd_ma=sd_ma,
        glut_bonus=GOODS_RETAIL_DOWN_GLUT_BONUS,
    )


def estimate_commerce_opex_per_unit(
    world: Optional["World"],
    state: Optional["State"],
    sector_obj: Optional["SelfEmployedSector"],
) -> float:
    """자영 상업 고정비(임대·노동·전력)를 예상 판매량으로 나눈 단위 전가분.

    정격 용량이 아니라 실제 소매량(없으면 용량의 45% 하한) 기준으로 전가해
    저가동·과잉 임대 상태에서도 고정비를 회수한다.
    """
    if sector_obj is None:
        return 0.0
    rental = max(
        float(getattr(sector_obj, "rental_filled", 0.0) or 0.0),
        float(getattr(sector_obj, "rental_ordered", 0.0) or 0.0),
        float(SELF_EMP_RENTAL_ORDER_BASE),
    )
    act = (SELF_EMP_ACTIVITY_SPECS or {}).get(COMMERCE_ACTIVITY_NAME) or {}
    labor = act.get("labor") or ("미교육", 1.0)
    ltype = labor[0]
    lqty = float(labor[1]) if len(labor) > 1 else 1.0
    power_qty = float((act.get("inputs") or {}).get("전력 서비스", 0.5) or 0.5)
    per = float(
        act.get("throughput_per_rental", RE_SELF_EMP_COMMERCE_THROUGHPUT_PER_RENTAL)
        or RE_SELF_EMP_COMMERCE_THROUGHPUT_PER_RENTAL
    )
    rent_p = product_base_price("임대 서비스")
    labor_p = labor_seed_wage(ltype)
    power_p = product_base_price("전력 서비스")
    if world is not None and state is not None:
        rm = world.markets.get(market_key(state.id, "임대 서비스"))
        if rm:
            rent_p = float(market_goods_labor_price(rm) or rent_p)
        lm = world.labor_markets.get(market_key(state.id, ltype))
        if lm:
            labor_p = float(labor_pay_price(lm) or labor_p)
        pm = world.markets.get(market_key(state.id, "전력 서비스"))
        if pm:
            power_p = float(market_goods_labor_price(pm) or power_p)
    fixed = rental * (rent_p + lqty * labor_p + power_qty * power_p)
    capacity = max(rental * per, 1.0)
    sold = float(getattr(sector_obj, "last_settled_retail_volume", 0.0) or 0.0)
    if sold <= 1e-9:
        sold = float(getattr(sector_obj, "weekly_retail_volume", 0.0) or 0.0)
    # 저가동 시 단가↑ — 과잉 임대를 가격·축소 압력으로 흡수
    denom = max(sold, capacity * 0.45, 1.0)
    return max(0.0, (fixed / denom) * RETAIL_MARKET_OPEX_COVER)


def quote_market_retail_price(
    market_price: float,
    product: str,
    logistics_price: float,
    infra_factor: float = 1.0,
    opex_per_unit: float = 0.0,
    last_price: Optional[float] = None,
    sd_ma: Optional[float] = None,
) -> float:
    weight = PRODUCT_WEIGHTS.get(product, 1.0)
    mkt_infra = retail_market_logistics_infra_factor(infra_factor)
    logistics = (
        weight * RETAIL_CORP_LOGISTICS_COEFF * logistics_price
        * RETAIL_MARKET_LOCAL_LOGISTICS_SHARE
        / max(mkt_infra, 1e-9)
    )
    goods = (
        market_price
        * (1.0 + RETAIL_MARKET_BASE_MARGIN)
        * RETAIL_MARKET_COGS_COVER
    )
    raw = max(
        0.0,
        goods + logistics + max(0.0, float(opex_per_unit)),
    )
    return apply_asymmetric_price_rigidity(
        raw, last_price,
        up_lambda=GOODS_ASK_UP_LAMBDA,
        down_lambda=GOODS_RETAIL_DOWN_LAMBDA,
        sd_ma=sd_ma,
        glut_bonus=GOODS_RETAIL_DOWN_GLUT_BONUS,
    )


def quote_overflow_retail_price(
    market_price: float,
    product: str,
    logistics_price: float,
    infra_factor: float = 1.0,
    load_util: float = 1.0,
    opex_per_unit: float = 0.0,
    last_price: Optional[float] = None,
    sd_ma: Optional[float] = None,
) -> float:
    """정격 초과·비공식 유통가 — 정식 시장보다 마진·물류·혼잡 할증."""
    weight = PRODUCT_WEIGHTS.get(product, 1.0)
    mkt_infra = retail_market_logistics_infra_factor(infra_factor)
    logistics = (
        weight * RETAIL_CORP_LOGISTICS_COEFF * logistics_price
        * RETAIL_MARKET_LOCAL_LOGISTICS_SHARE
        * RETAIL_OVERFLOW_LOGISTICS_MULT
        / max(mkt_infra, 1e-9)
    )
    congestion = 1.0 + RETAIL_CONGESTION_PRICE_ALPHA * max(0.0, float(load_util) - 1.0)
    margin = RETAIL_MARKET_BASE_MARGIN + RETAIL_OVERFLOW_MARGIN
    goods = (
        market_price
        * (1.0 + margin)
        * congestion
        * RETAIL_MARKET_COGS_COVER
    )
    raw = max(
        0.0,
        goods + logistics + max(0.0, float(opex_per_unit)),
    )
    return apply_asymmetric_price_rigidity(
        raw, last_price,
        up_lambda=GOODS_ASK_UP_LAMBDA,
        down_lambda=GOODS_RETAIL_DOWN_LAMBDA,
        sd_ma=sd_ma,
        glut_bonus=GOODS_RETAIL_DOWN_GLUT_BONUS,
    )


def retail_overflow_settle_eff(overflow_util: float) -> float:
    """overflow 부하(overflow/정격)↑ → 정산 효율↓."""
    u = max(0.0, float(overflow_util))
    return clamp(
        RETAIL_OVERFLOW_EFF_BASE / (1.0 + RETAIL_CONGESTION_EFF_DELTA * u),
        0.25,
        1.0,
    )


def allocate_retail_channel_qty_with_overflow(
    qty: float,
    corp_price: float,
    market_price: float,
    corp_capacity: float,
    market_capacity: float,
    corp_labor: float = 1.0,
    market_labor: float = 1.0,
) -> Tuple[float, float, float]:
    """정격 채널 배분 + 잔량 overflow. 반환: (corp, market, overflow)."""
    c_qty, m_qty = allocate_retail_channel_qty(
        qty, corp_price, market_price, corp_capacity, market_capacity,
        corp_labor=corp_labor, market_labor=market_labor,
    )
    overflow = max(0.0, float(qty) - c_qty - m_qty)
    return c_qty, m_qty, overflow


def commerce_rental_target_from_gap(
    sector_obj: Optional["SelfEmployedSector"],
    corp_cap_nom: float = 0.0,
) -> float:
    """실제 소매량·판매 가능 overflow에 맞춘 자영 상업 임대 목표.

    도매 주문량(미체결·노동 헤어컷 포함)에 맞추면 임대·고정비만 부풀어 적자가 난다.
    """
    base = SELF_EMP_RENTAL_ORDER_BASE * 1.5
    if sector_obj is None:
        return clamp(base, 1.0, COMMERCE_RENTAL_MAX)
    per = float(RE_SELF_EMP_COMMERCE_THROUGHPUT_PER_RENTAL)
    specs = globals().get("SELF_EMP_ACTIVITY_SPECS") or {}
    if isinstance(specs, dict):
        act = specs.get("자영 상업") or {}
        per = float(act.get("throughput_per_rental", per) or per)
    goods_demand = float(getattr(sector_obj, "last_goods_demand", 0.0) or 0.0)
    overflow = float(getattr(sector_obj, "last_overflow_volume", 0.0) or 0.0)
    unmet = float(getattr(sector_obj, "last_unmet_retail", 0.0) or 0.0)
    sold = float(getattr(sector_obj, "last_settled_retail_volume", 0.0) or 0.0)
    if sold <= 1e-9:
        sold = float(getattr(sector_obj, "weekly_retail_volume", 0.0) or 0.0)
    corp_cap = float(getattr(sector_obj, "last_corp_retail_cap", 0.0) or 0.0)
    if corp_cap <= 1e-9:
        corp_cap = max(0.0, float(corp_cap_nom))
    residual = max(0.0, goods_demand - corp_cap)
    # overflow는 정산 효율만큼만 임대 수요로 인정
    sellable_overflow = overflow * RETAIL_OVERFLOW_EFF_BASE
    desired_tp = max(sold * 1.08, sellable_overflow + sold * 0.2, base * per)
    desired_tp += max(0.0, residual - sold) * 0.35
    desired_tp += unmet * COMMERCE_RENTAL_GAP_COVER * 0.5
    raw_target = max(base, desired_tp / max(per, 1e-9))
    # 주당 확장 상한 — 전주 체결·목표 대비 +15%
    current = max(
        float(getattr(sector_obj, "rental_filled", 0.0) or 0.0),
        float(getattr(sector_obj, "rental_ordered", 0.0) or 0.0),
        base,
    )
    # 저가동이면 축소: 소매량이 정격의 55% 미만이면 판매량 기준으로 당김
    util = sold / max(current * per, 1e-9)
    if util < 0.55 and sold > 1e-9:
        raw_target = min(raw_target, max(base, (sold / max(per, 1e-9)) * 1.12))
    target = min(raw_target, current * 1.15)
    return clamp(target, 1.0, COMMERCE_RENTAL_MAX)


def allocate_retail_channel_qty(
    qty: float,
    corp_price: float,
    market_price: float,
    corp_capacity: float,
    market_capacity: float,
    corp_labor: float = 1.0,
    market_labor: float = 1.0,
) -> Tuple[float, float]:
    """가격·용량·노동 점수로 주문량을 두 채널에 배분. 반환: (corp_qty, market_qty).

    자영 시장 용량이 있으면 최소 RETAIL_MARKET_MIN_SHARE 비율을 보장한다.
    """
    if qty <= 1e-12:
        return 0.0, 0.0
    corp_cap = max(0.0, corp_capacity)
    mkt_cap = max(0.0, market_capacity)
    # 자영 시장 용량이 있으면 최소 보장분 확보
    mkt_floor = 0.0
    if mkt_cap > 1e-9 and corp_cap > 1e-9:
        mkt_floor = min(qty * RETAIL_MARKET_MIN_SHARE, mkt_cap)
    corp_score = 0.0
    mkt_score = 0.0
    if corp_cap > 1e-9:
        corp_score = (
            (1.0 / max(corp_price, 1e-6))
            * clamp(corp_labor, 0.05, 1.0)
            * corp_cap
        )
    if mkt_cap > 1e-9:
        mkt_score = (
            (1.0 / max(market_price, 1e-6))
            * clamp(market_labor, 0.05, 1.0)
            * mkt_cap
        )
    total = corp_score + mkt_score
    if total <= 1e-12:
        # 용량이 있으면 균등, 없으면 0
        if corp_cap > 1e-9 and mkt_cap <= 1e-9:
            return min(qty, corp_cap), 0.0
        if mkt_cap > 1e-9 and corp_cap <= 1e-9:
            return 0.0, min(qty, mkt_cap)
        if corp_cap > 1e-9 and mkt_cap > 1e-9:
            mkt_got = min(qty * RETAIL_MARKET_MIN_SHARE, mkt_cap, qty)
            corp_got = min(qty - mkt_got, corp_cap)
            return corp_got, mkt_got
        return 0.0, 0.0
    corp_want = qty * (corp_score / total)
    mkt_want = qty - corp_want
    # 최소 보장분 적용
    if mkt_want < mkt_floor:
        mkt_want = mkt_floor
        corp_want = qty - mkt_want
    corp_got = min(corp_want, corp_cap)
    mkt_got = min(mkt_want, mkt_cap)
    leftover = qty - corp_got - mkt_got
    if leftover > 1e-9:
        if corp_got < corp_cap - 1e-12:
            extra = min(leftover, corp_cap - corp_got)
            corp_got += extra
            leftover -= extra
        if leftover > 1e-9 and mkt_got < mkt_cap - 1e-12:
            extra = min(leftover, mkt_cap - mkt_got)
            mkt_got += extra
    return corp_got, mkt_got


def company_facility_names(company_type: str) -> List[str]:
    ctype = normalize_company_type(company_type)
    if company_type in SME_FACILITY_MAP and ctype not in COMPANY_FACILITY_MAP:
        return [SME_FACILITY_MAP[company_type]]
    mapped = COMPANY_FACILITY_MAP.get(ctype, [])
    if isinstance(mapped, str):
        return [mapped]
    return list(mapped)


def sme_company_id(state_id: str, sme_type: str, index: int) -> str:
    return f"sme_{state_id}_{normalize_company_type(sme_type).replace(' ', '_')}_{index}"


def company_active_facility_levels(co: "Company") -> int:
    return sum(
        int(f.active_levels()) for f in getattr(co, "facilities", [])
        if not getattr(f, "is_office", False)
    )


def company_is_small(co: "Company") -> bool:
    """소규모 기업 판정 (정책·하청 보호용). 하드 카스트가 아님."""
    if bool(getattr(co, "is_sme", False)):
        return True
    if normalize_company_type(co.type) != co.type and co.type in SME_OCCUPATION_TYPES:
        return True
    return company_active_facility_levels(co) < SMALL_COMPANY_FACILITY_LEVEL_MAX


def company_is_sme(co: "Company") -> bool:
    """하위 호환: 소규모 기업 여부. 신규 코드는 company_is_small 사용."""
    return company_is_small(co)


def company_is_coop_partner(co: Optional["Company"]) -> bool:
    """협력 중소기업(시장 미노출·가공/외주 전용) 여부."""
    return bool(co is not None and getattr(co, "is_coop_partner", False))


def company_control_share(world: "World", parent_id: str, child_id: str) -> float:
    """모회사 보유 지분율 (0~1). 자기주식·미존재는 0."""
    if not world or not parent_id or not child_id or parent_id == child_id:
        return 0.0
    parent = world.companies.get(parent_id)
    child = world.companies.get(child_id)
    if parent is None or child is None:
        return 0.0
    held = float((getattr(parent, "stock_holdings", None) or {}).get(child_id, 0.0) or 0.0)
    total = float(getattr(child, "stock_shares", COMPANY_STOCK_SHARES) or COMPANY_STOCK_SHARES)
    if total <= 1e-9 or held <= 1e-9:
        return 0.0
    return clamp(held / total, 0.0, 1.0)


def company_parent_id(world: "World", co_id: str) -> Optional[str]:
    """동일 국가·보유≥CORP_CONTROL_THRESHOLD 중 최대 지분 1곳. 동률 시 id 안정 선택."""
    if world is None or not co_id:
        return None
    idx = getattr(world, "_corp_control_index", None)
    if isinstance(idx, dict):
        parent_of = idx.get("parent_of")
        if isinstance(parent_of, dict):
            return parent_of.get(co_id)
    child = world.companies.get(co_id)
    if child is None:
        return None
    child_cid = company_home_country_id(child, world.states)
    best_id = ""
    best_share = 0.0
    thr = float(CORP_CONTROL_THRESHOLD)
    for parent in world.companies.values():
        if parent.id == co_id:
            continue
        if company_home_country_id(parent, world.states) != child_cid:
            continue
        if not company_can_operate(parent):
            continue
        share = company_control_share(world, parent.id, co_id)
        if share + 1e-12 < thr:
            continue
        if share > best_share + 1e-12 or (
            abs(share - best_share) <= 1e-12 and (not best_id or parent.id < best_id)
        ):
            best_share = share
            best_id = parent.id
    return best_id or None


def company_subsidiaries(world: "World", co_id: str) -> List[str]:
    """직접 자회사 id 목록 (과반 보유, id 정렬)."""
    if world is None or co_id not in world.companies:
        return []
    idx = getattr(world, "_corp_control_index", None)
    if isinstance(idx, dict):
        parent_of = idx.get("parent_of")
        if isinstance(parent_of, dict):
            out = [cid for cid, pid in parent_of.items() if pid == co_id]
            out.sort()
            return out
    thr = float(CORP_CONTROL_THRESHOLD)
    out: List[str] = []
    for child in world.companies.values():
        if child.id == co_id:
            continue
        if company_control_share(world, co_id, child.id) + 1e-12 >= thr:
            out.append(child.id)
    out.sort()
    return out


def company_group_root(world: "World", co_id: str) -> str:
    """궁극 모회사. 순환·깊이 초과 시 현재 노드."""
    if world is None or co_id not in world.companies:
        return co_id or ""
    idx = getattr(world, "_corp_control_index", None)
    if isinstance(idx, dict):
        root_of = idx.get("root_of")
        if isinstance(root_of, dict) and co_id in root_of:
            return root_of[co_id]
    seen: Set[str] = set()
    cur = co_id
    for _ in range(int(CORP_GROUP_WALK_DEPTH)):
        if cur in seen:
            return cur
        seen.add(cur)
        parent = company_parent_id(world, cur)
        if not parent:
            return cur
        cur = parent
    return cur


def company_group_members(world: "World", root_id: str) -> List[str]:
    """같은 루트를 공유하는 멤버 id (루트 포함, 순환출자 클러스터, id 정렬)."""
    if world is None or not root_id:
        return []
    idx = getattr(world, "_corp_control_index", None)
    members: Set[str]
    if isinstance(idx, dict):
        by_root = idx.get("members_by_root")
        if isinstance(by_root, dict) and root_id in by_root:
            members = set(by_root.get(root_id) or ())
        else:
            root_of = idx.get("root_of") or {}
            members = {cid for cid, rid in root_of.items() if rid == root_id}
            if not members and root_id in world.companies:
                members = {root_id}
    else:
        members = {
            cid for cid in world.companies
            if company_group_root(world, cid) == root_id
        }
    # 실제 지분이 있는 순환출자 링크로만 잔여 노드를 동일 그룹으로 확장
    circular = getattr(world, "corp_circular_links", None) or {}
    if isinstance(circular, dict) and members:
        min_share = float(CORP_CIRCULAR_LINK_MIN)
        changed = True
        while changed:
            changed = False
            for key in list(circular.keys()):
                parsed = corp_parse_circular_link_key(key)
                if not parsed:
                    continue
                a, b = parsed
                # 목표만 있고 보유가 없으면 그룹을 확장하지 않음
                if company_control_share(world, a, b) + 1e-12 < min_share:
                    continue
                if a in members and b not in members and b in world.companies:
                    members.add(b)
                    changed = True
                elif b in members and a not in members and a in world.companies:
                    members.add(a)
                    changed = True
    return sorted(members)


def company_group_listed_count(world: "World", root_id: str) -> int:
    """그룹 루트 멤버 중 상장사 수 (협력사는 비상장이라 제외)."""
    if world is None or not root_id:
        return 0
    idx = getattr(world, "_corp_control_index", None)
    if isinstance(idx, dict):
        cached = (idx.get("listed_count_by_root") or {}).get(root_id)
        if cached is not None:
            return int(cached)
    n = 0
    for mid in company_group_members(world, root_id):
        if company_is_listed(world, mid):
            n += 1
    return n


def company_non_coop_subsidiaries(world: "World", co_id: str) -> List[str]:
    """직접 자회사 중 협력사가 아닌 id (상장·일반 계열 한도용)."""
    out: List[str] = []
    for sid in company_subsidiaries(world, co_id):
        sub = world.companies.get(sid) if world else None
        if sub is None or company_is_coop_partner(sub):
            continue
        out.append(sid)
    return out


def company_is_holding(co: Optional["Company"]) -> bool:
    """지주회사 여부."""
    if co is None:
        return False
    if bool(getattr(co, "is_holding_company", False)):
        return True
    return str(getattr(co, "type", "") or "") == CORP_HOLDING_COMPANY_TYPE


def corp_group_has_unrelated_affiliate(world: "World", root_id: str) -> bool:
    """루트와 직종이 다르고 BOM 상류도 아닌 일반 계열사가 있는지.

    같은 직종·협력사·지주·수직 상류는 비관련 다각화가 아니다.
    """
    if world is None or not root_id:
        return False
    root = world.companies.get(root_id)
    if root is None:
        return False
    for mid in company_group_members(world, root_id):
        if mid == root_id:
            continue
        m = world.companies.get(mid)
        if m is None or company_is_coop_partner(m) or company_is_holding(m):
            continue
        parent_id = company_parent_id(world, mid)
        parent = world.companies.get(parent_id) if parent_id else root
        if parent is None:
            parent = root
        rt = normalize_company_type(getattr(root, "type", "") or "")
        mt = normalize_company_type(getattr(m, "type", "") or "")
        if rt and mt and rt == mt:
            continue
        if parent is not None:
            pt = normalize_company_type(getattr(parent, "type", "") or "")
            if pt and mt and pt == mt:
                continue
        if parent is not None and corp_is_vertical_upstream_target(world, parent, m):
            continue
        if corp_is_vertical_upstream_target(world, root, m):
            continue
        return True
    return False


def corp_group_is_conglomerate(world: "World", root_id: str) -> bool:
    """그룹이 복합(비관련 다각화·지주)인지.

    같은 직종 묶음·수직 상류·인수 intent·전략 태그만으로는 복합이 아니다.
    실제 이종(비관련) 계열사가 있거나 지주일 때만 True.
    """
    if world is None or not root_id:
        return False
    root = world.companies.get(root_id)
    if root is not None and company_is_holding(root):
        return True
    return corp_group_has_unrelated_affiliate(world, root_id)


def corp_group_is_vertical(world: "World", root_id: str) -> bool:
    """원재료·중간재 상류로 묶인 수직계열인지.

    같은 직종만 있는 그룹은 수직이 아니다(계열로만 표시).
    """
    if world is None or not root_id:
        return False
    if corp_group_is_conglomerate(world, root_id):
        return False
    root = world.companies.get(root_id)
    if root is None:
        return False
    for mid in company_group_members(world, root_id):
        if mid == root_id:
            continue
        m = world.companies.get(mid)
        if m is None or company_is_holding(m) or company_is_coop_partner(m):
            continue
        parent_id = company_parent_id(world, mid)
        parent = world.companies.get(parent_id) if parent_id else root
        if parent is not None and corp_is_vertical_upstream_target(world, parent, m):
            return True
        if corp_is_vertical_upstream_target(world, root, m):
            return True
    return False


def corp_group_max_listed(world: "World", root_id: str) -> int:
    """그룹 전략별 상장사 상한."""
    if corp_group_is_conglomerate(world, root_id):
        return int(CORP_GROUP_MAX_LISTED_CONGLOMERATE)
    return int(CORP_GROUP_MAX_LISTED_VERTICAL)


def corp_adding_listed_would_exceed(
    world: "World",
    parent: "Company",
    target: "Company",
    *,
    strategy: str = "",
) -> bool:
    """target을 과반 편입하면 그룹 상장사 수가 전략별 상한을 넘는지."""
    if world is None or parent is None or target is None:
        return False
    if not company_is_listed(world, target.id):
        return False
    idx = getattr(world, "_corp_control_index", None)
    root_of = (idx.get("root_of") if isinstance(idx, dict) else None) or {}
    root_id = root_of.get(parent.id) if root_of else company_group_root(world, parent.id)
    tgt_root = root_of.get(target.id) if root_of else company_group_root(world, target.id)
    if tgt_root == root_id:
        return False
    if strategy == "conglomerate":
        cap = int(CORP_GROUP_MAX_LISTED_CONGLOMERATE)
    elif strategy == "vertical":
        cap = int(CORP_GROUP_MAX_LISTED_VERTICAL)
    else:
        # 인덱스 있을 때 무거운 conglomerate 재판정 회피
        root = world.companies.get(root_id)
        if root is not None and (
            company_is_holding(root)
            or str(getattr(root, "corp_group_strategy", "") or "") == "conglomerate"
        ):
            cap = int(CORP_GROUP_MAX_LISTED_CONGLOMERATE)
        elif isinstance(idx, dict):
            cap = int(CORP_GROUP_MAX_LISTED_VERTICAL)
        else:
            cap = corp_group_max_listed(world, root_id)
    return company_group_listed_count(world, root_id) >= cap


def corp_group_strategy_for_target(strategy: str, target: "Company") -> str:
    """협력사 편입은 계열이지만 수직계열 전략 태그를 붙이지 않는다."""
    s = str(strategy or "")
    if company_is_coop_partner(target) and s == "vertical":
        return ""
    return s


def corp_same_occupation_type(a: Optional["Company"], b: Optional["Company"]) -> bool:
    """두 기업이 같은 직종(occupation type)인지."""
    if a is None or b is None or a is b:
        return False
    at = normalize_company_type(getattr(a, "type", "") or "")
    bt = normalize_company_type(getattr(b, "type", "") or "")
    return bool(at and bt and at == bt)


def corp_conglomerate_forbids_same_occupation(
    world: "World",
    buyer: "Company",
    target: "Company",
    *,
    strategy: str = "",
) -> bool:
    """같은 직종 과반 편입을 금지한다 (수직·복합·무전략 공통).

    협력사·지주는 제외. 루트·기존 계열 멤버와 target 직종이 겹치면 True.
    strategy 인자는 호환용으로 받지만 판정에 쓰지 않는다.
    """
    del strategy  # 호환 시그니처 유지
    if world is None or buyer is None or target is None:
        return False
    if company_is_coop_partner(target) or company_is_holding(target):
        return False
    ct = normalize_company_type(getattr(target, "type", "") or "")
    if not ct:
        return False
    root_id = company_group_root(world, buyer.id)
    root = world.companies.get(root_id) if root_id else buyer
    if corp_same_occupation_type(buyer, target):
        return True
    if root is not None and root.id != buyer.id and corp_same_occupation_type(root, target):
        return True
    for mid in company_group_members(world, root_id or buyer.id):
        if mid == target.id:
            continue
        m = world.companies.get(mid)
        if m is None or company_is_coop_partner(m) or company_is_holding(m):
            continue
        if corp_same_occupation_type(m, target):
            return True
    return False


def coop_allows_subsidiary(world: "World", partner: "Company") -> bool:
    """협력사 자회사(과반) 편입: 강압(exploitative) 관계일 때만."""
    if world is None or partner is None or not company_is_coop_partner(partner):
        return False
    effects = coop_partner_relation_effects(world, partner)
    return str(effects.get("relation_type") or "standard") == "exploitative"


def corp_max_acquire_share(
    world: "World",
    buyer: "Company",
    target: "Company",
    *,
    gradual: bool = True,
    strategy: str = "",
    contest_phase: str = "",
) -> float:
    """buyer가 target에 대해 이번에 목표로 삼을 수 있는 최대 지분율.

    gradual=True(주간): 현재 지분 + CORP_ACQ_WEEKLY_STEP.
    gradual=False(시드): CORP_ACQ_TARGET_SHARE까지 허용(한도·관계 게이트는 동일).
    경쟁 중(accumulating)에는 과반 미만으로 캡.
    """
    if world is None or buyer is None or target is None:
        return 0.0
    cur = company_control_share(world, buyer.id, target.id)
    if gradual:
        step_cap = min(float(CORP_ACQ_TARGET_SHARE), cur + float(CORP_ACQ_WEEKLY_STEP))
    else:
        step_cap = float(CORP_ACQ_TARGET_SHARE)
    if contest_phase == "accumulating":
        step_cap = min(step_cap, float(CORP_MINORITY_SHARE_CAP))
    if company_is_coop_partner(target):
        if not coop_allows_subsidiary(world, target):
            return min(step_cap, float(COOP_NON_EXPLOIT_EQUITY_CAP))
        return step_cap
    if corp_conglomerate_forbids_same_occupation(
            world, buyer, target, strategy=strategy):
        return min(step_cap, float(CORP_MINORITY_SHARE_CAP))
    if company_is_listed(world, target.id):
        if corp_adding_listed_would_exceed(
                world, buyer, target, strategy=strategy):
            return min(step_cap, float(CORP_MINORITY_SHARE_CAP))
    return step_cap


def corp_circular_link_key(holder_id: str, issuer_id: str) -> str:
    return f"{holder_id}>{issuer_id}"


def corp_parse_circular_link_key(key: Any) -> Optional[Tuple[str, str]]:
    """corp_circular_links 키 → (holder_id, issuer_id)."""
    if isinstance(key, tuple) and len(key) >= 2:
        a, b = str(key[0] or ""), str(key[1] or "")
        return (a, b) if a and b and a != b else None
    parts = str(key or "").split(">")
    if len(parts) != 2:
        return None
    a, b = parts[0], parts[1]
    return (a, b) if a and b and a != b else None


def _corp_can_reach_ownership(
    adj: Dict[str, List[str]], start: str, goal: str, *, limit: int = 32,
) -> bool:
    """보유 그래프에서 start → goal 도달 가능 여부 (BFS)."""
    if not start or not goal:
        return False
    if start == goal:
        return True
    seen = {start}
    queue = [start]
    while queue:
        cur = queue.pop(0)
        for nxt in adj.get(cur) or ():
            if nxt in seen:
                continue
            if nxt == goal:
                return True
            if len(seen) >= limit:
                return False
            seen.add(nxt)
            queue.append(nxt)
    return False


def corp_ownership_cycle_edges(
    world: "World",
    member_ids: Set[str],
    *,
    min_share: float = 0.0,
) -> List[Tuple[str, str, float]]:
    """멤버 간 실제 지분으로 순환(사이클)에 올라간 엣지만 반환.

    모회사가 자회사 과반만 가진 트리형 그룹은 빈 목록.
    A↔B 또는 A→B→C→A처럼 되돌아오는 경로가 있을 때만 순환출자로 본다.
    """
    if world is None or not member_ids:
        return []
    thr = max(0.0, float(min_share or 0.0))
    edges: List[Tuple[str, str, float]] = []
    adj: Dict[str, List[str]] = defaultdict(list)
    for holder_id in member_ids:
        holder = world.companies.get(holder_id)
        if holder is None:
            continue
        holdings = getattr(holder, "stock_holdings", None) or {}
        for issuer_id, qty in holdings.items():
            if issuer_id not in member_ids or issuer_id == holder_id:
                continue
            if float(qty or 0.0) <= 1e-9:
                continue
            share = company_control_share(world, holder_id, issuer_id)
            if share + 1e-12 < thr:
                continue
            adj[holder_id].append(issuer_id)
            edges.append((holder_id, issuer_id, share))
    on_cycle: List[Tuple[str, str, float]] = []
    for holder_id, issuer_id, share in edges:
        if _corp_can_reach_ownership(adj, issuer_id, holder_id):
            on_cycle.append((holder_id, issuer_id, share))
    on_cycle.sort(key=lambda t: (t[0], t[1]))
    return on_cycle


def _corp_uf_find(uf: Dict[str, str], x: str) -> str:
    while uf[x] != x:
        uf[x] = uf[uf[x]]
        x = uf[x]
    return x


def _corp_uf_unite(uf: Dict[str, str], a: str, b: str) -> None:
    ra, rb = _corp_uf_find(uf, a), _corp_uf_find(uf, b)
    if ra == rb:
        return
    # 사전순 작은 쪽을 대표로 (안정); 최종 canonical은 별도 선정
    if ra < rb:
        uf[rb] = ra
    else:
        uf[ra] = rb


def _corp_pick_canonical_root(world: "World", members: List[str]) -> str:
    """순환·통합 그룹의 대표 루트: 지주 > 규모 > id."""
    best = ""
    best_holding = -1
    best_size = -1.0
    for mid in sorted(members):
        co = world.companies.get(mid)
        if co is None:
            continue
        holding = 1 if company_is_holding(co) else 0
        size = (
            float(getattr(co, "income", 0.0) or 0.0)
            + float(getattr(co, "cash", 0.0) or 0.0)
        )
        if (
            holding > best_holding
            or (holding == best_holding and size > best_size + 1e-9)
            or (
                holding == best_holding
                and abs(size - best_size) <= 1e-9
                and (not best or mid < best)
            )
        ):
            best = mid
            best_holding = holding
            best_size = size
    return best or (min(members) if members else "")


def corp_resolve_control_cycles(
    world: "World",
    parent_of: Dict[str, str],
    best_share: Dict[str, float],
) -> Tuple[Dict[str, str], Dict[str, str], List[Tuple[str, str, float]]]:
    """과반 지배 그래프의 순환(타타↔고드레지)을 한 그룹·순환출자로 해소.

    - 순환 없는 트리는 기존처럼 최상위 모회사가 루트.
    - 서로 과반을 보유해 루트가 둘로 갈라지면 하나로 합치고,
      대표 루트를 향한 역방향 과반은 순환출자 링크로 돌린다.
    """
    if world is None:
        return parent_of, {}, []

    uf: Dict[str, str] = {cid: cid for cid in world.companies}
    for child, parent in parent_of.items():
        if child in uf and parent in uf:
            _corp_uf_unite(uf, child, parent)

    comps: Dict[str, List[str]] = defaultdict(list)
    for cid in world.companies:
        comps[_corp_uf_find(uf, cid)].append(cid)

    circular_edges: List[Tuple[str, str, float]] = []
    canon_of: Dict[str, str] = {}

    for rep, members in comps.items():
        member_set = set(members)
        # 컴포넌트 밖에서 들어오거나 parent 없는 노드 = 트리 루트 후보
        entry_points = [
            m for m in members
            if parent_of.get(m) is None or parent_of.get(m) not in member_set
        ]
        if len(entry_points) == 1:
            canon_of[rep] = entry_points[0]
            continue
        if len(entry_points) > 1:
            # 여러 진입점(이례) — 규모로 대표 선정, 사이클 절단은 아래
            canon = _corp_pick_canonical_root(world, entry_points)
        else:
            # entry_points == 0: 순수 순환 (타타↔고드레지)
            canon = _corp_pick_canonical_root(world, members)
        canon_of[rep] = canon
        # 대표 루트의 parent를 순환출자로 절단
        holder = parent_of.get(canon)
        if holder and holder in member_set:
            share = float(best_share.get(canon, 0.0) or 0.0)
            if share <= 1e-12:
                share = company_control_share(world, holder, canon)
            circular_edges.append((holder, canon, share))
            parent_of.pop(canon, None)
        # 컴포넌트 내 잔여 2-사이클 제거
        for child, parent in list(parent_of.items()):
            if child not in member_set or parent not in member_set:
                continue
            if parent_of.get(parent) == child:
                drop = child if child != canon else parent
                if drop == canon:
                    drop = parent if parent != canon else child
                hold = parent_of.get(drop)
                if not hold:
                    continue
                share = float(best_share.get(drop, 0.0) or 0.0)
                if share <= 1e-12:
                    share = company_control_share(world, hold, drop)
                circular_edges.append((hold, drop, share))
                parent_of.pop(drop, None)

    # 절단 후 트리 걷기로 root_of 확정 (실패 시 컴포넌트 canonical)
    root_of: Dict[str, str] = {}
    for cid in world.companies:
        seen: Set[str] = set()
        cur = cid
        for _ in range(int(CORP_GROUP_WALK_DEPTH)):
            if cur in seen:
                cur = canon_of.get(_corp_uf_find(uf, cid), cur)
                break
            seen.add(cur)
            p = parent_of.get(cur)
            if not p:
                break
            cur = p
        root_of[cid] = cur

    return parent_of, root_of, circular_edges


def corp_sync_circular_links_from_edges(
    world: "World", edges: List[Tuple[str, str, float]],
) -> None:
    """감지된 순환 지배 엣지를 corp_circular_links에 반영하고 복합 전략으로 표시."""
    if world is None or not edges:
        return
    if not hasattr(world, "corp_circular_links") or world.corp_circular_links is None:
        world.corp_circular_links = {}
    links = world.corp_circular_links
    for holder_id, issuer_id, share in edges:
        if not holder_id or not issuer_id or holder_id == issuer_id:
            continue
        key = corp_circular_link_key(holder_id, issuer_id)
        # UI·유지 목표: 과반 미만으로 캡 (실제 보유 수량은 stock_holdings)
        target = min(
            max(float(share or 0.0), float(CORP_CIRCULAR_LINK_MIN)),
            float(CORP_MINORITY_SHARE_CAP),
        )
        links[key] = max(float(links.get(key, 0.0) or 0.0), target)
        for cid in (holder_id, issuer_id):
            co = world.companies.get(cid)
            if co is not None and not company_is_coop_partner(co):
                co.corp_group_strategy = "conglomerate"


def build_corp_control_index(world: "World") -> Dict[str, Any]:
    """주간 인수·그룹용 지배/후보 인덱스 — O(기업·보유) 1회 구축.

    타타↔고드레지처럼 과반이 서로 물리면 한 그룹 + 순환출자로 묶는다.
    """
    parent_of: Dict[str, str] = {}
    best_share: Dict[str, float] = {}
    thr = float(CORP_CONTROL_THRESHOLD)
    country_of: Dict[str, str] = {}
    for co in world.companies.values():
        country_of[co.id] = company_home_country_id(co, world.states) or ""
    for parent in world.companies.values():
        if not company_can_operate(parent):
            continue
        p_cid = country_of.get(parent.id, "")
        holdings = getattr(parent, "stock_holdings", None) or {}
        for child_id, qty in holdings.items():
            q = float(qty or 0.0)
            if q <= 1e-9 or child_id == parent.id:
                continue
            child = world.companies.get(child_id)
            if child is None:
                continue
            if country_of.get(child_id, "") != p_cid:
                continue
            total = float(
                getattr(child, "stock_shares", COMPANY_STOCK_SHARES) or COMPANY_STOCK_SHARES)
            if total <= 1e-9:
                continue
            share = q / total
            if share + 1e-12 < thr:
                continue
            prev = best_share.get(child_id, -1.0)
            if share > prev + 1e-12 or (
                abs(share - prev) <= 1e-12
                and (child_id not in parent_of or parent.id < parent_of[child_id])
            ):
                best_share[child_id] = share
                parent_of[child_id] = parent.id

    parent_of, root_of, circular_edges = corp_resolve_control_cycles(
        world, parent_of, best_share)
    if circular_edges:
        corp_sync_circular_links_from_edges(world, circular_edges)

    members_by_root: Dict[str, List[str]] = defaultdict(list)
    for cid, rid in root_of.items():
        members_by_root[rid].append(cid)
    for rid in members_by_root:
        members_by_root[rid].sort()
    independents_by_country: Dict[str, List[str]] = defaultdict(list)
    producers: Dict[Tuple[str, str], List[str]] = defaultdict(list)
    coop_by_host: Dict[str, List[str]] = defaultdict(list)
    for co in world.companies.values():
        if not company_can_operate(co):
            continue
        cid = country_of.get(co.id, "")
        if company_is_coop_partner(co):
            host = str(getattr(co, "host_company_id", "") or "")
            if host:
                coop_by_host[host].append(co.id)
            continue
        if isinstance(co, RetailCompany) or company_is_holding(co):
            continue
        if parent_of.get(co.id) is None and root_of.get(co.id) == co.id:
            independents_by_country[cid].append(co.id)
        for fname in company_facility_names(getattr(co, "type", "") or ""):
            out = (FACILITY_SPECS.get(fname) or {}).get("output")
            if out:
                producers[(cid, str(out))].append(co.id)
        for fac in list(getattr(co, "facilities", None) or []):
            if getattr(fac, "is_office", False):
                continue
            out = (FACILITY_SPECS.get(getattr(fac, "name", ""), {}) or {}).get("output")
            if out:
                producers[(cid, str(out))].append(co.id)
    # producers dedupe
    for key, ids in list(producers.items()):
        producers[key] = sorted(set(ids))
    for hid in coop_by_host:
        coop_by_host[hid].sort()
    for cid in independents_by_country:
        independents_by_country[cid].sort()
    listed_count_by_root: Dict[str, int] = {}
    for rid, members in members_by_root.items():
        listed_count_by_root[rid] = sum(
            1 for mid in members if company_is_listed(world, mid))
    return {
        "parent_of": parent_of,
        "root_of": root_of,
        "members_by_root": dict(members_by_root),
        "independents_by_country": dict(independents_by_country),
        "producers": dict(producers),
        "coop_by_host": dict(coop_by_host),
        "country_of": country_of,
        "listed_count_by_root": listed_count_by_root,
        "circular_edges": circular_edges,
    }


def corp_company_input_needs(co: "Company") -> Dict[str, float]:
    """기업 BOM 기반 주간 투입 수요(대략)."""
    needs: Dict[str, float] = defaultdict(float)
    if co is None:
        return {}
    for fac in list(getattr(co, "facilities", None) or []):
        fname = str(getattr(fac, "name", "") or getattr(fac, "facility_type", "") or "")
        spec = FACILITY_SPECS.get(fname) or {}
        inputs = spec.get("inputs") or {}
        if not inputs:
            continue
        levels = 0.0
        if callable(getattr(fac, "active_levels", None)):
            try:
                levels = float(fac.active_levels() or 0)
            except Exception:
                levels = 0.0
        if levels <= 1e-9:
            levels = float(getattr(fac, "level", 0) or 0)
        if levels <= 1e-9:
            levels = float(getattr(fac, "under_construction", 0) or 0)
        planned = float(getattr(fac, "planned_weekly_output", 0.0) or 0.0)
        out_qty = float(spec.get("output_qty", 1.0) or 1.0)
        scale = planned / out_qty if planned > 1e-9 and out_qty > 1e-9 else max(1.0, levels)
        for prod, qty in inputs.items():
            if prod in COOP_NON_PROCESSABLE_INPUTS:
                continue
            needs[str(prod)] += float(qty or 0.0) * scale
    if needs:
        return dict(needs)
    # 시설 없으면 유형 기본 BOM
    for fname in company_facility_names(getattr(co, "type", "") or ""):
        spec = FACILITY_SPECS.get(fname) or {}
        for prod, qty in (spec.get("inputs") or {}).items():
            if prod in COOP_NON_PROCESSABLE_INPUTS:
                continue
            needs[str(prod)] += float(qty or 0.0)
    return dict(needs)


def corp_company_output_products(co: "Company") -> Set[str]:
    """기업이 생산하는 산출물 집합 (시설·직종 BOM)."""
    outs: Set[str] = set()
    if co is None:
        return outs
    for fac in list(getattr(co, "facilities", None) or []):
        if getattr(fac, "is_office", False):
            continue
        fname = str(getattr(fac, "name", "") or "")
        out = (FACILITY_SPECS.get(fname) or {}).get("output")
        if out:
            outs.add(str(out))
    if outs:
        return outs
    for fname in company_facility_names(getattr(co, "type", "") or ""):
        out = (FACILITY_SPECS.get(fname) or {}).get("output")
        if out:
            outs.add(str(out))
    return outs


def corp_vertical_overlap_products(
    buyer: "Company", candidate: "Company",
) -> Set[str]:
    """buyer 투입재 ∩ candidate 산출물. 동일 직종이면 빈 집합."""
    if buyer is None or candidate is None or buyer.id == candidate.id:
        return set()
    bt = normalize_company_type(getattr(buyer, "type", "") or "")
    ct = normalize_company_type(getattr(candidate, "type", "") or "")
    if bt and ct and bt == ct:
        return set()
    needs = set(corp_company_input_needs(buyer).keys())
    if not needs:
        return set()
    return needs & corp_company_output_products(candidate)


def corp_is_vertical_upstream_target(
    world: "World", buyer: "Company", candidate: "Company",
) -> bool:
    """수직계열 대상: 원재료·중간재 등 buyer 투입재를 생산하는 상류 기업.

    같은 직종·동종 산업군 묶음이 아니라 BOM/하청 공급망 상류만 인정.
    """
    if world is None or buyer is None or candidate is None:
        return False
    if buyer.id == candidate.id:
        return False
    if company_is_coop_partner(candidate) or company_is_holding(candidate):
        return False
    if isinstance(candidate, RetailCompany):
        return False
    if corp_vertical_overlap_products(buyer, candidate):
        return True
    bt = normalize_company_type(getattr(buyer, "type", "") or "")
    ct = normalize_company_type(getattr(candidate, "type", "") or "")
    if not bt or not ct or bt == ct:
        return False
    for product, rule in SUBCONTRACT_RULES.items():
        parents = rule.get("parent_types") or frozenset()
        suppliers = rule.get("supplier_types") or frozenset()
        if bt in parents and ct in suppliers:
            # 하청 공급자이면서 해당 상품이 buyer 투입재이거나 공급자 산출물일 때만
            outs = corp_company_output_products(candidate)
            needs = set(corp_company_input_needs(buyer).keys())
            if product in needs or product in outs:
                return True
    return False


def corp_vertical_target_score(
    world: "World", buyer: "Company", candidate: "Company",
) -> float:
    """수직 타깃 매력: 겹치는 투입재 수요 비중 + 규모."""
    if not corp_is_vertical_upstream_target(world, buyer, candidate):
        return 0.0
    overlap = corp_vertical_overlap_products(buyer, candidate)
    needs = corp_company_input_needs(buyer)
    total = sum(needs.values()) or 1.0
    cover = sum(float(needs.get(p, 0.0) or 0.0) for p in overlap) / total
    if cover <= 1e-12:
        cover = 0.25  # 하청 규칙 링크만 있는 경우
    size = min(
        1.0,
        (float(getattr(candidate, "income", 0.0) or 0.0)
         + float(getattr(candidate, "cash", 0.0) or 0.0)) / 4000.0,
    )
    return cover * 0.7 + size * 0.3


def corp_bidder_expansion_pressure(world: "World", co: "Company") -> float:
    """증설·증산 압력 0~1+ (경량: UC·계획산출만, capacity_gap 호출 금지)."""
    if world is None or co is None:
        return 0.0
    pressure = 0.0
    planned_sum = 0.0
    for fac in list(getattr(co, "facilities", None) or []):
        uc = float(getattr(fac, "under_construction", 0) or 0)
        if uc > 0:
            pressure += min(0.5, 0.15 * uc)
        planned_sum += float(getattr(fac, "planned_weekly_output", 0.0) or 0.0)
        levels = 0.0
        if callable(getattr(fac, "active_levels", None)):
            try:
                levels = float(fac.active_levels() or 0)
            except Exception:
                levels = 0.0
        if levels <= 1e-9 and planned_sum <= 1e-9 and uc <= 0:
            continue
        # 가동 대비 계획 산출이 크면 증산 압력
        if levels > 1e-9:
            planned = float(getattr(fac, "planned_weekly_output", 0.0) or 0.0)
            if planned > levels * 1.1:
                pressure += 0.2
    if planned_sum > 50.0:
        pressure += 0.15
    return float(min(2.0, pressure))


def corp_score_vertical_motives(
    world: "World", bidder: "Company",
    index: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    """수직계열화 후보: 투입재(원재료·중간재) 생산 기업 확보.

    같은 직종 묶음이 아니라 BOM/하청 상류만.
    실제 증설·증산 압력이 있을 때만 등록해 인수 폭주를 막는다.
    투입재당 최상위 생산자 1곳만 후보로 올린다.
    """
    out: List[Dict[str, Any]] = []
    if world is None or bidder is None:
        return out
    if company_is_coop_partner(bidder) or company_is_holding(bidder):
        return out
    needs = corp_company_input_needs(bidder)
    if not needs:
        return out
    expand = corp_bidder_expansion_pressure(world, bidder)
    # 증설 압력 없으면 수직 인수 동기 없음 (투입재만으로는 매집하지 않음)
    if float(expand) + 1e-12 < float(CORP_VERTICAL_EXPAND_MIN):
        return out
    drive = float(expand)
    idx = index or getattr(world, "_corp_control_index", None) or {}
    parent_of: Dict[str, str] = idx.get("parent_of") or {}
    root_of: Dict[str, str] = idx.get("root_of") or {}
    country_id = (idx.get("country_of") or {}).get(bidder.id) or (
        company_home_country_id(bidder, world.states))
    producers = idx.get("producers") or {}
    coop_hosts = idx.get("coop_by_host") or {}
    total_need = sum(needs.values()) or 1.0
    cap = int(CORP_INTENT_CANDIDATE_CAP)
    bidder_type = normalize_company_type(getattr(bidder, "type", "") or "")
    for product, need_qty in sorted(needs.items(), key=lambda x: -x[1])[:4]:
        weight = need_qty / total_need
        base_score = clamp(
            0.45 * drive + 0.55 * weight * min(1.5, drive + 0.5), 0.0, 1.5)
        if base_score < float(CORP_ACQ_MOTIVE_SCORE_MIN):
            continue
        detail_verb = "증설로" if expand >= 0.15 else "투입재"
        # 1) 원재료·중간재 상류 — 투입재당 매력 최고 1곳만
        best_tid = ""
        best_combo = -1.0
        best_ct = ""
        for tid in producers.get((country_id, product), ()):
            if tid == bidder.id:
                continue
            if tid in parent_of:
                continue
            if root_of.get(tid, tid) != tid:
                continue
            c = world.companies.get(tid)
            if c is None or company_is_coop_partner(c) or company_is_holding(c):
                continue
            if isinstance(c, RetailCompany):
                continue
            # 산출물이 해당 투입재를 포함하는 상류만 (하청 규칙만으로 오매칭 방지)
            if product not in corp_company_output_products(c):
                continue
            if not corp_is_vertical_upstream_target(world, bidder, c):
                continue
            ct = normalize_company_type(getattr(c, "type", "") or "")
            if bidder_type and ct and bidder_type == ct:
                continue
            tscore = corp_vertical_target_score(world, bidder, c)
            combo = base_score * (0.55 + 0.45 * tscore)
            if combo > best_combo + 1e-12 or (
                abs(combo - best_combo) <= 1e-12 and (not best_tid or tid < best_tid)
            ):
                best_combo = combo
                best_tid = tid
                best_ct = ct
        if best_tid and best_combo >= float(CORP_ACQ_MOTIVE_SCORE_MIN):
            ct_label = best_ct or "상류"
            out.append({
                "target_id": best_tid,
                "strategy": "vertical",
                "motive": "capacity_input_secure",
                "motive_detail": (
                    f"{detail_verb} {product} 수요 → {ct_label} 인수·공급 확보"
                ),
                "score": best_combo,
                "input_product": product,
            })
        if len(out) >= cap:
            break
        # 2) 협력사는 강압 관계에서만·낮은 점수로 (계열 과다 편입 방지)
        best_pid = ""
        best_p_score = -1.0
        for pid in coop_hosts.get(bidder.id, ()):
            p = world.companies.get(pid)
            if p is None:
                continue
            if str(getattr(p, "coop_specialty", "") or "") != product:
                continue
            p_parent = parent_of.get(pid)
            if p_parent is not None and p_parent != bidder.id:
                continue
            if not coop_allows_subsidiary(world, p):
                continue
            p_score = max(
                0.0,
                base_score - float(CORP_VERTICAL_COOP_SCORE_PENALTY),
            )
            if p_score > best_p_score + 1e-12 or (
                abs(p_score - best_p_score) <= 1e-12 and (not best_pid or pid < best_pid)
            ):
                best_p_score = p_score
                best_pid = pid
        if best_pid and best_p_score >= float(CORP_ACQ_MOTIVE_SCORE_MIN):
            out.append({
                "target_id": best_pid,
                "strategy": "",  # 협력 편입 — 수직계열 표시 아님
                "motive": "capacity_input_secure",
                "motive_detail": f"{detail_verb} {product} 수요 → 협력사 지분 확보",
                "score": best_p_score,
                "input_product": product,
            })
        if len(out) >= cap:
            break
    out.sort(key=lambda d: (-float(d.get("score", 0.0)), str(d.get("target_id", ""))))
    # bidder당 최종 수직 후보 1건만 (과다 매집 방지)
    return out[:1]


def corp_score_conglomerate_motives(
    world: "World", bidder: "Company",
    index: Optional[Dict[str, Any]] = None,
) -> List[Dict[str, Any]]:
    """복합기업형 후보: 다각화·여유현금·포트폴리오 균형."""
    out: List[Dict[str, Any]] = []
    if world is None or bidder is None:
        return out
    if company_is_coop_partner(bidder) or isinstance(bidder, RetailCompany):
        return out
    idx = index or getattr(world, "_corp_control_index", None) or {}
    country_id = (idx.get("country_of") or {}).get(bidder.id) or (
        company_home_country_id(bidder, world.states))
    cash = max(0.0, float(getattr(bidder, "cash", 0.0) or 0.0))
    ni = float(getattr(bidder, "net_income", 0.0) or 0.0)
    income = max(1.0, float(getattr(bidder, "income", 0.0) or 0.0))
    margin = ni / income
    expand = corp_bidder_expansion_pressure(world, bidder)
    bidder_type = normalize_company_type(getattr(bidder, "type", "") or "")
    root_id = (idx.get("root_of") or {}).get(bidder.id) or company_group_root(world, bidder.id)
    # 복합은 여유현금·수익성 악화가 뚜렷할 때만 (일상적 잔여현금으로 남발 금지)
    diversify = margin < 0.02 and expand < 0.08
    surplus = cash > 5000.0 and ni > 0 and expand < 0.12 and margin > 0.04
    if not (diversify or surplus):
        return out
    listed_count = (idx.get("listed_count_by_root") or {}).get(root_id)
    if listed_count is None:
        listed_count = company_group_listed_count(world, root_id)
    cap_listed = int(CORP_GROUP_MAX_LISTED_CONGLOMERATE)
    independents = (idx.get("independents_by_country") or {}).get(country_id) or []
    # 매력 상위만 평가
    ranked: List[Tuple[float, str]] = []
    for tid in independents:
        if tid == bidder.id:
            continue
        c = world.companies.get(tid)
        if c is None:
            continue
        t_ni = float(getattr(c, "net_income", 0.0) or 0.0)
        t_cash = float(getattr(c, "cash", 0.0) or 0.0)
        attract = clamp(
            0.4 * (1.0 if t_ni > 0 else 0.2)
            + 0.3 * min(1.0, t_cash / 2000.0)
            + 0.3 * min(1.0, max(0.0, t_ni) / 200.0),
            0.0, 1.0)
        ranked.append((attract, tid))
    ranked.sort(key=lambda x: (-x[0], x[1]))
    for attract, tid in ranked[: max(24, int(CORP_INTENT_CANDIDATE_CAP) * 2)]:
        c = world.companies.get(tid)
        if c is None:
            continue
        ct = normalize_company_type(getattr(c, "type", "") or "")
        if ct and bidder_type and ct == bidder_type:
            continue
        # 원재료·상류는 수직계열 경로로 — 복합 후보에서 제외
        if corp_is_vertical_upstream_target(world, bidder, c):
            continue
        if hasattr(world, "_corp_related_target") and world._corp_related_target(bidder, c):
            continue
        motive = "margin_diversify"
        detail = f"본업 수익성 약화 → {ct or c.name} 다각화"
        score = 0.0
        if diversify:
            score = max(score, 0.5 * (0.6 - min(0.6, margin + 0.1)) / 0.6 + 0.5 * attract)
            motive = "margin_diversify"
        if surplus:
            s2 = 0.45 * min(1.0, cash / 8000.0) + 0.55 * attract
            if s2 >= score:
                score, motive = s2, "surplus_cash_deploy"
                detail = f"여유 현금 이종 배치 → {ct or c.name}"
        if score < float(CORP_ACQ_MOTIVE_SCORE_MIN):
            continue
        if company_is_listed(world, tid) and listed_count >= cap_listed:
            continue
        out.append({
            "target_id": tid,
            "strategy": "conglomerate",
            "motive": motive,
            "motive_detail": detail,
            "score": score,
            "input_product": "",
        })
        break
    out.sort(key=lambda d: (-float(d.get("score", 0.0)), str(d.get("target_id", ""))))
    return out[:1]


def _company_group_member_payload(
    world: "World", mid: str, *, viewer_id: str = "",
) -> Dict[str, Any]:
    """계열 UI용 멤버 한 줄."""
    m = world.companies.get(mid) if world else None
    if m is None:
        return {"id": mid, "name": mid}
    pid = company_parent_id(world, mid)
    parent = world.companies.get(pid) if pid else None
    is_coop = company_is_coop_partner(m)
    role = "root"
    root_id = company_group_root(world, mid)
    if mid != root_id:
        role = "coop" if is_coop else "affiliate"
    return {
        "id": mid,
        "name": getattr(m, "name", mid),
        "type": normalize_company_type(getattr(m, "type", "") or "") or getattr(m, "type", ""),
        "is_coop_partner": is_coop,
        "is_holding": company_is_holding(m),
        "listed": company_is_listed(world, mid),
        "parent_id": pid or "",
        "parent_name": getattr(parent, "name", pid) if parent else "",
        "control_share": round(
            company_control_share(world, pid, mid) if pid else 0.0, 4),
        "root_control_share": round(
            company_control_share(world, root_id, mid) if root_id and mid != root_id else (
                1.0 if mid == root_id else 0.0), 4),
        "cash": round(float(getattr(m, "cash", 0.0) or 0.0), 1),
        "income": round(float(getattr(m, "income", 0.0) or 0.0), 1),
        "net_income": round(float(getattr(m, "net_income", 0.0) or 0.0), 1),
        "role": role,
        "is_self": bool(mid == viewer_id),
        "strategy": str(getattr(m, "corp_group_strategy", "") or ""),
        "country_id": company_home_country_id(m, world.states) or "",
    }


def company_group_report(world: "World", co_id: str) -> Dict[str, Any]:
    """get_company_report용 계열 블록."""
    co = world.companies.get(co_id) if world else None
    if co is None:
        return {}
    root_id = company_group_root(world, co_id)
    root = world.companies.get(root_id)
    parent_id = company_parent_id(world, co_id)
    parent = world.companies.get(parent_id) if parent_id else None
    brand = company_group_brand(world, root_id) if root_id else ""
    subs = []
    for sid in company_subsidiaries(world, co_id):
        row = _company_group_member_payload(world, sid, viewer_id=co_id)
        row["control_share"] = round(company_control_share(world, co_id, sid), 4)
        subs.append(row)
    members = [
        _company_group_member_payload(world, mid, viewer_id=co_id)
        for mid in company_group_members(world, root_id)
        if world.companies.get(mid) is not None
    ]
    member_ids = {m["id"] for m in members}
    n_coop = sum(1 for m in members if m.get("is_coop_partner"))
    n_listed = sum(1 for m in members if m.get("listed"))
    n_holding = sum(1 for m in members if m.get("is_holding"))
    total_income = sum(float(m.get("income", 0.0) or 0.0) for m in members)
    total_net = sum(float(m.get("net_income", 0.0) or 0.0) for m in members)
    total_cash = sum(float(m.get("cash", 0.0) or 0.0) for m in members)
    # 실제 지분으로 사이클이 성립하는 엣지만 순환출자로 표시
    # (목표만 잡힌 가짜 링크·모→자 과반 트리는 제외)
    circ = getattr(world, "corp_circular_links", None) or {}
    if not isinstance(circ, dict):
        circ = {}
    circular_links = []
    for holder_id, issuer_id, share in corp_ownership_cycle_edges(
        world, member_ids, min_share=float(CORP_CIRCULAR_LINK_MIN),
    ):
        key = corp_circular_link_key(holder_id, issuer_id)
        ha = world.companies.get(holder_id)
        hb = world.companies.get(issuer_id)
        target = float(circ.get(key, 0.0) or 0.0)
        if target <= 1e-12:
            target = min(float(share), float(CORP_MINORITY_SHARE_CAP))
            if target + 1e-12 < float(CORP_CIRCULAR_LINK_MIN):
                target = float(CORP_CIRCULAR_LINK_SHARE)
        circular_links.append({
            "holder_id": holder_id, "issuer_id": issuer_id,
            "holder_name": getattr(ha, "name", holder_id) if ha else holder_id,
            "issuer_name": getattr(hb, "name", issuer_id) if hb else issuer_id,
            "target_share": round(target, 4),
            "actual_share": round(float(share), 4),
        })
    acq_intents = []
    intents = getattr(world, "corp_acquisition_intents", None) or {}
    contests = getattr(world, "corp_acquisition_contests", None) or {}
    if isinstance(intents, dict):
        for intent in intents.values():
            if str(getattr(intent, "bidder_id", "") or "") != co_id and (
                    str(getattr(intent, "target_id", "") or "") != co_id):
                continue
            bid = str(getattr(intent, "bidder_id", "") or "")
            tid = str(getattr(intent, "target_id", "") or "")
            bco = world.companies.get(bid)
            tco = world.companies.get(tid)
            phase = str(getattr(intent, "phase", "") or "")
            wl = int(getattr(intent, "weeks_left", 0) or 0)
            cid = str(getattr(intent, "contest_id", "") or "")
            if (
                phase == "accumulating"
                and cid
                and isinstance(contests, dict)
                and cid in contests
            ):
                wl = int(getattr(contests[cid], "weeks_left", wl) or wl)
            if phase in ("won", "losing_exit", "done"):
                wl = 0
            role = "outbound" if bid == co_id else "inbound"
            acq_intents.append({
                "id": getattr(intent, "id", ""),
                "bidder_id": bid,
                "target_id": tid,
                "bidder_name": getattr(bco, "name", bid) if bco else bid,
                "target_name": getattr(tco, "name", tid) if tco else tid,
                "strategy": getattr(intent, "strategy", ""),
                "motive": getattr(intent, "motive", ""),
                "motive_detail": getattr(intent, "motive_detail", ""),
                "phase": phase,
                "role": role,
                "score": round(float(getattr(intent, "score", 0.0) or 0.0), 3),
                "input_product": str(getattr(intent, "input_product", "") or ""),
                "weeks_left": wl,
            })
        # 진행 중(매집·인수권)을 앞에, 청산은 뒤
        _phase_ord = {"accumulating": 0, "won": 1, "losing_exit": 2, "done": 3}
        acq_intents.sort(
            key=lambda r: (
                _phase_ord.get(str(r.get("phase") or ""), 9),
                -float(r.get("score") or 0.0),
                str(r.get("id") or ""),
            ))
    # 잘못된 conglomerate 태그 교정: 이종 계열 없으면 태그 제거
    if root is not None and str(getattr(root, "corp_group_strategy", "") or "") == "conglomerate":
        if not company_is_holding(root) and not corp_group_has_unrelated_affiliate(world, root_id):
            root.corp_group_strategy = (
                "vertical" if corp_group_is_vertical(world, root_id) else ""
            )
    strategy = str(getattr(root, "corp_group_strategy", "") or "") if root else ""
    is_cong = corp_group_is_conglomerate(world, root_id)
    is_vert = corp_group_is_vertical(world, root_id)
    # 협력사만 과반인 경우는 기업 그룹으로 보지 않음 (인수·계열 자회사 필요)
    affiliate_count = max(
        0, len(members) - n_coop - (1 if root_id in member_ids else 0))
    non_coop_subs = [
        s for s in subs if not s.get("is_coop_partner")
    ]
    has_real_group = bool(
        affiliate_count > 0
        or non_coop_subs
        or n_holding > 0
        or (parent_id and not company_is_coop_partner(co))
    )
    return {
        "root_id": root_id,
        "root_name": getattr(root, "name", root_id) if root else root_id,
        "brand": brand if has_real_group else "",
        "parent_id": parent_id or "",
        "parent_name": getattr(parent, "name", parent_id) if parent else "",
        "control_share": round(
            company_control_share(world, parent_id, co_id) if parent_id else 0.0, 4),
        "subsidiaries": subs,
        "members": members,
        "is_root": bool(root_id == co_id and has_real_group),
        "has_real_group": has_real_group,
        "is_conglomerate": bool(is_cong and has_real_group),
        "is_vertical": bool(is_vert and has_real_group),
        "strategy": strategy if has_real_group else "",
        "strategy_label": (
            "지주회사" if company_is_holding(co) or (
                has_real_group and company_is_holding(root))
            else (
                "복합기업" if (is_cong and has_real_group)
                else ("수직계열" if (is_vert and has_real_group) else (
                    "계열" if has_real_group else ""
                ))
            )
        ),
        "has_coop_affiliates": n_coop > 0,
        "max_listed": corp_group_max_listed(world, root_id),
        "listed_count": company_group_listed_count(world, root_id),
        "member_count": len(members),
        "coop_count": n_coop,
        "affiliate_count": affiliate_count,
        "holding_count": n_holding,
        "total_income": round(total_income, 1),
        "total_net_income": round(total_net, 1),
        "total_cash": round(total_cash, 1),
        "circular_links": circular_links,
        "acquisition_intents": acq_intents,
        "is_holding": company_is_holding(co),
    }


def coop_service_kind_for_activity(activity: str) -> str:
    rule = COOP_ACTIVITY_RULES.get(activity) or {}
    return str(rule.get("service_kind") or "processing")


def company_coop_activities(co: "Company") -> List[str]:
    """발주 기업이 협력 지원을 받을 수 있는 활동 목록.

    - 가공(processing): 시설 **투입재** (유틸·자본재 제외)
    - 외주(outsourcing): 소프트웨어·콘텐츠 등 산출 외주
    """
    if company_is_coop_partner(co):
        return []
    acts: List[str] = []
    for fname in company_facility_names(getattr(co, "type", "") or ""):
        spec = FACILITY_SPECS.get(fname, {}) or {}
        for product, qty in (spec.get("inputs") or {}).items():
            product = str(product or "").strip()
            if (
                product
                and float(qty or 0.0) > 1e-12
                and product not in COOP_NON_PROCESSABLE_INPUTS
                and product in COOP_ACTIVITY_RULES
                and coop_service_kind_for_activity(product) == "processing"
                and product not in acts
            ):
                acts.append(product)
        out = str(spec.get("output") or "").strip()
        if (
            out
            and out in COOP_OUTSOURCING_PRODUCTS
            and out in COOP_ACTIVITY_RULES
            and out not in acts
        ):
            acts.append(out)
    return acts


def company_coop_processing_input_need(co: "Company", product: str) -> float:
    """가공 계약용: 당주 계획 산출에 대응하는 투입재 필요량."""
    total = 0.0
    for fac in getattr(co, "facilities", []) or []:
        if getattr(fac, "is_office", False):
            continue
        spec = FACILITY_SPECS.get(fac.name, {}) or {}
        inputs = spec.get("inputs") or {}
        if product not in inputs:
            continue
        unit_in = float(inputs.get(product) or 0.0)
        if unit_in <= 1e-12:
            continue
        planned = float(getattr(fac, "planned_weekly_output", 0.0) or 0.0)
        out_qty = float(spec.get("output_qty") or 0.0)
        if planned > 1e-9 and out_qty > 1e-9:
            total += planned * (unit_in / out_qty)
            continue
        levels = float(fac.active_levels()) if hasattr(fac, "active_levels") else 0.0
        if levels > 1e-9:
            total += levels * unit_in
    return total


def company_coop_activity_need(co: "Company", activity: str) -> float:
    """협력 계약 규모 산정 기준 물량 (가공=투입 필요, 외주=계획 산출)."""
    if coop_service_kind_for_activity(activity) == "outsourcing":
        return company_subcontract_planned_output(co, activity)
    return company_coop_processing_input_need(co, activity)


def coop_outputs_for_processed_input(co: "Company", input_product: str) -> List[str]:
    """해당 투입재를 쓰는 시설의 산출물 목록 (가공 보너스 적용 대상)."""
    outs: List[str] = []
    fnames = [
        fac.name for fac in getattr(co, "facilities", []) or []
        if not getattr(fac, "is_office", False)
    ]
    if not fnames:
        fnames = company_facility_names(getattr(co, "type", "") or "")
    for fname in fnames:
        spec = FACILITY_SPECS.get(fname, {}) or {}
        inputs = spec.get("inputs") or {}
        if input_product not in inputs:
            continue
        out = str(spec.get("output") or "").strip()
        if out and out not in outs:
            outs.append(out)
    return outs


def company_primary_coop_activity(co: "Company") -> str:
    acts = company_coop_activities(co)
    if not acts:
        return ""
    scored = [(company_coop_activity_need(co, a), a) for a in acts]
    scored.sort(key=lambda x: -x[0])
    if scored[0][0] > 1e-9:
        return scored[0][1]
    for pref in COOP_ACTIVITY_PRIORITY:
        if pref in acts:
            return pref
    return acts[0]


def coop_target_ratio(co: "Company", activity: str) -> float:
    """협력 지원 목표 비율 (로지스틱, 평시 ~15–20%)."""
    mid = 0.5 * (COOP_RATIO_MIN + COOP_RATIO_MAX)
    tech = float(getattr(co, "tech_level", 1) or 1)
    x = (tech - 3.0) / 4.0
    return clamp(
        mid + (COOP_RATIO_MAX - mid) * (2.0 / (1.0 + math.exp(-COOP_RATIO_K * (x - COOP_RATIO_X0))) - 1.0),
        COOP_RATIO_MIN,
        COOP_RATIO_MAX,
    )


def company_coop_partner_base_capacity(partner: "Company") -> float:
    """협력사 기술 기준 최대 지원 용량 (고용 반영 전)."""
    tech = max(1.0, float(getattr(partner, "tech_level", 1) or 1))
    return COOP_PARTNER_CAPACITY_BASE * (0.75 + 0.25 * tech)


def coop_partner_labor_type(activity: str) -> str:
    """전문 활동에 대응하는 노동 자격 (산출 시설 우선)."""
    act = str(activity or "").strip()
    if not act:
        return "기본교육"
    for spec in FACILITY_SPECS.values():
        if str(spec.get("output") or "").strip() != act:
            continue
        labor = spec.get("labor")
        if labor:
            return str(labor[0])
    for spec in FACILITY_SPECS.values():
        inputs = spec.get("inputs") or {}
        if act not in inputs:
            continue
        labor = spec.get("labor")
        if labor:
            return str(labor[0])
    if act in COOP_OUTSOURCING_PRODUCTS:
        return "고등교육"
    return "기본교육"


def company_coop_partner_desired_throughput(
    partner: "Company",
    world: Optional["World"] = None,
) -> float:
    """다음 주 고용 목표 처리량 — 발주 필요·기존 계약 중 실수요, 없으면 0(해고)."""
    base = company_coop_partner_base_capacity(partner)
    if base <= 1e-9:
        return 0.0
    activity = str(getattr(partner, "coop_specialty", "") or "").strip()
    contracted = 0.0
    for sc in getattr(partner, "coop_contracts_as_partner", []) or []:
        contracted += max(
            float(getattr(sc, "fulfilled_qty", 0.0) or 0.0),
            float(getattr(sc, "weekly_qty", 0.0) or 0.0),
        )
    expected = 0.0
    host_id = str(getattr(partner, "host_company_id", "") or "")
    host = None
    if world is not None and host_id:
        host = (getattr(world, "companies", {}) or {}).get(host_id)
    if host is not None and company_can_operate(host) and activity:
        need = company_coop_activity_need(host, activity)
        if need > 1e-9:
            expected = need * coop_target_ratio(host, activity)
    target = max(contracted, expected)
    if target <= 1e-9:
        return 0.0
    return min(base, target)


def company_coop_partner_labor_need(
    partner: "Company",
    world: Optional["World"] = None,
) -> Tuple[str, float]:
    """협력사 주간 노동 수요 (자격, 인원). 수요 0이면 전원 해고."""
    activity = str(getattr(partner, "coop_specialty", "") or "").strip()
    ltype = coop_partner_labor_type(activity)
    throughput = company_coop_partner_desired_throughput(partner, world)
    if throughput <= 1e-9:
        return ltype, 0.0
    return ltype, throughput * COOP_LABOR_PER_CAPACITY


def company_coop_partner_employed(partner: "Company") -> float:
    """직전 주 노동 체결 합계 (고용 인원)."""
    filled = getattr(partner, "last_labor_filled", None) or {}
    if not filled:
        return 0.0
    return float(sum(float(v or 0.0) for v in filled.values()))


def company_coop_partner_capacity(partner: "Company") -> float:
    """협력사 주간 지원 가능 물량 (기술 용량 × 고용 충족률)."""
    base = company_coop_partner_base_capacity(partner)
    if base <= 1e-9:
        return 0.0
    # 한 번도 구인하지 않은 신생 협력사는 기본 가동(시드)으로 둔다.
    filled_map = getattr(partner, "last_labor_filled", None) or {}
    if not filled_map and float(
            getattr(partner, "last_labor_fill_ratio", 1.0) or 1.0) >= 1.0 - 1e-9:
        return base
    ratio = clamp(
        float(getattr(partner, "last_labor_fill_ratio", 0.0) or 0.0), 0.0, 1.0)
    return base * ratio


def coop_partner_seed_tech_level(host: "Company", partner: "Company") -> int:
    """협력사 시작 기술: 국가·직종 기본과 발주 기업(한 단계 아래) 중 높은 쪽."""
    base = max(1, int(getattr(partner, "tech_level", 1) or 1))
    host_tech = max(1, int(getattr(host, "tech_level", 1) or 1))
    return max(base, max(1, host_tech - 1))


def coop_yield_bonus_from_fulfillment(
    client: "Company",
    partner: "Company",
    qty: float,
    baseline: float,
) -> float:
    """협력 이행 → 발주 산출 가산율. 커버리지·효율·상대 기술로 산정."""
    if baseline <= 1e-9 or qty <= 1e-9:
        return 0.0
    coverage = float(qty) / float(baseline)
    c_tech = max(1.0, float(getattr(client, "tech_level", 1) or 1))
    p_tech = max(1.0, float(getattr(partner, "tech_level", 1) or 1))
    tech_mult = clamp(p_tech / c_tech, 0.55, 1.10)
    return min(
        COOP_YIELD_BONUS_CAP,
        coverage * COOP_YIELD_EFFICIENCY * tech_mult,
    )


def _coop_lerp(lo: float, hi: float, u: float) -> float:
    t = clamp(float(u), 0.0, 1.0)
    return float(lo) + (float(hi) - float(lo)) * t


def coop_host_equity_share(world: "World", partner: "Company") -> float:
    """발주 기업이 보유한 협력사 지분율 (0~1)."""
    if world is None or partner is None:
        return 0.0
    host_id = str(getattr(partner, "host_company_id", "") or "")
    host = world.companies.get(host_id) if host_id else None
    if host is None:
        return 0.0
    held = float((getattr(host, "stock_holdings", None) or {}).get(partner.id, 0.0) or 0.0)
    total = float(getattr(partner, "stock_shares", COMPANY_STOCK_SHARES) or COMPANY_STOCK_SHARES)
    if total <= 1e-9:
        return 0.0
    return clamp(held / total, 0.0, 1.0)


def coop_tech_gap_pressure(host_tech: float, partner_tech: float) -> float:
    """기술 격차 → 발주 우위 압력. 약 1레벨 차이는 거의 무시."""
    h_tech = max(1.0, float(host_tech or 1))
    p_tech = max(1.0, float(partner_tech or 1))
    raw_lv = h_tech - p_tech
    free = float(COOP_REL_TECH_GAP_FREE_LEVELS)
    if raw_lv >= 0:
        return max(0.0, raw_lv - free) / h_tech
    # 협력사가 더 높으면 음수(협력사 우위)
    return raw_lv / h_tech


def coop_bargaining_score(
    world: "World",
    host: "Company",
    partner: "Company",
    country: Optional["Country"],
) -> float:
    """협력 협상점수. 양수=발주 우위, 음수=협력사 우위."""
    h_tech = max(1.0, float(getattr(host, "tech_level", 1) or 1))
    p_tech = max(1.0, float(getattr(partner, "tech_level", 1) or 1))
    tech_gap = coop_tech_gap_pressure(h_tech, p_tech)
    host_power = company_raw_bargaining_power(host, as_parent=True)
    partner_power = company_raw_bargaining_power(partner, as_parent=False)
    power_diff = (host_power - partner_power) * float(COOP_REL_POWER_DIFF_WEIGHT)
    score = 0.55 * tech_gap + power_diff
    mreg = country_corp_intensity(country, "market_power_reg")
    prot_i = country_sme_intensity(country, "sme_subcontract_protection")
    fair_i = country_sme_intensity(country, "sme_fair_trade_policy")
    policy_dampen = clamp(max(mreg, prot_i, fair_i), 0.0, 1.0)
    if str(getattr(partner, "host_company_id", "") or "") == str(host.id):
        # 소속 발주 보너스 — 시장규제·보호가 셀수록 약해짐
        score += float(COOP_REL_HOST_AFFILIATION_BONUS) * (1.0 - 0.75 * policy_dampen)
    score += (
        float(COOP_REL_EQUITY_SCORE_WEIGHT)
        * coop_host_equity_share(world, partner)
        * (1.0 - 0.55 * policy_dampen)
    )
    eff_info = sme_protection_effectiveness(host, partner, country)
    eff = float(eff_info.get("effectiveness", 0.0) or 0.0)
    # 시장지배력 규제는 SME 보호와 별도로 발주 우위를 직접 깎음
    score -= float(COOP_REL_MREG_SCORE_PULL) * mreg
    if prot_i > 1e-9 or fair_i > 1e-9:
        score -= float(COOP_REL_PROTECT_SCORE_PULL) * eff
    if country_sme_policy(country, "sme_tech_transfer_support"):
        intens = country_sme_intensity(country, "sme_tech_transfer_support")
        score -= 0.08 * clamp(intens, 0.0, 1.0)
    return clamp(score, COOP_REL_SCORE_MIN, COOP_REL_SCORE_MAX)


def coop_relation_effects(
    score: float,
    *,
    protection_eff: float = 0.0,
) -> Dict[str, float]:
    """협상점수 → 연속 관계 효과. 유형 라벨은 배율을 고정하지 않음."""
    s = clamp(float(score), COOP_REL_SCORE_MIN, COOP_REL_SCORE_MAX)
    u = 1.0 / (1.0 + math.exp(COOP_REL_LOGISTIC_K * s))
    eff = clamp(float(protection_eff), 0.0, 1.0)
    if eff > 1e-9:
        u = u + (1.0 - u) * COOP_REL_POLICY_PULL * eff
    u = clamp(u, 0.0, 1.0)
    fee_mult = _coop_lerp(COOP_REL_FEE_LO, COOP_REL_FEE_HI, u)
    tech_u = max(0.0, (u - COOP_REL_TECH_TRANSFER_U0) / max(1e-9, 1.0 - COOP_REL_TECH_TRANSFER_U0))
    tech_transfer = tech_u * COOP_REL_TECH_TRANSFER_MAX
    # 라벨은 보호효과를 반영한 유효 점수로 — 수수료만 완화되고 일방형 라벨이 남는 문제 방지
    s_label = s - float(COOP_REL_LABEL_EFF_DEMOTION) * eff
    if s_label > COOP_REL_LABEL_EXPLOIT:
        rel = "exploitative"
    elif (
        s_label < COOP_REL_LABEL_COOP
        or tech_transfer + 1e-12 >= float(COOP_REL_LABEL_COOP_TECH_TRANSFER)
    ):
        rel = "cooperative"
    else:
        rel = "standard"
    host_equity_cap = _coop_lerp(COOP_REL_HOST_EQUITY_CAP_LO, COOP_REL_HOST_EQUITY_CAP_HI, u)
    # 강압(exploitative)만 과반 편입 가능 — 중립·협력형은 소수 상한
    if rel != "exploitative":
        host_equity_cap = min(host_equity_cap, float(COOP_NON_EXPLOIT_EQUITY_CAP))
    return {
        "relation_type": rel,
        "bargaining_score": s,
        "relation_u": u,
        "fee_mult": fee_mult,
        "tech_transfer_rate": tech_transfer,
        "yield_bonus_mult": _coop_lerp(COOP_REL_YIELD_LO, COOP_REL_YIELD_HI, u),
        "volume_floor_ratio": _coop_lerp(COOP_REL_VOLUME_FLOOR_LO, COOP_REL_VOLUME_FLOOR_HI, u),
        "equity_discount_extra": _coop_lerp(COOP_REL_EQUITY_DISC_LO, COOP_REL_EQUITY_DISC_HI, u),
        "host_equity_cap": host_equity_cap,
        "stickiness": _coop_lerp(COOP_REL_STICKINESS_LO, COOP_REL_STICKINESS_HI, u),
        "payment_lag_weeks": _coop_lerp(COOP_REL_PAY_LAG_LO, COOP_REL_PAY_LAG_HI, u),
        "protection_effectiveness": eff,
    }


def apply_coop_relation_to_contract(
    sc: "CoopContract",
    effects: Dict[str, Any],
    *,
    market_price: float,
) -> None:
    """연속 효과값을 계약 필드·단가에 기록."""
    sc.relation_type = str(effects.get("relation_type") or "standard")
    sc.bargaining_score = float(effects.get("bargaining_score") or 0.0)
    sc.fee_mult = float(effects.get("fee_mult") or 1.0)
    sc.tech_transfer_rate = float(effects.get("tech_transfer_rate") or 0.0)
    sc.yield_bonus_mult = float(effects.get("yield_bonus_mult") or 1.0)
    sc.volume_floor_ratio = float(effects.get("volume_floor_ratio") or 0.70)
    sc.equity_discount_extra = float(effects.get("equity_discount_extra") or 0.0)
    sc.host_equity_cap = float(effects.get("host_equity_cap") or 0.49)
    sc.stickiness = float(effects.get("stickiness") or 0.50)
    sc.payment_lag_weeks = float(effects.get("payment_lag_weeks") or 0.0)
    sc.protection_effectiveness = float(effects.get("protection_effectiveness") or 0.0)
    sc.unit_fee = max(0.5, float(market_price) * COOP_FEE_RATE * sc.fee_mult)


def coop_partner_relation_effects(
    world: "World", partner: "Company",
) -> Dict[str, float]:
    """협력사의 대표(최신/최대 대금) 계약 효과. 없으면 중립 표준."""
    contracts = list(getattr(partner, "coop_contracts_as_partner", []) or [])
    if contracts:
        sc = max(
            contracts,
            key=lambda c: float(getattr(c, "fulfilled_qty", 0.0) or 0.0)
            * float(getattr(c, "unit_fee", 0.0) or 0.0),
        )
        rel = str(getattr(sc, "relation_type", "standard") or "standard")
        host_cap = float(getattr(sc, "host_equity_cap", 0.49) or 0.49)
        if rel != "exploitative":
            host_cap = min(host_cap, float(COOP_NON_EXPLOIT_EQUITY_CAP))
        return {
            "relation_type": rel,
            "bargaining_score": float(getattr(sc, "bargaining_score", 0.0) or 0.0),
            "fee_mult": float(getattr(sc, "fee_mult", 1.0) or 1.0),
            "tech_transfer_rate": float(getattr(sc, "tech_transfer_rate", 0.0) or 0.0),
            "yield_bonus_mult": float(getattr(sc, "yield_bonus_mult", 1.0) or 1.0),
            "volume_floor_ratio": float(getattr(sc, "volume_floor_ratio", 0.70) or 0.70),
            "equity_discount_extra": float(getattr(sc, "equity_discount_extra", 0.0) or 0.0),
            "host_equity_cap": host_cap,
            "stickiness": float(getattr(sc, "stickiness", 0.50) or 0.50),
            "payment_lag_weeks": float(getattr(sc, "payment_lag_weeks", 0.0) or 0.0),
            "protection_effectiveness": float(
                getattr(sc, "protection_effectiveness", 0.0) or 0.0),
        }
    host_id = str(getattr(partner, "host_company_id", "") or "")
    host = world.companies.get(host_id) if host_id else None
    if host is None:
        return coop_relation_effects(0.0, protection_eff=0.0)
    st = world.states.get(host.home_state)
    country = world.countries.get(st.country_id) if st else None
    eff = float(
        sme_protection_effectiveness(host, partner, country).get("effectiveness", 0.0) or 0.0)
    score = coop_bargaining_score(world, host, partner, country)
    return coop_relation_effects(score, protection_eff=eff)


def coop_host_equity_raise_capacity(world: "World", partner: "Company") -> float:
    """발주가 지분 상한·현금 한도 안에서 추가로 넣을 수 있는 현금."""
    if world is None or not company_is_coop_partner(partner):
        return 0.0
    host_id = str(getattr(partner, "host_company_id", "") or "")
    host = world.companies.get(host_id) if host_id else None
    if host is None or not company_can_operate(host):
        return 0.0
    effects = coop_partner_relation_effects(world, partner)
    cap = clamp(float(effects.get("host_equity_cap", 0.49) or 0.49), 0.05, 0.95)
    if str(effects.get("relation_type") or "standard") != "exploitative":
        cap = min(cap, float(COOP_NON_EXPLOIT_EQUITY_CAP))
    owned = coop_host_equity_share(world, partner)
    room_frac = max(0.0, cap - owned)
    if room_frac <= 1e-9:
        return 0.0
    price = stock_personal_equity_mark_price(world, partner.id)
    extra = float(effects.get("equity_discount_extra", 0.0) or 0.0)
    price = clamp_stock_price(price * max(0.35, 1.0 - extra))
    if price <= 1e-9:
        return 0.0
    total_shares = float(
        getattr(partner, "stock_shares", COMPANY_STOCK_SHARES) or COMPANY_STOCK_SHARES)
    # 신주 발행 후 호스트 지분 ≤ cap 이 되도록 최대 신주 수
    # owned_shares / (total + new) <= cap  →  new <= (cap*total - owned_shares)/(1-cap)
    owned_shares = owned * total_shares
    max_new = (cap * total_shares - owned_shares) / max(1e-9, 1.0 - cap)
    max_new = max(0.0, max_new)
    host_cash = max(0.0, float(getattr(host, "cash", 0.0) or 0.0))
    return min(max_new * price, host_cash)


def coop_raise_equity_from_host(
    world: "World", partner: "Company", amount: float,
) -> float:
    """협력사가 발주기업에 신주를 주고 현금을 받는다. 실제 조달액 반환."""
    need = max(0.0, float(amount or 0.0))
    if need <= 1e-9 or world is None or not company_is_coop_partner(partner):
        return 0.0
    host_id = str(getattr(partner, "host_company_id", "") or "")
    host = world.companies.get(host_id) if host_id else None
    if host is None or not company_can_operate(host):
        return 0.0
    capacity = coop_host_equity_raise_capacity(world, partner)
    pay = min(need, capacity)
    if pay <= 1e-9:
        return 0.0
    effects = coop_partner_relation_effects(world, partner)
    price = stock_personal_equity_mark_price(world, partner.id)
    extra = float(effects.get("equity_discount_extra", 0.0) or 0.0)
    price = clamp_stock_price(price * max(0.35, 1.0 - extra))
    if price <= 1e-9:
        return 0.0
    shares = pay / price
    if shares <= 1e-9:
        return 0.0
    host_cash = max(0.0, float(getattr(host, "cash", 0.0) or 0.0))
    pay = min(pay, host_cash)
    shares = pay / price
    if pay <= 1e-9 or shares <= 1e-9:
        return 0.0
    if not hasattr(host, "stock_avg_cost") or host.stock_avg_cost is None:
        host.stock_avg_cost = defaultdict(float)
    host.stock_holdings[partner.id] = (
        float(host.stock_holdings.get(partner.id, 0.0) or 0.0) + shares)
    portfolio_apply_stock_buy(
        host.stock_holdings, host.stock_avg_cost, partner.id, shares, price)
    host.cash = max(0.0, host.cash - pay)
    partner.cash = float(getattr(partner, "cash", 0.0) or 0.0) + pay
    partner.stock_shares = float(
        getattr(partner, "stock_shares", COMPANY_STOCK_SHARES) or COMPANY_STOCK_SHARES
    ) + shares
    partner.last_week_coop_equity_raised = (
        float(getattr(partner, "last_week_coop_equity_raised", 0.0) or 0.0) + pay)
    host.last_week_coop_equity_invested = (
        float(getattr(host, "last_week_coop_equity_invested", 0.0) or 0.0) + pay)
    cache = getattr(world, "_fin_cache_stock_held", None)
    if cache is not None:
        cache[partner.id] = float(cache.get(partner.id, 0.0) or 0.0) + shares
    return pay


def _ensure_sme_intensity_map(country: "Country") -> Dict[str, float]:
    m = getattr(country, "sme_policy_intensity", None)
    if not isinstance(m, dict):
        m = {}
        country.sme_policy_intensity = m
    return m


def country_sme_intensity(country: Optional["Country"], key: str) -> float:
    """소규모 기업 정책 강도 0~1. bool만 켜져 있으면 1.0으로 취급."""
    if country is None or key not in SME_POLICY_KEYS:
        return 0.0
    m = getattr(country, "sme_policy_intensity", None)
    if isinstance(m, dict) and key in m:
        return clamp(float(m.get(key, 0.0) or 0.0) / 100.0, 0.0, 1.0)
    return 1.0 if bool(getattr(country, key, False)) else 0.0


def country_sme_policy(country: Optional["Country"], key: str) -> bool:
    return country_sme_intensity(country, key) > 1e-9


def country_sme_policies_dict(country: "Country") -> Dict[str, Any]:
    return {
        key: {
            "enabled": country_sme_policy(country, key),
            "intensity": round(country_sme_intensity(country, key) * 100.0, 1),
            "label": SME_POLICY_LABELS.get(key, key),
            "category": SME_POLICY_CATEGORIES.get(key, ""),
            "needs_tech_and_equality": key in (
                "sme_subcontract_protection",
                "sme_fair_trade_policy",
            ),
        }
        for key in SME_POLICY_KEYS
    }


def set_country_sme_policy(country: "Country", key: str, enabled: bool) -> bool:
    if key not in SME_POLICY_KEYS:
        raise ValueError(f"알 수 없는 소규모 기업 정책: {key}")
    intens = SME_INTENSITY_DEFAULT_ON if enabled else 0.0
    set_country_sme_policy_intensity(country, key, intens)
    return country_sme_policy(country, key)


def set_country_sme_policy_intensity(country: "Country", key: str, intensity: float) -> float:
    if key not in SME_POLICY_KEYS:
        raise ValueError(f"알 수 없는 소규모 기업 정책: {key}")
    val = clamp(float(intensity), 0.0, 100.0)
    _ensure_sme_intensity_map(country)[key] = val
    setattr(country, key, val > 0.5)
    return val


def _ensure_corp_intensity_map(country: "Country") -> Dict[str, float]:
    m = getattr(country, "corp_policy_intensity", None)
    if not isinstance(m, dict):
        m = {k: 0.0 for k in CORP_POLICY_KEYS}
        country.corp_policy_intensity = m
    for k in CORP_POLICY_KEYS:
        m.setdefault(k, 0.0)
    return m


def country_corp_intensity(country: Optional["Country"], key: str) -> float:
    """국가 기업 정책 강도 0~1."""
    if country is None or key not in CORP_POLICY_KEYS:
        return 0.0
    m = getattr(country, "corp_policy_intensity", None) or {}
    return clamp(float(m.get(key, 0.0) or 0.0) / 100.0, 0.0, 1.0)


def set_country_corp_intensity(country: "Country", key: str, intensity: float) -> float:
    if key not in CORP_POLICY_KEYS:
        raise ValueError(f"알 수 없는 기업 정책: {key}")
    val = clamp(float(intensity), 0.0, 100.0)
    _ensure_corp_intensity_map(country)[key] = val
    return val


def country_corp_policies_dict(country: "Country") -> Dict[str, Any]:
    m = _ensure_corp_intensity_map(country)
    return {
        key: {
            "intensity": round(float(m.get(key, 0.0) or 0.0), 1),
            "enabled": float(m.get(key, 0.0) or 0.0) > 0.5,
            "label": CORP_POLICY_LABELS.get(key, key),
            "category": CORP_POLICY_CATEGORIES.get(key, ""),
            "hint": CORP_POLICY_HINTS.get(key, ""),
        }
        for key in CORP_POLICY_KEYS
    }


def _ensure_strategic_industry_map(country: "Country") -> Dict[str, float]:
    m = getattr(country, "strategic_industry_intensity", None)
    if not isinstance(m, dict):
        m = {}
        country.strategic_industry_intensity = m
    return m


def country_strategic_intensity(country: Optional["Country"], company_type: str) -> float:
    if country is None:
        return 0.0
    m = getattr(country, "strategic_industry_intensity", None) or {}
    ctype = normalize_company_type(company_type)
    return clamp(float(m.get(ctype, 0.0) or 0.0) / 100.0, 0.0, 1.0)


def set_country_strategic_intensity(country: "Country", company_type: str, intensity: float) -> float:
    ctype = normalize_company_type(company_type)
    val = clamp(float(intensity), 0.0, 100.0)
    _ensure_strategic_industry_map(country)[ctype] = val
    return val


def country_strategic_industries_dict(country: "Country") -> Dict[str, Any]:
    m = _ensure_strategic_industry_map(country)
    out = {}
    for ctype in COMPANY_OCCUPATION_TYPES:
        raw = float(m.get(ctype, 0.0) or 0.0)
        if raw <= 0.5 and ctype not in m:
            continue
        out[ctype] = {
            "intensity": round(raw, 1),
            "enabled": raw > 0.5,
            "label": ctype,
        }
    # include zeros that were explicitly set
    for ctype, raw in m.items():
        if ctype not in out:
            out[ctype] = {
                "intensity": round(float(raw or 0.0), 1),
                "enabled": float(raw or 0.0) > 0.5,
                "label": ctype,
            }
    return out


def subcontract_target_ratio(
    parent: "Company",
    product: str,
    country: Optional["Country"] = None,
    market: Optional["MarketState"] = None,
) -> float:
    """하청으로 충당할 투입 필요량 비율 (로지스틱, 평시 ~30%)."""
    x = 0.0
    if market is not None:
        buy = float(getattr(market, "last_buy_volume", 0.0) or 0.0)
        sell = float(getattr(market, "last_sell_volume", 0.0) or 0.0)
        if sell > 1e-9:
            imbalance = (buy - sell) / sell
            x += clamp(imbalance, -1.5, 1.5)
        elif buy > 1e-9:
            x += 1.0
    cash = float(getattr(parent, "cash", 0.0) or 0.0)
    if cash < 2000.0:
        x += 0.4
    if country_sme_policy(country, "sme_subcontract_protection"):
        x += 0.2 * country_sme_intensity(country, "sme_subcontract_protection")
    r = SUBCONTRACT_RATIO_MIN + (SUBCONTRACT_RATIO_MAX - SUBCONTRACT_RATIO_MIN) * sme_logistic(
        x, k=SUBCONTRACT_RATIO_K, x0=SUBCONTRACT_RATIO_X0)
    return float(clamp(r, SUBCONTRACT_RATIO_MIN, SUBCONTRACT_RATIO_MAX))


def company_produces_product(co: "Company", product: str) -> bool:
    for fac in getattr(co, "facilities", []):
        if getattr(fac, "is_office", False):
            continue
        spec = FACILITY_SPECS.get(fac.name, {})
        if spec.get("output") == product:
            return True
    # 시설이 아직 없어도 직종 기본 산출로 공급자 후보 인정
    for fname in company_facility_names(co.type):
        spec = FACILITY_SPECS.get(fname, {})
        if spec.get("output") == product:
            return True
    return False


def ipo_offer_ratio(desired_raise: float, holdings: float, share_price: float) -> float:
    """목표 조달액 → 대주주 보유분 공모 비율 (포화 지수)."""
    hp = max(1e-9, holdings * max(share_price, 1e-9))
    return IPO_OFFER_RATIO_MAX * sme_saturating(desired_raise, scale=IPO_OFFER_RATIO_K * hp)


def seasoned_equity_ratio(market_score: float) -> float:
    """주식시장 호황 점수 → 건설 부족액 중 유상증자 비중."""
    return SEASONED_EQ_RATIO_MAX * sme_logistic(market_score, k=1.4, x0=0.15)


def company_subcontract_input_need(
    co: "Company", markets: Dict[str, "MarketState"], product: str,
) -> float:
    """하청 대상 상품의 주간 투입 필요량 합."""
    return sum(
        company_subcontract_input_need_by_state(co, markets, product).values())


def company_subcontract_input_need_by_state(
    co: "Company", markets: Dict[str, "MarketState"], product: str,
) -> Dict[str, float]:
    """하청 대상 상품의 주·시설별 주간 투입 필요량."""
    by_state: Dict[str, float] = defaultdict(float)
    efficiency = co.production_efficiency_factor()
    for fac in co.facilities:
        if fac.is_office or fac.active_levels() <= 0:
            continue
        spec = FACILITY_SPECS.get(fac.name, {})
        site_eff = facility_site_resource_efficiency(
            fac.name, fac.state_id, spec=spec, company=co)
        need = co._input_requirements_with_substitution(
            fac, spec, markets, site_eff=site_eff).get(product, 0.0)
        if need > 1e-9:
            by_state[fac.state_id] += need * efficiency
    return dict(by_state)


def company_subcontract_planned_output(co: "Company", product: str) -> float:
    total = 0.0
    for fac in co.facilities:
        if fac.is_office:
            continue
        spec = FACILITY_SPECS.get(fac.name, {})
        if spec.get("output") != product:
            continue
        total += max(0.0, float(getattr(fac, "planned_weekly_output", 0.0) or 0.0))
    return total


def company_parts_input_need(co: "Company", markets: Dict[str, "MarketState"]) -> float:
    return company_subcontract_input_need(co, markets, SME_SUBCONTRACT_PRODUCT)


def company_parts_planned_output(co: "Company") -> float:
    return company_subcontract_planned_output(co, SME_SUBCONTRACT_PRODUCT)


# 보호 정책 ON만으로 보장되는 최소 효과 (나머지는 기술×평등으로 해금)
SME_PROTECTION_BASE_EFFECT = 0.25


def sme_turn_jitter(spread: float = 0.06, center: float = 1.0) -> float:
    """턴마다 실질 효과가 약간씩 달라지도록 하는 ±spread 균등 노이즈 계수."""
    return center + random.uniform(-spread, spread)


def sme_logistic(x: float, k: float = 1.0, x0: float = 0.0) -> float:
    """로지스틱(시그모이드) 곡선. 0~1로 부드럽게 포화."""
    try:
        return 1.0 / (1.0 + math.exp(-k * (x - x0)))
    except OverflowError:
        return 0.0 if x < x0 else 1.0


def sme_saturating(x: float, scale: float = 1.0) -> float:
    """포화 지수 곡선 1 - e^(-x/scale) (지수감쇠의 적분형). x>=0에서 0→1로 체감."""
    if scale <= 1e-9:
        return 0.0
    return 1.0 - math.exp(-max(0.0, x) / scale)


def sme_rnd_tech_multiplier(co: "Company", country: Optional["Country"]) -> float:
    """중소기업 R&D 지원의 실질 기술점수 배율.

    저기술일수록 한계 추격 효과가 큼(지수감쇠 = 성장률의 미분),
    사회기술 인프라로 포화 가산, 턴마다 랜덤으로 미세 변동.
    """
    if not (company_is_sme(co) and country_sme_policy(country, "sme_rnd_support")):
        return 1.0
    intens = country_sme_intensity(country, "sme_rnd_support")
    tech = max(1.0, float(getattr(co, "tech_level", 1) or 1))
    catchup = 0.12 + 0.34 * math.exp(-(tech - 1.0) / 6.0)
    social = float(country_social_tech_level(country)) if country else 0.0
    infra = 0.14 * sme_saturating(social, scale=5.0)
    boost = (catchup + infra) * sme_turn_jitter(spread=0.08) * intens
    return 1.0 + max(0.0, boost)


def sme_tech_transfer_factor(
    parent: "Company",
    supplier: "Company",
    country: Optional["Country"],
) -> float:
    """기술이전·협력 촉진의 실질 배율 (기존 tech_transfer_rate에 곱).

    원청-하청 기술 격차가 클수록 이전 여지가 크고 로지스틱으로 포화,
    사회기술 인프라로 가산, 턴마다 랜덤 변동.
    """
    if not country_sme_policy(country, "sme_tech_transfer_support"):
        return 1.0
    intens = country_sme_intensity(country, "sme_tech_transfer_support")
    gap = float(getattr(parent, "tech_level", 1) or 1) - float(
        getattr(supplier, "tech_level", 1) or 1)
    logi = sme_logistic(gap, k=0.55, x0=2.0)
    social = float(country_social_tech_level(country)) if country else 0.0
    infra = sme_saturating(social, scale=6.0)
    return 1.0 + (0.35 + 0.85 * logi + 0.25 * infra) * sme_turn_jitter(spread=0.07) * intens


def company_raw_bargaining_power(co: "Company", *, as_parent: bool = False) -> float:
    """정책 보너스 제외한 실질 협상력 (기술·규모·저항)."""
    tech = float(getattr(co, "tech_level", 1) or 1)
    levels = sum(
        f.active_levels() for f in getattr(co, "facilities", [])
        if not getattr(f, "is_office", False)
    )
    scale = min(0.25, levels * 0.015)
    if as_parent:
        return 0.40 + min(0.40, tech * 0.025) + scale
    resistance = float(getattr(co, "market_power_resistance", 0.35) or 0.35)
    return resistance + min(0.45, tech * 0.028) + scale * 0.6


def sme_protection_effectiveness(
    parent: "Company",
    supplier: "Company",
    country: Optional["Country"],
) -> Dict[str, float]:
    """
    하도급·갑을 보호 정책의 실질 효과 계수 (0~1).

    정책 ON만으로는 일부(기본)만 적용되고,
    실질 기술 발전 + 원청·하청 권력 상호 평등이 갖춰져야 완전한 효과.
    """
    p_tech = max(1.0, float(getattr(parent, "tech_level", 1) or 1))
    s_tech = max(1.0, float(getattr(supplier, "tech_level", 1) or 1))
    # 상대 기술 격차 축소 + SME 절대 기술 성숙
    relative_tech = clamp(s_tech / p_tech, 0.0, 1.0)
    absolute_tech = clamp(s_tech / 10.0, 0.0, 1.0)
    social = float(country_social_tech_level(country)) if country else 0.0
    social_tech = clamp(social / 8.0, 0.0, 1.0)
    tech_factor = clamp(
        0.50 * relative_tech + 0.35 * absolute_tech + 0.15 * social_tech,
        0.0, 1.0,
    )

    parent_power = company_raw_bargaining_power(parent, as_parent=True)
    supplier_power = company_raw_bargaining_power(supplier, as_parent=False)
    # 상호 평등: 두 권력 비율이 1에 가까울수록 1
    equality = clamp(
        min(parent_power, supplier_power) / max(parent_power, supplier_power, 1e-9),
        0.0, 1.0,
    )

    # 정책 ON 시 기본 25% + 기술×평등으로 나머지 75% 해금.
    # 기술·평등이 모두 어느 정도 갖춰져야(로지스틱 게이트) 효과가 급상승하고,
    # 턴마다 소폭 랜덤 변동을 준다.
    base = SME_PROTECTION_BASE_EFFECT
    combined = tech_factor * equality
    gate = sme_logistic(combined, k=6.0, x0=0.45)
    unlocked = (1.0 - base) * gate * sme_turn_jitter(spread=0.05)
    overall = clamp(base + unlocked, 0.0, 1.0)
    # 하도급 보호·공정거래·시장지배력 규제 강도로 실질 효과 스케일
    # 시장지배력 규제만 켜져 있어도(보호 SME 없이도) 일부 효과가 나도록 함
    prot = country_sme_intensity(country, "sme_subcontract_protection")
    fair = country_sme_intensity(country, "sme_fair_trade_policy")
    mreg = country_corp_intensity(country, "market_power_reg")
    scale = clamp(
        max(prot, fair, 0.70 * mreg) * (1.0 + 0.35 * mreg),
        0.0, 1.35,
    )
    overall = clamp(overall * scale, 0.0, 1.0)
    return {
        "tech_factor": tech_factor,
        "equality_factor": equality,
        "parent_power": parent_power,
        "supplier_power": supplier_power,
        "effectiveness": overall,
    }


def subcontract_relation_type(
    parent: "Company",
    supplier: "Company",
    country: Optional["Country"],
    foreign_product_tech: float = 0.0,
    domestic_monopoly: bool = False,
) -> Tuple[str, float, float, float]:
    """관계 유형, 시장가 대비 단가 배율, tech_transfer_rate, 보호효과계수.

    foreign_product_tech: 해외(타국) 동일 상품 생산 기업의 평균 기술 수준.
    domestic_monopoly: 국내에 해당 상품 생산 기업이 사실상 하나뿐인지 여부.
    두 조건은 공급자의 실질 협상력을 높여, 중소기업 정책이 없더라도
    기술 경쟁력·독점 지위를 갖춘 공급자가 폭리형으로 분류되지 않게 한다.
    """
    prot_i = country_sme_intensity(country, "sme_subcontract_protection")
    fair_i = country_sme_intensity(country, "sme_fair_trade_policy")
    tech_i = country_sme_intensity(country, "sme_tech_transfer_support")
    mreg = country_corp_intensity(country, "market_power_reg")
    protect_on = prot_i > 1e-9
    fair_on = fair_i > 1e-9
    tech_coop = tech_i > 1e-9
    mreg_on = mreg > 1e-9
    eff_info = sme_protection_effectiveness(parent, supplier, country)
    # 보호·공정·시장규제 중 하나라도 있으면 효과 계수 사용
    eff = (
        float(eff_info["effectiveness"])
        if (protect_on or fair_on or mreg_on) else 0.0
    )

    parent_power = (
        float(eff_info["parent_power"])
        + 0.15 * (1.0 - prot_i)
        + 0.10 * (1.0 - fair_i)
        - 0.22 * mreg
    )
    supplier_power = (
        float(eff_info["supplier_power"])
        + (0.12 * eff if protect_on else 0.0)
        + (0.15 * eff if fair_on else 0.0)
        + 0.10 * eff * mreg
    )
    # 공급자 실질 협상력 보정: 해외 시장 기술 대비 우위 + 국내 독점 지위.
    # 정책이 없어도 경쟁력·독점을 갖춘 공급자는 착취 대상이 되지 않는다.
    p_tech = float(getattr(parent, "tech_level", 1) or 1)
    s_tech = float(getattr(supplier, "tech_level", 1) or 1)
    # 국제 평균을 '명확히' 상회할 때만 협상 우위 인정.
    # 기술력이 국제 평균 수준에 그치면(독점 프리미엄이 없는 한) 폭리 대상이 된다.
    tech_competitive = (
        foreign_product_tech > 1e-9
        and s_tech > foreign_product_tech * SUBCONTRACT_TECH_EDGE_MARGIN)
    supplier_leverage = 0.0
    if foreign_product_tech > 1e-9:
        tech_edge = (s_tech - foreign_product_tech) / foreign_product_tech
        supplier_leverage += clamp(tech_edge, -0.25, 0.60)
    if domestic_monopoly:
        supplier_leverage += 0.30
    supplier_power += max(0.0, supplier_leverage)
    # 기술 1레벨 전후 차이는 일방형 판정에서 완화
    tech_pressure = 0.20 * coop_tech_gap_pressure(p_tech, s_tech)
    score = (parent_power - supplier_power) * float(COOP_REL_POWER_DIFF_WEIGHT) + tech_pressure
    score -= float(COOP_REL_MREG_SCORE_PULL) * mreg * 0.45
    transfer = 0.0
    if tech_coop or p_tech >= s_tech + 3:
        rel = "cooperative"
        price_mult = 1.0
        # 기술이전 촉진 슬라이더만큼 이전률; 기술격차만으로 협력형은 기본 이전
        transfer = 0.15 * (tech_i if tech_coop else 1.0)
    elif score > COOP_REL_LABEL_EXPLOIT:
        rel = "exploitative"
        # 보호 없을 때 0.70, 완전 보호 시 하한 0.80으로 점진 상승
        floor = 0.70 + 0.10 * (eff if (protect_on or mreg_on) else 0.0)
        price_mult = floor if (protect_on or mreg_on) else 0.70
    else:
        rel = "standard"
        price_mult = 1.0

    # 독점 공급자이거나 해외 시장 기술력 이상이면 폭리형에서 표준으로 승격
    if rel == "exploitative" and (domestic_monopoly or tech_competitive):
        rel = "standard"
        price_mult = 1.0

    # 갑을 공정거래·시장규제: 효과 계수만큼 폭리→표준 전환
    if (fair_on or mreg_on) and rel == "exploitative":
        demote_bar = 0.85 - 0.25 * mreg
        if eff >= demote_bar or (mreg_on and score < COOP_REL_LABEL_EXPLOIT + 0.20 * mreg):
            rel = "standard"
            price_mult = 1.0
        else:
            price_mult = max(price_mult, 0.70 + 0.25 * eff)

    if protect_on or mreg_on:
        price_mult = max(price_mult, 0.70 + 0.10 * eff)
    return rel, price_mult, transfer, eff


def company_capex_credit_multiplier(country: Optional["Country"]) -> float:
    """설비투자 세액공제 → 건설비 배율 (1 → 최대 0.70)."""
    intens = country_corp_intensity(country, "capex_credit")
    return 1.0 - 0.30 * intens


def company_work_hours_output_multiplier(country: Optional["Country"]) -> float:
    """노동시간 규제 → 가동·산출 배율 (1 → 최대 0.85)."""
    intens = country_corp_intensity(country, "work_hours_reg")
    return 1.0 - 0.15 * intens


def company_vocational_labor_bonus(country: Optional["Country"]) -> float:
    """직업훈련 → 노동 fill 가산 (0 → 최대 +0.08)."""
    return 0.08 * country_corp_intensity(country, "vocational_train")


def company_dividend_restrict_multiplier(country: Optional["Country"]) -> float:
    """배당·자사주 제한 → 환원액 배율 (1 → 최대 0.30)."""
    intens = country_corp_intensity(country, "dividend_restrict")
    return 1.0 - 0.70 * intens


def company_tech_export_restrict_factor(
    parent: "Company", supplier: "Company", country: Optional["Country"],
) -> float:
    """핵심기술 국외이전 제한 — 원청·하청 국가가 다르면 이전 배율 축소."""
    intens = country_corp_intensity(country, "tech_export_restrict")
    if intens <= 1e-9:
        return 1.0
    p_cid = getattr(parent, "country_id", None)
    s_cid = getattr(supplier, "country_id", None)
    if not p_cid or not s_cid or p_cid == s_cid:
        return 1.0
    return 1.0 - 0.85 * intens


def apply_monopoly_watch_penalty(co: "Company", country: "Country", world: "World") -> float:
    """국내 독점 감시: 고마진·독점 기업에 과징금."""
    intens = country_corp_intensity(country, "monopoly_watch")
    if intens <= 1e-9:
        return 0.0
    # 동직종 국내 기업 수
    peers = [
        other for other in world.companies.values()
        if getattr(other, "country_id", None) == country.id
        and normalize_company_type(getattr(other, "type", "")) == normalize_company_type(getattr(co, "type", ""))
        and not company_is_bankrupt(other)
    ]
    if len(peers) > 1:
        return 0.0
    rev = float(getattr(co, "revenue", 0.0) or 0.0)
    ni = float(getattr(co, "net_income", 0.0) or 0.0)
    if rev <= 1e-6 or ni <= 0:
        return 0.0
    margin = ni / rev
    if margin < 0.12:
        return 0.0
    fine = min(rev * 0.01 * intens * (margin / 0.20), max(0.0, country.treasury) * 0.01)
    fine = max(0.0, fine)
    if fine > 1e-6:
        co.cash -= fine
        country.treasury += fine
        gov_record_subsidy(country, f"독점 감시 과징금 · {co.name}", -fine)
    return fine


def apply_procurement_sme_support(co: "Company", country: "Country") -> float:
    """공공조달 소규모 할당 — SME에 주간 조달성 지원금."""
    intens = country_corp_intensity(country, "procurement_sme")
    if intens <= 1e-9 or not company_is_sme(co):
        return 0.0
    base = max(80.0, abs(float(getattr(co, "revenue", 0.0) or 0.0)) * 0.004)
    amt = base * intens
    amt = min(amt, max(0.0, country.treasury) * 0.0015)
    if amt > 1e-6:
        co.cash += amt
        country.treasury -= amt
        gov_record_subsidy(country, f"공공조달 소규모 할당 · {co.name}", amt)
    return amt


def apply_bond_buy_support(world: "World", co: "Company", country: "Country") -> float:
    """회사채 매입 지원 — 유통 회사채를 시장 매수 주문으로 매입한다.

    장부 한도(corp_bond_gov_purchase_remaining)만 채우지 않는다.
    체결은 주간 채권시장 매칭·정산 경로. 반환: 접수한 액면 수량.
    """
    intens = country_corp_intensity(country, "bond_buy_support")
    if intens <= 1e-9:
        return 0.0
    outstanding = float(getattr(co, "bond_balance", 0.0) or 0.0)
    if outstanding <= 1e-6:
        # 발행 잔액 없으면 유통 매수 대상 없음 (신규 발행 인수는 underwrite=gov 경로)
        return 0.0
    bm = getattr(world, "bond_markets", None) or {}
    if co.id not in bm:
        ensure = getattr(world, "_ensure_bond_market", None)
        if callable(ensure):
            ensure(co.id)
        bm = getattr(world, "bond_markets", None) or {}
        if co.id not in bm:
            return 0.0
    # 주간 매수 액면: 강도 × 잔액 일부 (최대 잔액의 2%)
    face = 500.0 * intens * (1.0 + 0.002 * outstanding)
    face = min(face, outstanding * 0.02 * max(intens, 1e-9))
    face = max(face, 0.0)
    rate = float(getattr(bm[co.id], "current_interest_rate", 0.0) or 0.0)
    unit = float(bond_discount_price(1.0, rate))
    treasury = max(0.0, float(getattr(country, "treasury", 0.0) or 0.0))
    if unit > 1e-12 and treasury > 1e-9:
        afford = (treasury * 0.05) / unit  # 국고 5%/주 소프트 상한
        face = min(face, afford)
    if face <= 1e-6:
        return 0.0
    # 동일 종목 pending 중복 합산 방지
    pending = list(getattr(country, "pending_market_orders", None) or [])
    already = 0.0
    for o in pending:
        if (
            str(o.get("actor", "")) == "central_gov"
            and str(o.get("side", "")) == "buy"
            and str(o.get("asset", "")) == "bond"
            and str(o.get("symbol", "")) == co.id
        ):
            already += float(o.get("quantity", 0.0) or 0.0)
    face = max(0.0, face - already)
    if face <= 1e-6:
        return 0.0
    err = world.queue_policy_market_order(
        country.id, "central_gov", "buy", "bond", co.id, face)
    if err:
        return 0.0
    return float(face)


def apply_vocational_train_cost(country: "Country", company_count: int) -> float:
    """직업훈련 주간 국고 부담."""
    intens = country_corp_intensity(country, "vocational_train")
    if intens <= 1e-9 or company_count <= 0:
        return 0.0
    cost = 40.0 * intens * max(1, company_count)
    cost = min(cost, max(0.0, country.treasury) * 0.002)
    if cost > 1e-6:
        country.treasury -= cost
        gov_record_subsidy(country, "직업훈련 보조금", cost)
    return cost


def apply_gov_equity_target_step(world: "World", co: "Company", country: "Country") -> float:
    """정부 지분 목표%까지 — 시장에 주식 매수 주문을 넣어 매입한다.

    장부 텔레포트 금지. 체결은 주간 주식시장 매칭·정산 경로를 탄다.
    반환값: 이번 주 접수한 매수 주문 주식 수 (0이면 미주문).
    """
    target = clamp(float(getattr(co, "gov_equity_target_pct", 0.0) or 0.0), 0.0, 100.0) / 100.0
    if target <= 1e-9:
        return 0.0
    sm = getattr(world, "stock_markets", None) or {}
    if co.id not in sm:
        return 0.0  # 비상장·시장 없음 → 매수 불가
    cur = company_gov_ownership_share(world, co.id, country.id)
    if cur >= target - 1e-4:
        return 0.0
    issued = float(stock_issuer_issued_shares(world, co.id))
    if issued <= 1e-9:
        return 0.0
    need_share = (target - cur) * issued
    # 부족분의 일부만 매주 주문 (전량 일괄 주문 방지). 정책 주당 발행비율 상한도 적용.
    buy = need_share * 0.20
    buy = min(
        buy,
        stock_max_weekly_order_shares(
            world, co.id, issued_fraction=STOCK_POLICY_MAX_ORDER_ISSUED_FRACTION),
    )
    price = 0.0
    mk = sm.get(co.id)
    if mk is not None:
        price = float(getattr(mk, "price", 0.0) or 0.0)
    if price <= 1e-9:
        price = float(getattr(co, "share_price", 0.0) or 0.0)
    treasury = max(0.0, float(getattr(country, "treasury", 0.0) or 0.0))
    if price > 1e-9 and treasury > 1e-9:
        # 국고의 최대 5%/주 소프트 상한 (실제 지출은 체결 시 정산)
        afford = treasury * 0.05 / price
        buy = min(buy, afford)
    if buy <= 1e-6:
        return 0.0
    # 동일 종목·동일 주체 중복 pending 합산 (같은 주 재호출 대비)
    pending = list(getattr(country, "pending_market_orders", None) or [])
    already = 0.0
    for o in pending:
        if (
            str(o.get("actor", "")) == "central_gov"
            and str(o.get("side", "")) == "buy"
            and str(o.get("asset", "")) == "stock"
            and str(o.get("symbol", "")) == co.id
        ):
            already += float(o.get("quantity", 0.0) or 0.0)
    remaining_cap = max(
        0.0,
        stock_max_weekly_order_shares(
            world, co.id, issued_fraction=STOCK_POLICY_MAX_ORDER_ISSUED_FRACTION) - already,
    )
    buy = min(buy, remaining_cap)
    if buy <= 1e-6:
        return 0.0
    err = world.queue_policy_market_order(
        country.id, "central_gov", "buy", "stock", co.id, buy)
    if err:
        return 0.0
    return float(buy)


def apply_weekly_corp_company_policies(world: "World", co: "Company", country: "Country") -> None:
    """기업 단위로 돌리는 국가 기업정책 (주간)."""
    # 연속 적자 주수 추적
    ni = float(getattr(co, "net_income", 0.0) or 0.0)
    if ni < -1e-6:
        co.player_consecutive_deficit_weeks = int(getattr(co, "player_consecutive_deficit_weeks", 0) or 0) + 1
    else:
        co.player_consecutive_deficit_weeks = 0

    apply_monopoly_watch_penalty(co, country, world)
    apply_procurement_sme_support(co, country)
    apply_bond_buy_support(world, co, country)
    if float(getattr(co, "gov_equity_target_pct", 0.0) or 0.0) > 0.5:
        apply_gov_equity_target_step(world, co, country)


def company_social_tech_track_requirement(company_type: str) -> Tuple[str, int]:
    """기업 설립에 필요한 (사회기술 트랙, 레벨)."""
    ctype = normalize_company_type(company_type)
    req = COMPANY_SOCIAL_TECH_REQUIREMENTS.get(ctype)
    if req is None:
        return ("basic_mfg", 0)
    if isinstance(req, (tuple, list)) and len(req) >= 2:
        return str(req[0]), int(req[1] or 0)
    return ("basic_mfg", int(req or 0))


def company_social_tech_required(company_type: str) -> int:
    """하위 호환: 필요 레벨만 반환."""
    return company_social_tech_track_requirement(company_type)[1]


def empty_social_tech_track_state(level: int = 0) -> Dict[str, float]:
    lvl = max(0, int(level))
    return {
        "level": lvl,
        "points": 0.0,
        "points_required": social_tech_points_required_for_level(lvl),
        "last_weekly": 0.0,
    }


def ensure_country_social_tech_tracks(country: "Country") -> Dict[str, Dict[str, float]]:
    tracks = getattr(country, "social_tech_tracks", None)
    if not isinstance(tracks, dict) or not tracks:
        legacy = int(getattr(country, "social_tech_level", 0) or 0)
        tracks = {t: empty_social_tech_track_state(legacy) for t in SOCIAL_TECH_TRACKS}
        country.social_tech_tracks = tracks
    for t in SOCIAL_TECH_TRACKS:
        if t not in tracks or not isinstance(tracks[t], dict):
            tracks[t] = empty_social_tech_track_state(0)
        else:
            tracks[t].setdefault("level", 0)
            tracks[t].setdefault("points", 0.0)
            tracks[t].setdefault(
                "points_required",
                social_tech_points_required_for_level(int(tracks[t].get("level", 0) or 0)),
            )
            tracks[t].setdefault("last_weekly", 0.0)
    country.social_tech_tracks = tracks
    return tracks


def sync_country_social_tech_legacy(country: "Country") -> None:
    """max 트랙을 social_tech_level 등 레거시 필드에 반영."""
    tracks = ensure_country_social_tech_tracks(country)
    best = max(tracks.values(), key=lambda x: (int(x.get("level", 0)), float(x.get("points", 0))))
    country.social_tech_level = int(best.get("level", 0) or 0)
    country.social_tech_points = float(best.get("points", 0.0) or 0.0)
    country.social_tech_points_required = float(
        best.get("points_required", SOCIAL_TECH_TP_INITIAL_REQ) or SOCIAL_TECH_TP_INITIAL_REQ)
    country.last_weekly_social_tech_points = sum(
        float(t.get("last_weekly", 0.0) or 0.0) for t in tracks.values())


def country_social_tech_level(country: Optional["Country"]) -> int:
    if not country:
        return 0
    tracks = getattr(country, "social_tech_tracks", None)
    if isinstance(tracks, dict) and tracks:
        return max(int(t.get("level", 0) or 0) for t in tracks.values())
    return int(getattr(country, "social_tech_level", 0) or 0)


def country_social_tech_track_level(country: Optional["Country"], track: str) -> int:
    if not country:
        return 0
    tracks = ensure_country_social_tech_tracks(country)
    entry = tracks.get(track) or {}
    return int(entry.get("level", 0) or 0)


def country_meets_company_social_tech(country: Optional["Country"], company_type: str) -> bool:
    if not country:
        return False
    track, need = company_social_tech_track_requirement(company_type)
    return country_social_tech_track_level(country, track) >= need


def ensure_lab_research_allocation(country: "Country") -> Dict[str, float]:
    raw = getattr(country, "lab_research_allocation", None)
    n = max(1, len(SOCIAL_TECH_TRACKS))
    equal = 1.0 / n
    if not isinstance(raw, dict) or not raw:
        alloc = {t: equal for t in SOCIAL_TECH_TRACKS}
        country.lab_research_allocation = alloc
        return alloc
    alloc = {t: max(0.0, float(raw.get(t, 0.0) or 0.0)) for t in SOCIAL_TECH_TRACKS}
    total = sum(alloc.values())
    if total <= 1e-12:
        alloc = {t: equal for t in SOCIAL_TECH_TRACKS}
    else:
        alloc = {t: v / total for t, v in alloc.items()}
    country.lab_research_allocation = alloc
    return alloc


def set_lab_research_allocation(country: "Country", allocation: Dict[str, float]) -> Dict[str, float]:
    country.lab_research_allocation = {
        t: max(0.0, float((allocation or {}).get(t, 0.0) or 0.0)) for t in SOCIAL_TECH_TRACKS
    }
    return ensure_lab_research_allocation(country)


def set_research_coop_policy(country: "Country", policy: str) -> str:
    key = str(policy or RESEARCH_COOP_NEUTRAL).strip()
    if key not in RESEARCH_COOP_POLICIES:
        key = RESEARCH_COOP_NEUTRAL
    country.research_coop_policy = key
    return key


def research_coop_firm_tech_multiplier(country: Optional["Country"]) -> float:
    if not country:
        return 1.0
    policy = getattr(country, "research_coop_policy", RESEARCH_COOP_NEUTRAL)
    if policy == RESEARCH_COOP_CORP_HELPS:
        return RESEARCH_COOP_CORP_FIRM_MULT
    if policy == RESEARCH_COOP_SOCIAL_HELPS:
        return RESEARCH_COOP_SOCIAL_FIRM_MULT
    return 1.0


def company_social_tech_catchup_gap(
    country: Optional["Country"],
    company_type: str,
    company_tech_level: int,
) -> float:
    """해당 트랙 사회기술 − (설립 요건 + (1 − 기업 기술레벨)). 양수면 추격 효과."""
    track, need = company_social_tech_track_requirement(company_type)
    social = float(country_social_tech_track_level(country, track))
    threshold = need + (1.0 - float(company_tech_level))
    return max(0.0, social - threshold)


def company_social_tech_catchup_multiplier(
    country: Optional["Country"],
    company_type: str,
    company_tech_level: int,
) -> float:
    gap = company_social_tech_catchup_gap(country, company_type, company_tech_level)
    return 1.0 + gap * SOCIAL_TECH_CATCHUP_PER_LEVEL


def company_initial_market_cap(world: "World", co: "Company") -> float:
    """건설 서비스 가격 × (생산 시설 1개 + 사무 시설 1개 건설 비용)."""
    cs_mk = world.markets.get(market_key(co.home_state, "건설 서비스"))
    cs_price = market_goods_labor_price(cs_mk) if cs_mk else product_base_price("건설 서비스")
    prod_facilities = company_facility_names(co.type)
    prod_name = prod_facilities[0] if prod_facilities else "사무 시설"
    prod_construction = float(FACILITY_SPECS.get(prod_name, {}).get("construction", 624))
    office_construction = float(OFFICE_SPEC.get("construction", 624))
    return cs_price * (prod_construction + office_construction)

