def _build_coop_activity_rules() -> Dict[str, Dict[str, Any]]:
    """협력 규칙: 가공=시설 투입재, 외주=소프트웨어·콘텐츠 등 산출. 소매 제외."""
    rules: Dict[str, Dict[str, Any]] = {}
    for ctype, mapped in COMPANY_FACILITY_MAP.items():
        if ctype == RETAIL_COMPANY_TYPE:
            continue
        fnames = [mapped] if isinstance(mapped, str) else list(mapped or [])
        for fname in fnames:
            spec = FACILITY_SPECS.get(fname, {}) or {}
            # 가공: 투입재를 발주에 맞게 가공
            for product, qty in (spec.get("inputs") or {}).items():
                product = str(product or "").strip()
                if (
                    not product
                    or float(qty or 0.0) <= 1e-12
                    or product in COOP_NON_PROCESSABLE_INPUTS
                    or product not in PRODUCT_BASE_PRICES
                ):
                    continue
                entry = rules.setdefault(product, {
                    "client_types": set(),
                    "service_kind": "processing",
                })
                entry["client_types"].add(ctype)
                # 산출 외주와 충돌 시 outsourcing 유지
                if product in COOP_OUTSOURCING_PRODUCTS:
                    entry["service_kind"] = "outsourcing"
            # 외주: 서비스·콘텐츠 산출의 일부 외주
            out_product = str(spec.get("output") or "").strip()
            if (
                out_product
                and out_product in COOP_OUTSOURCING_PRODUCTS
                and out_product in PRODUCT_BASE_PRICES
            ):
                entry = rules.setdefault(out_product, {
                    "client_types": set(),
                    "service_kind": "outsourcing",
                })
                entry["client_types"].add(ctype)
                entry["service_kind"] = "outsourcing"
    out: Dict[str, Dict[str, Any]] = {}
    for product, entry in rules.items():
        out[product] = {
            "client_types": frozenset(entry["client_types"]),
            "service_kind": entry["service_kind"],
        }
    return out


COOP_ACTIVITY_RULES = _build_coop_activity_rules()


def facility_natural_resource_product(facility_name: str, spec: Optional[Dict] = None) -> str:
    """시설이 천연자원 산출이면 상품명, 아니면 빈 문자열."""
    use = spec if spec is not None else FACILITY_SPECS.get(facility_name, {})
    tagged = str((use or {}).get("natural_resource", "") or "")
    if tagged in NATURAL_RESOURCE_PRODUCTS:
        return tagged
    out = str((use or {}).get("output", "") or "")
    return out if out in NATURAL_RESOURCE_PRODUCTS else ""


def state_natural_resource_yield(
    product: str,
    *,
    state: Optional["State"] = None,
    state_id: str = "",
    states: Optional[Dict[str, "State"]] = None,
    company: Any = None,
) -> float:
    """주별 광물/원유 수율(채광·시추 효율). 비자원 상품은 1.0, 매장 없으면 0."""
    if product not in NATURAL_RESOURCE_PRODUCTS:
        return 1.0
    st = state
    sid = str(state_id or getattr(st, "id", "") or "")
    if st is None and states and sid:
        st = states.get(sid)
    if st is None and company is not None:
        world = getattr(company, "_world_ref", None)
        st_map = getattr(world, "states", None) if world is not None else None
        if st_map and sid:
            st = st_map.get(sid)
    if st is None:
        return 0.0
    if product == "광물":
        return max(0.0, float(getattr(st, "mineral_yield", 0.0) or 0.0))
    return max(0.0, float(getattr(st, "oil_yield", 0.0) or 0.0))


def state_allows_natural_resource_product(
    product: str,
    *,
    state: Optional["State"] = None,
    state_id: str = "",
    states: Optional[Dict[str, "State"]] = None,
    company: Any = None,
) -> bool:
    """비자원 상품은 항상 True. 광물/원유는 해당 주 수율 > 0 일 때만."""
    if product not in NATURAL_RESOURCE_PRODUCTS:
        return True
    return state_natural_resource_yield(
        product, state=state, state_id=state_id, states=states, company=company,
    ) > 1e-9


def facility_site_resource_efficiency(
    facility_name: str,
    state_id: str,
    *,
    spec: Optional[Dict] = None,
    state: Optional["State"] = None,
    states: Optional[Dict[str, "State"]] = None,
    company: Any = None,
) -> float:
    """시설 입지 천연자원 효율. 비자원 시설 1.0, 매장 없는 자원 시설 0."""
    product = facility_natural_resource_product(facility_name, spec)
    if not product:
        return 1.0
    return state_natural_resource_yield(
        product, state=state, state_id=state_id, states=states, company=company,
    )


def country_has_natural_resource_deposit(
    country_id: str,
    product: str,
    states: Dict[str, "State"],
) -> bool:
    """국가 내 어느 주든 해당 천연자원 수율 > 0 이면 True."""
    if product not in NATURAL_RESOURCE_PRODUCTS:
        return True
    cid = str(country_id or "")
    for st in states.values():
        if str(getattr(st, "country_id", "") or "") != cid:
            continue
        if state_natural_resource_yield(product, state=st) > 1e-9:
            return True
    return False


def country_allows_resource_company_type(
    country_id: str,
    ctype: str,
    states: Dict[str, "State"],
) -> bool:
    """광업/원유 기업은 국내 매장지가 있을 때만 설립·시드 허용."""
    product = COMPANY_NATURAL_RESOURCE_PRODUCT.get(normalize_company_type(ctype), "")
    if not product:
        return True
    return country_has_natural_resource_deposit(country_id, product, states)


