def remove_export_facility_specs() -> None:
    """수출 전용 시설 스펙·매핑 제거 (일반 생산 시설만 유지)."""
    to_remove = [
        fname for fname, spec in list(FACILITY_SPECS.items())
        if spec.get("export_only") or str(fname).startswith(EXPORT_FACILITY_PREFIX)
    ]
    for fname in to_remove:
        FACILITY_SPECS.pop(fname, None)

    for ctype, mapped in list(COMPANY_FACILITY_MAP.items()):
        if ctype in SERVICE_COMPANY_TYPES:
            continue
        if isinstance(mapped, str):
            names = [mapped]
        else:
            names = list(mapped)
        cleaned = [
            n for n in names
            if not str(n).startswith(EXPORT_FACILITY_PREFIX)
            and not FACILITY_SPECS.get(n, {}).get("export_only")
        ]
        if not cleaned:
            continue
        if len(cleaned) == 1:
            COMPANY_FACILITY_MAP[ctype] = cleaned[0]
        else:
            COMPANY_FACILITY_MAP[ctype] = cleaned

    PRODUCT_PRODUCTION_FACILITIES.clear()
    FACILITY_OWNER_COMPANY_TYPES.clear()
    for _fname, _spec in FACILITY_SPECS.items():
        if _spec.get("office") or not _spec.get("output"):
            continue
        PRODUCT_PRODUCTION_FACILITIES.setdefault(_spec["output"], []).append(_fname)
    for _ctype, _mapped in COMPANY_FACILITY_MAP.items():
        if _ctype == "물류 기업":
            continue
        for _fname in company_facility_names(_ctype):
            FACILITY_OWNER_COMPANY_TYPES.setdefault(_fname, []).append(_ctype)


def migrate_company_export_facilities(co: "Company") -> None:
    """레거시 수출 시설 인스턴스를 동일 이름 내수 시설로 병합."""
    merged: Dict[Tuple[str, str], "Facility"] = {}
    remaining: List["Facility"] = []
    for fac in co.facilities:
        if not str(fac.name).startswith(EXPORT_FACILITY_PREFIX):
            remaining.append(fac)
            continue
        domestic = str(fac.name)[len(EXPORT_FACILITY_PREFIX):]
        if domestic not in FACILITY_SPECS:
            continue
        key = (domestic, fac.state_id)
        if key in merged:
            merged[key].level += max(0, fac.level)
            merged[key].closed_levels += max(0, fac.closed_levels)
            merged[key].under_construction += max(0, fac.under_construction)
        else:
            nf = Facility(
                name=domestic,
                state_id=fac.state_id,
                company_id=fac.company_id,
                level=fac.level,
                closed_levels=fac.closed_levels,
                under_construction=fac.under_construction,
                construction_progress=fac.construction_progress,
                construction_target=fac.construction_target,
                idle_stage_weeks=list(fac.idle_stage_weeks),
                last_construction_fill=fac.last_construction_fill,
            )
            merged[key] = nf
    co.facilities = remaining + list(merged.values())


