POP_CONSUMPTION_COMPLEMENTS: Dict[str, Dict[str, float]] = {
    "차량": {"석유 정제품": 0.35},
    "컴퓨터": {"통신 서비스": 0.30},
    "전자 제품": {"통신 서비스": 0.22},
    "가전 제품": {"전력 서비스": 0.18},
    "소프트웨어": {"통신 서비스": 0.15},
    "영화 및 콘텐츠": {"미디어 및 방송": 0.30, "통신 서비스": 0.18},
    "외식 서비스": {"주류": 0.10},
}


def pop_complement_extra_qty(primary_orders: Dict[str, float]) -> Dict[str, float]:
    """주 상품 주문량에 따른 보조 상품 추가 필요량."""
    extra: Dict[str, float] = defaultdict(float)
    for item, qty in primary_orders.items():
        comps = POP_CONSUMPTION_COMPLEMENTS.get(item)
        if not comps or qty <= 1e-12:
            continue
        for comp, ratio in comps.items():
            if ratio > 1e-12:
                extra[comp] += float(qty) * float(ratio)
    return extra


def apply_consumption_complement_caps(filled: Dict[str, float]) -> Dict[str, float]:
    """보조재 부족 시 주 상품의 유효 소비량을 비례 제한."""
    result = {k: float(v or 0.0) for k, v in filled.items()}
    demand: Dict[str, List[Tuple[str, float]]] = defaultdict(list)
    for primary, comps in POP_CONSUMPTION_COMPLEMENTS.items():
        pqty = float(filled.get(primary, 0.0) or 0.0)
        if pqty <= 1e-12:
            continue
        for comp, ratio in comps.items():
            if ratio > 1e-12:
                demand[comp].append((primary, pqty * float(ratio)))
    cap_factor: Dict[str, float] = defaultdict(lambda: 1.0)
    for comp, reqs in demand.items():
        avail = float(filled.get(comp, 0.0) or 0.0)
        total_need = sum(n for _, n in reqs)
        if total_need <= 1e-12:
            continue
        fill_ratio = clamp(avail / total_need, 0.0, 1.0)
        for primary, _ in reqs:
            cap_factor[primary] = min(cap_factor[primary], fill_ratio)
    for primary, factor in cap_factor.items():
        if primary in result:
            result[primary] *= factor
    return result


