def pop_longevity_age(sol: float, health: float) -> float:
    """사망이 본격적으로 오르는 특성 연령. SoL·의료가 높을수록 늦어진다."""
    sol_n = clamp((float(sol) - 1.0) / 9.0, 0.0, 1.0)
    h = clamp(float(health), 0.0, 1.0)
    return (
        POP_LONGEVITY_AGE_BASE
        + sol_n * POP_LONGEVITY_SOL_SPAN
        + h * POP_LONGEVITY_HEALTH_SPAN
    )


def pop_age_weekly_death_rate(age: float, sol: float, health: float) -> float:
    """전 연령 주간 사망률. 특성연령 이전은 기저, 이후 log1p로 상승."""
    longevity = max(1.0, pop_longevity_age(sol, health))
    age_n = max(0.0, float(age))
    onset = max(18.0, longevity - POP_DEATH_LOG_ONSET_BEFORE)
    pre_term = math.log1p(age_n / max(onset, 1.0)) * POP_PRE_ONSET_LOG_SCALE
    excess = max(0.0, age_n - onset)
    age_term = math.log1p(excess / POP_DEATH_LOG_TAU)
    post = 0.0
    if age_n > longevity:
        post = math.log1p((age_n - longevity) / POP_POST_LONGEVITY_LOG_TAU)
    h = clamp(float(health), 0.0, 1.0)
    health_factor = min(2.0, 2.0 - h) if h < 1.0 else 1.0
    dr = (
        POP_BASE_WEEKLY_DEATH_RATE
        + pre_term
        + POP_AGE_DEATH_LOG_SCALE * age_term
        + POP_POST_LONGEVITY_LOG_SCALE * post
    ) * health_factor
    return clamp(dr, 0.0, POP_AGE_DEATH_WEEKLY_CAP)


