def country_import_trade_rate(country: "Country", product: str) -> float:
    """수입 순요율 — 양수=관세, 음수=보조금."""
    return float(country.import_tariffs.get(product, 0.0) or 0.0)


def country_export_trade_rate(country: "Country", product: str) -> float:
    """수출 순요율 — 양수=관세, 음수=보조금 (관세−보조금)."""
    tariff = float(country.export_tariffs.get(product, 0.0) or 0.0)
    subsidy = float(country.export_subsidy.get(product, 0.0) or 0.0)
    return tariff - subsidy


def set_country_import_trade_rate(
    country: "Country", product: str, rate: float,
) -> float:
    """수입 순요율 설정. 양수=관세, 음수=보조금."""
    rate = clamp(float(rate), -TRADE_TARIFF_CUSTOM_MAX, TRADE_TARIFF_CUSTOM_MAX)
    country.import_tariffs[product] = rate
    return rate


def set_country_export_trade_rate(
    country: "Country", product: str, rate: float,
) -> float:
    """수출 순요율 설정. 양수→관세, 음수→보조금(상호 배타)."""
    rate = clamp(float(rate), -TRADE_TARIFF_CUSTOM_MAX, TRADE_TARIFF_CUSTOM_MAX)
    if rate >= 0:
        country.export_tariffs[product] = rate
        country.export_subsidy[product] = 0.0
    else:
        country.export_tariffs[product] = 0.0
        country.export_subsidy[product] = -rate
    return rate


def enrich_goods_rows_trade_rates(
    country: Optional["Country"], rows: List[Dict[str, Any]],
) -> None:
    if not country:
        return
    for row in rows:
        product = row.get("product", "")
        if not product:
            continue
        row["import_tariff_rate"] = country_import_trade_rate(country, product)
        row["export_tariff_rate"] = country_export_trade_rate(country, product)

