def stock_buy_sell_price_ratio(buy_volume: float, sell_volume: float) -> float:
    """매수/매도 주문량 비율 — 주가 변동 배수(±30% 클램프)."""
    if sell_volume <= 1e-9:
        if buy_volume <= 1e-9:
            return 1.0
        return 1.0 + STOCK_PRICE_MAX_WOW_CHANGE
    return clamp(
        buy_volume / sell_volume,
        1.0 - STOCK_PRICE_MAX_WOW_CHANGE,
        1.0 + STOCK_PRICE_MAX_WOW_CHANGE,
    )


def stock_damped_price_ratio(raw_ratio: float) -> float:
    """매수/매도 절대 비율에 STOCK_PRICE_FLOW_SCALE만 반영한 적용 배수."""
    return 1.0 + (float(raw_ratio) - 1.0) * STOCK_PRICE_FLOW_SCALE


def bond_flow_spread_delta(raw_ratio: float) -> float:
    """매도/매수 절대 비율 → 스프레드 변동(%p). 매도>매수 → 스프레드↑."""
    return (float(raw_ratio) - 1.0) * BOND_SPREAD_FLOW_SCALE


def bond_damped_rate_ratio(raw_ratio: float) -> float:
    """레거시 호환. 신규 코드는 bond_flow_spread_delta(%p)를 쓴다."""
    return 1.0 + bond_flow_spread_delta(raw_ratio)


def financial_regime_signed_change(
    prev_chg: float,
    flow_chg: float,
    bias: float = 0.0,
    *,
    move_cap: float = STOCK_PRICE_WEEKLY_MOVE_CAP,
    gravity: float = 0.0,
) -> float:
    """주간 등락: 추세 지속 + 약한 수급은 횡보. 봉마다 부호가 뒤집히지 않게 한다.

    flow_chg는 이미 damped 된 (ratio-1). gravity는 MA/공정가 쪽으로의 약한 당김.
    """
    prev = float(prev_chg or 0.0)
    flow = float(flow_chg or 0.0)
    b = clamp(float(bias or 0.0), -INVEST_BIAS_MAX, INVEST_BIAS_MAX)
    b_abs = abs(b)
    if b * flow < 0.0:
        flow *= 1.0 - clamp(b_abs / INVEST_BIAS_MAX, 0.0, 1.0) * INVEST_BIAS_FLOW_FADE
    elif b_abs > 1e-9:
        flow *= 1.0 + clamp(b_abs / INVEST_BIAS_MAX, 0.0, 1.0) * INVEST_BIAS_FLOW_BOOST

    in_range = b_abs < INVEST_BIAS_RANGE and abs(flow) < STOCK_PRICE_RANGE_EPS
    if in_range:
        flow *= STOCK_PRICE_RANGE_SHRINK
        mixed = flow_smooth_ma(prev, flow, lam=0.22, seed_if_zero=False)
        mixed += float(gravity or 0.0) * 0.35
        return clamp(mixed, -float(move_cap), float(move_cap))

    if prev * flow < -1e-12:
        weak_flip = abs(flow) < max(STOCK_PRICE_RANGE_EPS * 1.5, 0.90 * abs(prev))
        if weak_flip:
            mixed = clamp(prev * 0.15, -STOCK_PRICE_RANGE_EPS, STOCK_PRICE_RANGE_EPS)
        else:
            mixed = 0.28 * prev + 0.72 * flow
    else:
        mixed = (
            STOCK_PRICE_TREND_PREV * prev
            + STOCK_PRICE_TREND_FLOW * flow
        )
    mixed += float(gravity or 0.0)
    return clamp(mixed, -float(move_cap), float(move_cap))


def stock_price_series(market: Optional["StockMarketState"]) -> List[float]:
    if market is None:
        return []
    hist = getattr(market, "weekly_price_history", None) or ()
    try:
        current = float(getattr(market, "current_price", 0.0) or 0.0)
    except (TypeError, ValueError):
        current = 0.0
    n = len(hist)
    try:
        last = float(hist[-1]) if n else 0.0
    except (TypeError, ValueError, IndexError):
        last = 0.0
    cached = getattr(market, "_price_series_cache", None)
    if (
        isinstance(cached, tuple)
        and len(cached) == 4
        and cached[0] == n
        and abs(float(cached[1]) - last) <= 1e-12
        and abs(float(cached[2]) - current) <= 1e-12
    ):
        return cached[3]
    prices: List[float] = []
    for p in hist:
        try:
            x = float(p)
        except (TypeError, ValueError):
            continue
        if math.isfinite(x) and x > 0:
            prices.append(x)
    if current > 0:
        if not prices:
            prices.append(current)
        elif abs(prices[-1] - current) > 1e-9:
            last = float(prices[-1])
            # 액면분할·병합 직후 미동기화 갭은 append 대신 종가 교체
            if last > 1e-12 and abs(current / last - 1.0) > float(
                STOCK_PRICE_MAX_WOW_CHANGE
            ) + 1e-9:
                prices[-1] = current
            else:
                prices.append(current)
    market._price_series_cache = (n, last, current, prices)
    return prices


def stock_moving_averages(market: Optional["StockMarketState"]) -> Dict[str, float]:
    """주간 종가 SMA. 이력이 period 미만이면 0."""
    if market is None:
        return {}
    prices = stock_price_series(market)
    n = len(prices)
    last = prices[-1] if prices else 0.0
    cached = getattr(market, "_ma_cache", None)
    if (
        isinstance(cached, tuple)
        and len(cached) == 3
        and cached[0] == n
        and abs(float(cached[1]) - last) <= 1e-12
    ):
        return cached[2]
    out: Dict[str, float] = {}
    for period in STOCK_TREND_MA_PERIODS:
        key = f"MA{int(period)}"
        p = int(period)
        if n < p or p <= 0:
            out[key] = 0.0
            continue
        out[key] = sum(prices[-p:]) / p
    market._ma_cache = (n, last, out)
    return out


def stock_trend_ma_lookback(period: int) -> int:
    p = int(period)
    if p <= 0:
        return 0
    return max(4, int(round(p * STOCK_TREND_SLOPE_LOOKBACK_FRAC)))


def stock_moving_average_slopes(
    market: Optional["StockMarketState"],
) -> Dict[str, Optional[float]]:
    """각 SMA의 lookback 기울기. 이력 부족이면 None."""
    if market is None:
        return {}
    prices = stock_price_series(market)
    n = len(prices)
    last = prices[-1] if prices else 0.0
    cached = getattr(market, "_ma_slope_cache", None)
    if (
        isinstance(cached, tuple)
        and len(cached) == 3
        and cached[0] == n
        and abs(float(cached[1]) - last) <= 1e-12
    ):
        return cached[2]
    out: Dict[str, Optional[float]] = {}
    for period in STOCK_TREND_MA_PERIODS:
        p = int(period)
        key = f"MA{p}"
        k = stock_trend_ma_lookback(p)
        if p <= 0 or k <= 0 or n < p + k:
            out[key] = None
            continue
        ma_now = sum(prices[-p:]) / p
        ma_prev = sum(prices[-p - k:-k]) / p
        if ma_now <= 0.0 or ma_prev <= 1e-12:
            out[key] = None
            continue
        out[key] = ma_now / ma_prev - 1.0
    market._ma_slope_cache = (n, last, out)
    return out


def _stock_trend_ma_weights(periods: Sequence[int]) -> List[float]:
    """이평 가중. 기간이 길수록 크고 합=1."""
    raw = [float(max(int(p), 0)) for p in periods]
    total = sum(raw)
    if total <= 1e-12:
        n = max(len(raw), 1)
        return [1.0 / n] * len(raw)
    return [w / total for w in raw]


def _stock_trend_slope_score(
    slopes: Dict[str, Optional[float]],
) -> Tuple[float, str]:
    """MA20/60/120/200 기울기 가중합. (trend_score 0~1, UP/DN/FLAT).

    장기 이평 기울기일수록 가중치가 크다. 이력 부족 이평은 제외하고 재정규화.
    """
    periods = [int(p) for p in STOCK_TREND_MA_PERIODS if int(p) > 0]
    used: List[int] = []
    zs: List[float] = []
    scale = max(float(STOCK_TREND_SLOPE_SCALE), 1e-12)
    for p in periods:
        sl = slopes.get(f"MA{p}")
        if sl is None:
            continue
        zs.append(clamp(float(sl) / scale, -1.0, 1.0))
        used.append(p)
    if not used:
        return 0.5, "FLAT"
    weights = _stock_trend_ma_weights(used)
    signed = sum(w * z for w, z in zip(weights, zs))
    if abs(signed) < STOCK_TREND_SLOPE_FLAT:
        return 0.5, "FLAT"
    if signed > 0.0:
        return 0.5 + STOCK_TREND_UP_SPAN * signed, "UP"
    return 0.5 + STOCK_TREND_DN_SPAN * signed, "DN"


def stock_chart_trend_score(
    market: Optional["StockMarketState"],
) -> Tuple[float, str]:
    """MA 기울기 가중합. 반환 (trend_score 0~1, UP/DN/FLAT)."""
    if market is None:
        return 0.5, "FLAT"
    return _stock_trend_slope_score(stock_moving_average_slopes(market))


def update_stock_trend_tracker(market: "StockMarketState") -> Tuple[str, int, float]:
    trend_score, current_dir = stock_chart_trend_score(market)
    prev_dir = str(getattr(market, "trend_dir", "FLAT") or "FLAT")
    count = int(getattr(market, "trend_count", 0) or 0)
    if current_dir == prev_dir and current_dir != "FLAT":
        count += 1
    else:
        count = 1
    market.trend_dir = current_dir
    market.trend_count = count
    return current_dir, count, trend_score


def stock_dynamic_hedge_ratio(final_score: float) -> float:
    distance = abs(float(final_score) - 0.5)
    span = STOCK_HEDGE_RATIO_MAX - STOCK_HEDGE_RATIO_MIN
    return STOCK_HEDGE_RATIO_MAX - clamp(distance / 0.5, 0.0, 1.0) * span


def stock_order_hedge_ratio(world: "World", issuer_id: str) -> float:
    score = stock_representative_score(world, issuer_id)
    return stock_dynamic_hedge_ratio(score)


def stock_valuation_unit_score(profile: Optional[Dict[str, Any]]) -> float:
    """PER/PBR → 0~1 가치점수 (stockprice.py calculate_valuation 근사)."""
    if not profile:
        return 0.5
    per = float(profile.get("per", 0.0) or 0.0)
    pbr = float(profile.get("pbr", 0.0) or 0.0)
    s_per = clamp(1.0 - ((per - 5.0) / 25.0), 0.0, 1.0) if 0.0 < per < 900.0 else 0.0
    s_pbr = clamp(1.0 - ((pbr - 0.5) / 2.5), 0.0, 1.0) if pbr > 0.0 else 0.0
    return (s_per + s_pbr) * 0.5


def stock_representative_score(world: "World", issuer_id: str) -> float:
    sm = (world.stock_markets or {}).get(str(issuer_id or ""))
    trend_score, _ = stock_chart_trend_score(sm)
    prof = stock_issuer_valuation_profile(world, issuer_id) if issuer_id else {}
    val_score = stock_valuation_unit_score(prof)
    bias = market_invest_bias(sm)
    ai = clamp(0.5 + bias / (2.0 * INVEST_BIAS_MAX), 0.0, 1.0)
    return ai * 0.4 + val_score * 0.3 + trend_score * 0.3


def _last_finite(series: Sequence[float], default: float = float("nan")) -> float:
    for v in reversed(list(series or [])):
        try:
            x = float(v)
        except (TypeError, ValueError):
            continue
        if math.isfinite(x):
            return x
    return default


def _series_ema(values: Sequence[float], period: int) -> List[float]:
    n = len(values)
    p = int(period)
    out: List[float] = [float("nan")] * n
    if p <= 0 or n < p:
        return out
    seed = sum(float(values[i]) for i in range(p)) / p
    out[p - 1] = seed
    alpha = 2.0 / (p + 1.0)
    prev = seed
    for i in range(p, n):
        prev = alpha * float(values[i]) + (1.0 - alpha) * prev
        out[i] = prev
    return out


def _series_rsi(values: Sequence[float], period: int = STOCK_RSI_PERIOD) -> List[float]:
    n = len(values)
    p = int(period)
    out: List[float] = [float("nan")] * n
    if p <= 0 or n < p + 1:
        return out
    gains: List[float] = []
    losses: List[float] = []
    for i in range(1, n):
        ch = float(values[i]) - float(values[i - 1])
        gains.append(max(ch, 0.0))
        losses.append(max(-ch, 0.0))

    def _rsi(ag: float, al: float) -> float:
        if al <= 1e-12:
            return 100.0 if ag > 1e-12 else 50.0
        return 100.0 - 100.0 / (1.0 + ag / al)

    avg_g = sum(gains[:p]) / p
    avg_l = sum(losses[:p]) / p
    out[p] = _rsi(avg_g, avg_l)
    for i in range(p, len(gains)):
        avg_g = (avg_g * (p - 1) + gains[i]) / p
        avg_l = (avg_l * (p - 1) + losses[i]) / p
        out[i + 1] = _rsi(avg_g, avg_l)
    return out


def _series_stoch_k(
    values: Sequence[float], period: int = STOCK_STOCH_K_PERIOD,
) -> List[float]:
    n = len(values)
    p = int(period)
    out: List[float] = [float("nan")] * n
    if p <= 0 or n < p:
        return out
    for i in range(p - 1, n):
        window = [float(values[j]) for j in range(i - p + 1, i + 1)]
        lo = min(window)
        hi = max(window)
        c = float(values[i])
        if hi - lo <= 1e-12:
            out[i] = 50.0
        else:
            out[i] = (c - lo) / (hi - lo) * 100.0
    return out


def _series_sma_from(series: Sequence[float], period: int) -> List[float]:
    n = len(series)
    p = int(period)
    out: List[float] = [float("nan")] * n
    if p <= 0:
        return out
    buf: List[float] = []
    acc = 0.0
    for i, raw in enumerate(series):
        try:
            x = float(raw)
        except (TypeError, ValueError):
            x = float("nan")
        if not math.isfinite(x):
            buf.clear()
            acc = 0.0
            continue
        buf.append(x)
        acc += x
        if len(buf) > p:
            acc -= buf.pop(0)
        if len(buf) == p:
            out[i] = acc / p
    return out


def stock_oscillator_pack(
    market: Optional["StockMarketState"],
) -> Dict[str, float]:
    """주간 종가 MACD(12/26/9)·RSI(14)·Stochastic(14,3). 이력 부족은 중립."""
    empty = {
        "macd": 0.0, "macd_signal": 0.0, "macd_hist": 0.0, "macd_cross": 0.0,
        "rsi": 50.0, "stoch_k": 50.0, "stoch_d": 50.0,
        "overbought": 0.0, "oversold": 0.0,
    }
    if market is None:
        return dict(empty)
    prices = stock_price_series(market)
    n = len(prices)
    last = prices[-1] if prices else 0.0
    cached = getattr(market, "_osc_pack_cache", None)
    if (
        isinstance(cached, tuple)
        and len(cached) == 3
        and cached[0] == n
        and abs(float(cached[1]) - last) <= 1e-12
    ):
        return cached[2]

    pack = dict(empty)
    if n >= 2:
        macd_line = _series_ema(prices, STOCK_MACD_FAST)
        slow = _series_ema(prices, STOCK_MACD_SLOW)
        finite_macd: List[float] = []
        for i in range(n):
            a, b = macd_line[i], slow[i]
            if math.isfinite(a) and math.isfinite(b):
                finite_macd.append(a - b)
        if len(finite_macd) >= STOCK_MACD_SIGNAL:
            sig_series = _series_ema(finite_macd, STOCK_MACD_SIGNAL)
            macd_now = finite_macd[-1]
            sig_now = _last_finite(sig_series, 0.0)
            macd_prev = finite_macd[-2] if len(finite_macd) >= 2 else macd_now
            sig_prev = (
                float(sig_series[-2])
                if len(sig_series) >= 2 and math.isfinite(sig_series[-2])
                else sig_now
            )
            hist = macd_now - sig_now
            hist_prev = macd_prev - sig_prev
            pack["macd"] = macd_now
            pack["macd_signal"] = sig_now
            pack["macd_hist"] = hist
            if hist_prev <= 0.0 and hist > 0.0:
                pack["macd_cross"] = 1.0
            elif hist_prev >= 0.0 and hist < 0.0:
                pack["macd_cross"] = -1.0
            pack["_hist_prev"] = hist_prev
        rsi_s = _series_rsi(prices, STOCK_RSI_PERIOD)
        stoch_k_s = _series_stoch_k(prices, STOCK_STOCH_K_PERIOD)
        stoch_d_s = _series_sma_from(stoch_k_s, STOCK_STOCH_D_PERIOD)
        rsi = _last_finite(rsi_s, 50.0)
        k = _last_finite(stoch_k_s, 50.0)
        d = _last_finite(stoch_d_s, k)
        if math.isfinite(rsi):
            pack["rsi"] = rsi
        if math.isfinite(k):
            pack["stoch_k"] = k
        if math.isfinite(d):
            pack["stoch_d"] = d

    rsi = float(pack["rsi"])
    k = float(pack["stoch_k"])
    d = float(pack["stoch_d"])
    hist = float(pack["macd_hist"])
    hist_prev = float(pack.get("_hist_prev", hist))
    if not math.isfinite(hist_prev):
        hist_prev = hist
    cross = float(pack["macd_cross"])
    overbought = (
        rsi > STOCK_RSI_OVERBOUGHT
        or k > STOCK_STOCH_OVERBOUGHT
        or (cross < 0.0 and rsi >= 50.0)
        or (hist > 0.0 and hist < hist_prev and rsi >= 55.0)
    )
    oversold = (
        rsi < STOCK_RSI_OVERSOLD
        or k < STOCK_STOCH_OVERSOLD
        or (cross > 0.0 and rsi <= 50.0)
        or (hist < 0.0 and hist > hist_prev and rsi <= 45.0)
    )
    pack["overbought"] = 1.0 if overbought else 0.0
    pack["oversold"] = 1.0 if oversold else 0.0
    pack.pop("_hist_prev", None)
    market._osc_pack_cache = (n, last, dict(pack))
    return pack


STOCK_REVERSION_WINDOWS = (2, 4, 6, 13, 26)
# 짧은 창일수록 무겁다. 2주 가중은 26주의 13배.
# 구 2.0은 되돌림이 수급을 압도해 봉마다 반전되는 느낌을 줌.
STOCK_REVERSION_STRENGTH = 0.85
# 연속 상승·하락이 한 주 반전으로 끊겨도 직전 되돌림의 이 비율은 남긴다.
STOCK_REVERSION_PERSIST = 0.60


def _stock_reversion_window_weight(period: int) -> float:
    return 1.0 / max(float(period), 1.0)


def stock_reversion_pull(market: Optional["StockMarketState"]) -> float:
    """2·4·6·13·26주 창의 쏠림×평균가 괴리. 짧은 창이 더 크게 반영된다.

    창 N: s=(상승주−하락주)/N, g=MA_N/현재가−1, r=|s|×g.
    많이 올라 평균 위이거나 많이 내려 평균 아래일 때만 적용하고, 어긋나면 0.
    이력이 N+1주보다 짧은 창은 평균에서 뺀다.
    이번 주 신호가 직전보다 약하면 직전 되돌림의 75%는 다음 주까지 남긴다.
    """
    if market is None:
        return 0.0
    fresh = _stock_reversion_pull_fresh(market)
    prev = float(getattr(market, "reversion_pull_memory", 0.0) or 0.0)
    if abs(fresh) + 1e-12 >= abs(prev):
        mixed = fresh
    else:
        mixed = (
            STOCK_REVERSION_PERSIST * prev
            + (1.0 - STOCK_REVERSION_PERSIST) * fresh
        )
    market.reversion_pull_memory = mixed
    return mixed


def _stock_reversion_pull_fresh(market: "StockMarketState") -> float:
    prices = stock_price_series(market)
    if len(prices) < 3:
        return 0.0
    current = float(prices[-1])
    if current <= 1e-12:
        return 0.0
    weighted = 0.0
    weight_sum = 0.0
    for n in STOCK_REVERSION_WINDOWS:
        period = int(n)
        if period <= 0 or len(prices) < period + 1:
            continue
        window = prices[-(period + 1):]
        up = 0
        down = 0
        for i in range(1, len(window)):
            delta = float(window[i]) - float(window[i - 1])
            if delta > 1e-12:
                up += 1
            elif delta < -1e-12:
                down += 1
        skew = (up - down) / float(period)
        ma = sum(float(p) for p in prices[-period:]) / float(period)
        gap = ma / current - 1.0
        pull = abs(skew) * gap if skew * gap < 0.0 else 0.0
        weight = _stock_reversion_window_weight(period)
        weighted += pull * weight
        weight_sum += weight
    if weight_sum <= 1e-12:
        return 0.0
    return STOCK_REVERSION_STRENGTH * weighted / weight_sum


def stock_profit_taking_mod(market: Optional["StockMarketState"]) -> float:
    """지표 과열도 0~0.3 (RSI/Stoch/MACD)."""
    if market is None:
        return 0.0
    pack = stock_oscillator_pack(market)
    rsi = float(pack.get("rsi", 50.0))
    k = float(pack.get("stoch_k", 50.0))
    hist = float(pack.get("macd_hist", 0.0))
    cross = float(pack.get("macd_cross", 0.0))
    pt = 0.0
    if rsi > STOCK_RSI_OVERBOUGHT:
        pt += 0.10 * clamp((rsi - STOCK_RSI_OVERBOUGHT) / 30.0, 0.0, 1.0)
    if k > STOCK_STOCH_OVERBOUGHT:
        pt += 0.08 * clamp((k - STOCK_STOCH_OVERBOUGHT) / 20.0, 0.0, 1.0)
    if cross < 0.0 and rsi >= 50.0:
        pt += 0.10
    elif hist > 0.0 and rsi >= 55.0:
        pt += 0.06
    return clamp(pt, 0.0, 0.3)


def stock_oversold_bounce_mod(market: Optional["StockMarketState"]) -> float:
    """지표 침체 반등 가산 0~0.1."""
    if market is None:
        return 0.0
    pack = stock_oscillator_pack(market)
    rsi = float(pack.get("rsi", 50.0))
    k = float(pack.get("stoch_k", 50.0))
    cross = float(pack.get("macd_cross", 0.0))
    bounce = 0.0
    if rsi < STOCK_RSI_OVERSOLD:
        bounce += 0.04 * clamp((STOCK_RSI_OVERSOLD - rsi) / 30.0, 0.0, 1.0)
    if k < STOCK_STOCH_OVERSOLD:
        bounce += 0.04 * clamp((STOCK_STOCH_OVERSOLD - k) / 20.0, 0.0, 1.0)
    if cross > 0.0:
        bounce += 0.04
    return clamp(bounce, 0.0, 0.10)


def _stock_sma_at(prices: Sequence[float], period: int, end: int) -> Optional[float]:
    p = int(period)
    e = int(end)
    if p <= 0 or e < p or e > len(prices):
        return None
    window = [float(prices[i]) for i in range(e - p, e)]
    if any(x <= 1e-15 for x in window):
        return None
    return sum(window) / float(p)


def _stock_sma_cross(prices: Sequence[float], fast: int, slow: int) -> float:
    """이번 주 단기/장기 SMA 교차. +1 골든, -1 데드, 0 없음."""
    n = len(prices)
    if n < int(slow) + 1:
        return 0.0
    f_now = _stock_sma_at(prices, fast, n)
    s_now = _stock_sma_at(prices, slow, n)
    f_prev = _stock_sma_at(prices, fast, n - 1)
    s_prev = _stock_sma_at(prices, slow, n - 1)
    if None in (f_now, s_now, f_prev, s_prev):
        return 0.0
    prev_d = float(f_prev) - float(s_prev)
    now_d = float(f_now) - float(s_now)
    if prev_d <= 0.0 and now_d > 0.0:
        return 1.0
    if prev_d >= 0.0 and now_d < 0.0:
        return -1.0
    return 0.0


def stock_ma_cross_signal(market: Optional["StockMarketState"]) -> float:
    """MA5/20·MA20/60 골든(+1)/데드(-1). 충돌이면 0."""
    if market is None:
        return 0.0
    prices = stock_price_series(market)
    c_fast = _stock_sma_cross(prices, POP_MA_FAST, POP_MA_SLOW)
    c_mid = _stock_sma_cross(prices, POP_MA_SLOW, POP_MA_MED)
    gold = (c_fast > 0.0) or (c_mid > 0.0)
    dead = (c_fast < 0.0) or (c_mid < 0.0)
    if gold and not dead:
        return 1.0
    if dead and not gold:
        return -1.0
    return 0.0


def stock_golden_dead_cross_signal(market: Optional["StockMarketState"]) -> float:
    """이번 주 골든(+1)/데드(-1) — MA 교차 또는 MACD 시그널 교차."""
    if market is None:
        return 0.0
    prices = stock_price_series(market)
    n = len(prices)
    last = prices[-1] if prices else 0.0
    cached = getattr(market, "_cross_sig_cache", None)
    if (
        isinstance(cached, tuple)
        and len(cached) == 3
        and cached[0] == n
        and abs(float(cached[1]) - last) <= 1e-12
    ):
        return float(cached[2])
    ma_x = stock_ma_cross_signal(market)
    macd_x = float(stock_oscillator_pack(market).get("macd_cross", 0.0) or 0.0)
    gold = (ma_x > 0.0) or (macd_x > 0.0)
    dead = (ma_x < 0.0) or (macd_x < 0.0)
    if gold and not dead:
        result = 1.0
    elif dead and not gold:
        result = -1.0
    else:
        result = 0.0
    market._cross_sig_cache = (n, last, result)
    return result


def stock_at_golden_or_dead_cross(market: Optional["StockMarketState"]) -> bool:
    return abs(stock_golden_dead_cross_signal(market)) > 1e-12


def pop_stock_cross_div_bonus(market: Optional["StockMarketState"]) -> float:
    """골든/데드크로스 주에는 합성 괴리에 가산해 반대호가를 85% 쪽으로 민다."""
    if stock_at_golden_or_dead_cross(market):
        return float(POP_CROSS_OPPOSITE_DIV_BONUS)
    return 0.0


def _stock_weeks_return(prices: Sequence[float], weeks: int) -> Optional[float]:
    w = int(weeks)
    if w <= 0 or len(prices) <= w:
        return None
    prev = float(prices[-1 - w])
    now = float(prices[-1])
    if prev <= 1e-12 or now <= 0.0:
        return None
    return now / prev - 1.0


def _stock_ma_slope_value(prices: Sequence[float], period: int) -> Optional[float]:
    p = int(period)
    n = len(prices)
    k = stock_trend_ma_lookback(p)
    if p <= 0 or k <= 0 or n < p + k:
        return None
    ma_now = sum(prices[-p:]) / p
    ma_prev = sum(prices[-p - k:-k]) / p
    if ma_now <= 0.0 or ma_prev <= 1e-12:
        return None
    return ma_now / ma_prev - 1.0


def _stock_macd_hist_by_index(prices: Sequence[float]) -> Dict[int, float]:
    n = len(prices)
    macd_line = _series_ema(prices, STOCK_MACD_FAST)
    slow = _series_ema(prices, STOCK_MACD_SLOW)
    finite: List[float] = []
    idx: List[int] = []
    for i in range(n):
        a, b = macd_line[i], slow[i]
        if math.isfinite(a) and math.isfinite(b):
            finite.append(a - b)
            idx.append(i)
    if len(finite) < STOCK_MACD_SIGNAL:
        return {}
    sig = _series_ema(finite, STOCK_MACD_SIGNAL)
    out: Dict[int, float] = {}
    for j, i in enumerate(idx):
        s = sig[j]
        if math.isfinite(s):
            out[i] = finite[j] - s
    return out


def _stock_cross_signal_at(
    prices: Sequence[float], hist_at: Dict[int, float], end: int,
) -> float:
    """end 직전 봉 기준 골든(+1)/데드(-1). 충돌이면 0."""
    e = int(end)
    if e < 2 or e > len(prices):
        return 0.0
    view = prices[:e]
    c_fast = _stock_sma_cross(view, POP_MA_FAST, POP_MA_SLOW)
    c_mid = _stock_sma_cross(view, POP_MA_SLOW, POP_MA_MED)
    hist = hist_at.get(e - 1)
    hist_prev = hist_at.get(e - 2)
    macd_x = 0.0
    if hist is not None and hist_prev is not None:
        if hist_prev <= 0.0 and hist > 0.0:
            macd_x = 1.0
        elif hist_prev >= 0.0 and hist < 0.0:
            macd_x = -1.0
    gold = (c_fast > 0.0) or (c_mid > 0.0) or (macd_x > 0.0)
    dead = (c_fast < 0.0) or (c_mid < 0.0) or (macd_x < 0.0)
    if gold and not dead:
        return 1.0
    if dead and not gold:
        return -1.0
    return 0.0


def _stock_cross_decay_term(prices: Sequence[float]) -> float:
    """최근 교차의 4주 감쇠. 가장 가까운 교차만 ±POP_CROSS_MOM_Z × 감쇠."""
    n = len(prices)
    if n < 2:
        return 0.0
    hist_at = _stock_macd_hist_by_index(prices)
    decay = STOCK_RANK_CROSS_DECAY
    for lag, w in enumerate(decay):
        if n - lag < 2:
            break
        sig = _stock_cross_signal_at(prices, hist_at, n - lag)
        if sig > 0.0:
            return POP_CROSS_MOM_Z * float(w)
        if sig < 0.0:
            return -POP_CROSS_MOM_Z * float(w)
    return 0.0


def stock_momentum_z(
    market: Optional["StockMarketState"],
    *,
    actor: str = "ib",
) -> float:
    """순위용 추세 원시값. RSI·스토캐스틱·차익실현은 제외.

    4주·13주 수익률, MA5/20/60 기울기(120·200은 부호 필터), MACD hist/가격,
    교차 4주 감쇠. 국가 단위 ib_cs_zscore 전에 쓴다.
    """
    _ = actor
    if market is None:
        return 0.0
    prices = stock_price_series(market)
    n = len(prices)
    last = prices[-1] if prices else 0.0
    cached = getattr(market, "_trend_rank_raw", None)
    if (
        isinstance(cached, tuple)
        and len(cached) == 3
        and cached[0] == n
        and abs(float(cached[1]) - last) <= 1e-12
    ):
        return float(cached[2])

    parts: List[Tuple[float, float]] = []
    ret4 = _stock_weeks_return(prices, 4)
    if ret4 is not None:
        parts.append((
            STOCK_RANK_W_RET4,
            ib_clip_z(ret4 / max(STOCK_RANK_RET4_SCALE, 1e-12)),
        ))
    ret13 = _stock_weeks_return(prices, 13)
    if ret13 is not None:
        parts.append((
            STOCK_RANK_W_RET13,
            ib_clip_z(ret13 / max(STOCK_RANK_RET13_SCALE, 1e-12)),
        ))

    scale = max(float(STOCK_TREND_SLOPE_SCALE), 1e-12)
    short: List[Tuple[int, float]] = []
    for period in STOCK_RANK_MA_PERIODS:
        sl = _stock_ma_slope_value(prices, period)
        if sl is None:
            continue
        short.append((int(period), ib_clip_z(float(sl) / scale)))
    if short:
        sw = _stock_trend_ma_weights([p for p, _ in short])
        signed = sum(w * z for w, (_, z) in zip(sw, short))
        oppose = False
        for period in STOCK_RANK_MA_SIGN_PERIODS:
            sl = _stock_ma_slope_value(prices, period)
            if sl is None or abs(float(sl)) < STOCK_RANK_LONG_SLOPE_FLAT:
                continue
            if signed * float(sl) < 0.0:
                oppose = True
                break
        if oppose:
            signed = 0.0
        parts.append((STOCK_RANK_W_SLOPE, signed))

    if last > 1e-12:
        hist = float(stock_oscillator_pack(market).get("macd_hist", 0.0) or 0.0)
        parts.append((
            STOCK_RANK_W_MACD,
            ib_clip_z(hist / last / max(STOCK_RANK_MACD_SCALE, 1e-12)),
        ))

    if parts:
        wsum = sum(w for w, _ in parts)
        raw = sum(w * v for w, v in parts) / wsum if wsum > 1e-12 else 0.0
    else:
        raw = 0.0
    raw += _stock_cross_decay_term(prices)
    market._trend_rank_raw = (n, last, raw)
    return raw


def _blend_regime_table(
    tables: Dict[str, Dict[str, float]],
    probs: Dict[str, float],
) -> Dict[str, float]:
    keys: List[str] = []
    for row in tables.values():
        for k in row:
            if k not in keys:
                keys.append(k)
    out = {k: 0.0 for k in keys}
    for name, row in tables.items():
        p = float(probs.get(name, 0.0) or 0.0)
        if p <= 1e-12:
            continue
        for k, v in row.items():
            out[k] = out.get(k, 0.0) + p * float(v)
    total = sum(out.values())
    if total <= 1e-12:
        n = max(len(keys), 1)
        return {k: 1.0 / n for k in keys}
    return {k: v / total for k, v in out.items()}


def stock_country_regime_logits(
    world: "World",
    country_id: str,
) -> Dict[str, float]:
    cache = getattr(world, "_fin_cache_stock_regime_logits", None)
    if cache is None:
        world._fin_cache_stock_regime_logits = {}
        cache = world._fin_cache_stock_regime_logits
    cid = str(country_id or "")
    if cid in cache:
        return dict(cache[cid])
    trends: List[float] = []
    aligned = 0
    macd_n = 0
    for iid, sm in (getattr(world, "stock_markets", None) or {}).items():
        if issuer_stock_country_id(world, iid) != cid:
            continue
        t, d = stock_chart_trend_score(sm)
        trends.append(float(t))
        pack = stock_oscillator_pack(sm)
        hist = float(pack.get("macd_hist", 0.0) or 0.0)
        if abs(hist) <= 1e-15:
            continue
        macd_n += 1
        if (d == "UP" and hist > 0.0) or (d == "DN" and hist < 0.0):
            aligned += 1
    avg_trend = sum(trends) / len(trends) if trends else 0.5
    if not math.isfinite(avg_trend):
        avg_trend = 0.5
    trend_strength = abs(avg_trend - 0.5) * 2.0
    chop = 1.0 - clamp(trend_strength / 0.40, 0.0, 1.0)
    align_frac = (aligned / macd_n) if macd_n > 0 else 0.5
    macro = ib_macro_factor_pack(world, cid) if cid else {}
    try:
        avg_mos = abs(float(macro.get("avg_mos", 0.0) or 0.0))
    except (TypeError, ValueError):
        avg_mos = 0.0
    if not math.isfinite(avg_mos):
        avg_mos = 0.0
    stress = float(ib_market_stress_factor(world, cid) or 0.0) if cid else 0.0
    probs = macro.get("regime_probs") or {}
    rec_stag = float(probs.get("recession", 0.0) or 0.0) + float(
        probs.get("stagflation", 0.0) or 0.0)
    m_s = abs(float(macro.get("m_s", 0.0) or 0.0))
    logits = {
        "momentum": 1.2 * trend_strength + 0.8 * align_frac - 0.5 * chop,
        "fundamental": (
            2.0 * avg_mos / max(IB_Z_TYPICAL_MOS, 1e-9) + 0.8 * chop
        ),
        "macro": 1.5 * stress + 1.2 * rec_stag + 0.4 * (m_s / 2.0),
    }
    cache[cid] = dict(logits)
    return dict(logits)


def stock_actor_regime_weights(
    world: "World",
    country_id: str,
    *,
    actor: str = "ib",
    style: str = "",
) -> Dict[str, float]:
    """국면 softmax → 주체별 가중. 주당 1회 EMA 갱신."""
    cid = str(country_id or "")
    style_key = str(style or "balanced_value")
    cache_key = ("pop", cid) if actor == "pop" else ("ib", cid, style_key)
    week_cache = getattr(world, "_fin_cache_regime_weights", None)
    if week_cache is None:
        world._fin_cache_regime_weights = {}
        week_cache = world._fin_cache_regime_weights
    hit = week_cache.get(cache_key)
    if hit is not None:
        return dict(hit)

    logits = stock_country_regime_logits(world, cid)
    if actor == "pop":
        logits["momentum"] = float(logits.get("momentum", 0.0)) + POP_REGIME_MOMENTUM_PRIOR
        tables = STOCK_POP_REGIME_TABLES
    else:
        prior = IB_REGIME_STYLE_PRIOR.get(style_key) or {}
        for k, v in prior.items():
            logits[k] = float(logits.get(k, 0.0)) + float(v)
        tables = STOCK_IB_REGIME_TABLES
    probs = ib_softmax_weights(logits, STOCK_REGIME_SOFTMAX_TEMP)
    target = _blend_regime_table(tables, probs)
    if actor == "pop":
        mom = max(STOCK_POP_MOMENTUM_FLOOR, float(target.get("mom", 0.0) or 0.0))
        rest = max(0.0, 1.0 - mom)
        other = float(target.get("value", 0.0)) + float(target.get("macro", 0.0))
        if other <= 1e-12:
            target = {"value": rest * 0.5, "macro": rest * 0.5, "mom": mom}
        else:
            target = {
                "value": rest * float(target.get("value", 0.0)) / other,
                "macro": rest * float(target.get("macro", 0.0)) / other,
                "mom": mom,
            }
    else:
        risk_w = max(0.08, float(IB_NAME_W_RISK))
        core = (
            float(target.get("mos", 0.0))
            + float(target.get("er", 0.0))
            + float(target.get("macro", 0.0))
            + float(target.get("mom", 0.0))
        )
        scale = (1.0 - risk_w) / max(core, 1e-9)
        mos = float(target.get("mos", 0.0)) * scale
        er = float(target.get("er", 0.0)) * scale
        macro_w = float(target.get("macro", 0.0)) * scale
        mom = float(target.get("mom", 0.0)) * scale
        er_den = IB_NAME_W_ERG + IB_NAME_W_ERC
        erg = er * (IB_NAME_W_ERG / max(er_den, 1e-9))
        erc = er - erg
        target = {
            "mos": mos, "er": er, "erg": erg, "erc": erc,
            "macro": macro_w, "mom": mom, "risk": risk_w,
        }

    ema_store = getattr(world, "_stock_regime_weight_ema", None)
    if ema_store is None:
        world._stock_regime_weight_ema = {}
        ema_store = world._stock_regime_weight_ema
    prev = ema_store.get(cache_key)
    if prev is None:
        blended = dict(target)
    else:
        blended = {}
        keys = set(target.keys()) | set(prev.keys())
        for k in keys:
            blended[k] = flow_smooth_ma(
                float(prev.get(k, 0.0) or 0.0),
                float(target.get(k, 0.0) or 0.0),
                lam=STOCK_REGIME_EMA_LAMBDA,
            )
        tot = sum(abs(v) for v in blended.values())
        if tot > 1e-12 and actor == "pop":
            s = blended.get("value", 0.0) + blended.get("macro", 0.0) + blended.get("mom", 0.0)
            if s > 1e-12:
                blended["value"] /= s
                blended["macro"] /= s
                blended["mom"] /= s
                blended["mom"] = max(STOCK_POP_MOMENTUM_FLOOR, blended["mom"])
                rest = max(0.0, 1.0 - blended["mom"])
                other = blended["value"] + blended["macro"]
                if other > 1e-12:
                    blended["value"] = rest * blended["value"] / other
                    blended["macro"] = rest * blended["macro"] / other
        elif actor != "pop":
            risk_w = max(0.08, float(blended.get("risk", IB_NAME_W_RISK) or IB_NAME_W_RISK))
            core_keys = ("mos", "erg", "erc", "macro", "mom")
            core = sum(float(blended.get(k, 0.0) or 0.0) for k in core_keys)
            scale = (1.0 - risk_w) / max(core, 1e-9)
            for k in core_keys:
                blended[k] = float(blended.get(k, 0.0) or 0.0) * scale
            blended["risk"] = risk_w
            blended["er"] = float(blended.get("erg", 0.0)) + float(blended.get("erc", 0.0))
    ema_store[cache_key] = dict(blended)
    week_cache[cache_key] = dict(blended)
    return dict(blended)


def stock_volume_move_scale(current_vol: float, issued_shares: float) -> float:
    """총 주문량 / 발행주식 비율 → 변동성 계수 (주간 ~수 % 스케일).

    0%면 MIN, RATIO_HIGH까지는 직선으로 AT_HIGH.
    그 이상은 로그로 MAX에 가까워지고, 늘어나는 폭은 점점 줄어든다.
    """
    s_min = STOCK_VOLUME_SCALE_MIN
    s_high = STOCK_VOLUME_SCALE_AT_HIGH
    s_max = STOCK_VOLUME_SCALE_MAX
    issued = max(0.0, float(issued_shares or 0.0))
    if issued <= 1e-12:
        return s_min
    r = max(0.0, float(current_vol or 0.0)) / issued
    r_high = STOCK_VOLUME_RATIO_HIGH
    if r <= r_high:
        return s_min + (s_high - s_min) * (r / max(r_high, 1e-12))
    gap = max(0.0, s_max - s_high)
    slope = (s_high - s_min) / max(r_high, 1e-12)
    span = gap / slope if slope > 1e-12 else r_high
    damp = math.log1p((r - r_high) / max(span, 1e-12))
    return s_high + gap * (damp / (1.0 + damp))


def stock_take_usual_order_volume(market: "StockMarketState", current_vol: float) -> float:
    """하위호환: 예전 EMA 평소 거래량. 가격식은 발행주식 대비 주문량을 쓴다."""
    cur = max(0.0, float(current_vol or 0.0))
    prev = max(0.0, float(getattr(market, "usual_order_volume", 0.0) or 0.0))
    usual = prev if prev > 1e-12 else cur
    market.usual_order_volume = flow_smooth_ma(
        prev, cur, lam=STOCK_VOLUME_USUAL_MA_LAMBDA)
    return usual


def stock_market_issued_shares(
    market: Optional["StockMarketState"],
    company_info: Optional[Dict[str, float]] = None,
) -> float:
    if company_info:
        issued = float(company_info.get("stock_shares", 0.0) or 0.0)
        if issued > 1e-12:
            return issued
    if market is None:
        return 0.0
    return max(0.0, float(getattr(market, "issued_shares", 0.0) or 0.0))


def stock_attraction_order_scale(
    attraction: float,
    *,
    neutral: float = STOCK_ATTRACTION_NEUTRAL,
    max_scale: float = STOCK_ATTRACTION_ORDER_SCALE_MAX,
) -> float:
    """매력도가 중립에서 멀수록(높거나 낮을수록) 주문 배율. 1 ~ max_scale."""
    a = max(1e-9, float(attraction or 0.0))
    n = max(1e-9, float(neutral or 1.0))
    hi = max(float(max_scale or 1.0), 1.0)
    dist = abs(math.log(a / n))
    t = clamp(dist / math.log(4.0), 0.0, 1.0)
    return 1.0 + t * (hi - 1.0)


def apply_stock_attraction_order_scale(
    buy_q: float,
    sell_q: float,
    attraction: float,
    max_order_value: float,
) -> Tuple[float, float]:
    """매력 극단일수록 주문을 키우되, 보유 대비 주당 유량 상한을 넘기지 않는다."""
    cap = max(0.0, float(max_order_value or 0.0))
    scale = stock_attraction_order_scale(attraction)
    buy = max(0.0, float(buy_q or 0.0)) * scale
    sell = max(0.0, float(sell_q or 0.0)) * scale
    if cap > 1e-12:
        buy = min(buy, cap)
        sell = min(sell, cap)
    return buy, sell


def stock_imbalance_change_rate(
    buy_vol: float,
    sell_vol: float,
    *,
    issued_shares: float = 0.0,
    usual_vol: float = 0.0,
) -> float:
    """tanh로 완화된 (매수-매도)/합 × 발행주식 대비 거래량 계수."""
    total = float(buy_vol) + float(sell_vol)
    if total <= 1e-12:
        return 0.0
    raw_imb = (float(buy_vol) - float(sell_vol)) / total
    # 한쪽으로 쏟아져도 ±1에 선형으로 붙지 않게 완화
    gain = max(1e-9, float(STOCK_IMBALANCE_TANH_GAIN))
    imb = math.tanh(gain * raw_imb) / math.tanh(gain)
    issued = float(issued_shares or 0.0)
    if issued <= 1e-12:
        issued = float(usual_vol or 0.0)
    return imb * stock_volume_move_scale(total, issued)


def stock_recent_move_streak(market: Optional["StockMarketState"]) -> Tuple[int, float]:
    """직전 연속 동방향 주수와 그 부호(+1/-1/0)."""
    if market is None:
        return 0, 0.0
    hist = list(getattr(market, "price_change_history", None) or [])
    if not hist:
        prices = [
            float(p) for p in (getattr(market, "weekly_price_history", None) or [])
            if float(p) > 1e-12
        ]
        hist = []
        for i in range(1, len(prices)):
            prev = prices[i - 1]
            if prev > 1e-12:
                hist.append(prices[i] / prev - 1.0)
    if not hist:
        return 0, 0.0
    last = float(hist[-1])
    if abs(last) <= 1e-8:
        return 0, 0.0
    sign = 1.0 if last > 0.0 else -1.0
    streak = 1
    for chg in reversed(hist[:-1]):
        c = float(chg)
        if c * sign > 1e-8:
            streak += 1
        else:
            break
    return streak, sign


def stock_streak_flow_damp(market: Optional["StockMarketState"], flow: float) -> float:
    """연속 동방향 주가 충격이 쌓이면 같은 방향 수급 충격을 줄인다."""
    f = float(flow or 0.0)
    if abs(f) <= 1e-15:
        return 0.0
    streak, sign = stock_recent_move_streak(market)
    if streak < STOCK_STREAK_DAMP_START or f * sign <= 0.0:
        return f
    extra = max(0, streak - STOCK_STREAK_DAMP_START + 1)
    mult = max(
        STOCK_STREAK_DAMP_FLOOR,
        1.0 - STOCK_STREAK_DAMP_PER * float(extra),
    )
    return f * mult


_STOCK_PRICE_INTENTS = frozenset({
    "raise", "lower", "neutral", "force_raise", "force_lower",
})
_STOCK_TACTICAL_PURPOSES = frozenset({"tactical", "tactical_short"})
_STOCK_SELL_SIDES = frozenset({"sell", "s", "ask"})


def stock_order_price_intent(
    purpose: str,
    side: str,
    explicit: str = "",
) -> str:
    """주식 주문의 가격 의도. explicit가 있으면 그대로, 아니면 purpose·side로 추론."""
    raw = explicit if isinstance(explicit, str) else str(explicit or "")
    if raw:
        raw_l = raw.strip().lower()
        if raw_l in _STOCK_PRICE_INTENTS:
            return raw_l
    p = purpose if isinstance(purpose, str) else str(purpose or "")
    if p:
        p = p.strip().lower()
    side_l = side if isinstance(side, str) else str(side or "")
    sell = side_l.strip().lower() in _STOCK_SELL_SIDES if side_l else False
    if p == "force_liq":
        return "force_lower" if sell else "force_raise"
    if p in _STOCK_TACTICAL_PURPOSES:
        return "lower" if sell else "raise"
    if p == "liquidity" and sell:
        return "lower"
    return "neutral"


def stock_price_intent_weight(intent: str, purpose: str = "") -> float:
    """가격식에만 쓰는 주문 가중. 체결 수량에는 적용하지 않는다."""
    p = purpose if isinstance(purpose, str) else str(purpose or "")
    if p:
        p = p.strip().lower()
    if p == "lp":
        return STOCK_INTENT_WEIGHT_LP
    if p == "liquidity":
        return STOCK_INTENT_WEIGHT_LIQUIDITY
    intent_l = intent if isinstance(intent, str) else str(intent or "neutral")
    if intent_l:
        intent_l = intent_l.strip().lower()
    if intent_l in ("raise", "lower", "force_raise", "force_lower"):
        return STOCK_INTENT_WEIGHT_DIRECTIONAL
    return STOCK_INTENT_WEIGHT_NEUTRAL


def stock_orders_impact_volumes(
    buy_orders: Optional[Sequence[Any]] = None,
    sell_orders: Optional[Sequence[Any]] = None,
) -> Tuple[float, float, float, float]:
    """의도 가중 매수/매도량과 강제청산 순량.

    Returns:
        impact_buy, impact_sell, force_raise_qty, force_lower_qty
    """
    impact_buy = 0.0
    impact_sell = 0.0
    force_raise = 0.0
    force_lower = 0.0
    # 핫패스: BuyOrder/SellOrder는 속성 직접 접근 (getattr·str 반복 회피)
    for o in buy_orders or ():
        try:
            qty = o.quantity
        except AttributeError:
            qty = float(getattr(o, "quantity", 0.0) or 0.0)
        if qty <= 1e-15:
            continue
        try:
            purpose = o.purpose or ""
            explicit = o.price_intent or ""
        except AttributeError:
            purpose = str(getattr(o, "purpose", "") or "")
            explicit = str(getattr(o, "price_intent", "") or "")
        intent = stock_order_price_intent(purpose, "buy", explicit)
        impact_buy += qty * stock_price_intent_weight(intent, purpose)
        if intent == "force_raise":
            force_raise += qty
    for s in sell_orders or ():
        try:
            qty = s.quantity
        except AttributeError:
            qty = float(getattr(s, "quantity", 0.0) or 0.0)
        if qty <= 1e-15:
            continue
        try:
            purpose = s.purpose or ""
            explicit = s.price_intent or ""
        except AttributeError:
            purpose = str(getattr(s, "purpose", "") or "")
            explicit = str(getattr(s, "price_intent", "") or "")
        intent = stock_order_price_intent(purpose, "sell", explicit)
        impact_sell += qty * stock_price_intent_weight(intent, purpose)
        if intent == "force_lower":
            force_lower += qty
    return impact_buy, impact_sell, force_raise, force_lower


def invalidate_stock_flow_signal_caches(world: "World") -> None:
    """주문장 기반 주가 수급 시그널 캐시 무효화 (로직 동일, 재계산만 강제)."""
    flow = getattr(world, "_fin_cache_stock_flow_signal", None)
    if flow is not None:
        flow.clear()
    world._fin_cache_world_stock_signal = None
    world._fin_cache_world_stock_signal_ready = False


def stock_fair_value_reversion(
    current_price: float,
    fair_value: float,
    *,
    opposing_flow: float = 0.0,
) -> float:
    """FV 밴드 밖일 때만 log(FV/P)×speed 를 ±STOCK_FV_REVERSION_MAX로 제한.

    밴드에서 멀수록 되돌림을 키워(최대 2.5배) 큰 공정가 괴리를 더 빨리 해소한다.
    opposing_flow가 회귀와 반대 부호이면 |flow|/MAX 비율만큼 회귀를 깎아
    강한 수급이 공정가 당김을 이길 수 있게 한다.
    """
    px = float(current_price or 0.0)
    fv = float(fair_value or 0.0)
    if px <= 1e-12 or fv <= 1e-12:
        return 0.0
    ratio = px / fv
    if STOCK_FV_BAND_LO <= ratio <= STOCK_FV_BAND_HI:
        return 0.0
    gap = math.log(fv / px)
    # 밴드 가장자리 대비 초과 거리 → 되돌림 배율 1~2.5 (괴리↑일수록 가속)
    if ratio > STOCK_FV_BAND_HI:
        excess = ratio / STOCK_FV_BAND_HI - 1.0
    else:
        excess = STOCK_FV_BAND_LO / max(ratio, 1e-9) - 1.0
    stretch = 1.0 + clamp(excess / 0.35, 0.0, 1.5)
    rev = clamp(
        gap * STOCK_FV_REVERSION_SPEED * stretch,
        -STOCK_FV_REVERSION_MAX * stretch,
        STOCK_FV_REVERSION_MAX * stretch,
    )
    flow = float(opposing_flow or 0.0)
    if rev * flow < 0.0 and abs(flow) > 1e-15:
        damp = clamp(
            1.0 - abs(flow) / max(STOCK_FV_REVERSION_MAX, 1e-9),
            0.0,
            1.0,
        )
        rev *= damp
    return rev


def stock_apply_force_liq_floor(
    price_change: float,
    force_raise_qty: float,
    force_lower_qty: float,
    *,
    impact_total: float = 0.0,
) -> float:
    """강제청산이 가격영향의 상당 비중일 때만 방향을 지킨다.

    강제청산 주문은 이미 가중치 1.0으로 수급·가격식에 포함된다.
    소량일 때는 건드리지 않고, 비중이 SHARE_MIN 이상인데 노이즈가
    부호를 뒤집으면 0 쪽으로 눌러 반대 방향으로 튀지 않게 한다.
    고정 ±% 하한은 쓰지 않는다(매주 같은 폭의 인위적 봉 방지).
    """
    up = float(force_raise_qty or 0.0)
    dn = float(force_lower_qty or 0.0)
    net = up - dn
    if abs(net) <= 1e-12:
        return float(price_change or 0.0)
    total = max(float(impact_total or 0.0), abs(net), 1e-12)
    share = abs(net) / total
    if share + 1e-15 < STOCK_FORCE_LIQ_SHARE_MIN:
        return float(price_change or 0.0)
    chg = float(price_change or 0.0)
    if net < 0.0 and chg > 0.0:
        return 0.0
    if net > 0.0 and chg < 0.0:
        return 0.0
    return chg


def _stock_laplace_noise(scale: float) -> float:
    """평균 0, b=scale/√2 인 Laplace 표본 (두꺼운 꼬리)."""
    b = max(float(scale), 1e-15) / math.sqrt(2.0)
    u = random.uniform(-1.0 + 1e-12, 1.0 - 1e-12)
    return -b * math.copysign(1.0, u) * math.log(1.0 - abs(u))


def stock_update_realized_vol(market: "StockMarketState") -> float:
    """최근 등락 기반 실현변동성 EMA. 미시구조 노이즈 스케일에 사용."""
    hist = list(getattr(market, "price_change_history", None) or [])[-8:]
    if len(hist) >= 2:
        recent = math.sqrt(sum(float(c) * float(c) for c in hist) / float(len(hist)))
    elif hist:
        recent = abs(float(hist[-1]))
    else:
        recent = float(STOCK_PRICE_NOISE_BASE)
    prev = float(getattr(market, "realized_vol_ema", 0.0) or 0.0)
    if prev <= 1e-15:
        prev = float(STOCK_PRICE_NOISE_BASE)
    lam = clamp(float(STOCK_VOL_EMA_LAMBDA), 0.05, 0.80)
    blended = (1.0 - lam) * prev + lam * max(recent, STOCK_PRICE_NOISE_FLOOR * 0.5)
    vol = clamp(
        0.55 * float(STOCK_PRICE_NOISE_BASE) + 0.45 * blended,
        float(STOCK_PRICE_NOISE_FLOOR),
        float(STOCK_PRICE_NOISE_MAX),
    )
    market.realized_vol_ema = vol
    return vol


def stock_microstructure_noise(
    market: "StockMarketState",
    *,
    apply_noise: bool,
) -> float:
    """종목 고유 미시구조 노이즈 — 변동성 클러스터링 + 희귀 점프."""
    if not apply_noise:
        return 0.0
    vol = stock_update_realized_vol(market)
    noise = _stock_laplace_noise(vol)
    if random.random() < float(STOCK_PRICE_JUMP_PROB):
        noise += random.gauss(0.0, vol * float(STOCK_PRICE_JUMP_SCALE))
    return clamp(
        noise,
        -float(STOCK_PRICE_ORDER_MOVE_CAP),
        float(STOCK_PRICE_ORDER_MOVE_CAP),
    )


def stock_draw_country_market_factor(
    world: "World",
    country_id: str,
) -> float:
    """국가·주 단위 공유 시장충격. Laplace + GDP/신용 약한 편향."""
    week = int(getattr(world, "week", 0) or 0)
    cache = getattr(world, "_stock_market_factor_cache", None)
    if not isinstance(cache, dict) or int(cache.get("_week", -1)) != week:
        cache = {"_week": week}
        world._stock_market_factor_cache = cache
    key = str(country_id or "") or "_"
    hit = cache.get(key)
    if hit is not None:
        try:
            return float(hit)
        except (TypeError, ValueError):
            pass
    shock = _stock_laplace_noise(float(STOCK_MARKET_FACTOR_BASE))
    if random.random() < float(STOCK_MARKET_FACTOR_JUMP_PROB):
        shock += random.gauss(0.0, float(STOCK_MARKET_FACTOR_BASE) * 2.2)
    bias = 0.0
    try:
        country = world.countries.get(country_id) if country_id else None
        if country is not None:
            gdp_hist = list(country_ensure_gdp_history(country))
            gdp_yoy = series_annual_flow_yoy_pct(gdp_hist) if len(gdp_hist) >= 2 else None
            if gdp_yoy is not None:
                bias += 0.35 * math.tanh(float(gdp_yoy) / 100.0)
            spot = country_credit_score_spot(world, country_id)
            spot_score = float(spot.get("score", 50.0) or 50.0)
            credit_ma, _n = credit_score_52w_ma(
                world, f"gov_{country_id}", spot_score)
            bias += 0.25 * ((float(credit_ma) - 50.0) / 50.0)
    except Exception:
        bias = 0.0
    shock += 0.4 * float(bias) * float(STOCK_MARKET_FACTOR_BASE)
    shock = clamp(
        shock,
        -float(STOCK_PRICE_ORDER_MOVE_CAP),
        float(STOCK_PRICE_ORDER_MOVE_CAP),
    )
    cache[key] = shock
    return shock


def stock_price_change_from_orders(
    market: "StockMarketState",
    company_info: Optional[Dict[str, float]] = None,
    *,
    apply_noise: bool = False,
    freeze_price: bool = False,
) -> float:
    """의도 가중 수급 + 추세·되돌림 + 시장충격·미시노이즈 + 강제청산 하한.

    수급만으로 매주 비슷한 %가 나오면 캔들·지수가 직선처럼 보이므로,
    전주 관성·차트 되돌림·소화주·두꺼운 꼬리 노이즈로 현실적인 굴곡을 만든다.
    """
    if freeze_price:
        return 0.0
    info = company_info or {}
    impact_buy, impact_sell, force_up, force_dn = stock_orders_impact_volumes(
        getattr(market, "buy_orders", None),
        getattr(market, "sell_orders", None),
    )
    issued = stock_market_issued_shares(market, info)
    flow = stock_imbalance_change_rate(
        impact_buy, impact_sell, issued_shares=issued)
    flow = stock_streak_flow_damp(market, flow)
    # 시총 가중 충격 흡수: 대형주는 동일 주문에도 % 변동이 작음
    try:
        mcap = float(info.get("market_cap", 0.0) or 0.0)
    except (TypeError, ValueError):
        mcap = 0.0
    if mcap <= 1e-9:
        shares = float(info.get("stock_shares", 0.0) or 0.0)
        px = float(getattr(market, "current_price", 0.0) or 0.0)
        mcap = shares * px
    try:
        median_mcap = float(info.get("median_mcap", 0.0) or 0.0)
    except (TypeError, ValueError):
        median_mcap = 0.0
    if mcap > 1e-9 and median_mcap > 1e-9 and abs(flow) > 1e-15:
        rel = mcap / median_mcap
        flow /= (1.0 + float(STOCK_MCAP_FLOW_DAMP_GAMMA) * math.log1p(max(0.0, rel)))
    # 반대호가 비율이 비슷하면 |flow|가 매주 ~동일해 직선 추세가 됨 → 진폭 지터
    if apply_noise and abs(flow) > 1e-15:
        jitter = clamp(float(STOCK_FLOW_AMP_JITTER), 0.0, 0.95)
        if jitter > 1e-15:
            flow *= random.uniform(1.0 - jitter, 1.0 + jitter)
    # 추세 속 소화 주: 연속 동방향이 길수록 더 자주 폭을 줄여 직선 추세를 깬다
    if apply_noise and abs(flow) > float(STOCK_PRICE_RANGE_EPS) * 0.5:
        streak, sign = stock_recent_move_streak(market)
        digest_p = float(STOCK_DIGEST_WEEK_PROB)
        if streak >= STOCK_STREAK_DAMP_START and flow * sign > 0.0:
            digest_p = min(
                float(STOCK_DIGEST_STREAK_PROB_CAP),
                digest_p + float(STOCK_DIGEST_STREAK_BONUS) * float(streak),
            )
        if random.random() < digest_p:
            flow *= float(STOCK_DIGEST_WEEK_SCALE)

    last_close = float(getattr(market, "current_price", 0.0) or 0.0)
    if last_close <= 1e-12:
        last_close = stock_market_reference_price(market)
    fv = float(info.get("fair_value", 0.0) or 0.0)
    if fv <= 1e-12:
        fv = float(getattr(market, "fair_value", 0.0) or 0.0)
    if fv <= 1e-12:
        fv = last_close
    fv_rev = stock_fair_value_reversion(
        last_close, fv, opposing_flow=flow)
    # 예상 신호 경로(apply_noise=False)는 되돌림 메모리를 건드리지 않는다.
    if apply_noise:
        chart_rev = stock_reversion_pull(market)
    else:
        chart_rev = _stock_reversion_pull_fresh(market)

    hist = list(getattr(market, "price_change_history", None) or [])
    prev_chg = float(hist[-1]) if hist else 0.0
    flow_signal = flow + fv_rev + chart_rev
    mixed = financial_regime_signed_change(
        prev_chg,
        flow_signal,
        market_invest_bias(market),
        move_cap=STOCK_PRICE_ORDER_MOVE_CAP,
        gravity=0.0,
    )

    market_factor = 0.0
    if apply_noise:
        try:
            market_factor = float(info.get("market_factor", 0.0) or 0.0)
        except (TypeError, ValueError):
            market_factor = 0.0
    noise = stock_microstructure_noise(market, apply_noise=apply_noise)

    chg = mixed + float(STOCK_MARKET_FACTOR_BETA) * market_factor + noise
    chg = clamp(chg, -STOCK_PRICE_ORDER_MOVE_CAP, STOCK_PRICE_ORDER_MOVE_CAP)
    chg = stock_apply_force_liq_floor(
        chg, force_up, force_dn,
        impact_total=impact_buy + impact_sell,
    )
    return clamp(chg, -STOCK_PRICE_ORDER_MOVE_CAP, STOCK_PRICE_ORDER_MOVE_CAP)


def bond_market_current_spread(
    market: "BondMarketState",
    base_rate: float,
) -> float:
    """시장스프레드(%p). 미설정 시 쿠폰 − 기준금리로 부트스트랩."""
    base = float(base_rate or 0.0)
    raw = getattr(market, "current_spread", None)
    if raw is None:
        last = float(getattr(market, "current_interest_rate", 0.0) or 0.0)
        if last <= 1e-12:
            last = max(base, RATE_MIN)
        return clamp(last - base, BOND_SPREAD_FLOOR, BOND_SPREAD_CEIL)
    try:
        return clamp(float(raw), BOND_SPREAD_FLOOR, BOND_SPREAD_CEIL)
    except (TypeError, ValueError):
        last = float(getattr(market, "current_interest_rate", 0.0) or 0.0)
        return clamp(last - base, BOND_SPREAD_FLOOR, BOND_SPREAD_CEIL)


def bond_spread_delta_from_book(
    market: "BondMarketState",
    *,
    base_rate: float,
    fair_rate: Optional[float] = None,
) -> float:
    """주문장 수급 + 평균회귀 + 관성 + 바이어스 → 주간 스프레드 변동(%p)."""
    total_demand = sum(float(o.quantity or 0.0) for o in (market.buy_orders or []))
    secondary_supply = 0.0
    treasury_supply = 0.0
    for s in (market.sell_orders or []):
        qty = float(getattr(s, "quantity", 0.0) or 0.0)
        if qty <= 1e-12:
            continue
        if getattr(s, "is_treasury_issue", False):
            treasury_supply += qty
        else:
            secondary_supply += qty
    # 미소화 신규 발행도 일부 매도압력으로 반영해 금리가 매력 구간으로 열리게 한다.
    effective_supply = secondary_supply + float(
        BOND_TREASURY_SUPPLY_FLOW_WEIGHT) * treasury_supply
    flow_bp = bond_flow_spread_delta(
        bond_sell_buy_rate_ratio(effective_supply, total_demand))
    spread = bond_market_current_spread(market, base_rate)
    fair = float(fair_rate) if fair_rate is not None else 0.0
    mr_bp = 0.0
    if fair > 0.0:
        mr_bp = (fair - float(base_rate) - spread) * BOND_SPREAD_MEAN_REVERT
    hist = getattr(market, "rate_change_history", None) or []
    prev_chg = float(hist[-1] or 0.0) if hist else 0.0
    trend_bp = prev_chg * BOND_SPREAD_TREND_PREV
    bias_bp = market_invest_bias(market) * BOND_SPREAD_BIAS_SCALE
    return clamp(
        flow_bp + mr_bp + trend_bp + bias_bp,
        -BOND_SPREAD_WEEKLY_MOVE_CAP,
        BOND_SPREAD_WEEKLY_MOVE_CAP,
    )


def bond_discount_price(
    face_value: float,
    rate: float,
    tenor_years: float = 5.0,
    coupon_rate: Optional[float] = None,
) -> float:
    """변동금리채 결제·평가 금액. 이자가 매주 시장금리로 다시 붙으므로 가격은 액면.

    금리 변동은 주간 이자(액면 × 현재금리 / 52)로만 반영된다.
    rate·tenor_years·coupon_rate는 호출부 호환용이며 가격에 쓰지 않는다.
    """
    _ = (rate, tenor_years, coupon_rate)
    return max(0.0, float(face_value or 0.0))


def bond_mtm_prices(
    face_value: float,
    purchase_rate: float,
    current_rate: float,
    tenor_years: float = 5.0,
) -> Tuple[float, float]:
    """매입가·시가. 쿠폰이 시장금리에 연동되므로 둘 다 액면."""
    _ = (purchase_rate, current_rate, tenor_years)
    face = bond_discount_price(face_value, current_rate, tenor_years=tenor_years)
    return face, face


def bond_holding_mark_value(
    world: Optional["World"],
    market_key: str,
    face: float,
    purchase_rate: float = 0.0,
) -> float:
    """보유 채권 1건의 시가. 이자가 매주 시장금리로 재설정되므로 액면."""
    _ = (world, market_key, purchase_rate)
    return bond_discount_price(face, 0.0)


def bond_holdings_mark_value(
    world: Optional["World"],
    holdings: Optional[Dict[str, float]],
    purchase_rates: Optional[Dict[str, float]] = None,
) -> float:
    """보유 채권 시가 합. 변동금리채라 합은 액면 합과 같다."""
    rates = purchase_rates or {}
    total = 0.0
    for key, face in (holdings or {}).items():
        total += bond_holding_mark_value(
            world, str(key), face, float(rates.get(key, 0.0) or 0.0))
    return total


# 회사채·지방채: 발행 로트 만기(년). 만기 전 원금 상환 불가, 만기 후 점진 상환.
BOND_TENOR_YEARS_OPTIONS: Tuple[int, ...] = (3, 5, 10)
BOND_TENOR_WEEKS_PER_YEAR = 52


def bond_tenor_weeks(tenor_years: int) -> int:
    years = int(tenor_years or 5)
    if years not in BOND_TENOR_YEARS_OPTIONS:
        years = 5
    return years * BOND_TENOR_WEEKS_PER_YEAR


def ai_choose_bond_tenor_years(
    world: "World",
    owner: Any,
    kind: str,
) -> int:
    """발행 AI가 3/5/10년 만기를 고른다.

    고금리·저신용 → 단기(3), 저금리·고신용 → 장기(10), 그 외 5년.
    """
    kind = "local" if kind == "local" else "corp"
    base_rate = 3.5
    market_rate = base_rate
    credit_q = 0.55
    try:
        if kind == "corp":
            market_key = str(getattr(owner, "id", "") or "")
            st = world.states.get(getattr(owner, "home_state", ""))
            country = world.countries.get(st.country_id) if st else None
            if country is None:
                country = world.countries.get(getattr(owner, "country_id", "") or "")
            if country is not None:
                base_rate = country_base_rate(country)
            bm = (getattr(world, "bond_markets", {}) or {}).get(market_key)
            market_rate = float(
                getattr(bm, "current_interest_rate", 0.0) or base_rate)
            if market_key:
                credit_q = float(bond_market_credit_quality(world, market_key) or 0.55)
        else:
            state_id = str(getattr(owner, "state_id", "") or "")
            market_key = f"local_{state_id}"
            st = world.states.get(state_id)
            country = world.countries.get(st.country_id) if st else None
            if country is not None:
                base_rate = country_base_rate(country)
            bm = (getattr(world, "bond_markets", {}) or {}).get(market_key)
            market_rate = float(
                getattr(bm, "current_interest_rate", 0.0) or base_rate)
            credit_q = float(bond_market_credit_quality(world, market_key) or 0.55)
    except Exception:
        pass
    rate_pressure = clamp((market_rate - base_rate) / 5.0, -1.0, 1.0)
    credit_signal = clamp((credit_q - 0.5) * 2.0, -1.0, 1.0)
    # 0~1, 높을수록 장기
    score = clamp(0.5 - 0.35 * rate_pressure + 0.35 * credit_signal, 0.0, 1.0)
    if score < 0.38:
        return 3
    if score > 0.62:
        return 10
    return 5


def _bond_issue_lot_queue(owner: Any) -> List[Dict[str, Any]]:
    q = getattr(owner, "bond_issue_lot_queue", None)
    if q is None:
        owner.bond_issue_lot_queue = []
        q = owner.bond_issue_lot_queue
    return q


def _bond_principal_lots(owner: Any) -> List[Dict[str, Any]]:
    lots = getattr(owner, "bond_principal_lots", None)
    if lots is None:
        owner.bond_principal_lots = []
        lots = owner.bond_principal_lots
    return lots


def append_pending_bond_sell(
    owner: Any,
    amount: float,
    world: Optional["World"],
    *,
    kind: str,
) -> int:
    """회사채·지방채 발행 대기 가산 + AI 만기 로트 큐. 반환: 선택 만기(년)."""
    # 협력 중소기업 회사채 차단 (대출만 가능)
    if kind == "corp" and company_is_coop_partner(owner):
        return 5
    amt = float(amount or 0.0)
    if amt <= 1e-9:
        return 5
    tenor = 5
    if world is not None:
        tenor = int(ai_choose_bond_tenor_years(world, owner, kind))
    if tenor not in BOND_TENOR_YEARS_OPTIONS:
        tenor = 5
    owner.pending_bond_sell = float(getattr(owner, "pending_bond_sell", 0.0) or 0.0) + amt
    _bond_issue_lot_queue(owner).append({
        "face": amt,
        "tenor_years": tenor,
    })
    return tenor


def sync_bond_principal_lots(owner: Any, week: int) -> None:
    """bond_balance와 로트 합을 맞춤. 레거시 잔액은 즉시 만기 도래로 간주."""
    lots = _bond_principal_lots(owner)
    bal = max(0.0, float(getattr(owner, "bond_balance", 0.0) or 0.0))
    lot_sum = sum(max(0.0, float(x.get("face", 0.0) or 0.0)) for x in lots)
    if bal > lot_sum + 1e-6:
        gap = bal - lot_sum
        # 기존 잔액: 만기 도래분으로 취급(점진 상환 가능)
        lots.append({
            "face": gap,
            "issue_week": max(0, int(week) - bond_tenor_weeks(5)),
            "tenor_years": 5,
            "mature_week": int(week),
        })
    elif lot_sum > bal + 1e-6:
        # 잔액보다 로트가 크면 FIFO로 축소
        need_cut = lot_sum - bal
        new_lots: List[Dict[str, Any]] = []
        for lot in lots:
            if need_cut <= 1e-9:
                new_lots.append(lot)
                continue
            face = max(0.0, float(lot.get("face", 0.0) or 0.0))
            take = min(face, need_cut)
            face -= take
            need_cut -= take
            if face > 1e-9:
                lot = dict(lot)
                lot["face"] = face
                new_lots.append(lot)
        owner.bond_principal_lots = new_lots


def bond_matured_face(owner: Any, week: int) -> float:
    """만기 도래(상환 가능) 액면."""
    sync_bond_principal_lots(owner, week)
    total = 0.0
    for lot in _bond_principal_lots(owner):
        mature = int(lot.get("mature_week", 0) or 0)
        if mature <= int(week):
            total += max(0.0, float(lot.get("face", 0.0) or 0.0))
    return total


def bond_locked_face(owner: Any, week: int) -> float:
    """만기 전(상환 불가) 액면."""
    sync_bond_principal_lots(owner, week)
    bal = max(0.0, float(getattr(owner, "bond_balance", 0.0) or 0.0))
    return max(0.0, bal - bond_matured_face(owner, week))


def record_bond_principal_from_sale(
    owner: Any,
    sold_face: float,
    week: int,
) -> None:
    """시장 체결분만큼 발행 큐에서 만기를 가져와 원금 로트 기록."""
    sold = max(0.0, float(sold_face or 0.0))
    if sold <= 1e-9:
        return
    q = _bond_issue_lot_queue(owner)
    left = sold
    while left > 1e-9 and q:
        head = q[0]
        face = max(0.0, float(head.get("face", 0.0) or 0.0))
        tenor = int(head.get("tenor_years", 5) or 5)
        if tenor not in BOND_TENOR_YEARS_OPTIONS:
            tenor = 5
        take = min(face, left)
        if take > 1e-9:
            _bond_principal_lots(owner).append({
                "face": take,
                "issue_week": int(week),
                "tenor_years": tenor,
                "mature_week": int(week) + bond_tenor_weeks(tenor),
            })
        face -= take
        left -= take
        if face <= 1e-9:
            q.pop(0)
        else:
            head["face"] = face
    if left > 1e-9:
        # 큐 없음(레거시): 기본 5년
        _bond_principal_lots(owner).append({
            "face": left,
            "issue_week": int(week),
            "tenor_years": 5,
            "mature_week": int(week) + bond_tenor_weeks(5),
        })


def apply_bond_principal_repay(owner: Any, amount: float, week: int) -> float:
    """만기 도래 로트에서만 FIFO 원금 상환. 실제 상환액 반환."""
    want = max(0.0, float(amount or 0.0))
    if want <= 1e-9:
        return 0.0
    sync_bond_principal_lots(owner, week)
    matured = bond_matured_face(owner, week)
    repay = min(want, matured, max(0.0, float(getattr(owner, "bond_balance", 0.0) or 0.0)))
    if repay <= 1e-9:
        return 0.0
    left = repay
    new_lots: List[Dict[str, Any]] = []
    for lot in _bond_principal_lots(owner):
        face = max(0.0, float(lot.get("face", 0.0) or 0.0))
        mature = int(lot.get("mature_week", 0) or 0)
        if left > 1e-9 and mature <= int(week) and face > 1e-9:
            take = min(face, left)
            face -= take
            left -= take
        if face > 1e-9:
            lot = dict(lot)
            lot["face"] = face
            new_lots.append(lot)
    owner.bond_principal_lots = new_lots
    owner.bond_balance = max(0.0, float(getattr(owner, "bond_balance", 0.0) or 0.0) - repay)
    return repay


def bond_sell_buy_rate_ratio(sell_volume: float, buy_volume: float) -> float:
    """매도/매수 주문량 비율(클램프 없음). 매도 > 매수 → 금리 상승.

    매수≈0으로 분모가 터지는 경우만 최소 안전장치(ε)를 둔다.
    """
    if buy_volume <= 1e-9 and sell_volume <= 1e-9:
        return 1.0
    return sell_volume / max(buy_volume, 1e-9)


