def country_repo_stance(country: Optional["Country"]) -> str:
    """국가(중앙은행) 레포시장 개입 스탠스: intervene(개입) | none(방임).

    구버전 strong/moderate/call_stance 값은 intervene(개입)으로 정규화해 수용한다.
    """
    stance = getattr(country, "repo_stance", None)
    if stance is None:
        stance = getattr(country, "call_stance", DEFAULT_REPO_STANCE)
    stance = str(stance or DEFAULT_REPO_STANCE)
    if stance in ("strong", "moderate", "intervene"):
        return "intervene"
    if stance == "none":
        return "none"
    return "intervene"


def country_repo_band_halfwidth(country: Optional["Country"]) -> float:
    """방임 시 기대금리 스케일용 반폭(%p). 개입 레포금리는 기준금리에 고정한다."""
    stance = country_repo_stance(country)
    if stance == "none":
        return REPO_STANCE_NONE_HALFWIDTH
    hw_raw = getattr(country, "repo_band_halfwidth", None)
    if hw_raw is None:
        hw_raw = getattr(country, "call_band_halfwidth", REPO_STANCE_MODERATE_HALFWIDTH)
    try:
        hw = float(hw_raw)
    except (TypeError, ValueError):
        hw = REPO_STANCE_MODERATE_HALFWIDTH
    return clamp(hw, REPO_STANCE_STRONG_HALFWIDTH, REPO_STANCE_MODERATE_HALFWIDTH)


# 하위호환 별칭 — 기존 콜 스탠스 API가 레포 스탠스를 가리키도록 위임
def country_call_stance(country: Optional["Country"]) -> str:
    return country_repo_stance(country)


def country_call_band_halfwidth(country: Optional["Country"]) -> float:
    return country_repo_band_halfwidth(country)


def pin_repo_rate_to_base_if_intervening(world: Optional["World"], country: Optional["Country"]) -> None:
    """개입 중이면 레포 체결금리를 기준금리와 같게 둔다."""
    if world is None or country is None:
        return
    if country_repo_stance(country) != "intervene":
        return
    markets = getattr(world, "repo_markets", None) or {}
    market = markets.get(getattr(country, "id", ""))
    if market is None:
        return
    rate = clamp_market_rate(country_base_rate(country))
    market.current_repo_rate = rate
    market.last_floor = rate
    market.last_ceiling = rate


def country_reserve_requirement_ratio(country: Optional["Country"]) -> float:
    """국가 지급준비금 비율 (0~MAX)."""
    if country is None:
        return DEFAULT_RESERVE_REQUIREMENT_RATIO
    try:
        ratio = float(getattr(
            country, "reserve_requirement_ratio", DEFAULT_RESERVE_REQUIREMENT_RATIO))
    except (TypeError, ValueError):
        return DEFAULT_RESERVE_REQUIREMENT_RATIO
    if not math.isfinite(ratio):
        return DEFAULT_RESERVE_REQUIREMENT_RATIO
    return clamp(ratio, 0.0, MAX_RESERVE_REQUIREMENT_RATIO)


def format_reserve_requirement_label(ratio: float) -> str:
    """지급준비금 비율 표시 문자열."""
    try:
        r = float(ratio)
    except (TypeError, ValueError):
        r = DEFAULT_RESERVE_REQUIREMENT_RATIO
    if not math.isfinite(r):
        r = DEFAULT_RESERVE_REQUIREMENT_RATIO
    return f"{clamp(r, 0.0, MAX_RESERVE_REQUIREMENT_RATIO) * 100.0:,.1f}%"


def financial_leverage_pct_to_equity_ratio_pct(leverage_pct: float) -> float:
    """loan/equity×100 → 자기자본비율(%). 10배(1000) → 10%.

    대출이 자기자본보다 작으면(1배 미만) 비율이 100%를 넘지 않도록 상한.
    (미소 대출 시 10000/ε → 수십만 %로 폭주하던 표시 오류 방지)
    """
    try:
        lev = float(leverage_pct)
    except (TypeError, ValueError):
        return 100.0
    if not math.isfinite(lev):
        return 0.0
    if lev < 0:
        return 0.0
    if lev <= 0:
        return 100.0
    return min(100.0, 10000.0 / lev)


def equity_ratio_pct_to_financial_leverage_pct(equity_ratio_pct: float) -> float:
    """자기자본비율(%) → loan/equity×100 저장값."""
    try:
        ratio = float(equity_ratio_pct)
    except (TypeError, ValueError):
        return 0.0
    if ratio <= 0:
        return 0.0
    return 10000.0 / ratio


def financial_leverage_multiple(leverage_pct: float) -> float:
    """저장값(loan/equity×100) → 배수."""
    try:
        return max(0.0, float(leverage_pct or 0.0) / 100.0)
    except (TypeError, ValueError):
        return 0.0


def format_equity_capital_ratio_label(leverage_pct: float) -> str:
    """규제·현황 표시용 자기자본비율 문자열."""
    try:
        lev = float(leverage_pct)
    except (TypeError, ValueError):
        return "—"
    if not math.isfinite(lev):
        return "0%"
    if lev < 0:
        return "0%"
    if lev <= 0:
        return "100%"
    return f"{financial_leverage_pct_to_equity_ratio_pct(lev):,.1f}%"


