def _sync_public_output_qty() -> None:
    """시장 산출량을 단계당 capacity와 비례하게 맞춘다."""
    for service, ratio in PUBLIC_OUTPUT_PER_CAPACITY.items():
        cap = float(PUBLIC_SERVICE_SPECS.get(service, {}).get("capacity", 0.0) or 0.0)
        if service in PUBLIC_OPERATION_SPECS and cap > 1e-12:
            PUBLIC_OPERATION_SPECS[service]["output_qty"] = cap * float(ratio)


_sync_public_output_qty()


def public_required_capacities(
    population: float,
    children: float,
    seniors: float,
    facility_stock: float,
    public_count: int,
    *,
    coastal: bool = False,
    trade_ema: Optional[Dict[str, float]] = None,
) -> Dict[str, float]:
    """주 공공 필요 역량 (유효용량 단위). 도로·항구·철도는 무역 EMA를 포함한다."""
    pop = max(0.0, float(population) or 0.0)
    child = max(0.0, float(children) or 0.0)
    sen = max(0.0, float(seniors) or 0.0)
    stock = max(0.0, float(facility_stock) or 0.0)
    pubs = max(0, int(public_count or 0))
    ema = trade_ema or {}
    gain = float(TRADE_INFRA_FEEDBACK_GAIN)
    road = max(
        PUBLIC_DEMAND_ROAD_FLOOR,
        pop / PUBLIC_DEMAND_ROAD_POP_DIV + stock * PUBLIC_DEMAND_ROAD_STOCK,
    ) + gain * float(ema.get("road", 0.0) or 0.0)
    if coastal:
        port = max(
            PUBLIC_DEMAND_PORT_FLOOR,
            pop / PUBLIC_DEMAND_PORT_POP_DIV,
        ) + gain * float(ema.get("port", 0.0) or 0.0)
    else:
        port = 0.0
    rail = max(
        PUBLIC_DEMAND_RAIL_FLOOR,
        pop / PUBLIC_DEMAND_RAIL_POP_DIV + stock * PUBLIC_DEMAND_RAIL_STOCK,
    ) + gain * float(ema.get("rail", 0.0) or 0.0)
    return {
        "fire": pop / PUBLIC_DEMAND_FIRE_POP_DIV + stock * PUBLIC_DEMAND_FIRE_STOCK,
        "police": pop / PUBLIC_DEMAND_POLICE_POP_DIV + stock * PUBLIC_DEMAND_POLICE_STOCK,
        "medical": (
            pop / PUBLIC_DEMAND_MEDICAL_POP_DIV
            + (child + sen) / PUBLIC_DEMAND_MEDICAL_DEP_DIV),
        "basic_edu": child * PUBLIC_DEMAND_BASIC_EDU_PER_CHILD,
        "high_edu": child * PUBLIC_DEMAND_HIGH_EDU_PER_CHILD,
        "admin": pop / PUBLIC_DEMAND_ADMIN_POP_DIV + pubs * PUBLIC_DEMAND_ADMIN_PUBLIC,
        "road": road,
        "port": port,
        "rail": rail,
    }


def state_youth_total(state: "State") -> float:
    total = 0.0
    for p in getattr(state, "pops", None) or []:
        youth = float(getattr(p, "youth", 0.0) or 0.0)
        if youth <= 1e-12:
            cq = getattr(p, "children_queue", None) or []
            youth = float(sum(cq)) if cq else 0.0
        total += youth
    return total


def state_private_facility_stock(world: Optional["World"], state_id: str) -> float:
    """본사가 그 주인 기업 시설의 가동 단계 합 (산업 스톡)."""
    if world is None:
        return 0.0
    total = 0.0
    sid = str(state_id)
    for co in getattr(world, "companies", {}).values():
        if str(getattr(co, "home_state", "") or "") != sid:
            continue
        for fac in getattr(co, "facilities", None) or []:
            if hasattr(fac, "active_levels"):
                total += float(fac.active_levels())
            else:
                lvl = float(getattr(fac, "level", 0) or 0)
                closed = float(getattr(fac, "closed_levels", 0) or 0)
                total += max(0.0, lvl - closed)
    return total

