def _scale_spec_labor_qty(specs: Dict[str, Dict], scale: float) -> None:
    for spec in specs.values():
        labor = spec.get("labor")
        if not labor or not isinstance(labor, (tuple, list)) or len(labor) < 2:
            continue
        spec["labor"] = (labor[0], round(float(labor[1]) * float(scale), 4))


_scale_spec_labor_qty(FACILITY_SPECS, FACILITY_LABOR_QTY_SCALE)
