def public_operation_efficiency(service: str, *, central: bool = False, country: Any = None) -> float:
    """공공·중앙 시설 운영 효율 — 동일 노동으로 더 많은 서비스·용량 (기업 efficiency와 동일 역할)."""
    specs = CENTRAL_OPERATION_SPECS if central else PUBLIC_OPERATION_SPECS
    op = specs.get(service, {})
    return max(1.0, float(op.get("efficiency", 1.0) or 1.0))


def central_operation_efficiency(service: str) -> float:
    return public_operation_efficiency(service, central=True)


