def default_regional_sector_weights() -> Dict[str, float]:
    n = max(1, len(REGIONAL_INVESTMENT_SECTORS))
    return {k: 1.0 / n for k in REGIONAL_INVESTMENT_SECTORS}


def normalize_regional_sector_weights(raw: Optional[Dict[str, float]] = None) -> Dict[str, float]:
    weights = default_regional_sector_weights()
    if raw:
        for key in REGIONAL_INVESTMENT_SECTORS:
            try:
                weights[key] = max(0.0, float(raw.get(key, weights[key]) or 0.0))
            except (TypeError, ValueError):
                pass
    total = sum(weights.values())
    if total <= 1e-12:
        return default_regional_sector_weights()
    return {k: v / total for k, v in weights.items()}


def ensure_country_regional_investment(country: Optional["Country"]) -> None:
    if country is None:
        return
    if not getattr(country, "regional_invest_stance", None):
        country.regional_invest_stance = "balanced"
    if country.regional_invest_stance not in REGIONAL_INVESTMENT_STANCES:
        country.regional_invest_stance = "balanced"
    country.regional_invest_auto = bool(getattr(country, "regional_invest_auto", True))
    country.regional_ops_auto = bool(getattr(country, "regional_ops_auto", True))
    country.regional_invest_budget = max(
        0.0, float(getattr(country, "regional_invest_budget", 0.0) or 0.0))
    country.regional_ops_budget = max(
        0.0, float(getattr(country, "regional_ops_budget", 0.0) or 0.0))
    country.regional_invest_tax_pct = max(0.0, min(80.0, float(
        getattr(country, "regional_invest_tax_pct", REGIONAL_DEFAULT_TAX_PCT)
        or REGIONAL_DEFAULT_TAX_PCT)))
    country.regional_sector_weights = normalize_regional_sector_weights(
        getattr(country, "regional_sector_weights", None))
    focus = list(getattr(country, "regional_focus_states", None) or [])
    country.regional_focus_states = [str(x) for x in focus if x][:REGIONAL_MAX_FOCUS_STATES]
    frozen = list(getattr(country, "regional_frozen_states", None) or [])
    country.regional_frozen_states = [str(x) for x in frozen if x]
    country.regional_review_weeks = max(
        1, int(getattr(country, "regional_review_weeks", REGIONAL_REVIEW_WEEKS)
               or REGIONAL_REVIEW_WEEKS))
    country.regional_weeks_since_review = max(
        0, int(getattr(country, "regional_weeks_since_review", 0) or 0))
    if not isinstance(getattr(country, "regional_last_outcome", None), dict):
        country.regional_last_outcome = {}
    if not isinstance(getattr(country, "regional_queue", None), list):
        country.regional_queue = []
    if not isinstance(getattr(country, "regional_alerts", None), list):
        country.regional_alerts = []
    country.regional_invest_remaining = max(
        0.0, float(getattr(country, "regional_invest_remaining", 0.0) or 0.0))
    country.regional_ops_remaining = max(
        0.0, float(getattr(country, "regional_ops_remaining", 0.0) or 0.0))
    country.weekly_regional_invest_spent = max(
        0.0, float(getattr(country, "weekly_regional_invest_spent", 0.0) or 0.0))
    country.weekly_regional_ops_spent = max(
        0.0, float(getattr(country, "weekly_regional_ops_spent", 0.0) or 0.0))
    country.local_share = 0.0


def country_regional_invest_budget_amount(country: "Country") -> float:
    ensure_country_regional_investment(country)
    if getattr(country, "regional_invest_auto", True):
        tax = float(getattr(country, "weekly_tax_revenue", 0.0) or 0.0)
        if tax <= 1e-9:
            tax = float(getattr(country, "last_weekly_tax_revenue", 0.0) or 0.0)
        amount = max(0.0, tax * float(country.regional_invest_tax_pct) / 100.0)
        if amount <= 1e-9:
            amount = max(0.0, float(getattr(country, "treasury", 0.0) or 0.0) * 0.05)
        return amount
    return max(0.0, float(country.regional_invest_budget or 0.0))


def country_charge_regional(
    country: "Country",
    label: str,
    amount: float,
    *,
    kind: str = "ops",
) -> float:
    amt = max(0.0, float(amount or 0.0))
    if amt <= 1e-12 or country is None:
        return 0.0
    treasury = max(0.0, float(getattr(country, "treasury", 0.0) or 0.0))
    paid = min(amt, treasury)
    if paid <= 1e-12:
        return 0.0
    country.treasury = treasury - paid
    gov_record_subsidy(country, label, paid)
    if kind == "invest":
        country.weekly_regional_invest_spent = (
            float(getattr(country, "weekly_regional_invest_spent", 0.0) or 0.0) + paid)
    else:
        country.weekly_regional_ops_spent = (
            float(getattr(country, "weekly_regional_ops_spent", 0.0) or 0.0) + paid)
    return paid


def regional_construction_market_tight(world: "World", state_id: str) -> bool:
    mk = world.markets.get(market_key(state_id, "건설 서비스"))
    if mk is None:
        return False
    sd = float(getattr(mk, "last_supply_demand_ratio", 1.0) or 1.0)
    return sd >= REGIONAL_CONSTRUCTION_TIGHT_SD


