def clamp(v: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, v))


def clamp_stock_price(price: float) -> float:
    try:
        v = float(price)
    except (TypeError, ValueError):
        v = 0.0
    if not math.isfinite(v):
        v = 0.0
    return round(max(STOCK_PRICE_MIN, v), FINANCE_PRICE_DECIMALS)


def clamp_bond_rate(rate: float) -> float:
    """채권 금리 — 계산은 소수점 4자리."""
    return round(clamp_market_rate(rate), FINANCE_PRICE_DECIMALS)


def clamp_base_rate(rate: float) -> float:
    try:
        v = float(rate)
    except (TypeError, ValueError):
        v = 0.0
    if not math.isfinite(v):
        v = 0.0
    return clamp(v, BASE_RATE_MIN, RATE_MAX)


def clamp_market_rate(rate: float, hi: float = RATE_MAX) -> float:
    try:
        v = float(rate)
    except (TypeError, ValueError):
        v = 0.0
    if not math.isfinite(v):
        v = 0.0
    return clamp(v, RATE_MIN, hi)


def country_base_rate(country: Optional["Country"], default: float = 3.5) -> float:
    """국가 기준금리(%). 0%는 유효 값이므로 `or 3.5`로 덮지 않는다."""
    if country is None:
        return clamp_base_rate(default)
    raw = getattr(country, "base_rate", None)
    if raw is None:
        return clamp_base_rate(default)
    return clamp_base_rate(raw)


def pin_warmup_base_rates(world: Optional["World"]) -> None:
    """워밍업 동안 모든 국가 기준금리를 WARMUP_FIXED_BASE_RATE로 고정."""
    if world is None:
        return
    rate = clamp_base_rate(WARMUP_FIXED_BASE_RATE)
    for country in (getattr(world, "countries", None) or {}).values():
        country.base_rate = rate
        pin_repo_rate_to_base_if_intervening(world, country)
        country.trend_weeks = 0


def ib_clip_z(value: float, lo: float = -IB_Z_CLIP, hi: float = IB_Z_CLIP) -> float:
    """표준화 점수 클램프 (−2~+2)."""
    try:
        v = float(value)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(v):
        return 0.0
    return clamp(v, lo, hi)


def _ib_finite(v: Any) -> bool:
    try:
        return math.isfinite(float(v))
    except (TypeError, ValueError):
        return False


def ib_cs_zscore(
    values: Dict[str, float], *, clip: float = IB_Z_CLIP,
) -> Dict[str, float]:
    """교차단면 z-score. 표본 1개·분산 0이면 0."""
    if not values:
        return {}
    xs = []
    for v in values.values():
        try:
            x = float(v)
        except (TypeError, ValueError):
            x = 0.0
        if not math.isfinite(x):
            x = 0.0
        xs.append(x)
    n = len(xs)
    if n <= 1:
        return {k: 0.0 for k in values}
    mean = sum(xs) / n
    var = sum((x - mean) ** 2 for x in xs) / float(n - 1)
    sd = math.sqrt(var) if var > 1e-18 else 0.0
    if sd <= 1e-12:
        return {k: 0.0 for k in values}
    lo, hi = -abs(clip), abs(clip)
    out: Dict[str, float] = {}
    for k, v in values.items():
        x = float(v) if _ib_finite(v) else 0.0
        out[k] = ib_clip_z((x - mean) / sd, lo, hi)
    return out


def ib_scale_then_clip(
    value: float, typical: float, *, clip: float = IB_Z_CLIP,
) -> float:
    """이력 부족 시 x/typical 후 clip."""
    t = max(abs(float(typical or 0.0)), 1e-9)
    return ib_clip_z(float(value or 0.0) / t, -abs(clip), abs(clip))


def ib_rolling_zscore(
    history: Optional[Sequence[float]],
    spot: float,
    *,
    typical: float = 1.0,
    weeks: int = 52,
    clip: float = IB_Z_CLIP,
) -> float:
    """롤링 z. 표본 부족이면 typical 스케일."""
    xs = []
    for v in (history or []):
        try:
            x = float(v)
        except (TypeError, ValueError):
            continue
        if math.isfinite(x):
            xs.append(x)
    xs = xs[-max(1, int(weeks)):]
    try:
        s = float(spot)
    except (TypeError, ValueError):
        s = 0.0
    if not math.isfinite(s):
        s = 0.0
    if len(xs) < 4:
        return ib_scale_then_clip(s, typical, clip=clip)
    mean = sum(xs) / len(xs)
    var = sum((x - mean) ** 2 for x in xs) / float(len(xs) - 1)
    sd = math.sqrt(var) if var > 1e-18 else 0.0
    if sd <= 1e-12:
        return 0.0
    return ib_clip_z((s - mean) / sd, -abs(clip), abs(clip))


def ib_dcf_growth_path(
    g_forecast: float,
    g_normal: float,
    *,
    years: int = IB_DCF_YEARS,
) -> List[float]:
    """1–3년 forecast, 4–7년 선형 정상화, 8–N년 g_normal."""
    n = max(1, int(years))
    gf = float(g_forecast)
    gn = float(g_normal)
    out: List[float] = []
    for t in range(1, n + 1):
        if t <= 3:
            g = gf
        elif t <= 7:
            g = gf - (gf - gn) * ((t - 3) / 4.0)
        else:
            g = gn
        out.append(g)
    return out


def ib_dcf_equity_value(
    fcf0: float,
    r_e: float,
    growths: Sequence[float],
    g_terminal: float,
) -> float:
    """명시적 구간 FCF 할인 + Gordon TV. FCF≤0 또는 r_e≤0이면 0."""
    f0 = float(fcf0 or 0.0)
    re = float(r_e or 0.0)
    if f0 <= 1e-9 or re <= 1e-9:
        return 0.0
    gs = [float(g) for g in (growths or [])]
    if not gs:
        return 0.0
    pv = 0.0
    fcf = f0
    n = len(gs)
    for t, g in enumerate(gs, start=1):
        fcf *= (1.0 + g)
        pv += fcf / ((1.0 + re) ** t)
    g_t = min(float(g_terminal), re - 0.005)
    tv_fcf = fcf * (1.0 + g_t)
    tv = tv_fcf / max(re - g_t, 0.005)
    pv += tv / ((1.0 + re) ** n)
    return max(0.0, pv)


def ib_annualized_capital_gain(fv: float, price: float, years: float) -> float:
    """(FV/P)^(1/N) − 1."""
    p = float(price or 0.0)
    v = float(fv or 0.0)
    n = float(years or 0.0)
    if p <= 1e-9 or v <= 1e-9 or n <= 1e-9:
        return 0.0
    return max(v / p, 1e-9) ** (1.0 / n) - 1.0


def ib_expected_fv_scenarios(fv_base: float) -> float:
    """비대칭 3시나리오 E[FV] — bear 20% / base 60% / bull 20%."""
    base = max(0.0, float(fv_base or 0.0))
    return 0.20 * base * 0.78 + 0.60 * base + 0.20 * base * 1.22


def ib_corp_adj_spread_edge(
    edge: float,
    credit_score: float,
    duration: float,
    vol: float,
) -> float:
    """Spread−Fair를 신용·듀레이션·변동성으로 나눈 표준화 전 엣지."""
    cs = clamp(float(credit_score or 50.0) / 100.0, 0.05, 1.0)
    credit_w = 0.70 + (1.0 - cs) * 1.10
    dur_w = max(float(duration or 0.0), 0.30)
    vol_w = max(float(vol or 0.0), 0.25)
    return float(edge or 0.0) / (credit_w * dur_w * vol_w)


def ib_sleeve_score_combine(
    z_val: float, z_er: float, macro: float, z_risk: float,
) -> float:
    """자산군 점수. 입력은 이미 −2~+2 (매크로 포함)."""
    return (
        IB_SCORE_W_MOS * float(z_val)
        + IB_SCORE_W_ER * float(z_er)
        + IB_SCORE_W_MACRO * float(macro)
        - IB_SCORE_W_RISK * float(z_risk)
    )


def ib_name_score_combine(
    z_mos: float, z_erg: float, z_erc: float, macro: float, z_risk: float,
    z_mom: float = 0.0,
    weights: Optional[Dict[str, float]] = None,
) -> float:
    w = weights or {}
    w_mos = float(w.get("mos", IB_NAME_W_MOS))
    w_erg = float(w.get("erg", IB_NAME_W_ERG))
    w_erc = float(w.get("erc", IB_NAME_W_ERC))
    w_macro = float(w.get("macro", IB_NAME_W_MACRO))
    w_risk = float(w.get("risk", IB_NAME_W_RISK))
    w_mom = float(w.get("mom", 0.0))
    return (
        w_mos * float(z_mos)
        + w_erg * float(z_erg)
        + w_erc * float(z_erc)
        + w_macro * float(macro)
        - w_risk * float(z_risk)
        + w_mom * float(z_mom)
    )


def ib_legacy_attraction_from_score(score: float) -> float:
    """z결합 점수 → 기존 [0.01, 4] attraction 스케일 (게이트·질량 호환)."""
    return max(0.01, clamp(1.0 + float(score or 0.0), 0.01, 4.0))


def ib_weight_gap_flow_mult(
    target: float,
    current: float,
    *,
    deadband: float = IB_PORTFOLIO_REBALANCE_DEADBAND,
) -> float:
    """목표−현재 괴리율 → 주간 유량 배율 (0.5~1.5)."""
    scale = max(abs(float(target or 0.0)), abs(float(current or 0.0)), 1.0)
    gap = abs(float(target or 0.0) - float(current or 0.0)) / scale
    db = max(float(deadband or 0.0), 0.0)
    if gap <= db + 1e-12:
        return IB_GAP_FLOW_MIN_MULT
    t = clamp((gap - db) / 0.25, 0.0, 1.0)
    return IB_GAP_FLOW_MIN_MULT + t * (IB_GAP_FLOW_MAX_MULT - IB_GAP_FLOW_MIN_MULT)


def ib_bond_is_gov_sleeve(market_key: str) -> bool:
    key = str(market_key or "")
    return key.startswith("gov_") or key.startswith("local_")


def labor_output_factor(labor_ratio: float) -> float:
    """노동 충족률 → 산출 계수. 제곱근 한계체감(50% 인력 ≈ 70.7% 산출)."""
    return math.sqrt(clamp(float(labor_ratio), 0.0, 1.0))


def labor_overtime_multiplier(wage_premium: float, headcount_ratio: float) -> float:
    """인원 부족일 때만 임금 프리미엄으로 초과근무 배수. 충분하면 1.0.

    프리미엄 +40% → 약 1.25배, 상한 LABOR_OT_MAX (체감 곡선).
    """
    hc = clamp(float(headcount_ratio), 0.0, 1.0)
    if hc >= 1.0 - 1e-12:
        return 1.0
    extra = max(0.0, float(wage_premium) - 1.0)
    if extra <= 1e-12:
        return 1.0
    boost = (LABOR_OT_MAX - 1.0) * extra / (extra + LABOR_OT_PREMIUM_K)
    return 1.0 + boost


def effective_labor_ratio(
    headcount_ratio: float,
    wage_premium: float = 1.0,
) -> Tuple[float, float]:
    """(유효 노동비율, 초과근무 배수). 부족 시 풀가동(1.0)은 못 채움."""
    hc = clamp(float(headcount_ratio), 0.0, 1.0)
    ot = labor_overtime_multiplier(wage_premium, hc)
    if hc >= 1.0 - 1e-12:
        return 1.0, 1.0
    raw = hc * ot
    cap = max(LABOR_OT_EFFECTIVE_CAP, hc)
    return clamp(min(raw, cap), 0.0, 1.0), ot


def company_labor_wage_premium(
    company: "Company",
    state_id: str,
    labor_type: str,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
) -> float:
    """임금 offer / 마진 기준 기본급. 부족·수급비가 반영된 배수."""
    needed = company_labor_market_total_needed(company, state_id, labor_type)
    employed = float(
        (getattr(company, "last_labor_filled", {}) or {}).get(
            market_key(state_id, labor_type), 0.0) or 0.0)
    if employed <= 1e-9:
        # 미채용 상태에서는 부족 프리미엄 최댓값으로 구인 신호를 키운다.
        lo, hi = LABOR_EMPLOYMENT_RATIO_CLAMP
        emp_ratio = float(hi)
    else:
        lo, hi = LABOR_EMPLOYMENT_RATIO_CLAMP
        emp_ratio = clamp(needed / employed, float(lo), float(hi))
    sd_ratio = 1.0
    lms = labor_markets
    if lms is None:
        world_ref = getattr(company, "_world_ref", None)
        lms = getattr(world_ref, "labor_markets", None) if world_ref is not None else None
    if lms is not None:
        lm = lms.get(market_key(state_id, labor_type))
        if lm is not None:
            sd_ratio = float(getattr(lm, "last_supply_demand_ratio", 1.0) or 1.0)
            if sd_ratio <= 1e-9:
                sd_ratio = 1.0
    return max(0.0, emp_ratio * sd_ratio)


def facility_effective_labor_scale(
    fac: "Facility",
    company: Optional["Company"] = None,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
) -> float:
    """원자재·산출용 유효 노동비율. 회사 있으면 인원×초과근무로 재계산."""
    spec = FACILITY_SPECS.get(getattr(fac, "name", ""), {})
    if not spec.get("labor"):
        return 1.0
    hc = clamp(float(getattr(fac, "last_labor_ratio", 1.0) or 0.0), 0.0, 1.0)
    if company is not None:
        ltype = str(spec["labor"][0])
        premium = company_labor_wage_premium(
            company, fac.state_id, ltype, labor_markets)
        eff, _ot = effective_labor_ratio(hc, premium)
        return eff
    stored = getattr(fac, "last_effective_labor_ratio", None)
    if stored is not None:
        return clamp(float(stored or 0.0), 0.0, 1.0)
    return hc


def wma(values: List[float]) -> float:
    if not values:
        return 0.0
    weights = list(range(1, len(values) + 1))
    return sum(v * w for v, w in zip(values, weights)) / sum(weights)


# 주식 밸류에이션용 순이익 연환산 주수 (최근 N주 합 = 연간)
ANNUAL_NET_INCOME_WEEKS = 52
# GDP 주간 유량 이력: 최근 1년 합 vs 직전 1년 합 YoY용 (52+52)
GDP_YOY_YEAR_WEEKS = 52
GDP_HISTORY_MAX_WEEKS = GDP_YOY_YEAR_WEEKS * 2
# 생산법 GDP 구성 (부가가치 + 생산물세 순액)
GDP_PROD_FACTORS: Tuple[Tuple[str, str, str], ...] = (
    ("value_added_corp", "기업 부가가치", "#818cf8"),
    ("value_added_self", "자영 부가가치", "#38bdf8"),
    ("value_added_gov", "공공 부가가치", "#34d399"),
    ("value_added_fin", "금융 부가가치", "#f59e0b"),
    ("product_taxes_net", "생산물세 순액", "#f472b6"),
)
GDP_PROD_FACTOR_KEYS: Tuple[str, ...] = tuple(k for k, _label, _color in GDP_PROD_FACTORS)


def annual_net_income_from_weekly_history(
    history: Optional[Sequence[float]],
    *,
    fallback_weekly: float = 0.0,
    weeks: int = ANNUAL_NET_INCOME_WEEKS,
) -> float:
    """주간 순이익 이력 → 연환산 순이익.

    - 최근 ``weeks``주가 모두 있으면 합계.
    - 부족하면(또는 비어 있으면) 가용 표본의 최근 가중평균(WMA)×weeks.
      이력이 비면 ``fallback_weekly`` 한 주를 WMA 표본으로 쓴다.
    """
    hist = [float(v or 0.0) for v in (history or [])]
    recent = hist[-weeks:] if hist else []
    if len(recent) >= weeks:
        return float(sum(recent))
    sample = recent if recent else [float(fallback_weekly or 0.0)]
    return float(wma(sample) * weeks)


def portfolio_macro_weights_wma(
    history: Optional[deque],
    spot: Dict[str, float],
    *,
    weeks: int = PORTFOLIO_TARGET_WMA_WEEKS,
    record: bool = False,
    week: Optional[int] = None,
    recorded_week: Optional[int] = None,
) -> Tuple[Dict[str, float], int, Optional[int]]:
    """매크로 목표 비중의 최근 N주 가중이동평균.

    Returns:
        (최종비중, 표본수, 기록된 주 번호)
    history에는 과거 주간 스팟만 둡니다. 이번 주가 아직 미기록이면 spot을
    마지막 표본으로 포함하고, 이미 기록됐으면 history 마지막을 이번 주로 봅니다.
    """
    keys = [k for k in spot.keys()]
    past = list(history) if history is not None else []
    same_week = (
        week is not None
        and recorded_week is not None
        and week == recorded_week
        and bool(past)
    )
    if same_week:
        samples = past[-weeks:]
        # 조회 시에도 최신 스팟으로 이번 주 표본을 갱신해 표시·주문 일관성 유지
        samples = list(samples)
        samples[-1] = spot
    else:
        samples = past[-(max(weeks - 1, 0)):] + [spot]
        samples = samples[-weeks:]
    out = {
        k: wma([float(s.get(k, 0.0) or 0.0) for s in samples])
        for k in keys
    }
    total = sum(out.values())
    if total > 1e-9:
        out = {k: v / total for k, v in out.items()}
    new_recorded = recorded_week
    if record and history is not None:
        entry = {k: float(spot.get(k, 0.0) or 0.0) for k in keys}
        if same_week:
            history[-1] = entry
        else:
            history.append(entry)
        new_recorded = week if week is not None else recorded_week
    return out, len(samples), new_recorded


def market_supply_demand_ratio(
    total_demand: float,
    total_supply: float,
    base_volume: float,
    *,
    supply_weighted: bool = False,
) -> float:
    """수급 비율 S. supply_weighted=True면 (공급+Base)/(수요+Base) — 채권 금리 방향."""
    if supply_weighted:
        numerator = total_supply + base_volume
        denominator = total_demand + base_volume
    else:
        numerator = total_demand + base_volume
        denominator = total_supply + base_volume
    return numerator / max(denominator, 1e-9)


def supply_demand_ratio_wow_change(current_s: float, prior_s: Optional[float]) -> float:
    """전주 대비 수급 비율 변동률 (S_t - S_{t-1}) / S_{t-1}."""
    baseline = prior_s if prior_s is not None and prior_s > 1e-9 else 1.0
    return (current_s - baseline) / baseline


def market_sd_wow_change(
    market: Any,
    total_demand: float,
    total_supply: float,
    *,
    supply_weighted: bool = False,
) -> float:
    """전주 대비 수급비 변화율을 반환하고 last_supply_demand_ratio를 갱신.

    비율이 고정이면 0 — 절대 편차로 인한 영구 시세 드리프트를 막는다.
    첫 주(이력이 없으면) wow=0.
    """
    current_s = market_supply_demand_ratio(
        total_demand,
        total_supply,
        float(getattr(market, "base_volume", 0.0) or 0.0),
        supply_weighted=supply_weighted,
    )
    prior_s = getattr(market, "last_supply_demand_ratio", None)
    if prior_s is None or float(prior_s) <= 1e-9:
        wow = 0.0
    else:
        wow = supply_demand_ratio_wow_change(current_s, float(prior_s))
    market.last_supply_demand_ratio = current_s
    return wow


def market_sd_target_mult(
    sd_ratio: float,
    *,
    gamma: float = GOODS_PRICE_SD_GAMMA,
    t_min: float = GOODS_PRICE_SD_T_MIN,
    t_max: float = GOODS_PRICE_SD_T_MAX,
) -> float:
    """수급비 S → 목표 시세 배수 T(S). S=1이면 T=1."""
    s = max(float(sd_ratio or 0.0), 1e-9)
    return clamp(s ** max(0.0, float(gamma)), float(t_min), float(t_max))


def market_sd_gap_adjustment(
    market: Any,
    total_demand: float,
    total_supply: float,
    p_now: float,
    p_ref: float,
    *,
    supply_weighted: bool = False,
    gamma: float = GOODS_PRICE_SD_GAMMA,
    t_min: float = GOODS_PRICE_SD_T_MIN,
    t_max: float = GOODS_PRICE_SD_T_MAX,
    gap_lambda: float = GOODS_PRICE_GAP_LAMBDA,
    wow_lambda: float = GOODS_PRICE_WOW_LAMBDA,
    p_star_override: Optional[float] = None,
) -> float:
    """목표시세 갭 수렴 + 소량 wow → 주간 상대 변화율 Δ.

    S 고정이고 P≈P*이면 Δ≈0. S 고정·P≪P*이면 수주에 걸쳐 수렴 후 정지.
    """
    wow = market_sd_wow_change(
        market, total_demand, total_supply, supply_weighted=supply_weighted)
    current_s = float(getattr(market, "last_supply_demand_ratio", 1.0) or 1.0)
    t_mult = market_sd_target_mult(
        current_s, gamma=gamma, t_min=t_min, t_max=t_max)
    pref = max(float(p_ref or 0.0), 1e-9)
    if p_star_override is not None and float(p_star_override) > 1e-12:
        p_star = float(p_star_override)
    else:
        p_star = pref * t_mult
    p0 = max(float(p_now or 0.0), 1e-9)
    gap = p_star / p0 - 1.0
    return float(gap_lambda) * gap + float(wow_lambda) * wow


def interpolate_sol_birth_rate(sol: float) -> float:
    sol = clamp(sol, 1.0, 10.0)
    lo = int(math.floor(sol))
    hi = int(math.ceil(sol))
    if lo == hi:
        return BIRTH_RATE_BY_SOL[lo]
    t = sol - lo
    return BIRTH_RATE_BY_SOL[lo] * (1 - t) + BIRTH_RATE_BY_SOL[hi] * t


def pop_weekly_birth_rate(
    sol: float, edu_shares: Dict[str, float], health: float,
) -> float:
    """가임 코호트 주간 출산률. SoL × 학력보정 × 의료(바닥 있음)."""
    base_br = interpolate_sol_birth_rate(sol)
    edu_mod = 1.0 + pop_edu_shares_weighted_modifier(edu_shares)
    # 의료 0이어도 출산이 끊기지 않음. 의료는 주로 수명(사망)에 반영.
    health_birth = 0.55 + 0.45 * clamp(float(health), 0.0, 1.0)
    return max(0.0, base_br * edu_mod * health_birth)


def format_sol(sol: float) -> str:
    """Victoria 3 스타일 SoL 표기 (1.00~10.00, 소수 둘째 자리)."""
    return f"{clamp(sol, 1.0, 10.0):.2f}"


def _weeks_buffer_to_wealth_subscore(weeks: float, cap: float = 9.5) -> float:
    return clamp(
        1.0 + math.log1p(max(weeks, 0.0) / 4.0) / math.log1p(13.0) * 7.0,
        0.0, cap,
    )


def wealth_multiplier(wealth: float) -> float:
    if wealth < 10:
        return 1.0
    if wealth < 50:
        return 1.0 + (wealth - 10) / 40 * 1.5
    if wealth < 100:
        return 2.5 + (wealth - 50) / 50 * 2.5
    return 5.0


def income_consumption_multiplier(weekly_income: float, population: float) -> float:
    """전주 1인당 수입에 따른 소비 목표 배율."""
    if population <= 1e-9:
        return 1.0
    per_capita = weekly_income / population
    if per_capita < 10:
        return 0.75
    if per_capita < 50:
        return 0.75 + (per_capita - 10) / 40 * 1.0
    if per_capita < 150:
        return 1.75 + (per_capita - 50) / 100 * 1.75
    return 3.5


def pop_consumption_catchup_multiplier(
    essential_fulfillment: float,
    need_score: float,
) -> float:
    """지난주 욕구 미충족 시 이번 주 소비 목표 상향."""
    ef = clamp(float(essential_fulfillment or 1.0), 0.0, 1.0)
    ns = clamp(float(need_score or 10.0) / 10.0, 0.0, 1.0)
    shortfall = max(1.0 - ef, (1.0 - ns) * 0.85)
    return 1.0 + shortfall * POP_CONSUMPTION_CATCHUP_MAX


def pop_effective_mpc(essential_fulfillment: float) -> float:
    """필수 욕구가 부족할수록 소득을 소비에 우선 배분."""
    ef = clamp(float(essential_fulfillment or 1.0), 0.0, 1.0)
    if ef >= POP_INVEST_ESSENTIAL_GATE:
        return POP_MPC
    gate_ratio = ef / POP_INVEST_ESSENTIAL_GATE
    return POP_MPC_ESSENTIAL_FLOOR - (POP_MPC_ESSENTIAL_FLOOR - POP_MPC) * gate_ratio


def pop_calculus_realistic_budget(
    disposable_income: float,
    ideal_consumption: float,
    catch_up_mult: float,
    drawable_liquid: float,
    *,
    essential_fulfillment: float = 1.0,
) -> Tuple[float, float, float]:
    """가처분소득·미충족 보정 기반 (소비예산, 투자예산, 투자성향)."""
    disposable = max(0.0, disposable_income)
    ideal = max(0.0, ideal_consumption)
    catch_up = max(1.0, catch_up_mult)
    drawable = max(0.0, drawable_liquid)
    target = ideal * catch_up

    mpc = pop_effective_mpc(essential_fulfillment)
    income_consumption = disposable * mpc
    shortfall = max(0.0, target - income_consumption)
    wealth_draw = min(
        shortfall,
        drawable * POP_CONSUMPTION_WEALTH_DRAW_MAX_RATIO,
    )
    cons_budget = min(target, income_consumption + wealth_draw)

    savings_rate = max(POP_INVEST_MIN_SAVINGS_RATE, 1.0 - mpc)
    inv_budget = max(0.0, disposable * savings_rate)
    if cons_budget + inv_budget > disposable + wealth_draw + 1e-9:
        inv_budget = max(0.0, disposable + wealth_draw - cons_budget)

    if inv_budget <= 1e-9:
        propensity = 0.0
    else:
        propensity = clamp(
            0.25 + (inv_budget / max(disposable, 1.0)) * 0.45,
            0.10, 0.80,
        )
        ef = clamp(essential_fulfillment, 0.0, 1.0)
        if ef < POP_INVEST_ESSENTIAL_GATE:
            propensity *= ef / POP_INVEST_ESSENTIAL_GATE
    return cons_budget, inv_budget, propensity


def pop_surplus_invest_propensity(
    total_liquid: float,
    consumption_need: float,
) -> float:
    """레거시 호환 — 가처분소득 기반 투자 성향 근사."""
    if consumption_need <= 1e-9:
        return 0.0
    return clamp(
        POP_INVEST_MIN_SAVINGS_RATE,
        0.0,
        0.80,
    )


def pop_calculus_liquid_split(
    total_liquid: float,
    ideal_consumption: float,
) -> Tuple[float, float, float]:
    """레거시 호환 래퍼."""
    return pop_calculus_realistic_budget(
        max(0.0, ideal_consumption * POP_MPC),
        ideal_consumption,
        1.0,
        total_liquid,
    )


def pop_calculus_general_consumption_scale(essential_fulfillment: float) -> float:
    """필수 충족도 f → 일반 욕구 허용 비율. scale(f)=floor+(1−floor)·f, ∂scale/∂f=1−floor."""
    floor = POP_GENERAL_CONSUMPTION_FLOOR
    f = clamp(essential_fulfillment, 0.0, 1.0)
    return floor + (1.0 - floor) * f


def pop_calculus_essential_general_budget_split(
    budget: float,
    essential_cost: float,
    general_cost: float,
) -> Tuple[float, float, float]:
    """예산 B, 필수·일반 이상비용(e,g) → (필수예산, 일반예산, 필수충족도 f).
    일반 = g·scale(f), 필수 = e·f, B = e·f + g·(floor+(1−floor)·f) 선형 결합."""
    floor = POP_GENERAL_CONSUMPTION_FLOOR
    b = max(budget, 0.0)
    e = max(essential_cost, 0.0)
    g = max(general_cost, 0.0)
    if b <= 1e-9:
        return 0.0, 0.0, 0.0
    if e <= 1e-9:
        return 0.0, min(b, g), 1.0
    if g <= 1e-9:
        es = min(b, e)
        return es, 0.0, min(1.0, es / e)
    denom = e + g * (1.0 - floor)
    f = clamp((b - g * floor) / max(denom, 1e-9), 0.0, 1.0)
    essential_budget = f * e
    general_scale = pop_calculus_general_consumption_scale(f)
    general_budget = min(g * general_scale, max(0.0, b - essential_budget))
    return essential_budget, general_budget, f


def _pop_need_sort_key(need: Dict[str, Any]) -> Tuple[int, float]:
    name = need["name"]
    essential = 0 if name in POP_ESSENTIAL_NEEDS else 1
    priority = POP_NEED_PRIORITY.get(name, 1.0)
    return essential, -priority


def tech_level_bonus(tech_level: int) -> float:
    return 1.0 + (tech_level - 1) * 0.005


def debt_ratio_score(debt_ratio: float) -> float:
    return max(0.0, 1.0 - debt_ratio / 4.0)


def base_rate_score(base_rate: float) -> float:
    return clamp((30.0 - base_rate) / 29.0, 0.0, 1.0)


def country_market_rate_bias(country: Optional["Country"]) -> float:
    """국가 시장 기대 금리 편향 (−1~+1). 기대금리−기준금리에서 유도."""
    if country is None:
        return 0.0
    return clamp(float(getattr(country, "market_rate_bias", 0.0) or 0.0), -1.0, 1.0)


def country_market_expected_rate(country: Optional["Country"]) -> float:
    """시장이 가격하는 기대 기준금리(%)."""
    if country is None:
        return 3.5
    stored = getattr(country, "market_expected_rate", None)
    if stored is not None:
        return clamp_base_rate(stored)
    return country_base_rate(country)


def dovish_score_from_mrb(mrb: float) -> float:
    """MRB(+1 인상기대) → 구 RATE_TREND_SCORE 호환 비둘기파 점수(인하기=1)."""
    return clamp((1.0 - float(mrb)) * 0.5, 0.0, 1.0)


def country_dovish_score(country: Optional["Country"]) -> float:
    return dovish_score_from_mrb(country_market_rate_bias(country))


def market_rate_stance_label(mrb: float) -> str:
    """MRB → UI/리포트용 기대 기조 라벨."""
    v = float(mrb)
    if v > MRB_HOLD_BAND:
        return "인상 기대"
    if v < -MRB_HOLD_BAND:
        return "인하 기대"
    return "동결 기대"


def sync_country_rate_trend_label(country: "Country") -> str:
    """rate_trend를 시장 기대 라벨로 미러(쓰기 API 없이 표시용)."""
    label = market_rate_stance_label(country_market_rate_bias(country))
    country.rate_trend = label
    return label


def country_mrb_follow_base_rate(country: Optional["Country"]) -> bool:
    """시장 기대 기조로 기준금리를 자동 조정할지(기본 True)."""
    if country is None:
        return True
    return bool(getattr(country, "mrb_follow_base_rate", True))


def country_taylor_policy_rate(
    world: "World", country_id: str, inflation_yoy: Optional[float] = None,
) -> float:
    """간이 테일러 적정 기준금리(인플레 채널). 시행 가능한 0~30%로 자른다."""
    if inflation_yoy is None:
        inflation_yoy = country_composite_inflation_yoy(world, country_id)
    if inflation_yoy is None:
        return clamp_base_rate(MRB_REAL_NEUTRAL + MRB_INFLATION_TARGET)
    pi = float(inflation_yoy)
    return clamp_base_rate(MRB_REAL_NEUTRAL + pi + 0.5 * (pi - MRB_INFLATION_TARGET))


def mrb_bias_from_expected_rate(expected_rate: float, base_rate: float) -> float:
    """기대금리−현재 기준금리 갭 → (−1~+1) 편향."""
    return _mrb_unit_signal(
        float(expected_rate) - float(base_rate), MRB_BASE_LEVEL_SCALE)


def mrb_auto_base_rate_delta(
    world: "World", country: "Country", mrb: Optional[float] = None,
) -> float:
    """MRB 추종 시 기준금리 조정폭(%p). 기대금리−현재 갭에 따라 0.25~1.00.

    0.75·1.00은 갭·편향이 크고 점보 쿨다운이 없을 때만 허용한다.
    """
    bias = float(country_market_rate_bias(country) if mrb is None else mrb)
    if abs(bias) <= MRB_HOLD_BAND:
        return 0.0
    direction = 1.0 if bias > 0.0 else -1.0
    base_rate = country_base_rate(country)
    expected = country_market_expected_rate(country)
    gap = expected - base_rate
    # 기조 방향과 갭이 어긋나면 기본 스텝만 (대형 스텝 금지)
    aligned_gap = gap * direction
    abs_bias = abs(bias)
    cooldown = int(getattr(country, "mrb_jumbo_cooldown", 0) or 0)

    step = MRB_BASE_RATE_STEP
    if aligned_gap >= MRB_STEP_GAP_050 and abs_bias >= MRB_STEP_BIAS_050:
        step = MRB_BASE_RATE_STEP_MED
    if (
        cooldown <= 0
        and aligned_gap >= MRB_STEP_GAP_075
        and abs_bias >= MRB_STEP_BIAS_075
    ):
        step = MRB_BASE_RATE_STEP_LARGE
    if (
        cooldown <= 0
        and aligned_gap >= MRB_STEP_GAP_100
        and abs_bias >= MRB_STEP_BIAS_100
    ):
        step = MRB_BASE_RATE_STEP_XL
    return direction * step


def apply_mrb_auto_base_rate_step(world: "World", country: "Country") -> float:
    """4주 주기 자동 금리 결정. 적용 델타(%p)를 반환(동결이면 0)."""
    if not getattr(world, "warmup_completed", True):
        country.base_rate = clamp_base_rate(WARMUP_FIXED_BASE_RATE)
        pin_repo_rate_to_base_if_intervening(world, country)
        country.trend_weeks = 0
        return 0.0
    mrb = country_market_rate_bias(country)
    delta = mrb_auto_base_rate_delta(world, country, mrb)
    cooldown = int(getattr(country, "mrb_jumbo_cooldown", 0) or 0)
    if cooldown > 0:
        country.mrb_jumbo_cooldown = cooldown - 1
    if abs(delta) >= MRB_BASE_RATE_STEP_XL - 1e-9:
        country.mrb_jumbo_cooldown = MRB_JUMBO_COOLDOWN_100
    elif abs(delta) >= MRB_BASE_RATE_STEP_LARGE - 1e-9:
        country.mrb_jumbo_cooldown = MRB_JUMBO_COOLDOWN_075
    if abs(delta) > 1e-12:
        country.base_rate = clamp_base_rate(country.base_rate + delta)
        pin_repo_rate_to_base_if_intervening(world, country)
    return delta


def _mrb_unit_signal(value: float, scale: float) -> float:
    if scale <= 1e-12:
        return 0.0
    return clamp(float(value) / float(scale), -1.0, 1.0)


def country_unemployment_rate_pct(world: "World", country_id: str) -> float:
    """국가 성인 실업률(%)."""
    states = [s for s in world.states.values() if s.country_id == country_id]
    pops = [p for st in states for p in st.pops]
    if not pops:
        return MRB_NATURAL_UNEMPLOYMENT
    adults = sum(
        p.adult_employed + p.adult_unemployed + p.adult_self_employed for p in pops)
    unemployed = sum(p.adult_unemployed for p in pops)
    return unemployed / max(adults, 1.0) * 100.0


def calc_country_market_rate_bias_raw(
    world: "World", country_id: str,
) -> Tuple[float, Dict[str, float]]:
    """지표별 함의 금리(% )를 가중합해 기대 금리·편향(raw)을 산출.

    인플레이션(테일러) 가중치가 최대. 반환 components에 expected_rate 포함.
    """
    country = world.countries.get(country_id)
    if not country:
        return 0.0, {}
    base_rate = country_base_rate(country)
    components: Dict[str, float] = {}
    r_neutral = MRB_REAL_NEUTRAL + MRB_INFLATION_TARGET

    infl = country_composite_inflation_yoy(world, country_id)
    r_infl = country_taylor_policy_rate(world, country_id, infl)
    if infl is None:
        infl_sig = 0.0
    else:
        infl_sig = _mrb_unit_signal(float(infl) - MRB_INFLATION_TARGET, 4.0)
    components["inflation"] = infl_sig
    components["r_inflation"] = r_infl

    unemp = country_unemployment_rate_pct(world, country_id)
    # 실업↑ → 기대금리↓
    r_unemp = r_neutral + MRB_UNEMP_RATE_SENS * (MRB_NATURAL_UNEMPLOYMENT - unemp)
    unemp_sig = _mrb_unit_signal(MRB_NATURAL_UNEMPLOYMENT - unemp, 5.0)
    components["unemployment"] = unemp_sig
    components["r_unemployment"] = r_unemp

    repo_m = world.repo_markets.get(country_id)
    repo_hw = max(0.05, float(country_repo_band_halfwidth(country) or 0.25))
    if repo_m is not None:
        repo_rate = float(getattr(repo_m, "current_repo_rate", base_rate) or base_rate)
        stress = float(getattr(repo_m, "repo_stress_rate", 0.0) or 0.0)
        if stress > repo_rate + 1e-9:
            repo_rate = 0.7 * repo_rate + 0.3 * stress
        r_repo = repo_rate
        repo_sig = _mrb_unit_signal(repo_rate - base_rate, repo_hw * 2.0)
    else:
        r_repo = base_rate
        repo_sig = 0.0
    components["repo"] = repo_sig
    components["r_repo"] = r_repo

    call_m = world.call_markets.get(country_id)
    if call_m is not None:
        call_rate = float(getattr(call_m, "current_call_rate", base_rate) or base_rate)
        r_call = call_rate
        call_sig = _mrb_unit_signal(call_rate - base_rate, 0.5)
    else:
        r_call = base_rate
        call_sig = 0.0
    components["call"] = call_sig
    components["r_call"] = r_call

    fx_m = country_fx_index_metrics(world, country_id)
    fx_yoy = fx_m.get("fx_index_yoy_pct")
    if fx_yoy is None:
        fx_sig = 0.0
        r_fx = r_neutral
    else:
        # 외환지수↑(자국통화 약세) → 기대금리↑
        fx_sig = _mrb_unit_signal(float(fx_yoy), 10.0)
        r_fx = r_neutral + MRB_FX_RATE_SENS * float(fx_yoy)
    components["fx"] = fx_sig
    components["r_fx"] = r_fx

    gdp_hist = list(country_ensure_gdp_history(country))
    gdp_yoy = series_annual_flow_yoy_pct(gdp_hist) if len(gdp_hist) >= 2 else None
    if gdp_yoy is None:
        gdp_sig = 0.0
        r_gdp = r_neutral
    else:
        gdp_sig = _mrb_unit_signal(float(gdp_yoy) - MRB_GDP_TARGET_YOY, 4.0)
        r_gdp = r_neutral + MRB_GDP_RATE_SENS * (float(gdp_yoy) - MRB_GDP_TARGET_YOY)
    components["gdp"] = gdp_sig
    components["r_gdp"] = r_gdp

    # 국채: 공정 대비 할증 → 더 높은 정책금리 기대
    gov_rate = float(country_reference_bond_rate(world, country_id) or base_rate)
    gov_cq = float(
        bond_market_credit_quality(world, f"gov_{country_id}") or 1.0)
    gov_fair = float(bond_gov_fair_yield_rate(base_rate, gov_cq))
    r_bond = base_rate + (gov_rate - gov_fair)
    bond_sig = _mrb_unit_signal(gov_rate - gov_fair, MRB_BOND_LEVEL_SCALE)
    components["bond"] = bond_sig
    components["r_bond"] = r_bond

    weighted_rate = (
        MRB_WEIGHT_INFLATION * r_infl
        + MRB_WEIGHT_UNEMPLOYMENT * r_unemp
        + MRB_WEIGHT_REPO * r_repo
        + MRB_WEIGHT_CALL * r_call
        + MRB_WEIGHT_FX * r_fx
        + MRB_WEIGHT_GDP * r_gdp
        + MRB_WEIGHT_BOND * r_bond
    )
    weight_sum = (
        MRB_WEIGHT_INFLATION
        + MRB_WEIGHT_UNEMPLOYMENT
        + MRB_WEIGHT_REPO
        + MRB_WEIGHT_CALL
        + MRB_WEIGHT_FX
        + MRB_WEIGHT_GDP
        + MRB_WEIGHT_BOND
    )
    expected = clamp_base_rate(weighted_rate / max(weight_sum, 1e-9))
    raw = mrb_bias_from_expected_rate(expected, base_rate)
    components["expected_rate"] = expected
    components["raw"] = raw
    return raw, components


def update_country_market_rate_bias(world: "World", country: "Country") -> float:
    """주간 기대 금리·MRB 평활 갱신 후 rate_trend 라벨 미러."""
    raw, components = calc_country_market_rate_bias_raw(world, country.id)
    base_rate = country_base_rate(country)
    raw_expected = float(components.get("expected_rate", base_rate) or base_rate)
    prev_expected = country_market_expected_rate(country)
    alpha = MRB_SMOOTH_ALPHA
    smoothed_expected = clamp_base_rate(
        (1.0 - alpha) * prev_expected + alpha * raw_expected)
    country.market_expected_rate = smoothed_expected
    smoothed = mrb_bias_from_expected_rate(smoothed_expected, base_rate)
    # raw 편향도 참고용으로 보관하되, 표시·정책은 평활 기대금리 기준
    country.market_rate_bias = smoothed
    components["expected_rate"] = smoothed_expected
    components["expected_rate_raw"] = raw_expected
    components["raw"] = raw
    country.market_rate_bias_components = {
        k: round(float(v), 4) for k, v in components.items()
    }
    sync_country_rate_trend_label(country)
    return smoothed


def fin_shock_ensure_country(country: "Country") -> None:
    """구 세이브 호환: 금융충격 필드를 채운다."""
    if getattr(country, "financial_shock_index", None) is None:
        country.financial_shock_index = 0.0
    if getattr(country, "financial_shock_delta", None) is None:
        country.financial_shock_delta = 0.0
    if getattr(country, "financial_shock_impulse", None) is None:
        country.financial_shock_impulse = 0.0
    if getattr(country, "financial_shock_pending", None) is None:
        country.financial_shock_pending = 0.0
    if not isinstance(getattr(country, "financial_shock_components", None), dict):
        country.financial_shock_components = {}
    if not isinstance(getattr(country, "financial_shock_reasons", None), list):
        country.financial_shock_reasons = []
    if not isinstance(getattr(country, "financial_shock_policy_snapshot", None), dict):
        country.financial_shock_policy_snapshot = {}
    hist = getattr(country, "weekly_financial_shock_history", None)
    if not isinstance(hist, deque):
        country.weekly_financial_shock_history = deque(maxlen=FIN_SHOCK_HISTORY_WEEKS)
    elif hist.maxlen != FIN_SHOCK_HISTORY_WEEKS:
        country.weekly_financial_shock_history = deque(hist, maxlen=FIN_SHOCK_HISTORY_WEEKS)
    chist = getattr(country, "weekly_financial_shock_components_history", None)
    if not isinstance(chist, deque):
        country.weekly_financial_shock_components_history = deque(
            maxlen=FIN_SHOCK_HISTORY_WEEKS)
    elif chist.maxlen != FIN_SHOCK_HISTORY_WEEKS:
        country.weekly_financial_shock_components_history = deque(
            chist, maxlen=FIN_SHOCK_HISTORY_WEEKS)


def country_ensure_financial_shock_history(country: "Country") -> deque:
    fin_shock_ensure_country(country)
    return country.weekly_financial_shock_history


def country_ensure_financial_shock_components_history(country: "Country") -> deque:
    fin_shock_ensure_country(country)
    return country.weekly_financial_shock_components_history


def fin_shock_label(index: float) -> str:
    v = float(index or 0.0)
    if v >= FIN_SHOCK_RUN:
        return "패닉"
    if v >= FIN_SHOCK_FLIGHT:
        return "뱅크런"
    if v >= FIN_SHOCK_UNEASE:
        return "이탈"
    if v >= FIN_SHOCK_CALM:
        return "불안"
    return "평온"


def country_financial_shock_index(country: Optional["Country"]) -> float:
    if country is None:
        return 0.0
    return clamp(float(getattr(country, "financial_shock_index", 0.0) or 0.0), 0.0, 100.0)


def country_financial_shock_delta(country: Optional["Country"]) -> float:
    if country is None:
        return 0.0
    return float(getattr(country, "financial_shock_delta", 0.0) or 0.0)


def country_financial_shock_intensity(country: Optional["Country"]) -> float:
    """0(평온)~1(패닉). 레벨과 주간 급등을 함께 반영."""
    idx = country_financial_shock_index(country)
    delta = country_financial_shock_delta(country)
    if idx <= FIN_SHOCK_CALM:
        level = 0.0
    elif idx >= FIN_SHOCK_RUN:
        level = 1.0
    else:
        level = (idx - FIN_SHOCK_CALM) / (FIN_SHOCK_RUN - FIN_SHOCK_CALM)
    spike = 0.0
    if delta > FIN_SHOCK_SPIKE_DELTA:
        spike = clamp((delta - FIN_SHOCK_SPIKE_DELTA) / 20.0, 0.0, 0.45)
    return clamp(level + spike, 0.0, 1.0)


def _fin_shock_omo_stock_buy_qty(country: "Country") -> float:
    total = 0.0
    for o in list(getattr(country, "auto_market_orders", None) or []):
        if str(o.get("side") or "") != "buy":
            continue
        if str(o.get("asset") or "") != "stock":
            continue
        total += float(o.get("quantity") or 0.0)
    return total


def fin_shock_capture_policy(country: "Country") -> Dict[str, float]:
    """정책 점프 탐지용 스냅샷."""
    return {
        "base_rate": float(getattr(country, "base_rate", 0.0) or 0.0),
        "corporate_tax": float(getattr(country, "corporate_tax", 0.0) or 0.0),
        "income_tax_low": float(getattr(country, "income_tax_low", 0.0) or 0.0),
        "income_tax_mid": float(getattr(country, "income_tax_mid", 0.0) or 0.0),
        "income_tax_high": float(getattr(country, "income_tax_high", 0.0) or 0.0),
        "consumption_tax": float(getattr(country, "consumption_tax", 0.0) or 0.0),
        "securities_tax": float(getattr(country, "securities_tax", 0.0) or 0.0),
        "property_tax": float(getattr(country, "property_tax", 0.0) or 0.0),
        "reserve_requirement_ratio": float(
            getattr(country, "reserve_requirement_ratio", DEFAULT_RESERVE_REQUIREMENT_RATIO)
            or 0.0),
        "financial_leverage_ratio_pct": float(
            getattr(country, "financial_leverage_ratio_pct", DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT)
            or 0.0),
        "bank_cb_leverage_ratio_pct": float(
            getattr(country, "bank_cb_leverage_ratio_pct", DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT)
            or 0.0),
        "repo_none": 1.0 if country_repo_stance(country) == "none" else 0.0,
        "pop_basic_income_support_pct": float(
            getattr(country, "pop_basic_income_support_pct", 0.0) or 0.0),
        "pop_universal_support_low_pct": float(
            getattr(country, "pop_universal_support_low_pct", 0.0) or 0.0),
        "gov_bond_cb_purchase_remaining": float(
            getattr(country, "gov_bond_cb_purchase_remaining", 0.0) or 0.0),
        "gov_bond_auto_cb": (
            1.0 if (
                bool(getattr(country, "gov_bond_auto_issue", False))
                and str(getattr(country, "gov_bond_auto_issue_underwrite", "") or "") == "cb"
            ) else 0.0
        ),
        "omo_stock_buy": _fin_shock_omo_stock_buy_qty(country),
        "mrb_follow": 1.0 if country_mrb_follow_base_rate(country) else 0.0,
    }


def _fin_shock_reason(
    channel: str, score: float, title: str, detail: str = "",
) -> Dict[str, Any]:
    return {
        "channel": str(channel),
        "score": round(float(score), 2),
        "title": str(title),
        "detail": str(detail or ""),
    }


def _fin_shock_rate_txt(value: float) -> str:
    return f"{float(value):.2f}%"


def _fin_shock_pct_txt(ratio: float) -> str:
    return f"{float(ratio) * 100.0:.1f}%"


FIN_SHOCK_TAX_LABELS: Dict[str, str] = {
    "corporate_tax": "법인세",
    "income_tax_high": "고소득 소득세",
    "income_tax_mid": "중산층 소득세",
    "income_tax_low": "저소득 소득세",
    "consumption_tax": "소비세",
    "securities_tax": "증권세",
    "property_tax": "재산세",
}


def fin_shock_serialize_reasons(reasons: Optional[List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    for raw in list(reasons or []):
        if not isinstance(raw, dict):
            continue
        score = float(raw.get("score", 0.0) or 0.0)
        title = str(raw.get("title") or "").strip()
        if score <= 0.05 and not title:
            continue
        channel = str(raw.get("channel") or "")
        out.append({
            "channel": channel,
            "channel_label": {
                "surprise": "서프라이즈",
                "absurd": "모순정책",
                "market": "시장피드백",
            }.get(channel, channel),
            "score": round(score, 2),
            "title": title,
            "detail": str(raw.get("detail") or ""),
            "lingering": bool(raw.get("lingering")),
        })
    out.sort(key=lambda r: (-float(r.get("score") or 0.0), str(r.get("channel") or "")))
    return out[:12]


def fin_shock_rate_surprise_score(
    country: "Country", old_rate: float, new_rate: float,
) -> float:
    """기준금리 변경의 서프라이즈 점수 (0~28).

    시장이 가격한 방향·폭 안의 조정(자동 추종 포함)은 0.
    반대 방향이거나 기대를 크게 지나친 점보만 점수를 준다.
    """
    delta = float(new_rate) - float(old_rate)
    if abs(delta) < 0.04:
        return 0.0
    expected = country_market_expected_rate(country)
    mrb = country_market_rate_bias(country)
    follow = country_mrb_follow_base_rate(country)
    old_err = float(old_rate) - float(expected)
    new_err = float(new_rate) - float(expected)
    expected_move = float(expected) - float(old_rate)
    against = (delta > 0.0 and mrb < -MRB_HOLD_BAND) or (
        delta < 0.0 and mrb > MRB_HOLD_BAND)
    # 기대 금리에 더 가까워지는 추종 스텝은 서프라이즈가 아니다.
    if (not against) and abs(new_err) <= abs(old_err) + 0.04:
        if follow or (delta * expected_move > 0.0) or abs(expected_move) <= 0.12:
            return 0.0
    if delta * expected_move > 0.0:
        unexpected = max(0.0, abs(delta) - abs(expected_move))
    elif abs(expected_move) <= 0.12:
        unexpected = abs(delta)
    else:
        unexpected = abs(delta) + min(abs(expected_move), 1.0) * 0.45
    if unexpected < 0.20 and not against:
        return 0.0
    if (
        unexpected < 0.40
        and abs(mrb) <= MRB_HOLD_BAND
        and not against
    ):
        return 0.0
    mag = unexpected / max(MRB_BASE_RATE_STEP, 0.25)
    score = mag * 2.2
    hold_break = abs(mrb) <= MRB_HOLD_BAND and abs(delta) >= 0.75
    if against:
        score *= 1.85
    elif hold_break:
        score *= 1.30
    if not follow:
        score *= 1.12
    return clamp(score, 0.0, 28.0)


def fin_shock_residual_gap_score(country: "Country") -> Tuple[float, List[Dict[str, Any]]]:
    """금리를 안 바꿔도 기대와 크게 어긋나면 남는 구조 항 (매주 점프하지 않음)."""
    if country_mrb_follow_base_rate(country):
        return 0.0, []
    expected = country_market_expected_rate(country)
    base = country_base_rate(country)
    gap = abs(expected - base)
    if gap <= 1.25:
        return 0.0, []
    score = clamp((gap - 1.25) * 0.85, 0.0, 5.0)
    stance = market_rate_stance_label(country_market_rate_bias(country))
    return score, [_fin_shock_reason(
        "surprise", score,
        f"시장은 {stance}인데 금리를 그대로 둠",
        f"시행 {_fin_shock_rate_txt(base)} · 시장 기대 {_fin_shock_rate_txt(expected)} · 갭 {gap:.2f}%p",
    )]


def fin_shock_policy_jump_impulse(
    world: "World", country: "Country", snap: Optional[Dict[str, float]],
) -> Tuple[float, List[Dict[str, Any]]]:
    """전 스냅샷 대비 정책 점프 → 일회 충격."""
    now = fin_shock_capture_policy(country)
    if not snap:
        return 0.0, []
    reasons: List[Dict[str, Any]] = []
    total = 0.0

    old_r = float(snap.get("base_rate", now["base_rate"]) or 0.0)
    new_r = now["base_rate"]
    delta = new_r - old_r
    if abs(delta) > 0.04:
        rate_s = fin_shock_rate_surprise_score(country, old_r, new_r)
        if rate_s > 0.05:
            expected = country_market_expected_rate(country)
            stance = market_rate_stance_label(country_market_rate_bias(country))
            direction = "인상" if delta > 0.0 else "인하"
            mrb = country_market_rate_bias(country)
            against = (delta > 0.0 and mrb < -MRB_HOLD_BAND) or (
                delta < 0.0 and mrb > MRB_HOLD_BAND)
            hold_break = abs(mrb) <= MRB_HOLD_BAND and abs(delta) >= 0.75
            if against:
                title = f"{stance}인데 기준금리를 {abs(delta):.2f}%p {direction}"
            elif hold_break:
                title = f"{stance}인데 기준금리를 {abs(delta):.2f}%p {direction}"
            else:
                title = f"기준금리 {abs(delta):.2f}%p {direction}"
            reasons.append(_fin_shock_reason(
                "surprise", rate_s, title,
                f"시행 {_fin_shock_rate_txt(old_r)} → {_fin_shock_rate_txt(new_r)} · 시장 기대 {_fin_shock_rate_txt(expected)}",
            ))
            total += rate_s

    tax_jump = 0.0
    tax_bits: List[str] = []
    for key, weight in (
        ("corporate_tax", 55.0),
        ("income_tax_high", 42.0),
        ("income_tax_mid", 36.0),
        ("income_tax_low", 32.0),
        ("consumption_tax", 48.0),
        ("securities_tax", 140.0),
        ("property_tax", 70.0),
    ):
        old_t = float(snap.get(key, now[key]) or 0.0)
        new_t = now[key]
        dlt = abs(new_t - old_t)
        part = dlt * weight
        if part <= 0.55:
            continue
        tax_jump += part
        tax_bits.append(
            f"{FIN_SHOCK_TAX_LABELS.get(key, key)} {_fin_shock_pct_txt(old_t)} → {_fin_shock_pct_txt(new_t)}"
        )
    tax_jump = min(14.0, tax_jump)
    if tax_jump > 0.55:
        reasons.append(_fin_shock_reason(
            "surprise", tax_jump, "세율 급변", " · ".join(tax_bits)))
        total += tax_jump

    old_res = float(snap.get("reserve_requirement_ratio", now["reserve_requirement_ratio"]) or 0.0)
    res_jump = abs(now["reserve_requirement_ratio"] - old_res) * 70.0
    if res_jump > 0.55:
        res_s = min(10.0, res_jump)
        reasons.append(_fin_shock_reason(
            "surprise", res_s, "지급준비금 급변",
            f"{_fin_shock_pct_txt(old_res)} → {_fin_shock_pct_txt(now['reserve_requirement_ratio'])}",
        ))
        total += res_s

    old_lev = float(snap.get("financial_leverage_ratio_pct", now["financial_leverage_ratio_pct"]) or 0.0)
    old_cb_lev = float(snap.get("bank_cb_leverage_ratio_pct", now["bank_cb_leverage_ratio_pct"]) or 0.0)
    lev_jump = abs(now["financial_leverage_ratio_pct"] - old_lev) * 0.015
    cb_lev_jump = abs(now["bank_cb_leverage_ratio_pct"] - old_cb_lev) * 0.012
    lev_s = min(14.0, lev_jump + cb_lev_jump)
    if lev_s > 0.4:
        bits = []
        if lev_jump > 0.2:
            bits.append(
                f"금투 {financial_leverage_multiple(old_lev):.1f}배 → "
                f"{financial_leverage_multiple(now['financial_leverage_ratio_pct']):.1f}배"
            )
        if cb_lev_jump > 0.2:
            bits.append(
                f"은행 CB차입 {financial_leverage_multiple(old_cb_lev):.1f}배 → "
                f"{financial_leverage_multiple(now['bank_cb_leverage_ratio_pct']):.1f}배"
            )
        reasons.append(_fin_shock_reason(
            "surprise", lev_s, "레버리지 한도 급변", " · ".join(bits) or "자기자본비율 급변"))
        total += lev_s

    if now["repo_none"] > float(snap.get("repo_none", 0.0) or 0.0) + 0.5:
        repo_s = 6.0
        extra = "레포 시장 개입을 방임으로 전환"
        repo_m = world.repo_markets.get(country.id)
        if repo_m is not None:
            stress = float(getattr(repo_m, "repo_stress_rate", 0.0) or 0.0)
            base = country_base_rate(country)
            if stress > base + 0.5:
                repo_s += min(8.0, (stress - base) * 0.8)
                extra = (
                    f"레포 스트레스({_fin_shock_rate_txt(stress)}) 중에 개입을 방임으로 전환"
                )
        reasons.append(_fin_shock_reason("surprise", repo_s, extra))
        total += repo_s

    old_basic = float(snap.get("pop_basic_income_support_pct", 0.0) or 0.0)
    old_univ = float(snap.get("pop_universal_support_low_pct", 0.0) or 0.0)
    wel = (
        max(0.0, old_basic - now["pop_basic_income_support_pct"]) * 0.12
        + max(0.0, old_univ - now["pop_universal_support_low_pct"]) * 0.06
    )
    if wel > 0.4:
        wel_s = min(12.0, wel)
        bits = []
        if now["pop_basic_income_support_pct"] + 0.05 < old_basic:
            bits.append(
                f"기초수급 {old_basic:.0f}% → {now['pop_basic_income_support_pct']:.0f}%"
            )
        if now["pop_universal_support_low_pct"] + 0.05 < old_univ:
            bits.append(
                f"저소득 보편지원 {old_univ:.0f}% → {now['pop_universal_support_low_pct']:.0f}%"
            )
        reasons.append(_fin_shock_reason(
            "surprise", wel_s, "복지 급감", " · ".join(bits) or "복지 지원 축소"))
        total += wel_s

    cb_s = 0.0
    old_cb = float(snap.get("gov_bond_cb_purchase_remaining", 0.0) or 0.0)
    cb_bits: List[str] = []
    if now["gov_bond_cb_purchase_remaining"] > old_cb + 1.0:
        cb_s += min(7.0, 2.5 + math.log10(1.0 + now["gov_bond_cb_purchase_remaining"]) * 1.6)
        cb_bits.append("국채를 중앙은행이 인수(사실상 발권)")
    if now["gov_bond_auto_cb"] > float(snap.get("gov_bond_auto_cb", 0.0) or 0.0) + 0.5:
        cb_s += 5.0
        cb_bits.append("매주 국채 자동발행을 중앙은행 인수로 설정")
    if cb_s > 0.4:
        reasons.append(_fin_shock_reason(
            "surprise", cb_s, "국채 발권성 인수", " · ".join(cb_bits)))
        total += cb_s

    if now["omo_stock_buy"] > float(snap.get("omo_stock_buy", 0.0) or 0.0) + 1e-9:
        reasons.append(_fin_shock_reason(
            "surprise", 3.5, "주식 공개시장 자동매수 시작",
            "중앙은행·정부가 주식을 매주 사도록 설정",
        ))
        total += 3.5

    if float(snap.get("mrb_follow", 1.0) or 0.0) > now["mrb_follow"] + 0.5:
        gap = abs(country_market_expected_rate(country) - country_base_rate(country))
        follow_s = min(6.0, 2.0 + gap * 1.2)
        reasons.append(_fin_shock_reason(
            "surprise", follow_s, "시장 기대 기조 추종을 해제",
            f"시행 {_fin_shock_rate_txt(country_base_rate(country))} · "
            f"시장 기대 {_fin_shock_rate_txt(country_market_expected_rate(country))}",
        ))
        total += follow_s

    return min(36.0, total), reasons


def fin_shock_absurd_score(
    world: "World", country: "Country",
) -> Tuple[float, List[Dict[str, Any]]]:
    """거시와 정책이 모순일 때 지속되는 점수 (0~32)."""
    cid = country.id
    infl = country_consumer_cpi_yoy(world, cid)
    if infl is None:
        infl = country_composite_inflation_yoy(world, cid)
    infl = float(infl or 0.0)
    unemp = country_unemployment_rate_pct(world, cid)
    taylor = country_taylor_policy_rate(world, cid, infl)
    base = country_base_rate(country)
    expected = country_market_expected_rate(country)
    score = 0.0
    reasons: List[Dict[str, Any]] = []

    if infl > 8.0 and base < taylor - 1.50:
        part = min(10.0, (infl - 8.0) * 0.45 + (taylor - base) * 0.65)
        score += part
        reasons.append(_fin_shock_reason(
            "absurd", part, "고인플레인데 금리가 너무 낮음",
            f"인플레 {infl:.1f}% · 시행 {_fin_shock_rate_txt(base)} · 테일러 적정 {_fin_shock_rate_txt(taylor)}",
        ))
    if infl < -1.0 and base > taylor + 1.50:
        part = min(6.0, abs(infl) * 0.7 + (base - taylor) * 0.45)
        score += part
        reasons.append(_fin_shock_reason(
            "absurd", part, "물가 하락인데 긴축",
            f"인플레 {infl:.1f}% · 시행 {_fin_shock_rate_txt(base)} · 테일러 적정 {_fin_shock_rate_txt(taylor)}",
        ))
    if unemp > 10.0 and base > expected + 1.25:
        part = min(6.0, (unemp - 10.0) * 0.7 + (base - expected) * 0.4)
        score += part
        reasons.append(_fin_shock_reason(
            "absurd", part, "고실업인데 금리가 기대보다 높음",
            f"실업 {unemp:.1f}% · 시행 {_fin_shock_rate_txt(base)} · 시장 기대 {_fin_shock_rate_txt(expected)}",
        ))

    cb_rem = float(getattr(country, "gov_bond_cb_purchase_remaining", 0.0) or 0.0)
    auto_cb = (
        bool(getattr(country, "gov_bond_auto_issue", False))
        and str(getattr(country, "gov_bond_auto_issue_underwrite", "") or "") == "cb"
    )
    if infl > 6.0 and (cb_rem > 1.0 or auto_cb):
        part = min(8.0, 3.0 + max(0.0, infl - 6.0) * 0.7)
        score += part
        how = "매주 국채 중앙은행 인수" if auto_cb else "국채 중앙은행 인수 대기"
        reasons.append(_fin_shock_reason(
            "absurd", part, f"고인플레인데 {how}",
            f"인플레 {infl:.1f}% · 사실상 발권",
        ))
    if infl > 6.0 and _fin_shock_omo_stock_buy_qty(country) > 1e-9:
        score += 4.0
        reasons.append(_fin_shock_reason(
            "absurd", 4.0, "고인플레인데 주식 공개시장 매수",
            f"인플레 {infl:.1f}%인데 정부·중앙은행이 주식을 매주 매수",
        ))

    if country_repo_stance(country) == "none":
        repo_m = world.repo_markets.get(cid)
        if repo_m is not None:
            stress = float(getattr(repo_m, "repo_stress_rate", 0.0) or 0.0)
            if stress > base + 0.8:
                part = min(8.0, 3.0 + (stress - base) * 0.5)
                score += part
                reasons.append(_fin_shock_reason(
                    "absurd", part, "레포 스트레스인데 개입 방임",
                    f"레포 스트레스 {_fin_shock_rate_txt(stress)} · 기준 {_fin_shock_rate_txt(base)}",
                ))

    reserve = country_reserve_requirement_ratio(country)
    if abs(reserve - DEFAULT_RESERVE_REQUIREMENT_RATIO) > 0.12:
        part = min(6.0, abs(reserve - DEFAULT_RESERVE_REQUIREMENT_RATIO) * 22.0)
        score += part
        reasons.append(_fin_shock_reason(
            "absurd", part, "지급준비금이 기본에서 크게 벗어남",
            f"현재 {_fin_shock_pct_txt(reserve)} · 기본 {_fin_shock_pct_txt(DEFAULT_RESERVE_REQUIREMENT_RATIO)}",
        ))

    lev_mult = financial_leverage_multiple(
        float(getattr(country, "financial_leverage_ratio_pct", DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT)
              or DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT))
    if lev_mult < 2.5 or lev_mult > 28.0:
        part = min(6.0, abs(lev_mult - DEFAULT_FINANCIAL_LEVERAGE_MULTIPLE) * 0.28)
        score += part
        kind = "과도하게 낮음" if lev_mult < 2.5 else "과도하게 높음"
        reasons.append(_fin_shock_reason(
            "absurd", part, f"금융 레버리지가 {kind}",
            f"현재 {lev_mult:.1f}배 · 기본 {DEFAULT_FINANCIAL_LEVERAGE_MULTIPLE:.1f}배",
        ))

    corp = float(getattr(country, "corporate_tax", 0.0) or 0.0)
    high = float(getattr(country, "income_tax_high", 0.0) or 0.0)
    if corp > 0.50 or high > 0.60:
        score += 4.0
        reasons.append(_fin_shock_reason(
            "absurd", 4.0, "세율이 극단적으로 높음",
            f"법인세 {_fin_shock_pct_txt(corp)} · 고소득 소득세 {_fin_shock_pct_txt(high)}",
        ))
    if corp < 0.02 and infl > 8.0:
        score += 3.0
        reasons.append(_fin_shock_reason(
            "absurd", 3.0, "고인플레인데 법인세를 거의 면제",
            f"인플레 {infl:.1f}% · 법인세 {_fin_shock_pct_txt(corp)}",
        ))

    return clamp(score, 0.0, 32.0), reasons


def fin_shock_market_score(
    world: "World", country: "Country", prev_index: float,
) -> Tuple[float, List[Dict[str, Any]]]:
    """가격·레포 스트레스 증폭 (0~12). 평온+평범한 약세는 거의 무시."""
    cid = country.id
    eq_stress = 0.0
    ret4 = 0.0
    vals = country_stock_index_weekly_values(world, cid)
    if len(vals) >= 5 and float(vals[-5] or 0.0) > 1e-9:
        ret4 = float(vals[-1]) / float(vals[-5]) - 1.0
        eq_stress = clamp((-ret4) / 0.12, 0.0, 1.0)
    ib_s = 0.0
    try:
        ib_s = float(ib_market_stress_factor(world, cid) or 0.0)
    except Exception:
        ib_s = 0.0
    repo_sig = 0.0
    stress_rate = 0.0
    repo_m = world.repo_markets.get(cid)
    base = country_base_rate(country)
    if repo_m is not None:
        stress_rate = float(getattr(repo_m, "repo_stress_rate", 0.0) or 0.0)
        repo_sig = clamp((stress_rate - base) / 5.0, 0.0, 1.0)
    raw = 18.0 * (0.45 * eq_stress + 0.30 * clamp(ib_s, 0.0, 1.0) + 0.25 * repo_sig)
    if prev_index < FIN_SHOCK_CALM and eq_stress < 0.70:
        raw *= 0.35
    score = clamp(raw, 0.0, 12.0)
    reasons: List[Dict[str, Any]] = []
    if score <= 0.15:
        return score, reasons
    denom = max(0.45 * eq_stress + 0.30 * ib_s + 0.25 * repo_sig, 1e-9)
    if eq_stress > 0.15:
        reasons.append(_fin_shock_reason(
            "market", score * (0.45 * eq_stress) / denom,
            f"{country_stock_index_label(cid)} 급락",
            f"최근 4주 {ret4 * 100.0:+.1f}%",
        ))
    if ib_s > 0.20:
        reasons.append(_fin_shock_reason(
            "market", score * (0.30 * ib_s) / denom,
            "금융시장 스트레스",
            f"금투 스트레스 {ib_s * 100.0:.0f}%",
        ))
    if repo_sig > 0.15:
        reasons.append(_fin_shock_reason(
            "market", score * (0.25 * repo_sig) / denom,
            "레포 스트레스 금리 급등",
            f"스트레스 {_fin_shock_rate_txt(stress_rate)} · 기준 {_fin_shock_rate_txt(base)}",
        ))
    return score, reasons


def fin_shock_display_reasons(world: "World", country: "Country") -> List[Dict[str, Any]]:
    """HUD용. 서프라이즈는 저장된 값을, 모순·시장은 현재 정책으로 다시 계산한다."""
    stored_surprise = [
        r for r in list(getattr(country, "financial_shock_reasons", None) or [])
        if str(r.get("channel") or "") == "surprise"
    ]
    if not stored_surprise:
        _res, stored_surprise = fin_shock_residual_gap_score(country)
    _abs, absurd_reasons = fin_shock_absurd_score(world, country)
    _mkt, market_reasons = fin_shock_market_score(
        world, country, country_financial_shock_index(country))
    return fin_shock_serialize_reasons(stored_surprise + absurd_reasons + market_reasons)


def _fin_shock_keep_lingering_surprises(
    country: "Country", fresh: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """이번 주 새 서프라이즈가 없어도, 지수가 남아 있으면 직전 원인을 보여 준다."""
    has_fresh_surprise = any(
        str(r.get("channel") or "") == "surprise" and not r.get("lingering")
        for r in fresh
    )
    if has_fresh_surprise or country_financial_shock_index(country) < FIN_SHOCK_CALM:
        return fresh
    prev = [
        dict(r, lingering=True)
        for r in list(getattr(country, "financial_shock_reasons", None) or [])
        if str(r.get("channel") or "") == "surprise"
    ]
    return prev + fresh


def update_country_financial_shock(world: "World", country: "Country") -> float:
    """주간 금융충격지수 갱신. 정책 점프는 일회, 모순·시장은 구조 항."""
    fin_shock_ensure_country(country)
    prev = country_financial_shock_index(country)
    snap = getattr(country, "financial_shock_policy_snapshot", None) or {}
    jump, jump_reasons = fin_shock_policy_jump_impulse(world, country, snap)
    residual, residual_reasons = fin_shock_residual_gap_score(country)
    surprise = jump
    absurd, absurd_reasons = fin_shock_absurd_score(world, country)
    market, market_reasons = fin_shock_market_score(world, country, prev)
    # 잔여 금리갭은 매주 점프가 아니라 구조 항. (점프로 넣으면 감쇠 역수로 누적된다)
    structural = absurd + market + residual
    nxt = (
        FIN_SHOCK_DECAY * prev
        + (1.0 - FIN_SHOCK_DECAY) * structural
        + surprise
    )
    nxt = clamp(nxt, 0.0, 100.0)
    country.financial_shock_index = nxt
    country.financial_shock_delta = nxt - prev
    country.financial_shock_impulse = surprise
    country.financial_shock_pending = 0.0
    country.financial_shock_components = {
        "surprise": round(jump + residual, 3),
        "absurd": round(absurd, 3),
        "market": round(market, 3),
    }
    fresh = jump_reasons + residual_reasons + absurd_reasons + market_reasons
    country.financial_shock_reasons = fin_shock_serialize_reasons(
        _fin_shock_keep_lingering_surprises(country, fresh))
    country_ensure_financial_shock_history(country).append(nxt)
    country_ensure_financial_shock_components_history(country).append(
        dict(country.financial_shock_components))
    country.financial_shock_policy_snapshot = fin_shock_capture_policy(country)
    return nxt


def apply_financial_shock_policy_event(
    world: Optional["World"], country: "Country",
) -> float:
    """정책 API 직후 점프를 지수에 즉시 반영하고 스냅샷을 갱신."""
    fin_shock_ensure_country(country)
    snap = getattr(country, "financial_shock_policy_snapshot", None) or {}
    if not snap or world is None:
        country.financial_shock_policy_snapshot = fin_shock_capture_policy(country)
        return 0.0
    jump, jump_reasons = fin_shock_policy_jump_impulse(world, country, snap)
    if jump > 0.05:
        prev = country_financial_shock_index(country)
        nxt = clamp(prev + jump, 0.0, 100.0)
        country.financial_shock_index = nxt
        country.financial_shock_delta = nxt - prev
        country.financial_shock_impulse = jump
        comps = dict(getattr(country, "financial_shock_components", None) or {})
        comps["surprise"] = round(float(comps.get("surprise", 0.0) or 0.0) + jump, 3)
        country.financial_shock_components = comps
        kept = [
            r for r in list(getattr(country, "financial_shock_reasons", None) or [])
            if str(r.get("channel") or "") != "surprise"
        ]
        country.financial_shock_reasons = fin_shock_serialize_reasons(jump_reasons + kept)
    country.financial_shock_policy_snapshot = fin_shock_capture_policy(country)
    return jump


def financial_shock_rate_preview(
    country: "Country", new_rate: float,
) -> Dict[str, Any]:
    """기준금리 변경 시 예상 충격 가산."""
    fin_shock_ensure_country(country)
    old = country_base_rate(country)
    target = clamp_base_rate(new_rate)
    impulse = fin_shock_rate_surprise_score(country, old, target)
    idx = country_financial_shock_index(country)
    expected = country_market_expected_rate(country)
    stance = market_rate_stance_label(country_market_rate_bias(country))
    delta = target - old
    direction = "인상" if delta > 0 else "인하"
    reason = ""
    if impulse >= 0.3:
        mrb = country_market_rate_bias(country)
        against = (delta > 0.0 and mrb < -MRB_HOLD_BAND) or (
            delta < 0.0 and mrb > MRB_HOLD_BAND)
        if against:
            reason = f"{stance}인데 {abs(delta):.2f}%p {direction}"
        else:
            reason = f"기준금리 {abs(delta):.2f}%p {direction} · 기대 {_fin_shock_rate_txt(expected)}"
    return {
        "impulse": round(impulse, 2),
        "index": round(idx, 2),
        "index_after": round(clamp(idx + impulse, 0.0, 100.0), 2),
        "label": fin_shock_label(idx + impulse),
        "reason": reason,
        "current_rate": round(old, 3),
        "target_rate": round(target, 3),
        "expected_rate": round(expected, 3),
        "market_expected_stance": stance,
    }


def country_financial_shock_payload(country: Optional["Country"]) -> Dict[str, Any]:
    if country is not None:
        fin_shock_ensure_country(country)
    idx = country_financial_shock_index(country)
    comps = dict(getattr(country, "financial_shock_components", None) or {}) if country else {}
    reasons = fin_shock_serialize_reasons(
        getattr(country, "financial_shock_reasons", None) if country else None)
    return {
        "financial_shock_index": round(idx, 2),
        "financial_shock_delta": round(country_financial_shock_delta(country), 2),
        "financial_shock_impulse": round(
            float(getattr(country, "financial_shock_impulse", 0.0) or 0.0), 2)
        if country else 0.0,
        "financial_shock_label": fin_shock_label(idx),
        "financial_shock_intensity": round(country_financial_shock_intensity(country), 3),
        "financial_shock_components": {
            k: round(float(comps.get(k, 0.0) or 0.0), 3)
            for k, _lab, _col in FIN_SHOCK_FACTORS
        },
        "financial_shock_reasons": reasons,
    }


def pop_country_of(world: "World", pop: "POP") -> Optional["Country"]:
    st = world.states.get(getattr(pop, "state_id", None))
    if st is None:
        return None
    return world.countries.get(st.country_id)


def pop_financial_shock_intensity(world: "World", pop: "POP") -> float:
    """문해력·필수재 미충족일수록 같은 충격에도 더 강하게 현금 도피."""
    country = pop_country_of(world, pop)
    base = country_financial_shock_intensity(country)
    if base <= 1e-9:
        return 0.0
    lit = clamp(float(getattr(pop, "financial_literacy", 0.5) or 0.5), 0.0, 1.0)
    essential = clamp(float(getattr(pop, "last_essential_fulfillment", 1.0) or 1.0), 0.0, 1.0)
    safe_bias = max(0.0, (POP_INVEST_ESSENTIAL_GATE - essential) / max(POP_INVEST_ESSENTIAL_GATE, 1e-9))
    return clamp(base * (0.70 + 0.30 * (1.0 - lit) + 0.25 * safe_bias), 0.0, 1.0)


def pop_alloc_shock_limits(world: "World", pop: "POP") -> Dict[str, float]:
    """충격 강도에 따라 현금캡·예금/펀드 하한·주간 유량을 연다."""
    t = pop_financial_shock_intensity(world, pop)
    return {
        "intensity": t,
        "cash_cap": POP_ALLOC_CASH_CAP + (FIN_SHOCK_CASH_CAP_PANIC - POP_ALLOC_CASH_CAP) * t,
        "deposit_floor": (
            POP_ALLOC_DEPOSIT_FLOOR
            + (FIN_SHOCK_DEPOSIT_FLOOR_PANIC - POP_ALLOC_DEPOSIT_FLOOR) * t
        ),
        "fund_floor": (
            POP_ALLOC_FUND_FLOOR
            + (FIN_SHOCK_FUND_FLOOR_PANIC - POP_ALLOC_FUND_FLOOR) * t
        ),
        "weekly_flow": (
            PORTFOLIO_MAX_WEEKLY_FLOW_PCT
            + (FIN_SHOCK_FLOW_PANIC - PORTFOLIO_MAX_WEEKLY_FLOW_PCT) * t
        ),
        # 이탈 구간부터는 초과현금을 예금·펀드에 다시 넣지 않는다.
        "cash_deploy": POP_CASH_DEPLOY_PCT * max(0.0, 1.0 - t / max(FIN_SHOCK_INFLOW_STOP, 1e-9)),
    }


def country_auto_deposit_ratio(country: Optional["Country"]) -> float:
    """기업 유동자산 예치 비율. 금융충격 시 현금 보유를 늘린다."""
    t = country_financial_shock_intensity(country)
    if t <= 1e-9:
        return AUTO_DEPOSIT_RATIO
    return (
        AUTO_DEPOSIT_RATIO * (1.0 - t)
        + FIN_SHOCK_CORP_DEPOSIT_PANIC * t
    )


def calc_dividend_ratio(
    net_income: float, bond_balance: float, base_rate: float,
    dovish_score: float = 0.5,
) -> float:
    if net_income <= 0:
        return 0.0
    dr = bond_balance / net_income if net_income > 0 else 999.0
    weight = (
        debt_ratio_score(dr) * 0.5
        + base_rate_score(base_rate) * 0.3
        + clamp(float(dovish_score), 0.0, 1.0) * 0.2
    )
    return clamp(weight * 60.0, 0.0, 60.0)


def _sigmoid01(x: float) -> float:
    return 1.0 / (1.0 + math.exp(-clamp(float(x), -8.0, 8.0)))


def industry_payout_elasticity(company_type: str) -> Dict[str, float]:
    """산업군 파라미터 → 배당/자사주 반응 탄력 (고정 prior 표 없음)."""
    ctype = normalize_company_type(company_type)
    margin_mid = industry_margin_target_mid("", ctype)
    labor = industry_labor_share("", ctype)
    buf = product_supply_buffer_multiplier(None, ctype)
    # 고마진 업종: 저평가→매입 전환이 더 민감
    w_val = 0.55 + 1.35 * clamp((margin_mid - 0.05) / 0.18, 0.0, 1.0)
    # 노동집약: 안정 시 배당 soft bias
    w_labor_bias = 0.40 * clamp((labor - 0.28) / 0.42, 0.0, 1.0)
    # 공급버퍼 큰 사이클 업종: 실적 호황→매입 탄력↑
    w_cycle = 0.25 + 2.0 * clamp((buf - 1.0) / 0.20, 0.0, 1.0)
    return {"w_val": w_val, "w_labor_bias": w_labor_bias, "w_cycle": w_cycle}


def _company_expansion_pressure(company: "Company") -> float:
    if int(getattr(company, "office_under_construction", 0) or 0) > 0:
        return 1.0
    for fac in getattr(company, "facilities", None) or []:
        if int(getattr(fac, "under_construction", 0) or 0) > 0:
            return 1.0
    return 0.0


def _company_earnings_gap_z(company: "Company") -> float:
    ni = float(getattr(company, "net_income", 0.0) or 0.0)
    hist = [
        float(x or 0.0)
        for x in (getattr(company, "weekly_net_income_history", None) or [])
    ]
    if len(hist) >= 4:
        window = hist[-13:]
        avg = sum(window) / max(len(window), 1)
        return clamp((ni - avg) / max(abs(avg), 1.0), -2.0, 2.0)
    opex = max(0.0, float(getattr(company, "last_week_operating_expense", 0.0) or 0.0))
    if opex <= 1e-9:
        return 0.0
    return clamp(ni / opex - 0.15, -2.0, 2.0)


def calc_buyback_share_of_payout(world: "World", company: "Company") -> float:
    """환원 예산 중 자사주 매입 비중. 매주 기업 상황·업종 탄력으로 재산출."""
    if company is None:
        return 0.0
    listed = bool(getattr(company, "listed", False)) or int(
        getattr(company, "ipo_weeks_left", 0) or 0) > 0
    if world is not None and not listed:
        listed = company_is_listed(world, str(getattr(company, "id", "") or ""))
    if not listed:
        return 0.0
    elast = industry_payout_elasticity(str(getattr(company, "type", "") or ""))
    mos = 0.0
    if world is not None:
        try:
            mos = float(
                ib_stock_mixed_fv_pack(world, str(company.id)).get("mos", 0.0) or 0.0)
        except Exception:
            mos = 0.0
    valuation_z = clamp(mos / max(IB_Z_TYPICAL_MOS, 1e-9), -2.0, 2.0)
    buffer = max(
        0.0, float(getattr(company, "last_week_operating_expense", 0.0) or 0.0)) * 4.0
    cash = max(0.0, float(getattr(company, "cash", 0.0) or 0.0))
    cash_z = clamp(
        (cash - buffer) / max(buffer, 1.0), -2.0, 2.0)
    ni = max(0.0, float(getattr(company, "net_income", 0.0) or 0.0))
    debt = max(0.0, float(getattr(company, "bond_balance", 0.0) or 0.0))
    debt_z = clamp(debt / max(ni, 1.0) / 10.0, 0.0, 2.0)
    earnings_z = _company_earnings_gap_z(company)
    expansion = _company_expansion_pressure(company)
    score = (
        float(elast["w_val"]) * valuation_z
        + 0.70 * cash_z
        - 0.90 * debt_z
        + float(elast["w_cycle"]) * earnings_z
        - float(elast["w_labor_bias"])
        - 0.80 * expansion
    )
    return clamp(
        _sigmoid01(score),
        BUYBACK_OF_PAYOUT_FLOOR,
        BUYBACK_OF_PAYOUT_CEIL,
    )


def market_key(state_id: str, item: str) -> str:
    return f"{state_id}::{item}"


def canonical_service_item(product: str) -> str:
    """구 공립/민간 의료·교육 품목을 통합 서비스명으로 바꾼다."""
    name = str(product or "")
    return SERVICE_ITEM_ALIASES.get(name, name)


def migrate_legacy_service_markets(world: "World") -> None:
    """세이브·재초기화 시 공립/민간 의료·교육 시장을 하나로 합친다."""
    markets = getattr(world, "markets", None)
    if not isinstance(markets, dict) or not markets:
        return
    grouped: Dict[Tuple[str, str], List[Any]] = defaultdict(list)
    stale: List[str] = []
    for mk, market in list(markets.items()):
        item = str(getattr(market, "item_type", "") or "")
        canon = SERVICE_ITEM_ALIASES.get(item)
        if not canon:
            continue
        grouped[(str(getattr(market, "state_id", "") or ""), canon)].append(market)
        stale.append(mk)
    if not stale:
        return
    for mk in stale:
        markets.pop(mk, None)
    for (sid, canon), olds in grouped.items():
        dest_key = market_key(sid, canon)
        existing = markets.get(dest_key)
        pool = list(olds)
        if existing is not None and str(getattr(existing, "item_type", "") or "") == canon:
            pool.append(existing)
        chosen = max(
            pool,
            key=lambda m: (
                len(getattr(m, "weekly_price_history", None) or []),
                float(getattr(m, "last_buy_volume", 0.0) or 0.0)
                + float(getattr(m, "last_sell_volume", 0.0) or 0.0),
            ),
        )
        chosen.item_type = canon
        chosen.state_id = sid
        base = float(PRODUCT_BASE_PRICES.get(canon, 0.0) or 0.0)
        if base > 1e-12:
            chosen.base_price = base
        buy = sum(float(getattr(m, "last_buy_volume", 0.0) or 0.0) for m in pool)
        sell = sum(float(getattr(m, "last_sell_volume", 0.0) or 0.0) for m in pool)
        if buy > 1e-12:
            chosen.last_buy_volume = buy
        if sell > 1e-12:
            chosen.last_sell_volume = sell
        num = den = 0.0
        for m in pool:
            px = float(getattr(m, "current_price", 0.0) or 0.0)
            w = (
                float(getattr(m, "last_buy_volume", 0.0) or 0.0)
                + float(getattr(m, "last_sell_volume", 0.0) or 0.0)
            )
            if px <= 1e-12:
                continue
            ww = w if w > 1e-12 else 1.0
            num += px * ww
            den += ww
        if den > 1e-12:
            chosen.current_price = num / den
        markets[dest_key] = chosen


# 주 간 최단 경로(주 개수) 메모이제이션 — 지형(neighbors)은 월드 수명 동안 고정
STATE_PATH_CACHE: Dict[Tuple[str, str], Optional[int]] = {}
# None(경로 없음)도 캐시하므로 미스 판별용 센티널
_STATE_PATH_CACHE_MISS = object()


def clear_state_path_cache() -> None:
    STATE_PATH_CACHE.clear()


def state_path_length(states: Dict[str, "State"], origin_id: str, dest_id: str) -> Optional[int]:
    """출발 주에서 도착 주까지 최단 육로 경로의 주 개수(n). 불가 시 None."""
    if origin_id not in states or dest_id not in states:
        return None
    if origin_id == dest_id:
        return 1
    cache_key = (origin_id, dest_id)
    cached = STATE_PATH_CACHE.get(cache_key, _STATE_PATH_CACHE_MISS)
    if cached is not _STATE_PATH_CACHE_MISS:
        return cached  # type: ignore[return-value]
    visited = {origin_id}
    frontier = deque([(origin_id, 1)])
    result: Optional[int] = None
    while frontier:
        current, depth = frontier.popleft()
        current_state = states.get(current)
        if not current_state:
            continue
        for neighbor in current_state.neighbors:
            if neighbor not in states:
                continue
            if neighbor == dest_id:
                result = depth + 1
                frontier.clear()
                break
            if neighbor in visited:
                continue
            visited.add(neighbor)
            frontier.append((neighbor, depth + 1))
        if result is not None:
            break
    STATE_PATH_CACHE[cache_key] = result
    # 무향 그래프이므로 역방향도 동일
    STATE_PATH_CACHE[(dest_id, origin_id)] = result
    return result


def oceans_sea_connected(origin_ocean: Optional[str], dest_ocean: Optional[str]) -> bool:
    """두 연안 주의 ocean_connection이 해상 항로로 이어지는지 (preset_worlds.json ocean_links)."""
    if not origin_ocean or not dest_ocean:
        return True
    if origin_ocean == dest_ocean:
        return True
    linked = OCEAN_LINKS.get(origin_ocean)
    if linked is None:
        linked = OCEAN_LINKS.get(dest_ocean)
    if linked is None:
        return True
    return dest_ocean in linked


def sea_route_available(origin: "State", dest: "State") -> bool:
    if not origin.coastal or not dest.coastal:
        return False
    return oceans_sea_connected(origin.ocean_connection, dest.ocean_connection)


def trade_land_unit_transport_cost(
    path_segments: int,
    vehicle_price: float,
    rail_price: float,
    logistics_price: float,
    weight: float,
    rail_available: Optional[float] = None,
    quantity: float = 1.0,
) -> float:
    """육로만 단위 운송비 (해상·항구 제외)."""
    segments = max(1, int(path_segments))
    need_rail_per_unit = 0.02 * segments * weight
    need_rail_total = need_rail_per_unit * quantity
    rail_cap = rail_available if rail_available is not None else need_rail_total
    rail_share = clamp(rail_cap / max(need_rail_total, 1e-9), 0.0, 1.0)
    segment = 0.0
    for idx in range(segments):
        n = idx + 1
        road_cost = vehicle_price * 0.01 * road_segment_distance_factor(n)
        rail_cost = rail_price * 0.02
        segment += road_cost * (1.0 - rail_share) + min(road_cost, rail_cost) * rail_share
    handling = logistics_price * LOGISTICS_HANDLING_RATIO * weight
    return segment + handling


def trade_sea_unit_transport_cost(
    ship_price: float,
    logistics_price: float,
    weight: float,
    port_cost: float = 0.0,
) -> float:
    """해상만 단위 운송비 (육로 구간 제외)."""
    handling = logistics_price * LOGISTICS_HANDLING_RATIO * weight
    return ship_price * 0.01 + max(0.0, float(port_cost or 0.0)) + handling


def trade_choose_transport_mode(
    source: "State",
    dest: "State",
    path_len: Optional[int],
    vehicle_price: float,
    rail_price: float,
    ship_price: float,
    logistics_price: float,
    weight: float,
    rail_available: Optional[float] = None,
    quantity: float = 1.0,
) -> Tuple[bool, int, float]:
    """육로 vs 해상 단가 비교로 모드 선택.

    Returns:
        (use_sea, effective_path_len, unit_transport_cost)
    육로 불가·해상만 가능 → 해상. 둘 다 가능하면 싼 쪽. 해상 선택 시
    path_len은 표시용으로 유지하되 실행 시 차량·도로 수요는 0.
    """
    sea_ok = sea_route_available(source, dest)
    land_ok = path_len is not None
    if not land_ok and not sea_ok:
        return False, 1, 1e9
    port_cost = logistics_port_handling_cost(
        ship_price, source.infrastructure.get("port", 1.0)) if sea_ok else 0.0
    land_cost = None
    if land_ok:
        land_cost = trade_land_unit_transport_cost(
            int(path_len), vehicle_price, rail_price, logistics_price, weight,
            rail_available=rail_available, quantity=quantity)
    sea_cost = None
    if sea_ok:
        sea_cost = trade_sea_unit_transport_cost(
            ship_price, logistics_price, weight, port_cost=port_cost)
    if land_ok and sea_ok:
        assert land_cost is not None and sea_cost is not None
        if sea_cost + 1e-12 < land_cost:
            return True, int(path_len), float(sea_cost)
        return False, int(path_len), float(land_cost)
    if sea_ok:
        eff_len = int(path_len) if land_ok else 1
        return True, eff_len, float(sea_cost or 1e9)
    return False, int(path_len or 1), float(land_cost or 1e9)


# ---------------------------------------------------------------------------
# 주문 / 결과
# ---------------------------------------------------------------------------
class BuyOrder:
    def __init__(self, buyer_id: str, quantity: float, created_time: str = "now",
                 fx_home: str = "", fx_foreign: str = "", allow_loan: bool = False,
                 reservation_price: float = 0.0, source: str = "",
                 purpose: str = "", priority: int = 0,
                 is_buyback: bool = False, price_intent: str = "",
                 is_treasury_hold: bool = False):
        self.buyer_id = buyer_id
        self.quantity = float(quantity)
        self.created_time = created_time
        self.fx_home = fx_home
        self.fx_foreign = fx_foreign
        self.allow_loan = bool(allow_loan)
        # 상품 이중앵커: 지불의사(WTP). 0이면 VWAP_WTP 집계에서 제외
        self.reservation_price = float(reservation_price)
        # "subcontract" = 하청 섀도 주문 (가격·물량 반영, 공개 매칭 제외)
        self.source = str(source or "")
        # 부동산 실수요: construction|housing_need|office_need|invest|lp
        self.purpose = str(purpose or "")
        self.priority = int(priority or 0)
        # 발행사 자사주 매입(체결 시 소각) — 방어 비소각은 is_treasury_hold
        self.is_buyback = bool(is_buyback)
        # 방어용 자사주: 소각 없이 treasury 보유
        self.is_treasury_hold = bool(is_treasury_hold)
        # 주식 가격영향: raise|lower|neutral|force_raise|force_lower (빈값이면 purpose 추론)
        self.price_intent = str(price_intent or "")
        if self.priority <= 0 and self.purpose:
            self.priority = int(RE_PURPOSE_PRIORITY.get(self.purpose, 40))


class SellOrder:
    def __init__(self, seller_id: str, quantity: float, tech_level: int = 1,
                 created_time: str = "now", net_income: float = 0.0, bond_balance: float = 0.0,
                 is_foreign: bool = False, fx_home: str = "", fx_foreign: str = "",
                 is_fx_acquire: bool = False, is_treasury_issue: bool = False,
                 unit_cost: float = 0.0, source: str = "",
                 seller_age: float = 0.0, ask_price: float = 0.0,
                 purpose: str = "", from_labor_cascade: bool = False,
                 price_intent: str = ""):
        self.seller_id = seller_id
        self.quantity = float(quantity)
        self.tech_level = int(tech_level)
        self.created_time = created_time
        self.net_income = float(net_income)
        self.bond_balance = float(bond_balance)
        self.is_foreign = bool(is_foreign)
        self.fx_home = fx_home
        self.fx_foreign = fx_foreign
        self.is_fx_acquire = bool(is_fx_acquire)
        self.is_treasury_issue = bool(is_treasury_issue)
        # 상품 이중앵커: 생산/도착 단위원가. 0이면 VWAPC 집계에서 제외
        self.unit_cost = float(unit_cost)
        # 기업 호가(상품). 0이면 매칭 시 시장 기준가/균등 가중으로 fallback
        self.ask_price = float(ask_price or 0.0)
        self.source = str(source or "")
        # 노동 연령가중 매칭용 (0이면 연령 가중 미적용)
        self.seller_age = float(seller_age or 0.0)
        # 부동산 등: construction|housing_need|invest|lp
        self.purpose = str(purpose or "")
        # 학력 캐스케이드(고등→기본→미교육)로 내려온 미체결 매도
        self.from_labor_cascade = bool(from_labor_cascade)
        # 주식 가격영향: raise|lower|neutral|force_raise|force_lower
        self.price_intent = str(price_intent or "")


