# ---------------------------------------------------------------------------
# 시장 상태 및 체결
# ---------------------------------------------------------------------------
class MarketState:
    """상품·노동력 시장"""
    def __init__(self, state_id: str, item_type: str, base_price: float = 100.0):
        self.state_id = state_id
        self.item_type = item_type
        self.base_volume = 10.0
        self.base_price = base_price
        self.last_current_price = base_price
        self.current_price = base_price
        # 수요·WTP용 완만 기준가 (EMA). 초기값은 base_price.
        self.price_ref = base_price
        self.price_change_history: List[float] = []
        self.buy_orders: List[BuyOrder] = []
        self.sell_orders: List[SellOrder] = []
        self.buy_order_results: List[BuyResult] = []
        self.sell_order_results: List[SellResult] = []
        self.order_imbalance_history: deque = deque(maxlen=5)
        self.facility_order_imbalance_history: deque = deque(maxlen=5)
        # 시설 건설 수요 예측용 주간 매수 시계열 (이산 미분)
        self.facility_buy_volume_history: deque = deque(maxlen=FACILITY_BUY_HISTORY_WEEKS)
        self.last_supply_demand_ratio: Optional[float] = None
        # 호가용 수급비·원자재 원가 상태 (매주 관측값 쪽으로 갭의 1/4만 이동)
        self.ask_sd_ratio: float = 1.0
        self.cost_input_price: float = 0.0
        self.last_buy_volume = 0.0
        self.last_sell_volume = 0.0
        self.last_retail_price = base_price
        self.last_ask_vwap = base_price
        self.weekly_price_history: deque = deque(maxlen=None)
        self.weekly_sd_history: deque = deque(maxlen=None)
        # 상품 이중앵커 디버그·UI용 (노동·금융 시장은 0)
        self.last_vwap_cost = 0.0
        self.last_vwap_wtp = 0.0
        # 하청 이행 물량·단가 (가격 반영용 통계)
        self.last_subcontract_volume = 0.0
        self.last_subcontract_vwap = 0.0
        # 노동 임금 산정 전용: 폐쇄 시설 등으로 실제 주문 없이 매수(수요)를 가산
        self.wage_price_buy_boost = 0.0
        # 노동 체결 단가 (최저임금 floor 반영). 실질 시세는 current_price.
        self.labor_settlement_wage = 0.0


class StockMarketState(MarketState):
    """주식 시장"""
    def __init__(self, company_id: str, base_price: float = INITIAL_STOCK_PRICE):
        super().__init__(company_id, "STOCK", clamp_stock_price(base_price))
        self.company_id = company_id
        self.weekly_price_history: deque = deque(maxlen=FINANCIAL_CHART_HISTORY_WEEKS)
        self.invest_bias: float = 0.0
        self.trend_dir: str = "FLAT"
        self.trend_count: int = 0
        self.usual_order_volume: float = 0.0
        self.issued_shares: float = 0.0
        self.reversion_pull_memory: float = 0.0
        self.realized_vol_ema: float = float(STOCK_PRICE_NOISE_BASE)
        # 혼합 FV(DCF/PER/FCF) 캐시 — 가격 회귀 앵커 (시세와 별개)
        self.fair_value: float = clamp_stock_price(base_price)
        # 누적 액면분할·병합 가격 배수 (차트 adjusted close 추적용, 1=미조정)
        self.split_adjust_factor: float = 1.0


class RealEstateMarketState(MarketState):
    """주 단위 부동산 로컬 시장 (토지·주택·다세대·다용도·기업시설 분류)."""

    def __init__(self, state_id: str, kind: str, base_price: float = 1000.0):
        super().__init__(state_id, f"RE_{kind}", base_price)
        self.kind = kind
        self.weekly_price_history: deque = deque(maxlen=FINANCIAL_CHART_HISTORY_WEEKS)
        self.stock_outstanding = 0.0
        self.vacant_land_float = 0.0
        self.last_matched_volume = 0.0
        self.last_cap_rate = RE_CAP_PREMIUM.get(kind, 0.03) + 0.035
        self.fair_value = base_price
        self.replacement_cost = base_price
        self.liquidity_score = 0.5
        self.last_noi_annual = 0.0
        self.vacancy_weeks = 0
        self.utilization = 1.0
        # 주간 수급 주체 스냅샷 (최근 한 달)
        self.participant_week_history: deque = deque(maxlen=RE_PARTICIPANT_HISTORY_WEEKS)
        # 순수급·게이트용 주간 수급 이력 (buy/sell/matched/unmet/primary_sell/other_sell)
        self.sd_week_history: deque = deque(maxlen=max(
            RE_BUY_PRESENCE_WINDOW_WEEKS, RE_UNMET_WINDOW_WEEKS, 16))


