def create_stock_combined_chart(
    world: "World",
    country_id: str,
    *,
    issuer_id: str = "",
) -> Optional[io.BytesIO]:
    """주식 캔들 차트(상단) + 수급/거래 현황 패널(하단) 단일 이미지."""
    if issuer_id == STOCK_INDEX_ISSUER_ID:
        issuer_id = ""
    country = world.countries.get(country_id)
    if not country:
        return None

    if issuer_id:
        label, _, _ = describe_stock_issuer(world, issuer_id)
        candles = _issuer_stock_candles(world, issuer_id)
        weekly_prices = _stock_weekly_prices(world, issuer_id)
        chart_title = label
        ylabel = "가격"
        market = world.stock_markets.get(issuer_id)
        has_trading_panel = market is not None
        sections = []
    else:
        label = ""
        category = ""
        candles = _country_stock_index_candles(world, country_id)
        weekly_prices = _country_stock_index_weekly(world, country_id)
        chart_title = country_stock_index_label(country_id)
        ylabel = "지수"
        has_trading_panel = False
        sections = country_stock_market_sections(world, country_id, include_index=False)

    has_chart = bool(candles)
    has_supply_panel = bool(sections) and not issuer_id
    has_bottom_panel = has_supply_panel or has_trading_panel
    if not has_chart and not has_bottom_panel:
        return None

    import matplotlib
    matplotlib.use("Agg")
    _configure_project_matplotlib_font()
    import matplotlib.pyplot as plt

    chart_height = 7.0 if has_chart else 0.0
    if has_supply_panel:
        panel_height = _stock_supply_panel_height(sections)
    elif has_trading_panel:
        panel_height = _STOCK_TRADING_PANEL_HEIGHT_INCH
    else:
        panel_height = 0.0
    panel_gap = (
        _STOCK_SUPPLY_CHART_GAP_INCH if has_chart and has_bottom_panel else 0.0
    )
    fig_height = (
        _STOCK_FIG_TOP_INCH + chart_height + panel_gap
        + panel_height + _STOCK_FIG_BOTTOM_INCH
    )
    fig = plt.figure(figsize=(14.5, max(fig_height, 3.5)))
    fig.patch.set_facecolor(_STOCK_CHART_BG)

    bottom_frac = _STOCK_FIG_BOTTOM_INCH / fig_height
    panel_top_frac = bottom_frac
    if has_bottom_panel:
        panel_frac = panel_height / fig_height
        panel_rect = [0.04, bottom_frac, 0.92, panel_frac]
        if has_supply_panel:
            ax_supply = fig.add_axes(panel_rect)
            _draw_stock_supply_panel_on_ax(
                ax_supply, sections, label_header="종목", label_max_len=19,
            )
        else:
            _draw_stock_trading_status_in_rect(
                fig, panel_rect, world, issuer_id,
                title="거래 현황",
            )
        panel_top_frac = bottom_frac + panel_frac

    if has_chart:
        gap_frac = panel_gap / fig_height if has_bottom_panel else 0.0
        chart_frac = chart_height / fig_height
        chart_bottom = panel_top_frac + gap_frac
        ax_chart = fig.add_axes([0.06, chart_bottom, 0.88, chart_frac])
        _draw_stock_candle_ma_on_ax(
            ax_chart, candles, title=chart_title, ylabel=ylabel,
            weekly_prices=weekly_prices,
            start_year=world_start_year(world),
        )

    buf = io.BytesIO()
    plt.savefig(
        buf, format="png", facecolor=fig.get_facecolor(),
        bbox_inches="tight", pad_inches=0.04,
    )
    buf.seek(0)
    plt.close(fig)
    return buf


def _bond_market_candles_or_fallback(
    world: "World", market_key_id: str,
) -> List[Dict[str, float]]:
    candles = _bond_market_candles(world, market_key_id)
    if candles:
        return candles
    market = world.bond_markets.get(market_key_id)
    if not market:
        return []
    rate = float(market.current_interest_rate or 0.0)
    if rate <= 0:
        return []
    return [{
        "week_start": world.week,
        "week_end": world.week,
        "open": rate,
        "high": rate,
        "low": rate,
        "close": rate,
    }]


def create_bond_combined_chart(
    world: "World",
    country_id: str,
    *,
    market_key_id: str = "",
) -> Optional[io.BytesIO]:
    """채권 금리 차트(상단) + 수급/거래 현황 패널(하단) 단일 이미지."""
    country = world.countries.get(country_id)
