_ITEM_IMAGE_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "item_image")
_ITEM_IMAGE_CACHE: Dict[str, Optional[Any]] = {}


def _item_image_candidates(product_name: str) -> List[str]:
    name = (product_name or "").strip()
    if not name:
        return []
    variants: List[str] = []
    for variant in (name, name.replace(" ", "_"), name.replace(" ", "")):
        if variant and variant not in variants:
            variants.append(variant)
    return [os.path.join(_ITEM_IMAGE_DIR, f"{variant}.png") for variant in variants]


def _item_image_lookup_names(product_name: str) -> List[str]:
    name = (product_name or "").strip()
    if not name:
        return []
    names = [name]
    for prefix in ("선택·", "노동·"):
        if name.startswith(prefix):
            stripped = name[len(prefix):].strip()
            if stripped and stripped not in names:
                names.append(stripped)
    return names


def _resolve_item_image_path(product_name: str) -> Optional[str]:
    for lookup in _item_image_lookup_names(product_name):
        for path in _item_image_candidates(lookup):
            if os.path.isfile(path):
                return path
    return None


def _load_item_image_rgba(path: str) -> Optional[Any]:
    import matplotlib.pyplot as plt
    import numpy as np

    if path in _ITEM_IMAGE_CACHE:
        return _ITEM_IMAGE_CACHE[path]
    try:
        arr = plt.imread(path)
        if arr.ndim == 2:
            arr = np.stack([arr, arr, arr, np.ones_like(arr)], axis=-1)
        elif arr.shape[-1] == 3:
            alpha = np.ones((*arr.shape[:2], 1), dtype=arr.dtype)
            arr = np.concatenate([arr, alpha], axis=-1)
        _ITEM_IMAGE_CACHE[path] = arr
        return arr
    except (OSError, ValueError):
        _ITEM_IMAGE_CACHE[path] = None
        return None


def _chart_points_to_axes_x(ax, points: float) -> float:
    pos = ax.get_position()
    fig = ax.get_figure()
    ax_w_in = fig.get_figwidth() * pos.width
    return (points / 72.0) / max(ax_w_in, 1e-9)


def _draw_company_panel_row_label(
    ax,
    x: float,
    y: float,
    label: str,
    *,
    product: Optional[str] = None,
    font,
    fontsize: int = 8,
    max_len: int = 10,
    color: str = _STOCK_CHART_TEXT,
    valign: str = "center",
) -> None:
    """상품 아이콘(텍스트 높이) + 라벨."""
    from matplotlib.offsetbox import AnnotationBbox, OffsetImage

    short_label = _short_pie_label(label, max_len=max_len)
    text_x = x
    lookup_name = (product or label or "").strip()
    img_path = _resolve_item_image_path(lookup_name)
    box_alignment = (0.0, 0.5 if valign == "center" else 1.0)
    if img_path:
        img_arr = _load_item_image_rgba(img_path)
        if img_arr is not None:
            zoom = fontsize / img_arr.shape[0]
            icon = OffsetImage(img_arr, zoom=zoom)
            ax.add_artist(AnnotationBbox(
                icon,
                (x, y),
                xycoords=ax.transAxes,
                box_alignment=box_alignment,
                pad=0.0,
                frameon=False,
                zorder=4,
            ))
            icon_w_pt = img_arr.shape[1] * zoom
            text_x = x + _chart_points_to_axes_x(ax, icon_w_pt + max(2.0, fontsize * 0.2))

    ax.text(
        text_x, y, short_label,
        transform=ax.transAxes, va=valign, ha="left",
        color=color, fontproperties=font, fontsize=fontsize,
        zorder=5,
    )


def _company_panel_bar_dims(ax) -> Tuple[float, float]:
    """작은 서브플롯에서도 다른 패널과 동일한 픽셀 크기 막대."""
    pos = ax.get_position()
    bar_w = clamp(
        _COMPANY_PANEL_BAR_MAX_W * _COMPANY_PANEL_REF_AX_WIDTH / max(pos.width, 1e-9),
        _COMPANY_PANEL_BAR_MAX_W,
        0.96,
    )
    bar_h = clamp(
        _COMPANY_PANEL_BAR_H * _COMPANY_PANEL_REF_AX_HEIGHT / max(pos.height, 1e-9),
        _COMPANY_PANEL_BAR_H,
        0.34,
    )
    return bar_w, bar_h


def _finance_chart_ylim(
    values: List[float], *, pad_ratio: float = 0.14, min_pad: float = 1.0,
) -> Tuple[float, float]:
    """데이터 범위에 맞춘 비대칭 Y축 — 0선은 항상 실제 0 위치."""
    if not values:
        return -min_pad, min_pad
    vmin = min(values)
    vmax = max(values)
    pad = max((vmax - vmin) * pad_ratio, min_pad)
    low = vmin - pad
    high = vmax + pad
    if vmin < 0 < vmax:
        low = min(low, -pad * 0.08)
        high = max(high, pad * 0.08)
    elif vmin >= 0:
        low = max(0.0, vmin - pad)
    elif vmax <= 0:
        high = min(0.0, vmax + pad)
    return low, high


def _company_panel_fit_rows(
    rows: List[Dict[str, Any]],
    *,
    height: float,
    max_rows: Optional[int] = None,
    min_row_h: float = _COMPANY_PANEL_MIN_ROW_H,
    max_row_h: float = _COMPANY_PANEL_MAX_ROW_GAP,
) -> Tuple[List[Dict[str, Any]], float]:
    """행 수에 맞춰 간격을 계산하고, 너무 촘촘하면 행 수를 줄인다."""
    if not rows:
        return [], height
    max_fit = max(1, int(height / min_row_h))
    if max_rows is not None:
        max_fit = min(max_fit, max_rows)
    display_rows = rows[:max_fit]
    row_h = height / max(len(display_rows), 1)
    row_h = min(row_h, max_row_h)
    return display_rows, row_h


def _finance_chart_calendar_ctx(company: "Company") -> Tuple[Optional[int], int]:
    world = getattr(company, "_world_ref", None)
    if world is None:
        return None, 1960
    return int(getattr(world, "week", 0) or 0), world_start_year(world)


def _aggregate_finance_chart_buckets(
    series: List[float],
    *,
    weeks_per_bar: int = _COMPANY_FINANCE_CHART_WEEKS_PER_BAR,
    max_bars: int = _COMPANY_FINANCE_CHART_MAX_BARS,
    world_week: Optional[int] = None,
    start_year: int = 1960,
) -> Tuple[List[float], List[str]]:
    """주간 시계열을 N주 평균 막대(최대 max_bars개)로 묶는다. X축은 날짜."""
    if not series:
        return [0.0], ["—"]
    window = series[-weeks_per_bar * max_bars:]
    end_week = int(world_week) if world_week is not None else (len(series) - 1)
    start_week = end_week - len(window) + 1
    bars: List[float] = []
    labels: List[str] = []
    for start in range(0, len(window), weeks_per_bar):
        chunk = window[start:start + weeks_per_bar]
        if not chunk:
            continue
        bars.append(sum(chunk) / len(chunk))
        w_end = start_week + start + len(chunk) - 1
        labels.append(week_to_date_label(w_end, start_year))
    if not bars:
        return [0.0], ["—"]
    return bars, labels


def company_weekly_facility_metrics(company: "Company") -> Tuple[float, float]:
    """주간 시설 수·산출(또는 소매/무역 실적) 스냅샷."""
    if isinstance(company, RetailCompany):
        count = float(len(company.state_weekly_volume or {}))
        output = float(company.weekly_retail_volume or 0.0)
    elif company.type == "물류 기업":
        routes = getattr(company, "active_trade_routes", []) or []
        count = float(len(routes))
        output = float(sum(float(r.get("actual_qty", 0.0) or 0.0) for r in routes))
    else:
        count = float(company.total_production_levels())
        output = float(company.last_production or 0.0)
    return count, output


def _company_facility_chart_series(
    company: "Company",
) -> Tuple[List[float], List[float]]:
    """시설 수·산출 주간 이력 (차트용)."""
    count_series = list(getattr(company, "weekly_facility_count_history", []))
    output_series = list(getattr(company, "weekly_facility_output_history", []))
    cur_count, cur_output = company_weekly_facility_metrics(company)
    if not count_series:
        count_series = [cur_count]
    elif abs(count_series[-1] - cur_count) > 1e-6:
        count_series = count_series + [cur_count]
    if not output_series:
        output_series = [cur_output]
    elif abs(output_series[-1] - cur_output) > 1e-6:
        output_series = output_series + [cur_output]
    max_weeks = _COMPANY_FINANCE_CHART_HISTORY_WEEKS
    length = min(max_weeks, max(len(count_series), len(output_series)))
    count_series = count_series[-length:]
    output_series = output_series[-length:]
    while len(output_series) < len(count_series):
        output_series.insert(0, output_series[0] if output_series else 0.0)
    while len(count_series) < len(output_series):
        count_series.insert(0, count_series[0] if count_series else 0.0)
    return count_series, output_series


def _draw_company_panel_dual_bar_row(
    ax,
    *,
    y_center: float,
    label: str,
    required: float,
    filled: float,
    bar_color: str,
    text_color: str,
    scale: float,
    inner_text: str,
    bar_max_w: Optional[float] = None,
    bar_h: Optional[float] = None,
    product: Optional[str] = None,
) -> None:
    """회색(필요) + 색상(체결) 이중 막대 — 거래 현황 차트와 동일한 가로형 레이아웃."""
    small_font = _load_project_chart_font(size=8)
    tiny_font = _load_project_chart_font(size=7)
    _draw_company_panel_row_label(
        ax, _COMPANY_PANEL_LABEL_X, y_center, label,
        product=product, font=small_font, fontsize=8, max_len=10,
    )
    if bar_max_w is None:
        bar_max_w = _COMPANY_PANEL_BAR_MAX_W
    if bar_h is None:
        bar_h = _COMPANY_PANEL_BAR_H
    if scale <= 1e-9:
        scale = 1.0
    gray_w = bar_max_w
    fill_ratio = clamp(filled / max(required, 1e-9), 0.0, 1.0)
    fill_w = bar_max_w * fill_ratio
    _stock_trading_rounded_bar(
        ax, _COMPANY_PANEL_BAR_X, y_center, gray_w, bar_h,
        _COMPANY_BAR_MAX_COLOR, alpha=0.26,
    )
    if filled > 1e-6:
        fill_w = max(fill_w, bar_h * 1.6)
        _stock_trading_rounded_bar(
            ax, _COMPANY_PANEL_BAR_X, y_center, fill_w, bar_h,
            bar_color, alpha=0.26,
        )
    ax.text(
        _COMPANY_PANEL_BAR_X + _COMPANY_PANEL_BAR_TEXT_PAD, y_center, inner_text,
        transform=ax.transAxes, va="center", ha="left",
        color=text_color, fontproperties=tiny_font, fontsize=7,
        **_chart_bold_text_kwargs(),
    )


