def _company_labor_input_row(
    world: "World", company: "Company",
) -> Dict[str, Any]:
    """노동력 투입 — 필요 인원 대비 실제 체결."""
    needed = 0.0
    filled = 0.0

    if isinstance(company, RetailCompany):
        needed = max(float(company.employees), 1.0)
        filled = max(float(company.filled_employees), 0.0)
        if filled <= 1e-6:
            filled = needed * float(company.last_labor_fill_ratio or 0.0)
    else:
        office_active = (
            company.office_labor_slots()
            if hasattr(company, "office_labor_slots")
            else float(max(0, company.office_levels - company.office_closed))
        )
        if office_active > 1e-9:
            ltype, lqty = OFFICE_SPEC["labor"]
            office_needed = float(lqty) * office_active
            needed += office_needed
            filled += allocate_company_labor_fill(
                company, company.home_state, str(ltype), office_needed)
        for fac in company.facilities:
            if fac.is_office or fac.active_levels() <= 0:
                continue
            spec = FACILITY_SPECS.get(fac.name, {})
            labor_req = spec.get("labor") if spec else None
            if not labor_req:
                continue
            ltype, lqty = labor_req
            fac_needed = float(lqty) * fac.active_levels()
            needed += fac_needed
            filled += allocate_company_labor_fill(
                company, fac.state_id, str(ltype), fac_needed)
        if needed <= 1e-6:
            needed = 1.0
            filled = float(company.last_labor_fill_ratio or 0.0)

    return {
        "label": "노동력",
        "required": max(needed, 1e-9),
        "filled": filled,
        "ratio": max(filled / max(needed, 1e-9), 0.0),
        "kind": "labor",
    }


def _company_input_row_dict(
    item: str, need: float, actual: float, *, kind: str,
) -> Dict[str, Any]:
    return {
        "label": _short_pie_label(item, 12),
        "product": item,
        "required": max(need, 1e-9),
        "filled": actual,
        "ratio": max(actual / max(need, 1e-9), 0.0),
        "kind": kind,
    }


def _company_input_product_rows(
    world: "World", company: "Company",
) -> Tuple[Dict[str, Any], List[Dict[str, Any]], List[Dict[str, Any]]]:
    """(노동력, 필수 투입, 비필수 투입) — 필요량(회색) 대비 실제 체결량(색)."""
    labor_row = _company_labor_input_row(world, company)
    if isinstance(company, RetailCompany) or company.type == "물류 기업":
        essential, optional = _company_purchase_fill_rows_split(world, company)
        return labor_row, essential, optional

    essential_required: Dict[str, float] = defaultdict(float)
    optional_required: Dict[str, float] = defaultdict(float)
    markets = world.markets
    efficiency = company.production_efficiency_factor()
    office_active = (
        company.office_labor_slots()
        if hasattr(company, "office_labor_slots")
        else float(max(0, company.office_levels - company.office_closed))
    )
    if office_active > 1e-9:
        ol = OFFICE_SPEC.get("labor")
        office_labor_scale = 1.0
        if ol:
            ol_type, ol_qty = ol
            office_needed = float(ol_qty) * office_active
            office_filled = allocate_company_labor_fill(
                company, company.home_state, str(ol_type), office_needed)
            if office_needed > 1e-9:
                office_labor_scale = clamp(office_filled / office_needed, 0.0, 1.0)
        for item, qty in OFFICE_SPEC.get("inputs", {}).items():
            essential_required[item] += float(qty) * office_active * office_labor_scale
        rental_need = max(0.0, float(getattr(company, "_office_rental_need", 0.0) or 0.0))
        if rental_need <= 1e-9 and hasattr(company, "office_slots_required"):
            gap = max(
                0.0,
                float(company.office_slots_required()) - float(company.owned_office_slots()),
            )
            rental_need = gap * RE_RENTAL_PER_OFFICE_SLOT
        if rental_need > 1e-9:
            essential_required["임대 서비스"] += rental_need
    for fac in company.facilities:
        if fac.is_office or fac.active_levels() <= 0:
            continue
        spec = FACILITY_SPECS.get(fac.name, {})
        if not spec:
            continue
        site_eff = facility_site_resource_efficiency(
            fac.name, fac.state_id, spec=spec, company=company)
        needs = company._input_requirements_with_substitution(
            fac, spec, markets, site_eff=site_eff)
        for item, qty in needs.items():
            essential_required[item] += qty * efficiency
        for item, per_level in spec.get("optional", {}).items():
            optional_required[item] += (
                per_level * fac.active_levels() * efficiency * site_eff)

    filled_map = getattr(company, "last_week_goods_filled", {}) or {}
    essential_rows: List[Dict[str, Any]] = []
    for item in sorted(
        set(essential_required) | set(filled_map),
        key=lambda k: (-essential_required.get(k, 0.0), k),
    ):
        if item in optional_required:
            continue
        need = float(essential_required.get(item, 0.0))
        actual = float(filled_map.get(item, 0.0))
        if need <= 1e-6 and actual <= 1e-6:
            continue
        essential_rows.append(_company_input_row_dict(item, need, actual, kind="essential"))
    essential_rows.sort(key=lambda row: (-row["required"], row["label"]))

    optional_rows: List[Dict[str, Any]] = []
    for item in sorted(
        set(optional_required) | set(filled_map),
        key=lambda k: (-optional_required.get(k, 0.0), k),
    ):
        if item in essential_required:
            continue
        need = float(optional_required.get(item, 0.0))
        actual = float(filled_map.get(item, 0.0))
        if need <= 1e-6 and actual <= 1e-6:
            continue
        optional_rows.append(_company_input_row_dict(item, need, actual, kind="optional"))
    optional_rows.sort(key=lambda row: (-row["required"], row["label"]))

    return (
        labor_row,
        essential_rows[:_COMPANY_PANEL_TOP_N],
        optional_rows[:_COMPANY_PANEL_OPTIONAL_N],
    )


def _company_purchase_fill_rows_split(
    world: "World", company: "Company",
) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """시장 매수 주문 기준 — 필수·비필수 분리."""
    ordered_by_item: Dict[str, float] = defaultdict(float)
    filled_by_item: Dict[str, float] = defaultdict(float)
    for mk, market in world.markets.items():
        if "::" not in mk:
            continue
        item = mk.split("::", 1)[1]
        ordered = sum(
            o.quantity for o in market.buy_orders if o.buyer_id == company.id)
        filled = sum(
            br.filled_quantity for br in market.buy_order_results
            if br.buyer_id == company.id)
        if ordered <= 1e-6 and filled <= 1e-6:
            continue
        ordered_by_item[item] += ordered
        filled_by_item[item] += filled

    essential_rows: List[Dict[str, Any]] = []
    optional_rows: List[Dict[str, Any]] = []
    for item in sorted(
        set(ordered_by_item) | set(filled_by_item),
        key=lambda k: (-ordered_by_item.get(k, 0.0), k),
    ):
        need = float(ordered_by_item.get(item, 0.0))
        actual = float(filled_by_item.get(item, 0.0))
        if need <= 1e-6 and actual <= 1e-6:
            continue
        row = _company_input_row_dict(
            item, max(need, actual, 1e-9), actual,
            kind="optional" if item in OPTIONAL_PRODUCTS else "essential",
        )
        if item in OPTIONAL_PRODUCTS:
            optional_rows.append(row)
        else:
            essential_rows.append(row)
    essential_rows.sort(key=lambda row: (-row["required"], row["label"]))
    optional_rows.sort(key=lambda row: (-row["required"], row["label"]))
    return essential_rows[:_COMPANY_PANEL_TOP_N], optional_rows[:_COMPANY_PANEL_OPTIONAL_N]


def _company_purchase_fill_rows(
    world: "World", company: "Company",
) -> List[Dict[str, Any]]:
    """시장 매수 주문 기준 — 주문량(회색) 대비 체결량(색)."""
    essential, optional = _company_purchase_fill_rows_split(world, company)
    return essential + optional


def _company_output_product_rows(
    world: "World", company: "Company",
) -> List[Dict[str, Any]]:
    """실제 생산(체결) 상품 — 최대 생산능력(회색) 대비 실제 산출(색)."""
    if isinstance(company, RetailCompany):
        rows = _company_retail_operation_rows(world, company)
        return [{
            "label": row["label"],
            "product": row.get("product"),
            "required": max(row["capacity"], row["output"], 1.0),
            "filled": row["output"],
            "ratio": row["utilization"],
        } for row in rows[:_COMPANY_PANEL_TOP_N]]

    if company.type == "물류 기업":
        rows = _company_logistics_operation_rows(company)
        return [{
            "label": row["label"],
            "product": row.get("product"),
            "required": max(row["capacity"], row["output"], 1.0),
            "filled": row["output"],
            "ratio": row["utilization"],
        } for row in rows[:_COMPANY_PANEL_TOP_N]]

    product_output: Dict[str, float] = defaultdict(float)
    product_capacity: Dict[str, float] = defaultdict(float)
    for fac in company.facilities:
        if fac.is_office or fac.active_levels() <= 0:
            continue
        spec = FACILITY_SPECS.get(fac.name, {})
        product = spec.get("output") if spec else None
        if not product:
            continue
        capacity = max(fac.base_output(), 1e-9)
        output = float(fac.planned_weekly_output or 0.0)
        if output <= 1e-6:
            output = (
                capacity
                * float(company.last_efficiency or 1.0)
                * float(fac.actual_input_fill or 1.0)
                * labor_output_factor(float(company.last_labor_fill_ratio or 1.0))
            )
        product_capacity[product] += capacity
        product_output[product] += output

    rows: List[Dict[str, Any]] = []
    for product in sorted(product_capacity.keys(), key=lambda p: -product_output.get(p, 0.0)):
        need = product_capacity[product]
        actual = product_output[product]
        rows.append({
            "label": _short_pie_label(product, 12),
            "product": product,
            "required": max(need, 1e-9),
            "filled": actual,
            "ratio": max(actual / max(need, 1e-9), 0.0),
        })
    return rows[:_COMPANY_PANEL_TOP_N]


def company_product_price_rows(
    world: "World", company: "Company",
) -> List[Dict[str, Any]]:
    """기업 생산 상품별 호가·원가·시장 체결가."""
    if isinstance(company, RetailCompany) or company.type == "물류 기업":
        return []
    by_product: Dict[str, Dict[str, Any]] = {}
    for fac in company.facilities:
        if getattr(fac, "is_office", False):
            continue
        if fac.active_levels() <= 0 and float(getattr(fac, "planned_weekly_output", 0.0) or 0.0) <= 1e-9:
            continue
        spec = FACILITY_SPECS.get(fac.name, {})
        product = spec.get("output")
        if not product:
            continue
        product = str(product)
        entry = by_product.get(product)
        if entry is None:
            by_product[product] = {
                "product": product,
                "states": set(),
                "output": 0.0,
                "labor_filled": 0.0,
                "labor_needed": 0.0,
                "labor_budget": 0.0,
            }
            entry = by_product[product]
        entry["states"].add(fac.state_id)
        out = float(getattr(fac, "planned_weekly_output", 0.0) or 0.0)
        if out <= 1e-9:
            active = float(fac.active_levels()) if hasattr(fac, "active_levels") else 0.0
            try:
                eff = float(company.production_efficiency_factor())
            except Exception:
                eff = float(getattr(company, "last_efficiency", 1.0) or 1.0)
            out = float(spec.get("output_qty", 1) or 1.0) * active * max(eff, 1e-6)
        entry["output"] += out
        filled = float(getattr(fac, "last_labor_filled", 0.0) or 0.0)
        needed = float(getattr(fac, "last_labor_needed", 0.0) or 0.0)
        if needed <= 1e-9:
            lr = spec.get("labor")
            active = float(fac.active_levels()) if hasattr(fac, "active_levels") else 0.0
            if lr and active > 1e-9:
                needed = float(lr[1]) * active
        entry["labor_filled"] += filled
        entry["labor_needed"] += needed
        # 시설별 노동시장 단가 기준 노동예산 (단위임금×산출과 동일 계열)
        uc_fac = facility_materials_unit_cost(
            spec, fac.state_id, world.markets, world.labor_markets)
        entry["labor_budget"] += (
            production_labor_unit_cost(
                uc_fac, product, str(getattr(company, "type", "") or ""),
                spec=spec, state_id=fac.state_id,
                labor_markets=world.labor_markets,
            ) * out
        )

    rows: List[Dict[str, Any]] = []
    for product, meta in sorted(
        by_product.items(), key=lambda kv: -float(kv[1].get("output", 0.0) or 0.0)
    ):
        states = list(meta["states"]) or [company.home_state]
        primary_state = (
            company.home_state if company.home_state in states else states[0]
        )
        ask_explain: Dict[str, Any] = {}
        ask, uc = company_product_ask_price(
            company, product, primary_state,
            world.markets, world.labor_markets,
            explain=ask_explain,
        )
        stored = (getattr(company, "product_ask_raise_reasons", None) or {}).get(product)
        if stored and stored.get("reasons"):
            ask_pack = stored
        else:
            ask_pack = format_company_product_ask_raise_reasons(
                ask_explain,
                (getattr(company, "product_ask_snapshot", None) or {}).get(product),
            )
        mk = world.markets.get(market_key(primary_state, product))
        market_p = market_settlement_price(mk) if mk else 0.0
        # 다주 생산 시 시장가는 체결량 가중
        if len(states) > 1:
            markets = [
                world.markets[market_key(sid, product)]
                for sid in states
                if market_key(sid, product) in world.markets
            ]
            if markets:
                market_p = market_volume_weighted_price(markets)
        ctype = str(getattr(company, "type", "") or "")
        margin_rate = float(industry_margin_target_mid(product, ctype) or 0.0)
        labor_share = float(industry_labor_share(product, ctype) or 0.0)
        wage_unit = production_labor_unit_cost(
            uc, product, ctype,
            spec=spec_for_output_product(product),
            state_id=primary_state,
            labor_markets=world.labor_markets,
        )
        # 호가 기준 실현 마진율 (재료+노동 대비, 표시용)
        full_uc = float(uc) + float(wage_unit)
        ask_margin_rate = (
            (float(ask) - full_uc) / float(ask) if float(ask) > 1e-9 else 0.0
        )
        # 대표 노동 자격의 기업 임금 offer (있으면)
        labor_type = ""
        wage_offer = 0.0
        for fac in company.facilities:
            if getattr(fac, "is_office", False) or fac.state_id != primary_state:
                continue
            fac_spec = FACILITY_SPECS.get(fac.name, {})
            if fac_spec.get("output") != product:
                continue
            lr = fac_spec.get("labor")
            if lr:
                labor_type = str(lr[0])
                break
        if labor_type:
            wage_offer = float(company_margin_labor_wage_offer(
                company, primary_state, labor_type,
                world.markets, world.labor_markets,
            ) or 0.0)
        # 시설 실지급: 기업이 해당 자격 노동에 실제 지급하는 1인당 단가
        wage_paid = 0.0
        if labor_type:
            lm = world.labor_markets.get(market_key(primary_state, labor_type))
            if lm is not None:
                wage_paid = float(labor_buyer_wage_price(world, lm, company.id) or 0.0)
            if wage_paid <= 1e-9:
                wage_paid = wage_offer
        # 시설 귀속 임금 = 노동예산(단위임금×산출) ÷ 배치인원
        workers = float(meta.get("labor_filled", 0.0) or 0.0)
        if workers <= 1e-9:
            workers = float(meta.get("labor_needed", 0.0) or 0.0)
        labor_budget = float(meta.get("labor_budget", 0.0) or 0.0)
        if labor_budget <= 1e-12:
            labor_budget = wage_unit * float(meta.get("output", 0.0) or 0.0)
        facility_wage = (labor_budget / workers) if workers > 1e-9 else 0.0
        rows.append({
            "product": product,
            "ask_price": round(float(ask), 2),
            "unit_cost": round(float(uc), 2),
            "market_price": round(float(market_p), 2),
            "margin_rate": round(margin_rate, 4),
            "ask_margin_rate": round(ask_margin_rate, 4),
            "labor_share": round(labor_share, 4),
            "wage_unit": round(wage_unit, 2),
            "wage_offer": round(wage_offer, 2),
            "wage_paid": round(wage_paid, 2),
            "facility_wage": round(facility_wage, 2),
            "labor_workers": round(workers, 2),
            "labor_type": labor_type,
            "output": round(float(meta.get("output", 0.0) or 0.0), 2),
            "state_id": primary_state,
            "raised": bool(ask_pack.get("raised")),
            "ask_change_pct": ask_pack.get("change_pct"),
            "last_ask": ask_pack.get("last_ask"),
            "raise_reasons": list(ask_pack.get("reasons") or []),
        })
    return rows


def _company_weekly_income_lines(
    world: "World", company: "Company",
) -> List[Tuple[str, float]]:
    """주간 수입 상세 — weekly_revenues 장부에서 직접 추출 (CapEx 매각 제외)."""
    detail = sorted(
        [(label, value) for label, value in company.weekly_revenues.items()
         if value > 1e-6 and not _is_company_capex_label(label)],
        key=lambda item: -item[1],
    )
    return detail[:8]


def _company_weekly_expense_lines(
    world: "World", company: "Company",
) -> List[Tuple[str, float]]:
    """주간 영업지출 상세 — CapEx(시설 매입·건설) 제외."""
    detail = sorted(
        [(label, value) for label, value in company.weekly_expenses.items()
         if value > 1e-6 and not _is_company_capex_label(label)],
        key=lambda item: -item[1],
    )
    return detail[:10]


def _company_flow_item_meta(label: str) -> Dict[str, Any]:
    """수입/지출 라벨 → UI 차트용 분류 (goods/labor/tax/other)."""
    lab = str(label or "").strip()
    if not lab:
        return {"kind": "other", "product": "", "labor_type": "", "channel": ""}
    if lab.startswith("노동·") or lab.startswith("노동 "):
        labor = lab.split("·", 1)[-1].strip() if "·" in lab else lab[2:].strip()
        return {
            "kind": "labor",
            "product": "",
            "labor_type": labor or lab,
            "channel": "",
        }
    if (
        "법인세" in lab
        or "재산세" in lab
        or "관세" in lab
        or lab.endswith("세")
        or "세금" in lab
    ):
        return {"kind": "tax", "product": "", "labor_type": "", "channel": ""}
    m = re.match(r"^(.+?)\s*\((내수|해외 수출)\)$", lab)
    if m:
        return {
            "kind": "goods",
            "product": m.group(1).strip(),
            "labor_type": "",
            "channel": m.group(2),
        }
    m_sc = re.match(r"^하청\s+(.+)$", lab)
    if m_sc:
        product = m_sc.group(1).strip()
        if product in PRODUCT_BASE_PRICES:
            return {
                "kind": "goods",
                "product": product,
                "labor_type": "",
                "channel": "하청",
            }
    m_coop = re.match(r"^협력\s+(?:가공|외주)\s+(.+)$", lab) or re.match(
        r"^협력\s+(.+)$", lab)
    if m_coop:
        product = m_coop.group(1).strip()
        if product in PRODUCT_BASE_PRICES:
            return {
                "kind": "goods",
                "product": product,
                "labor_type": "",
                "channel": "협력",
            }
    if lab in PRODUCT_BASE_PRICES:
        return {"kind": "goods", "product": lab, "labor_type": "", "channel": ""}
    return {"kind": "other", "product": "", "labor_type": "", "channel": ""}


def _company_flow_history_for_label(
    company: "Company",
    side: str,
    label: str,
    *,
    max_weeks: int = _COMPANY_FINANCE_CHART_HISTORY_WEEKS,
) -> List[float]:
    """항목별 주간 금액 시계열 (없으면 빈 목록)."""
    attr = (
        "weekly_revenue_detail_history"
        if side == "income"
        else "weekly_expense_detail_history"
    )
    hist = list(getattr(company, attr, None) or [])
    if not hist:
        return []
    out: List[float] = []
    for snap in hist[-max_weeks:]:
        if isinstance(snap, dict):
            out.append(round(float(snap.get(label, 0.0) or 0.0), 2))
        else:
            out.append(0.0)
    return out


def _company_flow_detail_rows(
    world: "World",
    company: "Company",
    side: str,
) -> List[Dict[str, Any]]:
    """API용 수입/지출 상세 행 (분류·히스토리 포함)."""
    lines = (
        _company_weekly_income_lines(world, company)
        if side == "income"
        else _company_weekly_expense_lines(world, company)
    )
    rows: List[Dict[str, Any]] = []
    for label, value in lines:
        meta = _company_flow_item_meta(label)
        hist = _company_flow_history_for_label(company, side, label)
        # 당주 값이 이력 끝에 없으면 붙여 UI가 바로 보이게 함
        cur = round(float(value or 0.0), 2)
        if not hist or abs(hist[-1] - cur) > 1e-6:
            hist = (hist + [cur])[-_COMPANY_FINANCE_CHART_HISTORY_WEEKS:]
        rows.append({
            "label": label,
            "value": cur,
            "kind": meta.get("kind", "other"),
            "product": meta.get("product", ""),
            "labor_type": meta.get("labor_type", ""),
            "channel": meta.get("channel", ""),
            "history": hist,
        })
    return rows


def _allocate_company_fx_export_income(
    company: "Company",
    pay_ccy: str,
    pay_nominal: float,
    gained: float,
) -> None:
    """외화→본국 환전 대금을 상품별 deferred_trade_income_by_product에 배분."""
    gained = float(gained or 0.0)
    if gained <= 1e-12:
        return
    company.deferred_trade_income = float(
        getattr(company, "deferred_trade_income", 0.0) or 0.0) + gained
    pending = getattr(company, "pending_export_fc_by_product", None)
    if not isinstance(pending, dict):
        company.pending_export_fc_by_product = {}
        pending = company.pending_export_fc_by_product
    by_prod = getattr(company, "deferred_trade_income_by_product", None)
    if not isinstance(by_prod, dict):
        company.deferred_trade_income_by_product = defaultdict(float)
        by_prod = company.deferred_trade_income_by_product
    keys = [
        k for k, v in pending.items()
        if isinstance(k, tuple) and len(k) >= 2
        and str(k[0]) == str(pay_ccy) and float(v or 0.0) > 1e-12
    ]
    total = sum(float(pending[k] or 0.0) for k in keys)
    if total <= 1e-12:
        return
    use = min(max(0.0, float(pay_nominal or 0.0)), total)
    if use <= 1e-12:
        return
    for k in keys:
        share = float(pending[k] or 0.0) / total
        take_fc = use * share
        pending[k] = max(0.0, float(pending[k] or 0.0) - take_fc)
        product = str(k[1] or "").strip()
        amt = gained * (take_fc / use)
        if product and amt > 1e-12:
            by_prod[product] = float(by_prod.get(product, 0.0) or 0.0) + amt


def _track_company_export_fc(
    company: "Company",
    dest_country: str,
    product: str,
    amount: float,
) -> None:
    """해외 수출 대금(외화)을 상품별로 추적 — 환전 시 라벨 배분용."""
    amt = float(amount or 0.0)
    if amt <= 1e-12:
        return
    pending = getattr(company, "pending_export_fc_by_product", None)
    if not isinstance(pending, dict):
        company.pending_export_fc_by_product = {}
        pending = company.pending_export_fc_by_product
    key = (str(dest_country or ""), str(product or "").strip())
    pending[key] = float(pending.get(key, 0.0) or 0.0) + amt


def _is_company_capex_label(label: str) -> bool:
    lab = str(label or "")
    return (
        lab.startswith("시설 OTC")
        or lab in ("시설 건설", "시설 OTC 매입", "시설 OTC 매각")
        or "CapEx" in lab
    )


def _company_weekly_capex_lines(
    company: "Company",
) -> List[Tuple[str, float]]:
    """주간 CapEx 지출(양수) · 시설 매각 유입은 별도 inflows."""
    capex = getattr(company, "weekly_capex", None) or {}
    detail = sorted(
        [(label, value) for label, value in capex.items() if value > 1e-6],
        key=lambda item: -item[1],
    )
    return detail[:10]


def _company_weekly_capex_inflow_lines(
    company: "Company",
) -> List[Tuple[str, float]]:
    inflows = getattr(company, "weekly_capex_inflows", None) or {}
    detail = sorted(
        [(label, value) for label, value in inflows.items() if value > 1e-6],
        key=lambda item: -item[1],
    )
    return detail[:10]


def _company_finance_chart_series(
    company: "Company", *, max_weeks: int = _COMPANY_FINANCE_CHART_HISTORY_WEEKS,
) -> Tuple[List[float], List[float], List[float]]:
    """주간 순수입·현금·현금흐름 시계열 (차트용)."""
    net_series = list(getattr(company, "weekly_net_income_history", []))
    cash_series = list(getattr(company, "weekly_cash_history", []))
    cur_net = float(company.net_income or 0.0)
    cur_cash = float(company.cash or 0.0)
    if not net_series:
        net_series = [cur_net]
    elif abs(net_series[-1] - cur_net) > 1e-6:
        net_series = net_series + [cur_net]
    if not cash_series:
        cash_series = [cur_cash]
    elif abs(cash_series[-1] - cur_cash) > 1e-6:
        cash_series = cash_series + [cur_cash]
    length = min(max_weeks, max(len(net_series), len(cash_series)))
    net_series = net_series[-length:]
    cash_series = cash_series[-length:]
    while len(cash_series) < len(net_series):
        cash_series.insert(0, cash_series[0] if cash_series else 0.0)
    while len(net_series) < len(cash_series):
        net_series.insert(0, net_series[0] if net_series else 0.0)
    cash_flow = []
    for idx, cash in enumerate(cash_series):
        if idx == 0:
            cash_flow.append(net_series[0])
        else:
            cash_flow.append(cash - cash_series[idx - 1])
    return net_series, cash_series, cash_flow


def _style_company_chart_ax(ax, *, show_x: bool = True) -> None:
    ax.set_facecolor(_STOCK_CHART_BG)
    for spine in ax.spines.values():
        spine.set_color(_STOCK_CHART_TEXT)
        spine.set_linewidth(0.8)
    ax.tick_params(axis="both", colors=_STOCK_CHART_TEXT, labelsize=8, pad=2)
    ax.yaxis.grid(True, linestyle="--", linewidth=0.5, color="#3f3f3f", zorder=0)
    ax.set_axisbelow(True)
    if not show_x:
        ax.set_xticks([])
    ax.set_ylabel("")
    ax.margins(x=0.04)


def _finalize_company_twin_chart_axes(ax, ax_twin, tick_font) -> None:
    """이중 Y축 차트 — 축 라벨 제거(제목으로 대체) + 글꼴 통일."""
    ax_twin.set_ylabel("")
    ax.tick_params(axis="y", colors=_STOCK_CHART_TEXT, labelsize=7, pad=1)
    ax_twin.tick_params(axis="y", colors=_STOCK_CHART_TEXT_DIM, labelsize=7, pad=1)
    _apply_chart_axis_fonts(ax, tick_font)
    _apply_chart_axis_fonts(ax_twin, tick_font)


def _draw_company_dual_bars_panel(
    ax,
    rows: List[Dict[str, Any]],
    *,
    title: str,
    bar_color: str,
    text_color: str,
    filled_label: str = "체결",
    required_label: str = "필요",
    y_top: float = 0.90,
    height: float = 0.78,
) -> None:
    label_font = _load_project_chart_font(size=11)
    small_font = _load_project_chart_font(size=9)
    if title:
        ax.text(
            0.02, y_top + 0.05, title,
            transform=ax.transAxes, va="top", ha="left",
            color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=11,
        )
    if not rows:
        ax.text(
            0.02, y_top - 0.06, "표시할 데이터가 없습니다.",
            transform=ax.transAxes, va="top", ha="left",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font,
        )
        return

    display_rows, row_h = _company_panel_fit_rows(rows[:_COMPANY_PANEL_TOP_N], height=height)
    scale = max((row["required"] for row in display_rows), default=1.0)
    if scale <= 1e-9:
        scale = 1.0

    row_gap = row_h
    for idx, row in enumerate(display_rows):
        y_center = y_top - _COMPANY_PANEL_TITLE_BODY_GAP - idx * row_gap
        pct = row["ratio"] * 100.0
        _draw_company_panel_dual_bar_row(
            ax,
            y_center=y_center,
            label=row["label"],
            product=row.get("product"),
            required=row["required"],
            filled=row["filled"],
            bar_color=bar_color,
            text_color=text_color,
            scale=scale,
            inner_text=(
                f"{filled_label} {row['filled']:,.1f}  ·  "
                f"{required_label} {row['required']:,.1f}  ·  {pct:.0f}%"
            ),
        )


def _company_input_row_colors(kind: str) -> Tuple[str, str]:
    if kind == "labor":
        return _COMPANY_LABOR_BAR_COLOR, _COMPANY_LABOR_TEXT_COLOR
    if kind == "optional":
        return _COMPANY_OPTIONAL_BAR_COLOR, _COMPANY_OPTIONAL_TEXT_COLOR
    return _COMPANY_INPUT_BAR_COLOR, _COMPANY_INPUT_TEXT_COLOR


def _draw_company_input_fulfillment_panel(
    ax,
    labor_row: Dict[str, Any],
    essential_rows: List[Dict[str, Any]],
    optional_rows: List[Dict[str, Any]],
    *,
    title: str,
    y_top: float = 0.92,
    height: float = 0.80,
) -> None:
    """투입 충족 — 노동력(상단·빨강), 필수(중간), 비필수(하단·파랑)."""
    label_font = _load_project_chart_font(size=11)
    small_font = _load_project_chart_font(size=9)
    ax.text(
        0.02, y_top + 0.05, title,
        transform=ax.transAxes, va="top", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=11,
    )

    display_rows: List[Dict[str, Any]] = [labor_row]
    display_rows.extend(essential_rows)
    if optional_rows:
        display_rows.extend(optional_rows)
    if len(display_rows) <= 1 and not essential_rows and not optional_rows:
        ax.text(
            0.02, y_top - 0.06, "표시할 투입 데이터가 없습니다.",
            transform=ax.transAxes, va="top", ha="left",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font,
        )
        return

    display_rows, row_h = _company_panel_fit_rows(
        display_rows, height=height, max_rows=_COMPANY_PANEL_INPUT_MAX_ROWS,
    )
    scale = max((row["required"] for row in display_rows), default=1.0)
    if scale <= 1e-9:
        scale = 1.0

    row_gap = row_h
    for idx, row in enumerate(display_rows):
        y_center = y_top - _COMPANY_PANEL_TITLE_BODY_GAP - idx * row_gap
        bar_color, text_color = _company_input_row_colors(row.get("kind", "essential"))
        pct = row["ratio"] * 100.0
        _draw_company_panel_dual_bar_row(
            ax,
            y_center=y_center,
            label=row["label"],
            product=row.get("product") if row.get("kind") != "labor" else None,
            required=row["required"],
            filled=row["filled"],
            bar_color=bar_color,
            text_color=text_color,
            scale=scale,
            inner_text=(
                f"체결 {row['filled']:,.1f}  ·  "
                f"필요 {row['required']:,.1f}  ·  {pct:.0f}%"
            ),
        )


def _company_net_income_display(net_income: float) -> Tuple[str, str]:
    if net_income >= 0:
        return _company_panel_income_money(net_income), _COMPANY_PROFIT_COLOR
    return _company_panel_expense_money(net_income), _COMPANY_LOSS_COLOR


def _draw_company_finance_panel(
    ax, world: "World", company: "Company",
) -> None:
    """주간 순수입 → 영업수입·지출 → CapEx(현금흐름)."""
    headline_font = _load_project_chart_font(size=_COMPANY_FINANCE_HEADLINE_VALUE_SIZE)
    section_font = _load_project_chart_font(size=_COMPANY_FINANCE_SECTION_VALUE_SIZE)
    detail_font = _load_project_chart_font(size=_COMPANY_FINANCE_DETAIL_VALUE_SIZE)
    label_font = _load_project_chart_font(size=_COMPANY_FINANCE_LABEL_SIZE)

    income_lines = _company_weekly_income_lines(world, company)[:5]
    expense_lines = _company_weekly_expense_lines(world, company)[:5]
    capex_lines = _company_weekly_capex_lines(company)[:4]
    capex_in_lines = _company_weekly_capex_inflow_lines(company)[:4]

    total_income = float(getattr(company, "income", 0.0) or 0.0)
    if total_income <= 1e-9:
        total_income = sum(value for _, value in income_lines)
    total_expense = float(getattr(company, "expense", 0.0) or 0.0)
    if total_expense <= 1e-9:
        total_expense = sum(value for _, value in expense_lines)
    net_income = float(getattr(company, "net_income", 0.0) or 0.0)
    if abs(net_income) <= 1e-9 and (income_lines or expense_lines):
        net_income = total_income - total_expense
    total_capex = float(getattr(company, "last_week_capex", 0.0) or 0.0)
    if total_capex <= 1e-9:
        total_capex = sum(v for _, v in capex_lines)
    total_capex_in = float(getattr(company, "last_week_capex_inflows", 0.0) or 0.0)
    if total_capex_in <= 1e-9:
        total_capex_in = sum(v for _, v in capex_in_lines)
    net_text, net_color = _company_net_income_display(net_income)
    label_x = 0.04
    value_x = 0.96

    rows: List[Tuple[str, str, str, str, Optional[str]]] = [
        ("headline", "주간 순수입", net_text, net_color, None),
        ("gap", "", "", "", None),
        ("section", "영업수입", _company_panel_income_money(total_income), _COMPANY_FINANCE_SECTION_PROFIT_COLOR, None),
        ("gap_sm", "", "", "", None),
    ]
    for item_label, value in income_lines:
        rows.append((
            "detail",
            _short_pie_label(item_label, 14),
            _company_panel_income_money(value),
            _COMPANY_FINANCE_DETAIL_PROFIT_COLOR,
            item_label,
        ))
    rows.append(("gap", "", "", "", None))
    rows.extend([
        ("section", "영업지출", _company_panel_expense_money(total_expense), _COMPANY_FINANCE_SECTION_LOSS_COLOR, None),
        ("gap_sm", "", "", "", None),
    ])
    for item_label, value in expense_lines:
        rows.append((
            "detail",
            _short_pie_label(item_label, 14),
            _company_panel_expense_money(value),
            _COMPANY_FINANCE_DETAIL_LOSS_COLOR,
            item_label,
        ))
    if total_capex > 1e-6 or total_capex_in > 1e-6 or capex_lines or capex_in_lines:
        rows.append(("gap", "", "", "", None))
        rows.append((
            "section",
            "CapEx(순)",
            _company_panel_expense_money(total_capex - total_capex_in),
            _COMPANY_FINANCE_SECTION_LOSS_COLOR,
            None,
        ))
        rows.append(("gap_sm", "", "", "", None))
        if capex_lines:
            for item_label, value in capex_lines:
                rows.append((
                    "detail",
                    _short_pie_label(item_label, 14),
                    _company_panel_expense_money(value),
                    _COMPANY_FINANCE_DETAIL_LOSS_COLOR,
                    item_label,
                ))
        elif total_capex > 1e-6:
            rows.append((
                "detail",
                "시설투자",
                _company_panel_expense_money(total_capex),
                _COMPANY_FINANCE_DETAIL_LOSS_COLOR,
                "시설 투자",
            ))
        if capex_in_lines:
            for item_label, value in capex_in_lines:
                rows.append((
                    "detail",
                    _short_pie_label(item_label, 14),
                    _company_panel_income_money(value),
                    _COMPANY_FINANCE_DETAIL_PROFIT_COLOR,
                    item_label,
                ))
        elif total_capex_in > 1e-6:
            rows.append((
                "detail",
                "시설매각",
                _company_panel_income_money(total_capex_in),
                _COMPANY_FINANCE_DETAIL_PROFIT_COLOR,
                "시설 매각",
            ))

    row_weights = {
        "headline": 1.75,
        "section": 1.25,
        "detail": 1.0,
        "gap": 0.70,
        "gap_sm": 0.42,
    }
    y_top = 0.97
    y_bottom = 0.05
    total_weight = sum(row_weights[kind] for kind, _, _, _, _ in rows)
    unit_h = (y_top - y_bottom) / max(total_weight, 1e-9)

    y = y_top
    for kind, label_text, value_text, color, product in rows:
        step = unit_h * row_weights[kind]
        if kind in ("gap", "gap_sm"):
            y -= step
            continue
        if kind == "headline":
            value_font = headline_font
            value_size = _COMPANY_FINANCE_HEADLINE_VALUE_SIZE
        elif kind == "section":
            value_font = section_font
            value_size = _COMPANY_FINANCE_SECTION_VALUE_SIZE
        else:
            value_font = detail_font
            value_size = _COMPANY_FINANCE_DETAIL_VALUE_SIZE
        if kind == "detail" and product:
            _draw_company_panel_row_label(
                ax, label_x, y, label_text,
                product=product,
                font=label_font,
                fontsize=_COMPANY_FINANCE_LABEL_SIZE,
                max_len=14,
                valign="top",
            )
        else:
            ax.text(
                label_x, y, label_text,
                transform=ax.transAxes, va="top", ha="left",
                color=_STOCK_CHART_TEXT, fontproperties=label_font,
                fontsize=_COMPANY_FINANCE_LABEL_SIZE,
            )
        ax.text(
            value_x, y, value_text,
            transform=ax.transAxes, va="top", ha="right",
            color=color,
            fontproperties=value_font, fontsize=value_size, **_chart_bold_text_kwargs(),
        )
        y -= step


def _draw_company_cash_headline(ax, company: "Company") -> None:
    """총 보유 현금 + 배당 지출."""
    headline_font = _load_project_chart_font(size=22)
    label_font = _load_project_chart_font(size=_COMPANY_FINANCE_LABEL_SIZE)
    small_font = _load_project_chart_font(size=_COMPANY_DIVIDEND_LABEL_SIZE)
    cash = float(company.cash or 0.0)
    if cash < 0:
        cash_text = _company_panel_money(cash)
        cash_color = _COMPANY_LOSS_COLOR
    else:
        cash_text = _company_panel_money(cash)
        cash_color = _STOCK_CHART_TEXT
    ax.text(
        0.04, 0.84, "총 보유 현금",
        transform=ax.transAxes, va="center", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font,
        fontsize=_COMPANY_FINANCE_LABEL_SIZE,
    )
    ax.text(
        0.96, 0.84, cash_text,
        transform=ax.transAxes, va="center", ha="right",
        color=cash_color, fontproperties=headline_font, fontsize=22, **_chart_bold_text_kwargs(),
    )
    dividend = _company_weekly_dividend_expense(company)
    ax.text(
        0.04, 0.36, "배당 지출",
        transform=ax.transAxes, va="center", ha="left",
        color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font, fontsize=_COMPANY_DIVIDEND_LABEL_SIZE,
    )
    ax.text(
        0.96, 0.36, _company_panel_expense_money(dividend),
        transform=ax.transAxes, va="center", ha="right",
        color=cash_color, fontproperties=small_font, fontsize=_COMPANY_DIVIDEND_LABEL_SIZE, **_chart_bold_text_kwargs(),
    )


def _draw_company_bond_panel(
    ax, world: "World", company: "Company",
) -> None:
    """채권 — 투입·거래 패널과 동일한 그래프(가로 막대) 형식."""
    label_font = _load_project_chart_font(size=11)
    small_font = _load_project_chart_font(size=8)

    bond_debt = float(company.bond_balance or 0.0)
    bond_issue = float(
        company.current_bond_issue or company.pending_bond_issue or 0.0)
    bond_market = world.bond_markets.get(company.id)
    bond_rate = float(
        getattr(bond_market, "current_interest_rate", 0.0) or 0.0) if bond_market else 0.0
    sold_ratio = float(company.bond_sold_ratio or 0.0) * 100.0
    dividend = float(company.dividend_ratio or 0.0)

    ax.text(
        0.02, 0.98, "채권",
        transform=ax.transAxes, va="top", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=11,
    )
    ax.text(
        0.98, 0.98,
        f"금리 {bond_rate:.2f}%  ·  판매 {sold_ratio:.0f}%  ·  배당 {dividend:.1f}%",
        transform=ax.transAxes, va="top", ha="right",
        color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font, fontsize=7,
    )

    bond_issue_amt = max(bond_issue, 1e-9)
    debt_pct = clamp(bond_debt / bond_issue_amt, 0.0, 1.2) * 100.0
    bar_max_w, bar_h = _company_panel_bar_dims(ax)
    y_center = 0.90 - _COMPANY_BOND_TITLE_BODY_GAP
    _draw_company_panel_dual_bar_row(
        ax,
        y_center=y_center,
        label="채권부채",
        required=bond_issue_amt,
        filled=bond_debt,
        bar_color=_COMPANY_BOND_DEBT_BAR_COLOR,
        text_color=_COMPANY_BOND_DEBT_TEXT_COLOR,
        scale=bond_issue_amt,
        bar_max_w=bar_max_w,
        bar_h=bar_h,
        inner_text=(
            f"부채 {_company_panel_money(bond_debt)}  ·  "
            f"발행 {_company_panel_money(bond_issue)}  ·  {debt_pct:.0f}%"
        ),
    )


def _draw_company_combined_finance_chart(
    ax, company: "Company",
) -> None:
    """이전 주 순수입 막대 + 현금흐름 선 — 주식 차트 스타일."""
    import numpy as np

    label_font = _load_project_chart_font(size=10)
    small_font = _load_project_chart_font(size=8)
    tick_font = _load_project_chart_font(size=8)
    _style_company_chart_ax(ax)

    net_series, cash_series, cash_flow = _company_finance_chart_series(company)
    world_week, start_year = _finance_chart_calendar_ctx(company)
    net_bars, bar_labels = _aggregate_finance_chart_buckets(
        net_series, world_week=world_week, start_year=start_year)
    cash_flow_bars, _ = _aggregate_finance_chart_buckets(
        cash_flow, world_week=world_week, start_year=start_year)
    bar_count = len(net_bars)
    indices = np.arange(bar_count)

    ax.text(
        0.02, 1.04, "순이익 · 현금흐름",
        transform=ax.transAxes, va="bottom", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=10,
    )

    chart_gray = _COMPANY_FINANCE_CHART_GRAY
    ax.bar(
        indices, net_bars, color=chart_gray, alpha=0.78, width=0.88,
        edgecolor="none", zorder=2,
    )
    for idx, value in enumerate(net_bars):
        if abs(value) <= 1e-6:
            continue
        ax.text(
            idx, value, _company_panel_money(value),
            ha="center",
            va="bottom" if value >= 0 else "top",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font, fontsize=6,
        )

    net_low, net_high = _finance_chart_ylim(net_bars)
    ax.set_ylim(net_low, net_high)
    if net_low < 0 < net_high:
        ax.axhline(0, color="#3f3f3f", linewidth=0.8, zorder=1)

    ax_cf = ax.twinx()
    ax_cf.set_facecolor(_STOCK_CHART_BG)
    for spine in ax_cf.spines.values():
        spine.set_color(_STOCK_CHART_TEXT)
        spine.set_linewidth(0.8)
    ax_cf.plot(
        indices, cash_flow_bars, color=chart_gray, linewidth=1.6,
        marker="o", markersize=3.5, alpha=0.92, zorder=3,
    )
    cf_low, cf_high = _finance_chart_ylim(cash_flow_bars)
    ax_cf.set_ylim(cf_low, cf_high)

    ax.set_xticks(indices)
    ax.set_xticklabels(bar_labels, fontproperties=tick_font, fontsize=7)
    ax.set_xlim(-0.6, max(bar_count - 0.4, 0.6))
    _finalize_company_twin_chart_axes(ax, ax_cf, tick_font)


def _draw_company_facility_metric_chart(
    ax, company: "Company", *, panel_mode: str,
) -> None:
    """13주 평균 시설 수 막대 + 산출/실적 선 — 순이익 차트와 동일 스타일."""
    import numpy as np

    label_font = _load_project_chart_font(size=10)
    small_font = _load_project_chart_font(size=8)
    tick_font = _load_project_chart_font(size=8)
    _style_company_chart_ax(ax)

    count_series, output_series = _company_facility_chart_series(company)
    world_week, start_year = _finance_chart_calendar_ctx(company)
    count_bars, bar_labels = _aggregate_finance_chart_buckets(
        count_series, world_week=world_week, start_year=start_year)
    output_bars, _ = _aggregate_finance_chart_buckets(
        output_series, world_week=world_week, start_year=start_year)
    bar_count = len(count_bars)
    indices = np.arange(bar_count)

    chart_titles = {
        "생산": ("시설 수 · 산출", "시설 수", "산출"),
        "소매": ("매장 수 · 소매량", "매장 수", "소매량"),
        "무역": ("루트 수 · 체결량", "루트 수", "체결량"),
    }
    chart_title, _, _ = chart_titles.get(
        panel_mode, ("시설 수 · 산출", "시설 수", "산출"))

    ax.text(
        0.02, 1.04, chart_title,
        transform=ax.transAxes, va="bottom", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=10,
    )

    chart_gray = _COMPANY_FINANCE_CHART_GRAY
    ax.bar(
        indices, count_bars, color=chart_gray, alpha=0.78, width=0.88,
        edgecolor="none", zorder=2,
    )
    for idx, value in enumerate(count_bars):
        if abs(value) <= 1e-6:
            continue
        ax.text(
            idx, value, f"{value:,.1f}",
            ha="center",
            va="bottom" if value >= 0 else "top",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font, fontsize=6,
        )

    count_low, count_high = _finance_chart_ylim(count_bars)
    ax.set_ylim(count_low, count_high)
    if count_low < 0 < count_high:
        ax.axhline(0, color="#3f3f3f", linewidth=0.8, zorder=1)

    ax_out = ax.twinx()
    ax_out.set_facecolor(_STOCK_CHART_BG)
    for spine in ax_out.spines.values():
        spine.set_color(_STOCK_CHART_TEXT)
        spine.set_linewidth(0.8)
    ax_out.plot(
        indices, output_bars, color=chart_gray, linewidth=1.6,
        marker="o", markersize=3.5, alpha=0.92, zorder=3,
    )
    out_low, out_high = _finance_chart_ylim(output_bars)
    ax_out.set_ylim(out_low, out_high)

    ax.set_xticks(indices)
    ax.set_xticklabels(bar_labels, fontproperties=tick_font, fontsize=7)
    ax.set_xlim(-0.6, max(bar_count - 0.4, 0.6))
    _finalize_company_twin_chart_axes(ax, ax_out, tick_font)


def _draw_company_financial_chart(
    world: "World", company: "Company", ax_bar, ax_line,
) -> None:
    _draw_company_combined_finance_chart(ax_bar, company)
    ax_line.set_visible(False)


def _company_facility_production_rows(
    world: "World", company: "Company",
) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for fac in company.facilities:
        if fac.is_office:
            continue
        spec = FACILITY_SPECS.get(fac.name, {})
        product = spec.get("output") if spec else None
        state = world.states.get(fac.state_id)
        state_label = _short_pie_label(getattr(state, "name", fac.state_id), 8)
        if fac.under_construction > 0 and fac.active_levels() <= 0:
            target = float(
                fac.construction_target
                or FACILITY_SPECS.get(fac.name, {}).get("construction", 0.0)
                or 0.0)
            progress = float(fac.construction_progress or 0.0)
            pct = clamp(progress / max(target, 1e-9), 0.0, 1.0)
            rows.append({
                "label": _short_pie_label(fac.name, 10),
                "state": state_label,
                "product": product or "건설",
                "output": 0.0,
                "capacity": max(fac.base_output(), 1.0),
                "utilization": 0.0,
                "input_fill": fac.actual_input_fill,
                "levels": fac.active_levels(),
                "is_construction": True,
                "construction_progress": progress,
                "construction_target": max(target, 1e-9),
                "construction_pct": pct,
                "construction_services": float(
                    getattr(fac, "last_week_construction_services", 0.0) or 0.0),
            })
            continue
        if not product or fac.active_levels() <= 0:
            continue
        capacity = max(fac.base_output(), 1e-9)
        output = float(fac.planned_weekly_output or 0.0)
        if output <= 1e-6:
            output = (
                capacity
                * float(company.last_efficiency or 1.0)
                * float(fac.actual_input_fill or 1.0)
                * labor_output_factor(float(company.last_labor_fill_ratio or 1.0))
            )
        utilization = clamp(output / capacity, 0.0, 1.2)
        rows.append({
            "label": _short_pie_label(fac.name, 10),
            "state": state_label,
            "product": product,
            "output": output,
            "capacity": capacity,
            "utilization": utilization,
            "input_fill": fac.actual_input_fill,
            "levels": fac.active_levels(),
            "is_construction": False,
        })
    rows.sort(key=lambda row: (row["is_construction"], -row["output"], row["label"]))
    return rows


def _company_retail_operation_rows(
    world: "World", company: "RetailCompany",
) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for state_id, volume in company.state_weekly_volume.items():
        if volume <= 1e-6:
            continue
        state = world.states.get(state_id)
        rows.append({
            "label": _short_pie_label(getattr(state, "name", state_id), 10),
            "state": _short_pie_label(getattr(state, "name", state_id), 8),
            "product": "소매",
            "output": float(volume),
            "capacity": float(volume),
            "utilization": 1.0,
            "input_fill": 1.0,
            "levels": 1,
            "is_construction": False,
        })
    if not rows:
        branch_count = sum(
            1 for st in world.states.values() if st.country_id == company.country_id)
        rows.append({
            "label": "전국 매장",
            "state": f"{branch_count}주",
            "product": "소매",
            "output": float(company.weekly_retail_volume or 0.0),
            "capacity": max(float(company.weekly_retail_volume or 1.0), 1.0),
            "utilization": 1.0,
            "input_fill": 1.0,
            "levels": branch_count,
            "is_construction": False,
        })
    rows.sort(key=lambda row: -row["output"])
    return rows


def _company_logistics_operation_rows(company: "Company") -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for route in getattr(company, "active_trade_routes", [])[:_COMPANY_PANEL_TOP_N]:
        ordered = float(route.get("ordered_qty", route.get("qty", 0.0)) or 0.0)
        actual = float(route.get("actual_qty", 0.0) or 0.0)
        rows.append({
            "label": _short_pie_label(route.get("product", "물류"), 10),
            "state": _short_pie_label(route.get("dest_country", ""), 8),
            "product": route.get("product", "물류"),
            "output": actual,
            "capacity": max(ordered, actual, 1.0),
            "utilization": clamp(actual / max(ordered, 1e-9), 0.0, 1.2),
            "input_fill": 1.0,
            "levels": 1,
            "is_construction": False,
        })
    rows.sort(key=lambda row: -row["output"])
    return rows


def create_company_detail_panel(world: "World", company_id: str) -> Optional[io.BytesIO]:
    """기업 생산 현황 패널 — 거래 현황 차트와 동일 레이아웃."""
    company = world.companies.get(company_id)
    if not company:
        return None

    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    _configure_project_matplotlib_font()
    title_font = _load_project_chart_font(size=15)
    small_font = _load_project_chart_font(size=9)

    state = world.states.get(company.home_state)
    country = world.countries.get(company_home_country_id(company, world.states))

    if isinstance(company, RetailCompany):
        production_rows = _company_retail_operation_rows(world, company)
        panel_mode = "소매"
    elif company.type == "물류 기업":
        production_rows = _company_logistics_operation_rows(company)
        panel_mode = "물류"
    else:
        production_rows = _company_facility_production_rows(world, company)
        panel_mode = "생산"

    input_rows = _company_input_product_rows(world, company)
    labor_row, essential_rows, optional_rows = input_rows
    output_rows = _company_output_product_rows(world, company)

    fig = plt.figure(figsize=(15.0, 7.0))
    fig.patch.set_facecolor(_STOCK_CHART_BG)
    gs = fig.add_gridspec(1, 2, width_ratios=[1.05, 1], wspace=0.16)
    chart_ratio = _COMPANY_DETAIL_CHART_ROW_RATIO
    gs_left = gs[0, 0].subgridspec(
        3, 1,
        height_ratios=[0.95, 1.88, chart_ratio],
        hspace=0.14,
    )
    gs_left_mid = gs_left[1].subgridspec(
        2, 1,
        height_ratios=[0.88, 1.0],
        hspace=_COMPANY_DETAIL_MID_PANEL_HSPACE,
    )
    gs_right = gs[0, 1].subgridspec(
        4, 1,
        height_ratios=[0.36, 0.08, 0.12, chart_ratio],
        hspace=0.06,
    )

    ax_inputs = fig.add_subplot(gs_left[0, 0])
    ax_outputs = fig.add_subplot(gs_left_mid[0, 0])
    ax_prod = fig.add_subplot(gs_left_mid[1, 0])
    ax_facility_chart = fig.add_subplot(gs_left[2, 0])
    ax_finance = fig.add_subplot(gs_right[0, 0])
    ax_cash = fig.add_subplot(gs_right[1, 0])
    ax_bond = fig.add_subplot(gs_right[2, 0])
    ax_finance_chart = fig.add_subplot(gs_right[3, 0])

    for ax in (ax_inputs, ax_outputs, ax_prod, ax_finance, ax_cash, ax_bond):
        ax.set_facecolor(_STOCK_CHART_BG)
        for spine in ax.spines.values():
            spine.set_visible(False)
        ax.axis("off")
        ax.set_xlim(0, 1)
        ax.set_ylim(0, 1)

    fig.text(
        0.5, 0.96, f"{company.name} · {panel_mode} 현황",
        ha="center", va="top", color=_STOCK_CHART_TEXT,
        fontproperties=title_font, fontsize=15,
    )
    fig.text(
        0.5, 0.915,
        f"{company.company_type}  ·  "
        f"{getattr(country, 'name', '무소속')} / {getattr(state, 'name', company.home_state)}",
        ha="center", va="top", color=_STOCK_CHART_TEXT_DIM,
        fontproperties=small_font, fontsize=9,
    )

    input_title = {
        "생산": "투입 충족 상품",
        "소매": "매입 충족 상품",
        "무역": "매입 충족 상품",
    }.get(panel_mode, "투입 충족 상품")
    output_title = {
        "생산": "생산 산출 상품",
        "소매": "소매 실적",
        "무역": "무역 체결",
    }.get(panel_mode, "생산 산출 상품")

    _draw_company_input_fulfillment_panel(
        ax_inputs,
        labor_row,
        essential_rows,
        optional_rows,
        title=input_title,
        y_top=0.92,
        height=0.80,
    )
    _draw_company_dual_bars_panel(
        ax_outputs,
        output_rows,
        title=output_title,
        bar_color=_COMPANY_OUTPUT_BAR_COLOR,
        text_color=_COMPANY_OUTPUT_TEXT_COLOR,
        filled_label="생산" if panel_mode == "생산" else "실적",
        required_label="최대",
        y_top=0.92,
        height=0.80,
    )

    right_title = {
        "생산": "시설 생산",
        "소매": "주별 소매",
        "무역": "무역 체결",
    }.get(panel_mode, "시설 생산")
    _draw_company_production_panel(
        ax_prod,
        production_rows,
        title=right_title,
        bar_color=_COMPANY_PRODUCTION_BAR_COLOR,
        text_color=_COMPANY_PRODUCTION_TEXT_COLOR,
        y_top=0.90,
        height=0.76,
    )
    _draw_company_finance_panel(ax_finance, world, company)
    _draw_company_cash_headline(ax_cash, company)
    _draw_company_bond_panel(ax_bond, world, company)
    _draw_company_combined_finance_chart(ax_finance_chart, company)
    _draw_company_facility_metric_chart(ax_facility_chart, company, panel_mode=panel_mode)

    fig.subplots_adjust(left=0.055, right=0.965, top=0.90, bottom=0.08)

    summary = (
        f"기술 Lv.{company.tech_level}  ·  "
        f"효율 {company.last_efficiency:.0%}  ·  "
        f"투입 {company.last_input_fill_ratio:.0%}  ·  "
        f"노동 {company.last_labor_fill_ratio:.0%}"
    )
    if isinstance(company, RetailCompany):
        summary = (
            f"매장 {sum(1 for st in world.states.values() if st.country_id == company.country_id)}주  ·  "
            f"종업 {company.employees}명  ·  "
            f"소매량 {company.weekly_retail_volume:,.1f}"
        )
    fig.text(
        0.5, 0.03, summary,
        ha="center", va="bottom", color=_STOCK_CHART_TEXT_DIM,
        fontproperties=small_font, fontsize=8,
    )

    buf = io.BytesIO()
    plt.savefig(
        buf, format="png", facecolor=fig.get_facecolor(),
        bbox_inches="tight", pad_inches=0.18,
    )
    buf.seek(0)
    plt.close(fig)
    return buf


_IB_STATUS_COLOR = "#00B8A9"
_IB_STATUS_PIE_COLORS = (
    "#00B8A9", "#3182F6", "#5B8DEF", "#F04452", "#FF6B6B", "#FFB020", "#8B95A1",
)


def investment_bank_stock_values_by_region(
    world: "World", ib: "InvestmentBank",
) -> Tuple[float, float]:
    """금투은행 주식 평가액 — (국내, 해외)."""
    domestic = 0.0
    foreign = 0.0
    avg_costs = getattr(ib, "stock_avg_cost", None) or {}
    for issuer_id, shares in ib.stock_holdings.items():
        if shares <= 1e-9:
            continue
        value = stock_holding_market_value(
            world, issuer_id, shares, float(avg_costs.get(issuer_id, 0.0) or 0.0))
        if issuer_stock_country_id(world, issuer_id) == ib.country_id:
            domestic += value
        else:
            foreign += value
    return domestic, foreign


def investment_bank_bond_values_by_region(
    world: "World", ib: "InvestmentBank",
) -> Tuple[float, float]:
    """금투은행 채권 시가 — (국내, 해외)."""
    rates = getattr(ib, "bond_purchase_rate", None) or {}
    domestic = 0.0
    foreign = 0.0
    for market_key, amount in ib.bond_holdings.items():
        if amount <= 1e-9:
            continue
        mark = bond_holding_mark_value(
            world, market_key, amount, float(rates.get(market_key, 0.0) or 0.0))
        if bond_market_country_id(world, market_key) == ib.country_id:
            domestic += mark
        else:
            foreign += mark
    return domestic, foreign


def _bond_holding_panel_row(
    world: "World",
    market_key: str,
    amount: float,
    purchase_rate: float = 0.0,
) -> Dict[str, Any]:
    label, category, _cid = describe_bond_market(world, market_key)
    bm = world.bond_markets.get(market_key)
    eval_rate = float(getattr(bm, "current_interest_rate", 0.0) or 0.0) if bm else 0.0
    avg_rate = purchase_rate
    if avg_rate <= 1e-9:
        avg_rate = bond_market_prior_week_rate(world, market_key) or eval_rate
    purchase_price, current_price = bond_mtm_prices(amount, avg_rate, eval_rate)
    return_pct = bond_holding_return_pct(avg_rate, eval_rate)
    return {
        "label": _short_pie_label(label, 12),
        "sublabel": category,
        "value": current_price,
        "amount": amount,
        "return_pct": return_pct,
        "return_detail": (
            f"매입가 {_company_panel_money(purchase_price)}"
            f" · 현재가 {_company_panel_money(current_price)}"
        ),
        "show_return": True,
    }


def _investment_bank_holding_rows(
    world: "World",
    ib: "InvestmentBank",
    holdings: Dict[str, float],
    *,
    asset_kind: str,
    limit: int = 6,
) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for key, amount in holdings.items():
        if amount <= 1e-6:
            continue
        if asset_kind == "stock":
            label, category, _cid = describe_stock_issuer(world, key)
            held_cost = float(ib.stock_avg_cost.get(key, 0.0) or 0.0)
            price = stock_holding_mark_price(world, key, held_cost)
            value = amount * price if price > 0 else 0.0
            return_pct, avg_cost = stock_holding_return_pct(
                world, key, held_cost)
            return_detail = f"평가단가 {_company_panel_money(avg_cost)}"
            show_return = True
        else:
            row = _bond_holding_panel_row(
                world, key, amount, ib.bond_purchase_rate.get(key, 0.0))
            rows.append(row)
            continue
        rows.append({
            "label": _short_pie_label(label, 12),
            "sublabel": category,
            "value": value,
            "amount": amount,
            "return_pct": return_pct,
            "return_detail": return_detail,
            "show_return": show_return,
        })
    rows.sort(key=lambda row: row["value"], reverse=True)
    return rows[:limit]


def _ib_income_detail_display(value: float) -> Tuple[str, str]:
    v = float(value or 0.0)
    if v >= 0:
        return _company_panel_income_money(v), _COMPANY_FINANCE_DETAIL_PROFIT_COLOR
    return _company_panel_expense_money(v), _COMPANY_FINANCE_DETAIL_LOSS_COLOR


def _draw_investment_bank_stats_panel(
    ax, ib: "InvestmentBank", world: "World",
) -> None:
    """기업 재무 패널과 동일한 계층·색상."""
    headline_font = _load_project_chart_font(size=_COMPANY_FINANCE_HEADLINE_VALUE_SIZE)
    detail_font = _load_project_chart_font(size=_COMPANY_FINANCE_DETAIL_VALUE_SIZE)
    label_font = _load_project_chart_font(size=_COMPANY_FINANCE_LABEL_SIZE)

    net_assets = investment_bank_net_assets(world, ib)
    net_text, net_color = _company_net_income_display(
        float(getattr(ib, "last_week_net_income", 0.0) or 0.0))
    div_text, div_color = _ib_income_detail_display(
        float(getattr(ib, "last_week_dividend_income", 0.0) or 0.0))
    bond_int_text, bond_int_color = _ib_income_detail_display(
        float(getattr(ib, "last_week_bond_interest_income", 0.0) or 0.0))
    foreign_text, foreign_color = _ib_income_detail_display(
        float(getattr(ib, "last_week_foreign_passive_income", 0.0) or 0.0))
    fee_text, fee_color = _ib_income_detail_display(
        float(getattr(ib, "last_week_fee_income", 0.0) or 0.0))
    payout = float(getattr(ib, "last_week_fund_payout", 0.0) or 0.0)
    if payout <= 1e-6:
        payout_text = _company_panel_income_money(0.0)
        payout_color = _STOCK_CHART_TEXT_DIM
    else:
        payout_text, payout_color = _ib_income_detail_display(-payout)
    loan_exp = float(getattr(ib, "last_week_loan_interest_expense", 0.0) or 0.0)
    if loan_exp <= 1e-6:
        loan_exp_text = _company_panel_income_money(0.0)
        loan_exp_color = _STOCK_CHART_TEXT_DIM
    else:
        loan_exp_text, loan_exp_color = _ib_income_detail_display(-loan_exp)
    cash_val = float(getattr(ib, "last_week_cash", ib.cash) or 0.0)
    dep_val = float(getattr(ib, "last_week_deposits", ib.deposits) or 0.0)
    loan_val = float(getattr(ib, "last_week_loan_balance", ib.loan_balance) or 0.0)
    fund_val = float(getattr(ib, "last_week_fund_aum", ib.fund_aum) or 0.0)
    stock_value = float(getattr(ib, "last_week_stock_value", 0.0) or 0.0)
    bond_value = float(getattr(ib, "last_week_bond_value", 0.0) or 0.0)
    fx_value = float(getattr(ib, "last_week_fx_value", 0.0) or 0.0)
    lev_pct = float(getattr(ib, "last_week_leverage_ratio_pct", 0.0) or 0.0)

    label_x = 0.04
    value_x = 0.96

    rows: List[Tuple[str, str, str, str]] = [
        ("headline", "주간 순수입", net_text, net_color),
        ("gap_sm", "", "", ""),
        ("detail", "주간 배당", div_text, div_color),
        ("detail", "주간 채권이자", bond_int_text, bond_int_color),
        ("detail", "주간 해외수익", foreign_text, foreign_color),
        ("detail", "주간 운용보수", fee_text, fee_color),
        ("detail", "주간 펀드배분", payout_text, payout_color),
        ("detail", "주간 대출이자", loan_exp_text, loan_exp_color),
        ("gap", "", "", ""),
        ("section", "자산", "", _STOCK_CHART_TEXT),
        ("detail", "현금", _company_panel_money(cash_val), _STOCK_CHART_TEXT),
        ("detail", "예금", _company_panel_money(dep_val), _STOCK_CHART_TEXT),
        ("detail", "대출잔액", _company_panel_money(loan_val), _STOCK_CHART_TEXT),
        ("detail", "자기자본비율", (
            f"{format_equity_capital_ratio_label(lev_pct)}"
            f" / {format_equity_capital_ratio_label(getattr(world.countries.get(ib.country_id), 'financial_leverage_ratio_pct', DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT))}"
        ), _STOCK_CHART_TEXT),
        ("gap", "", "", ""),
        ("section", "운용", "", _STOCK_CHART_TEXT),
        ("detail", "펀드", _company_panel_money(fund_val), _STOCK_CHART_TEXT),
        ("detail", "주식", _company_panel_money(stock_value), _STOCK_CHART_TEXT),
        ("detail", "채권", _company_panel_money(bond_value), _STOCK_CHART_TEXT),
        ("detail", "외화", _company_panel_money(fx_value), _STOCK_CHART_TEXT),
        ("gap", "", "", ""),
        ("headline", "순자산", _company_panel_money(net_assets), _IB_STATUS_COLOR),
    ]

    row_weights = {
        "headline": 1.75,
        "section": 1.25,
        "detail": 1.0,
        "gap": 0.70,
        "gap_sm": 0.42,
    }
    y_top = 0.97
    y_bottom = 0.05
    total_weight = sum(row_weights[kind] for kind, _, _, _ in rows)
    unit_h = (y_top - y_bottom) / max(total_weight, 1e-9)

    y = y_top
    for kind, label_text, value_text, color in rows:
        step = unit_h * row_weights[kind]
        if kind in ("gap", "gap_sm"):
            y -= step
            continue
        if kind == "headline":
            value_font = headline_font
            value_size = _COMPANY_FINANCE_HEADLINE_VALUE_SIZE
        elif kind == "section":
            ax.text(
                label_x, y, label_text,
                transform=ax.transAxes, va="top", ha="left",
                color=_STOCK_CHART_TEXT, fontproperties=label_font,
                fontsize=_COMPANY_FINANCE_LABEL_SIZE, **_chart_bold_text_kwargs(),
            )
            y -= step
            continue
        else:
            value_font = detail_font
            value_size = _COMPANY_FINANCE_DETAIL_VALUE_SIZE
        ax.text(
            label_x, y, label_text,
            transform=ax.transAxes, va="top", ha="left",
            color=_STOCK_CHART_TEXT, fontproperties=label_font,
            fontsize=_COMPANY_FINANCE_LABEL_SIZE,
        )
        if value_text:
            ax.text(
                value_x, y, value_text,
                transform=ax.transAxes, va="top", ha="right",
                color=color, fontproperties=value_font, fontsize=value_size,
                **_chart_bold_text_kwargs(),
            )
        y -= step


def _draw_investment_bank_aum_pie(ax, ib: "InvestmentBank", world: "World") -> None:
    import matplotlib.patches as mpatches

    label_font = _load_project_chart_font(size=11)
    small_font = _load_project_chart_font(size=8)
    legend_rect_x = -0.16
    legend_text_x = -0.12

    ax.set_xlim(-0.32, 1.0)
    ax.set_ylim(0, 1)

    domestic_stock = float(getattr(ib, "last_week_domestic_stock", 0.0) or 0.0)
    foreign_stock = float(getattr(ib, "last_week_foreign_stock", 0.0) or 0.0)
    domestic_bond = float(getattr(ib, "last_week_domestic_bond", 0.0) or 0.0)
    foreign_bond = float(getattr(ib, "last_week_foreign_bond", 0.0) or 0.0)
    fx_value = float(getattr(ib, "last_week_fx_value", 0.0) or 0.0)
    cash_val = float(getattr(ib, "last_week_cash", ib.cash) or 0.0)
    slices = [
        ("현금", max(0.0, cash_val)),
        ("주식", max(0.0, domestic_stock)),
        ("해외주식", max(0.0, foreign_stock)),
        ("채권", max(0.0, domestic_bond)),
        ("해외채권", max(0.0, foreign_bond)),
        ("외화", max(0.0, fx_value)),
    ]
    sizes = [val for _, val in slices if val > 1e-6]
    colors = _IB_STATUS_PIE_COLORS[: len(sizes)]

    ax.text(
        legend_rect_x, 0.98, "운용 자금 구성",
        transform=ax.transAxes, va="top", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=11,
        **_chart_bold_text_kwargs(),
    )
    if not sizes:
        ax.text(
            0.5, 0.45, "표시할 자산이 없습니다.",
            transform=ax.transData, va="center", ha="center",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font,
        )
        return

    _, _, autotexts = ax.pie(
        sizes,
        labels=None,
        colors=colors,
        autopct=lambda pct: f"{pct:.0f}%" if pct >= 6 else "",
        pctdistance=0.78,
        startangle=90,
        radius=0.52,
        center=(0.68, 0.42),
        wedgeprops={"width": 0.34, "edgecolor": _STOCK_CHART_BG, "linewidth": 1.0},
    )
    for autotext in autotexts:
        autotext.set_color(_STOCK_CHART_TEXT)
        autotext.set_fontsize(7)
        autotext.set_fontproperties(small_font)

    legend_y = 0.88
    legend_rows = [(n, v) for n, v in slices if v > 1e-6]
    legend_step = 0.10 if len(legend_rows) > 5 else 0.11
    for idx, (name, val) in enumerate(legend_rows[:8]):
        color = colors[idx]
        y = legend_y - idx * legend_step
        swatch = mpatches.Rectangle(
            (legend_rect_x, y - 0.025), 0.018, 0.05,
            facecolor=color, edgecolor="none", clip_on=False,
            transform=ax.transAxes,
        )
        ax.add_patch(swatch)
        ax.text(
            legend_text_x, y,
            f"{name}  {format_currency_short(val)}",
            transform=ax.transAxes, va="center", ha="left",
            color=_STOCK_CHART_TEXT, fontproperties=small_font, fontsize=8,
            clip_on=False,
        )
    ax.set_xlim(-0.32, 1.0)
    ax.set_ylim(0, 1)


def _draw_investment_bank_holdings_panel(
    ax,
    rows: List[Dict[str, Any]],
    *,
    title: str,
    bar_color: str,
    text_color: str,
    y_top: float = 0.98,
    height: float = 0.78,
    max_rows: int = 6,
    bar_x: Optional[float] = None,
    bar_max_w: Optional[float] = None,
) -> None:
    label_font = _load_project_chart_font(size=11)
    ax.text(
        0.02, y_top, title,
        transform=ax.transAxes, va="top", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=11,
        **_chart_bold_text_kwargs(),
    )
    body_base = y_top - 0.12
    if not rows:
        ax.text(
            0.02, body_base - 0.04, "보유 없음",
            transform=ax.transAxes, va="top", ha="left",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=label_font, fontsize=9,
        )
        return

    display_rows, row_h = _company_panel_fit_rows(
        rows, height=height, min_row_h=_COMPANY_PANEL_MIN_ROW_H, max_rows=max_rows,
    )
    scale = max((row["value"] for row in display_rows), default=1.0)
    if scale <= 1e-9:
        scale = 1.0
    panel_bar_x = bar_x if bar_x is not None else _COMPANY_PANEL_BAR_X
    default_bar_w, bar_h = _company_panel_bar_dims(ax)
    if bar_max_w is not None:
        default_bar_w = bar_max_w
    safe_bar_w = min(default_bar_w, max(0.12, 0.97 - panel_bar_x))
    for idx, row in enumerate(display_rows):
        y_center = body_base - _COMPANY_PANEL_TITLE_BODY_GAP - idx * row_h
        ratio = clamp(row["value"] / scale, 0.0, 1.0)
        fill_w = min(
            max(safe_bar_w * ratio, bar_h * 1.4 if row["value"] > 1e-6 else 0.0),
            safe_bar_w,
        )
        _stock_trading_rounded_bar(
            ax, panel_bar_x, y_center, fill_w, bar_h,
            bar_color, alpha=0.30,
        )
        inner_base = (
            f"{_company_panel_money(row['amount'])}  ·  "
            f"{_company_panel_money(row['value'])}"
        )
        if row.get("return_detail"):
            inner_base += f"  ·  {row['return_detail']}"
        _draw_company_panel_row_label(
            ax, _COMPANY_PANEL_LABEL_X, y_center, row["label"],
            font=_load_project_chart_font(size=8), fontsize=8, max_len=10,
        )
        ax.text(
            panel_bar_x + _COMPANY_PANEL_BAR_TEXT_PAD, y_center, inner_base,
            transform=ax.transAxes, va="center", ha="left",
            color=text_color, fontproperties=_load_project_chart_font(size=7),
            fontsize=7, **_chart_bold_text_kwargs(),
        )
        if row.get("show_return", False):
            return_text, return_color = _ib_holding_return_display(
                float(row.get("return_pct", 0.0)))
            ax.text(
                0.97, y_center, return_text,
                transform=ax.transAxes, va="center", ha="right",
                color=return_color, fontproperties=_load_project_chart_font(size=8),
                fontsize=8, **_chart_bold_text_kwargs(),
            )


def create_investment_bank_status_panel(
    world: "World", country_id: str,
) -> Optional[io.BytesIO]:
    """금융투자은행 현황 패널 이미지."""
    ib = world.investment_banks.get(country_id) or world.investment_banks.get(f"ib_{country_id}")
    if not ib:
        return None

    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    _configure_project_matplotlib_font()
    title_font = _load_project_chart_font(size=15)
    small_font = _load_project_chart_font(size=9)

    country = world.countries.get(ib.country_id)
    country_name = getattr(country, "name", ib.country_id)

    fig = plt.figure(figsize=(14.5, 7.8))
    fig.patch.set_facecolor(_STOCK_CHART_BG)
    gs = fig.add_gridspec(2, 2, width_ratios=[1.05, 1.0], height_ratios=[1.0, 1.05], wspace=0.14, hspace=0.18)

    ax_pie = fig.add_subplot(gs[0, 0])
    ax_stats = fig.add_subplot(gs[0, 1])
    ax_stocks = fig.add_subplot(gs[1, 0])
    ax_bonds = fig.add_subplot(gs[1, 1])

    for ax in (ax_stats, ax_pie, ax_stocks, ax_bonds):
        ax.set_facecolor(_STOCK_CHART_BG)
        for spine in ax.spines.values():
            spine.set_visible(False)
        ax.axis("off")
        ax.set_xlim(0, 1)
        ax.set_ylim(0, 1)

    fig.text(
        0.5, 0.965, f"{ib.name} · 금융투자은행 현황",
        ha="center", va="top", color=_STOCK_CHART_TEXT,
        fontproperties=title_font, fontsize=15,
    )
    fig.text(
        0.5, 0.925,
        f"{country_name}  ·  {week_to_date_label(world.week, world_start_year(world), style='long')}  ·  "
        f"순자산 {_company_panel_money(investment_bank_net_assets(world, ib))}",
        ha="center", va="top", color=_STOCK_CHART_TEXT_DIM,
        fontproperties=small_font, fontsize=9,
    )

    _draw_investment_bank_aum_pie(ax_pie, ib, world)
    _draw_investment_bank_stats_panel(ax_stats, ib, world)
    _draw_investment_bank_holdings_panel(
        ax_stocks,
        _investment_bank_holding_rows(
            world, ib, ib.stock_holdings, asset_kind="stock"),
        title="보유 주식",
        bar_color="#3182F6",
        text_color="#4A9AFF",
    )
    _draw_investment_bank_holdings_panel(
        ax_bonds,
        _investment_bank_holding_rows(
            world, ib, ib.bond_holdings, asset_kind="bond"),
        title="보유 채권",
        bar_color=_IB_STATUS_COLOR,
        text_color="#33D4C5",
    )

    fig.subplots_adjust(left=0.055, right=0.965, top=0.88, bottom=0.06)
    buf = io.BytesIO()
    plt.savefig(
        buf, format="png", facecolor=fig.get_facecolor(),
        bbox_inches="tight", pad_inches=0.16,
    )
    buf.seek(0)
    plt.close(fig)
    return buf


_BANK_STATUS_COLOR = "#3182F6"
_BANK_STATUS_PIE_COLORS = ("#3182F6", "#5B8DEF", "#00B8A9", "#FFB020", "#8B95A1", "#F04452")
_BANK_CUSTOMER_ORDER = ("기업", "인구층", "금융투자은행", "유통", "지방정부")


def _entity_domestic_deposit(entity: Any, country_id: str) -> float:
    if getattr(entity, "deposits_currency", country_id) != country_id:
        return 0.0
    return max(0.0, float(getattr(entity, "deposits", 0.0) or 0.0))


def _entity_domestic_loan(entity: Any, country_id: str) -> float:
    if getattr(entity, "loan_currency", country_id) != country_id:
        return 0.0
    return max(0.0, float(getattr(entity, "loan_balance", 0.0) or 0.0))


def collect_commercial_bank_customer_balances(
    world: "World", bank: "Bank",
) -> Dict[str, Dict[str, float]]:
    cid = bank.country_id
    buckets: Dict[str, Dict[str, float]] = {
        name: {"deposits": 0.0, "loans": 0.0} for name in _BANK_CUSTOMER_ORDER
    }

    def _dep_here(entity) -> float:
        # 배분 오버레이: 이 은행에 예치된 슬라이스만 귀속 (주거래 은행 폴백 없음)
        d = getattr(entity, "deposit_alloc", None)
        if isinstance(d, dict) and d:
            if getattr(entity, "deposits_currency", cid) != cid:
                return 0.0
            return max(0.0, float(d.get(bank.id, 0.0) or 0.0))
        # 배분 맵 미생성분은 레거시 단일 소속으로 폴백
        if getattr(entity, "deposit_bank_id", None) == bank.id:
            return _entity_domestic_deposit(entity, cid)
        return 0.0

    def _loan_here(entity) -> float:
        sync_mortgage_loan_alloc(world, entity)
        d = getattr(entity, "loan_alloc", None)
        if isinstance(d, dict) and d:
            if getattr(entity, "loan_currency", cid) != cid:
                return 0.0
            return max(0.0, float(d.get(bank.id, 0.0) or 0.0))
        if getattr(entity, "loan_bank_id", None) == bank.id:
            return _entity_domestic_loan(entity, cid)
        return mortgage_principal_at_bank(world, entity, bank.id)

    for co in world.companies.values():
        st = world.states.get(co.home_state)
        if not st or st.country_id != cid:
            continue
        key = "유통" if isinstance(co, RetailCompany) else "기업"
        buckets[key]["deposits"] += _dep_here(co)
        buckets[key]["loans"] += _loan_here(co)
    for st in world.states.values():
        if st.country_id != cid:
            continue
        for pop in st.pops:
            buckets["인구층"]["deposits"] += _dep_here(pop)
            buckets["인구층"]["loans"] += _loan_here(pop)
        gov = st.local_government
        buckets["지방정부"]["deposits"] += _dep_here(gov)
        buckets["지방정부"]["loans"] += _loan_here(gov)
    for ib in world.ibs_in_country(cid):
        buckets["금융투자은행"]["deposits"] += _dep_here(ib)
        buckets["금융투자은행"]["loans"] += _loan_here(ib)
    return buckets


def _commercial_bank_customer_rows(
    buckets: Dict[str, Dict[str, float]], *, kind: str, limit: int = 6,
) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    for name in _BANK_CUSTOMER_ORDER:
        amount = buckets.get(name, {}).get(kind, 0.0)
        if amount <= 1e-6:
            continue
        rows.append({
            "label": _short_pie_label(name, 12),
            "sublabel": "",
            "value": amount,
            "amount": amount,
            "return_pct": 0.0,
            "return_detail": "",
            "show_return": False,
        })
    rows.sort(key=lambda row: row["value"], reverse=True)
    return rows[:limit]


def _commercial_bank_bond_holding_rows(
    world: "World", bank: "Bank", *, limit: int = 6,
) -> List[Dict[str, Any]]:
    merged: Dict[str, float] = defaultdict(float)
    for key, amount in bank.bond_portfolio.items():
        if amount > 1e-6:
            merged[key] += amount
    for key, amount in bank.foreign_bond_portfolio.items():
        if amount > 1e-6:
            merged[key] += amount
    rows: List[Dict[str, Any]] = []
    for key, amount in merged.items():
        rows.append(_bond_holding_panel_row(
            world, key, amount, bank.bond_purchase_rate.get(key, 0.0)))
    rows.sort(key=lambda row: row["value"], reverse=True)
    return rows[:limit]


def _draw_commercial_bank_auto_lending_panel(
    ax_left,
    ax_right,
    customer_balances: Dict[str, Dict[str, float]],
    *,
    auto_dep_pct: int,
) -> None:
    compact_bar_x = 0.20
    compact_bar_max_w = 0.68
    _draw_investment_bank_holdings_panel(
        ax_left,
        _commercial_bank_customer_rows(customer_balances, kind="deposits", limit=3),
        title="예금 (고객별 · 자산비중)",
        bar_color="#3182F6",
        text_color="#4A9AFF",
        max_rows=3,
        height=0.72,
        bar_x=compact_bar_x,
        bar_max_w=compact_bar_max_w,
    )
    _draw_investment_bank_holdings_panel(
        ax_right,
        _commercial_bank_customer_rows(customer_balances, kind="loans", limit=3),
        title="대출 (고객별)",
        bar_color="#F04452",
        text_color="#FF6B7A",
        max_rows=3,
        height=0.72,
        bar_x=compact_bar_x,
        bar_max_w=compact_bar_max_w,
    )


def _draw_commercial_bank_rates_strip(ax, bank: "Bank", world: Any = None) -> None:
    """재무 패널과 보유 채권 사이 — 예금·대출 금리·LDR 한 줄."""
    label_font = _load_project_chart_font(size=9)
    _mtg, _other, loans = bank_loan_asset_components(world, bank)
    deposits = float(getattr(bank, "deposits", 0.0) or 0.0)
    ldr = (loans / deposits) if deposits > 1e-9 else 0.0
    pricing = getattr(bank, "last_rate_pricing", None) or {}
    dep_tgt = pricing.get("deposit_target")
    loan_tgt = pricing.get("loan_target")
    line = (
        f"예금금리 {bank.deposit_rate:.2f}%"
        + (f" (목표 {float(dep_tgt):.2f})" if dep_tgt is not None else "")
        + f"   ·   대출금리 {bank.loan_rate:.2f}%"
        + (f" (목표 {float(loan_tgt):.2f})" if loan_tgt is not None else "")
        + f"   ·   LDR {ldr:.1%}"
    )
    parts = [
        (str(name), float(pp))
        for name, pp in (pricing.get("parts") or [])
        if abs(float(pp or 0.0)) >= 0.005
    ]
    parts.sort(key=lambda row: abs(row[1]), reverse=True)
    if parts:
        line += "   ·   " + "   ".join(
            f"{name} {pp:+.2f}%p" for name, pp in parts[:2])
    ax.text(
        0.5, 0.5, line,
        transform=ax.transAxes, va="center", ha="center",
        color=_STOCK_CHART_TEXT_DIM, fontproperties=label_font, fontsize=9,
    )


def commercial_bank_total_assets(world: Optional["World"], bank: "Bank") -> float:
    """시중은행 총자산 — 현금·대출(담보대출 포함)·채권시가·머니마켓 공여·외화·압류부동산."""
    rates = getattr(bank, "bond_purchase_rate", None)
    _mortgage, _other, loans = bank_loan_asset_components(world, bank)
    return (
        float(bank.cash or 0.0)
        + loans
        + bond_holdings_mark_value(world, bank.bond_portfolio, rates)
        + bond_holdings_mark_value(world, bank.foreign_bond_portfolio, rates)
        + float(getattr(bank, "call_lending", 0.0) or 0.0)
        + float(getattr(bank, "repo_lending", 0.0) or 0.0)
        + foreign_cash_home_value(
            bank.country_id, getattr(bank, "foreign_cash", None), world)
        + bank_foreclosure_holdings_value(world, bank)
    )


def commercial_bank_liabilities(bank: "Bank") -> float:
    """시중은행 부채 — 예금 + CB차입(증권금융 포함) + 콜/레포 차입 + 은행채.

    cb_securities_borrowing은 cb_borrowing의 일부이므로 따로 빼지 않는다.
    """
    return (
        float(bank.deposits or 0.0)
        + float(bank.cb_borrowing or 0.0)
        + float(getattr(bank, "call_borrowing", 0.0) or 0.0)
        + float(getattr(bank, "repo_borrowing", 0.0) or 0.0)
        + float(getattr(bank, "bond_balance", 0.0) or 0.0)
    )


def commercial_bank_net_assets(bank: "Bank", world: Any = None) -> float:
    """순자산 = 총자산 − 부채."""
    return commercial_bank_total_assets(world, bank) - commercial_bank_liabilities(bank)


def bank_invest_equity(bank: "Bank", world: Any = None) -> float:
    """시중은행 운용 자기자본 — 순자산(CB차입을 자본에 더하지 않음)."""
    return max(
        commercial_bank_net_assets(bank, world),
        MIN_INVESTMENT_BANK_EQUITY,
    )


def bank_required_cash(bank: "Bank", world: Any = None) -> float:
    """지급준비금 소요 — 예금 × 지준율."""
    if world is not None:
        country = world.countries.get(getattr(bank, "country_id", None))
        ratio = country_reserve_requirement_ratio(country)
    else:
        try:
            ratio = float(getattr(
                bank, "_reserve_ratio", DEFAULT_RESERVE_REQUIREMENT_RATIO) or 0.0)
        except (TypeError, ValueError):
            ratio = DEFAULT_RESERVE_REQUIREMENT_RATIO
        if not math.isfinite(ratio):
            ratio = DEFAULT_RESERVE_REQUIREMENT_RATIO
        ratio = clamp(ratio, 0.0, MAX_RESERVE_REQUIREMENT_RATIO)
    return max(0.0, float(getattr(bank, "deposits", 0.0) or 0.0) * ratio)


def bank_excess_cash(bank: "Bank", world: Any = None) -> float:
    """지준 위 운용 가능 현금."""
    return max(0.0, float(getattr(bank, "cash", 0.0) or 0.0) - bank_required_cash(bank, world))


def bank_deployable_cash(bank: "Bank", world: Any = None) -> float:
    """대출·채권·머니마켓에 쓸 수 있는 지준 초과 현금."""
    return bank_excess_cash(bank, world)


def bank_current_bonds(bank: "Bank") -> float:
    """시중은행 국내·해외 채권 액면 합."""
    return (
        sum(getattr(bank, "bond_portfolio", {}).values())
        + sum(getattr(bank, "foreign_bond_portfolio", {}).values())
    )


def bank_loan_capital_room(bank: "Bank", world: Any = None) -> float:
    """자기자본비율(BANK_TARGET_CAPITAL_RATIO) 기준 추가 대출 여력."""
    equity = max(0.0, commercial_bank_net_assets(bank, world))
    max_loans = equity / max(float(BANK_TARGET_CAPITAL_RATIO), 1e-9)
    _mortgage, _other, loans = bank_loan_asset_components(world, bank)
    return max(0.0, max_loans - loans)


def bank_loan_capacity(bank: "Bank", world: Any = None) -> float:
    """신규 대출 한도 = min(주간 잔여 목표, 지준초과 현금, 자본여력).

    주간 배분 캐시만 쓰면 같은 주 여러 대출이 한도를 재사용해 현금이 음수로
    갈 수 있으므로, 항상 실시간 여력으로 상한을 건다.
    """
    live = max(0.0, min(
        bank_deployable_cash(bank, world), bank_loan_capital_room(bank, world)))
    pack = getattr(bank, "_bank_alloc_pack", None)
    if isinstance(pack, dict) and "loan_capacity" in pack:
        if world is None or pack.get("week") == getattr(world, "week", None):
            cached = max(0.0, float(pack.get("loan_capacity") or 0.0))
            return min(cached, live)
    return live


def bank_consume_loan_capacity(
    bank: "Bank", amount: float, world: Any = None,
) -> None:
    """대출 실행 후 주간 잔여 loan_capacity를 깎는다."""
    amt = max(0.0, float(amount or 0.0))
    if amt <= 1e-12 or bank is None:
        return
    pack = getattr(bank, "_bank_alloc_pack", None)
    if not isinstance(pack, dict) or "loan_capacity" not in pack:
        return
    if world is not None and pack.get("week") != getattr(world, "week", None):
        return
    pack["loan_capacity"] = max(
        0.0, float(pack.get("loan_capacity") or 0.0) - amt)


def bank_max_cb_borrowing(world: "World", bank: "Bank") -> float:
    """은행 CB 차입 자기자본비율 규제 기준 최대 CB 차입(유동성+증권 합산)."""
    country = world.countries.get(bank.country_id)
    limit_pct = getattr(
        country, "bank_cb_leverage_ratio_pct", None)
    if limit_pct is None:
        limit_pct = getattr(
            country, "financial_leverage_ratio_pct", DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT)
    equity = max(0.0, commercial_bank_net_assets(bank, world))
    return equity * (float(limit_pct) / 100.0)


def entity_repo_collateral_value(ent) -> float:
    """레포 담보가치 — 보유 채권(국내+외화 국채) 시가 합. 은행·금투 공용."""
    dom = sum(getattr(ent, "bond_portfolio", {}).values())
    foreign = sum(getattr(ent, "foreign_bond_portfolio", {}).values())
    return max(0.0, dom + foreign)


def entity_repo_collateral_capacity(ent) -> float:
    """담보 × (1−헤어컷) = 레포 차입 총한도(자국화)."""
    return entity_repo_collateral_value(ent) * (1.0 - REPO_HAIRCUT)


def entity_repo_capacity_remaining(ent) -> float:
    """추가로 더 낼 수 있는 레포 차입 여력 — 담보한도 − 기존 레포(머니마켓+증권금융)."""
    used = (
        float(getattr(ent, "repo_borrowing", 0.0) or 0.0)
        + float(getattr(ent, "cb_securities_borrowing", 0.0) or 0.0)
    )
    return max(0.0, entity_repo_collateral_capacity(ent) - used)


def bank_cb_policy_leverage_pct(country: Optional["Country"]) -> float:
    """국가 은행 CB 차입 레버리지 한도 저장값(loan/equity×100)."""
    if country is None:
        return DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT
    limit_pct = getattr(country, "bank_cb_leverage_ratio_pct", None)
    if limit_pct is None:
        limit_pct = getattr(
            country, "financial_leverage_ratio_pct", DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT)
    try:
        return max(0.0, float(limit_pct))
    except (TypeError, ValueError):
        return DEFAULT_FINANCIAL_LEVERAGE_RATIO_PCT


def bank_cb_leverage_ratio_pct(world: "World", bank: "Bank") -> float:
    """CB차입 / 순자산 × 100. 자본잠식이면 inf."""
    equity = commercial_bank_net_assets(bank, world)
    cb = float(getattr(bank, "cb_borrowing", 0.0) or 0.0)
    if equity <= 1e-9:
        return 0.0 if cb <= 1e-9 and equity > -1e-9 else float("inf")
    return cb / equity * 100.0


def bank_settled_net_income(bank: "Bank") -> float:
    """결산 순수입 — 주간 손익 항목 합계(표시·스냅샷용)."""
    return (
        float(getattr(bank, "last_week_loan_interest_income", 0.0) or 0.0)
        - float(getattr(bank, "last_week_deposit_interest_expense", 0.0) or 0.0)
        + float(getattr(bank, "last_week_bond_interest_income", 0.0) or 0.0)
        - float(getattr(bank, "last_week_cb_borrowing_interest_expense", 0.0) or 0.0)
        + float(getattr(bank, "last_week_call_interest_income", 0.0) or 0.0)
        - float(getattr(bank, "last_week_call_interest_expense", 0.0) or 0.0)
        + float(getattr(bank, "last_week_repo_interest_income", 0.0) or 0.0)
        - float(getattr(bank, "last_week_repo_interest_expense", 0.0) or 0.0)
        - float(getattr(bank, "last_week_issued_bond_interest_expense", 0.0) or 0.0)
    )


def bank_settled_net_assets(bank: "Bank") -> float:
    return float(getattr(bank, "last_week_net_assets", 0.0) or 0.0)


def investment_bank_net_assets(world: "World", ib: "InvestmentBank") -> float:
    """금투 고유계정 순자산 = 누적 운용보수(retained_equity).

    주의: ib.deposits는 시중은행 예치금(자산)이다. 고객 펀드 부채는 fund_aum.
    펀드 NAV는 총자산 − 기타부채 − retained. 잔여를 min()으로 깎아
    숨기지 않는다. world는 호출 호환용.
    """
    _ = world
    return max(0.0, float(getattr(ib, "retained_equity", 0.0) or 0.0))


def investment_bank_settled_net_assets(ib: "InvestmentBank") -> float:
    return float(getattr(ib, "last_week_net_assets", 0.0) or 0.0)


def investment_bank_settled_net_income(ib: "InvestmentBank") -> float:
    """결산 순수입 — 고유계정만 (배당·보유이자는 펀드 NAV).

    운용보수 + 콜/레포 순이자 − 대출이자 − 금투채 이자.
    """
    return (
        float(getattr(ib, "last_week_fee_income", 0.0) or 0.0)
        + float(getattr(ib, "last_week_call_interest_income", 0.0) or 0.0)
        - float(getattr(ib, "last_week_call_interest_expense", 0.0) or 0.0)
        + float(getattr(ib, "last_week_repo_interest_income", 0.0) or 0.0)
        - float(getattr(ib, "last_week_repo_interest_expense", 0.0) or 0.0)
        - float(getattr(ib, "last_week_loan_interest_expense", 0.0) or 0.0)
        - float(getattr(ib, "last_week_issued_bond_interest_expense", 0.0) or 0.0)
    )


def _draw_commercial_bank_stats_panel(
    ax, bank: "Bank", world: "World",
) -> None:
    headline_font = _load_project_chart_font(size=_COMPANY_FINANCE_HEADLINE_VALUE_SIZE)
    detail_font = _load_project_chart_font(size=_COMPANY_FINANCE_DETAIL_VALUE_SIZE)
    label_font = _load_project_chart_font(size=_COMPANY_FINANCE_LABEL_SIZE)

    net_assets = commercial_bank_net_assets(bank, world)
    net_text, net_color = _company_net_income_display(bank_settled_net_income(bank))
    loan_int_text, loan_int_color = _ib_income_detail_display(
        float(getattr(bank, "last_week_loan_interest_income", 0.0) or 0.0))
    dep_int_text, dep_int_color = _ib_income_detail_display(
        -float(getattr(bank, "last_week_deposit_interest_expense", 0.0) or 0.0))
    bond_int_text, bond_int_color = _ib_income_detail_display(
        float(getattr(bank, "last_week_bond_interest_income", 0.0) or 0.0))
    cb_expense = float(getattr(bank, "last_week_cb_borrowing_interest_expense", 0.0) or 0.0)
    if cb_expense <= 1e-6:
        cb_int_text = _company_panel_income_money(0.0)
        cb_int_color = _STOCK_CHART_TEXT_DIM
    else:
        cb_int_text, cb_int_color = _ib_income_detail_display(-cb_expense)

    label_x = 0.04
    value_x = 0.96
    dep_val = float(getattr(bank, "deposits", 0.0) or 0.0)
    cb_val = float(getattr(bank, "cb_borrowing", 0.0) or 0.0)
    rows: List[Tuple[str, str, str, str]] = [
        ("headline", "주간 순수입", net_text, net_color),
        ("gap_sm", "", "", ""),
        ("detail", "주간 대출이자", loan_int_text, loan_int_color),
        ("detail", "주간 채권이자", bond_int_text, bond_int_color),
        ("detail", "주간 예금이자", dep_int_text, dep_int_color),
        ("detail", "주간 재할인이자", cb_int_text, cb_int_color),
        ("gap", "", "", ""),
        ("section", "부채", "", _STOCK_CHART_TEXT),
        ("detail", "예금", _company_panel_money(dep_val), _STOCK_CHART_TEXT),
        ("detail", "중앙은행 차입", _company_panel_money(cb_val), _STOCK_CHART_TEXT),
        ("gap", "", "", ""),
        ("headline", "순자산", _company_panel_money(net_assets),
         _COMPANY_LOSS_COLOR if net_assets < 0 else _IB_STATUS_COLOR),
    ]

    row_weights = {
        "headline": 1.75,
        "section": 1.25,
        "detail": 1.0,
        "gap": 0.70,
        "gap_sm": 0.42,
    }
    y_top = 0.97
    y_bottom = 0.05
    total_weight = sum(row_weights[kind] for kind, _, _, _ in rows)
    unit_h = (y_top - y_bottom) / max(total_weight, 1e-9)

    y = y_top
    for kind, label_text, value_text, color in rows:
        step = unit_h * row_weights[kind]
        if kind in ("gap", "gap_sm"):
            y -= step
            continue
        if kind == "headline":
            value_font = headline_font
            value_size = _COMPANY_FINANCE_HEADLINE_VALUE_SIZE
        elif kind == "section":
            ax.text(
                label_x, y, label_text,
                transform=ax.transAxes, va="top", ha="left",
                color=_STOCK_CHART_TEXT, fontproperties=label_font,
                fontsize=_COMPANY_FINANCE_LABEL_SIZE, **_chart_bold_text_kwargs(),
            )
            y -= step
            continue
        else:
            value_font = detail_font
            value_size = _COMPANY_FINANCE_DETAIL_VALUE_SIZE
        ax.text(
            label_x, y, label_text,
            transform=ax.transAxes, va="top", ha="left",
            color=_STOCK_CHART_TEXT, fontproperties=label_font,
            fontsize=_COMPANY_FINANCE_LABEL_SIZE,
        )
        if value_text:
            ax.text(
                value_x, y, value_text,
                transform=ax.transAxes, va="top", ha="right",
                color=color, fontproperties=value_font, fontsize=value_size,
                **_chart_bold_text_kwargs(),
            )
        y -= step


def _draw_commercial_bank_asset_pie(ax, bank: "Bank", world: "World") -> None:
    import matplotlib.patches as mpatches

    label_font = _load_project_chart_font(size=11)
    small_font = _load_project_chart_font(size=8)
    legend_rect_x = -0.16
    legend_text_x = -0.12

    ax.set_xlim(-0.32, 1.0)
    ax.set_ylim(0, 1)

    cash_val = float(getattr(bank, "cash", 0.0) or 0.0)
    dep_val = float(getattr(bank, "deposits", 0.0) or 0.0)
    _mortgage, _other, loan_val = bank_loan_asset_components(world, bank)
    domestic_bond = bond_holdings_mark_value(
        world, getattr(bank, "bond_portfolio", None),
        getattr(bank, "bond_purchase_rate", None))
    foreign_bond = bond_holdings_mark_value(
        world, getattr(bank, "foreign_bond_portfolio", None),
        getattr(bank, "bond_purchase_rate", None))
    fx_value = foreign_cash_home_value(
        bank.country_id, getattr(bank, "foreign_cash", None), world)
    slices = [
        ("현금", max(0.0, cash_val)),
        ("예금", max(0.0, dep_val)),
        ("대출", max(0.0, loan_val)),
        ("국내채권", max(0.0, domestic_bond)),
        ("해외채권", max(0.0, foreign_bond)),
        ("외화", max(0.0, fx_value)),
    ]
    sizes = [val for _, val in slices if val > 1e-6]
    colors = _BANK_STATUS_PIE_COLORS[: len(sizes)]

    ax.text(
        legend_rect_x, 0.98, "자산 구성",
        transform=ax.transAxes, va="top", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=11,
        **_chart_bold_text_kwargs(),
    )
    if not sizes:
        ax.text(
            0.5, 0.45, "표시할 자산이 없습니다.",
            transform=ax.transData, va="center", ha="center",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font,
        )
        return

    _, _, autotexts = ax.pie(
        sizes,
        labels=None,
        colors=colors,
        autopct=lambda pct: f"{pct:.0f}%" if pct >= 6 else "",
        pctdistance=0.78,
        startangle=90,
        radius=0.52,
        center=(0.68, 0.42),
        wedgeprops={"width": 0.34, "edgecolor": _STOCK_CHART_BG, "linewidth": 1.0},
    )
    for autotext in autotexts:
        autotext.set_color(_STOCK_CHART_TEXT)
        autotext.set_fontsize(7)
        autotext.set_fontproperties(small_font)

    legend_y = 0.88
    for idx, (name, val) in enumerate(
        [(n, v) for n, v in slices if v > 1e-6][:6]
    ):
        color = colors[idx]
        y = legend_y - idx * 0.11
        swatch = mpatches.Rectangle(
            (legend_rect_x, y - 0.025), 0.018, 0.05,
            facecolor=color, edgecolor="none", clip_on=False,
            transform=ax.transAxes,
        )
        ax.add_patch(swatch)
        ax.text(
            legend_text_x, y,
            f"{name}  {format_currency_short(val)}",
            transform=ax.transAxes, va="center", ha="left",
            color=_STOCK_CHART_TEXT, fontproperties=small_font, fontsize=8,
            clip_on=False,
        )
    ax.set_xlim(-0.32, 1.0)
    ax.set_ylim(0, 1)


def create_commercial_bank_status_panel(
    world: "World", country_id: str,
) -> Optional[io.BytesIO]:
    """시중은행 현황 패널 이미지."""
    bank = world.banks.get(country_id) or world.banks.get(f"bank_{country_id}")
    if not bank:
        return None
    world.reconcile_mortgage_loan_ledgers()

    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    _configure_project_matplotlib_font()
    title_font = _load_project_chart_font(size=15)
    small_font = _load_project_chart_font(size=9)

    country = world.countries.get(bank.country_id)
    country_name = getattr(country, "name", bank.country_id)
    customer_balances = collect_commercial_bank_customer_balances(world, bank)
    auto_dep_pct = int(round(AUTO_DEPOSIT_RATIO * 100))

    fig = plt.figure(figsize=(14.5, 7.8))
    fig.patch.set_facecolor(_STOCK_CHART_BG)
    gs = fig.add_gridspec(
        2, 2, width_ratios=[1.05, 1.0], height_ratios=[1.0, 1.05],
        wspace=0.14, hspace=0.18,
    )

    ax_pie = fig.add_subplot(gs[0, 0])
    right_col = gs[:, 1].subgridspec(3, 1, height_ratios=[1.0, 0.09, 1.0], hspace=0.06)
    ax_stats = fig.add_subplot(right_col[0, 0])
    ax_rates = fig.add_subplot(right_col[1, 0])
    ax_bonds = fig.add_subplot(right_col[2, 0])
    auto_inner = gs[1, 0].subgridspec(1, 2, wspace=0.22)
    ax_deposits = fig.add_subplot(auto_inner[0, 0])
    ax_loans = fig.add_subplot(auto_inner[0, 1])

    for ax in (ax_stats, ax_pie, ax_rates, ax_deposits, ax_loans, ax_bonds):
        ax.set_facecolor(_STOCK_CHART_BG)
        for spine in ax.spines.values():
            spine.set_visible(False)
        ax.axis("off")
        ax.set_xlim(0, 1)
        ax.set_ylim(0, 1)

    fig.text(
        0.5, 0.965, f"{bank.name} · 시중은행 현황",
        ha="center", va="top", color=_STOCK_CHART_TEXT,
        fontproperties=title_font, fontsize=15,
    )
    fig.text(
        0.5, 0.925,
        f"{country_name}  ·  {week_to_date_label(world.week, world_start_year(world), style='long')}  ·  "
        f"순자산 {_company_panel_money(commercial_bank_net_assets(bank, world))}  ·  "
        f"예금 자산비중 기반",
        ha="center", va="top", color=_STOCK_CHART_TEXT_DIM,
        fontproperties=small_font, fontsize=9,
    )

    _draw_commercial_bank_asset_pie(ax_pie, bank, world)
    _draw_commercial_bank_stats_panel(ax_stats, bank, world)
    _draw_commercial_bank_rates_strip(ax_rates, bank, world)
    _draw_commercial_bank_auto_lending_panel(
        ax_deposits, ax_loans, customer_balances, auto_dep_pct=auto_dep_pct,
    )
    _draw_investment_bank_holdings_panel(
        ax_bonds,
        _commercial_bank_bond_holding_rows(world, bank),
        title="보유 채권",
        bar_color=_BANK_STATUS_COLOR,
        text_color="#4A9AFF",
    )

    fig.subplots_adjust(left=0.055, right=0.965, top=0.88, bottom=0.06)
    buf = io.BytesIO()
    plt.savefig(
        buf, format="png", facecolor=fig.get_facecolor(),
        bbox_inches="tight", pad_inches=0.16,
    )
    buf.seek(0)
    plt.close(fig)
    return buf


def _draw_company_production_panel(
    ax,
    rows: List[Dict[str, Any]],
    *,
    title: str,
    bar_color: str,
    text_color: str,
    y_top: float = 0.88,
    height: float = 0.72,
) -> None:
    label_font = _load_project_chart_font(size=11)
    small_font = _load_project_chart_font(size=9)
    ax.text(
        0.02, y_top + 0.04, title,
        transform=ax.transAxes, va="top", ha="left",
        color=_STOCK_CHART_TEXT, fontproperties=label_font, fontsize=11,
    )
    if not rows:
        ax.text(
            0.02, y_top - 0.06, "표시할 생산 데이터가 없습니다.",
            transform=ax.transAxes, va="top", ha="left",
            color=_STOCK_CHART_TEXT_DIM, fontproperties=small_font,
        )
        return

    display_rows, row_h = _company_panel_fit_rows(
        rows[:_COMPANY_PANEL_TOP_N], height=height, min_row_h=_COMPANY_PANEL_MIN_ROW_H,
    )

    row_gap = row_h
    for idx, row in enumerate(display_rows):
        y_center = y_top - _COMPANY_PANEL_TITLE_BODY_GAP - idx * row_gap
        level_text = f"Lv.{row['levels']}" if row["levels"] > 0 else "건설"
        if row.get("is_construction"):
            _draw_company_panel_construction_bar_row(
                ax,
                y_center=y_center,
                label=row["label"],
                sublabel=f"{row['state']} · {level_text}",
                progress_ratio=row.get("construction_pct", 0.0),
                inner_text=(
                    f"건설 {row.get('construction_pct', 0.0) * 100:.0f}%  ·  "
                    f"서비스 {row.get('construction_services', 0.0):,.1f}  ·  "
                    f"{row.get('construction_progress', 0.0):,.0f}/"
                    f"{row.get('construction_target', 0.0):,.0f}"
                ),
            )
        else:
            _draw_company_panel_single_bar_row(
                ax,
                y_center=y_center,
                label=row["label"],
                sublabel=f"{row['state']} · {level_text}",
                bar_ratio=row["utilization"],
                bar_color=bar_color,
                text_color=text_color,
                inner_text=(
                    f"생산 {row['output']:,.1f}  ·  "
                    f"용량 {row['utilization'] * 100:.0f}%  ·  "
                    f"투입 {row['input_fill'] * 100:.0f}%"
                ),
                bar_alpha=0.26,
            )


def stock_holding_market_value(
    world: "World",
    issuer_id: str,
    shares: float,
    avg_cost: float = 0.0,
) -> float:
    if shares <= 1e-9:
        return 0.0
    return shares * stock_holding_mark_price(world, issuer_id, avg_cost)


def stock_holdings_total_value(
    world: "World",
    holdings: Dict[str, float],
    avg_costs: Optional[Dict[str, float]] = None,
) -> float:
    """보유 주식 총평가 — 상장 시장가 + 개인 소유(협력사) 공정가 할인 + 그 외 원가."""
    if not holdings:
        return 0.0
    costs = avg_costs or {}
    total = 0.0
    for issuer_id, shares in holdings.items():
        sh = float(shares or 0.0)
        if sh <= 1e-9:
            continue
        try:
            cost = float(costs.get(issuer_id, 0.0) or 0.0)
        except (TypeError, ValueError):
            cost = 0.0
        total += sh * stock_holding_mark_price(world, issuer_id, cost)
    return total


def stock_holdings_portfolio_value(
    world: "World",
    holdings: Dict[str, float],
    avg_costs: Optional[Dict[str, float]] = None,
) -> float:
    """인구 포트폴리오 구성용 주식 평가 — 개인 소유(협력사) 지분 제외."""
    if not holdings:
        return 0.0
    costs = avg_costs or {}
    total = 0.0
    for issuer_id, shares in holdings.items():
        sh = float(shares or 0.0)
        if sh <= 1e-9:
            continue
        if stock_issuer_is_personal_equity(world, issuer_id):
            continue
        try:
            cost = float(costs.get(issuer_id, 0.0) or 0.0)
        except (TypeError, ValueError):
            cost = 0.0
        total += sh * stock_holding_mark_price(world, issuer_id, cost)
    return total


def stock_holdings_personal_equity_value(
    world: "World",
    holdings: Dict[str, float],
) -> float:
    """개인 소유 비상장 지분(협력사) 가치 — 공정가 할인."""
    if not holdings:
        return 0.0
    total = 0.0
    for issuer_id, shares in holdings.items():
        sh = float(shares or 0.0)
        if sh <= 1e-9:
            continue
        if not stock_issuer_is_personal_equity(world, issuer_id):
            continue
        total += sh * stock_personal_equity_mark_price(world, issuer_id)
    return total


def stock_holdings_fair_value(
    world: "World",
    holdings: Dict[str, float],
) -> float:
    """보유 주식 공정가 합 — 상장 시장가, 미상장·미형성 시 펀더멘털 공정가."""
    total = 0.0
    for issuer_id, shares in (holdings or {}).items():
        sh = float(shares or 0.0)
        if sh <= 1e-9:
            continue
        total += sh * stock_issuer_reference_price(world, issuer_id)
    return total


def _warmup_is_financial_stock_issuer(world: "World", issuer_id: str) -> bool:
    """시중은행·금투·중앙은행 주식 — 국채 시드 기준으로 쓰지 않는다."""
    key = str(issuer_id or "")
    if not key:
        return False
    banks = getattr(world, "banks", None) or {}
    ibs = getattr(world, "investment_banks", None) or {}
    cbs = getattr(world, "central_banks", None) or {}
    if key in banks or key in ibs or key in cbs:
        return True
    if key.startswith("bank_") and key[5:] in banks:
        return True
    if key.startswith("ib_") and key[3:] in ibs:
        return True
    return False


def warmup_ib_nonfinancial_stock_fair_value(
    world: "World",
    holdings: Dict[str, float],
) -> float:
    """금투 국채 시드용 주식 공정가 — 은행·금투 교차보유지분 제외.

    워밍업에서 금투는 은행·다른 금투 주식을 35~70% 보유한다. 그 시총에
    ib_bond_to_stock을 곱해 국채를 신규 발행하면 금융주가 국채로 한 번 더
    찍혀 과다 발행된다.
    """
    total = 0.0
    for issuer_id, shares in (holdings or {}).items():
        sh = float(shares or 0.0)
        if sh <= 1e-9:
            continue
        if _warmup_is_financial_stock_issuer(world, issuer_id):
            continue
        total += sh * stock_issuer_reference_price(world, issuer_id)
    return total


def warmup_gov_bond_face_for_proceeds(proceeds: float, rate: float) -> float:
    """워밍업 국채 매입 대금에 해당하는 액면. 변동금리채라 액면=대금."""
    cash = max(0.0, float(proceeds or 0.0))
    if cash <= 1e-12:
        return 0.0
    px = float(bond_discount_price(1.0, rate))
    if px <= 1e-12:
        return cash
    return cash / px


def ib_cash_like_home_value(world: "World", ib: "InvestmentBank") -> float:
    """현금성 자산 — 현금·예금·외화환산·콜론·역레포."""
    return (
        max(0.0, float(getattr(ib, "cash", 0.0) or 0.0))
        + max(0.0, float(getattr(ib, "deposits", 0.0) or 0.0))
        + max(0.0, float(getattr(ib, "call_lending", 0.0) or 0.0))
        + max(0.0, float(getattr(ib, "repo_lending", 0.0) or 0.0))
        + foreign_cash_home_value(
            ib.country_id, getattr(ib, "foreign_cash", None), world)
    )


def ib_cash_like_overweight(world: "World", ib: "InvestmentBank") -> bool:
    aum = max(ib.allocation_aum(world), 1e-9)
    return ib_cash_like_home_value(world, ib) / aum > IB_MACRO_CASH_CEILING


def investment_bank_total_assets(world: "World", ib: "InvestmentBank") -> float:
    """금투 총자산 — 운용자산·은행예치·머니마켓 공여·외화(환율 환산)."""
    return (
        float(ib.total_aum(world) or 0.0)
        + float(getattr(ib, "deposits", 0.0) or 0.0)
        + float(getattr(ib, "call_lending", 0.0) or 0.0)
        + float(getattr(ib, "repo_lending", 0.0) or 0.0)
        + foreign_cash_home_value(
            ib.country_id, getattr(ib, "foreign_cash", None), world)
    )


def investment_bank_other_liabilities(ib: "InvestmentBank") -> float:
    """펀드 부채를 제외한 금투 부채 (은행대출·콜/레포 차입·금투채)."""
    return (
        float(getattr(ib, "loan_balance", 0.0) or 0.0)
        + float(getattr(ib, "call_borrowing", 0.0) or 0.0)
        + float(getattr(ib, "repo_borrowing", 0.0) or 0.0)
        + float(getattr(ib, "bond_balance", 0.0) or 0.0)
    )


def investment_bank_fund_nav(world: "World", ib: "InvestmentBank") -> float:
    """펀드 NAV = 운용자산 − 펀드 외 부채 − 금투 유보자기자본(누적 수수료)."""
    assets = investment_bank_total_assets(world, ib)
    other = investment_bank_other_liabilities(ib)
    retained = max(0.0, float(getattr(ib, "retained_equity", 0.0) or 0.0))
    return max(0.0, assets - other - retained)


def investment_bank_apply_seed_equity(ib: "InvestmentBank") -> float:
    """워밍업·설립 시 GP 시드. 고객 NAV에서 자기자본을 떼어 공동투자한다."""
    aum = max(0.0, float(getattr(ib, "fund_aum", 0.0) or 0.0))
    target = max(float(MIN_INVESTMENT_BANK_EQUITY), aum * float(IB_SEED_EQUITY_TO_AUM))
    have = max(0.0, float(getattr(ib, "retained_equity", 0.0) or 0.0))
    if have + 1e-9 >= target:
        return 0.0
    ib.retained_equity = target
    return target - have


def investment_bank_apply_leverage_first_loss(
    world: "World", ib: "InvestmentBank", prev_nav: float, nav: float,
) -> float:
    """레버리지 슬리브 손실은 금투 자기자본이 먼저 부담. 반환=고객 NAV 보전액.

    NAV = 자산 − 부채 − retained 이므로 retained를 깎으면 다음 마크에서
    고객 NAV가 그 금액만큼 회복된다.
    """
    pnl = float(nav or 0.0) - float(prev_nav or 0.0)
    if pnl >= -1e-9:
        return 0.0
    retained = max(0.0, float(getattr(ib, "retained_equity", 0.0) or 0.0))
    if retained <= 1e-9:
        return 0.0
    assets = max(investment_bank_total_assets(world, ib), 1e-9)
    debt = max(0.0, investment_bank_other_liabilities(ib))
    levered_share = clamp(debt / assets, 0.0, 1.0)
    absorb = min(-pnl * levered_share, retained)
    if absorb > 1e-9:
        ib.retained_equity = retained - absorb
    return absorb


# 워밍업 금투: 시드 증권은 전액 펀드 유입으로 매입. 못 사면 미펀딩 주식을 줄인다.
WARMUP_CUSTOMER_ORIGIN_FRAC = 1.0
# 시중은행 자기자본(예금 대비) — 지준 위 현금이 아니라 국채 등 운용자산으로 보유
WARMUP_BANK_EQUITY_TO_DEPOSITS = 0.08
# 본게임 순자산 상한(예금 대비). 워밍업 8%보다 넓게 두어 유보이익은 남긴다.
BANK_MAX_EQUITY_TO_DEPOSITS = 0.20
# 콜론+역레포 상한(예금 대비). 주초에 전주 포지션을 만기 상환하므로
# 주말 잔여를 공여해도 주중 채권·대출이 잠기지 않는다.
# 10%면 대출 수요가 없을 때 지준 초과현금이 장부에 쌓인다.
BANK_MAX_MM_LEND_TO_DEPOSITS = 1.00


def warmup_issue_gov_bonds_to_holder(
    world: "World",
    country_id: str,
    holder: Any,
    face_amount: float,
) -> float:
    """국채를 즉시 발행해 보유자 포트폴리오에 편입(워밍업 비중 조절용).

    대금은 국고에 입고하고, 액면은 국가 국채 잔액·매각 누적에 반영한다.
    POP/IB는 bond_holdings, 시중은행은 bond_portfolio를 사용한다.
    """
    face = max(0.0, float(face_amount or 0.0))
    if face <= 1e-9:
        return 0.0
    country = world.countries.get(country_id)
    if country is None:
        return 0.0
    gov_key = f"gov_{country_id}"
    bm = world.bond_markets.get(gov_key)
    if bm is None and hasattr(world, "_ensure_bond_market"):
        bm = world._ensure_bond_market(gov_key)
    rate = float(
        getattr(bm, "current_interest_rate", 0.0) or 0.0
    ) if bm is not None else country_base_rate(country)
    if rate <= 1e-12:
        rate = country_base_rate(country)
    proceeds = float(bond_discount_price(face, rate))
    country.treasury = float(getattr(country, "treasury", 0.0) or 0.0) + proceeds
    country.gov_bond_balance = float(getattr(country, "gov_bond_balance", 0.0) or 0.0) + face
    country.gov_bond_sold_cumulative = (
        float(getattr(country, "gov_bond_sold_cumulative", 0.0) or 0.0) + face)
    warmup_credit_bond_holding(world, holder, gov_key, face, rate)
    return face


def warmup_credit_bond_holding(
    world: "World",
    holder: Any,
    market_key: str,
    face_amount: float,
    rate: float,
) -> None:
    """워밍업 시드: 보유자에게 채권 액면을 편입 (시중은행·CB는 portfolio, 그 외 holdings)."""
    face = max(0.0, float(face_amount or 0.0))
    if face <= 1e-9 or holder is None:
        return
    holder_id = str(getattr(holder, "id", "") or "")
    use_bank_portfolio = (
        holder_id in getattr(world, "banks", {})
        or holder_id in getattr(world, "central_banks", {})
        or (
            hasattr(holder, "bond_portfolio")
            and not hasattr(holder, "bond_holdings")
        )
    )
    if use_bank_portfolio:
        port = getattr(holder, "bond_portfolio", None)
        if port is None:
            holder.bond_portfolio = defaultdict(float)
            port = holder.bond_portfolio
        port[market_key] = float(port.get(market_key, 0.0) or 0.0) + face
    else:
        holdings = getattr(holder, "bond_holdings", None)
        if holdings is None:
            holder.bond_holdings = defaultdict(float)
            holdings = holder.bond_holdings
        holdings[market_key] = float(holdings.get(market_key, 0.0) or 0.0) + face
    rates = getattr(holder, "bond_purchase_rate", None)
    if rates is None:
        holder.bond_purchase_rate = defaultdict(float)
        rates = holder.bond_purchase_rate
    rates[market_key] = float(rate or 0.0)


def _warmup_holder_bond_ports(world: "World", holder: Any) -> List[Dict[str, float]]:
    """시중은행·CB는 bond_portfolio(+외화), 그 외는 bond_holdings."""
    holder_id = str(getattr(holder, "id", "") or "")
    use_bank_portfolio = (
        holder_id in getattr(world, "banks", {})
        or holder_id in getattr(world, "central_banks", {})
        or (
            hasattr(holder, "bond_portfolio")
            and not hasattr(holder, "bond_holdings")
        )
    )
    ports: List[Dict[str, float]] = []
    if use_bank_portfolio:
        for name in ("bond_portfolio", "foreign_bond_portfolio"):
            port = getattr(holder, name, None)
            if port:
                ports.append(port)
    else:
        holdings = getattr(holder, "bond_holdings", None)
        if holdings:
            ports.append(holdings)
    return ports


def warmup_cut_gov_bond_mark(
    world: "World",
    holder: Any,
    country_id: str,
    mark_amount: float,
) -> float:
    """국채 시가를 대금 없이 줄인다.

    예금이 빠져 나간 뒤에도 국채만 남아 은행 순자산이 부푸는 불일치를
    맞출 때 쓴다. 자국 국채를 먼저 줄이고, 모자라면 다른 나라 국채.
    회사채는 발행사 원장이 있어 건드리지 않는다.
    """
    want = max(0.0, float(mark_amount or 0.0))
    if want <= 1e-9 or holder is None:
        return 0.0
    prefer = f"gov_{country_id}"
    rates = getattr(holder, "bond_purchase_rate", None)
    cut_total = 0.0
    for port in _warmup_holder_bond_ports(world, holder):
        if want - cut_total <= 1e-9:
            break
        keys = [k for k in list(port.keys()) if str(k).startswith("gov_")]
        keys.sort(key=lambda k: (0 if str(k) == prefer else 1, str(k)))
        for key in keys:
            remain = want - cut_total
            if remain <= 1e-9:
                break
            face = float(port.get(key, 0.0) or 0.0)
            if face <= 1e-12:
                continue
            buy_rate = float((rates or {}).get(key, 0.0) or 0.0)
            mark = float(bond_holding_mark_value(world, str(key), face, buy_rate) or 0.0)
            if mark <= 1e-12:
                mark = face
            take_mark = min(mark, remain)
            face_cut = face * (take_mark / mark) if mark > 1e-12 else face
            new_face = face - face_cut
            if new_face <= 1e-9:
                port.pop(key, None)
                if rates is not None:
                    rates.pop(key, None)
            else:
                port[key] = new_face
            issuer_cid = str(key)[4:] if str(key).startswith("gov_") else ""
            country = (getattr(world, "countries", None) or {}).get(issuer_cid)
            if country is not None:
                country.gov_bond_balance = max(
                    0.0,
                    float(getattr(country, "gov_bond_balance", 0.0) or 0.0) - face_cut)
                country.gov_bond_sold_cumulative = max(
                    0.0,
                    float(getattr(country, "gov_bond_sold_cumulative", 0.0) or 0.0)
                    - face_cut)
            cut_total += take_mark
    return cut_total


def commercial_bank_money_market_assets(bank: "Bank") -> float:
    """콜론+역레포 원금."""
    return (
        max(0.0, float(getattr(bank, "call_lending", 0.0) or 0.0))
        + max(0.0, float(getattr(bank, "repo_lending", 0.0) or 0.0))
    )


def bank_mm_lend_room(bank: "Bank") -> float:
    """예금 대비 머니마켓 공여 잔여 한도."""
    deposits = max(0.0, float(getattr(bank, "deposits", 0.0) or 0.0))
    cap = deposits * BANK_MAX_MM_LEND_TO_DEPOSITS
    return max(0.0, cap - commercial_bank_money_market_assets(bank))


def bank_cut_money_market_assets(bank: "Bank", amount: float) -> float:
    """콜론·역레포를 대금 없이 줄인다. 소각액 반환."""
    want = max(0.0, float(amount or 0.0))
    cut = 0.0
    for attr in ("repo_lending", "call_lending"):
        remain = want - cut
        if remain <= 1e-9:
            break
        have = max(0.0, float(getattr(bank, attr, 0.0) or 0.0))
        take = min(have, remain)
        if take > 1e-9:
            setattr(bank, attr, have - take)
            cut += take
    return cut


def bank_cut_excess_cash(bank: "Bank", amount: float, *, floor: float = 0.0) -> float:
    """현금을 floor 아래로 내려가지 않게 깎는다. 삭감액 반환."""
    cash = max(0.0, float(getattr(bank, "cash", 0.0) or 0.0))
    take = min(max(0.0, cash - max(0.0, float(floor or 0.0))), max(0.0, float(amount or 0.0)))
    if take > 1e-9:
        bank.cash = cash - take
        return take
    return 0.0


def cap_commercial_bank_money_market_lending(bank: "Bank") -> float:
    """예금 대비 콜론+역레포 초과분을 현금으로 되돌린다(재분류, 순자산 불변)."""
    extra = commercial_bank_money_market_assets(bank) - (
        max(0.0, float(getattr(bank, "deposits", 0.0) or 0.0))
        * BANK_MAX_MM_LEND_TO_DEPOSITS
    )
    if extra <= 1.0:
        return 0.0
    remaining = extra
    for attr in ("repo_lending", "call_lending"):
        if remaining <= 1e-9:
            break
        have = max(0.0, float(getattr(bank, attr, 0.0) or 0.0))
        take = min(have, remaining)
        if take > 1e-9:
            setattr(bank, attr, have - take)
            bank.cash = float(getattr(bank, "cash", 0.0) or 0.0) + take
            remaining -= take
    return extra - remaining


def trim_commercial_bank_excess_net_assets(
    world: "World",
    bank: "Bank",
    *,
    target_ratio: float,
) -> float:
    """순자산이 예금×target_ratio를 넘으면 역레포·콜론 → 현금(지준 위) → 국채 순으로 소각.

    유휴 유동성(역레포·지준 초과 현금)을 먼저 지운다. 현금이 이미 지준
    이하인데도 순자산이 크면 그때만 국채를 줄인다. 대출·회사채는
    고객 원장이 있어 건드리지 않는다.
    """
    deposits = max(0.0, float(getattr(bank, "deposits", 0.0) or 0.0))
    target = deposits * max(0.0, float(target_ratio or 0.0))
    trimmed = 0.0
    cid = str(getattr(bank, "country_id", "") or "")
    for _ in range(6):
        excess = commercial_bank_net_assets(bank, world) - target
        if excess <= 1.0:
            break
        step = bank_cut_money_market_assets(bank, excess)
        if excess - step > 1.0:
            required = bank_required_cash(bank, world)
            step += bank_cut_excess_cash(bank, excess - step, floor=required)
        if excess - step > 1.0:
            step += warmup_cut_gov_bond_mark(world, bank, cid, excess - step)
        if step <= 1e-9:
            break
        trimmed += step
    return trimmed


def bank_refresh_displayed_assets(world: "World", bank: "Bank") -> None:
    """패널용 last_week 자산 항목만 현재 잔액으로 맞춘다. 손익 스냅샷은 건드리지 않는다."""
    rates = getattr(bank, "bond_purchase_rate", None)
    bank.last_week_cash = float(getattr(bank, "cash", 0.0) or 0.0)
    bank.last_week_deposits = float(getattr(bank, "deposits", 0.0) or 0.0)
    _mortgage, _other, loans = bank_loan_asset_components(world, bank)
    bank.last_week_loans = loans
    bank.last_week_call_lending = float(getattr(bank, "call_lending", 0.0) or 0.0)
    bank.last_week_repo_lending = float(getattr(bank, "repo_lending", 0.0) or 0.0)
    bank.last_week_call_borrowing = float(getattr(bank, "call_borrowing", 0.0) or 0.0)
    bank.last_week_repo_borrowing = float(getattr(bank, "repo_borrowing", 0.0) or 0.0)
    bank.last_week_domestic_bond = bond_holdings_mark_value(
        world, getattr(bank, "bond_portfolio", None), rates)
    bank.last_week_foreign_bond = bond_holdings_mark_value(
        world, getattr(bank, "foreign_bond_portfolio", None), rates)
    bank.last_week_fx_value = foreign_cash_home_value(
        getattr(bank, "country_id", None), getattr(bank, "foreign_cash", None), world)
    bank.last_week_total_assets = commercial_bank_total_assets(world, bank)
    bank.last_week_net_assets = commercial_bank_net_assets(bank, world)


def bank_settle_deposit_cash_outflow(
    world: "World",
    bank: "Bank",
    amount: float,
) -> None:
    """예금 인출·이전만큼 은행 자산을 줄인다.

    현금만 0으로 깎고 국채·역레포를 남기면 부채만 사라져 순자산이 복사된다.
    현금이 모자라면 국채·머니마켓 공여를 같은 금액만큼 소각한다.
    """
    amt = max(0.0, float(amount or 0.0))
    if amt <= 1e-12 or bank is None:
        return
    cash = float(getattr(bank, "cash", 0.0) or 0.0)
    from_cash = min(max(0.0, cash), amt)
    bank.cash = cash - from_cash
    short = amt - from_cash
    if short > 1e-9:
        cut = warmup_cut_gov_bond_mark(
            world, bank, str(getattr(bank, "country_id", "") or ""), short)
        short -= cut
    if short > 1e-9:
        short -= bank_cut_money_market_assets(bank, short)
    if short > 1e-9:
        bank.cash = float(getattr(bank, "cash", 0.0) or 0.0) - short


def warmup_issue_corp_bonds_to_holder(
    world: "World",
    company: Any,
    holder: Any,
    face_amount: float,
    *,
    week: int = 0,
    credit_issuer_cash: bool = False,
) -> float:
    """회사채를 즉시 발행해 은행·금투 포트폴리오에 편입(마지막 워밍업 시드).

    기본은 과거 설비 투자분(현금 미입고). credit_issuer_cash=True 이면 대금도 입고.
    """
    face = max(0.0, float(face_amount or 0.0))
    if face <= 1e-9 or company is None:
        return 0.0
    co_id = str(getattr(company, "id", "") or "")
    if not co_id:
        return 0.0
    bm = world.bond_markets.get(co_id)
    if bm is None and hasattr(world, "_ensure_bond_market"):
        bm = world._ensure_bond_market(co_id)
    st = (getattr(world, "states", None) or {}).get(
        str(getattr(company, "home_state", "") or ""))
    cid = str(getattr(st, "country_id", "") or "") if st else ""
    country = (getattr(world, "countries", None) or {}).get(cid)
    rate = float(
        getattr(bm, "current_interest_rate", 0.0) or 0.0
    ) if bm is not None else 0.0
    if rate <= 1e-12:
        rate = country_base_rate(country) + 1.0
    proceeds = float(bond_discount_price(face, rate))
    if credit_issuer_cash:
        company.cash = float(getattr(company, "cash", 0.0) or 0.0) + proceeds
    company.bond_balance = float(getattr(company, "bond_balance", 0.0) or 0.0) + face
    tenor = 5
    tw = bond_tenor_weeks(tenor)
    elapsed = max(1, tw // 2)
    _bond_principal_lots(company).append({
        "face": face,
        "issue_week": int(week) - elapsed,
        "tenor_years": tenor,
        "mature_week": int(week) + (tw - elapsed),
    })
    warmup_credit_bond_holding(world, holder, co_id, face, rate)
    return face


def stock_issuer_entity(world: "World", issuer_id: str) -> Optional[Any]:
    co = world.companies.get(issuer_id)
    if co:
        return co
    bank = world.banks.get(issuer_id)
    if not bank and issuer_id.startswith("bank_"):
        bank = world.banks.get(issuer_id[5:])
    if bank:
        return bank
    ib = world.investment_banks.get(issuer_id)
    if not ib and issuer_id.startswith("ib_"):
        ib = world.investment_banks.get(issuer_id[3:])
    return ib


def clear_stock_held_cache(world: "World") -> None:
    """유통·보유 주식 캐시 무효화 (체결·배분 후 호출)."""
    world._fin_cache_stock_held = None


def _build_stock_held_cache(world: "World") -> Dict[str, float]:
    """전 보유 주체를 1회 순회해 issuer→보유주식 합계 인덱스 구축."""
    held: Dict[str, float] = defaultdict(float)
    for cb in world.central_banks.values():
        for iid, qty in cb.stock_portfolio.items():
            if qty > 1e-15:
                held[iid] += qty
    for ib in world.investment_banks.values():
        for iid, qty in ib.stock_holdings.items():
            if qty > 1e-15:
                held[iid] += qty
    for country in world.countries.values():
        for iid, qty in country.stock_holdings.items():
            if qty > 1e-15:
                held[iid] += qty
    pops = world._fin_idx_pops
    if pops is not None:
        pop_iter = pops.values()
    else:
        pop_iter = (pop for st in world.states.values() for pop in st.pops)
    for pop in pop_iter:
        holdings = pop.stock_holdings
        if not holdings:
            continue
        for iid, qty in holdings.items():
            if qty > 1e-15:
                held[iid] += qty
    # 기업→기업 보유. 자기주식(treasury)도 held에 포함해 float=issued−held에서 유통 제외.
    for co in world.companies.values():
        holdings = getattr(co, "stock_holdings", None) or {}
        if not holdings:
            continue
        for iid, qty in holdings.items():
            q = float(qty or 0.0)
            if q <= 1e-15:
                continue
            held[iid] += q
    return dict(held)


def ensure_stock_held_cache(world: "World") -> Dict[str, float]:
    """당주 보유주식 합계 캐시. 미스 시 전수 1회 스캔으로 구축."""
    cache = world._fin_cache_stock_held
    if cache is None:
        cache = _build_stock_held_cache(world)
        world._fin_cache_stock_held = cache
    return cache


def stock_issuer_total_shares_held(world: "World", issuer_id: str) -> float:
    """외부 보유 주식 합계 — 전 POP 풀스캔 대신 캐시 O(1) 조회."""
    cache = world._fin_cache_stock_held
    if cache is None:
        cache = ensure_stock_held_cache(world)
    return float(cache.get(issuer_id, 0.0))


def stock_issuer_issued_shares(world: "World", issuer_id: str) -> float:
    issuer = stock_issuer_entity(world, issuer_id)
    return getattr(issuer, "stock_shares", COMPANY_STOCK_SHARES) if issuer else COMPANY_STOCK_SHARES


def stock_ownership_share(world: "World", issuer_id: str, held_shares: float) -> float:
    """보유 주식 / 발행 주식 — 시장 보유 비중."""
    issued = stock_issuer_issued_shares(world, issuer_id)
    if issued <= 0:
        return 0.0
    return clamp(held_shares / issued, 0.0, 1.0)


def stock_sell_step_size(buy_speed: float, ownership_share: float) -> float:
    """보유 비중이 높을수록 매도 step_size 축소 (Market Impact Mitigation)."""
    mult = max(
        STOCK_SELL_STEP_MIN_MULT,
        1.0 - ownership_share * (1.0 - STOCK_SELL_STEP_MIN_MULT),
    )
    return buy_speed * mult


def stock_max_weekly_order_shares(
    world: "World",
    issuer_id: str,
    *,
    issued_fraction: Optional[float] = None,
) -> float:
    """정책 주체 등 명시적 발행비율이 있을 때만 쓰는 주당 수량 상한."""
    frac = (
        float(issued_fraction)
        if issued_fraction is not None
        else float(STOCK_MAX_ORDER_ISSUED_FRACTION)
    )
    return stock_issuer_issued_shares(world, issuer_id) * max(0.0, frac)


def country_stock_market_open(world: "World", country_id: str) -> bool:
    """해당 국가가 있으면 주식시장은 항상 열려 있다."""
    return country_id in (world.countries or {})


def stock_market_sell_supply(world: "World", issuer_id: str) -> float:
    sm = world.stock_markets.get(issuer_id)
    if not sm:
        return 0.0
    return sum(o.quantity for o in sm.sell_orders)


def stock_issuer_available_buy_shares(world: "World", issuer_id: str) -> float:
    """유통 주식 + 당주 매도호가 — 이차 매수·양방향 LP 가능 물량."""
    return (
        stock_issuer_float_shares(world, issuer_id)
        + stock_market_sell_supply(world, issuer_id)
    )


def stock_clamp_order_shares(
    world: "World",
    issuer_id: str,
    shares: float,
    *,
    is_buy: bool = False,
    match_secondary: bool = True,
    issued_fraction: Optional[float] = None,
) -> float:
    """매수는 유통·매도호가 합산 한도(이차 매칭). 발행비율 상한은 명시할 때만."""
    if shares <= 1e-9:
        return 0.0
    capped = float(shares)
    if issued_fraction is not None:
        capped = min(
            capped,
            stock_max_weekly_order_shares(
                world, issuer_id, issued_fraction=issued_fraction),
        )
    if is_buy:
        avail = (
            stock_issuer_available_buy_shares(world, issuer_id)
            if match_secondary
            else stock_issuer_float_shares(world, issuer_id)
        )
        capped = min(capped, avail)
    return max(0.0, capped)


def stock_rebalance_order_flows(
    world: "World",
    issuer_id: str,
    held_shares: float,
    target_value: float,
    current_value: float,
    buy_speed: float = STOCK_REBALANCE_BUY_SPEED_HOME,
    attractiveness: float = 1.0,
    risk_aversion: float = 1.5,
    turnover_rate: float = 0.03,
    deadband: float = PORTFOLIO_REBALANCE_DEADBAND,
    max_flow_pct: float = PORTFOLIO_MAX_WEEKLY_FLOW_PCT,
    *,
    ownership: Optional[float] = None,
    max_order_value: Optional[float] = None,
) -> Tuple[float, float]:
    """주식 리밸런싱: 매수 속도 고정, 보유 비중에 따라 매도 속도 완화.

    주당 유량은 채권과 같이 보유(또는 신규면 목표) 대비 max_flow_pct(기본 12.5%).
    """
    if ownership is None:
        ownership = stock_ownership_share(world, issuer_id, held_shares)
    sell_step = stock_sell_step_size(buy_speed, ownership)
    buy_q, sell_q = portfolio_rebalance_flows(
        target_value,
        current_value,
        attractiveness=attractiveness,
        risk_aversion=risk_aversion,
        step_size=buy_speed,
        sell_step_size=sell_step,
        deadband=deadband,
        max_flow_pct=max_flow_pct,
        turnover_rate=turnover_rate,
        two_way_pct=0.0,
    )
    if max_order_value is None:
        max_order_value = portfolio_holding_directional_cap(
            current_value, target_value, max_flow_pct)
    return apply_stock_attraction_order_scale(
        buy_q, sell_q, attractiveness, max_order_value)


def stock_issuer_float_shares(world: "World", issuer_id: str) -> float:
    issuer = stock_issuer_entity(world, issuer_id)
    total_issued = getattr(issuer, "stock_shares", 0.0) if issuer else 0.0
    return max(0.0, total_issued - stock_issuer_total_shares_held(world, issuer_id))


def stock_clamp_portfolio_sell(holdings: Dict[str, float], issuer_id: str, qty: float) -> float:
    """보유 주식 수 이하로만 매도 가능."""
    if qty <= 1e-9:
        return 0.0
    return max(0.0, min(qty, holdings.get(issuer_id, 0.0)))


def stock_allocate_new_shares(
    world: "World",
    issuer_id: str,
    holdings: Dict[str, float],
    qty: float,
) -> float:
    """유통(미배분) 주식 한도 내에서만 보유에 반영."""
    if qty <= 1e-9:
        return 0.0
    allowed = stock_issuer_float_shares(world, issuer_id)
    actual = min(qty, allowed)
    if actual <= 1e-9:
        return 0.0
    holdings[issuer_id] = holdings.get(issuer_id, 0.0) + actual
    cache = getattr(world, "_fin_cache_stock_held", None)
    if cache is not None:
        cache[issuer_id] = float(cache.get(issuer_id, 0.0)) + actual
    return actual


def portfolio_apply_stock_buy(
    holdings: Dict[str, float],
    avg_costs: Dict[str, float],
    issuer_id: str,
    shares: float,
    price: float,
) -> None:
    """가중평균 매입단가 갱신 (holdings는 stock_apply_buy_fill 이후 호출)."""
    if shares <= 1e-9:
        return
    prev_shares = max(0.0, holdings.get(issuer_id, 0.0) - shares)
    prev_cost = avg_costs.get(issuer_id, price)
    new_shares = prev_shares + shares
    if new_shares > 1e-9:
        avg_costs[issuer_id] = (prev_shares * prev_cost + shares * price) / new_shares


def portfolio_apply_stock_sell(
    holdings: Dict[str, float],
    avg_costs: Dict[str, float],
    issuer_id: str,
    shares: float,
) -> None:
    prev = holdings.get(issuer_id, 0.0)
    new = max(0.0, prev - shares)
    holdings[issuer_id] = new
    if new <= 1e-9:
        avg_costs.pop(issuer_id, None)


def portfolio_apply_bond_buy(
    holdings: Dict[str, float],
    purchase_rates: Dict[str, float],
    market_key: str,
    amount: float,
    rate: float,
) -> None:
    if amount <= 1e-9:
        return
    prev = holdings.get(market_key, 0.0)
    prev_rate = purchase_rates.get(market_key, rate)
    new = prev + amount
    if new > 1e-9:
        purchase_rates[market_key] = (prev * prev_rate + amount * rate) / new
    holdings[market_key] = new


def portfolio_apply_bond_sell(
    holdings: Dict[str, float],
    purchase_rates: Dict[str, float],
    market_key: str,
    amount: float,
) -> None:
    prev = holdings.get(market_key, 0.0)
    new = max(0.0, prev - amount)
    holdings[market_key] = new
    if new <= 1e-9:
        purchase_rates.pop(market_key, None)


def stock_holding_return_pct(
    world: "World", issuer_id: str, avg_cost: float,
) -> Tuple[float, float]:
    """취득단가 대비 보유평가단가 수익률 (%), 표시용 취득단가."""
    try:
        cost = float(avg_cost or 0.0)
    except (TypeError, ValueError):
        cost = 0.0
    price = stock_holding_mark_price(world, issuer_id, cost)
    if cost <= 1e-9:
        # 평단 미기록: 전주가(상장) 또는 평가단가 자체를 기준으로 0% 처리
        prior = stock_issuer_market_mark_price(world, issuer_id)
        if prior <= 1e-9:
            prior = stock_issuer_prior_week_price(world, issuer_id)
        cost = prior if prior > 1e-9 else price
    if cost <= 1e-9 or price <= 1e-9:
        return 0.0, cost
    return (price / cost - 1.0) * 100.0, cost


def bond_holding_return_pct(purchase_rate: float, current_rate: float) -> float:
    """매입가 대비 시가 수익률 (%). 변동금리채는 둘 다 액면이라 가격 손익은 0."""
    purchase_price, current_price = bond_mtm_prices(1.0, purchase_rate, current_rate)
    if purchase_price <= 1e-9:
        return 0.0
    return (current_price / purchase_price - 1.0) * 100.0


def _ib_holding_return_display(pct: float) -> Tuple[str, str]:
    if abs(pct) < 0.05:
        return "0.0%", _STOCK_CHART_TEXT_DIM
    sign = "+" if pct > 0 else ""
    color = _GOODS_MARKET_BUY_TEXT if pct > 0 else _GOODS_MARKET_SELL_TEXT
    return f"{sign}{pct:.1f}%", color


def stock_apply_buy_fill(
    world: "World",
    issuer_id: str,
    holdings: Dict[str, float],
    qty: float,
) -> float:
    """매수 체결 반영. 매도 정산 후 남은 유통 한도 내에서 증가."""
    if qty <= 1e-9:
        return 0.0
    issuer = stock_issuer_entity(world, issuer_id)
    issued = getattr(issuer, "stock_shares", 0.0) if issuer else 0.0
    if issued <= 0:
        return 0.0
    max_add = stock_issuer_float_shares(world, issuer_id)
    # 부동소수 오차로 유통이 약간 모자랄 때 체결이 통째로 0이 되지 않게 함
    if max_add <= 1e-9:
        return 0.0
    actual = min(qty, max_add)
    if actual <= 1e-9:
        return 0.0
    holdings[issuer_id] = holdings.get(issuer_id, 0.0) + actual
    cache = getattr(world, "_fin_cache_stock_held", None)
    if cache is not None:
        cache[issuer_id] = float(cache.get(issuer_id, 0.0)) + actual
    return actual


def stock_held_cache_adjust(world: "World", issuer_id: str, delta: float) -> None:
    """보유 변동분을 유통주식 캐시에 반영 (캐시가 있을 때만)."""
    if abs(delta) <= 1e-15:
        return
    cache = getattr(world, "_fin_cache_stock_held", None)
    if cache is None:
        return
    cache[issuer_id] = max(0.0, float(cache.get(issuer_id, 0.0)) + delta)


def cap_stock_market_treasury_sells(market: StockMarketState, world: "World", issuer_id: str) -> None:
    """유통 주식 한도를 넘는 신규 발행 매도 주문을 체결 전에 축소."""
    float_avail = stock_issuer_float_shares(world, issuer_id)
    treasury_total = sum(
        o.quantity for o in market.sell_orders if getattr(o, "is_treasury_issue", False))
    if treasury_total <= float_avail + 1e-9:
        return
    scale = float_avail / treasury_total if treasury_total > 1e-9 else 0.0
    for order in market.sell_orders:
        if getattr(order, "is_treasury_issue", False):
            order.quantity *= scale


def stock_holder_holdings(world: "World", entity_id: str) -> Optional[Dict[str, float]]:
    """주식 보유 dict 반환. 보유 주체가 아니면 None."""
    cb = resolve_central_bank_entity(world, entity_id)
    if cb:
        return cb.stock_portfolio
    bank = world.banks.get(entity_id)
    if not bank and entity_id.startswith("bank_"):
        bank = world.banks.get(entity_id[5:])
    if bank:
        return None
    ib = world.investment_banks.get(entity_id)
    if not ib and entity_id.startswith("ib_"):
        ib = world.investment_banks.get(entity_id[3:])
    if ib:
        return ib.stock_holdings
    country = world.countries.get(entity_id)
    if country:
        return country.stock_holdings
    pop = world.find_pop_by_id(entity_id)
    if pop is not None:
        return pop.stock_holdings
    return None


def cap_stock_market_portfolio_sells(
    market: StockMarketState, world: "World", issuer_id: str,
) -> None:
    """보유량을 초과하는 포트폴리오 매도 주문을 체결 전에 축소.

    동일 매도자의 주문이 여러 건이면 보유량을 누적으로 차감해
    합산 매도가 보유를 넘지 않게 한다.
    """
    used: Dict[str, float] = defaultdict(float)
    for order in market.sell_orders:
        if getattr(order, "is_treasury_issue", False):
            continue
        holdings = stock_holder_holdings(world, order.seller_id)
        if holdings is None:
            order.quantity = 0.0
            continue
        held = float(holdings.get(issuer_id, 0.0) or 0.0)
        avail = max(0.0, held - used.get(order.seller_id, 0.0))
        order.quantity = max(0.0, min(float(order.quantity or 0.0), avail))
        if order.quantity > 1e-9:
            used[order.seller_id] = used.get(order.seller_id, 0.0) + order.quantity


def collect_stock_issuer_shareholders(world: "World", issuer_id: str) -> List[Dict[str, Any]]:
    """특정 종목 보유 주체와 보유 주식 수 (내림차순)."""
    rows: List[Dict[str, Any]] = []
    for cb in world.central_banks.values():
        shares = cb.stock_portfolio.get(issuer_id, 0.0)
        if shares <= 1e-6:
            continue
        rows.append({
            "entity_id": cb.id,
            "label": describe_market_entity(world, cb.id),
            "shares": shares,
            "category": "중앙은행",
        })
    for ib in world.investment_banks.values():
        shares = ib.stock_holdings.get(issuer_id, 0.0)
        if shares <= 1e-6:
            continue
        rows.append({
            "entity_id": ib.id,
            "label": describe_market_entity(world, ib.id),
            "shares": shares,
            "category": "금융투자은행",
        })
    for country in world.countries.values():
        shares = country.stock_holdings.get(issuer_id, 0.0)
        if shares <= 1e-6:
            continue
        rows.append({
            "entity_id": country.id,
            "label": describe_market_entity(world, country.id),
            "shares": shares,
            "category": "정부",
        })
    for st in world.states.values():
        for pop in st.pops:
            shares = pop.stock_holdings.get(issuer_id, 0.0)
            if shares <= 1e-6:
                continue
            rows.append({
                "entity_id": pop.id,
                "label": describe_market_entity(world, pop.id),
                "shares": shares,
                "category": "인구층",
            })
    for co in world.companies.values():
        shares = float((getattr(co, "stock_holdings", None) or {}).get(issuer_id, 0.0) or 0.0)
        if shares <= 1e-6:
            continue
        rows.append({
            "entity_id": co.id,
            "label": describe_market_entity(world, co.id),
            "shares": shares,
            "category": "기업",
        })
    rows.sort(key=lambda row: row["shares"], reverse=True)
    return rows


def format_stock_shareholder_lines(world: "World", issuer_id: str) -> List[str]:
    """특정 종목 주주 목록 표시 줄."""
    issuer = stock_issuer_entity(world, issuer_id)
    total_issued = getattr(issuer, "stock_shares", 0.0) if issuer else 0.0
    rows = collect_stock_issuer_shareholders(world, issuer_id)
    lines: List[str] = []
    for row in rows:
        pct = (row["shares"] / total_issued * 100.0) if total_issued > 0 else 0.0
        lines.append(
            f"· {row['label']} [{row['category']}] · "
            f"{row['shares']:,.2f}주 ({pct:.1f}%)"
        )
    float_shares = stock_issuer_float_shares(world, issuer_id)
    if float_shares > 1e-6:
        pct = (float_shares / total_issued * 100.0) if total_issued > 0 else 0.0
        lines.append(f"· 유통 미배분 [발행사] · {float_shares:,.2f}주 ({pct:.1f}%)")
    if not lines:
        if total_issued > 0:
            lines.append(f"· 전량 유통 미배분 · {total_issued:,.2f}주 (100.0%)")
        else:
            lines.append("보유 주체 없음")
    return lines


def format_stock_holdings_lines(world: "World", holdings: Dict[str, float]) -> List[str]:
    """보유 주식 종목별 표시 문자열 (평가액 내림차순). holdings 값은 주식 수."""
    rows = []
    for issuer_id, shares in holdings.items():
        if shares <= 1e-6:
            continue
        label, category, cid = describe_stock_issuer(world, issuer_id)
        value = stock_holding_market_value(world, issuer_id, shares)
        country = world.countries.get(cid)
        country_name = getattr(country, "name", cid or "무소속")
        rows.append((
            value,
            f"{label} · {category} · {country_name}: {value:,.0f}"
            + (f" ({shares:,.2f}주)" if shares > 0 else ""),
        ))
    rows.sort(reverse=True, key=lambda row: row[0])
    return [line for _, line in rows]


def serialize_stock_holdings_ui(
    world: "World",
    holdings: Dict[str, float],
    avg_costs: Optional[Dict[str, float]] = None,
    *,
    limit: int = 12,
) -> List[Dict[str, Any]]:
    """웹 UI용 주식 보유 행 — 평가액·평단·수익률."""
    costs = avg_costs or {}
    ranked = sorted(
        (
            (iid, shares)
            for iid, shares in holdings.items()
            if shares > 1e-6
        ),
        key=lambda item: -(
            stock_holding_market_value(
                world, item[0], item[1], float(costs.get(item[0], 0.0) or 0.0))
        ),
    )
    rows: List[Dict[str, Any]] = []
    for issuer_id, shares in ranked[:limit]:
        label, category, _cid = describe_stock_issuer(world, issuer_id)
        held_cost = float(costs.get(issuer_id, 0.0) or 0.0)
        price = stock_holding_mark_price(world, issuer_id, held_cost)
        value = shares * price if price > 0 else 0.0
        return_pct, avg_cost = stock_holding_return_pct(
            world, issuer_id, held_cost)
        rows.append({
            "issuer_id": issuer_id,
            "label": label,
            "category": category,
            "shares": round(shares, 2),
            "price": round(price, FINANCE_PRICE_DECIMALS),
            "value": round(value, 2),
            "avg_cost": round(avg_cost, FINANCE_PRICE_DECIMALS),
            "return_pct": round(return_pct, 2),
        })
    return rows


def serialize_bond_holdings_ui(
    world: "World",
    holdings: Dict[str, float],
    purchase_rates: Optional[Dict[str, float]] = None,
    *,
    limit: int = 12,
) -> List[Dict[str, Any]]:
    """웹 UI용 채권 보유 행 — 장부가·평단가·수익률."""
    rates = purchase_rates or {}
    ranked = sorted(
        ((mk, amt) for mk, amt in holdings.items() if amt > 1e-6),
        key=lambda item: -item[1],
    )
    rows: List[Dict[str, Any]] = []
    for market_key_id, amount in ranked[:limit]:
        label, category, cid = describe_bond_market(world, market_key_id)
        country = world.countries.get(cid)
        bm = world.bond_markets.get(market_key_id)
        eval_rate = float(getattr(bm, "current_interest_rate", 0.0) or 0.0) if bm else 0.0
        purchase_rate = float(rates.get(market_key_id, 0.0) or 0.0)
        if purchase_rate <= 1e-9:
            purchase_rate = bond_market_prior_week_rate(world, market_key_id) or eval_rate
        return_pct = bond_holding_return_pct(purchase_rate, eval_rate)
        rows.append({
            "market_key_id": market_key_id,
            "label": label,
            "category": category,
            "country_name": getattr(country, "name", cid or ""),
            "amount": round(amount, 2),
            "avg_cost": round(bond_discount_price(1.0, purchase_rate), 4),
            "return_pct": round(return_pct, 2),
        })
    return rows


def market_facility_supply_signal(market) -> float:
    """체결 전 수급의 5턴 WMA — 건설/폐쇄 판단용 (ideas.txt, World가 주당 1회 기록)"""
    samples = list(getattr(market, "order_imbalance_history", []))
    if not samples:
        return market_presettle_imbalance(market)
    if len(samples) < 5:
        return sum(samples) / len(samples)
    return wma(samples[-5:])


# 무역 가능 상품 생산 시설 건설/철거 시 수급 신호 가중치 (주 / 국가 / 월드)
TRADABLE_FACILITY_SIGNAL_WEIGHTS = (0.75, 0.15, 0.10)


def market_scope_trade_weight(market: "MarketState") -> float:
    """범위(국가·월드) 집계 시 거래 규모 가중치."""
    return (
        market_presettle_buy_volume(market)
        + market_presettle_sell_volume(market)
        + getattr(market, "base_volume", 1.0)
    )


def weighted_scope_supply_signal(
    product: str,
    markets: Dict[str, "MarketState"],
    states: Dict[str, "State"],
    country_id: Optional[str] = None,
) -> float:
    """동일 상품에 대해 주 목록(국가 또는 월드)의 수급 신호를 거래량 가중 평균."""
    weighted = 0.0
    total_w = 0.0
    for sid, st in states.items():
        if country_id is not None and st.country_id != country_id:
            continue
        m = markets.get(market_key(sid, product))
        if not m:
            continue
        w = market_scope_trade_weight(m)
        if w <= 0:
            continue
        weighted += market_facility_supply_signal(m) * w
        total_w += w
    return weighted / total_w if total_w > 1e-9 else 0.0


def company_has_facility_in_state(
    company: "Company",
    facility_name: str,
    state_id: str,
) -> bool:
    """해당 주에 지정 생산 시설이 가동·건설 중(또는 건설사 RE 스텁)인지."""
    builder_re_stub = (
        getattr(company, "type", None) == "건설 기업"
        and facility_re_kind(facility_name) in RE_BUILDABLE_KINDS
    )
    for fac in company.facilities:
        if fac.is_office or fac.name != facility_name or fac.state_id != state_id:
            continue
        if fac.level > 0 or fac.under_construction > 0:
            return True
        # 건설사 분양용 RE는 level=0 스텁으로 상시 유지 — 매주 신규 Facility 스폰 방지
        if builder_re_stub:
            return True
    return False


_COMPANY_COUNTRY_STATE_IDS_CACHE: Tuple[int, int, Dict[str, List[str]]] = (-1, -1, {})


def company_country_state_ids(
    company: "Company",
    states: Dict[str, "State"],
) -> List[str]:
    """기업 본사와 같은 국가에 속한 주 ID 목록."""
    home = states.get(company.home_state)
    if not home:
        return [company.home_state]
    global _COMPANY_COUNTRY_STATE_IDS_CACHE
    sid = id(states)
    n = len(states)
    cache_id, cache_n, by_c = _COMPANY_COUNTRY_STATE_IDS_CACHE
    if cache_id != sid or cache_n != n:
        rebuilt: Dict[str, List[str]] = defaultdict(list)
        for state_id, st in states.items():
            rebuilt[st.country_id].append(state_id)
        by_c = dict(rebuilt)
        _COMPANY_COUNTRY_STATE_IDS_CACHE = (sid, n, by_c)
    return by_c.get(home.country_id, [company.home_state])


def blended_tradable_facility_signal(
    product: str,
    state_id: str,
    country_id: str,
    markets: Dict[str, "MarketState"],
    states: Dict[str, "State"],
    weights: Tuple[float, float, float] = TRADABLE_FACILITY_SIGNAL_WEIGHTS,
    companies: Optional[Dict[str, "Company"]] = None,
    logistics_company_ids: Optional[set] = None,
) -> float:
    """무역 가능 상품 생산 시설용: 해당 주·국가·월드 수급 신호를 일부 반영한 합성 신호."""
    return tradable_facility_expansion_signal(
        product, state_id, country_id, markets, states, weights,
        companies, logistics_company_ids)


def tradable_facility_expansion_signal(
    product: str,
    state_id: str,
    country_id: str,
    markets: Dict[str, "MarketState"],
    states: Dict[str, "State"],
    weights: Tuple[float, float, float] = TRADABLE_FACILITY_SIGNAL_WEIGHTS,
    companies: Optional[Dict[str, "Company"]] = None,
    logistics_company_ids: Optional[set] = None,
    warmup: bool = False,
    country_sig: Optional[float] = None,
    world_sig: Optional[float] = None,
) -> float:
    """무역 가능 상품: 주 가정공급 신호 + 국가·월드 매도주문 신호 가중 합성."""
    local = markets.get(market_key(state_id, product))
    if local and companies and logistics_company_ids:
        local_sig = state_facility_supply_signal(
            local, companies, logistics_company_ids, warmup=warmup)
    else:
        local_sig = market_facility_supply_signal(local) if local else 0.0
    if country_sig is None:
        country_sig = weighted_scope_supply_signal(product, markets, states, country_id)
    if world_sig is None:
        world_sig = weighted_scope_supply_signal(product, markets, states, None)
    global_sig = (country_sig + world_sig) / 2.0
    ws, wc, ww = weights
    scope_weight = wc + ww
    scope_blended = (
        (wc * country_sig + ww * world_sig) / scope_weight
        if scope_weight > 1e-9 else global_sig
    )
    # 지역 신호와 글로벌(국가·월드) 신호를 가중 합성 (지역 75%)
    total_w = ws + scope_weight
    if total_w <= 1e-9:
        return (local_sig + global_sig) / 2.0
    return (ws * local_sig + scope_weight * scope_blended) / total_w


def is_tradable_production_product(product: Optional[str]) -> bool:
    return bool(product) and product in TRADABLE_PRODUCTS and product not in NON_TRADABLE


def sells_on_local_goods_market(product: Optional[str]) -> bool:
    """현지 상품 호가창에 매도할지 (무역 FOB 파이프 대신). 무역재는 FOB.

    선박은 예외: 실수요가 해운 물류의 출발국 매수뿐이라 FOB 배분 시점에는
    목적지 buy_orders가 비어 vanished_no_dest로 전량 소멸한다. 현지 호가에
    올려 같은 주 시장 체결에서 물류 매수와 맞춘다.
    """
    if not product:
        return False
    if product == "선박":
        return True
    return not is_tradable_production_product(product)


def is_service_facility_product(product: Optional[str]) -> bool:
    """주 단위 수요로 짓는 서비스 산출."""
    if not product:
        return False
    if product in NON_TRADABLE or product in LOCAL_STATE_FACILITY_PRODUCTS:
        return True
    return str(product).endswith("서비스")


def service_facility_local_signal(
    market: "MarketState",
    companies: Dict[str, "Company"],
    logistics_company_ids: set,
    warmup: bool = False,
) -> float:
    """서비스 생산 시설: 해당 주(STATE) 가정공급 수급 신호만 — 국가·월드 집계 미사용."""
    return state_facility_supply_signal(
        market, companies, logistics_company_ids, warmup=warmup)


def is_service_company(company_type: str) -> bool:
    return company_type in SERVICE_COMPANY_TYPES


def market_demand_exceeds_domestic_supply(
    market, logistics_company_ids: set,
) -> bool:
    """해당 주 시장에서 매수 주문량이 국내(무역 제외) 매도 주문량보다 많은지."""
    demand = sum(o.quantity for o in market.buy_orders)
    supply = market_domestic_sell_volume(market, logistics_company_ids)
    return demand > supply + 1e-6


def facility_spec_labor(facility_name: str) -> Optional[Tuple[str, float]]:
    spec = FACILITY_SPECS.get(facility_name, {})
    labor = spec.get("labor")
    if not labor:
        return None
    return labor[0], float(labor[1])


def state_labor_buy_orders(
    labor_markets: Dict[str, "MarketState"], state_id: str, ltype: str,
) -> float:
    mk = labor_markets.get(market_key(state_id, ltype))
    if not mk:
        return 0.0
    return sum(o.quantity for o in mk.buy_orders)


def state_labor_sell_orders(
    labor_markets: Dict[str, "MarketState"], state_id: str, ltype: str,
) -> float:
    mk = labor_markets.get(market_key(state_id, ltype))
    if not mk:
        return 0.0
    return sum(s.quantity for s in mk.sell_orders)


def state_under_construction_labor_demand(
    companies: Dict[str, "Company"], state_id: str,
) -> Dict[str, float]:
    global _OCC_UC_LABOR_WID, _OCC_UC_LABOR_BY_STATE
    wid = id(companies)
    if _OCC_CACHE_ENABLED and _OCC_UC_LABOR_WID == wid and _OCC_UC_LABOR_BY_STATE:
        return _OCC_UC_LABOR_BY_STATE.get(state_id, {})
    by_state: Dict[str, Dict[str, float]] = defaultdict(lambda: defaultdict(float))
    for co in companies.values():
        if isinstance(co, RetailCompany):
            continue
        for fac in co.facilities:
            labor = facility_spec_labor(fac.name)
            if labor and fac.under_construction > 0:
                ltype, qty = labor
                by_state[fac.state_id][ltype] += qty * fac.under_construction
        if co.office_under_construction > 0:
            office_labor = facility_spec_labor("사무 시설")
            if office_labor:
                ltype, qty = office_labor
                by_state[co.home_state][ltype] += qty * co.office_under_construction
    built = {sid: dict(dem) for sid, dem in by_state.items()}
    if _OCC_CACHE_ENABLED:
        _OCC_UC_LABOR_BY_STATE = built
        _OCC_UC_LABOR_WID = wid
    return built.get(state_id, {})


def state_construction_labor_spare(
    state_id: str,
    facility_name: str,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
    states: Optional[Dict[str, "State"]] = None,
    companies: Optional[Dict[str, "Company"]] = None,
) -> float:
    """착공 입지용 노동 잉여: 호가창/실업 − UC, 없으면 자격 인력−기존 시설 사용분."""
    spec = FACILITY_SPECS.get(facility_name, {})
    spare = export_state_labor_spare(state_id, spec, labor_markets, states)
    labor = facility_spec_labor(facility_name)
    if labor and companies:
        ltype, _qty = labor
        under = state_under_construction_labor_demand(
            companies, state_id).get(ltype, 0.0)
        spare -= float(under or 0.0)
        if spare <= 1e-9:
            pool = _state_skill_workforce(state_id, ltype, states)
            used = state_facility_labor_used(companies, state_id, ltype)
            spare = max(0.0, pool - used)
    elif labor and spare <= 1e-9:
        ltype, _qty = labor
        spare = _state_skill_workforce(state_id, ltype, states)
    return float(max(0.0, spare))


def facility_market_labor_spare(
    state_id: str,
    facility_name: str,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
) -> float:
    """착공 노동 게이트용 호가창 여분(매도 − 매수 + 학력 캐스케이드). 음수 가능."""
    labor = facility_spec_labor(facility_name)
    if not labor or labor_markets is None:
        return float("inf")
    ltype, _qty = labor
    return float(state_labor_construction_pool(state_id, str(ltype), labor_markets)[2])


def state_labor_pool(
    state_id: str,
    labor_type: str,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
) -> Tuple[float, float, float]:
    """(매도 공급, 매수 수요, 여분)."""
    supply = state_labor_sell_orders(labor_markets or {}, state_id, str(labor_type))
    demand = state_labor_buy_orders(labor_markets or {}, state_id, str(labor_type))
    return float(supply), float(demand), float(supply) - float(demand)


def _labor_cascade_already_applied(
    state_id: str,
    labor_type: str,
    labor_markets: Optional[Dict[str, "MarketState"]],
) -> bool:
    """해당 주 학력 사슬이 이미 체결·캐스케이드됐으면 True.

    착공은 체결 전, 진단 패널은 체결 후에 본다. 이미 내려온 매도를
    다시 더하면 미교육 여분이 이중 집계된다.
    """
    try:
        idx = LABOR_CASCADE_LAYERS.index(str(labor_type))
    except ValueError:
        return False
    if not labor_markets:
        return False
    for layer in LABOR_CASCADE_LAYERS[:idx + 1]:
        mk = labor_markets.get(market_key(state_id, layer))
        if not mk:
            continue
        if mk.sell_order_results or mk.buy_order_results:
            return True
        if any(
            getattr(o, "from_labor_cascade", False)
            for o in (getattr(mk, "sell_orders", None) or [])
        ):
            return True
    return False


def labor_cascade_inflow_qty(
    state_id: str,
    labor_type: str,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
) -> float:
    """상위 학력 미체결 매도 중 이 층으로 내려올 물량.

    resolve_state_labor_markets_cascaded 와 같이 고등→기본→미교육.
    이미 캐스케이드된 호가창이면 0 (live 매도에 포함됨).
    """
    try:
        idx = LABOR_CASCADE_LAYERS.index(str(labor_type))
    except ValueError:
        return 0.0
    if idx <= 0 or not labor_markets:
        return 0.0
    if _labor_cascade_already_applied(state_id, labor_type, labor_markets):
        return 0.0
    inflow = 0.0
    for higher in LABOR_CASCADE_LAYERS[:idx]:
        supply, demand, _ = state_labor_pool(state_id, higher, labor_markets)
        inflow = max(0.0, float(supply) + inflow - float(demand))
    return float(inflow)


def state_labor_construction_pool(
    state_id: str,
    labor_type: str,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
) -> Tuple[float, float, float]:
    """착공·진단용 노동 풀. 체결 전이면 학력 캐스케이드 유입을 미리 더한다.

    발전소처럼 미교육을 쓰는 시설이 체결 후 패널에서는 건설 가능,
    체결 전 엔진에서는 여분 0으로 착공을 건너뛰던 불일치를 없앤다.
    """
    supply, demand, spare = state_labor_pool(
        state_id, str(labor_type), labor_markets)
    extra = labor_cascade_inflow_qty(state_id, str(labor_type), labor_markets)
    if extra <= 1e-12:
        return supply, demand, spare
    supply = float(supply) + extra
    return supply, float(demand), supply - float(demand)


def occupation_labor_key(
    company_id: Any,
    state_id: Any,
    facility_name: Any,
) -> Tuple[str, str, str]:
    """착공 노동 배분 맵 키. 진단·엔진이 같은 문자열 3튜플을 쓴다."""
    return (str(company_id or ""), str(state_id or ""), str(facility_name or ""))


def lookup_occupation_labor_share(
    shares: Dict[Tuple[str, str, str], "OccupationLaborShare"],
    company_id: Any,
    state_id: Any,
    facility_name: Any,
) -> Optional["OccupationLaborShare"]:
    """정규화 키로 찾고, 구키(비문자열)도 한 번 더 본다."""
    key = occupation_labor_key(company_id, state_id, facility_name)
    hit = shares.get(key)
    if hit is not None:
        return hit
    legacy = (company_id, state_id, facility_name)
    if legacy != key:
        return shares.get(legacy)  # type: ignore[arg-type]
    return None


@dataclass
class OccupationLaborClaim:
    key: Tuple[str, str, str]
    state_id: str
    labor_type: str
    occupation: str
    want_stages: int
    per_stage: float


@dataclass
class OccupationLaborShare:
    allowed_stages: int
    labor_type: str
    supply: float
    demand: float
    spare: float
    occupation: str
    occupation_count: int
    occupation_budget: float
    occupation_want: float
    allocated_labor: float
    per_stage: float
    want_stages: int


def _share_labor_budget_as_stages(
    parts: List[OccupationLaborClaim],
    budget: float,
) -> Dict[Tuple[str, str, str], Tuple[int, float]]:
    """업종 노동 예산을 희망 노동량 비례로 단계에 배분 (잔여 최대 나머지)."""
    if not parts:
        return {}
    if budget <= 1e-12:
        return {c.key: (0, 0.0) for c in parts}
    wants = [(c, max(0, int(c.want_stages)) * max(0.0, float(c.per_stage))) for c in parts]
    total_want = sum(w for _, w in wants)
    if total_want <= 1e-12:
        return {c.key: (max(0, int(c.want_stages)), 0.0) for c in parts}
    if total_want <= budget + 1e-12:
        return {
            c.key: (max(0, int(c.want_stages)), max(0, int(c.want_stages)) * max(0.0, float(c.per_stage)))
            for c in parts
        }
    stages: Dict[Tuple[str, str, str], int] = {}
    alloc_labor: Dict[Tuple[str, str, str], float] = {}
    for c, w in wants:
        per = max(0.0, float(c.per_stage))
        labor = budget * (w / total_want)
        want = max(0, int(c.want_stages))
        if per <= 1e-12:
            st = want
            labor_used = 0.0
        else:
            st = min(want, int(labor // per))
            labor_used = st * per
        stages[c.key] = st
        alloc_labor[c.key] = labor_used
    remain = budget - sum(alloc_labor.values())
    while True:
        best: Optional[OccupationLaborClaim] = None
        best_score = -1e18
        for c, w in wants:
            want = max(0, int(c.want_stages))
            st = stages[c.key]
            if st >= want:
                continue
            per = max(0.0, float(c.per_stage))
            if per > remain + 1e-12:
                continue
            residual = budget * (w / total_want) - st * per
            if residual > best_score:
                best_score = residual
                best = c
        if best is None:
            break
        stages[best.key] += 1
        alloc_labor[best.key] += max(0.0, float(best.per_stage))
        remain -= max(0.0, float(best.per_stage))
    return {c.key: (stages[c.key], alloc_labor[c.key]) for c in parts}


def allocate_occupation_construction_labor(
    claims: Sequence[OccupationLaborClaim],
    pools: Dict[Tuple[str, str], Tuple[float, float, float]],
) -> Dict[Tuple[str, str, str], OccupationLaborShare]:
    """주·직능 잉여 노동을 착공 업종에 균분한 뒤, 미사용분은 희망 잔여 비례 재배분.

    시설은 자기 업종이 받은 노동량만큼만 착공한다. 선착순·0→1 후순위가 아니다.
    """
    out: Dict[Tuple[str, str, str], OccupationLaborShare] = {}
    merged: Dict[Tuple[str, str, str], OccupationLaborClaim] = {}
    for c in claims:
        want = max(0, int(c.want_stages or 0))
        if want <= 0:
            continue
        key = occupation_labor_key(
            c.key[0] if len(c.key) > 0 else "",
            c.key[1] if len(c.key) > 1 else c.state_id,
            c.key[2] if len(c.key) > 2 else "",
        )
        prev = merged.get(key)
        if prev is None or want > int(prev.want_stages or 0):
            merged[key] = OccupationLaborClaim(
                key=key,
                state_id=str(c.state_id or key[1]),
                labor_type=str(c.labor_type or ""),
                occupation=str(c.occupation or ""),
                want_stages=want,
                per_stage=max(0.0, float(c.per_stage or 0.0)),
            )
    by_pool: Dict[Tuple[str, str], List[OccupationLaborClaim]] = defaultdict(list)
    for c in merged.values():
        want = max(0, int(c.want_stages or 0))
        if not c.labor_type:
            out[c.key] = OccupationLaborShare(
                allowed_stages=want,
                labor_type="",
                supply=0.0,
                demand=0.0,
                spare=float("inf"),
                occupation=c.occupation,
                occupation_count=1,
                occupation_budget=0.0,
                occupation_want=0.0,
                allocated_labor=0.0,
                per_stage=0.0,
                want_stages=want,
            )
            continue
        by_pool[(c.state_id, str(c.labor_type))].append(c)

    def _empty_share(
        c: OccupationLaborClaim,
        supply: float,
        demand: float,
        spare: float,
        occ_n: int,
        occ_budget: float,
        occ_want: float,
    ) -> OccupationLaborShare:
        return OccupationLaborShare(
            allowed_stages=0,
            labor_type=c.labor_type,
            supply=supply,
            demand=demand,
            spare=spare,
            occupation=c.occupation,
            occupation_count=occ_n,
            occupation_budget=occ_budget,
            occupation_want=occ_want,
            allocated_labor=0.0,
            per_stage=c.per_stage,
            want_stages=c.want_stages,
        )

    for (state_id, ltype), group in by_pool.items():
        supply, demand, spare = pools.get((state_id, ltype), (0.0, 0.0, 0.0))
        spare = float(spare)
        occs = sorted({c.occupation for c in group})
        n = len(occs)
        occ_claims = {occ: [c for c in group if c.occupation == occ] for occ in occs}
        occ_want = {
            occ: sum(c.want_stages * c.per_stage for c in occ_claims[occ])
            for occ in occs
        }
        if spare <= 1e-12 or n <= 0:
            for c in group:
                out[c.key] = _empty_share(c, supply, demand, spare, n, 0.0, occ_want.get(c.occupation, 0.0))
            continue

        base = spare / float(n)
        occ_budget: Dict[str, float] = {}
        leftover = 0.0
        for occ in occs:
            min_per = min(
                (c.per_stage for c in occ_claims[occ] if c.per_stage > 1e-12),
                default=0.0,
            )
            want = occ_want[occ]
            if want <= base + 1e-12:
                occ_budget[occ] = want
                leftover += max(0.0, base - want)
            elif min_per > 1e-12 and base + 1e-12 < min_per:
                occ_budget[occ] = 0.0
                leftover += base
            else:
                occ_budget[occ] = base

        if leftover > 1e-12:
            unmet: Dict[str, float] = {}
            for occ in occs:
                left = occ_want[occ] - occ_budget[occ]
                if left > 1e-12:
                    unmet[occ] = left
            total_unmet = sum(unmet.values())
            if total_unmet > 1e-12:
                for occ, left in unmet.items():
                    occ_budget[occ] += leftover * (left / total_unmet)

        for occ in occs:
            parts = occ_claims[occ]
            distributed = _share_labor_budget_as_stages(parts, occ_budget[occ])
            for c in parts:
                st, labor = distributed.get(c.key, (0, 0.0))
                out[c.key] = OccupationLaborShare(
                    allowed_stages=int(st),
                    labor_type=ltype,
                    supply=float(supply),
                    demand=float(demand),
                    spare=spare,
                    occupation=occ,
                    occupation_count=n,
                    occupation_budget=float(occ_budget[occ]),
                    occupation_want=float(occ_want[occ]),
                    allocated_labor=float(labor),
                    per_stage=c.per_stage,
                    want_stages=c.want_stages,
                )
    return out


def facility_wanted_new_stages(
    company: "Company",
    fac: "Facility",
    *,
    markets: Dict[str, "MarketState"],
    companies: Dict[str, "Company"],
    states: Optional[Dict[str, "State"]],
    labor_markets: Optional[Dict[str, "MarketState"]],
    countries: Optional[Dict[str, "Country"]],
    logistics_company_ids: Optional[set] = None,
    warmup: bool = False,
) -> int:
    """장량 신호 − UC, 회차 soft cap. 노동 업종 배분 전."""
    spec = FACILITY_SPECS.get(getattr(fac, "name", ""), {})
    out = spec.get("output")
    if not out:
        return 0
    if skip_export_facility_during_warmup(warmup, spec, False):
        return 0
    site_eff = facility_site_resource_efficiency(
        fac.name, fac.state_id, spec=spec, states=states, company=company)
    if facility_natural_resource_product(fac.name, spec) and site_eff <= 1e-9:
        return 0
    mk = markets.get(market_key(fac.state_id, out))
    if mk is None:
        return 0
    buffer_gap, demand, supply = facility_construction_buffer_gap(
        company, str(out), mk, companies, logistics_company_ids or set(),
        markets=markets, states=states, warmup=warmup,
        company_tech_level=float(getattr(company, "tech_level", 1) or 1),
        labor_markets=labor_markets, facility_name=fac.name,
        countries=countries)
    base_output = float(spec.get("output_qty", 1) or 1) * max(site_eff, 1e-9)
    econ = evaluate_facility_construction_stages(
        company, spec, buffer_gap, base_output,
        markets=markets,
        labor_markets=labor_markets,
        state_id=fac.state_id,
        product=str(out),
        companies=companies,
        countries=countries,
        states=states,
        logistics_company_ids=logistics_company_ids,
        efficiency=company.production_efficiency_factor(),
        warmup=warmup,
        demand=demand,
        supply=supply,
        facility=fac,
    )
    expand = int(econ.expand_stages or 0)
    if expand <= 0:
        return 0
    remainder = max(0, expand - max(0, int(getattr(fac, "under_construction", 0) or 0)))
    if is_builder_re_facility(company, fac):
        room = max(0, RE_BUILDER_MAX_UC_PER_KIND - re_builder_uc_stages(
            company, fac.state_id, fac.name))
        remainder = min(remainder, room)
    else:
        remainder = min(remainder, FACILITY_EXPAND_MAX_STAGES)
    return int(remainder)


def collect_world_construction_labor_claims(
    world: "World",
) -> List[OccupationLaborClaim]:
    """진단·엔진과 같은 장량 신호로 주·업종 착공 희망 목록을 만든다."""
    companies = getattr(world, "companies", None) or {}
    markets = getattr(world, "markets", None) or {}
    states = getattr(world, "states", None) or {}
    labor_markets = getattr(world, "labor_markets", None)
    countries = getattr(world, "countries", None)
    logistics_ids = {
        co.id for co in companies.values() if getattr(co, "type", "") == "물류 기업"
    }
    claims: List[OccupationLaborClaim] = []
    seen: Set[Tuple[str, str, str]] = set()

    def _add(company: "Company", fac: "Facility", stages: int) -> None:
        stages = max(0, int(stages or 0))
        if stages <= 0:
            return
        key = occupation_labor_key(company.id, fac.state_id, fac.name)
        if key in seen:
            return
        seen.add(key)
        labor = facility_spec_labor(fac.name)
        ltype, per = ("", 0.0) if not labor else (str(labor[0]), float(labor[1]))
        claims.append(OccupationLaborClaim(
            key=key,
            state_id=str(fac.state_id),
            labor_type=ltype,
            occupation=str(getattr(company, "type", "") or ""),
            want_stages=stages,
            per_stage=per,
        ))

    for co in companies.values():
        if not company_can_operate(co):
            continue
        if co.__class__.__name__ == "RetailCompany":
            continue
        state_ids = company_country_state_ids(co, states)
        for fname in company_facility_names(getattr(co, "type", "")):
            spec = FACILITY_SPECS.get(fname, {})
            if not spec.get("output"):
                continue
            if (
                getattr(co, "type", None) == "건설 기업"
                and facility_re_kind(fname) in RE_BUILDABLE_KINDS
            ):
                continue
            for state_id in state_ids:
                if not state_allows_natural_resource_product(
                        str(spec.get("output", "") or ""),
                        state_id=state_id, states=states, company=co):
                    continue
                existing = next(
                    (
                        fac for fac in getattr(co, "facilities", [])
                        if (not getattr(fac, "is_office", False)
                            and fac.name == fname
                            and fac.state_id == state_id)
                    ),
                    None,
                )
                if existing is not None and (
                    int(getattr(existing, "level", 0) or 0) > 0
                    or int(getattr(existing, "under_construction", 0) or 0) > 0
                ):
                    continue
                placeholder = existing or Facility(fname, state_id, co.id, level=0)
                want = facility_wanted_new_stages(
                    co, placeholder,
                    markets=markets, companies=companies, states=states,
                    labor_markets=labor_markets, countries=countries,
                    logistics_company_ids=logistics_ids)
                _add(co, placeholder, want)

        for fac in getattr(co, "facilities", []):
            if getattr(fac, "is_office", False):
                continue
            if is_builder_re_facility(co, fac):
                continue
            if int(getattr(fac, "level", 0) or 0) <= 0 and int(
                    getattr(fac, "under_construction", 0) or 0) <= 0:
                continue
            want = facility_wanted_new_stages(
                co, fac,
                markets=markets, companies=companies, states=states,
                labor_markets=labor_markets, countries=countries,
                logistics_company_ids=logistics_ids)
            _add(co, fac, want)
    return claims


def world_occupation_labor_shares(
    world: "World",
) -> Dict[Tuple[str, str, str], OccupationLaborShare]:
    """현재 호가창 기준 업종 노동 배분. 진단 패널이 엔진과 같은 맵을 본다."""
    global _OCC_LABOR_SHARE_CACHE_WID, _OCC_LABOR_SHARE_CACHE_WEEK
    wid = id(world)
    week = int(getattr(world, "week", 0) or 0)
    if (
        _OCC_LABOR_SHARE_CACHE
        and _OCC_LABOR_SHARE_CACHE_WID == wid
        and _OCC_LABOR_SHARE_CACHE_WEEK == week
    ):
        return _OCC_LABOR_SHARE_CACHE
    claims = collect_world_construction_labor_claims(world)
    pools: Dict[Tuple[str, str], Tuple[float, float, float]] = {}
    labor_markets = getattr(world, "labor_markets", None)
    for c in claims:
        if not c.labor_type:
            continue
        pk = (c.state_id, c.labor_type)
        if pk not in pools:
            pools[pk] = state_labor_construction_pool(
                c.state_id, c.labor_type, labor_markets)
    shares = allocate_occupation_construction_labor(claims, pools)
    _OCC_LABOR_SHARE_CACHE.clear()
    _OCC_LABOR_SHARE_CACHE.update(shares)
    _OCC_LABOR_SHARE_CACHE_WID = wid
    _OCC_LABOR_SHARE_CACHE_WEEK = week
    return shares


def construction_labor_allowed_stages(
    *,
    company_id: Any,
    state_id: str,
    facility_name: str,
    want_stages: int,
    pending_shares: Dict[Tuple[str, str, str], OccupationLaborShare],
    world: Optional["World"] = None,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
) -> int:
    """진단 맵 → pending 맵 → 호가 여분 순으로 착공 단계 상한.

    맵 키 누락을 0으로 침묵 드롭하지 않는다. 여분이 단계당 노동 이상이면
    최소 1단계는 살린다.
    """
    want = max(0, int(want_stages or 0))
    if want <= 0:
        return 0
    labor = facility_spec_labor(facility_name)
    if not labor:
        return want
    share = None
    if world is not None:
        share = lookup_occupation_labor_share(
            world_occupation_labor_shares(world),
            company_id, state_id, facility_name)
    if share is None:
        share = lookup_occupation_labor_share(
            pending_shares, company_id, state_id, facility_name)
    ltype, per = str(labor[0]), float(labor[1] or 0.0)
    if share is not None:
        capped = int(getattr(share, "allowed_stages", 0) or 0)
        if capped > 0:
            return min(want, max(0, capped))
        if per <= 1e-12:
            return want
        spare = float(state_labor_construction_pool(
            str(state_id), ltype, labor_markets)[2])
        if spare + 1e-12 < per:
            return 0
        return min(want, 1)
    if per <= 1e-12:
        return want
    spare = float(state_labor_construction_pool(
        str(state_id), ltype, labor_markets)[2])
    if spare + 1e-12 < per:
        return 0
    return min(want, max(1, int(spare // per)))


def facility_stages_capped_by_labor_spare(
    facility_name: str,
    state_id: str,
    stages: int,
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
    states: Optional[Dict[str, "State"]] = None,
    companies: Optional[Dict[str, "Company"]] = None,
    extra_used: float = 0.0,
    min_stages: int = 0,
) -> int:
    """호가창 여분만으로 단계 상한 (업종 배분 전 참고값)."""
    del states, companies, min_stages, extra_used
    want = max(0, int(stages or 0))
    if want <= 0:
        return 0
    want = min(want, FACILITY_EXPAND_MAX_STAGES)
    labor = facility_spec_labor(facility_name)
    if not labor:
        return want
    _ltype, qty = labor
    per = float(qty or 0.0)
    if per <= 1e-12:
        return want
    spare = facility_market_labor_spare(state_id, facility_name, labor_markets)
    if spare + 1e-12 < per:
        return 0
    allowed = int(spare // per) if per > 1e-12 else want
    if allowed <= 0:
        allowed = 1
    return min(want, allowed)


def product_market_sell_supply_total(
    product: str,
    markets: Optional[Dict[str, "MarketState"]],
    states: Optional[Dict[str, "State"]],
    *,
    country_id: Optional[str] = None,
) -> float:
    """상품 매도 공급 합(전주 체결 매도량, 없으면 호가창 매도)."""
    if not markets or not states:
        return 0.0
    total = 0.0
    for st in states.values():
        if country_id and getattr(st, "country_id", "") != country_id:
            continue
        mk = markets.get(market_key(st.id, product))
        if mk is None:
            continue
        last = float(getattr(mk, "last_sell_volume", 0.0) or 0.0)
        if last > 1e-9:
            total += last
            continue
        try:
            live = sum(
                float(getattr(s, "quantity", 0.0) or 0.0)
                for s in (getattr(mk, "sell_orders", None) or [])
            )
        except Exception:
            live = 0.0
        total += live
    return float(total)


def construction_facility_pipeline_levels(
    companies: Optional[Dict[str, "Company"]],
    *,
    country_id: Optional[str] = None,
    states: Optional[Dict[str, "State"]] = None,
    company_id: Optional[str] = None,
) -> float:
    """건설 시설 가동+UC 단계 합 (국가·기업 필터 가능)."""
    if not companies:
        return 0.0
    total = 0.0
    for co in companies.values():
        if getattr(co, "type", None) != "건설 기업":
            continue
        if company_id and co.id != company_id:
            continue
        for fac in getattr(co, "facilities", []) or []:
            if getattr(fac, "is_office", False) or fac.name != "건설 시설":
                continue
            if country_id and states:
                st = states.get(fac.state_id)
                if st is None or getattr(st, "country_id", "") != country_id:
                    continue
            total += float(fac.active_levels()) + float(
                max(0, int(getattr(fac, "under_construction", 0) or 0)))
    return total


def construction_companies_in_country(
    companies: Optional[Dict[str, "Company"]],
    states: Optional[Dict[str, "State"]],
    country_id: Optional[str],
) -> List["Company"]:
    """본사 또는 건설 시설이 해당 국가에 있는 건설 기업."""
    if not companies or not country_id:
        return []
    out: List["Company"] = []
    seen: Set[str] = set()
    for co in companies.values():
        if getattr(co, "type", None) != "건설 기업":
            continue
        if co.id in seen:
            continue
        home = states.get(getattr(co, "home_state", "") or "") if states else None
        if home is not None and getattr(home, "country_id", "") == country_id:
            seen.add(co.id)
            out.append(co)
            continue
        if not states:
            continue
        for fac in getattr(co, "facilities", []) or []:
            if fac.name != "건설 시설":
                continue
            st = states.get(fac.state_id)
            if st is not None and getattr(st, "country_id", "") == country_id:
                seen.add(co.id)
                out.append(co)
                break
    return out


def construction_company_country_share(
    company: "Company",
    companies: Optional[Dict[str, "Company"]],
    states: Optional[Dict[str, "State"]],
    country_id: Optional[str],
) -> float:
    """국가 내 건설 기업 목표 점유율(매력도 정규화). 신규사도 몫을 받음."""
    peers = construction_companies_in_country(companies, states, country_id)
    if not peers:
        return 1.0
    peer_ids = {c.id for c in peers}
    if company.id not in peer_ids:
        peers = list(peers) + [company]
    weights = [company_product_attractiveness(co) for co in peers]
    tw = sum(weights)
    if tw <= 1e-15:
        return 1.0 / max(len(peers), 1)
    for co, w in zip(peers, weights):
        if co.id == company.id:
            return float(w) / tw
    return 0.0


def construction_facility_stages_capped_by_input_supply(
    stages: int,
    *,
    company: Optional["Company"] = None,
    state_id: str = "",
    markets: Optional[Dict[str, "MarketState"]] = None,
    states: Optional[Dict[str, "State"]] = None,
    companies: Optional[Dict[str, "Company"]] = None,
    extra_levels: float = 0.0,
) -> int:
    """건설 시설 신규 단계: 국가 투입재 공급×CONSTRUCTION_FACILITY_INPUT_SUPPLY_SHARE를
    건설 기업 총한도로 두고 점유율 배분.

    기업 한도 = 국가한도 × 해당 기업 점유율.
    기업 기존(가동+UC)과 이번 주 이미 배정분을 뺀 잔여만 착공.
    """
    want = max(0, int(stages or 0))
    if want <= 0:
        return 0
    want = min(want, FACILITY_EXPAND_MAX_STAGES)
    if company is None:
        return want
    spec = FACILITY_SPECS.get("건설 시설", {})
    inputs = spec.get("inputs") or {}
    if not inputs or not markets or not states:
        return want
    country_id = None
    if state_id and states:
        st = states.get(state_id)
        if st is not None:
            country_id = getattr(st, "country_id", None)
    if country_id is None and states:
        home = states.get(getattr(company, "home_state", "") or "")
        if home is not None:
            country_id = getattr(home, "country_id", None)
    share = construction_company_country_share(
        company, companies, states, country_id)
    if share <= 1e-15:
        return 0
    mine = construction_facility_pipeline_levels(
        companies, country_id=country_id, states=states, company_id=company.id)
    mine += float(extra_levels or 0.0)
    room = want
    for item, per in inputs.items():
        per_f = float(per or 0.0)
        if per_f <= 1e-12:
            continue
        supply = product_market_sell_supply_total(
            str(item), markets, states, country_id=country_id)
        country_cap = (
            CONSTRUCTION_FACILITY_INPUT_SUPPLY_SHARE * supply) / per_f
        company_cap = country_cap * share
        avail = max(0.0, company_cap - mine)
        room = min(room, int(math.floor(avail + 1e-9)))
        if room <= 0:
            return 0
    return max(0, int(room))


def tradable_company_expansion_plan(
    company: "Company",
    product: str,
    companies: Dict[str, "Company"],
    markets: Optional[Dict[str, "MarketState"]],
    states: Optional[Dict[str, "State"]],
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
    facility_name: str = "",
    countries: Optional[Dict[str, "Country"]] = None,
) -> Dict[str, Any]:
    """무역재 건설 계획: 정책 수요몫 × 장량버퍼를 본사국 노동 잉여로 주별 배분."""
    empty: Dict[str, Any] = {
        "allocs": {},
        "spares": {},
        "weights": {},
        "weight_sum": 0.0,
        "total_spare": 0.0,
        "stock_target": 0.0,
        "pipeline": 0.0,
        "company_gap": 0.0,
        "state_pipes": {},
        "quota": 0.0,
        "domestic_quota": 0.0,
        "foreign_quota": 0.0,
        "export_focus": 0.0,
        "domestic_focus": 1.0,
        "base_out": 1.0,
    }
    if not states or not markets:
        return empty
    fname = facility_name or company_facility_name_for_product(company, product)
    cache_key = (company.id, product)
    if _OCC_CACHE_ENABLED:
        hit = _TRADABLE_ALLOC_CACHE.get(cache_key)
        if hit is not None and isinstance(hit, dict) and "allocs" in hit:
            return hit

    breakdown = company_policy_demand_breakdown(
        company, product, companies, markets, states, countries=countries)
    stock_target = company_product_stock_target(
        company, product, companies, markets, states, countries=countries)
    pipeline = company_product_pipeline_capacity(
        company, product, include_closed=True, efficiency_cap=1.0)
    home_ids = company_country_state_ids(company, states)
    spec = FACILITY_SPECS.get(fname, {}) or facility_spec_for_product(product)
    base_out = float(spec.get("output_qty", 1) or 1)
    spares: Dict[str, float] = {}
    total_spare = 0.0
    for sid in home_ids:
        spare = max(0.0, state_construction_labor_spare(
            sid, fname, labor_markets, states, companies))
        spares[sid] = spare
        total_spare += spare
    weights = dict(spares)
    weight_sum = total_spare
    if weight_sum <= 1e-9 and home_ids:
        weights = {sid: 1.0 for sid in home_ids}
        weight_sum = float(len(home_ids))
    allocs: Dict[str, float] = {}
    state_pipes: Dict[str, float] = {}
    if stock_target > 1e-9 and weight_sum > 1e-9:
        for sid, w in weights.items():
            if w <= 1e-9:
                continue
            pipe = company_product_pipeline_capacity(
                company, product, state_id=sid,
                include_closed=True, efficiency_cap=1.0)
            state_pipes[sid] = pipe
            gap = stock_target * (w / weight_sum) - pipe
            if gap <= 1e-9:
                continue
            qty = gap
            if base_out > 1e-12:
                qty = min(gap, FACILITY_EXPAND_MAX_STAGES * base_out)
            if qty > 1e-9:
                allocs[sid] = qty
    plan = {
        "allocs": allocs,
        "spares": spares,
        "weights": weights,
        "weight_sum": weight_sum,
        "total_spare": total_spare,
        "stock_target": stock_target,
        "pipeline": pipeline,
        "company_gap": stock_target - pipeline,
        "state_pipes": state_pipes,
        "quota": float(breakdown.get("quota", 0.0) or 0.0),
        "domestic_quota": float(breakdown.get("domestic_quota", 0.0) or 0.0),
        "foreign_quota": float(breakdown.get("foreign_quota", 0.0) or 0.0),
        "export_focus": float(breakdown.get("export_focus", 0.0) or 0.0),
        "domestic_focus": float(breakdown.get("domestic_focus", 0.0) or 0.0),
        "base_out": base_out,
    }
    if _OCC_CACHE_ENABLED:
        _TRADABLE_ALLOC_CACHE[cache_key] = plan
    return plan


def tradable_state_allocated_expansion(
    company: "Company",
    product: str,
    state_id: str,
    companies: Dict[str, "Company"],
    markets: Optional[Dict[str, "MarketState"]],
    states: Optional[Dict[str, "State"]],
    labor_markets: Optional[Dict[str, "MarketState"]] = None,
    facility_name: str = "",
    countries: Optional[Dict[str, "Country"]] = None,
) -> float:
    """무역재: 회사 총 장량을 본사국 노동 잉여 비중으로 주별 목표화한 뒤, 그 주 파이프를 뺀 갭.

    전사 파이프를 먼저 빼면 본사 과잉 건설 이후 다른 주 갭이 0이 된다.
    """
    if not state_id:
        return 0.0
    plan = tradable_company_expansion_plan(
        company, product, companies, markets, states,
        labor_markets=labor_markets, facility_name=facility_name,
        countries=countries)
    return float((plan.get("allocs") or {}).get(state_id, 0.0) or 0.0)


def facility_expansion_signal(
    product: str,
    market,
    state_id: str,
    tradable_signals: Optional[Dict[Tuple[str, str], float]],
    companies: Optional[Dict[str, "Company"]] = None,
    logistics_company_ids: Optional[set] = None,
    warmup: bool = False,
) -> float:
    if is_service_facility_product(product):
        if companies and logistics_company_ids:
            return service_facility_local_signal(
                market, companies, logistics_company_ids, warmup=warmup)
        return market_facility_supply_signal(market)
    if is_tradable_production_product(product) and tradable_signals is not None:
        return tradable_signals.get((state_id, product), market_facility_supply_signal(market))
    if companies and logistics_company_ids:
        return state_facility_supply_signal(
            market, companies, logistics_company_ids, warmup=warmup)
    return market_facility_supply_signal(market)


def resolve_stock_market(
    market: StockMarketState,
    company_info: Dict[str, float],
    freeze_price: bool = False,
) -> None:
    total_demand = sum(o.quantity for o in market.buy_orders)
    total_supply = sum(s.quantity for s in market.sell_orders)
    last_close = float(getattr(market, "current_price", 0.0) or 0.0)
    if last_close <= 1e-12:
        last_close = stock_market_reference_price(market)

    issued = stock_market_issued_shares(market, company_info)
    if issued > 1e-12:
        market.issued_shares = issued

    fv = float((company_info or {}).get("fair_value", 0.0) or 0.0)
    if fv <= 1e-12:
        fv = float(getattr(market, "fair_value", 0.0) or 0.0)
    if fv > 1e-12:
        market.fair_value = fv

    price_change = stock_price_change_from_orders(
        market, company_info,
        apply_noise=not freeze_price,
        freeze_price=freeze_price,
    )
    hist = getattr(market, "price_change_history", None)
    if hist is None:
        market.price_change_history = []
        hist = market.price_change_history
    hist.append(price_change)

    if not freeze_price:
        market.current_price = clamp_stock_price(last_close * (1.0 + price_change))
        market.last_current_price = market.current_price
    market.last_supply_demand_ratio = market_supply_demand_ratio(
        total_demand, total_supply, float(getattr(market, "base_volume", 0.0) or 0.0))

    transaction_qty = min(total_demand, total_supply)
    if transaction_qty <= 0:
        market.buy_order_results = []
        market.sell_order_results = []
        market.last_buy_volume = total_demand
        market.last_sell_volume = total_supply
        record_market_weekly_price(market)
        return
    market.sell_order_results, market.buy_order_results, _ = _match_orders(
        market.buy_orders, market.sell_orders, transaction_qty)
    market.last_buy_volume = total_demand
    market.last_sell_volume = total_supply
    record_market_weekly_price(market)


def bond_market_is_public_debt(issuer_id: str) -> bool:
    """국채·지방채 — 발행 기업 부채비율 신용 압력 대상 아님."""
    return issuer_id.startswith("gov_") or issuer_id.startswith("local_")


def bond_market_credit_pressure(market: BondMarketState) -> float:
    """발행사(회사채) 신용 위험 — 1·2차 매도 주문의 부채비율 반영."""
    if bond_market_is_public_debt(market.issuer_id):
        return 0.0
    credit_orders = [
        s for s in market.sell_orders
        if s.bond_balance > 0 or s.net_income > 0
    ]
    if not credit_orders:
        return 0.0
    total_qty = sum(s.quantity for s in credit_orders)
    if total_qty <= 0:
        return 0.0
    weighted_dr = sum(
        (s.bond_balance / max(s.net_income, 1.0)) * s.quantity
        for s in credit_orders
    ) / total_qty
    dr_score = max(0.0, 1.0 - weighted_dr / 4.0)
    return 1.0 - dr_score


def resolve_bond_market(market: BondMarketState, macro_info: Dict[str, float]) -> None:
    total_demand = sum(o.quantity for o in market.buy_orders)
    total_supply = sum(s.quantity for s in market.sell_orders)

    secondary_supply = 0.0
    treasury_supply = 0.0
    for s in market.sell_orders:
        qty = float(getattr(s, "quantity", 0.0) or 0.0)
        if qty <= 1e-12:
            continue
        if getattr(s, "is_treasury_issue", False):
            treasury_supply += qty
        else:
            secondary_supply += qty
    flow_supply = secondary_supply + float(
        BOND_TREASURY_SUPPLY_FLOW_WEIGHT) * treasury_supply

    # FRN: 쿠폰 = 기준금리 + 스프레드. 수급·신용(공정)은 스프레드를 %p로 가산.
    base = float((macro_info or {}).get("base_rate", 3.5) or 3.5)
    fair = float((macro_info or {}).get("fair_rate", 0.0) or 0.0)
    if fair <= 1e-12:
        fair = base
    spread = bond_market_current_spread(market, base)
    delta = bond_spread_delta_from_book(
        market, base_rate=base, fair_rate=fair)
    next_spread = clamp(
        spread + delta, BOND_SPREAD_FLOOR, BOND_SPREAD_CEIL)
    market.current_spread = next_spread
    market.rate_change_history.append(delta)
    market.current_interest_rate = clamp_bond_rate(base + next_spread)
    market.last_current_interest_rate = market.current_interest_rate
    # UI·통계용 수급비 — 미소화 발행 일부 포함 (가격식과 동일 가중)
    market.last_supply_demand_ratio = market_supply_demand_ratio(
        total_demand, flow_supply, market.base_volume, supply_weighted=True)

    transaction_qty = min(total_demand, total_supply)
    if transaction_qty <= 0:
        market.buy_order_results = []
        market.sell_order_results = []
        record_bond_weekly_rate(market)
        return
    market.sell_order_results, market.buy_order_results, _ = _match_orders(
        market.buy_orders, market.sell_orders, transaction_qty)
    record_bond_weekly_rate(market)


# ---------------------------------------------------------------------------
# 공사 게이트 조달 (분할 회사채)
# ---------------------------------------------------------------------------

def _positive_history_wma(values: Optional[Iterable[Any]], weeks: int = 13) -> float:
    samples = [float(v) for v in (values or []) if float(v or 0.0) > 0]
    if not samples:
        return 0.0
    tail = samples[-max(1, int(weeks)):]
    return float(wma(tail)) if len(tail) > 1 else float(tail[-1])


def construction_material_index(
    state_id: str,
    markets: Optional[Dict[str, "MarketState"]],
) -> float:
    """건설 시설 BOM 가중 건재 지수."""
    markets = markets or {}
    total = 0.0
    weight = 0.0
    for item, w in CONSTRUCTION_MATERIAL_WEIGHTS.items():
        ww = float(w or 0.0)
        if ww <= 1e-12:
            continue
        mk = markets.get(market_key(state_id, item)) if state_id else None
        if mk is not None:
            price = float(market_goods_labor_price(mk) or 0.0)
        else:
            price = float(PRODUCT_BASE_PRICES.get(item, 10.0) or 10.0)
        if price <= 1e-12:
            price = float(PRODUCT_BASE_PRICES.get(item, 10.0) or 10.0)
        total += price * ww
        weight += ww
    return total / max(weight, 1e-9)


def construction_material_index_base() -> float:
    total = 0.0
    weight = 0.0
    for item, w in CONSTRUCTION_MATERIAL_WEIGHTS.items():
        ww = float(w or 0.0)
        total += float(PRODUCT_BASE_PRICES.get(item, 10.0) or 10.0) * ww
        weight += ww
    return total / max(weight, 1e-9)


def construction_firm_material_scale(
    state_id: str,
    markets: Optional[Dict[str, "MarketState"]],
) -> float:
    """건재 원가/CS 단가 압박이 커지면 건설 서비스 공급을 줄인다."""
    markets = markets or {}
    cs_mk = markets.get(market_key(state_id, "건설 서비스")) if state_id else None
    cs_now = (
        float(market_goods_labor_price(cs_mk) or 0.0)
        if cs_mk is not None else 0.0)
    if cs_now <= 1e-12:
        cs_now = product_base_price("건설 서비스")
    cs_base = product_base_price("건설 서비스")
    mat_now = construction_material_index(state_id, markets)
    mat_base = construction_material_index_base()
    base_ratio = mat_base / max(cs_base, 1e-9)
    now_ratio = mat_now / max(cs_now, 1e-9)
    squeeze = now_ratio / max(base_ratio, 1e-9)
    if squeeze <= CONSTRUCTION_FIRM_MATERIAL_SQUEEZE_START:
        return 1.0
    span = max(
        CONSTRUCTION_FIRM_MATERIAL_SQUEEZE_FULL - CONSTRUCTION_FIRM_MATERIAL_SQUEEZE_START,
        1e-9)
    t = clamp((squeeze - CONSTRUCTION_FIRM_MATERIAL_SQUEEZE_START) / span, 0.0, 1.0)
    return float(1.0 - t * (1.0 - CONSTRUCTION_FIRM_CS_SCALE_MIN))


def construction_country_base_rate(
    world: Optional["World"],
    state_id: str,
) -> float:
    if world is None or not state_id:
        return 3.5
    st = (getattr(world, "states", None) or {}).get(state_id)
    cid = getattr(st, "country_id", "") if st is not None else ""
    country = (getattr(world, "countries", None) or {}).get(cid) if cid else None
    return country_base_rate(country) if country else 3.5


def construction_corp_bond_rate(
    world: Optional["World"],
    company: Optional[Any],
) -> float:
    if world is None or company is None:
        return 0.0
    cid = str(getattr(company, "id", "") or "")
    if not cid:
        return 0.0
    return float(bond_market_yield_pct(world, cid) or 0.0)


def capture_construction_market_snapshot(
    company: Any,
    state_id: str,
    markets: Optional[Dict[str, "MarketState"]],
    world: Optional["World"],
) -> Dict[str, float]:
    markets = markets or {}
    cs_mk = markets.get(market_key(state_id, "건설 서비스")) if state_id else None
    cs_price = (
        float(market_goods_labor_price(cs_mk) or 0.0)
        if cs_mk is not None else 0.0)
    if cs_price <= 1e-12:
        cs_price = product_base_price("건설 서비스")
    return {
        "base_rate": construction_country_base_rate(world, state_id),
        "corp_rate": construction_corp_bond_rate(world, company),
        "cs_price": cs_price,
        "material_index": construction_material_index(state_id, markets),
    }


def construction_market_baseline_snapshot(
    company: Any,
    state_id: str,
    markets: Optional[Dict[str, "MarketState"]],
    world: Optional["World"],
    current: Optional[Dict[str, float]] = None,
) -> Dict[str, float]:
    """첫 게이트용: 최근 13주 시세. 이력 없으면 현재가."""
    markets = markets or {}
    cur = dict(current or capture_construction_market_snapshot(
        company, state_id, markets, world))
    cs_mk = markets.get(market_key(state_id, "건설 서비스")) if state_id else None
    cs_ma = _positive_history_wma(
        getattr(cs_mk, "weekly_price_history", None) if cs_mk is not None else None,
        FINANCIAL_MARKET_WMA_WEEKS)
    if cs_ma > 1e-12:
        cur["cs_price"] = cs_ma
    mat_prices: List[float] = []
    mat_w: List[float] = []
    for item, w in CONSTRUCTION_MATERIAL_WEIGHTS.items():
        mk = markets.get(market_key(state_id, item)) if state_id else None
        ma = _positive_history_wma(
            getattr(mk, "weekly_price_history", None) if mk is not None else None,
            FINANCIAL_MARKET_WMA_WEEKS)
        if ma <= 1e-12 and mk is not None:
            ma = float(market_goods_labor_price(mk) or 0.0)
        if ma <= 1e-12:
            ma = float(PRODUCT_BASE_PRICES.get(item, 10.0) or 10.0)
        mat_prices.append(ma * float(w))
        mat_w.append(float(w))
    if mat_w:
        cur["material_index"] = sum(mat_prices) / max(sum(mat_w), 1e-9)
    st = (getattr(world, "states", None) or {}).get(state_id) if world else None
    cid = getattr(st, "country_id", "") if st is not None else ""
    country = (getattr(world, "countries", None) or {}).get(cid) if cid and world else None
    br_ma = _positive_history_wma(
        getattr(country, "weekly_base_rate_history", None) if country is not None else None,
        FINANCIAL_MARKET_WMA_WEEKS)
    if br_ma > 1e-12:
        cur["base_rate"] = br_ma
    issuer = str(getattr(company, "id", "") or "")
    bm = (getattr(world, "bond_markets", None) or {}).get(issuer) if world and issuer else None
    corp_ma = _positive_history_wma(
        getattr(bm, "weekly_rate_history", None) if bm is not None else None,
        FINANCIAL_MARKET_WMA_WEEKS)
    if corp_ma > 1e-12:
        cur["corp_rate"] = corp_ma
    return cur


def apply_construction_snapshot_to_target(target: Any, snap: Dict[str, float], prefix: str = "") -> None:
    setattr(target, f"{prefix}construction_start_base_rate", float(snap.get("base_rate", 0.0) or 0.0))
    setattr(target, f"{prefix}construction_start_corp_rate", float(snap.get("corp_rate", 0.0) or 0.0))
    setattr(target, f"{prefix}construction_start_cs_price", float(snap.get("cs_price", 0.0) or 0.0))
    setattr(
        target, f"{prefix}construction_start_material_index",
        float(snap.get("material_index", 0.0) or 0.0))


def construction_snapshot_from_target(target: Any, prefix: str = "") -> Dict[str, float]:
    return {
        "base_rate": float(getattr(target, f"{prefix}construction_start_base_rate", 0.0) or 0.0),
        "corp_rate": float(getattr(target, f"{prefix}construction_start_corp_rate", 0.0) or 0.0),
        "cs_price": float(getattr(target, f"{prefix}construction_start_cs_price", 0.0) or 0.0),
        "material_index": float(
            getattr(target, f"{prefix}construction_start_material_index", 0.0) or 0.0),
    }


def reset_facility_construction_funding(fac: Any) -> None:
    fac.construction_initial_stages = 0
    fac.construction_work_total = 0.0
    fac.construction_funded_until = 0.0
    fac.construction_bond_issued = 0.0
    fac.construction_funding_tier = ""
    fac.construction_start_base_rate = 0.0
    fac.construction_start_corp_rate = 0.0
    fac.construction_start_cs_price = 0.0
    fac.construction_start_material_index = 0.0
    fac.construction_pace_scale = 1.0
    fac.construction_last_gate_cost = 0.0


def reset_office_construction_funding(company: Any) -> None:
    company.office_construction_initial_stages = 0
    company.office_construction_work_total = 0.0
    company.office_construction_funded_until = 0.0
    company.office_construction_bond_issued = 0.0
    company.office_construction_funding_tier = ""
    company.office_construction_start_base_rate = 0.0
    company.office_construction_start_corp_rate = 0.0
    company.office_construction_start_cs_price = 0.0
    company.office_construction_start_material_index = 0.0
    company.office_construction_pace_scale = 1.0
    company.office_construction_last_gate_cost = 0.0
    company.office_pending_bond_issue = 0.0


def construction_project_work(
    under_construction: int,
    progress: float,
    target: float,
    initial_stages: int,
    work_total: float,
) -> Tuple[float, float, float]:
    uc = max(0, int(under_construction or 0))
    tgt = float(target or 0.0)
    initial = max(uc, int(initial_stages or 0))
    total = float(work_total or 0.0)
    if total <= 1e-12:
        total = float(initial) * tgt
    done = max(0.0, float(initial - uc) * tgt + float(progress or 0.0))
    if total > 1e-12:
        done = min(done, total)
    remaining = max(0.0, total - done)
    return done, remaining, total


def facility_construction_work(fac: Any) -> Tuple[float, float, float]:
    spec = FACILITY_SPECS.get(getattr(fac, "name", ""), {})
    target = float(
        getattr(fac, "construction_target", 0.0)
        or spec.get("construction", 0)
        or 0.0)
    return construction_project_work(
        int(getattr(fac, "under_construction", 0) or 0),
        float(getattr(fac, "construction_progress", 0.0) or 0.0),
        target,
        int(getattr(fac, "construction_initial_stages", 0) or 0),
        float(getattr(fac, "construction_work_total", 0.0) or 0.0),
    )


def office_construction_work(company: Any) -> Tuple[float, float, float]:
    target = float(OFFICE_SPEC.get("construction", 0) or 0.0)
    return construction_project_work(
        int(getattr(company, "office_under_construction", 0) or 0),
        float(getattr(company, "office_construction_progress", 0.0) or 0.0),
        target,
        int(getattr(company, "office_construction_initial_stages", 0) or 0),
        float(getattr(company, "office_construction_work_total", 0.0) or 0.0),
    )


def facility_construction_unit_cost(
    spec: Optional[Dict],
    state_id: str,
    markets: Optional[Dict[str, "MarketState"]],
    world: Optional["World"] = None,
    bond_financed: bool = False,
) -> float:
    """공사량 1포인트당 현재 비용 (CS가 × 배율 × 금리 가산)."""
    spec_dict = spec if spec is not None else {}
    markets = markets or {}
    cs_mk = markets.get(market_key(state_id, "건설 서비스")) if state_id else None
    cs_price = (
        float(market_goods_labor_price(cs_mk) or 0.0)
        if cs_mk is not None else 0.0)
    if cs_price <= 1e-12:
        cs_price = product_base_price("건설 서비스")
    cost = cs_price * facility_construction_cost_multiplier(spec_dict)
    if bond_financed:
        cost *= 1.0 + construction_country_base_rate(world, state_id) / 100.0
    return float(cost)


def construction_gate_due(done: float, funded_until: float, remaining: float) -> bool:
    if remaining <= 1e-9:
        return False
    runway = float(funded_until or 0.0) - float(done or 0.0)
    if runway <= 1e-9:
        return True
    lead = max(
        construction_weekly_cs_base_rate(remaining) * 2.0,
        remaining * CONSTRUCTION_BOND_PREISSUE_LEAD_FRAC)
    return runway <= lead


def _construction_tier_from_rate_delta(delta_pp: float) -> int:
    if delta_pp <= -0.10:
        return 0
    if delta_pp <= 0.25:
        return 1
    if delta_pp <= 0.50:
        return 2
    if delta_pp <= 1.00:
        return 3
    return 4


def _construction_tier_from_price_delta(delta_ratio: float) -> int:
    if delta_ratio <= -0.03:
        return 0
    if delta_ratio <= 0.08:
        return 1
    if delta_ratio <= 0.15:
        return 2
    if delta_ratio <= 0.25:
        return 3
    return 4


def construction_funding_tier(
    company: Any,
    remaining_work: float,
    remaining_cost: float,
    uc_stages: int,
    current: Dict[str, float],
    baseline: Dict[str, float],
    weekly_cs_cost: float,
) -> Tuple[float, float, str]:
    """조달 단계 → (slice_frac, pace_scale, label).

    정상 티어의 발행 비중은 국가·직종 프리셋(construction_bond_issue_ratios).
    금리·건재·건설서비스 가격이 오르면 티어가 나빠져 더 적게 발행한다.
    """
    n_tiers = len(CONSTRUCTION_FUNDING_TIER_SPECS)
    base_rate_now = float(current.get("base_rate", 0.0) or 0.0)
    base_rate_ref = float(baseline.get("base_rate", 0.0) or 0.0) or base_rate_now
    corp_now = float(current.get("corp_rate", 0.0) or 0.0)
    corp_ref = float(baseline.get("corp_rate", 0.0) or 0.0) or corp_now
    rate_delta = max(base_rate_now - base_rate_ref, corp_now - corp_ref)
    cs_now = float(current.get("cs_price", 0.0) or 0.0)
    cs_ref = float(baseline.get("cs_price", 0.0) or 0.0) or cs_now
    mat_now = float(current.get("material_index", 0.0) or 0.0)
    mat_ref = float(baseline.get("material_index", 0.0) or 0.0) or mat_now
    price_delta = 0.0
    if cs_ref > 1e-12:
        price_delta = max(price_delta, (cs_now - cs_ref) / cs_ref)
    if mat_ref > 1e-12:
        price_delta = max(price_delta, (mat_now - mat_ref) / mat_ref)
    tier = max(
        _construction_tier_from_rate_delta(rate_delta),
        _construction_tier_from_price_delta(price_delta),
    )
    stage_hint = remaining_work / max(1, int(uc_stages or 1))
    weekly_rate = construction_weekly_cs_qty(
        max(1, int(uc_stages or 1)), 1.0, stage_hint)
    remaining_weeks = remaining_work / max(weekly_rate, 1e-9)
    if remaining_weeks > CONSTRUCTION_FUNDING_LARGE_LEAD_WEEKS or int(uc_stages or 0) >= 3:
        tier = min(n_tiers - 1, tier + 1)
    elif int(uc_stages or 0) <= 1 and remaining_weeks <= CONSTRUCTION_FUNDING_LARGE_LEAD_WEEKS * 0.5:
        tier = max(0, tier - 1)
    cash = float(getattr(company, "cash", 0.0) or 0.0)
    preset_slice = company_construction_bond_issue_ratio(company)
    gate_ref = remaining_cost * preset_slice
    if cash + 1e-9 >= gate_ref * 1.5 and gate_ref > 1e-9:
        tier = max(0, tier - 1)
    if weekly_cs_cost > 1e-9 and cash < weekly_cs_cost * CONSTRUCTION_CASH_RUNWAY_WEEKS:
        tier = min(n_tiers - 1, tier + 1)
    label, slice_frac, pace = CONSTRUCTION_FUNDING_TIER_SPECS[tier]
    base_slice = float(CONSTRUCTION_FUNDING_TIER_SPECS[1][1])
    if preset_slice > 1e-12 and base_slice > 1e-12:
        slice_frac = float(slice_frac) * (preset_slice / base_slice)
    slice_frac = clamp(
        float(slice_frac),
        CONSTRUCTION_BOND_ISSUE_RATIO_MIN,
        CONSTRUCTION_BOND_ISSUE_RATIO_MAX,
    )
    if remaining_weeks <= CONSTRUCTION_FUNDING_SMALL_REMAINING_WEEKS:
        slice_frac = 1.0
    return float(slice_frac), float(pace), str(label)


def company_construction_funding_unblocked(company: Any, weekly_cs_cost: float) -> bool:
    if company_is_nationalized(company):
        return True
    sold_ratio = float(getattr(company, "bond_sold_ratio", 1.0) or 1.0)
    if sold_ratio + 1e-12 >= CONSTRUCTION_BOND_SOLD_START_RATIO:
        return True
    unsold = max(
        0.0,
        float(getattr(company, "current_bond_issue", 0.0) or 0.0)
        - float(getattr(company, "bond_sold_for_construction", 0.0) or 0.0))
    unsold += float(getattr(company, "pending_bond_sell", 0.0) or 0.0)
    if unsold <= 1e-6:
        return True
    weekly = max(0.0, float(weekly_cs_cost or 0.0))
    if weekly <= 1e-9:
        return True
    cash = float(getattr(company, "cash", 0.0) or 0.0)
    return cash + 1e-9 >= weekly * CONSTRUCTION_CASH_RUNWAY_WEEKS


def construction_weekly_cs_base_rate(construction_target: float = 0.0) -> float:
    """단계 공사량 대비 주당 CS 소진. 긴 공사는 목표 리드타임에 맞춰 가속."""
    base = float(CONSTRUCTION_MAX_PER_WEEK)
    target = max(0.0, float(construction_target or 0.0))
    lead = max(1.0, float(CONSTRUCTION_TARGET_LEAD_WEEKS))
    if target > 1e-9:
        base = max(base, target / lead)
    return base


def construction_weekly_cs_qty(
    under_construction: int,
    pace_scale: float,
    construction_target: float = 0.0,
) -> float:
    uc = max(0, int(under_construction or 0))
    if uc <= 0:
        return 0.0
    return (
        float(uc)
        * construction_weekly_cs_base_rate(construction_target)
        * max(0.0, float(pace_scale or 1.0))
    )


