# 시설
# ---------------------------------------------------------------------------
@dataclass
class Facility:
    name: str
    state_id: str
    company_id: str
    level: int = 1
    closed_levels: int = 0
    # (requirements.md) 폐쇄된 "단계별" 유휴 주차를 개별 트래킹
    idle_stage_weeks: List[int] = field(default_factory=list)
    # legacy (kept for compatibility; no longer authoritative)
    idle_weeks: int = 0
    under_construction: int = 0
    under_construction_signal: int = 0
    under_construction_demand: int = 0
    demand_supply_cooldown_weeks: int = 0
    demand_supply_completed_this_week: bool = False
    construction_progress: float = 0.0
    construction_target: float = 0.0
    last_week_construction_services: float = 0.0
    pending_bond_issue: float = 0.0
    bond_sold_for_construction: float = 0.0
    construction_initial_stages: int = 0
    construction_work_total: float = 0.0
    construction_funded_until: float = 0.0
    construction_bond_issued: float = 0.0
    construction_funding_tier: str = ""
    construction_start_base_rate: float = 0.0
    construction_start_corp_rate: float = 0.0
    construction_start_cs_price: float = 0.0
    construction_start_material_index: float = 0.0
    construction_pace_scale: float = 1.0
    construction_last_gate_cost: float = 0.0
    is_office: bool = False
    planned_weekly_output: float = 0.0
    base_input_fill: float = 1.0
    actual_input_fill: float = 1.0
    input_fill_history: deque = field(
        default_factory=lambda: deque(maxlen=INPUT_FILL_HISTORY_WEEKS))
    # 전주 노동·투입 체결 스냅샷 (시설 클릭 상세용)
    last_labor_type: str = ""
    last_labor_needed: float = 0.0
    last_labor_filled: float = 0.0
    last_labor_ratio: float = 1.0
    last_overtime_mult: float = 1.0
    last_effective_labor_ratio: float = 1.0
    last_wage_premium: float = 1.0
    last_input_fills: Dict[str, Dict[str, float]] = field(default_factory=dict)
    last_optional_fills: Dict[str, Dict[str, float]] = field(default_factory=dict)
    last_maint_cs_ordered: float = 0.0
    last_maint_cs_filled: float = 0.0

    def active_levels(self) -> int:
        return max(0, self.level - self.closed_levels)

    def base_output(self) -> float:
        spec = FACILITY_SPECS.get(self.name, {})
        return spec.get("output_qty", 0) * self.active_levels()


@dataclass
class SelfEmployedFacility:
    """레거시 — 자영 건물 제거 후 미사용. 호환용 유지."""
    name: str
    level: int = 0
    under_construction: int = 0
    construction_progress: float = 0.0
    construction_target: float = 0.0
    workers: float = 0.0
    planned_weekly_output: float = 0.0
    actual_input_fill: float = 1.0
    last_construction_fill: float = 0.0
    low_util_weeks: int = 0

    def active_levels(self) -> int:
        return max(0, self.level)

    def labor_capacity(self) -> float:
        return 0.0


@dataclass
class SelfEmployedSector:
    state_id: str
    sector: str
    facilities: List[SelfEmployedFacility] = field(default_factory=list)  # 항상 빈 목록
    cash_pool: float = 0.0
    weekly_revenues: Dict[str, float] = field(default_factory=dict)
    weekly_expenses: Dict[str, float] = field(default_factory=dict)
    last_input_fill_ratio: float = 1.0
    last_optional_fill_ratio: float = 0.0
    last_optional_tech_avg: float = 1.0
    last_construction_fill: float = 0.0
    pending_construction_bill: float = 0.0
    planned_output: Dict[str, float] = field(default_factory=dict)
    pending_retail: Dict[str, Dict[str, Tuple[float, float]]] = field(default_factory=dict)
    pending_overflow: Dict[str, Dict[str, Tuple[float, float]]] = field(default_factory=dict)
    weekly_retail_volume: float = 0.0
    last_settled_retail_volume: float = 0.0  # 전주 실제 소매 정산량 (임대·단가 산정용)
    last_ordered_volume: float = 0.0
    last_wholesale_fill: float = 0.0
    last_labor_fill: float = 1.0
    last_channel_share: float = 0.0
    # Soft retail / 빈틈 진입 신호 (전주 → 이번 주 임대 목표)
    last_goods_demand: float = 0.0
    last_overflow_volume: float = 0.0
    last_unmet_retail: float = 0.0
    last_corp_retail_cap: float = 0.0
    last_mkt_retail_cap: float = 0.0
    # 임대 기반 가동
    rental_ordered: float = 0.0
    rental_filled: float = 0.0
    workers: float = 0.0
    activity_scales: Dict[str, float] = field(default_factory=dict)  # activity → 목표 임대
    service_rental_ordered: Dict[str, float] = field(default_factory=dict)  # 서비스 활동별 임대 목표
    service_rental_filled: Dict[str, float] = field(default_factory=dict)  # 서비스 활동별 임대 체결
    actual_input_fill: float = 1.0
    flow_ma_goods_buy: Dict[str, float] = field(default_factory=dict)
    flow_ma_goods_sell: Dict[str, float] = field(default_factory=dict)
    flow_ma_labor_buy: Dict[str, float] = field(default_factory=dict)


def init_state_self_employed(st: "State") -> None:
    st.self_employed = {}
    for sector in SELF_EMP_SECTORS:
        st.self_employed[sector] = SelfEmployedSector(
            state_id=st.id, sector=sector, facilities=[],
            rental_ordered=SELF_EMP_RENTAL_ORDER_BASE if sector in ("service", "commerce") else 0.0,
        )


def ensure_state_commerce_sector(st: "State") -> SelfEmployedSector:
    if not getattr(st, "self_employed", None):
        init_state_self_employed(st)
    sector_obj = st.self_employed.get(COMMERCE_SECTOR)
    if sector_obj is None:
        sector_obj = SelfEmployedSector(
            state_id=st.id, sector=COMMERCE_SECTOR, facilities=[],
            rental_ordered=SELF_EMP_RENTAL_ORDER_BASE,
        )
        st.self_employed[COMMERCE_SECTOR] = sector_obj
    sector_obj.facilities = []  # 건물 제거
    if float(getattr(sector_obj, "rental_ordered", 0.0) or 0.0) <= 1e-9:
        sector_obj.rental_ordered = SELF_EMP_RENTAL_ORDER_BASE
    if not hasattr(sector_obj, "pending_retail") or sector_obj.pending_retail is None:
        sector_obj.pending_retail = {}
    if not hasattr(sector_obj, "pending_overflow") or sector_obj.pending_overflow is None:
        sector_obj.pending_overflow = {}
    return sector_obj


def _self_emp_sector_add_revenue(sector_obj: SelfEmployedSector, label: str, amount: float) -> None:
    if amount <= 1e-9:
        return
    if not getattr(sector_obj, "weekly_revenues", None):
        sector_obj.weekly_revenues = {}
    sector_obj.weekly_revenues[label] = sector_obj.weekly_revenues.get(label, 0.0) + amount


def _self_emp_sector_add_expense(sector_obj: SelfEmployedSector, label: str, amount: float) -> None:
    if amount <= 1e-9:
        return
    if not getattr(sector_obj, "weekly_expenses", None):
        sector_obj.weekly_expenses = {}
    sector_obj.weekly_expenses[label] = sector_obj.weekly_expenses.get(label, 0.0) + amount


def _rollup_self_emp_finance_sources(sources: Dict[str, float]) -> Dict[str, float]:
    """자영 재무 라벨 정리 — 소매·/도매· 항목을 UI용 대표 라벨로 묶는다."""
    merged: Dict[str, float] = defaultdict(float)
    for label, value in (sources or {}).items():
        if value <= 1e-6:
            continue
        # 이윤 배분·운영 적자 보전은 POP 측 거래이지 섹터 영업지출이 아님
        if label == "자영업 이윤" or label.startswith("자영업 이윤"):
            continue
        if label == "운영 적자" or label.startswith("운영 적자"):
            continue
        if label.startswith("소매·"):
            merged[SELF_EMP_RETAIL_INCOME_LABEL] += value
        elif label.startswith("도매·"):
            merged[SELF_EMP_RETAIL_EXPENSE_LABEL] += value
        else:
            merged[label] += value
    return dict(merged)


def self_emp_finance_detail_rows(sources: Dict[str, float]) -> List[Dict[str, Any]]:
    """자영 수입/지출 상세 API 행."""
    merged = _rollup_self_emp_finance_sources(sources)
    return [
        {"label": lab, "value": round(val, 2)}
        for lab, val in sorted(merged.items(), key=lambda x: -x[1])
    ]


def self_employed_actor_id(state_id: str, sector: str) -> str:
    return f"se_{state_id}_{sector}"


def parse_self_employed_actor_id(entity_id: str) -> Optional[Tuple[str, str]]:
    """자영 매수 주체 ID → (state_id, sector). 아니면 None."""
    if not entity_id or not str(entity_id).startswith("se_"):
        return None
    for sector in SELF_EMP_SECTORS:
        suffix = f"_{sector}"
        if entity_id.endswith(suffix):
            state_id = entity_id[3:-len(suffix)]
            if state_id:
                return state_id, sector
    return None


def is_self_employed_actor_id(entity_id: str) -> bool:
    return parse_self_employed_actor_id(entity_id) is not None


def self_emp_sector_has_activities(sector: str) -> bool:
    """농경·상업은 별도 경로. 그 외는 활동 스펙이 있는 섹터만 가동한다."""
    if sector in ("farm", COMMERCE_SECTOR):
        return True
    return any(
        spec.get("sector") == sector for spec in SELF_EMP_ACTIVITY_SPECS.values()
    )


def self_emp_service_activity_items(*, ban_private_edu: bool = False) -> List[Tuple[str, Dict]]:
    """자영 서비스 활동 목록. 민간 교육 금지면 교육 활동을 제외한다."""
    items: List[Tuple[str, Dict]] = []
    for name, spec in SELF_EMP_ACTIVITY_SPECS.items():
        if spec.get("sector") != "service":
            continue
        if ban_private_edu and name == "민간 교육 서비스":
            continue
        items.append((name, spec))
    return items


def public_welfare_offered_output(world: "World", st: "State", *services: str) -> float:
    """공공 복지 시설이 시장에 내놓는 산출량 ≈ output_qty × active × fill × efficiency."""
    gov = getattr(st, "local_government", None)
    if gov is None or not services:
        return 0.0
    country = world.countries.get(st.country_id) if world else None
    fill = float(getattr(gov, "operation_fill_ratio", 1.0) or 0.0)
    total = 0.0
    for service in services:
        facs = []
        getter = getattr(gov, "_public_facilities_for_service", None)
        if callable(getter):
            facs = list(getter(service) or [])
        else:
            primary = getattr(gov, "_primary_public_facility", None)
            fac = primary(service) if callable(primary) else None
            if fac is not None:
                facs = [fac]
        op = PUBLIC_OPERATION_SPECS.get(service, {})
        out_qty = float(op.get("output_qty", 0) or 0.0)
        if out_qty <= 1e-9:
            continue
        eff = public_operation_efficiency(service, country=country)
        active = 0.0
        for fac in facs:
            active += float(fac.active_levels() or 0)
        if active <= 1e-9:
            continue
        total += out_qty * active * fill * eff
    return total


def self_emp_own_planned_output(st: "State", product: str) -> float:
    """이번 주 자영이 막 잡아 둔 해당 상품 산출(전주 임대 체결 기반)."""
    if not product:
        return 0.0
    mk = market_key(st.id, product)
    total = 0.0
    for se in (getattr(st, "self_employed", None) or {}).values():
        total += float((getattr(se, "planned_output", None) or {}).get(mk, 0.0) or 0.0)
    return total


def self_emp_product_market_gap(
    world: "World",
    st: "State",
    product: str,
    *,
    public_svcs: Optional[Tuple[str, ...]] = None,
    exclude_actor: Optional[str] = None,
    prefer_live: bool = False,
) -> float:
    """자영이 채울 잔여 수요 = 매수 − 타인 매도(기업·공공).

    last_sell에는 자기 전주 매도가 들어 있다. 그걸 통째로 빼면
    ‘남은 부족분’만 규모가 되어 다음 주에 축소→부족→재확대가 반복된다.
    자기 산출은 목표에 남기고, 타인 공급만 차감한다.
    호가창이 있으면 라이브 타인 매도를 우선한다(자기 매도 제출 전).
    """
    if not product:
        return 0.0
    mk = world.markets.get(market_key(st.id, product)) if world else None
    if not mk:
        return 0.0
    live_buy = 0.0
    for o in getattr(mk, "buy_orders", None) or []:
        live_buy += float(getattr(o, "quantity", 0.0) or 0.0)
    last_buy = float(getattr(mk, "last_buy_volume", 0.0) or 0.0)
    own = self_emp_own_planned_output(st, product)
    live_others = 0.0
    for s in getattr(mk, "sell_orders", None) or []:
        seller = str(getattr(s, "seller_id", "") or "")
        if exclude_actor and seller == exclude_actor:
            continue
        live_others += float(getattr(s, "quantity", 0.0) or 0.0)
    last_sell = float(getattr(mk, "last_sell_volume", 0.0) or 0.0)
    if prefer_live:
        # 호가창이 이미 수요·타인 매도를 담은 시점 (자영농)
        demand = live_buy
        others = live_others
    else:
        demand = last_buy if last_buy > 1e-9 else live_buy
        others = live_others if live_others > 1e-9 else max(0.0, last_sell - own)
    if public_svcs:
        others = max(others, public_welfare_offered_output(world, st, *public_svcs))
    return max(0.0, demand - others)


def self_emp_service_market_gap(
    world: "World", st: "State", act_name: str, spec: Dict,
) -> float:
    """자영 서비스가 이번 주 맡아야 할 산출 목표."""
    product = spec.get("output")
    if not product:
        return 0.0
    actor = self_employed_actor_id(st.id, "service")
    return self_emp_product_market_gap(
        world, st, str(product),
        public_svcs=SELF_EMP_SERVICE_PUBLIC_OFFSET.get(act_name),
        exclude_actor=actor,
        prefer_live=False,
    )


def self_emp_activity_rental_need(
    gap: float, spec: Dict, *, output_per_rental: float = 0.0,
) -> float:
    """산출 목표를 임대 목표로 역산. 수요가 없으면 0."""
    if float(gap or 0.0) <= 1e-9:
        return 0.0
    out_qty = float(spec.get("output_qty", 0) or 0.0)
    nominal = out_qty * float(SELF_EMP_OUTPUT_MULTIPLIER)
    realized = float(output_per_rental or 0.0)
    if realized > 1e-9 and nominal > 1e-9:
        per = clamp(realized, nominal * 0.40, nominal * 1.25)
    else:
        per = nominal
    denom = per * SELF_EMP_RENTAL_OUTPUT_BUFFER
    if denom <= 1e-9:
        return 0.0
    return max(0.0, float(gap) / denom)


def allocate_service_rental_fill(
    rental_got: float,
    ordered: Optional[Dict[str, float]],
    *,
    ban_private_edu: bool = False,
) -> Dict[str, float]:
    """임대 체결량을 활동 주문량 비례로 귀속. 주문 dict가 없을 때만 구 균등."""
    acts = self_emp_service_activity_items(ban_private_edu=ban_private_edu)
    got = max(0.0, float(rental_got or 0.0))
    if not isinstance(ordered, dict) or not ordered:
        n = max(len(acts), 1)
        return {name: got / n for name, _ in acts}
    allowed = {name for name, _ in acts}
    total_ord = 0.0
    cleaned: Dict[str, float] = {}
    for name, qty in ordered.items():
        if name not in allowed:
            continue
        o = max(0.0, float(qty or 0.0))
        cleaned[name] = o
        total_ord += o
    filled: Dict[str, float] = {}
    for name, _ in acts:
        o = cleaned.get(name, 0.0)
        filled[name] = got * (o / total_ord) if total_ord > 1e-9 else 0.0
    return filled


def production_scale_economy_bonus(stages: int) -> float:
    """규모의 경제: 1단계 +0.2%, 한계증가분은 log2로 감소.

    총보너스 = 0.2% × log2(1 + 가동단계). 단계가 늘수록 단계당 가산이 줄어든다.
    """
    n = max(0, int(stages or 0))
    if n <= 0:
        return 0.0
    return PROD_EFF_SCALE_PER_STAGE * math.log2(1.0 + float(n))


def self_emp_production_efficiency(
    social_tech: int,
    optional_fill: float,
    optional_tech_avg: float,
    active_levels: int,
    farm_coop_mult: float = 1.0,
) -> float:
    scale_bonus = production_scale_economy_bonus(active_levels)
    tech_bonus = float(social_tech or 0) * PROD_EFF_TECH_PER_LEVEL
    optional_bonus = (
        PROD_EFF_OPTIONAL_WEIGHT
        * clamp(float(optional_fill or 0.0), 0.0, 1.0)
        * max(0.0, float(optional_tech_avg or 0.0))
    )
    base = 1.0 + scale_bonus + tech_bonus + optional_bonus
    return base * float(farm_coop_mult or 1.0)


def state_self_emp_expected_domestic_output(
    state_id: str,
    product: str,
    states: Dict[str, "State"],
    countries: Dict[str, "Country"],
    warmup: bool = False,
) -> float:
    """해당 주·상품 자영 시설의 (실제 효율 × 기본 산출량 × 가동 단계) 합계."""
    st = states.get(state_id)
    if not st or not st.self_employed:
        return 0.0
    country = countries.get(st.country_id)
    social_tech = int(country_social_tech_level(country)) if country else 0
    total = 0.0
    for sector_obj in st.self_employed.values():
        optional_fill = 0.0 if warmup else sector_obj.last_optional_fill_ratio
        optional_tech = 1.0 if warmup else sector_obj.last_optional_tech_avg
        for fac in sector_obj.facilities:
            spec = SELF_EMP_FACILITY_SPECS.get(fac.name, {})
            if spec.get("output") != product:
                continue
            levels = fac.active_levels()
            if levels <= 0:
                continue
            if warmup:
                labor_ratio = 1.0
                input_fill = 1.0
            else:
                labor_cap = fac.labor_capacity()
                labor_ratio = clamp(fac.workers / max(labor_cap, 1e-9), 0.0, 1.0)
                input_fill = fac.actual_input_fill
            efficiency = self_emp_production_efficiency(
                social_tech, optional_fill, optional_tech, levels,
            )
            total += (
                spec.get("output_qty", 0) * levels * SELF_EMP_OUTPUT_MULTIPLIER
                * efficiency * input_fill * labor_output_factor(labor_ratio)
            )
    return total


def self_emp_sector_demand_weight(
    world: "World", state_id: str, sector: str,
) -> float:
    """주·섹터별 수요 신호 (가격·체결·공급 부족)."""
    products: List[str] = []
    if sector == "farm":
        products = ["농업 상품", "축산품"]
    elif sector == "craft":
        products = []
    elif sector == COMMERCE_SECTOR:
        # 유통 채널: 재화 소매 미충족·소매가 신호 (대표 생필품)
        products = ["농업 상품", "식료품", "축산품", "주류", "의류", "가구", "제약품", "석유 정제품"]
    else:
        products = [
            "생활 서비스", "의료 서비스", "교육 서비스", "여가 및 숙박 서비스",
            "외식 서비스",
        ]
    signals: List[float] = []
    for product in products:
        mk = world.markets.get(market_key(state_id, product))
        if not mk:
            continue
        price = market_goods_labor_price(mk)
        base = PRODUCT_BASE_PRICES.get(product, price)
        price_signal = clamp((price - base) / max(base, 1.0), -0.5, 1.0)
        traded = mk.last_buy_volume + mk.last_sell_volume
        volume_signal = clamp(traded / max(mk.last_sell_volume, 1.0) - 1.0, -0.5, 1.0)
        imbalance = wma(list(mk.order_imbalance_history)[-4:]) if mk.order_imbalance_history else 0.0
        shortage = clamp(imbalance / max(base, 1.0), -0.5, 1.0)
        signals.append(0.35 * price_signal + 0.25 * volume_signal + 0.40 * shortage)
    base_w = max(0.05, sum(signals) / len(signals) + 0.5) if signals else 0.1
    # 자영 상업: soft overflow·미충족이 있으면 빈틈 진입 신호 강화
    if sector == COMMERCE_SECTOR:
        st = world.states.get(state_id)
        commerce = (getattr(st, "self_employed", None) or {}).get(COMMERCE_SECTOR) if st else None
        if commerce is not None:
            cap = max(
                float(getattr(commerce, "last_mkt_retail_cap", 0.0) or 0.0),
                commerce_market_retail_capacity(commerce),
                1.0,
            )
            overflow = float(getattr(commerce, "last_overflow_volume", 0.0) or 0.0)
            unmet = float(getattr(commerce, "last_unmet_retail", 0.0) or 0.0)
            gap_signal = clamp((overflow + unmet) / cap, 0.0, 1.5)
            base_w = max(base_w, 0.35 + 0.55 * gap_signal)
    return clamp(base_w, 0.05, 1.5)


def self_emp_facility_demand_weight(
    world: "World", state_id: str, facility_name: str,
) -> float:
    spec = SELF_EMP_FACILITY_SPECS.get(facility_name, {})
    product = spec.get("output")
    if not product:
        return 0.1
    mk = world.markets.get(market_key(state_id, product))
    if not mk:
        return 0.1
    base = PRODUCT_BASE_PRICES.get(product, mk.current_price)
    price = market_goods_labor_price(mk)
    price_signal = clamp((price - base) / max(base, 1.0), -0.5, 1.0)
    imbalance = wma(list(mk.order_imbalance_history)[-4:]) if mk.order_imbalance_history else 0.0
    shortage = clamp(imbalance / max(base, 1.0), -0.5, 1.0)
    return max(0.05, 0.5 + 0.4 * price_signal + 0.6 * shortage)


def pop_contribute_construction_fund(
    world: "World", pops: List["POP"], total_cost: float,
) -> float:
    """주 내 POP 비례 건설비 징수 (현금 → 예금 → auto_loan)."""
    return pop_contribute_self_emp_sector_fund(
        world, pops, total_cost, sector_label=None, pop_expense_label=None,
        track_construction_contrib=True,
    )


def pop_contribute_self_emp_sector_fund(
    world: "World",
    pops: List["POP"],
    total_cost: float,
    *,
    sector_label: Optional[str] = None,
    pop_expense_label: Optional[str] = None,
    track_construction_contrib: bool = False,
) -> float:
    """자영 섹터 비용 징수: 해당 섹터 종사자 비율, 종사자 없으면 POP size 비례."""
    if total_cost <= 1e-9 or not pops:
        return 0.0
    worker_weight_total = 0.0
    worker_weights: List[Tuple["POP", float]] = []
    for pop in pops:
        if sector_label:
            weight = max(
                pop.self_emp_sector_payout_eligible.get(sector_label, 0.0), 0.0)
        else:
            weight = max(pop.adult_self_employed_payout_eligible, 0.0)
        if weight <= 1e-9:
            continue
        worker_weights.append((pop, weight))
        worker_weight_total += weight
    use_size = worker_weight_total <= 1e-9
    if use_size:
        weight_total = sum(max(p.size, 1.0) for p in pops)
    else:
        weight_total = worker_weight_total
    if weight_total <= 1e-9:
        return 0.0
    collected = 0.0
    targets: List[Tuple["POP", float]] = (
        [(p, max(p.size, 1.0)) for p in pops] if use_size else worker_weights
    )
    for pop, weight in targets:
        if weight <= 1e-9:
            continue
        share = total_cost * weight / weight_total
        if share <= 1e-9:
            continue
        _cid = world.states[pop.state_id].country_id
        if pop.cash < share:
            world.distribute_new_loan(pop, share - pop.cash, _cid, apply_discretion=False)
        pay = min(pop.cash, share)
        if pay <= 1e-9:
            continue
        pop.cash -= pay
        collected += pay
        if track_construction_contrib:
            pop.self_emp_construction_contributed += pay
        if pop_expense_label:
            pop.weekly_expense += pay
            pop_record_expense(pop, pop_expense_label, pay)
    return collected


@dataclass
class PendingConstruction:
    company: "Company"
    facility: Optional[Facility]
    facility_name: str
    state_id: str
    stages: int
    source: str
    is_zero_to_one: bool

    def apply(self, markets: Dict[str, "MarketState"]) -> None:
        if self.stages <= 0:
            return
        if self.facility is not None:
            self.company._ensure_facility_attached(self.facility)
            self.company._start_construction(
                self.facility, self.stages, markets, source=self.source)
        else:
            self.company._start_office_construction(self.stages, markets)


