        self.gov_mood = 0.0
        self.gov_polarization = POP_GOV_OPINION_SIGMA_BASE
        self.gov_support = 0.0
        self.gov_neutral = 1.0
        self.gov_oppose = 0.0
        self.gov_opinion_inited = False
        self.gov_opinion_reasons: Dict[str, List[Dict[str, Any]]] = {
            "support": [], "neutral": [], "oppose": [],
        }
