def series_yoy_pct(hist) -> Optional[float]:
    """주간 시계열에서 전년 동기 대비 성장률(%). 52주 미만이면 연율 환산."""
    h = [float(x) for x in (hist or []) if x is not None]
    if len(h) < 2:
        return None
    if len(h) >= 53:
        old, new = h[-53], h[-1]
    else:
        old, new = h[0], h[-1]
        weeks = max(1, len(h) - 1)
        if abs(old) < 1e-12:
            return None
        total = (new - old) / abs(old)
        try:
            return ((1.0 + total) ** (52.0 / weeks) - 1.0) * 100.0
        except Exception:
            return None
    if abs(old) < 1e-12:
        return None
    return (new - old) / abs(old) * 100.0


def series_index_inflation_pct(hist, *, base: float = 100.0) -> Optional[float]:
    """물가 지수 인플레(%).

    1년(53포인트) 이상이면 전년 동기 대비.
    미만이면 시작 기준(100) 대비 누적 변화율. 연율 환산하지 않는다.
    """
    h = [float(x) for x in (hist or []) if x is not None]
    if not h:
        return None
    new = h[-1]
    if abs(base) < 1e-12:
        return None
    if len(h) >= 53:
        old = h[-53]
        if abs(old) < 1e-12:
            return None
        return (new - old) / abs(old) * 100.0
    return (new - base) / abs(base) * 100.0


def series_annual_flow_window(
    hist_len: int,
    year_weeks: int = GDP_YOY_YEAR_WEEKS,
) -> int:
    """YoY·연간창 평균에 쓰는 동일 길이 합산 주수.

    이력이 2N 이상이면 N주, 미만이면 len//2주(최소 1).
    """
    hlen = int(hist_len or 0)
    if hlen < 1:
        return 0
    n = int(year_weeks) if year_weeks and year_weeks > 0 else GDP_YOY_YEAR_WEEKS
    if hlen < 2:
        return hlen
    return min(n, hlen // 2)


def series_annual_flow_avg(
    hist,
    year_weeks: int = GDP_YOY_YEAR_WEEKS,
) -> Optional[float]:
    """최근 합산창 주간 GDP 평균 = (최근 window주 합) / window."""
    h = [float(x) for x in (hist or []) if x is not None]
    window = series_annual_flow_window(len(h), year_weeks)
    if window < 1:
        return None
    return sum(h[-window:]) / float(window)


def series_annual_flow_avg_series(
    hist,
    year_weeks: int = GDP_YOY_YEAR_WEEKS,
) -> List[float]:
    """각 시점까지의 이력으로 연간창 평균 주간 GDP 시계열."""
    h = [float(x) for x in (hist or []) if x is not None]
    out: List[float] = []
    for i in range(len(h)):
        prefix_len = i + 1
        w = series_annual_flow_window(prefix_len, year_weeks)
        if w < 1:
            out.append(h[i])
        else:
            out.append(sum(h[prefix_len - w:prefix_len]) / float(w))
    return out


def series_annual_flow_sum(
    hist,
    year_weeks: int = GDP_YOY_YEAR_WEEKS,
) -> Optional[float]:
    """연간 GDP = 최근 최대 year_weeks주 주간 유량 합.

    이력이 year_weeks 미만이면 합 × (year_weeks/창길이)로 연율 환산한다.
    """
    h = [float(x) for x in (hist or []) if x is not None]
    if not h:
        return None
    n = int(year_weeks) if year_weeks and year_weeks > 0 else GDP_YOY_YEAR_WEEKS
    window = min(len(h), n)
    if window < 1:
        return None
    total = sum(h[-window:])
    if window < n:
        return total * (float(n) / float(window))
    return total


def series_annual_flow_sum_series(
    hist,
    year_weeks: int = GDP_YOY_YEAR_WEEKS,
) -> List[float]:
    """각 시점까지의 이력으로 연간 GDP(합·짧은 창은 연율) 시계열."""
    h = [float(x) for x in (hist or []) if x is not None]
    n = int(year_weeks) if year_weeks and year_weeks > 0 else GDP_YOY_YEAR_WEEKS
    out: List[float] = []
    for i in range(len(h)):
        prefix_len = i + 1
        window = min(prefix_len, n)
        if window < 1:
            out.append(h[i])
            continue
        total = sum(h[prefix_len - window:prefix_len])
        if window < n:
            total *= float(n) / float(window)
        out.append(total)
    return out


def series_annual_flow_yoy_pct(
    hist,
    year_weeks: int = GDP_YOY_YEAR_WEEKS,
) -> Optional[float]:
    """주간 유량 합산 YoY(%): 최근 N주 합 ÷ 직전 N주 합.

    GDP처럼 주간 값이 유량일 때 사용. 점대점(전년 동기 주) 대비보다
    주간 노이즈에 덜 민감하다. 이력이 2N 미만이면 가능한 최대 동일 길이
    구간(N'=len//2)으로 비교한다.
    """
    h = [float(x) for x in (hist or []) if x is not None]
    if len(h) < 2:
        return None
    window = series_annual_flow_window(len(h), year_weeks)
    if window < 1:
        return None
    recent = sum(h[-window:])
    prior = sum(h[-2 * window:-window])
    if abs(prior) < 1e-12:
        return None
    return (recent - prior) / abs(prior) * 100.0


def series_yoy_delta(hist) -> Optional[float]:
    """주간 시계열 전년 동기 대비 절대 차이 (금리 %p 등). 52주 미만이면 연율 환산."""
    h = [float(x) for x in (hist or []) if x is not None]
    if len(h) < 2:
        return None
    if len(h) >= 53:
        return h[-1] - h[-53]
    weeks = max(1, len(h) - 1)
    return (h[-1] - h[0]) * (52.0 / weeks)


def series_weekly_vol_pct(hist, window: int = 13) -> Optional[float]:
    """주간 수익률 표준편차(%)."""
    h = [float(x) for x in (hist or []) if x is not None and float(x) > 0]
    if len(h) < 3:
        return None
    sample = h[-window:] if len(h) >= window else h
    rets = []
    for i in range(1, len(sample)):
        prev = sample[i - 1]
        if prev <= 1e-12:
            continue
        rets.append(sample[i] / prev - 1.0)
    if len(rets) < 2:
        return None
    mean = sum(rets) / len(rets)
    var = sum((r - mean) ** 2 for r in rets) / (len(rets) - 1)
    return (var ** 0.5) * 100.0


def _price_series_with_current(market) -> List[float]:
    hist: List[float] = []
    for p in (getattr(market, "weekly_price_history", None) or []):
        try:
            x = float(p)
        except (TypeError, ValueError):
            continue
        if math.isfinite(x) and x > 0:
            hist.append(x)
    current = float(getattr(market, "current_price", 0.0) or 0.0)
    if current > 0 and (not hist or abs(hist[-1] - current) > 1e-9):
        hist = hist + [current]
    return hist


# 종합 물가 섹터 가중치 (합=1). 인플레 = Σ(섹터YoY × w) / Σw
INFLATION_SECTOR_WEIGHTS = {
    "goods": 0.40,
    "services": 0.40,
    "real_estate": 0.20,
}
# 원자재 물가: 광물·원유 등 1차 원자재
PRICE_COMMODITY_PRODUCTS = frozenset({
    "광물", "원유", "석유 정제품", "농업 상품", "임업 가공품",
})
# 산업 물가: 중간재·자본재 (원자재·소비재 제외)
PRICE_INDUSTRIAL_PRODUCTS = frozenset({
    "철강", "금속", "화학 제품",
    "기계 부품", "생산 기계", "산업 설비",
    "반도체", "선박", "제약품",
})


def _weighted_mean(pairs: List[Tuple[float, float]]) -> Optional[float]:
    """Σ(value×weight) / Σ(weight). weight≤0 항목은 제외."""
    num = 0.0
    den = 0.0
    for value, weight in pairs:
        w = float(weight)
        if w <= 1e-12:
            continue
        num += float(value) * w
        den += w
    if den <= 1e-12:
        return None
    return num / den


def _avg_series_yoy(series_list: List[List[float]]) -> Optional[float]:
    yoys: List[float] = []
    for series in series_list:
        y = series_yoy_pct(series)
        if y is not None:
            yoys.append(y)
    if not yoys:
        return None
    return sum(yoys) / len(yoys)


def _avg_aligned_series(series_list: List[List[float]]) -> List[float]:
    """여러 시계열을 끝(최신) 기준으로 정렬해 등가중 평균."""
    return _weighted_avg_aligned_series([(s, 1.0) for s in series_list if s])


def _weighted_avg_aligned_series(
    series_weights: List[Tuple[List[float], float]],
) -> List[float]:
    """여러 시계열을 끝(최신) 기준으로 정렬해 가중 평균. Σ(v·w)/Σw."""
    usable = [(s, float(w)) for s, w in series_weights if s and float(w) > 1e-12]
    if not usable:
        return []
    max_len = max(len(s) for s, _ in usable)
    agg: List[float] = []
    for i in range(max_len):
        pairs: List[Tuple[float, float]] = []
        for s, w in usable:
            if len(s) >= max_len - i:
                pairs.append((float(s[len(s) - (max_len - i)]), w))
        mean = _weighted_mean(pairs)
        if mean is not None:
            agg.append(mean)
    return agg


def _market_base100_index_series(market) -> List[float]:
    """시장 가격을 base_price(또는 최초가)=100 지수로 변환."""
    series = _price_series_with_current(market)
    if not series:
        return []
    base = float(getattr(market, "base_price", 0.0) or 0.0)
    if base <= 1e-12:
        base = float(series[0])
    if base <= 1e-12:
        return []
    return [float(p) / base * 100.0 for p in series]


def country_price_bucket_series(
    world: "World", country_id: str,
) -> Dict[str, List[List[float]]]:
    """국가 상품·서비스·부동산 가격 시계열 버킷."""
    states = [s for s in world.states.values() if s.country_id == country_id]
    goods_series: List[List[float]] = []
    service_series: List[List[float]] = []
    re_series: List[List[float]] = []
    if not states:
        return {"goods": goods_series, "services": service_series, "real_estate": re_series}
    for st in states:
        for product in PRODUCT_BASE_PRICES:
            mk = world.markets.get(market_key(st.id, product))
            if not mk:
                continue
            series = _price_series_with_current(mk)
            if len(series) < 2:
                continue
            if product in NON_TRADABLE or "서비스" in product:
                service_series.append(series)
            else:
                goods_series.append(series)
    re_markets = getattr(world, "real_estate_markets", {}) or {}
    for st in states:
        for kind in RE_KINDS:
            rem = re_markets.get(re_market_key(st.id, kind))
            if not rem:
                continue
            series = _price_series_with_current(rem)
            if len(series) >= 2:
                re_series.append(series)
    return {"goods": goods_series, "services": service_series, "real_estate": re_series}


def country_inflation_index_series(
    world: "World", country_id: str,
) -> Dict[str, List[float]]:
    """상품·서비스·부동산·종합 물가 지수(기준=100) 시계열."""
    week = int(getattr(world, "week", -1) or -1)
    cache = getattr(world, "_cache_inflation_index_series", None)
    if cache is None:
        cache = {}
        world._cache_inflation_index_series = cache
    ck = (week, country_id)
    hit = cache.get(ck)
    if hit is not None:
        return hit
    st_idx = getattr(world, "_fin_idx_states_by_country", None)
    if st_idx is not None:
        states = st_idx.get(country_id) or []
    else:
        states = [s for s in world.states.values() if s.country_id == country_id]
    goods_idx: List[List[float]] = []
    service_idx: List[List[float]] = []
    re_idx: List[List[float]] = []
    industrial_idx: List[List[float]] = []
    commodity_idx: List[List[float]] = []
    if states:
        for st in states:
            for product in PRODUCT_BASE_PRICES:
                mk = world.markets.get(market_key(st.id, product))
                if not mk:
                    continue
                series = _market_base100_index_series(mk)
                if len(series) < 2:
                    continue
                if product in PRICE_COMMODITY_PRODUCTS:
                    commodity_idx.append(series)
                if product in PRICE_INDUSTRIAL_PRODUCTS:
                    industrial_idx.append(series)
                if product in NON_TRADABLE or "서비스" in product:
                    service_idx.append(series)
                else:
                    goods_idx.append(series)
        re_markets = getattr(world, "real_estate_markets", {}) or {}
        for st in states:
            for kind in RE_KINDS:
                rem = re_markets.get(re_market_key(st.id, kind))
                if not rem:
                    continue
                series = _market_base100_index_series(rem)
                if len(series) >= 2:
                    re_idx.append(series)
    goods = _avg_aligned_series(goods_idx)
    services = _avg_aligned_series(service_idx)
    real_estate = _avg_aligned_series(re_idx)
    industrial = _avg_aligned_series(industrial_idx)
    commodity = _avg_aligned_series(commodity_idx)
    sector_map = {
        "goods": goods,
        "services": services,
        "real_estate": real_estate,
    }
    composite = _weighted_avg_aligned_series([
        (sector_map[key], float(INFLATION_SECTOR_WEIGHTS.get(key, 0.0)))
        for key in ("goods", "services", "real_estate")
        if sector_map.get(key)
    ])
    result = {
        "composite": composite,
        "goods": goods,
        "services": services,
        "real_estate": real_estate,
        "industrial": industrial,
        "commodity": commodity,
    }
    cache[ck] = result
    return result


def pop_cpi_item_is_service(item: str) -> bool:
    return item in POP_DIRECT_BUY_ITEMS or "서비스" in str(item)


def pop_cpi_basket_weights() -> Dict[str, float]:
    """POP_NEEDS 가중 소비 장바구니. 가중치 = 욕구우선도 × target × max_share."""
    raw: Dict[str, float] = {}
    for need in POP_NEEDS:
        pri = float(POP_NEED_PRIORITY.get(need["name"], 1.0) or 1.0)
        target = float(need.get("target", 1.0) or 1.0)
        for item, _sat, max_share in need.get("items") or ():
            raw[item] = raw.get(item, 0.0) + pri * target * float(max_share or 0.0)
    tot = sum(raw.values())
    if tot <= 1e-12:
        return raw
    return {k: v / tot for k, v in raw.items()}


def _consumer_price_series_with_current(market) -> List[float]:
    """소비 CPI용 가격 시계열: 이력 + 최근 소매가(없으면 시장가)."""
    hist = [
        float(p) for p in (getattr(market, "weekly_price_history", None) or [])
        if float(p) > 0
    ]
    retail = float(getattr(market, "last_retail_price", 0.0) or 0.0)
    current = float(getattr(market, "current_price", 0.0) or 0.0)
    latest = retail if retail > 1e-12 else current
    if latest > 1e-12 and (not hist or abs(hist[-1] - latest) > 1e-9):
        hist = hist + [latest]
    return hist


def _consumer_base100_index_series(market) -> List[float]:
    series = _consumer_price_series_with_current(market)
    if not series:
        return []
    base = float(getattr(market, "base_price", 0.0) or 0.0)
    if base <= 1e-12:
        base = float(series[0])
    if base <= 1e-12:
        return []
    return [float(p) / base * 100.0 for p in series]


def series_nweek_change_pct(hist, weeks: int = 4) -> Optional[float]:
    """최근 N주 변화율(%). 이력이 짧으면 첫값 대비."""
    h = [float(x) for x in (hist or []) if x is not None]
    if len(h) < 2:
        return None
    n = max(1, int(weeks or 4))
    old = h[-(n + 1)] if len(h) > n else h[0]
    new = h[-1]
    if abs(old) < 1e-12:
        return None
    return (new - old) / abs(old) * 100.0


def _world_week_dict_cache(world: Optional["World"], name: str) -> Optional[Dict[str, Any]]:
    if world is None:
        return None
    week = int(getattr(world, "week", 0) or 0)
    store = getattr(world, name, None)
    cached_week = getattr(world, name + "_week", None)
    if not isinstance(store, dict) or cached_week != week:
        store = {}
        setattr(world, name, store)
        setattr(world, name + "_week", week)
    return store


def _empty_consumer_cpi() -> Dict[str, Any]:
    return {
        "index": [],
        "goods": [],
        "services": [],
        "food": [],
        "utilities": [],
        "transport": [],
        "yoy": None,
        "yoy_goods": None,
        "yoy_services": None,
        "yoy_food": None,
        "yoy_utilities": None,
        "yoy_transport": None,
        "change_4w": None,
        "change_4w_food": None,
        "change_4w_utilities": None,
        "change_4w_transport": None,
    }


def _cpi_pack_series(
    series: List[float], yoy_key: str, ch_key: Optional[str], out: Dict[str, Any],
) -> None:
    y = series_index_inflation_pct(series)
    out[yoy_key] = round(y, 4) if y is not None else None
    if ch_key:
        ch = series_nweek_change_pct(series, 4)
        out[ch_key] = round(ch, 4) if ch is not None else None


def country_consumer_cpi_series(
    world: "World", country_id: str,
) -> Dict[str, Any]:
    """POP_NEEDS 가중 소비 물가(기준=100). 생산재·부동산 제외."""
    cache = _world_week_dict_cache(world, "_pop_cpi_cache")
    if cache is not None and country_id in cache:
        return cache[country_id]
    empty = _empty_consumer_cpi()
    if world is None:
        return empty
    weights = pop_cpi_basket_weights()
    states = [s for s in world.states.values() if s.country_id == country_id]
    item_series: Dict[str, List[float]] = {}
    if states:
        for item, w in weights.items():
            if w <= 1e-12:
                continue
            collected: List[List[float]] = []
            for st in states:
                mk = world.markets.get(market_key(st.id, item))
                if not mk:
                    continue
                series = _consumer_base100_index_series(mk)
                if series:
                    collected.append(series)
            if collected:
                item_series[item] = _avg_aligned_series(collected)
    goods_pairs: List[Tuple[List[float], float]] = []
    service_pairs: List[Tuple[List[float], float]] = []
    all_pairs: List[Tuple[List[float], float]] = []
    food_pairs: List[Tuple[List[float], float]] = []
    util_pairs: List[Tuple[List[float], float]] = []
    trans_pairs: List[Tuple[List[float], float]] = []
    for item, series in item_series.items():
        w = float(weights.get(item, 0.0) or 0.0)
        if w <= 1e-12 or not series:
            continue
        pair = (series, w)
        all_pairs.append(pair)
        if pop_cpi_item_is_service(item):
            service_pairs.append(pair)
        else:
            goods_pairs.append(pair)
        if item in POP_CPI_FOOD_ITEMS:
            food_pairs.append(pair)
        if item in POP_CPI_UTIL_ITEMS:
            util_pairs.append(pair)
        if item in POP_CPI_TRANSPORT_ITEMS:
            trans_pairs.append(pair)
    out = _empty_consumer_cpi()
    out["index"] = _weighted_avg_aligned_series(all_pairs)
    out["goods"] = _weighted_avg_aligned_series(goods_pairs)
    out["services"] = _weighted_avg_aligned_series(service_pairs)
    out["food"] = _weighted_avg_aligned_series(food_pairs)
    out["utilities"] = _weighted_avg_aligned_series(util_pairs)
    out["transport"] = _weighted_avg_aligned_series(trans_pairs)
    _cpi_pack_series(out["index"], "yoy", "change_4w", out)
    _cpi_pack_series(out["goods"], "yoy_goods", None, out)
    _cpi_pack_series(out["services"], "yoy_services", None, out)
    _cpi_pack_series(out["food"], "yoy_food", "change_4w_food", out)
    _cpi_pack_series(out["utilities"], "yoy_utilities", "change_4w_utilities", out)
    _cpi_pack_series(out["transport"], "yoy_transport", "change_4w_transport", out)
    if cache is not None:
        cache[country_id] = out
    return out


def country_consumer_cpi_yoy(world: "World", country_id: str) -> Optional[float]:
    packed = country_consumer_cpi_series(world, country_id)
    y = packed.get("yoy")
    return float(y) if y is not None else None


def country_price_deflator_series(world: "World", country_id: str) -> List[float]:
    """실질 GDP 환산용 물가 지수(기준=100). 소비 CPI, 없으면 종합 물가."""
    cpi = country_consumer_cpi_series(world, country_id).get("index") or []
    vals = [float(x) for x in cpi if x is not None]
    if len(vals) >= 1:
        return vals
    idxs = country_inflation_index_series(world, country_id)
    return [float(x) for x in (idxs.get("composite") or []) if x is not None]


def deflate_flow_series_by_index(
    nominal, index, *, base: float = 100.0,
) -> List[float]:
    """명목 유량을 물가 지수로 나누어 실질 유량으로 환산. 끝점을 맞춰 정렬."""
    nom = [float(x) for x in (nominal or [])]
    idx = [float(x) for x in (index or [])]
    if not nom:
        return []
    if not idx:
        return nom[:]
    n_nom, n_idx = len(nom), len(idx)
    out: List[float] = []
    for i, v in enumerate(nom):
        j = i - n_nom + n_idx
        if j < 0:
            j = 0
        elif j >= n_idx:
            j = n_idx - 1
        d = idx[j]
        if d <= 1e-9:
            d = base
        out.append(v * base / d)
    return out


def country_real_gdp_series(
    world: "World", country_id: str, nominal_hist=None,
) -> List[float]:
    if nominal_hist is None:
        country = (getattr(world, "countries", None) or {}).get(country_id)
        nominal_hist = list(country_ensure_gdp_history(country)) if country else []
    return deflate_flow_series_by_index(
        nominal_hist, country_price_deflator_series(world, country_id))


def country_composite_inflation_yoy(world: "World", country_id: str) -> Optional[float]:
    """종합 물가 인플레(%). 1년 미만이면 지수 100 대비, 이후 전년 동기 대비."""
    idxs = country_inflation_index_series(world, country_id)
    y = series_index_inflation_pct(idxs.get("composite") or [])
    if y is not None:
        return y
    pairs: List[Tuple[float, float]] = []
    for key in ("goods", "services", "real_estate"):
        sy = series_index_inflation_pct(idxs.get(key) or [])
        if sy is None:
            continue
        w = float(INFLATION_SECTOR_WEIGHTS.get(key, 0.0))
        if w <= 1e-12:
            continue
        pairs.append((sy, w))
    return _weighted_mean(pairs)


def country_fx_index_series(world: "World", country_id: str) -> List[float]:
    """자국 기준 외환 지수(기준=100) 주간 시계열."""
    pair_histories: List[List[float]] = []
    for fid in sorted(world.countries.keys()):
        if fid == country_id:
            continue
        m_ab = world.fx_markets.get(fx_market_key(fid, country_id))
        if not m_ab:
            continue
        base = float(getattr(m_ab, "base_rate", 0.0) or 0.0)
        if base <= 1e-12:
            base = float(COUNTRY_FX_PAR.get(fid, 100.0) or 100.0) / max(
                float(COUNTRY_FX_PAR.get(country_id, 100.0) or 100.0), 1e-9
            )
            if base <= 1e-12:
                continue
        rates = [
            float(r) for r in (getattr(m_ab, "weekly_rate_history", None) or [])
            if float(r) > 0
        ]
        current = float(fx_home_per_foreign(country_id, fid, world) or 0.0)
        if current > 0 and (not rates or abs(rates[-1] - current) > 1e-9):
            rates = rates + [current]
        if not rates:
            continue
        pair_histories.append([r / base * 100.0 for r in rates])
    return _avg_aligned_series(pair_histories)


def country_fx_index_metrics(world: "World", country_id: str) -> Dict[str, Optional[float]]:
    """자국 기준 외환 지수(기준=100) · YoY · 주간 변동성(%)."""
    agg = country_fx_index_series(world, country_id)
    if not agg:
        return {"fx_index": None, "fx_index_yoy_pct": None, "fx_vol_pct": None}
    return {
        "fx_index": round(agg[-1], 2),
        "fx_index_yoy_pct": (
            round(y, 2) if (y := series_yoy_pct(agg)) is not None else None
        ),
        "fx_vol_pct": (
            round(v, 2) if (v := series_weekly_vol_pct(agg)) is not None else None
        ),
    }


def _weekly_values_to_line(values: List[float], world_week: int) -> List[Dict[str, float]]:
    """주간 값 리스트 → 차트 line 포인트."""
    n = len(values)
    if n <= 0:
        return []
    ww = int(world_week or 0)
    out: List[Dict[str, float]] = []
    for i, v in enumerate(values):
        try:
            num = float(v)
        except (TypeError, ValueError):
            continue
        out.append({
            "time": ww - (n - 1 - i),
            "value": round(num, 4),
        })
    return out


def country_m2_factor_history_payload(
    world: "World", country_id: str,
) -> Dict[str, Any]:
    """인구 현금+예금+펀드(통화량) 주간 합산 — HUD tip/구성용."""
    m2_factors: Tuple[Tuple[str, str, str], ...] = (
        ("cash", "현금", "#94a3b8"),
        ("deposits", "예금", "#38bdf8"),
        ("fund", "펀드", "#a78bfa"),
    )
    week = int(getattr(world, "week", 0) or 0)
    by_week: Dict[int, Dict[str, float]] = {}
    live_cash = 0.0
    live_dep = 0.0
    live_fund = 0.0
    for st in (getattr(world, "states", None) or {}).values():
        if getattr(st, "country_id", None) != country_id:
            continue
        for pop in (getattr(st, "pops", None) or []):
            live = pop_asset_mix_snapshot(world, pop)
            live_cash += float(live.get("cash") or 0.0)
            live_dep += float(live.get("deposits") or 0.0)
            live_fund += float(live.get("fund") or 0.0)
            for row in asset_mix_history_payload(pop, live):
                w = int(row.get("week") or 0)
                if w <= 0:
                    continue
                bucket = by_week.setdefault(
                    w, {"cash": 0.0, "deposits": 0.0, "fund": 0.0},
                )
                bucket["cash"] += float(row.get("cash") or 0.0)
                bucket["deposits"] += float(row.get("deposits") or 0.0)
                bucket["fund"] += float(row.get("fund") or 0.0)
    history: List[Dict[str, Any]] = []
    for w in sorted(by_week):
        row = by_week[w]
        cash = round(float(row["cash"]), 2)
        dep = round(float(row["deposits"]), 2)
        fund = round(float(row["fund"]), 2)
        history.append({
            "week": w,
            "cash": cash,
            "deposits": dep,
            "fund": fund,
            "total": round(cash + dep + fund, 2),
        })
    live_total = live_cash + live_dep + live_fund
    if live_total > 1e-9 or history:
        live_row = {
            "week": week,
            "cash": round(live_cash, 2),
            "deposits": round(live_dep, 2),
            "fund": round(live_fund, 2),
            "total": round(live_total, 2),
        }
        if not history or int(history[-1].get("week") or 0) != week:
            history.append(live_row)
        else:
            history[-1] = live_row
    last = history[-1] if history else {}
    return {
        "label": "통화량 구성",
        "source": "m2",
        "keys": [
            {
                "key": k,
                "label": lab,
                "color": col,
                "value": round(float(last.get(k, 0.0) or 0.0), 2),
            }
            for k, lab, col in m2_factors
        ],
        "history": history,
    }


def country_ensure_trade_product_history(country: "Country") -> deque:
    hist = getattr(country, "weekly_trade_product_history", None)
    if not isinstance(hist, deque):
        country.weekly_trade_product_history = deque(maxlen=GDP_HISTORY_MAX_WEEKS)
        hist = country.weekly_trade_product_history
    elif hist.maxlen != GDP_HISTORY_MAX_WEEKS:
        country.weekly_trade_product_history = deque(hist, maxlen=GDP_HISTORY_MAX_WEEKS)
        hist = country.weekly_trade_product_history
    return hist


def country_collect_trade_product_values(
    world: "World", country_id: str,
) -> Dict[str, Dict[str, float]]:
    """당주 품목별 수출·수입·국내 무역액."""
    out: Dict[str, Dict[str, float]] = {
        "export": defaultdict(float),
        "import": defaultdict(float),
        "domestic": defaultdict(float),
    }
    if not country_id:
        return {"export": {}, "import": {}, "domestic": {}}

    def _route_prices(route: Dict[str, Any], co_home_state: str) -> Tuple[float, float, Any, Any]:
        return _resolve_trade_route_prices(world, route, co_home_state)

    for co in world.companies.values():
        if co.type != "물류 기업":
            continue
        for route in getattr(co, "active_trade_routes", []) or []:
            price_a, _price_b, home, dest = _route_prices(route, co.home_state)
            dest_country_id = (
                dest.country_id if dest else str(route.get("dest_country", "") or "")
            )
            home_country_id = home.country_id if home else ""
            actual = float(route.get("actual_qty", 0.0) or 0.0)
            if actual <= 1e-9:
                continue
            is_foreign = bool(route.get("is_foreign"))
            value = actual * max(0.0, float(price_a or 0.0))
            if value <= 1e-9:
                continue
            prod = str(route.get("product") or "").strip() or "기타"
            if is_foreign and home_country_id == country_id:
                out["export"][prod] += value
            elif is_foreign and dest_country_id == country_id:
                out["import"][prod] += value
            elif (
                not is_foreign
                and home_country_id == country_id
                and dest_country_id == country_id
            ):
                out["domestic"][prod] += value
    return {
        "export": {k: round(v, 2) for k, v in out["export"].items()},
        "import": {k: round(v, 2) for k, v in out["import"].items()},
        "domestic": {k: round(v, 2) for k, v in out["domestic"].items()},
    }


def country_record_weekly_trade_products(world: "World", country: "Country") -> None:
    """주간 품목별 무역액을 이력에 기록."""
    week = int(getattr(world, "week", 0) or 0)
    snap = country_collect_trade_product_values(world, country.id)
    row = {
        "week": week,
        "export": dict(snap.get("export") or {}),
        "import": dict(snap.get("import") or {}),
        "domestic": dict(snap.get("domestic") or {}),
    }
    hist = country_ensure_trade_product_history(country)
    if hist and int(hist[-1].get("week", -1) or -1) == week:
        hist[-1] = row
    else:
        hist.append(row)


def country_trade_product_history_payload(
    world: "World", country_id: str,
) -> List[Dict[str, Any]]:
    """무역 tip 차트용 품목 시계열 (현재 주 스냅샷 포함)."""
    country = (getattr(world, "countries", None) or {}).get(country_id)
    if country is None:
        return []
    week = int(getattr(world, "week", 0) or 0)
    hist = [dict(r) for r in country_ensure_trade_product_history(country)]
    live = country_collect_trade_product_values(world, country_id)
    live_row = {
        "week": week,
        "export": dict(live.get("export") or {}),
        "import": dict(live.get("import") or {}),
        "domestic": dict(live.get("domestic") or {}),
    }
    if not hist or int(hist[-1].get("week", -1) or -1) != week:
        hist.append(live_row)
    else:
        hist[-1] = live_row
    return hist


def country_macro_charts_payload(
    world: "World", country_id: str, metric: str,
) -> Optional[Dict[str, Any]]:
    """HUD 지표 클릭용 매크로 차트 페이로드."""
    country = world.countries.get(country_id)
    if not country:
        return None
    key = (metric or "").strip().lower()
    week = int(getattr(world, "week", 0) or 0)
    charts: List[Dict[str, Any]] = []
    payload_factors: Optional[Dict[str, Any]] = None

    def _money_chart(title: str, values, chart_key: str) -> None:
        vals = [float(x) for x in (values or [])]
        if not vals:
            return
        charts.append({
            "key": chart_key,
            "title": title,
            "kind": "line",
            "unit": "money",
            "line": _weekly_values_to_line(vals, week),
        })

    def _index_chart(title: str, values, chart_key: str) -> None:
        vals = [float(x) for x in (values or [])]
        if not vals:
            return
        charts.append({
            "key": chart_key,
            "title": title,
            "kind": "line",
            "unit": "index",
            "line": _weekly_values_to_line(vals, week),
        })

    def _count_chart(title: str, values, chart_key: str) -> None:
        vals = [float(x) for x in (values or [])]
        if not vals:
            return
        charts.append({
            "key": chart_key,
            "title": title,
            "kind": "line",
            "unit": "count",
            "line": _weekly_values_to_line(vals, week),
        })

    if key in ("population", "pop"):
        hist = list(country_ensure_population_history(country))
        current = sum(
            p.total_population()
            for st in world.states.values() if st.country_id == country_id
            for p in st.pops
        )
        if current > 0 and (not hist or abs(hist[-1] - current) > 1e-9):
            hist = hist + [float(current)]
        _count_chart("인구", hist, "population")
    elif key in ("power", "power_index", "국력", "국력지수"):
        hist_map = getattr(world, "country_power_history", None) or {}
        raw = list(hist_map.get(country_id) or [])
        vals: List[float] = []
        for row in raw:
            try:
                if isinstance(row, (tuple, list)) and len(row) >= 2:
                    vals.append(float(row[1]) * 100.0)
                else:
                    vals.append(float(row) * 100.0)
            except (TypeError, ValueError):
                continue
        current = country_power_index(world, country_id) * 100.0
        if not vals or abs(vals[-1] - current) > 1e-6:
            vals = vals + [current]
        _index_chart("국력", vals, "power")
    elif key in ("gdp", "gdp_nominal", "nominal_gdp"):
        hist = list(country_ensure_gdp_history(country))
        gdp_now = float(country_gdp_breakdown(world, country_id).get("gdp", 0.0) or 0.0)
        if abs(gdp_now) > 1e-12 and (not hist or abs(hist[-1] - gdp_now) > 1e-9):
            hist = hist + [gdp_now]
        sum_hist = series_annual_flow_sum_series(hist)
        _money_chart("명목 GDP (연간)", sum_hist, "gdp")
        payload_factors = country_gdp_factor_history_payload(world, country_id, real=False)
    elif key in ("gdp_real", "real_gdp"):
        hist = list(country_ensure_gdp_history(country))
        gdp_now = float(country_gdp_breakdown(world, country_id).get("gdp", 0.0) or 0.0)
        if abs(gdp_now) > 1e-12 and (not hist or abs(hist[-1] - gdp_now) > 1e-9):
            hist = hist + [gdp_now]
        real_hist = country_real_gdp_series(world, country_id, hist)
        sum_hist = series_annual_flow_sum_series(real_hist)
        _money_chart("실질 GDP (연간)", sum_hist, "gdp_real")
        payload_factors = country_gdp_factor_history_payload(world, country_id, real=True)
    elif key in ("m2", "money_supply", "통화량"):
        payload_factors = country_m2_factor_history_payload(world, country_id)
        hist_rows = list(payload_factors.get("history") or [])
        line = [
            {
                "time": int(r.get("week") or 0),
                "value": round(float(r.get("total") or 0.0), 4),
            }
            for r in hist_rows
            if int(r.get("week") or 0) > 0
        ]
        if line:
            if len(line) == 1:
                line = [dict(line[0]), dict(line[0])]
            charts.append({
                "key": "m2",
                "title": "통화량",
                "kind": "line",
                "unit": "money",
                "line": line,
            })
    elif key in ("unemployment", "unemp", "실업"):
        hist = list(country_ensure_unemployment_history(country))
        unemp_now = country_unemployment_rate_pct(world, country_id)
        if not hist or abs(hist[-1] - unemp_now) > 1e-9:
            hist = hist + [float(unemp_now)]
        if hist:
            charts.append({
                "key": "unemployment",
                "title": "실업률",
                "kind": "line",
                "unit": "rate",
                "ylabel": "실업률",
                "line": _weekly_values_to_line(hist, week),
            })
    elif key in ("treasury", "fiscal", "gov"):
        t_hist = list(country_ensure_treasury_history(country))
        treasury_now = float(getattr(country, "treasury", 0.0) or 0.0)
        if not t_hist or abs(t_hist[-1] - treasury_now) > 1e-9:
            t_hist = t_hist + [treasury_now]
        _money_chart("국고", t_hist, "treasury")
        f_hist = list(country_ensure_fiscal_balance_history(country))
        net_now = (
            float(getattr(country, "weekly_tax_revenue", 0.0) or 0.0)
            - float(getattr(country, "weekly_subsidy_paid", 0.0) or 0.0)
        )
        if not f_hist or abs(f_hist[-1] - net_now) > 1e-9:
            f_hist = f_hist + [net_now]
        _money_chart("재정 수지", f_hist, "fiscal_balance")
    elif key in ("inflation", "infl", "cpi"):
        idxs = country_inflation_index_series(world, country_id)
        cpi = country_consumer_cpi_series(world, country_id)
        # 2열 레이아웃: 왼쪽 3 + 오른쪽 3 (grid-auto-flow: column)
        _index_chart("물가 지수", idxs.get("composite") or [], "inflation")
        _index_chart("상품 지수", idxs.get("goods") or [], "goods")
        _index_chart("부동산 지수", idxs.get("real_estate") or [], "real_estate")
        _index_chart("소매(소비) 물가", cpi.get("index") or [], "cpi")
        _index_chart("산업 물가", idxs.get("industrial") or [], "industrial")
        _index_chart("원자재(광물, 원유 등) 물가", idxs.get("commodity") or [], "commodity")
    elif key in ("fx", "exchange", "환율"):
        _index_chart("환율 지수", country_fx_index_series(world, country_id), "fx")
    elif key in ("rate", "base_rate", "기준금리"):
        hist = [float(r) for r in (getattr(country, "weekly_base_rate_history", None) or [])]
        current = float(getattr(country, "base_rate", 0.0) or 0.0)
        if current > 0 and (not hist or abs(hist[-1] - current) > 1e-9):
            hist = hist + [current]
        if hist:
            charts.append({
                "key": "base_rate",
                "title": "기준금리",
                "kind": "line",
                "unit": "rate",
                "ylabel": "금리",
                "line": _weekly_values_to_line(hist, week),
            })
    elif key in ("shock", "financial_shock", "금융충격"):
        hist = [
            float(v) for v in (getattr(country, "weekly_financial_shock_history", None) or [])
        ]
        current = country_financial_shock_index(country)
        if not hist or abs(hist[-1] - current) > 1e-9:
            hist = hist + [current]
        if hist:
            charts.append({
                "key": "financial_shock",
                "title": "금융충격지수",
                "kind": "line",
                "unit": "index",
                "ylabel": "충격",
                "line": _weekly_values_to_line(hist, week),
            })
        comps_now = dict(getattr(country, "financial_shock_components", None) or {})
        raw_hist = list(getattr(country, "weekly_financial_shock_components_history", None) or [])
        if not raw_hist or any(
            abs(float((raw_hist[-1] or {}).get(k, 0.0) or 0.0) - float(comps_now.get(k, 0.0) or 0.0)) > 1e-6
            for k, _lab, _col in FIN_SHOCK_FACTORS
        ):
            raw_hist = list(raw_hist) + [dict(comps_now)]
        n = len(raw_hist)
        history: List[Dict[str, Any]] = []
        for i, row in enumerate(raw_hist):
            item: Dict[str, Any] = {"week": week - (n - 1 - i)}
            total = 0.0
            for k, _lab, _col in FIN_SHOCK_FACTORS:
                v = float((row or {}).get(k, 0.0) or 0.0)
                item[k] = round(v, 3)
                total += v
            item["total"] = round(total, 3)
            history.append(item)
        last = history[-1] if history else {}
        payload_factors = {
            "label": "충격 구성",
            "keys": [
                {
                    "key": k,
                    "label": lab,
                    "color": col,
                    "value": round(float(last.get(k, 0.0) or 0.0), 3),
                }
                for k, lab, col in FIN_SHOCK_FACTORS
            ],
            "history": history,
            "reasons": fin_shock_display_reasons(world, country),
        }
    else:
        return None

    if not charts:
        return {
            "metric": key,
            "country_id": country_id,
            "title": country.name,
            "start_year": world_start_year(world),
            "charts": [],
            "factors": payload_factors,
        }
    start_year = world_start_year(world)
    for ch in charts:
        ch["start_year"] = start_year
    return {
        "metric": key,
        "country_id": country_id,
        "title": country.name,
        "start_year": start_year,
        "charts": charts,
        "factors": payload_factors,
    }


def country_base_rate_yoy_pp(world: "World", country_id: str) -> Optional[float]:
    country = world.countries.get(country_id)
    if not country:
        return None
    values = [
        float(r) for r in (getattr(country, "weekly_base_rate_history", None) or [])
        if float(r) > 0
    ]
    current = float(getattr(country, "base_rate", 0.0) or 0.0)
    if current > 0 and (not values or abs(values[-1] - current) > 1e-9):
        values = values + [current]
    d = series_yoy_delta(values)
    return round(d, 2) if d is not None else None


def week_to_calendar_date(week: int, start_year: int = 1960):
    """주차 → 달력 날짜 (시작연도 1월 1일, 1주=7일)."""
    from datetime import date, timedelta
    y = int(start_year or 1960)
    w = max(0, int(week or 0))
    return date(y, 1, 1) + timedelta(weeks=w)


def week_to_date_label(week: int, start_year: int = 1960, *, style: str = "short") -> str:
    """차트·패널용 날짜 문자열. short=1960.1.15, long=1960년 1월 15일."""
    current = week_to_calendar_date(week, start_year)
    if style == "long":
        return f"{current.year}년 {current.month}월 {current.day}일"
    return f"{current.year}.{current.month}.{current.day}"


def world_start_year(world: Optional["World"]) -> int:
    if world is None:
        return 1960
    return int(getattr(world, "start_year", 1960) or 1960)


def world_calendar_date(world: "World") -> Dict[str, Any]:
    """월드 주차 → 달력 날짜 (시작 1960-01-01, 1주=7일)."""
    start_year = world_start_year(world)
    week = max(0, int(getattr(world, "week", 0) or 0))
    cached = getattr(world, "_cache_calendar_date", None)
    if isinstance(cached, tuple) and len(cached) == 2 and cached[0] == week:
        return cached[1]
    current = week_to_calendar_date(week, start_year)
    result = {
        "year": current.year,
        "month": current.month,
        "day": current.day,
        "label": week_to_date_label(week, start_year, style="long"),
        "iso": current.isoformat(),
    }
    world._cache_calendar_date = (week, result)
    return result


def world_calendar_year(world: Optional["World"]) -> int:
    if world is None:
        return 1960
    return int(world_calendar_date(world).get("year", 1960) or 1960)


def pop_cohort_year_start(year: int) -> int:
    y = int(year)
    return (y // POP_COHORT_YEARS) * POP_COHORT_YEARS


def pop_cohort_id(state_id: str, birth_year_start: int) -> str:
    return f"{state_id}_c{int(birth_year_start)}"


def pop_normalize_edu_shares(shares: Optional[Dict[str, float]] = None) -> Dict[str, float]:
    raw = {q: max(0.0, float((shares or {}).get(q, 0.0) or 0.0)) for q in POP_QUALIFICATION_ORDER}
    tot = sum(raw.values())
    if tot <= 1e-12:
        return {"미교육": 1.0 / 3.0, "기본교육": 1.0 / 3.0, "고등교육": 1.0 / 3.0}
    return {q: raw[q] / tot for q in POP_QUALIFICATION_ORDER}


def pop_default_edu_shares_for_age(mean_age: float) -> Dict[str, float]:
    age = max(0.0, float(mean_age))
    for lim, triple in POP_COHORT_EDU_BY_AGE:
        if age <= lim:
            a, b, c = triple
            return pop_normalize_edu_shares({"미교육": a, "기본교육": b, "고등교육": c})
    a, b, c = POP_COHORT_EDU_BY_AGE[-1][1]
    return pop_normalize_edu_shares({"미교육": a, "기본교육": b, "고등교육": c})


def pop_mean_age(pop: "POP", world: Optional["World"] = None) -> float:
    bys = int(getattr(pop, "birth_year_start", 1950) or 1950)
    mid = bys + (POP_COHORT_YEARS - 1) * 0.5
    year = world_calendar_year(world) if world is not None else bys + 40
    return max(0.0, float(year) - mid)


def pop_age_behavior_profile(mean_age: float) -> Dict[str, float]:
    """연령별 소비·투자 성향 프로파일."""
    age = clamp(float(mean_age), 0.0, 100.0)
    # 교육 욕구 가중
    if age < POP_YOUTH_AGE_MAX:
        edu_w, medical_w, housing_w = 2.2, 0.7, 0.8
        mpc, invest_risk, deposit_bias, invest_scale = 0.92, 0.05, 0.85, 0.0
    elif age < 35.0:
        edu_w, medical_w, housing_w = 0.5, 0.85, 1.35
        mpc, invest_risk, deposit_bias, invest_scale = 0.78, 1.25, 0.35, 1.0
    elif age < 55.0:
        edu_w, medical_w, housing_w = 0.85, 1.0, 1.15
        mpc, invest_risk, deposit_bias, invest_scale = 0.72, 1.0, 0.45, 1.0
    elif age < POP_RETIRE_AGE:
        edu_w, medical_w, housing_w = 0.35, 1.35, 1.05
        mpc, invest_risk, deposit_bias, invest_scale = 0.68, 0.7, 0.65, 0.9
    else:
        edu_w, medical_w, housing_w = 0.15, 1.7, 1.2
        mpc, invest_risk, deposit_bias, invest_scale = 0.65, 0.35, 0.85, 0.55
    return {
        "edu_weight": edu_w,
        "medical_weight": medical_w,
        "housing_weight": housing_w,
        "mpc": mpc,
        "invest_risk": invest_risk,
        "deposit_bias": deposit_bias,
        "invest_scale": invest_scale,
    }


# 워밍업 후·시드 자산 배분: 나이대별 보유 성향 (10대 주식·부동산 대량 보유 방지)
# 부동산은 고령층 비중↑ (주식은 청장년 피크)
POP_ASSET_SEED_WEIGHT = {
    # (age_hi, stock, housing, multi_family, mixed_use)
    20.0: (0.00, 0.00, 0.00, 0.00),   # 아동·청소년
    30.0: (0.40, 0.08, 0.15, 0.05),   # 20대 — 부동산 거의 없음
    40.0: (1.00, 0.45, 0.55, 0.30),   # 30대 — 매입 시작
    55.0: (1.00, 0.90, 0.95, 0.75),   # 40–50대
    65.0: (0.55, 1.15, 1.10, 1.00),   # 은퇴 전 — 부동산 피크 진입
    200.0: (0.20, 1.35, 1.25, 1.20),  # 고령 — 부동산 최대 보유
}


def pop_asset_seed_weight(mean_age: float, kind: str = "stock") -> float:
    """나이대별 주식·부동산 시드/재배분 가중 (0=보유 안 함)."""
    age = max(0.0, float(mean_age))
    kind_key = {
        "stock": 0,
        "re": 1,
        "housing": 1,
        "multi_family": 2,
        "mixed_use": 3,
    }.get(kind, 0)
    for age_hi, weights in POP_ASSET_SEED_WEIGHT.items():
        if age < age_hi:
            return float(weights[kind_key])
    return float(list(POP_ASSET_SEED_WEIGHT.values())[-1][kind_key])


def pop_ownership_seed_weights(
    world: "World", pops: List["POP"], kind: str = "stock",
) -> List[float]:
    """인구 × 나이대 성향 가중. 전 코호트 가중 0이면 성인 인구 비중으로 폴백."""
    weights: List[float] = []
    for pop in pops:
        age = pop_mean_age(pop, world)
        size = max(0.0, float(pop.total_population() or 0.0))
        weights.append(max(0.0, pop_asset_seed_weight(age, kind) * size))
    if sum(weights) > 1e-12:
        return weights
    fallback: List[float] = []
    for pop in pops:
        age = pop_mean_age(pop, world)
        size = max(0.0, float(pop.total_population() or 0.0))
        if age < POP_YOUTH_AGE_MAX:
            fallback.append(0.0)
        else:
            fallback.append(size)
    if sum(fallback) > 1e-12:
        return fallback
    return [max(1.0, float(getattr(p, "size", 1) or 1)) for p in pops]


def pop_labor_age_score(age: float) -> float:
    return clamp((float(age) - POP_YOUTH_AGE_MAX) / max(POP_RETIRE_AGE - POP_YOUTH_AGE_MAX, 1e-9), 0.0, 1.0)


def pop_edu_shares_weighted_modifier(shares: Dict[str, float]) -> float:
    """edu_shares 가중 출산 보정(구간의 중점)."""
    s = pop_normalize_edu_shares(shares)
    total = 0.0
    for q, w in s.items():
        lo, hi = EDU_BIRTH_MODIFIER.get(q, (0.0, 0.0))
        total += w * (lo + hi) * 0.5
    return total


def country_edu_adult_shares(country_id: str) -> Dict[str, float]:
    """국가 성인 학력 구성. 프리셋이 없으면 사회기술 시작 레벨로 근사."""
    raw = COUNTRY_EDU_ADULT_SHARES.get(str(country_id or ""))
    if raw is None:
        tech = float(country_initial_social_tech_level(country_id or ""))
        t = clamp(tech / 5.0, 0.0, 1.0)
        une = 0.62 * (1.0 - t) + 0.10 * t
        high = 0.05 * (1.0 - t) + 0.36 * t
        raw = (une, max(0.0, 1.0 - une - high), high)
    a, b, c = raw
    return pop_normalize_edu_shares({"미교육": a, "기본교육": b, "고등교육": c})


def country_pop_seed_sol(country_id: str) -> float:
    tech = float(country_initial_social_tech_level(country_id or ""))
    return clamp(2.6 + tech * 0.90, 1.5, 9.0)


def country_pop_seed_health(country_id: str) -> float:
    tech = float(country_initial_social_tech_level(country_id or ""))
    return clamp(0.30 + tech * 0.12, 0.20, 0.95)


def pop_edu_shares_for_country_age(country_id: str, mean_age: float) -> Dict[str, float]:
    """국가 성인 학력을 연령으로 보정. 젊을수록 고학력, 고령일수록 미교육."""
    shares = dict(country_edu_adult_shares(country_id))
    shift = clamp((float(mean_age) - 40.0) / 80.0, -0.45, 0.50)
    if shift >= 0.0:
        take_h = shares.get("고등교육", 0.0) * shift * 0.70
        take_b = shares.get("기본교육", 0.0) * shift * 0.35
        shares["고등교육"] = shares.get("고등교육", 0.0) - take_h
        shares["기본교육"] = shares.get("기본교육", 0.0) - take_b
        shares["미교육"] = shares.get("미교육", 0.0) + take_h + take_b
    else:
        give = shares.get("미교육", 0.0) * (-shift) * 0.85
        shares["미교육"] = shares.get("미교육", 0.0) - give
        shares["기본교육"] = shares.get("기본교육", 0.0) + give * 0.40
        shares["고등교육"] = shares.get("고등교육", 0.0) + give * 0.60
    return pop_normalize_edu_shares(shares)


def simulate_country_cohort_pyramid(
    country_id: str, cal_year: int, sol: float, health: float,
) -> Dict[int, float]:
    """출생·사망 로직으로 연간 시뮬한 코호트 인구. {birth_year_start: size}."""
    cid = str(country_id or "")
    year0 = int(cal_year)
    key = (cid, year0, int(round(float(sol) * 100)), int(round(float(health) * 100)))
    cached = _POP_COHORT_PYRAMID_CACHE.get(key)
    if cached is not None:
        return dict(cached)
    sim_start = year0 - POP_SIM_HISTORY_YEARS
    cohorts: Dict[int, float] = {}
    for band in range(0, 10):
        mean_age = band * 10 + 5.0
        bys = pop_cohort_year_start(int(round(sim_start - mean_age)))
        cohorts[bys] = cohorts.get(bys, 0.0) + 1.0
    for year in range(sim_start, year0):
        births = 0.0
        nxt: Dict[int, float] = {}
        for bys, n in cohorts.items():
            if n <= 1e-12:
                continue
            age = max(0.0, float(year) - (bys + (POP_COHORT_YEARS - 1) * 0.5))
            if age > POP_SIM_MAX_MEAN_AGE:
                continue
            dr_w = pop_age_weekly_death_rate(age, sol, health)
            keep = (1.0 - clamp(dr_w, 0.0, 0.5)) ** 52
            n2 = n * keep
            if n2 > 1e-12:
                nxt[bys] = n2
            if POP_FERTILE_AGE_MIN <= age <= POP_FERTILE_AGE_MAX:
                edu = pop_edu_shares_for_country_age(cid, age)
                births += n * pop_weekly_birth_rate(sol, edu, health) * 52.0
        if births > 1e-12:
            child_bys = pop_cohort_year_start(year)
            nxt[child_bys] = nxt.get(child_bys, 0.0) + births
        cohorts = nxt
    _POP_COHORT_PYRAMID_CACHE[key] = dict(cohorts)
    return dict(cohorts)


def _match_orders_age_weighted(
    market_buy: List[BuyOrder],
    market_sell: List[SellOrder],
    transaction_qty: float,
    *,
    beta: float = POP_LABOR_AGE_BETA,
) -> Tuple[List[SellResult], List[BuyResult], Dict[int, float]]:
    """노동용: 연령가중 비례 매칭 (절대 연령 우선 정렬 아님)."""
    if transaction_qty <= 1e-9:
        return [], [], {}
    weights: List[float] = []
    for so in market_sell:
        age = float(getattr(so, "seller_age", 0.0) or 0.0)
        if age <= 1e-9:
            age = 40.0
        w = (1.0 + beta * pop_labor_age_score(age)) * max(0.0, float(so.quantity))
        weights.append(max(w, 1e-12))
    w_sum = sum(weights)
    sell_results: List[SellResult] = []
    tech_sold: Dict[int, float] = defaultdict(float)
    if w_sum <= 1e-12:
        return [], [], {}
    for so, w in zip(market_sell, weights):
        alloc = transaction_qty * (w / w_sum)
        sold = min(float(so.quantity), alloc)
        res = SellResult(
            so.seller_id,
            is_foreign=getattr(so, "is_foreign", False),
            is_treasury_issue=getattr(so, "is_treasury_issue", False),
        )
        res.sold_quantity = sold
        res.tech_level = so.tech_level
        sell_results.append(res)
        tech_sold[int(so.tech_level)] += sold
    # 반올림 잔여 보정
    sold_total = sum(r.sold_quantity for r in sell_results)
    if sold_total > 1e-9 and abs(sold_total - transaction_qty) > 1e-6:
        scale = transaction_qty / sold_total
        for r in sell_results:
            r.sold_quantity *= scale
        for t in list(tech_sold.keys()):
            tech_sold[t] *= scale
    total_demand = sum(o.quantity for o in market_buy)
    buyer_fill_ratio = transaction_qty / total_demand if total_demand > 0 else 0.0
    tech_mix = {
        t: q / transaction_qty for t, q in tech_sold.items()
    } if transaction_qty > 0 else {}
    buy_results = []
    for bo in market_buy:
        res = BuyResult(bo.buyer_id, allow_loan=getattr(bo, "allow_loan", False))
        my_qty = bo.quantity * buyer_fill_ratio
        res.filled_quantity = my_qty
        for tech, ratio in tech_mix.items():
            res.received_items[tech] = my_qty * ratio
        buy_results.append(res)
    return sell_results, buy_results, tech_mix


def country_avg_weekly_gdp(world: "World", country_id: str) -> float:
    """13주 평균 주간 GDP. 이력 없으면 당주 GDP."""
    country = world.countries.get(country_id)
    if not country:
        return 0.0
    hist = list(country_ensure_gdp_history(country))
    if hist:
        window = hist[-13:] if len(hist) > 13 else hist
        return float(sum(window) / len(window))
    cache = getattr(world, "_fin_cache_country_gdp", None)
    if cache is not None and country_id in cache:
        return float(cache[country_id])
    gdp = float(country_gdp_breakdown(world, country_id).get("gdp", 0.0) or 0.0)
    if cache is not None:
        cache[country_id] = gdp
    return gdp


def country_annual_gdp(
    world: "World",
    country_id: str,
    *,
    include_current: bool = True,
) -> float:
    """연간 명목 GDP = 최근 52주 주간 GDP 합(짧은 이력은 연율 환산)."""
    country = world.countries.get(country_id)
    if not country:
        return 0.0
    hist = list(country_ensure_gdp_history(country))
    if include_current:
        try:
            gdp_now = float(country_gdp_breakdown(world, country_id).get("gdp", 0.0) or 0.0)
        except Exception:
            gdp_now = 0.0
        if abs(gdp_now) > 1e-12 and (
            not hist or abs(hist[-1] - gdp_now) > 1e-9
        ):
            hist = hist + [gdp_now]
    annual = series_annual_flow_sum(hist)
    if annual is not None:
        return float(annual)
    return float(country_avg_weekly_gdp(world, country_id) * float(GDP_YOY_YEAR_WEEKS))


def country_gov_bond_issue_amount(
    world: "World",
    country: "Country",
    *,
    mode: str,
    amount: float = 0.0,
    gdp_ratio_pct: float = 0.0,
) -> float:
    """국채 1회 발행 액면 산출 (액면 고정 또는 연간 GDP 비율)."""
    if mode == "gdp_ratio":
        annual_gdp = country_annual_gdp(world, country.id)
        return max(0.0, annual_gdp * (float(gdp_ratio_pct or 0.0) / 100.0))
    return max(0.0, float(amount or 0.0))


def country_schedule_gov_bond_issue(country: "Country", amount: float, underwrite: str = "market") -> None:
    amt = float(amount or 0.0)
    if amt <= 1e-9:
        return
    country.gov_bond_pending_issue = float(getattr(country, "gov_bond_pending_issue", 0.0) or 0.0) + amt
    if underwrite == "cb":
        country.gov_bond_cb_purchase_remaining = (
            float(getattr(country, "gov_bond_cb_purchase_remaining", 0.0) or 0.0) + amt
        )


def country_rescue_treasury_via_cb_bond_purchase(world: "World", country: "Country") -> float:
    """국고가 음수면 부족분만큼 국채를 즉시 발행하고 중앙은행이 전량 매입해 보전.

    CB는 통상 채권 매수 시 현금을 차감하지 않으므로(본원통화 창설) 국고만 회복된다.
    대금은 결제가(변동금리채는 액면)라 발행 액면은 부족분 / 단가이다.
    Returns:
        국고에 보전된 금액.
    """
    gap = -float(getattr(country, "treasury", 0.0) or 0.0)
    if gap <= 1e-9:
        return 0.0
    cb = world.get_central_bank(country.id) if hasattr(world, "get_central_bank") else None
    if cb is None:
        cb = (getattr(world, "central_banks", {}) or {}).get(country.id)
    if cb is None:
        return 0.0
    gov_key = f"gov_{country.id}"
    bm = (getattr(world, "bond_markets", {}) or {}).get(gov_key)
    if bm is None and hasattr(world, "_ensure_bond_market"):
        bm = world._ensure_bond_market(gov_key)
    rate = float(getattr(bm, "current_interest_rate", 0.0) or 0.0) if bm is not None else 0.0
    if rate <= 1e-12:
        rate = country_base_rate(country)
    unit = float(bond_discount_price(1.0, rate))
    if unit <= 1e-12:
        return 0.0
    face = gap / unit
    proceeds = float(bond_discount_price(face, rate))
    if proceeds <= 1e-9:
        return 0.0
    country.treasury = float(getattr(country, "treasury", 0.0) or 0.0) + proceeds
    country.gov_bond_balance = float(getattr(country, "gov_bond_balance", 0.0) or 0.0) + face
    country.gov_bond_sold_cumulative = (
        float(getattr(country, "gov_bond_sold_cumulative", 0.0) or 0.0) + face)
    port = getattr(cb, "bond_portfolio", None)
    if port is None:
        cb.bond_portfolio = defaultdict(float)
        port = cb.bond_portfolio
    port[gov_key] = float(port.get(gov_key, 0.0) or 0.0) + face
    return proceeds


def country_fund_deficit_via_bank_loans(world: "World", country: "Country") -> float:
    """국고 음수를 자국 시중은행 여력(현금·자본)만큼 대출로 메운다."""
    gap = max(0.0, -float(getattr(country, "treasury", 0.0) or 0.0))
    if gap <= 1e-9:
        return 0.0
    banks = world.banks_in_country(country.id) if hasattr(world, "banks_in_country") else []
    if not banks:
        return 0.0
    caps = [(b, bank_loan_capacity(b, world)) for b in banks]
    total_cap = sum(cap for _, cap in caps)
    if total_cap <= 1e-9:
        return 0.0
    alloc = getattr(country, "gov_bank_loan_alloc", None)
    if not isinstance(alloc, dict):
        country.gov_bank_loan_alloc = {}
        alloc = country.gov_bank_loan_alloc
    funded = 0.0
    for bank, cap in caps:
        if funded >= gap - 1e-9:
            break
        take = min(cap, gap * (cap / total_cap), gap - funded)
        take = min(take, bank_loan_capacity(bank, world))
        if take <= 1e-9:
            continue
        bank.loans += take
        bank.loans_by_currency[bank.country_id] = (
            bank.loans_by_currency.get(bank.country_id, 0.0) + take)
        bank.cash -= take
        bank_consume_loan_capacity(bank, take, world)
        alloc[bank.id] = float(alloc.get(bank.id, 0.0) or 0.0) + take
        funded += take
    if funded <= 1e-9:
        return 0.0
    country.treasury = float(getattr(country, "treasury", 0.0) or 0.0) + funded
    country.gov_bank_loan = float(getattr(country, "gov_bank_loan", 0.0) or 0.0) + funded
    return funded


def country_accrue_gov_bank_loan_interest(world: "World") -> None:
    """국가 은행대출 주간 이자. 국고가 부족하면 미지급분은 잔액에 가산."""
    for country in (getattr(world, "countries", {}) or {}).values():
        alloc = getattr(country, "gov_bank_loan_alloc", None)
        if not isinstance(alloc, dict):
            continue
        for bid, bal in list(alloc.items()):
            bal = float(bal or 0.0)
            bank = (getattr(world, "banks", {}) or {}).get(bid)
            if bank is None or bal <= 1e-9:
                continue
            rate = float(getattr(bank, "loan_rate", 0.0) or 0.0)
            interest = bal * (rate / 100.0 / 52.0)
            if interest <= 1e-12:
                continue
            cash_pay = min(max(0.0, float(getattr(country, "treasury", 0.0) or 0.0)), interest)
            if cash_pay > 1e-9:
                country.treasury -= cash_pay
                bank.cash += cash_pay
            unpaid = interest - cash_pay
            if unpaid > 1e-9:
                alloc[bid] = bal + unpaid
                country.gov_bank_loan = (
                    float(getattr(country, "gov_bank_loan", 0.0) or 0.0) + unpaid)
                bank.loans += unpaid
                bank.loans_by_currency[bank.country_id] = (
                    bank.loans_by_currency.get(bank.country_id, 0.0) + unpaid)
            bank.net_income = float(getattr(bank, "net_income", 0.0) or 0.0) + interest
            bank.weekly_loan_interest_income = (
                float(getattr(bank, "weekly_loan_interest_income", 0.0) or 0.0) + interest)


def world_rescue_all_negative_treasuries(world: "World") -> float:
    """국고 음수는 시중은행 대출이 기본, 미소화분만 CB 국채 매입."""
    total = 0.0
    for country in (getattr(world, "countries", {}) or {}).values():
        total += country_fund_deficit_via_bank_loans(world, country)
        total += country_rescue_treasury_via_cb_bond_purchase(world, country)
    return total


def company_gov_ownership_share(world: "World", company_id: str, country_id: str) -> float:
    """중앙정부 보유 지분 비율 (0~1)."""
    country = world.countries.get(country_id)
    if not country:
        return 0.0
    held = float(country.stock_holdings.get(company_id, 0.0) or 0.0)
    return stock_ownership_share(world, company_id, held)


def company_is_nationalized(company: Any) -> bool:
    return bool(getattr(company, "is_nationalized", False))


def _nationalization_decay_multiplier(
    weeks: int, floor: float, half_life_weeks: float,
) -> float:
    """국유화 경과 주수에 따른 지수 감쇠 배율 (1 → floor)."""
    fl = clamp(float(floor), 0.0, 1.0)
    t = max(0, int(weeks or 0))
    hl = max(1e-9, float(half_life_weeks or 1.0))
    return fl + (1.0 - fl) * (0.5 ** (t / hl))


def company_nationalization_tech_multiplier(company: Any) -> float:
    """국유 기업 기술 개발 배율 — 시간이 지날수록 느려진다."""
    if not company_is_nationalized(company):
        return 1.0
    return _nationalization_decay_multiplier(
        int(getattr(company, "nationalized_weeks", 0) or 0),
        NATIONALIZATION_TECH_FLOOR,
        NATIONALIZATION_TECH_HALF_LIFE_WEEKS,
    )


def company_nationalization_efficiency_multiplier(company: Any) -> float:
    """국유 기업 시설 효율 배율 — 시간이 지날수록 감소한다."""
    if not company_is_nationalized(company):
        return 1.0
    return _nationalization_decay_multiplier(
        int(getattr(company, "nationalized_weeks", 0) or 0),
        NATIONALIZATION_EFF_FLOOR,
        NATIONALIZATION_EFF_HALF_LIFE_WEEKS,
    )


def company_can_nationalize(
    world: "World", company: "Company", country_id: str,
) -> bool:
    """본사국 중앙정부가 과반 지분을 보유하면 국유화 가능."""
    if not company or not country_id:
        return False
    home = company_home_country_id(company, getattr(world, "states", None))
    if home != country_id:
        return False
    share = company_gov_ownership_share(world, company.id, country_id)
    return share + 1e-12 >= NATIONALIZATION_OWNERSHIP_THRESHOLD


def set_company_nationalized(company: "Company", enabled: bool) -> bool:
    """국유화 on/off. 켜면 AI 정지·채권/건설 자유, 끄면 페널티 카운터 리셋."""
    on = bool(enabled)
    company.is_nationalized = on
    if on:
        company.nationalized_weeks = int(
            getattr(company, "nationalized_weeks", 0) or 0)
    else:
        company.nationalized_weeks = 0
    return on


def tick_nationalized_company_penalties(world: "World") -> None:
    """국유 기업 경과 주수를 누적한다 (기술·효율 감쇠용)."""
    for co in (getattr(world, "companies", None) or {}).values():
        if company_is_nationalized(co):
            co.nationalized_weeks = int(
                getattr(co, "nationalized_weeks", 0) or 0) + 1


def company_schedule_bond_issue(
    company: "Company",
    amount: float,
    underwrite: str = "market",
    world: Optional["World"] = None,
) -> None:
    """회사채 발행 예약. underwrite=gov 이면 중앙정부 매입 잔여에 가산."""
    if not company_can_issue_bonds(company):
        return
    amt = float(amount or 0.0)
    if amt <= 1e-9:
        return
    w = world if world is not None else getattr(company, "_world_ref", None)
    append_pending_bond_sell(company, amt, w, kind="corp")
    if underwrite == "gov":
        company.corp_bond_gov_purchase_remaining = (
            float(getattr(company, "corp_bond_gov_purchase_remaining", 0.0) or 0.0) + amt
        )


def world_financial_bond_issuer(world: "World", market_key_id: str) -> Any:
    """은행·금투 채권 발행자. 없으면 None."""
    bank = (getattr(world, "banks", None) or {}).get(market_key_id)
    if bank is not None:
        return bank
    return (getattr(world, "investment_banks", None) or {}).get(market_key_id)


def financial_issued_bond_outstanding(fin: Any) -> float:
    """은행·금투 발행 잔액 + 미매각 + 대기 발행."""
    unsold = max(
        0.0,
        float(getattr(fin, "current_bond_issue", 0.0) or 0.0)
        - float(getattr(fin, "bond_sold_for_construction", 0.0) or 0.0),
    )
    pending = float(getattr(fin, "pending_bond_sell", 0.0) or 0.0)
    return max(
        0.0,
        float(getattr(fin, "bond_balance", 0.0) or 0.0) + unsold + pending,
    )


def financial_schedule_bond_issue(
    fin: Any,
    amount: float,
    world: Optional["World"] = None,
) -> None:
    """은행채·금투채 발행 예약."""
    w = world if world is not None else getattr(fin, "_world_ref", None)
    append_pending_bond_sell(fin, amount, w, kind="corp")


def init_financial_funding_fields(entity: Any, *, reset: bool = False) -> None:
    """은행·금투 유상증자·금융채 발행 필드."""
    if reset:
        entity.bond_balance = 0.0
        entity.pending_bond_sell = 0.0
        entity.current_bond_issue = 0.0
        entity.bond_sold_for_construction = 0.0
        entity.bond_sold_ratio = 1.0
        entity.bond_issue_lot_queue = []
        entity.bond_principal_lots = []
        entity.seasoned_weeks_left = 0
        entity.seasoned_target = 0.0
        entity.seasoned_raised = 0.0
        entity.seasoned_share_price = 0.0
        entity.seasoned_cooldown_weeks = 0
        entity.offer_breach_weeks = 0
        entity.liq_breach_weeks = 0
        entity._unwound_mm_borrow = 0.0
        entity._last_week_liq_need = 0.0
        entity._last_week_liq_asset_sale = False
        entity._liq_asset_sale_this_week = False
        entity.weekly_issued_bond_interest_expense = 0.0
        entity.last_week_issued_bond_interest_expense = 0.0
        return
    entity.bond_balance = float(getattr(entity, "bond_balance", 0.0) or 0.0)
    entity.pending_bond_sell = float(getattr(entity, "pending_bond_sell", 0.0) or 0.0)
    entity.current_bond_issue = float(getattr(entity, "current_bond_issue", 0.0) or 0.0)
    entity.bond_sold_for_construction = float(
        getattr(entity, "bond_sold_for_construction", 0.0) or 0.0)
    entity.bond_sold_ratio = float(getattr(entity, "bond_sold_ratio", 1.0) or 1.0)
    if getattr(entity, "bond_issue_lot_queue", None) is None:
        entity.bond_issue_lot_queue = []
    if getattr(entity, "bond_principal_lots", None) is None:
        entity.bond_principal_lots = []
    entity.seasoned_weeks_left = int(getattr(entity, "seasoned_weeks_left", 0) or 0)
    entity.seasoned_target = float(getattr(entity, "seasoned_target", 0.0) or 0.0)
    entity.seasoned_raised = float(getattr(entity, "seasoned_raised", 0.0) or 0.0)
    entity.seasoned_share_price = float(getattr(entity, "seasoned_share_price", 0.0) or 0.0)
    entity.seasoned_cooldown_weeks = int(getattr(entity, "seasoned_cooldown_weeks", 0) or 0)
    entity.offer_breach_weeks = int(getattr(entity, "offer_breach_weeks", 0) or 0)
    entity.liq_breach_weeks = int(getattr(entity, "liq_breach_weeks", 0) or 0)
    entity._unwound_mm_borrow = float(getattr(entity, "_unwound_mm_borrow", 0.0) or 0.0)
    entity._last_week_liq_need = float(getattr(entity, "_last_week_liq_need", 0.0) or 0.0)
    entity._last_week_liq_asset_sale = bool(
        getattr(entity, "_last_week_liq_asset_sale", False))
    entity._liq_asset_sale_this_week = bool(
        getattr(entity, "_liq_asset_sale_this_week", False))
    entity.weekly_issued_bond_interest_expense = float(
        getattr(entity, "weekly_issued_bond_interest_expense", 0.0) or 0.0)
    entity.last_week_issued_bond_interest_expense = float(
        getattr(entity, "last_week_issued_bond_interest_expense", 0.0) or 0.0)


def ib_operating_cash_buffer(ib: Any) -> float:
    """금투 운영현금 바닥 — 콜 차입·환매 긴급분만. 포트폴리오 현금 목표와는 분리."""
    fund = max(0.0, float(getattr(ib, "fund_aum", 0.0) or 0.0))
    return CALL_IB_CASH_BUFFER + fund * IB_ORDER_CASH_BUFFER_RATIO


def ib_portfolio_cash_floor(ib: Any, world: Optional["World"] = None) -> float:
    """워밍업·리포트용 현금 목표 (전체 자산 × WARMUP_IB_CASH_TO_AUM).

    live 주문 세션의 매각 트리거·지출 하한이 아니다. 15%를 floor로 보면
    워밍업 직후 주식을 팔아 현금을 채우려 한다.
    """
    w = clamp(float(WARMUP_IB_CASH_TO_AUM), 0.0, 0.95)
    if world is not None and hasattr(ib, "allocation_aum"):
        aum = max(0.0, float(ib.allocation_aum(world) or 0.0))
    else:
        aum = max(
            0.0,
            float(getattr(ib, "fund_aum", 0.0) or 0.0),
            float(getattr(ib, "last_week_total_aum", 0.0) or 0.0),
        )
    return max(0.0, aum * w)


def ib_undeployable_cash(ib: Any, world: Optional["World"] = None) -> float:
    """주문·공여·예치·부동산에 묶을 현금 — live는 운영버퍼(floor)만.

    AUM 15%는 워밍업·리포트 목표. 워밍업 중에만 지출 하한으로 겹친다.
    """
    op = ib_operating_cash_buffer(ib)
    if world is not None and not getattr(world, "warmup_completed", True):
        return max(op, ib_portfolio_cash_floor(ib, world))
    return op


def financial_liquidity_cash(fin: Any) -> float:
    """지준·운영현금 판정용 가용액. 주초 콜/레포 만기 상환분은 주말 재차입 전까지 포함."""
    cash = float(getattr(fin, "cash", 0.0) or 0.0)
    unwound = float(getattr(fin, "_unwound_mm_borrow", 0.0) or 0.0)
    if isinstance(fin, InvestmentBank):
        cash += float(getattr(fin, "deposits", 0.0) or 0.0)
    return cash + unwound


def finance_actor_liq_aum(world: "World", fin: Any) -> float:
    """유동성 데드밴드·목표 산정용 규모."""
    if isinstance(fin, InvestmentBank):
        if hasattr(fin, "allocation_aum"):
            return max(0.0, float(fin.allocation_aum(world) or 0.0))
        return max(
            0.0,
            float(getattr(fin, "fund_aum", 0.0) or 0.0),
            float(getattr(fin, "last_week_total_aum", 0.0) or 0.0),
        )
    if isinstance(fin, Bank):
        return max(0.0, float(getattr(fin, "deposits", 0.0) or 0.0))
    return 0.0


def finance_liquidity_floor(world: "World", fin: Any) -> float:
    """진짜 하한. 은행=지준+결제버퍼, 금투=운영버퍼+환매/결제버퍼. AUM 15% 아님."""
    if isinstance(fin, Bank):
        dep = max(0.0, float(getattr(fin, "deposits", 0.0) or 0.0))
        return bank_required_cash(fin, world) + dep * BANK_LIQ_SETTLE_BUFFER_RATIO
    if isinstance(fin, InvestmentBank):
        fund = max(0.0, float(getattr(fin, "fund_aum", 0.0) or 0.0))
        return ib_operating_cash_buffer(fin) + fund * IB_LIQ_SETTLE_BUFFER_RATIO
    return 0.0


def finance_liquidity_target(world: "World", fin: Any, floor: float) -> float:
    """평상시 선호 현금. 매각 트리거가 아니다."""
    floor = max(0.0, float(floor or 0.0))
    if isinstance(fin, Bank):
        dep = max(0.0, float(getattr(fin, "deposits", 0.0) or 0.0))
        return floor + dep * BANK_HQLA_EXCESS_DEPOSIT_FLOOR
    if isinstance(fin, InvestmentBank):
        aum = finance_actor_liq_aum(world, fin)
        raw = max(floor * IB_LIQ_FLOOR_TO_TARGET, aum * IB_LIQ_TARGET_AUM)
        cap = aum * IB_MACRO_CASH_CEILING if aum > 1e-9 else raw
        if cap >= floor:
            return min(max(floor, raw), cap)
        return max(floor, raw)
    return floor


def finance_liquidity_inflows(fin: Any) -> float:
    """당주 적립된 매도대금(헤어컷). 기회 매도·긴급매각이 이미 넣은 분."""
    return max(
        0.0,
        float(getattr(fin, "_expected_sell_proceeds_remaining", 0.0) or 0.0),
    )


def finance_liq_deadband(world: "World", fin: Any) -> float:
    aum = finance_actor_liq_aum(world, fin)
    return max(float(FIN_OFFER_MIN_AMOUNT), float(LIQ_GAP_AUM_DEADBAND) * aum)


def finance_liquidity_pack(world: "World", fin: Any) -> Dict[str, Any]:
    """최소현금·목표현금·예상유입·국면을 한 팩으로.

    regime: normal(목표 이상) / warning(목표 미만·floor 근처, 매수 축소)
            / stress(전주에도 floor 미달, 순위 매각).
    """
    cash = financial_liquidity_cash(fin)
    inflows = finance_liquidity_inflows(fin)
    floor = finance_liquidity_floor(world, fin)
    target = max(floor, finance_liquidity_target(world, fin, floor))
    covered = cash + inflows
    net_gap = max(0.0, floor - covered)
    deadband = finance_liq_deadband(world, fin)
    last_short = financial_liq_last_week_short(fin)
    if cash + 1e-12 >= target:
        regime = "normal"
    elif net_gap <= deadband:
        regime = "warning"
    elif last_short and not financial_liq_sold_last_week(fin):
        regime = "stress"
    else:
        regime = "warning"
    return {
        "cash": cash,
        "inflows": inflows,
        "floor": floor,
        "target": target,
        "net_gap": net_gap,
        "deadband": deadband,
        "regime": regime,
        "covered": covered,
    }


def finance_liquidity_report(world: "World", fin: Any) -> Dict[str, Any]:
    """디버그·UI용 floor/target/regime. 목표비중이 아니라 현금 하한·선호·국면."""
    pack = finance_liquidity_pack(world, fin)
    aum = max(finance_actor_liq_aum(world, fin), 1e-9)
    cash = float(pack.get("cash", 0.0) or 0.0)
    floor = float(pack.get("floor", 0.0) or 0.0)
    target = float(pack.get("target", 0.0) or 0.0)
    inflows = float(pack.get("inflows", 0.0) or 0.0)
    net_gap = float(pack.get("net_gap", 0.0) or 0.0)
    deadband = float(pack.get("deadband", 0.0) or 0.0)
    regime = str(pack.get("regime") or "normal")
    return {
        "regime": regime,
        "cash": round(cash, 1),
        "inflows": round(inflows, 1),
        "floor": round(floor, 1),
        "target": round(target, 1),
        "net_gap": round(net_gap, 1),
        "deadband": round(deadband, 1),
        "cash_w": round(100.0 * cash / aum, 1),
        "floor_w": round(100.0 * floor / aum, 1),
        "target_w": round(100.0 * target / aum, 1),
        "inflows_w": round(100.0 * inflows / aum, 1),
    }


def financial_liquidity_need(world: "World", fin: Any) -> float:
    """floor 대비 부족액. 예상 유입을 뺀 net_gap. 데드밴드 안의 미세 갭은 0이 아니다."""
    return float(finance_liquidity_pack(world, fin).get("net_gap", 0.0) or 0.0)


def financial_liq_last_week_short(fin: Any) -> bool:
    need = float(getattr(fin, "_last_week_liq_need", 0.0) or 0.0)
    db = float(getattr(fin, "_last_week_liq_deadband", 0.0) or 0.0)
    if db <= 1e-12:
        db = 1.0
    return need > db


def financial_liq_sold_last_week(fin: Any) -> bool:
    return bool(getattr(fin, "_last_week_liq_asset_sale", False))


def financial_liq_buy_first(world: "World", fin: Any) -> bool:
    """부족 첫 주 — 매각 없이 매수 축소·유입 대기. 전주 부족이면 자산매각 단계."""
    if not getattr(world, "warmup_completed", True):
        return False
    pack = finance_liquidity_pack(world, fin)
    if float(pack.get("net_gap", 0.0) or 0.0) <= float(pack.get("deadband", 0.0) or 0.0):
        return False
    return not financial_liq_last_week_short(fin)


def financial_should_emergency_asset_sale(world: "World", fin: Any) -> bool:
    """전주에도 floor 미달이고, 전주가 자산매각 주가 아닐 때만 증권 매각.

    매각 다음 주는 콜/레포 차입을 먼저 시도한다.
    금투 차입 한도 초과는 2주 대기를 건너뛰고 당주 강제 매각한다.
    """
    if not getattr(world, "warmup_completed", True):
        return False
    if (
        isinstance(fin, InvestmentBank)
        and bool(getattr(fin, "leverage_repair_pending", False))
    ):
        max_loan = investment_bank_max_loan_balance(world, fin)
        if float(getattr(fin, "loan_balance", 0.0) or 0.0) > max_loan + 1e-6:
            return True
    pack = finance_liquidity_pack(world, fin)
    if float(pack.get("net_gap", 0.0) or 0.0) <= float(pack.get("deadband", 0.0) or 0.0):
        return False
    if not financial_liq_last_week_short(fin):
        return False
    if financial_liq_sold_last_week(fin):
        return False
    return True


def financial_skip_mm_lend(world: "World", fin: Any) -> bool:
    """목표현금 미만·긴급매각 전후 주에는 잔여 현금을 콜/레포에 올리지 않는다."""
    if not getattr(world, "warmup_completed", True):
        return False
    pack = finance_liquidity_pack(world, fin)
    if str(pack.get("regime") or "") != "normal":
        return True
    if bool(getattr(fin, "_liq_asset_sale_this_week", False)):
        return True
    if financial_liq_sold_last_week(fin):
        return True
    return False


def financial_cash_deploy_pct(world: "World", fin: Any) -> float:
    """warning은 매수 축소, stress는 신규 매수 0. 부족 첫 주에 매수를 키우지 않는다."""
    pack = finance_liquidity_pack(world, fin)
    regime = str(pack.get("regime") or "normal")
    if regime == "stress":
        return 0.0
    if regime == "warning":
        return min(float(FINANCE_CASH_DEPLOY_PCT), float(FIN_LIQ_WARNING_DEPLOY_PCT))
    return float(FINANCE_CASH_DEPLOY_PCT)


def financial_record_liq_week(world: "World", fin: Any) -> None:
    """주말 콜/레포 이후 부족·자산매각 여부를 다음 주 판단용으로 저장."""
    pack = finance_liquidity_pack(world, fin)
    fin._last_week_liq_need = float(pack.get("net_gap", 0.0) or 0.0)
    fin._last_week_liq_deadband = float(pack.get("deadband", 0.0) or 0.0)
    fin._last_week_liq_asset_sale = bool(
        getattr(fin, "_liq_asset_sale_this_week", False))
    fin._liq_asset_sale_this_week = False


def _financial_bond_holding_maps(fin: Any) -> List[Dict[str, float]]:
    if isinstance(fin, Bank):
        return [
            getattr(fin, "bond_portfolio", None) or {},
            getattr(fin, "foreign_bond_portfolio", None) or {},
        ]
    holdings = getattr(fin, "bond_holdings", None)
    return [holdings] if holdings is not None else []


def _financial_pending_market_sell_qty(market: Any, seller_id: str) -> float:
    if market is None:
        return 0.0
    return sum(
        float(getattr(o, "quantity", 0.0) or 0.0)
        for o in (getattr(market, "sell_orders", None) or [])
        if getattr(o, "seller_id", "") == seller_id
        and not getattr(o, "is_treasury_issue", False)
    )


def financial_sellable_asset_value(world: "World", fin: Any) -> float:
    """미체결 매도를 뺀 보유 증권 시가(자국화)."""
    total = 0.0
    home = str(getattr(fin, "country_id", "") or "")
    actor_id = str(getattr(fin, "id", "") or "")
    for holdings in _financial_bond_holding_maps(fin):
        for key, face in list((holdings or {}).items()):
            held = float(face or 0.0)
            if held <= 1e-9:
                continue
            bm = (getattr(world, "bond_markets", None) or {}).get(key)
            avail = max(0.0, held - _financial_pending_market_sell_qty(bm, actor_id))
            if avail <= 1e-9:
                continue
            rate = float(getattr(bm, "current_interest_rate", 0.0) or 0.0) if bm else 0.0
            mark = bond_discount_price(avail, rate)
            dest = bond_market_country_id(world, key) or home
            if dest and dest != home:
                mark *= fx_home_per_foreign(home, dest, world)
            total += mark
    stock_holdings = getattr(fin, "stock_holdings", None) or {}
    for iid, shares in list(stock_holdings.items()):
        sh = float(shares or 0.0)
        sm = (getattr(world, "stock_markets", None) or {}).get(iid)
        price = float(getattr(sm, "current_price", 0.0) or 0.0) if sm else 0.0
        if sh <= 1e-9 or price <= 1e-9:
            continue
        avail = max(0.0, sh - _financial_pending_market_sell_qty(sm, actor_id))
        if avail <= 1e-9:
            continue
        mark = avail * price
        dest = issuer_stock_country_id(world, iid) or home
        if dest and dest != home:
            mark *= fx_home_per_foreign(home, dest, world)
        total += mark
    return total


def finance_liq_name_edge(world: "World", fin: Any, key: str, kind: str) -> float:
    """매각 순위용 net_edge. 세션 점수가 없으면 기존 스코어 폴백."""
    raw = str(key or "")
    edges = getattr(fin, "_session_name_edges", None) or {}
    if not isinstance(edges, dict):
        edges = {}
    if kind == "stock":
        for cand in (finance_stock_alloc_key(raw), raw):
            if cand in edges:
                try:
                    return float(edges.get(cand, 0.0) or 0.0)
                except (TypeError, ValueError):
                    return 0.0
        if isinstance(fin, InvestmentBank):
            try:
                return float(ib_style_stock_score(world, fin, raw) or 0.0)
            except Exception:
                return 1.0
        return 1.0
    for cand in (finance_bond_alloc_key(raw), raw):
        if cand in edges:
            try:
                return float(edges.get(cand, 0.0) or 0.0)
            except (TypeError, ValueError):
                return 0.0
    scorer = getattr(fin, "_ib_bond_score", None) or getattr(fin, "_bank_bond_score", None)
    if callable(scorer):
        try:
            return float(scorer(world, raw) or 0.0)
        except Exception:
            return 1.0
    return 1.0


def finance_asset_liquidity_score(world: "World", fin: Any, key: str, kind: str) -> float:
    """높을수록 시장에서 팔기 쉬움. 국채 > 대형주 > 회사채 > 중소형."""
    raw = str(key or "")
    if kind == "bond":
        if raw.startswith("gov_"):
            return 3.0
        if raw.startswith("local_"):
            return 2.0
        return 1.0
    if kind == "stock":
        sm = (getattr(world, "stock_markets", None) or {}).get(raw)
        price = float(getattr(sm, "current_price", 0.0) or 0.0) if sm else 0.0
        sh = 0.0
        holdings = getattr(fin, "stock_holdings", None) or {}
        try:
            sh = float(holdings.get(raw, 0.0) or 0.0)
        except (TypeError, ValueError):
            sh = 0.0
        mv = max(0.0, sh * price)
        try:
            mcap = float(
                stock_issuer_valuation_profile(world, raw).get("market_cap", mv) or mv)
        except Exception:
            mcap = mv
        liq = math.log10(max(mcap, 1.0)) / 6.0
        if mcap < 5.0e5:
            liq *= 0.55
        return clamp(liq, 0.05, 3.0)
    return 0.5


def finance_liq_mark_home(world: "World", fin: Any, key: str, kind: str) -> float:
    home = str(getattr(fin, "country_id", "") or "")
    raw = str(key or "")
    if kind == "stock":
        sm = (getattr(world, "stock_markets", None) or {}).get(raw)
        price = float(getattr(sm, "current_price", 0.0) or 0.0) if sm else 0.0
        holdings = getattr(fin, "stock_holdings", None) or {}
        sh = float((holdings or {}).get(raw, 0.0) or 0.0)
        mark = sh * price
        dest = issuer_stock_country_id(world, raw) or home
        if dest and dest != home:
            mark *= fx_home_per_foreign(home, dest, world)
        return max(0.0, mark)
    held = 0.0
    for holdings in _financial_bond_holding_maps(fin):
        held += float((holdings or {}).get(raw, 0.0) or 0.0)
    bm = (getattr(world, "bond_markets", None) or {}).get(raw)
    rate = float(getattr(bm, "current_interest_rate", 0.0) or 0.0) if bm else 0.0
    mark = bond_discount_price(held, rate)
    dest = bond_market_country_id(world, raw) or home
    if dest and dest != home:
        mark *= fx_home_per_foreign(home, dest, world)
    return max(0.0, mark)


def finance_liquidation_rank(world: "World", fin: Any, key: str, kind: str) -> float:
    """높을수록 먼저 판다. -매력 + 유동성 - 거래비용 + 집중 완화."""
    edge = finance_liq_name_edge(world, fin, key, kind)
    liq = finance_asset_liquidity_score(world, fin, key, kind)
    home = str(getattr(fin, "country_id", "") or "")
    raw = str(key or "")
    if kind == "stock":
        dest = issuer_stock_country_id(world, raw) or home
    else:
        dest = bond_market_country_id(world, raw) or home
    txn = ib_country_shadow_cost(str(dest) == home) * IB_SHADOW_COST_ATTRACT_SCALE * 0.25
    aum = finance_actor_liq_aum(world, fin)
    relief = 0.0
    if aum > 1e-9:
        w = finance_liq_mark_home(world, fin, key, kind) / aum
        cap = IB_SINGLE_NAME_CAP if isinstance(fin, InvestmentBank) else 0.12
        relief = max(0.0, w - cap) * 8.0
    return -float(edge) + float(liq) - float(txn) + float(relief)


def queue_financial_liquidity_asset_sells(
    world: "World", fin: Any, need: float,
) -> float:
    """현금 부족분만큼 보유 채권·주식을 시장에 매도. 남은 필요액 반환.

    전주 부족 후 긴급 매각이므로 순매도의 80% 반대호가를 넣는다.
    순위는 낮은 매력·높은 유동성. 이미 나간 매도(pending)는 건너뛴다.
    """
    need = max(0.0, float(need or 0.0))
    if need <= 1e-9:
        return 0.0
    actor_id = str(getattr(fin, "id", "") or "")
    home = str(getattr(fin, "country_id", "") or "")
    weekly_frac = PORTFOLIO_HOLDING_DIRECTIONAL_MAX
    credit = getattr(fin, "_credit_expected_sell_proceeds", None)
    opp_pct = float(LIQ_EMERGENCY_OPPOSITE_PCT)

    def _credit_home(amount: float, market: Optional[Any] = None) -> float:
        if not callable(credit) or amount <= 1e-9:
            return 0.0
        try:
            return float(credit(amount, market=market) or 0.0)
        except TypeError:
            return float(credit(amount) or 0.0)

    for holdings in _financial_bond_holding_maps(fin):
        keys = sorted(
            (holdings or {}).keys(),
            key=lambda k: finance_liquidation_rank(world, fin, k, "bond"),
            reverse=True,
        )
        for key in keys:
            if need <= 1e-9:
                return 0.0
            bm = (getattr(world, "bond_markets", None) or {}).get(key)
            if bm is None:
                continue
            held = float((holdings or {}).get(key, 0.0) or 0.0)
            if held <= 1e-9:
                continue
            if isinstance(fin, Bank) and bank_bond_is_rate_loss(fin, world, key):
                continue
            pending = _financial_pending_market_sell_qty(bm, actor_id)
            avail = min(max(0.0, held - pending), held * weekly_frac)
            if avail <= 1e-9:
                continue
            rate = float(getattr(bm, "current_interest_rate", 0.0) or 0.0)
            dest = bond_market_country_id(world, key) or home
            mark = bond_discount_price(avail, rate)
            if dest and dest != home:
                mark *= fx_home_per_foreign(home, dest, world)
            if mark <= 1e-12:
                continue
            face = min(avail, avail * (need / mark))
            if face <= 1e-9:
                continue
            ni, bb = bond_arbitrage_sell_order_meta(world, key, held)
            bm.sell_orders.append(SellOrder(
                actor_id, face, 0, net_income=ni, bond_balance=bb,
                purpose="liquidity"))
            proceeds = mark * (face / avail)
            earmarked = finance_place_opposite_bond_order(
                world, fin, bm, key, holdings,
                placed_sell=face,
                opposite_pct=opp_pct,
            )
            net = max(0.0, proceeds - earmarked)
            usable = _credit_home(net, bm)
            need = max(0.0, need - usable)

    stock_holdings = getattr(fin, "stock_holdings", None)
    if stock_holdings and not isinstance(fin, Bank):
        keys = sorted(
            stock_holdings.keys(),
            key=lambda k: finance_liquidation_rank(world, fin, k, "stock"),
            reverse=True,
        )
        for iid in keys:
            if need <= 1e-9:
                return 0.0
            sm = (getattr(world, "stock_markets", None) or {}).get(iid)
            price = float(getattr(sm, "current_price", 0.0) or 0.0) if sm else 0.0
            if sm is None or price <= 1e-9:
                continue
            held = float(stock_holdings.get(iid, 0.0) or 0.0)
            if getattr(fin, "stock_tactical", None) is not None:
                held = min(held, ib_long_shares(fin, iid))
            if held <= 1e-9:
                continue
            pending = _financial_pending_market_sell_qty(sm, actor_id)
            avail = min(max(0.0, held - pending), held * weekly_frac)
            if avail <= 1e-9:
                continue
            dest = issuer_stock_country_id(world, iid) or home
            px_home = price
            if dest and dest != home:
                px_home *= fx_home_per_foreign(home, dest, world)
            if px_home <= 1e-12:
                continue
            sell_shares = min(avail, need / px_home)
            sell_shares = stock_clamp_order_shares(world, iid, sell_shares)
            sell_shares = stock_clamp_portfolio_sell(stock_holdings, iid, sell_shares)
            sell_shares = min(sell_shares, avail)
            if sell_shares <= 1e-9:
                continue
            sm.sell_orders.append(SellOrder(
                actor_id, sell_shares, 1, purpose="liquidity"))
            proceeds = sell_shares * px_home
            earmarked = finance_place_opposite_stock_order(
                world, fin, sm, iid, stock_holdings,
                placed_sell_shares=sell_shares,
                opposite_pct=opp_pct,
            )
            net = max(0.0, proceeds - earmarked)
            usable = _credit_home(net, sm)
            need = max(0.0, need - usable)
    return max(0.0, need)


def financial_try_liquidity_asset_sales(world: "World", fin: Any) -> bool:
    """전주 floor 미달이 남은 경우에만 순위 매각. True면 당주 신규 매수·레버리지를 중단한다.

    기회 매도대금(inflows)을 반영한 뒤에도 데드밴드를 넘는 부족만 판다.
    매각 다음 주는 콜/레포 차입을 먼저 시도한다.
    금투 차입 한도 초과분은 금융채 발행이 아니라 당주 매각으로 줄인다.
    """
    if not financial_should_emergency_asset_sale(world, fin):
        return False
    pack = finance_liquidity_pack(world, fin)
    need = float(pack.get("net_gap", 0.0) or 0.0)
    deadband = float(pack.get("deadband", 0.0) or 0.0)
    if isinstance(fin, InvestmentBank):
        max_loan = investment_bank_max_loan_balance(world, fin)
        need += max(
            0.0,
            float(getattr(fin, "loan_balance", 0.0) or 0.0) - max_loan,
        )
    if need <= deadband:
        return False
    queue_financial_liquidity_asset_sells(world, fin, need)
    fin._liq_asset_sale_this_week = True
    if hasattr(fin, "_leverage_order_remaining"):
        fin._leverage_order_remaining = 0.0
    return True


def company_production_facilities(company: "Company") -> List["Facility"]:
    return [f for f in company.facilities if not getattr(f, "is_office", False)]


def gov_record_tax(country: "Country", label: str, amount: float) -> None:
    """중앙정부 주간 세수(수입) 항목 누적."""
    amt = float(amount or 0.0)
    if amt <= 1e-12:
        return
    country.weekly_tax_revenue = float(getattr(country, "weekly_tax_revenue", 0.0) or 0.0) + amt
    bd = getattr(country, "weekly_tax_breakdown", None)
    if not isinstance(bd, dict):
        country.weekly_tax_breakdown = {}
        bd = country.weekly_tax_breakdown
    bd[label] = float(bd.get(label, 0.0) or 0.0) + amt


def gov_record_subsidy(country: "Country", label: str, amount: float) -> None:
    """중앙정부 주간 보조금·재정 지출 항목 누적."""
    amt = float(amount or 0.0)
    if amt <= 1e-12:
        return
    country.weekly_subsidy_paid = float(getattr(country, "weekly_subsidy_paid", 0.0) or 0.0) + amt
    bd = getattr(country, "weekly_subsidy_breakdown", None)
    if not isinstance(bd, dict):
        country.weekly_subsidy_breakdown = {}
        bd = country.weekly_subsidy_breakdown
    bd[label] = float(bd.get(label, 0.0) or 0.0) + amt


def gov_fiscal_detail_rows(breakdown: Optional[Dict[str, float]]) -> List[Dict[str, Any]]:
    rows = [
        {"label": str(lab), "value": round(float(val), 2)}
        for lab, val in (breakdown or {}).items()
        if float(val or 0.0) > 1e-9
    ]
    rows.sort(key=lambda r: -float(r["value"]))
    return rows


def country_display_fiscal(country: "Country") -> Dict[str, Any]:
    """UI용 주간 재정. 당주 세수가 비면(주 시작 리셋·턴 계산 중) 직전 주 값을 쓴다."""
    tax = float(getattr(country, "weekly_tax_revenue", 0.0) or 0.0)
    tax_bd = getattr(country, "weekly_tax_breakdown", None)
    if not isinstance(tax_bd, dict):
        tax_bd = {}
    if tax <= 1e-9:
        tax = float(getattr(country, "last_weekly_tax_revenue", 0.0) or 0.0)
        prev = getattr(country, "last_weekly_tax_breakdown", None)
        if isinstance(prev, dict) and prev:
            tax_bd = prev
    sub = float(getattr(country, "weekly_subsidy_paid", 0.0) or 0.0)
    sub_bd = getattr(country, "weekly_subsidy_breakdown", None)
    if not isinstance(sub_bd, dict):
        sub_bd = {}
    if sub <= 1e-9:
        sub = float(getattr(country, "last_weekly_subsidy_paid", 0.0) or 0.0)
        prev_s = getattr(country, "last_weekly_subsidy_breakdown", None)
        if isinstance(prev_s, dict) and prev_s:
            sub_bd = prev_s
    return {
        "weekly_tax_revenue": tax,
        "weekly_subsidy_paid": sub,
        "tax_breakdown": tax_bd,
        "subsidy_breakdown": sub_bd,
        "gov_net_weekly": tax - sub,
    }


# ---------------------------------------------------------------------------
# 프리셋 월드 (1960년대 냉전 배경)
# ---------------------------------------------------------------------------
_SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
WORLD_SIZE_ALIASES = {
    "소": "소", "소형": "소", "small": "소", "s": "소",
    "중": "중", "중형": "중", "medium": "중", "m": "중",
    "대": "대", "대형": "대", "large": "대", "l": "대",
}


def normalize_world_size(value: str) -> str:
    key = (value or "").strip().lower()
    return WORLD_SIZE_ALIASES.get(key, "")


def load_preset_worlds() -> Dict[str, Dict[str, Any]]:
    path = os.path.join(_SCRIPT_DIR, "preset_worlds.json")
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


PRESET_WORLDS = load_preset_worlds()


def load_ocean_links() -> Dict[str, Set[str]]:
    """preset_worlds.json ocean_links: 대양 간 해상 항로 연결 (국제 무역용)."""
    raw = PRESET_WORLDS.get("ocean_links", {})
    links: Dict[str, Set[str]] = {}
    for ocean, neighbors in raw.items():
        if isinstance(neighbors, list):
            links[str(ocean)] = {str(ocean), *(str(n) for n in neighbors)}
        else:
            links[str(ocean)] = {str(ocean)}
    return links


OCEAN_LINKS = load_ocean_links()


def load_company_name_presets() -> Dict[str, Dict[str, List[str]]]:
    """preset_worlds.json company_names: 국가·직종별 기업 이름 후보."""
    raw = PRESET_WORLDS.get("company_names", {})
    result: Dict[str, Dict[str, List[str]]] = {}
    for country_id, types in raw.items():
        if country_id.startswith("_") or not isinstance(types, dict):
            continue
        result[country_id] = {
            str(ctype): [str(name) for name in names if name]
            for ctype, names in types.items()
            if isinstance(names, list)
        }
    default_types = raw.get("_default", {})
    if isinstance(default_types, dict):
        result["_default"] = {
            str(ctype): [str(name) for name in names if name]
            for ctype, names in default_types.items()
            if isinstance(names, list)
        }
    return result


COMPANY_NAME_PRESETS = load_company_name_presets()


def load_historical_corporate_group_presets() -> Dict[str, List[Dict[str, Any]]]:
    """preset_worlds.json historical_corporate_groups: 국가별 역사적 기업 그룹.

    members 항목은 문자열 또는 {"name", "type?"} 객체.
    root_type이 있으면 루트 직종 힌트.
    """
    raw = PRESET_WORLDS.get("historical_corporate_groups", {})
    out: Dict[str, List[Dict[str, Any]]] = {}
    if not isinstance(raw, dict):
        return out
    for country_key, groups in raw.items():
        if not isinstance(groups, list):
            continue
        cleaned: List[Dict[str, Any]] = []
        for g in groups:
            if not isinstance(g, dict):
                continue
            root = str(g.get("root") or "").strip()
            if not root:
                continue
            members: List[Dict[str, str]] = []
            for m in (g.get("members") or []):
                if isinstance(m, dict):
                    nm = str(m.get("name") or "").strip()
                    if not nm:
                        continue
                    mt = normalize_company_type(str(m.get("type") or "").strip())
                    row: Dict[str, str] = {"name": nm}
                    if mt:
                        row["type"] = mt
                    members.append(row)
                else:
                    nm = str(m or "").strip()
                    if nm:
                        members.append({"name": nm})
            strategy = str(g.get("strategy") or "conglomerate").strip().lower()
            if strategy not in ("vertical", "conglomerate"):
                strategy = "conglomerate"
            brand = str(g.get("brand") or "").strip()
            root_type = normalize_company_type(str(g.get("root_type") or "").strip())
            row_g: Dict[str, Any] = {
                "brand": brand,
                "strategy": strategy,
                "root": root,
                "members": members,
            }
            if root_type:
                row_g["root_type"] = root_type
            cleaned.append(row_g)
        if cleaned:
            out[str(country_key)] = cleaned
    return out


HISTORICAL_CORPORATE_GROUP_PRESETS = load_historical_corporate_group_presets()


def preset_company_types_for_name(preset_key: str, company_name: str) -> List[str]:
    """프리셋 company_names에서 상호가 속한 직종 목록(등장 순, 중복 제거)."""
    name = str(company_name or "").strip()
    if not name:
        return []
    out: List[str] = []
    seen: Set[str] = set()
    for key in (preset_key, "_default"):
        pool = COMPANY_NAME_PRESETS.get(key) or {}
        for ctype, names in pool.items():
            if name not in (names or []):
                continue
            nt = normalize_company_type(str(ctype))
            if not nt or nt in seen:
                continue
            seen.add(nt)
            out.append(nt)
    return out


def preset_company_type_for_name(
    preset_key: str,
    company_name: str,
    *,
    avoid_types: Optional[Set[str]] = None,
) -> str:
    """프리셋 company_names에서 상호가 속한 직종.

    한 상호가 여러 직종에 있으면 avoid_types에 없는 쪽을 우선한다.
    """
    types = preset_company_types_for_name(preset_key, company_name)
    if not types:
        return ""
    avoid = {
        normalize_company_type(t)
        for t in (avoid_types or set())
        if t
    }
    if avoid:
        for t in types:
            if t not in avoid:
                return t
    return types[0]


