def resolve_name_preset_key(country_id: str) -> str:
    """국가 ID를 실제 이름 프리셋 키로 해석 (없으면 배정된 별칭·원본)."""
    if not country_id:
        return country_id
    if country_id in COMPANY_NAME_PRESETS:
        return country_id
    if country_id in COMPANY_NAME_PRESET_ALIAS:
        return COMPANY_NAME_PRESET_ALIAS[country_id]
    return country_id


def historical_corporate_groups_for_country(country_id: str) -> List[Dict[str, Any]]:
    """국가 ID에 적용할 역사적 그룹 프리셋 (국가 키 → _default 순)."""
    preset_key = resolve_name_preset_key(country_id)
    if preset_key in HISTORICAL_CORPORATE_GROUP_PRESETS:
        return list(HISTORICAL_CORPORATE_GROUP_PRESETS[preset_key])
    return list(HISTORICAL_CORPORATE_GROUP_PRESETS.get("_default", []))


def assign_name_preset_aliases(country_ids: Iterable[str]) -> None:
    """프리셋과 매칭되지 않는 국가에 국가별 이름 프리셋을 배정.

    이미 프리셋 키와 일치하는 국가는 그대로 두고, 나머지는 선호 매핑을
    우선 적용한 뒤 남은 국가 프리셋을 고르게 순환 배정한다.
    """
    country_ids = list(country_ids)
    available = [k for k in COMPANY_NAME_PRESETS.keys() if k != "_default"]
    used = {cid for cid in country_ids if cid in COMPANY_NAME_PRESETS}
    idx = 0
    for cid in country_ids:
        if not cid or cid in COMPANY_NAME_PRESETS or cid in COMPANY_NAME_PRESET_ALIAS:
            continue
        pref = COMPANY_NAME_PRESET_PREFERRED.get(cid)
        if pref is None:
            pref = COMPANY_NAME_PRESET_PREFERRED.get(cid.upper())
        if pref is not None:
            COMPANY_NAME_PRESET_ALIAS[cid] = pref
            used.add(pref)
            continue
        if not available:
            continue
        pool = [k for k in available if k not in used] or available
        COMPANY_NAME_PRESET_ALIAS[cid] = pool[idx % len(pool)]
        used.add(COMPANY_NAME_PRESET_ALIAS[cid])
        idx += 1


def load_self_employed_demolition_presets() -> Dict[str, Dict[str, float]]:
    """preset_worlds.json self_employed_demolition: 국가·시설별 워밍업 전 철거 비율(0~1)."""
    raw = PRESET_WORLDS.get("self_employed_demolition", {})
    facility_names = list(SELF_EMP_FACILITY_SPECS.keys())
    result: Dict[str, Dict[str, float]] = {}
    default_raw = raw.get("_default", {})
    default_ratios: Dict[str, float] = {}
    if isinstance(default_raw, dict):
        for fname in facility_names:
            val = default_raw.get(fname, 0.0)
            default_ratios[fname] = clamp(float(val), 0.0, 1.0)
    for country_id, fac_map in raw.items():
        if country_id.startswith("_") or not isinstance(fac_map, dict):
            continue
        result[country_id] = dict(default_ratios)
        for fname in facility_names:
            if fname in fac_map:
                result[country_id][fname] = clamp(float(fac_map[fname]), 0.0, 1.0)
    result["_default"] = default_ratios
    return result


