def load_construction_bond_issue_ratios() -> Dict[str, Dict[str, float]]:
    """preset_worlds.json construction_bond_issue_ratios:
    국가·기업 유형별 회사채 발행 비중(0~1). 건설 1회 발행(잔여 공사비)과
    마지막 워밍업 기발행 잔액(연환산 매출 대비)에 사용.

    최종 비중 = clamp(_default[직종] × _country_scale[국가] + _country_bonus[국가][직종]).
    국가 블록에 직종 키가 있으면 그 값이 최종값을 덮어쓴다.
    """
    raw = PRESET_WORLDS.get("construction_bond_issue_ratios", {})
    result: Dict[str, Dict[str, float]] = {}
    default_raw = raw.get("_default", {}) if isinstance(raw, dict) else {}
    fallback = CONSTRUCTION_BOND_ISSUE_RATIO_DEFAULT
    if isinstance(default_raw, dict) and "_default" in default_raw:
        try:
            fallback = float(default_raw.get("_default", fallback))
        except (TypeError, ValueError):
            fallback = CONSTRUCTION_BOND_ISSUE_RATIO_DEFAULT
    fallback = clamp(
        fallback,
        CONSTRUCTION_BOND_ISSUE_RATIO_MIN,
        CONSTRUCTION_BOND_ISSUE_RATIO_MAX,
    )
    default_ratios: Dict[str, float] = {}
    if isinstance(default_raw, dict):
        for ctype in COMPANY_OCCUPATION_TYPES:
            val = default_raw.get(ctype, fallback)
            try:
                default_ratios[ctype] = clamp(
                    float(val),
                    CONSTRUCTION_BOND_ISSUE_RATIO_MIN,
                    CONSTRUCTION_BOND_ISSUE_RATIO_MAX,
                )
            except (TypeError, ValueError):
                default_ratios[ctype] = fallback
    else:
        for ctype in COMPANY_OCCUPATION_TYPES:
            default_ratios[ctype] = fallback
    default_ratios["_default"] = fallback
    if not isinstance(raw, dict):
        result["_default"] = default_ratios
        return result
    scale_map = raw.get("_country_scale", {})
    if not isinstance(scale_map, dict):
        scale_map = {}
    bonus_map = raw.get("_country_bonus", {})
    if not isinstance(bonus_map, dict):
        bonus_map = {}
    country_ids = set()
    for cid in list(scale_map.keys()) + list(bonus_map.keys()) + list(raw.keys()):
        if cid and not str(cid).startswith("_"):
            country_ids.add(str(cid))
    lo = CONSTRUCTION_BOND_ISSUE_RATIO_MIN
    hi = CONSTRUCTION_BOND_ISSUE_RATIO_MAX
    for country_id in country_ids:
        try:
            scale = float(scale_map.get(country_id, 1.0) or 1.0)
        except (TypeError, ValueError):
            scale = 1.0
        bonus = bonus_map.get(country_id, {})
        if not isinstance(bonus, dict):
            bonus = {}
        built: Dict[str, float] = {}
        for ctype in COMPANY_OCCUPATION_TYPES:
            extra = 0.0
            if ctype in bonus:
                try:
                    extra = float(bonus[ctype])
                except (TypeError, ValueError):
                    extra = 0.0
            built[ctype] = clamp(
                default_ratios.get(ctype, fallback) * scale + extra, lo, hi)
        built["_default"] = clamp(fallback * scale, lo, hi)
        ctype_map = raw.get(country_id)
        if isinstance(ctype_map, dict):
            for ctype in list(COMPANY_OCCUPATION_TYPES) + ["_default"]:
                if ctype not in ctype_map:
                    continue
                try:
                    built[ctype] = clamp(float(ctype_map[ctype]), lo, hi)
                except (TypeError, ValueError):
                    pass
        result[country_id] = built
    result["_default"] = default_ratios
    return result


CONSTRUCTION_BOND_ISSUE_RATIOS = load_construction_bond_issue_ratios()


def load_country_economy_scale() -> Dict[str, float]:
    """preset_worlds.json country_economy_scale: 국가 경제 규모 배수."""
    raw = PRESET_WORLDS.get("country_economy_scale", {})
    result: Dict[str, float] = {}
    if not isinstance(raw, dict):
        return result
    for cid, val in raw.items():
        key = str(cid or "")
        if not key or key.startswith("_"):
            continue
        try:
            result[key] = max(0.05, float(val))
        except (TypeError, ValueError):
            result[key] = float(COUNTRY_ECONOMY_SCALE_DEFAULT)
    return result


COUNTRY_ECONOMY_SCALE_MAP = load_country_economy_scale()


def country_economy_scale(world: Optional["World"], country_id: str) -> float:
    """국가 경제 규모 배수 (시드·상한·공정배수 할인)."""
    cid = str(country_id or "")
    if world is not None:
        cached = getattr(world, "country_economy_scale", None)
        if isinstance(cached, dict) and cid in cached:
            try:
                return max(0.05, float(cached[cid]))
            except (TypeError, ValueError):
                pass
    try:
        return max(0.05, float(
            COUNTRY_ECONOMY_SCALE_MAP.get(cid, COUNTRY_ECONOMY_SCALE_DEFAULT)))
    except (TypeError, ValueError):
        return float(COUNTRY_ECONOMY_SCALE_DEFAULT)


def country_company_cap(world: Optional["World"], country_id: str) -> int:
    """국가·직종별 기업 상한 (전 국가 최대 2). scale은 인구·시설에만 사용."""
    del world, country_id
    return int(MAX_COMPANIES_PER_COUNTRY)


def country_fair_multiple_discount(world: Optional["World"], country_id: str) -> float:
    """후발·소형국 공정 PER/PBR 할인 배수."""
    scale = country_economy_scale(world, country_id)
    if scale < FAIR_MULT_SCALE_LOW:
        return float(FAIR_MULT_SCALE_DISCOUNT_LOW)
    if scale < FAIR_MULT_SCALE_MID:
        return float(FAIR_MULT_SCALE_DISCOUNT_MID)
    return 1.0


def country_company_bond_issue_ratio(country_id: str, company_type: str) -> float:
    """국가·직종별 회사채 발행 비중 (건설 잔여 공사비·워밍업 매출 대비)."""
    ctype = normalize_company_type(str(company_type or ""))
    country = CONSTRUCTION_BOND_ISSUE_RATIOS.get(str(country_id or ""))
    if country is None:
        country = CONSTRUCTION_BOND_ISSUE_RATIOS.get("_default", {})
    val = country.get(ctype)
    if val is None:
        val = country.get("_default", CONSTRUCTION_BOND_ISSUE_RATIO_DEFAULT)
    try:
        return clamp(
            float(val),
            CONSTRUCTION_BOND_ISSUE_RATIO_MIN,
            CONSTRUCTION_BOND_ISSUE_RATIO_MAX,
        )
    except (TypeError, ValueError):
        return CONSTRUCTION_BOND_ISSUE_RATIO_DEFAULT


def company_production_annual_sales(world: "World", company: Any) -> float:
    """시설 산출 × 시세 연환산. 워밍업 매출 장부가 비어도 기발행 규모를 잡을 수 있다."""
    weekly = 0.0
    markets = getattr(world, "markets", None) or {}
    try:
        eff = float(warmup_production_efficiency(company) or 1.0)
    except Exception:
        eff = 1.0
    eff = max(0.0, min(eff, 2.0)) or 1.0
    for fac in getattr(company, "facilities", []) or []:
        if getattr(fac, "is_office", False):
            continue
        levels = 0.0
        try:
            levels = float(fac.active_levels() or 0)
        except Exception:
            levels = float(getattr(fac, "level", 0) or 0) - float(
                getattr(fac, "closed_levels", 0) or 0)
        # 완공 전 단계도 워밍업 기발행 규모에 포함 (reset이 UC를 버리기 전 스냅샷용)
        levels += max(0.0, float(getattr(fac, "under_construction", 0) or 0))
        if levels <= 1e-9:
            continue
        spec = FACILITY_SPECS.get(getattr(fac, "name", ""), {}) or {}
        out = spec.get("output")
        if not out:
            continue
        qty = float(spec.get("output_qty", 1.0) or 1.0) * levels * eff
        if qty <= 1e-9:
            continue
        mk = market_key(str(getattr(fac, "state_id", "") or ""), str(out))
        m = markets.get(mk)
        price = float(market_goods_labor_price(m) or 0.0) if m is not None else 0.0
        if price <= 1e-12:
            price = float(getattr(m, "current_price", 0.0) or 0.0) if m is not None else 1.0
        weekly += qty * max(price, 0.0)
    return max(0.0, weekly * 52.0)


def company_warmup_annual_revenue(world: "World", company: Any) -> float:
    """기업 워밍업 매출 → 연환산. 장부가 없으면 시설 산출×시세로 추정."""
    raw = float(getattr(company, "warmup_annual_revenue", 0.0) or 0.0)
    if raw > 1e-6:
        return raw
    recorded = float(getattr(company, "warmup_corporate_revenue", 0.0) or 0.0)
    weeks = max(
        1,
        int(getattr(world, "warmup_corporate_turns", 0) or 0)
        or int(WARMUP_CORPORATE_TURNS or 0)
        or 13,
    )
    if recorded > 1e-9:
        raw = recorded * (52.0 / float(weeks))
    if raw <= 1e-6:
        raw = annual_net_income_from_weekly_history(
            getattr(company, "weekly_income_history", None),
            fallback_weekly=float(getattr(company, "income", 0.0) or 0.0),
        )
    if raw <= 1e-6:
        raw = company_production_annual_sales(world, company)
    if raw <= 1e-6:
        try:
            raw = float(company_plant_book_value(world, company) or 0.0)
        except Exception:
            raw = 0.0
    return max(0.0, float(raw or 0.0))


def company_warmup_annual_net_income(world: "World", company: Any) -> float:
    """기업 워밍업 순이익 → 연환산. 재무 초기화 전에 스냅한 값을 우선한다."""
    raw = float(getattr(company, "warmup_annual_net_income", 0.0) or 0.0)
    if raw > 1e-6:
        return raw
    hist = annual_net_income_from_weekly_history(
        getattr(company, "weekly_net_income_history", None),
        fallback_weekly=float(getattr(company, "net_income", 0.0) or 0.0),
    )
    if hist > 1e-6:
        return hist
    weekly = float(getattr(company, "net_income", 0.0) or 0.0)
    if weekly > 1e-6:
        return weekly * float(ANNUAL_NET_INCOME_WEEKS)
    return 0.0


def company_construction_bond_issue_ratio(company: Any) -> float:
    """기업 본사 소재국·직종 프리셋 발행 비중."""
    ctype = str(
        getattr(company, "company_type", None)
        or getattr(company, "type", "")
        or ""
    )
    world = getattr(company, "_world_ref", None)
    country_id = ""
    getter = getattr(company, "_investment_country_id", None)
    if callable(getter):
        try:
            country_id = str(getter(world) or "")
        except Exception:
            country_id = ""
    if not country_id and world is not None:
        home = str(getattr(company, "home_state", "") or "")
        st = (getattr(world, "states", None) or {}).get(home)
        country_id = str(getattr(st, "country_id", "") or "") if st else ""
    return country_company_bond_issue_ratio(country_id, ctype)


def country_export_facility_warmup_ratio(country_id: str, company_type: str) -> float:
    """국가·기업 유형별 수출 워밍업 건설 비중 (0~1)."""
    country = EXPORT_FACILITY_WARMUP_RATIOS.get(country_id)
    if country is None:
        country = EXPORT_FACILITY_WARMUP_RATIOS.get("_default", {})
    return country.get(company_type, 0.0)


def country_export_facility_warmup_target(
    country_id: str, company_type: str,
) -> int:
    """수출 워밍업 목표 시설 단계 수."""
    ratio = country_export_facility_warmup_ratio(country_id, company_type)
    if ratio <= 1e-12:
        return 0
    return max(0, int(round(ratio * WARMUP_EXPORT_RATIO_SCALE)))


def load_social_tech_start_level_presets() -> Dict[str, int]:
    """preset_worlds.json social_tech_start_levels: 국가별 시작 사회기술 레벨."""
    raw = PRESET_WORLDS.get("social_tech_start_levels", {})
    default = max(0, int(raw.get("_default", 0)))
    result: Dict[str, int] = {"_default": default}
    for country_id, level in raw.items():
        if country_id.startswith("_"):
            continue
        result[str(country_id)] = max(0, int(level))
    return result


SOCIAL_TECH_START_LEVEL_PRESETS = load_social_tech_start_level_presets()


def load_company_tech_start_level_presets() -> Dict[str, int]:
    """preset_worlds.json company_tech_start_levels: 국가별 기본 시작 기술 레벨."""
    raw = PRESET_WORLDS.get("company_tech_start_levels", {})
