def load_company_tech_occupation_bonuses() -> Dict[str, Dict[str, int]]:
    """preset_worlds.json company_tech_occupation_bonuses: 국가·직종별 기술 가산."""
    raw = PRESET_WORLDS.get("company_tech_occupation_bonuses", {})
