COMPANY_TECH_START_LEVEL_PRESETS = load_company_tech_start_level_presets()
COMPANY_TECH_OCCUPATION_BONUSES = load_company_tech_occupation_bonuses()


def country_company_tech_start_level(country_id: str) -> int:
    return COMPANY_TECH_START_LEVEL_PRESETS.get(
        country_id, COMPANY_TECH_START_LEVEL_PRESETS.get("_default", INITIAL_COMPANY_TECH_LEVEL))


def company_occupation_tech_start_level(country_id: str, company_type: str) -> int:
    """국가 기본 + 직종 보너스 — 동국 기업이라도 산업별 기술 차등."""
    base = country_company_tech_start_level(country_id)
    ctype = normalize_company_type(company_type)
    bonus = COMPANY_TECH_OCCUPATION_BONUSES.get(country_id, {}).get(ctype, 0)
    return max(1, base + int(bonus))


def company_id_seq_index(company_id: str) -> int:
    """법인 ID 끝 시퀀스 번호. 접미사 없는 레거시 ID는 0."""
    tail = str(company_id or "").rsplit("_", 1)[-1]
    try:
        return max(0, int(tail))
    except ValueError:
        return 0


def company_tech_start_jitter(
    company_id: str, spread: int = COMPANY_TECH_START_JITTER,
) -> int:
    """워밍업·시드 동종 기업이 같은 시작 레벨이 되지 않도록 ±spread 편차.

    첫 기업(시퀀스 0)은 프리셋 그대로, 2번째 +spread, 3번째 -spread.
    법인 ID 기반이라 워밍업 중 재적용해도 값이 바뀌지 않는다.
    """
    spread = max(0, int(spread or 0))
    if spread <= 0:
        return 0
    idx = company_id_seq_index(company_id)
    if idx <= 0:
        return 0
    sign = 1 if idx % 2 else -1
    mag = ((idx - 1) // 2) % spread + 1
    return sign * mag


def apply_company_country_tech_level(
    company: "Company", states: Dict[str, "State"],
) -> None:
    """기업 소재국·직종 프리셋 + 개별 시퀀스 편차로 tech_level 설정."""
    if isinstance(company, RetailCompany):
        return
    cid = company_home_country_id(company, states)
    base = company_occupation_tech_start_level(cid, company.type)
    jitter = company_tech_start_jitter(getattr(company, "id", ""))
    company.tech_level = max(1, int(base) + int(jitter))


def apply_all_company_country_tech_levels(world: "World") -> None:
    for co in world.companies.values():
        apply_company_country_tech_level(co, world.states)


def _merge_warmup_financial_preset_dict(
    base: Dict[str, Any], override: Dict[str, Any],
) -> Dict[str, Any]:
    """국가별 워밍업 재무 프리셋 — 중첩 dict(pop·company_cash_to_re) 병합."""
    result = dict(base)
    for key, val in override.items():
        if (
            key in result
            and isinstance(result[key], dict)
            and isinstance(val, dict)
        ):
            merged = dict(result[key])
            merged.update(val)
            result[key] = merged
        else:
            result[key] = val
    return result


def load_warmup_financial_presets() -> Dict[str, Dict[str, Any]]:
    """preset_worlds.json warmup_financial_presets: 국가별 워밍업 후 재무 비율.

    인구 예금/펀드/채권은 보유 주식 공정가×POP_WARMUP_STOCK_ANCHOR_FRAC 대비(*_to_stock).
    금투 예금/펀드/채권은 보유 주식 공정가 대비(*_to_stock).
    시중은행은 실제 인구 예금으로 조달하고 지준 초과 현금은 국채에 운용.
    """
    raw = PRESET_WORLDS.get("warmup_financial_presets", {})
    default_raw = raw.get("_default", {})
    default: Dict[str, Any] = {}
    if isinstance(default_raw, dict):
        default = dict(default_raw)
        pop_def = default_raw.get("pop", {})
        if isinstance(pop_def, dict):
            # 구키(*_to_re) → 주식 공정가 기준(*_to_stock) 호환
            default["pop"] = {
                "cash_to_re": float(pop_def.get("cash_to_re", 0.15)),
                "deposit_to_stock": float(pop_def.get(
                    "deposit_to_stock",
                    pop_def.get("deposit_to_re", 0.30))),
                "fund_to_stock": float(pop_def.get(
                    "fund_to_stock",
                    pop_def.get("fund_to_re", 0.10))),
                "bond_to_stock": float(pop_def.get("bond_to_stock", 0.20)),
                "mortgage_to_re": float(pop_def.get("mortgage_to_re", 0.40)),
                "loan_to_re": float(pop_def.get("loan_to_re", 0.10)),
                "re_anchor_per_capita": float(
                    pop_def.get("re_anchor_per_capita", 80.0)),
            }
        co_def = default_raw.get("company_cash_to_re", {})
        if isinstance(co_def, dict):
            default["company_cash_to_re"] = {
                str(k): float(v) for k, v in co_def.items()}
        default["company_re_anchor"] = float(
            default_raw.get("company_re_anchor", 40000.0))
        default["ib_bond_to_stock"] = float(default_raw.get(
            "ib_bond_to_stock",
            default_raw.get("ib_cash_to_re", 0.45)))
        default["bank_assets_to_ib_assets"] = float(default_raw.get(
            "bank_assets_to_ib_assets",
            default_raw.get("bank_cash_to_ib_cash", 2.50)))
        # 부동산: 인구·금투 소유 비중 (대부분 인구)
        default["re_pop_share"] = float(default_raw.get("re_pop_share", 0.85))
        default["re_ib_share"] = float(default_raw.get("re_ib_share", 0.15))
    result: Dict[str, Dict[str, Any]] = {"_default": default}
    for country_id, block in raw.items():
        if country_id.startswith("_") or not isinstance(block, dict):
            continue
        merged = _merge_warmup_financial_preset_dict(default, block)
        # 국가 블록에 구키만 있으면 주식 기준으로 승격
        pop_blk = block.get("pop", {})
        if isinstance(pop_blk, dict):
            pop_m = dict(merged.get("pop", {}))
            if "deposit_to_stock" not in pop_blk and "deposit_to_re" in pop_blk:
                pop_m["deposit_to_stock"] = float(pop_blk["deposit_to_re"])
            if "fund_to_stock" not in pop_blk and "fund_to_re" in pop_blk:
                pop_m["fund_to_stock"] = float(pop_blk["fund_to_re"])
            merged["pop"] = pop_m
        if "ib_bond_to_stock" not in block and "ib_cash_to_re" in block:
            merged["ib_bond_to_stock"] = float(block["ib_cash_to_re"])
        if (
            "bank_assets_to_ib_assets" not in block
            and "bank_cash_to_ib_cash" in block
        ):
            # 구 현금배수(1.x)는 총자산 배수(2~3)로 클램프
            legacy = float(block["bank_cash_to_ib_cash"])
            merged["bank_assets_to_ib_assets"] = clamp(legacy, 2.0, 3.0) if legacy < 2.0 else min(3.0, legacy)
        result[str(country_id)] = merged
    return result


WARMUP_FINANCIAL_PRESETS = load_warmup_financial_presets()


def country_warmup_financial_preset(country_id: str) -> Dict[str, Any]:
    """국가별 워밍업 후 재무 프리셋 — 미정의 항목은 _default."""
    preset = WARMUP_FINANCIAL_PRESETS.get(country_id)
    if preset is None:
        return dict(WARMUP_FINANCIAL_PRESETS.get("_default", {}))
    return dict(preset)


def pop_weekly_income_cash_base(pop: "POP") -> float:
    """워밍업 현금 버퍼용 주간 수입. 당주·전주·최저소비 폴백 중 큰 값."""
    weekly = max(0.0, float(getattr(pop, "weekly_income", 0.0) or 0.0))
    last = max(0.0, float(getattr(pop, "last_week_income", 0.0) or 0.0))
    try:
        pop_n = max(0.0, float(pop.total_population() or 0.0))
    except Exception:
        pop_n = max(0.0, float(getattr(pop, "size", 0.0) or 0.0))
    fallback = pop_n * POP_CONSUMPTION_MIN_FALLBACK
    return max(weekly, last, fallback)


# 서비스 소비→부동산 단위 환산 폴백 (거주 욕구 cap: 12/25, 12×0.55/55)
_RE_SERVICE_PER_CAPITA_FALLBACK = {
    "주거 서비스": 0.48,
    "고급 주거 서비스": 0.12,
    "임대 서비스": 0.08,
}


def _pop_need_item_structural_qty(
    pop: "POP", item: str, *, income_m: float, housing_weight: float,
) -> float:
    """POP_NEEDS 항목 cap (max_share) 기준 주당 이상 수량."""
    pop_n = max(0.0, float(pop.total_population() or 0.0))
    if pop_n <= 1e-9:
        return 0.0
    for need in POP_NEEDS:
        for it, sat_val, max_share in need["items"]:
            if it != item:
                continue
            target = float(need["target"] or 0.0) * max(0.0, float(income_m))
            nname = str(need.get("name", "") or "")
            if nname in ("거주", "주거"):
                target *= float(housing_weight)
            return (
                (target * float(max_share) * pop_n)
                / max(float(sat_val) or 1.0, 1e-9)
            )
    return 0.0


def state_re_service_structural_demand(
    world: "World", state_id: str, kind: str,
) -> float:
    """워밍업 시드용 구조 수요 — 매도량·소량 시드에 묶이지 않음.

    다세대/주택: 인구 거주 욕구 cap × 소득배율(하한 1.0) × 연령 가중.
    다용도: 본사 주 기업 필요 사무슬롯 전량(보유 회수 전제) + 자영 임대.
    """
    service = RE_SERVICE_OUTPUT.get(kind)
    if not service:
        return 0.0
    st = world.states.get(state_id)
    if st is None:
        return 0.0
    total = 0.0
    if kind in ("multi_family", "housing"):
        pending_sum = 0.0
        for pop in st.pops or []:
            pop_n = max(0.0, float(pop.total_population() or 0.0))
            if pop_n <= 1e-9:
                continue
            income_base = max(
                float(getattr(pop, "last_week_income", 0.0) or 0.0)
                + float(getattr(pop, "weekly_income", 0.0) or 0.0)
                + float(getattr(pop, "parent_support_received", 0.0) or 0.0),
                pop_n * POP_CONSUMPTION_MIN_FALLBACK,
            )
            m = max(1.0, income_consumption_multiplier(income_base, pop_n))
            try:
                age = pop_mean_age(pop, world)
            except Exception:
                age = float(getattr(pop, "_cached_mean_age", 40.0) or 40.0)
            hw = float(
                pop_age_behavior_profile(age).get("housing_weight", 1.0) or 1.0)
            total += _pop_need_item_structural_qty(
                pop, service, income_m=m, housing_weight=hw)
            pending = getattr(pop, "_pending_demand_need", None) or {}
            pending_sum += float(pending.get(service, 0.0) or 0.0)
        total = max(total, pending_sum)
    elif kind == "mixed_use":
        for co in (getattr(world, "companies", None) or {}).values():
            if getattr(co, "home_state", "") != state_id:
                continue
            if getattr(co, "is_bankrupt", False):
                continue
            if not hasattr(co, "office_slots_required"):
                continue
            try:
                slots = float(co.office_slots_required() or 0.0)
            except Exception:
                slots = 0.0
            total += max(0.0, slots) * float(RE_RENTAL_PER_OFFICE_SLOT)
        for sector in (getattr(st, "self_employed", None) or {}).values():
            ordered = float(getattr(sector, "rental_ordered", 0.0) or 0.0)
            filled = float(getattr(sector, "rental_filled", 0.0) or 0.0)
            total += max(ordered, filled, 0.0)
    return max(0.0, total)


def state_re_service_consumption(
    world: "World", state_id: str, kind: str,
) -> float:
    """주의 주거·임대 서비스 시드 물량 — 매수·구조 수요 (매도 제외).

    매도량을 쓰면 소량 RE 운영 매도가 목표로 고정되어 공급 부족이 영구화된다.
    """
    service = RE_SERVICE_OUTPUT.get(kind)
    if not service:
        return 0.0
    buy_v, _sell_v = re_service_market_volumes(world, state_id, service)
    structural = state_re_service_structural_demand(world, state_id, kind)
    vol = max(buy_v, structural)
    if vol > 1e-9:
        return vol
    mk = world.markets.get(market_key(state_id, service))
    if mk is not None:
        results = getattr(mk, "buy_order_results", None) or []
        filled = sum(float(getattr(r, "filled_quantity", 0.0) or 0.0) for r in results)
        if filled > 1e-9:
            return filled
        try:
            traded = float(market_traded_volume(mk) or 0.0)
        except Exception:
            traded = 0.0
        if traded > 1e-9:
            return traded
    st = world.states.get(state_id)
    if st is None:
        return 0.0
    pop_n = sum(max(0.0, float(p.total_population() or 0.0)) for p in (st.pops or []))
    return pop_n * float(_RE_SERVICE_PER_CAPITA_FALLBACK.get(service, 0.05))


def re_units_for_service_consumption(kind: str, service_qty: float) -> float:
    """서비스 소비량을 해당 부동산 종류 보유 단위로 환산."""
    fac_name = RE_KIND_FACILITY.get(kind)
    spec = FACILITY_SPECS.get(fac_name, {}) if fac_name else {}
    out_qty = float(spec.get("output_qty", 0.0) or 0.0)
    if out_qty <= 1e-9:
        out_qty = 1.0
    return max(0.0, float(service_qty or 0.0) / out_qty)


def pop_re_aum(world: "World", pop: "POP") -> float:
    """인구층 투자 AUM + 부동산 시가."""
    return float(pop.investment_aum(world) or 0.0) + re_holdings_market_value(
        world, ensure_actor_re_holdings(pop))


def rem_listing_price(rem: Optional["RealEstateMarketState"]) -> float:
    if rem is None:
        return 0.0
    px = float(getattr(rem, "current_price", 0.0) or 0.0)
    if px <= 1e-9:
        px = float(getattr(rem, "fair_value", 0.0) or 0.0)
    return max(0.0, px)


def pop_mixed_use_alloc_weights(world: "World", pops: List["POP"]) -> List[float]:
    """다용도 배분 가중: 시드(나이×인구) × max(AUM, 인구)."""
    if not pops:
        return []
    seed = pop_ownership_seed_weights(world, pops, "mixed_use")
    weights: List[float] = []
    for pop, sw in zip(pops, seed):
        aum = pop_re_aum(world, pop)
        n = max(1.0, float(pop.total_population() or 0.0))
        weights.append(max(0.0, float(sw)) * max(aum, n))
    if sum(weights) > 1e-12:
        return weights
    return [max(1.0, float(p.total_population() or 1.0)) for p in pops]


def state_warmup_re_pop_share(country_id: str) -> float:
    preset = country_warmup_financial_preset(country_id)
    pop_share = clamp(float(preset.get("re_pop_share", 0.85)), 0.55, 0.95)
    ib_share = clamp(float(preset.get("re_ib_share", 0.15)), 0.05, 0.45)
    share_sum = pop_share + ib_share
    if share_sum > 1e-9:
        return pop_share / share_sum
    return 0.85


def state_mixed_use_pop_floor_units(world: "World", state_id: str) -> float:
    """임대 수요 대비 인구층이 지켜야 할 다용도 유닛."""
    consumption = state_re_service_consumption(world, state_id, "mixed_use")
    need = re_units_for_service_consumption(
        "mixed_use", consumption * SUPPLY_SAFETY_BUFFER_RATIO)
    st = world.states.get(state_id)
    pop_share = 0.85
    if st is not None:
        pop_share = state_warmup_re_pop_share(st.country_id)
    return max(0.0, need * pop_share)


def pop_mixed_use_min_keep_qty(
    world: "World",
    pop: Any,
    state_id: str,
    *,
    aum: Optional[float] = None,
    weight: float = 0.0,
    weight_sum: float = 0.0,
    state_floor: Optional[float] = None,
) -> float:
    """인구층 다용도 매도 하한 — AUM 비율과 주 임대 필요 몫 중 큰 값."""
    rem = world.real_estate_markets.get(re_market_key(state_id, "mixed_use"))
    px = rem_listing_price(rem)
    if aum is None:
        aum = pop_re_aum(world, pop) if hasattr(pop, "investment_aum") else 0.0
    aum_keep = 0.0
    if px > 1e-9 and float(aum or 0.0) > 1e-9:
        aum_keep = (
            float(aum) * RE_POP_MIXED_USE_AUM_SHARE * RE_POP_MIN_MIXED_USE_KEEP
        ) / px
    lease_keep = 0.0
    tw = max(0.0, float(weight_sum))
    w = max(0.0, float(weight))
    if tw <= 1e-12 and hasattr(pop, "investment_aum"):
        st = world.states.get(state_id)
        pops = list(st.pops or []) if st is not None else []
        if pops:
            weights = pop_mixed_use_alloc_weights(world, pops)
            tw = sum(weights)
            pop_id = getattr(pop, "id", None)
            for other, ow in zip(pops, weights):
                if other is pop or getattr(other, "id", None) == pop_id:
                    w = max(0.0, float(ow))
                    break
    if tw > 1e-12:
        if state_floor is None:
            state_floor = state_mixed_use_pop_floor_units(world, state_id)
        lease_keep = (
            float(state_floor or 0.0)
            * (w / tw)
            * RE_POP_MIN_MIXED_USE_KEEP
        )
    return max(aum_keep, lease_keep)


def warmup_entity_re_anchor(
    world: "World",
    entity: Any,
    *,
    re_anchor_per_capita: float = 80.0,
    company_re_anchor: float = 40000.0,
) -> float:
    """부동산 시가 기준액 — 보유 없으면 인구·기업용 대체 앵커."""
    re_val = re_holdings_market_value(
        world, ensure_actor_re_holdings(entity))
    if re_val > 1e-6:
        return re_val
    if isinstance(entity, POP):
        return max(1.0, float(entity.size) * re_anchor_per_capita)
    return max(1000.0, float(company_re_anchor))


def pop_primary_re_collateral(
    world: "World", pop: "POP",
) -> Tuple[str, float]:
    """인구층 보유 부동산 중 시가 최대 1건 (모기지 담보용)."""
    key, val, _ = pop_best_mortgage_collateral(world, pop, prefer_residential=False)
    return key, val


def pop_best_mortgage_collateral(
    world: "World",
    pop: "POP",
    *,
    prefer_residential: bool = False,
) -> Tuple[str, float, float]:
    """(담보 키, 시가, LTV 상한 배수) — prefer_residential 시 주택·다세대 우선."""
    best_key, best_val, best_ltv = "", 0.0, 0.0
    best_score = -1.0
    for key, qty in ensure_actor_re_holdings(pop).items():
        if qty <= 1e-9:
            continue
        sid, kind = parse_re_holdings_key(key)
        if not sid or kind not in RE_KINDS:
            continue
        mk = world.real_estate_markets.get(re_market_key(sid, kind))
        val = float(qty) * float(mk.current_price) if mk else 0.0
        if val <= 1e-9:
            continue
        ltv_mult = float(RE_MORTGAGE_COLLATERAL_LTV_MULT.get(kind, 0.5))
        if prefer_residential:
            score = val * float(RE_MORTGAGE_COLLATERAL_PRIORITY.get(kind, 1.0))
        else:
            score = val
        if score > best_score:
            best_score = score
            best_key, best_val, best_ltv = key, val, ltv_mult
    return best_key, best_val, best_ltv


def mortgage_principal_for_ids(
    world: "World", mortgage_ids: Optional[Iterable[str]],
) -> float:
    """부동산담보대출 ID 목록의 잔여 원금 합."""
    total = 0.0
    for mid in mortgage_ids or []:
        mtg = world.mortgages.get(mid) if world else None
        if mtg is None:
            continue
        prin = float(getattr(mtg, "principal", 0.0) or 0.0)
        if prin > 1e-9:
            total += prin
    return total


def mortgage_principal_at_bank(
    world: "World", actor: Any, bank_id: str,
) -> float:
    """특정 은행에 귀속된 부동산담보대출 원금."""
    total = 0.0
    for mid in getattr(actor, "mortgages", None) or []:
        mtg = world.mortgages.get(mid)
        if mtg is None or mtg.bank_id != bank_id:
            continue
        prin = float(getattr(mtg, "principal", 0.0) or 0.0)
        if prin > 1e-9:
            total += prin
    return total


def sync_mortgage_loan_alloc(world: "World", entity: Any) -> None:
    """부동산담보대출 원금이 loan_alloc·loan_balance·은행 대출원장에 있게 한다.

    일반상환·대환이 담보대출 원장을 비워도 계약 잔액은 남는 구 세이브/틱을 복구한다.
    """
    if world is None or entity is None:
        return
    for mid in getattr(entity, "mortgages", None) or []:
        mtg = world.mortgages.get(mid)
        if mtg is None:
            continue
        prin = float(getattr(mtg, "principal", 0.0) or 0.0)
        if prin <= 1e-9:
            continue
        bid = str(getattr(mtg, "bank_id", "") or "")
        if not bid:
            continue
        banks = getattr(world, "banks", None) or {}
        bank = banks.get(bid)
        loan_alloc = _entity_alloc(entity, "loan_alloc")
        cur = float(loan_alloc.get(bid, 0.0) or 0.0)
        gap = prin - cur
        if gap <= 1e-6:
            continue
        for other_id in list(loan_alloc.keys()):
            if other_id == bid or gap <= 1e-6:
                continue
            other_mtg = mortgage_principal_at_bank(world, entity, other_id)
            movable = max(
                0.0,
                float(loan_alloc.get(other_id, 0.0) or 0.0) - other_mtg)
            take = min(gap, movable)
            if take <= 1e-9:
                continue
            other = banks.get(other_id)
            if other is not None:
                other.loans = max(0.0, float(other.loans or 0.0) - take)
                ocid = getattr(other, "country_id", None)
                if ocid:
                    other.loans_by_currency[ocid] = max(
                        0.0,
                        float(other.loans_by_currency.get(ocid, 0.0) or 0.0) - take)
            if bank is not None:
                bank.loans = float(bank.loans or 0.0) + take
                bcid = getattr(bank, "country_id", None)
                if bcid:
                    bank.loans_by_currency[bcid] = (
                        float(bank.loans_by_currency.get(bcid, 0.0) or 0.0) + take)
                bank_cash = float(getattr(bank, "cash", 0.0) or 0.0)
                if other is not None and bank_cash + 1e-6 >= take:
                    bank.cash = bank_cash - take
                    other.cash = float(getattr(other, "cash", 0.0) or 0.0) + take
            loan_alloc[other_id] = float(loan_alloc.get(other_id, 0.0) or 0.0) - take
            if loan_alloc[other_id] <= 1e-9:
                loan_alloc.pop(other_id, None)
            loan_alloc[bid] = float(loan_alloc.get(bid, 0.0) or 0.0) + take
            gap -= take
        if gap > 1e-6:
            # 계약·배분만 맞춘다. 은행 loans는 이미 취급 시 잡혀 있으므로
            # 여기서 다시 더하면 상속 등으로 alloc만 줄었을 때 여신이 복제된다.
            loan_alloc[bid] = float(loan_alloc.get(bid, 0.0) or 0.0) + gap
            if hasattr(entity, "loan_balance"):
                entity.loan_balance = (
                    float(getattr(entity, "loan_balance", 0.0) or 0.0) + gap)
        if hasattr(entity, "loan_bank_id"):
            entity.loan_bank_id = alloc_dominant_id(entity, "loan_alloc")


def mortgage_principal_by_collateral(
    world: "World", actor: Any,
) -> Dict[str, float]:
    """담보물 키별 부동산담보대출 원금."""
    out: Dict[str, float] = defaultdict(float)
    for mid in getattr(actor, "mortgages", None) or []:
        mtg = world.mortgages.get(mid)
        if mtg is None:
            continue
        prin = float(getattr(mtg, "principal", 0.0) or 0.0)
        if prin <= 1e-9:
            continue
        key = str(getattr(mtg, "collateral_key", "") or "")
        if key:
            out[key] += prin
    return dict(out)


def re_mortgage_loan_amount(
    qty: float, price: float, unit_cost: float, ltv: float,
) -> float:
    """부동산 매수 체결분에 대한 담보대출 가능액."""
    if qty <= 1e-9 or ltv <= 1e-9:
        return 0.0
    cost_only = qty * price * (1.0 + RE_CLEARING_FEE)
    total_all = qty * unit_cost
    return min(cost_only * ltv, total_all * 0.7)


def re_mortgage_eligible(buyer: Any) -> bool:
    return hasattr(buyer, "mortgages") and hasattr(buyer, "loan_balance")


def re_mortgage_cash_reserve_factor(ltv: float, use_loan: bool) -> float:
    """담보대출 사용 시 현금 예약·차감에 반영할 자기부담 비율."""
    if not use_loan:
        return 1.0
    return max(0.0, 1.0 - ltv * 0.5)


def re_use_mortgage_for_budget(
    budget: float, cash: float, ltv: float, *, min_cash_ratio: float = 0.25,
) -> bool:
    return budget > cash * min_cash_ratio and ltv > 0.4


def actor_mortgage_balance(world: Optional["World"], actor: Any) -> float:
    if world is None:
        return 0.0
    return mortgage_principal_for_ids(world, getattr(actor, "mortgages", None))


def pop_mortgage_balance(world: Optional["World"], pop: "POP") -> float:
    return actor_mortgage_balance(world, pop)


def bank_mortgage_balance(world: Optional["World"], bank: "Bank") -> float:
    if world is None:
        return 0.0
    return mortgage_principal_for_ids(world, getattr(bank, "mortgage_book", None))


def bank_loan_asset_components(
    world: Optional["World"], bank: "Bank",
) -> Tuple[float, float, float]:
    """담보대출·일반대출·합계.

    담보대출 계약 잔액이 은행 대출원장(bank.loans)보다 크면 원장에 안 잡힌
    담보대출을 자산으로 더한다. 원장이 더 크면 담보대출은 원장의 일부다.
    """
    mortgage = bank_mortgage_balance(world, bank)
    book = max(0.0, float(getattr(bank, "loans", 0.0) or 0.0))
    if mortgage <= book + 1e-9:
        other = max(0.0, book - mortgage)
        total = book
    else:
        other = book
        total = book + mortgage
    return mortgage, other, total


def bank_foreclosure_holdings_value(world: Optional["World"], bank: "Bank") -> float:
    """은행 압류 부동산 시가 합."""
    if world is None:
        return 0.0
    total = 0.0
    for key, qty in (getattr(bank, "re_foreclosure_holdings", None) or {}).items():
        q = float(qty or 0.0)
        if q <= 1e-9:
            continue
        sid, kind = parse_re_holdings_key(str(key))
        rem = world.real_estate_markets.get(re_market_key(sid, kind))
        if rem:
            total += q * float(getattr(rem, "current_price", 0.0) or 0.0)
    return total


def _asset_mix_week(world: Optional["World"]) -> int:
    return int(getattr(world, "week", 0) or 0) if world is not None else 0


def _asset_mix_row(world: Optional["World"], values: Dict[str, float]) -> Dict[str, Any]:
    row = {key: round(max(0.0, float(val or 0.0)), 2) for key, val in values.items()}
    total = round(sum(row.values()), 2)
    row["week"] = _asset_mix_week(world)
    row["total"] = total
    return row


def central_bank_asset_mix_snapshot(world: "World", cb: "CentralBank") -> Dict[str, Any]:
    """중은 자산 구성 막대와 동일 키."""
    return _asset_mix_row(world, {
        "foreign_reserves": float(sum((getattr(cb, "foreign_cash", None) or {}).values())),
        "domestic_bonds": float(sum((getattr(cb, "bond_portfolio", None) or {}).values())),
        "foreign_bonds": float(sum((getattr(cb, "foreign_bond_portfolio", None) or {}).values())),
        "stock_portfolio": stock_holdings_total_value(
            world, getattr(cb, "stock_portfolio", None) or {}),
    })


def commercial_bank_asset_mix_snapshot(world: "World", bank: "Bank") -> Dict[str, Any]:
    """시중은행 포트폴리오 구성 막대와 동일 키."""
    rates = getattr(bank, "bond_purchase_rate", None)
    mortgage_loans, other_loans, _total = bank_loan_asset_components(world, bank)
    return _asset_mix_row(world, {
        "cash": float(getattr(bank, "cash", 0.0) or 0.0),
        "fx_holdings": foreign_cash_home_value(
            getattr(bank, "country_id", None), getattr(bank, "foreign_cash", None), world),
        "mortgage_loans": mortgage_loans,
        "other_loans": other_loans,
        "call_lending": float(getattr(bank, "call_lending", 0.0) or 0.0),
        "repo_lending": float(getattr(bank, "repo_lending", 0.0) or 0.0),
        "domestic_bonds": bond_holdings_mark_value(
            world, getattr(bank, "bond_portfolio", None), rates),
        "foreign_bonds": bond_holdings_mark_value(
            world, getattr(bank, "foreign_bond_portfolio", None), rates),
        "foreclosure_value": bank_foreclosure_holdings_value(world, bank),
    })


def investment_bank_asset_mix_snapshot(world: "World", ib: "InvestmentBank") -> Dict[str, Any]:
    """금투 포트폴리오 구성 막대와 동일 키."""
    domestic_stock, foreign_stock = investment_bank_stock_values_by_region(world, ib)
    domestic_bond, foreign_bond = investment_bank_bond_values_by_region(world, ib)
    return _asset_mix_row(world, {
        "cash": float(getattr(ib, "cash", 0.0) or 0.0),
        "fx_value": foreign_cash_home_value(
            getattr(ib, "country_id", None), getattr(ib, "foreign_cash", None), world),
        "domestic_stock": domestic_stock,
        "foreign_stock": foreign_stock,
        "domestic_bond": domestic_bond,
        "foreign_bond": foreign_bond,
        "re_value": re_holdings_market_value(world, ensure_actor_re_holdings(ib)),
        "deposits": float(getattr(ib, "deposits", 0.0) or 0.0),
        "call_lending": float(getattr(ib, "call_lending", 0.0) or 0.0),
        "repo_lending": float(getattr(ib, "repo_lending", 0.0) or 0.0),
    })


def finance_asset_history_payload(
    world: Optional["World"], actor: Any, kind: str,
) -> List[Dict[str, Any]]:
    """금융기관 상세 자산 막대 호버 차트용 시계열."""
    if actor is None:
        return []
    live = None
    if world is not None:
        if kind == "central_bank":
            live = central_bank_asset_mix_snapshot(world, actor)
        elif kind == "commercial_bank":
            live = commercial_bank_asset_mix_snapshot(world, actor)
        elif kind == "investment_bank":
            live = investment_bank_asset_mix_snapshot(world, actor)
    return asset_mix_history_payload(actor, live)


def serialize_actor_mortgages(
    world: "World", actor: Any, *, limit: int = 8,
) -> List[Dict[str, Any]]:
    """주체 부동산담보대출 UI 행."""
    rows: List[Dict[str, Any]] = []
    for mid in getattr(actor, "mortgages", None) or []:
        mtg = world.mortgages.get(mid)
        if mtg is None:
            continue
        prin = float(getattr(mtg, "principal", 0.0) or 0.0)
        if prin <= 1e-9:
            continue
        sid, kind = parse_re_holdings_key(str(getattr(mtg, "collateral_key", "") or ""))
        st = world.states.get(sid)
        kind_label = RE_KIND_LABELS.get(kind, kind) if kind else "담보"
        bank = world.banks.get(getattr(mtg, "bank_id", "") or "")
        rows.append({
            "id": mid,
            "label": f"{getattr(st, 'name', sid) or sid} · {kind_label}",
            "principal": round(prin, 2),
            "rate_pct": round(float(getattr(mtg, "rate", 0.0) or 0.0) * 100.0, 2),
            "ltv_pct": round(float(getattr(mtg, "ltv", 0.0) or 0.0) * 100.0, 1),
            "weeks_delinquent": int(getattr(mtg, "weeks_delinquent", 0) or 0),
            "bank_name": getattr(bank, "name", "") or str(getattr(mtg, "bank_id", "") or ""),
        })
    rows.sort(key=lambda r: -float(r.get("principal", 0.0) or 0.0))
    return rows[:limit]


def serialize_pop_mortgages(
    world: "World", pop: "POP", *, limit: int = 8,
) -> List[Dict[str, Any]]:
    return serialize_actor_mortgages(world, pop, limit=limit)


def load_preset_currencies() -> Dict[str, Dict[str, str]]:
    """preset_worlds.json currencies: 국가별 통화 기호·명칭."""
    raw = PRESET_WORLDS.get("currencies", {})
    default = raw.get("_default", {"symbol": "¤", "name": "통화"})
    result: Dict[str, Dict[str, str]] = {
        "_default": {
            "symbol": str(default.get("symbol", "¤")),
            "name": str(default.get("name", "통화")),
        }
    }
    for country_id, entry in raw.items():
        if str(country_id).startswith("_"):
            continue
        if isinstance(entry, dict):
            result[str(country_id)] = {
                "symbol": str(entry.get("symbol", result["_default"]["symbol"])),
                "name": str(entry.get("name", "")),
            }
        else:
            result[str(country_id)] = {"symbol": str(entry), "name": ""}
    return result


CURRENCY_PRESETS = load_preset_currencies()


def pick_preset_currency(country_id: str, country_name: str = "") -> Tuple[str, str]:
    entry = CURRENCY_PRESETS.get(country_id, CURRENCY_PRESETS.get("_default", {}))
    symbol = entry.get("symbol", "¤")
    name = entry.get("name") or (f"{country_name}화" if country_name else "통화")
    return symbol, name


def apply_country_preset_currencies(countries: Dict[str, "Country"]) -> None:
    for cid, country in countries.items():
        symbol, name = pick_preset_currency(cid, country.name)
        country.currency_symbol = symbol
        country.currency = name


def country_initial_social_tech_level(country_id: str) -> int:
    return SOCIAL_TECH_START_LEVEL_PRESETS.get(
        country_id, SOCIAL_TECH_START_LEVEL_PRESETS.get("_default", 0))


def apply_country_initial_social_tech_levels(countries: Dict[str, "Country"]) -> None:
    for cid, country in countries.items():
        set_country_social_tech_level(country, country_initial_social_tech_level(cid))


def load_sme_coop_policy_presets() -> Dict[str, Dict[str, float]]:
    """preset_worlds.json sme_coop_policy_presets: 국가별 협력·소규모·관련 기업 정책 강도."""
    raw = PRESET_WORLDS.get("sme_coop_policy_presets", {})
    if not isinstance(raw, dict):
        return {"_default": {k: 0.0 for k in SME_POLICY_KEYS}}
    known = set(SME_POLICY_KEYS) | set(CORP_POLICY_KEYS)
    out: Dict[str, Dict[str, float]] = {}
    for cid, row in raw.items():
        if not isinstance(row, dict):
            continue
        packed: Dict[str, float] = {}
        for key, val in row.items():
            k = str(key)
            if k not in known:
                continue
            packed[k] = clamp(float(val or 0.0), 0.0, 100.0)
        out[str(cid)] = packed
    out.setdefault("_default", {k: 0.0 for k in SME_POLICY_KEYS})
    return out


SME_COOP_POLICY_PRESETS = load_sme_coop_policy_presets()


def country_sme_coop_policy_preset(country_id: str) -> Dict[str, float]:
    base = dict(SME_COOP_POLICY_PRESETS.get("_default") or {})
    overlay = SME_COOP_POLICY_PRESETS.get(str(country_id or "")) or {}
    base.update(overlay)
    return base


def apply_country_sme_coop_policy_presets(countries: Dict[str, "Country"]) -> None:
    """월드 생성 시 국가별 협력·소규모 기업 정책 슬라이더를 프리셋으로 세팅."""
    for cid, country in countries.items():
        row = country_sme_coop_policy_preset(cid)
        for key in SME_POLICY_KEYS:
            if key in row:
                set_country_sme_policy_intensity(country, key, row[key])
        for key in CORP_POLICY_KEYS:
            if key in row:
                set_country_corp_intensity(country, key, row[key])


def pick_preset_company_name(
    country_id: str, company_type: str, fallback: Optional[str] = None,
) -> str:
    """국가·직종 프리셋에서 기업 이름을 무작위 선택 (중복 검사 없음)."""
    ctype = normalize_company_type(company_type)
    country_pool = COMPANY_NAME_PRESETS.get(resolve_name_preset_key(country_id), {})
    names = list(country_pool.get(ctype, []) or [])
    if not names:
        # 레거시 SME 키 폴백
        names = list(country_pool.get(company_type, []) or [])
    if not names:
        names = list(COMPANY_NAME_PRESETS.get("_default", {}).get(ctype, []) or [])
    if not names:
        names = list(COMPANY_NAME_PRESETS.get("_default", {}).get(company_type, []) or [])
    if names:
        return random.choice(names)
    if fallback is not None:
        return fallback
    return ctype


def pick_distinct_preset_names(
    country_id: str, company_type: str, count: int,
    used_names: Set[str], fallback_prefix: str,
) -> List[str]:
    """국가·직종 프리셋에서 서로 겹치지 않는 이름을 count개 선택한다.

    - 프리셋 풀에서 이미 사용된 이름을 제외하고 무작위 순서로 배정.
    - 풀이 고갈되면 '{fallback_prefix}{n}' 형태의 고유 이름을 생성.
    """
    ctype = normalize_company_type(company_type)
    key = resolve_name_preset_key(country_id)
    pool = list(COMPANY_NAME_PRESETS.get(key, {}).get(ctype, []) or [])
    if not pool:
        pool = list(COMPANY_NAME_PRESETS.get("_default", {}).get(ctype, []) or [])
    random.shuffle(pool)
    chosen: List[str] = []
    for i in range(max(0, count)):
        name = next((c for c in pool if c not in used_names), None)
        if name is None:
            n = 1
            name = f"{fallback_prefix}{n}"
            while name in used_names:
                n += 1
                name = f"{fallback_prefix}{n}"
        used_names.add(name)
        chosen.append(name)
    return chosen


def world_used_company_names(world: "World") -> Set[str]:
    used = {co.name for co in world.companies.values() if getattr(co, "name", None)}
    for bank in world.banks.values():
        if getattr(bank, "name", None):
            used.add(bank.name)
    for ib in world.investment_banks.values():
        if getattr(ib, "name", None):
            used.add(ib.name)
    for cb in world.central_banks.values():
        if getattr(cb, "name", None):
            used.add(cb.name)
    return used


def company_type_brand_suffix(company_type: str) -> str:
    """계열 상호용 직종 짧은 접미 (화학 기업 → 화학)."""
    ctype = normalize_company_type(company_type)
    if ctype in SME_SHORT_LABELS:
        return SME_SHORT_LABELS[ctype]
    s = str(ctype or "").replace(" 중소기업", "").replace(" 기업", "").strip()
    return s or ctype or "산업"


