# 한국 재벌식 로마자 브랜드 (LG전자 — GE어플라이언스식과 구분)
CORP_KOREAN_LATIN_BRANDS = frozenset({"LG", "SK", "CJ", "GS", "KT", "HD"})


def _brand_uses_latin_group_suffix(brand: str) -> bool:
    brand = str(brand or "").strip()
    if not brand or not brand.isascii():
        return False
    return brand.upper() not in CORP_KOREAN_LATIN_BRANDS


def company_type_group_name_suffix(company_type: str, brand: str = "") -> str:
    """그룹 계열 상호용 접미. 영문 브랜드는 GE어플라이언스식, 한글/LG는 삼성전자식."""
    ctype = normalize_company_type(company_type)
    brand = str(brand or "").strip()
    table = (
        CORP_GROUP_NAME_SUFFIX_LATIN
        if _brand_uses_latin_group_suffix(brand)
        else CORP_GROUP_NAME_SUFFIX_KO
    )
    if ctype in table:
        return table[ctype]
    return company_type_brand_suffix(ctype)


# 계열사 상호 스템 — 모회사명과 무관한 기업형 상호 (마이크론 화학 등)
CORP_AFFILIATE_NAME_STEMS: Tuple[str, ...] = (
    "마이크론", "오리온", "네오", "헬리오스", "폴라리스", "아폴로", "젠시스",
    "아크론", "베가", "시리우스", "노바", "퀀텀", "솔라", "메티스", "아이리스",
    "카이로스", "아틀라스", "헤르메스", "포세이돈", "아레스",
)


def company_industry_label_for_name(co: "Company") -> str:
    """생산·직종 기준 상호 접미. 상품명 나열 대신 산업 라벨 (화학, 반도체…)."""
    if company_is_coop_partner(co):
        specialty = str(getattr(co, "coop_specialty", "") or "").strip()
        if specialty:
            label = specialty
            for cut in (" 및 ", "·"):
                if cut in label:
                    label = label.split(cut, 1)[0].strip()
            for suf in (" 제품", " 서비스", " 상품"):
                if label.endswith(suf):
                    label = label[: -len(suf)].strip()
                    break
            return label or "협력"
        return "협력"
    return company_type_brand_suffix(getattr(co, "type", "") or "")


def _coop_specialty_company_type(specialty: str) -> str:
    """협력 활동 → 이름 풀용 직종 (있으면)."""
    s = str(specialty or "").strip()
    if not s:
        return COOP_PARTNER_TYPE
    candidates = [
        f"{s} 기업",
        f"{s.replace(' 제품', '').strip()} 기업",
        f"{s.replace(' 서비스', '').strip()} 기업",
    ]
    for ctype in candidates:
        for pool in COMPANY_NAME_PRESETS.values():
            if ctype in (pool or {}):
                return ctype
    return COOP_PARTNER_TYPE


def company_group_brand(world: "World", root_id: str) -> str:
    """루트 상호에서 그룹 표시용 브랜드 추출 (UI 배지). 자회사 개명에는 쓰지 않음."""
    root = world.companies.get(root_id) if world else None
    if root is None:
        return ""
    cached = str(getattr(root, "group_brand", "") or "").strip()
    if cached:
        return cached
    name = str(getattr(root, "name", "") or "").strip()
    if not name:
        return ""
    for brand in CORP_KNOWN_BRANDS:
        if name == brand or name.startswith(brand + " ") or name.startswith(brand):
            # 'GE' vs 'General' 오탐 방지: 알려진 브랜드만, 한글은 startswith OK
            if brand.isascii() and len(brand) <= 3:
                if name == brand or name.startswith(brand + " ") or name.startswith(brand + "-"):
                    setattr(root, "group_brand", brand)
                    return brand
                continue
            setattr(root, "group_brand", brand)
            return brand
    stem = name
    # 긴 접미부터 제거
    for suf in sorted(CORP_BRAND_STRIP_SUFFIXES, key=len, reverse=True):
        if stem.endswith(suf) and len(stem) > len(suf):
            stem = stem[: -len(suf)].strip(" -·_")
            break
        spaced = f" {suf}"
        if spaced in stem:
            stem = stem.split(spaced, 1)[0].strip()
            break
    if " " in stem:
        stem = stem.split()[0]
    brand = stem.strip() or name
    setattr(root, "group_brand", brand)
    return brand


def _synthesize_affiliate_company_name(world: "World", industry: str) -> str:
    """'{스템} {산업}' 상호 생성 (마이크론 화학)."""
    used = world_used_company_names(world)
    industry = str(industry or "기업").strip() or "기업"
    stems = list(CORP_AFFILIATE_NAME_STEMS)
    random.shuffle(stems)
    for stem in stems:
        cand = f"{stem} {industry}".strip()
        if cand not in used:
            return cand
    n = 2
    while True:
        cand = f"{random.choice(CORP_AFFILIATE_NAME_STEMS)} {industry} {n}"
        if cand not in used:
            return cand
        n += 1


def historical_group_branded_name(
    brand: str,
    company_type: str,
    *,
    used: Optional[Set[str]] = None,
) -> str:
    """브랜드+직종 계열 상호 (삼성전자 / GE어플라이언스)."""
    brand = str(brand or "").strip()
    used = used or set()
    if not brand:
        return ""
    stem = company_type_group_name_suffix(company_type, brand) or "계열"
    latin = _brand_uses_latin_group_suffix(brand)
    if latin:
        bases = [f"{brand}{stem}", f"{brand} {stem}", f"{brand}-{stem}", brand]
    else:
        bases = [f"{brand}{stem}", f"{brand} {stem}", f"{brand}계열"]
    for base in bases:
        if base and base not in used:
            return base
    n = 2
    base0 = bases[0] if bases else f"{brand}계열"
    while True:
        cand = f"{base0}{n}" if latin else f"{base0} {n}"
        if cand not in used:
            return cand
        n += 1


def apply_historical_group_member_name(world: "World", co_id: str, brand: str) -> str:
    """역사적 그룹 편입 후 자회사 상호를 브랜드 계열명으로 바꾼다.

    영문 브랜드(GE)는 GE어플라이언스식으로 정규화.
    한글 브랜드(삼성)는 이미 브랜드 접두면 유지(삼성물산).
    """
    co = world.companies.get(co_id) if world else None
    if co is None:
        return ""
    brand = str(brand or "").strip()
    cur = str(getattr(co, "name", "") or "").strip()
    if not brand:
        return cur
    ctype = normalize_company_type(getattr(co, "type", "") or "")
    used = world_used_company_names(world)
    used.discard(cur)
    latin = _brand_uses_latin_group_suffix(brand)
    if (not latin) and _company_name_has_group_brand(cur, brand):
        co.group_affiliate_named = True
        return cur
    name = historical_group_branded_name(brand, ctype, used=used)
    if name:
        co.name = name
    co.group_affiliate_named = True
    return str(getattr(co, "name", "") or "")


def apply_historical_group_root_name(world: "World", root_id: str, brand: str) -> str:
    """역사 그룹 모기업 상호를 브랜드 계열명으로 맞춘다 (→ GE일렉트릭)."""
    root = world.companies.get(root_id) if world else None
    if root is None:
        return ""
    brand = str(brand or "").strip()
    cur = str(getattr(root, "name", "") or "").strip()
    if not brand:
        return cur
    setattr(root, "group_brand", brand)
    ctype = normalize_company_type(getattr(root, "type", "") or "")
    used = world_used_company_names(world)
    used.discard(cur)
    latin = _brand_uses_latin_group_suffix(brand)
    if (not latin) and _company_name_has_group_brand(cur, brand):
        return cur
    name = historical_group_branded_name(brand, ctype, used=used)
    if name:
        root.name = name
    return str(getattr(root, "name", "") or "")


def _company_name_has_group_brand(name: str, brand: str) -> bool:
    """상호가 그룹 브랜드로 시작하는지 (GE 컴퓨터, 삼성물산, LG전자)."""
    cur = str(name or "").strip()
    brand = str(brand or "").strip()
    if not cur or not brand:
        return False
    if cur == brand:
        return True
    if (
        cur.startswith(brand + " ")
        or cur.startswith(brand + "·")
        or cur.startswith(brand + "-")
    ):
        return True
    # 한글 브랜드 붙여쓰기 (삼성물산)
    if any(ord(ch) > 127 for ch in brand) and cur.startswith(brand):
        return True
    # 영문 브랜드 + 한글 접미 붙여쓰기 (LG전자)
    if (
        brand.isascii()
        and cur.startswith(brand)
        and len(cur) > len(brand)
        and not cur[len(brand)].isascii()
    ):
        return True
    return False


def apply_group_brand_name(world: "World", co_id: str) -> str:
    """과반 계열 편입 후 자회사 상호.

    이미 그룹 브랜드 접두(GE 컴퓨터·삼성물산)면 유지한다.
    그 외 신규 계열은 직종·국가 풀 또는 '{스템} {산업}' 상호를 쓴다.
    """
    co = world.companies.get(co_id) if world else None
    if co is None:
        return ""
    root_id = company_group_root(world, co_id)
    if root_id == co_id:
        return str(getattr(co, "name", "") or "")
    cur = str(getattr(co, "name", "") or "").strip()
    root_brand = company_group_brand(world, root_id)
    industry = company_industry_label_for_name(co)
    # 역사·브랜드 계열 상호는 풀 이름으로 덮지 않음
    if _company_name_has_group_brand(cur, root_brand):
        co.group_affiliate_named = True
        return cur
    product_like = bool(
        industry and (cur == industry or cur == f"{industry} 제품")
    )
    st = world.states.get(getattr(co, "home_state", ""))
    country_id = str(getattr(st, "country_id", "") or "") if st else ""
    if company_is_coop_partner(co):
        ctype = _coop_specialty_company_type(
            str(getattr(co, "coop_specialty", "") or ""))
    else:
        ctype = normalize_company_type(getattr(co, "type", "") or "")
    preset_key = resolve_name_preset_key(country_id) if country_id else ""
    is_korean_preset = (
        preset_key == "_default"
        or country_id in ("KR", "KOR", "한국", "대한민국")
    )
    # 타국인데 한국 _default 풀 이름이 붙어 있으면 교정 대상으로 본다
    wrong_locale = False
    if cur and ctype and not is_korean_preset:
        kr_pool = {
            str(n).strip()
            for n in ((COMPANY_NAME_PRESETS.get("_default") or {}).get(ctype, []) or [])
            if str(n or "").strip()
        }
        wrong_locale = cur in kr_pool
    already = bool(getattr(co, "group_affiliate_named", False))
    if already and cur and not product_like and not wrong_locale:
        return cur
    name = ""
    # 1) 해당 국가 이름 풀만 사용 (_default 한국식 풀을 타국에 섞지 않음)
    if country_id and ctype:
        used = world_used_company_names(world)
        used.discard(cur)
        if is_korean_preset:
            pool = list((COMPANY_NAME_PRESETS.get("_default") or {}).get(ctype, []) or [])
        else:
            pool = list((COMPANY_NAME_PRESETS.get(preset_key) or {}).get(ctype, []) or [])
        free = [str(n).strip() for n in pool if str(n or "").strip() and str(n).strip() not in used]
        industry_hits: List[str] = []
        if industry:
            industry_hits = [n for n in free if industry in n]
        if industry_hits:
            name = random.choice(industry_hits)
        elif free:
            # 산업 문자열이 이름에 없어도(다우 케미컬 등) 국가 풀 우선
            name = random.choice(free)
    # 2) 없으면 '{스템} {산업}' (마이크론 화학) — 국가 풀 고갈·미정의 시
    if not name:
        name = _synthesize_affiliate_company_name(world, industry)
    co.name = name
    co.group_affiliate_named = True
    return name


def pick_company_name(
    world: "World",
    country_id: str,
    company_type: str,
    fallback: Optional[str] = None,
) -> str:
    """미사용 이름 우선. 풀이 고갈되면 재사용 허용."""
    ctype = normalize_company_type(company_type)
    used = world_used_company_names(world)
    preset_key = resolve_name_preset_key(country_id)
    country_pool = COMPANY_NAME_PRESETS.get(preset_key, {})
    default_pool = COMPANY_NAME_PRESETS.get("_default", {})
    legacy_keys = [old for old, new in LEGACY_SME_TYPE_MAP.items() if new == ctype]

    def _collect(pool: Dict[str, List[str]]) -> List[str]:
        names: List[str] = []
        for key in [ctype, company_type, *legacy_keys]:
            for name in pool.get(key, []) or []:
                if name and str(name) not in names:
                    names.append(str(name))
        return names

    # 해당 국가 프리셋을 우선 사용. 국가 풀이 비어 있을 때만 기본(_default)로 폴백.
    # (국가 이름 풀에 한국식 기본 이름이 섞여 들어가지 않도록 분리)
    candidates = _collect(country_pool)
    if not candidates:
        candidates = _collect(default_pool)
    free = [n for n in candidates if n not in used]
    if free:
        return random.choice(free)
    if candidates:
        return random.choice(candidates)
    if fallback is not None and fallback not in used:
        return fallback
    n = 1
    while True:
        name = f"{ctype} {n}" if fallback is None else f"{fallback} {n}"
        if name not in used:
            return name
        n += 1


def pick_sme_company_name(
    world: "World",
    country_id: str,
    state_id: str,
    sme_type: str,
    index: int,
) -> str:
    """하위 호환 래퍼 → pick_company_name."""
    st = world.states.get(state_id)
    short = SME_SHORT_LABELS.get(sme_type, normalize_company_type(sme_type))
    fallback = f"{st.name if st else state_id} {short} {index + 1}"
    return pick_company_name(world, country_id, sme_type, fallback)


PRESET_BANK_NAME_TYPE = "은행"
PRESET_INVESTMENT_BANK_NAME_TYPE = "금융투자은행"
PRESET_CENTRAL_BANK_NAME_TYPE = "중앙은행"


class BankRegistry(dict):
    """은행/금투은행 레지스트리 — bank_id로 키잉하되, country_id로 조회하면
    해당 국가의 대표(첫 번째) 주체를 반환하여 다수 은행 전환의 하위호환을 제공한다."""

    def __init__(self, prefix: str = ""):
        super().__init__()
        self._prefix = prefix
        self._country_first: Dict[str, Any] = {}
        self._country_index_dirty: bool = True

    def _mark_country_index_dirty(self) -> None:
        self._country_index_dirty = True

    def _rebuild_country_index(self) -> None:
        first: Dict[str, Any] = {}
        for v in self.values():
            cid = getattr(v, "country_id", None)
            if cid is not None and cid not in first:
                first[cid] = v
        self._country_first = first
        self._country_index_dirty = False

    def _first_in_country(self, country_id: str):
        if self._country_index_dirty:
            self._rebuild_country_index()
        return self._country_first.get(country_id)

    def get(self, key, default=None):
        if dict.__contains__(self, key):
            return dict.__getitem__(self, key)
        found = self._first_in_country(key)
        if found is not None:
            return found
        if self._prefix and isinstance(key, str) and not key.startswith(self._prefix):
            pid = f"{self._prefix}{key}"
            if dict.__contains__(self, pid):
                return dict.__getitem__(self, pid)
        return default

    def __getitem__(self, key):
        if dict.__contains__(self, key):
            return dict.__getitem__(self, key)
        found = self.get(key)
        if found is None:
            raise KeyError(key)
        return found

    def __contains__(self, key):
        # 엄격한 실제 키(bank_id) 멤버십만 — 국가 id 오분류 방지
        return dict.__contains__(self, key)

    def __setitem__(self, key, value):
        dict.__setitem__(self, key, value)
        self._mark_country_index_dirty()

    def __delitem__(self, key):
        dict.__delitem__(self, key)
        self._mark_country_index_dirty()

    def clear(self):
        dict.clear(self)
        self._country_first = {}
        self._country_index_dirty = False

    def pop(self, key, *args):
        result = dict.pop(self, key, *args)
        self._mark_country_index_dirty()
        return result

    def popitem(self):
        result = dict.popitem(self)
        self._mark_country_index_dirty()
        return result

    def setdefault(self, key, default=None):
        if dict.__contains__(self, key):
            return dict.__getitem__(self, key)
        dict.__setitem__(self, key, default)
        self._mark_country_index_dirty()
        return default

    def update(self, other=(), /, **kwargs):
        dict.update(self, other, **kwargs)
        self._mark_country_index_dirty()


