class World:
    def _issuer_country(self, issuer: str) -> Optional[str]:
        # 기업 주식/회사채
        if issuer in self.companies:
            st = self.states.get(self.companies[issuer].home_state)
            return st.country_id if st else None
        if issuer.startswith("local_"):
            return bond_market_country_id(self, issuer) or None
        if issuer.startswith("gov_"):
            rest = issuer[4:]
            if rest in self.countries:
                return rest
            for st in self.states.values():
                if st.local_government.id == issuer:
                    return st.country_id
            return rest if rest in self.countries else None
        return bond_market_country_id(self, issuer) or None

    def _holder_country(self, holder: Any) -> Optional[str]:
        if isinstance(holder, Company):
            st = self.states.get(holder.home_state)
            return st.country_id if st else None
        if isinstance(holder, Bank) or isinstance(holder, CentralBank) or isinstance(holder, InvestmentBank):
            return holder.country_id
        if isinstance(holder, POP):
            return self.states.get(holder.state_id).country_id if holder.state_id in self.states else None
        if isinstance(holder, Country):
            return holder.id
        return None
