    def _prepare_finance_caches(
        self, *, rebuild_indexes: bool = False, clear_profiles: bool = True,
    ) -> None:
        """금융 핫패스용 인덱스·프로파일 캐시 준비.

        주문 수집 전에 호출한다. 체결 정산은 BuyResult.allow_loan만
        사용하므로 정산 직전 프로파일 재워밍이 필요 없다.
        """
        if rebuild_indexes:
            self._fin_idx_companies_by_country = None
            self._fin_idx_states_by_country = None
            self._fin_idx_pops = None
            self._fin_idx_local_gov = None
            self._fin_idx_stock_by_country = None
            self._fin_cache_bond_country.clear()
            self._fin_cache_avg_tech = None
        if clear_profiles:
            self._fin_cache_bond_profile.clear()
            if not hasattr(self, "_fin_cache_bond_credit_risk"):
                self._fin_cache_bond_credit_risk = {}
            self._fin_cache_bond_credit_risk.clear()
            self._fin_cache_stock_profile.clear()
            self._fin_cache_bond_rate.clear()
            self._fin_cache_credit_profile.clear()
            self._fin_cache_credit_spot.clear()
            self._fin_cache_country_credit_spot.clear()
            self._fin_cache_country_gdp.clear()
            self._fin_cache_issuer_country.clear()
            self._fin_cache_country_equity_val.clear()
            self._fin_cache_country_stock_signal.clear()
            if not hasattr(self, "_fin_cache_country_market_stress"):
                self._fin_cache_country_market_stress = {}
            else:
                self._fin_cache_country_market_stress.clear()
            if not hasattr(self, "_fin_cache_issuer_book"):
                self._fin_cache_issuer_book = {}
            else:
                self._fin_cache_issuer_book.clear()
            flow_sig = getattr(self, "_fin_cache_stock_flow_signal", None)
            if flow_sig is None:
                self._fin_cache_stock_flow_signal = {}
            else:
                flow_sig.clear()
            self._fin_cache_world_stock_signal = None
            self._fin_cache_world_stock_signal_ready = False
            self._fin_cache_stock_horizons.clear()
            self._fin_cache_ib_stock_scores_by_style.clear()
            self._fin_cache_ib_bond_country_attr.clear()
            self._fin_cache_ib_bond_scores_country.clear()
            self._fin_cache_stock_expected_yield.clear()
            if not hasattr(self, "_fin_cache_ib_mixed_fv"):
                self._fin_cache_ib_mixed_fv = {}
            self._fin_cache_ib_mixed_fv.clear()
            if not hasattr(self, "_fin_cache_ib_name_score"):
                self._fin_cache_ib_name_score = {}
            self._fin_cache_ib_name_score.clear()
            if not hasattr(self, "_fin_cache_ib_macro_factors"):
                self._fin_cache_ib_macro_factors = {}
            self._fin_cache_ib_macro_factors.clear()
            if not hasattr(self, "_fin_cache_stock_regime_logits"):
                self._fin_cache_stock_regime_logits = {}
            self._fin_cache_stock_regime_logits.clear()
            if not hasattr(self, "_fin_cache_regime_weights"):
                self._fin_cache_regime_weights = {}
            self._fin_cache_regime_weights.clear()
            raw_ns = getattr(self, "_fin_cache_ib_name_score_raw", None)
            if raw_ns is not None:
                raw_ns.clear()
            clear_stock_held_cache(self)
            if not hasattr(self, "_fin_cache_industry_avg"):
                self._fin_cache_industry_avg = {}
            else:
                self._fin_cache_industry_avg.clear()
            if not hasattr(self, "_fin_cache_pop_sec_weights"):
                self._fin_cache_pop_sec_weights = {}
            else:
                self._fin_cache_pop_sec_weights.clear()
            if not hasattr(self, "_fin_cache_pop_name_score"):
                self._fin_cache_pop_name_score = {}
            else:
                self._fin_cache_pop_name_score.clear()
        self._ensure_finance_indexes()
        # 유통주식 O(1) 조회용 — 금융 주문 전 반드시 1회 워밍
        ensure_stock_held_cache(self)
        if clear_profiles:
            self._warm_finance_valuation_profiles()
            self._warm_finance_stock_aux_caches()

    def _warm_finance_valuation_profiles(self) -> None:
        """포트폴리오 주문·체결 정산 직전 신용·valuation profile 선계산.

        주식 프로파일 → 국가 벨류/stress → 신용 → 채권 프로파일 순으로 데워
        신용 워밍이 주식 벨류를 거꾸로 끌어올리는 중복 계산을 제거한다.
        """
        stock_ids = list(self.stock_markets.keys())
        bond_keys = list(self.bond_markets.keys())
        _parallel_warm_finance_profiles(self, [], stock_ids)
        _stock_issuer_ids_by_country(self)
        for cid in self.countries:
            ib_country_equity_valuation_signal(self, cid)
        _warm_all_credit_profiles(self)
        _parallel_warm_finance_profiles(self, bond_keys, [])

    def _warm_finance_stock_aux_caches(self) -> None:
        """IB 주식 점수용 국가·horizon 보조 캐시 선계산 (수치 동등)."""
        for iid in self.stock_markets:
            issuer_stock_country_id(self, iid)
            stock_issuer_expected_return_horizons(self, iid)
            stock_issuer_expected_yield_pct(self, iid)
        for cid in self.countries:
            ib_country_equity_valuation_signal(self, cid)
            country_expected_stock_signal(self, cid)
        # 국가 시그널 워밍이 종목 캐시를 채운 뒤 월드 평균을 1회 확정
        world_expected_stock_signal(self)

    def _ensure_finance_indexes(self) -> None:
        if self._fin_idx_companies_by_country is None:
            by_c: Dict[str, List[Company]] = defaultdict(list)
            for co in self.companies.values():
                st = self.states.get(co.home_state)
                if st is not None:
                    by_c[st.country_id].append(co)
            self._fin_idx_companies_by_country = dict(by_c)
        if self._fin_idx_states_by_country is None:
            by_s: Dict[str, List[State]] = defaultdict(list)
            for st in self.states.values():
                by_s[st.country_id].append(st)
            self._fin_idx_states_by_country = dict(by_s)
        if self._fin_idx_pops is None:
            pops: Dict[str, POP] = {}
            for st in self.states.values():
                for pop in st.pops:
                    pops[pop.id] = pop
            self._fin_idx_pops = pops
        if self._fin_idx_local_gov is None:
            self._fin_idx_local_gov = {
                st.local_government.id: st for st in self.states.values()
            }
        if self._fin_cache_avg_tech is None:
            companies = list(self.companies.values())
            self._fin_cache_avg_tech = (
                sum(c.tech_level for c in companies) / max(len(companies), 1)
            )

