        """매주 턴 시작 시 무역·호가·정산 핫패스 캐시 무효화."""
        clear_goods_peer_price_cache()
        self._logistics_by_country = None
        self._logistics_weight_parts = None
        self._logistics_split_cache = None
        self._cache_trade_flows_by_country = None
        self._markets_by_state = None
        self._bond_held_totals_cache = None
        self._cache_country_stock_caps = None
        self._cache_describe_stock_issuer = {}
        self._cache_describe_market_entity = {}
        self._cache_calendar_date = None
        self._cache_inflation_index_series = None
        self._pop_cpi_cache = {}
        self._pop_cpi_cache_week = -1
        self._pop_security_fill_cache = {}
        self._pop_security_fill_cache_week = -1
        self._pop_env_density_cache = {}
        self._pop_env_density_cache_week = -1
        invalidate_stock_flow_signal_caches(self)
        self._trade_sell_order_buf = None
        self._trade_buy_order_buf = None
        self._trade_ask_cache = None
        self._trade_svc_cache = None
        self._trade_sale_route_buf = None
        self._trade_dest_cap_keys = set()
        self._trade_dest_demand = {}
        self._trade_dest_book_sell = {}
        self._trade_dest_reserved = {}
        self._trade_reserved_ready = False
        self._fob_dest_snap = {}
        self._fob_demand_dests_cache = {}
        self._fill_goods_by_actor = None
        self._fill_labor_by_actor = None
        self._fill_buy_qty = None
        self._fill_buy_ordered = None
        self._fill_buy_tech = None
        self._fill_buy_results = None
        self._fill_sell_qty = None
        self._fill_sell_qty_foreign = None
        self._fill_sell_results = None
        self._fill_labor_ordered = None
        self._fill_labor_filled = None
        self._fill_labor_results = None
        self._fob_sell_ordered_totals = None
        self._labor_mrpl_employer_index = None
        self._mortgage_active_index = None
        self._mortgage_contract_index = None
        self._trade_fx_ref_cache = None
        clear_occupation_week_caches()
        clear_stock_mark_price_cache(self)
        if not hasattr(self, "_fin_cache_industry_avg"):
            self._fin_cache_industry_avg = {}
