    def get_local_government_report(self, state_id: str) -> Dict[str, Any]:
        st = self.states.get(state_id)
        if not st:
            return {}
        gov = st.local_government
        gov._consolidate_public_facilities()
        country = self.countries.get(st.country_id)
        pop_total = sum(p.total_population() for p in st.pops)
        req = self._state_public_requirement(st)
        private_fac_count = sum(
            len(c.facilities) for c in self.companies.values() if c.home_state == st.id)
        services: List[Dict[str, Any]] = []
        installed = gov.installed_service_capacity()
        fill = gov.operation_fill_ratio
        current_map = government_planning_current(
            st, installed, fill, country=country, world=self)
        for key, spec in PUBLIC_SERVICE_SPECS.items():
            if key in ("road", "port", "rail"):
                current = st.infrastructure.get(key, 0.0)
            else:
                current = current_map.get(key, st.capacity.get(key, 0.0))
            services.append({
                "key": key,
                "name": spec["name"],
                "current": round(current, 1),
                "installed": round(installed.get(key, 0.0) if key in installed else current, 1),
                "required": round(req.get(key, 0.0), 1),
                "operation_fill": round(fill, 2),
            })
        facilities = []
        for fac in gov.public_facilities:
            service = gov._service_key_for_facility(fac.name)
            spec = PUBLIC_SERVICE_SPECS.get(service, {})
            op = PUBLIC_OPERATION_SPECS.get(service, {})
            active = fac.active_levels()
            unit_cap = float(spec.get("capacity", 0.0) or 0.0)
            max_cap = unit_cap * float(fac.level)
            capacity_cap = unit_cap * float(active)
            output_qty = float(op.get("output_qty", 0) or 0.0)
            fill = float(getattr(gov, "operation_fill_ratio", 1.0) or 0.0)
            eff = public_operation_efficiency(service, country=country)
            actual_output = (
                output_qty * float(active) * fill * eff if output_qty > 0 else 0.0)
            uc = int(fac.under_construction or 0)
            c_target = float(getattr(fac, "construction_target", 0.0) or 0.0)
            c_prog = float(getattr(fac, "construction_progress", 0.0) or 0.0)
            c_ratio = (c_prog / c_target) if c_target > 1e-9 else 0.0
            labor_req = op.get("labor")
            labor_type = ""
            labor_needed = 0.0
            if labor_req and active > 0:
                labor_type = str(labor_req[0])
                labor_needed = float(labor_req[1]) * active
            input_rows = [
                {
                    "item": item,
                    "ordered": round(float(qty) * active, 2),
                    "filled": round(float(qty) * active * fill, 2),
                    "ratio": round(fill, 3),
                }
                for item, qty in (op.get("inputs") or {}).items()
            ] if active > 0 else []
            facilities.append({
                "index": len(facilities),
                "service": service,
                "name": fac.name,
                "level": fac.level,
                "closed": fac.closed_levels,
                "active": active,
                "active_levels": active,
                "under_construction": uc,
                "construction_ratio": round(max(0.0, min(1.0, c_ratio)), 3),
                "max_output": round(max_cap if unit_cap > 0 else output_qty * float(fac.level), 2),
                "capacity_output": round(capacity_cap if unit_cap > 0 else output_qty * float(active), 2),
                "actual_output": round(actual_output if output_qty > 0 else capacity_cap * fill, 2),
                "overall_efficiency": round(fill, 3),
                "input_fill": round(fill, 3),
                "product": op.get("output") or "",
                "is_infrastructure": service in PUBLIC_INFRASTRUCTURE_SERVICES,
                "labor": {
                    "type": labor_type,
                    "needed": round(labor_needed, 2),
                    "filled": round(labor_needed * fill, 2),
                    "ratio": round(fill, 3),
                } if labor_type else {},
                "input_fills": input_rows,
                "optional_fills": [],
            })
        projects = []
        for fac in gov.public_facilities:
            if fac.under_construction <= 0:
                continue
            service_key = gov._service_key_for_facility(fac.name)
            spec = PUBLIC_SERVICE_SPECS.get(service_key, {})
            target = float(
                fac.construction_target or spec.get("construction", 0.0) or 0.0)
            remaining = max(0.0, target - float(fac.construction_progress or 0.0))
            projects.append({
                "service": fac.name,
                "remaining": round(remaining, 1),
                "under_construction": fac.under_construction,
                "construction_ratio": round(
                    (float(fac.construction_progress or 0.0) / target) if target > 1e-9 else 0.0,
                    3,
                ),
            })
        companies_home = sum(1 for c in self.companies.values() if c.home_state == st.id)
        total_levels = sum(int(f.level or 0) for f in gov.public_facilities)
        stance = str(getattr(country, "regional_invest_stance", "balanced") or "balanced") if country else "balanced"
        return {
            "state_id": state_id,
            "state_name": st.name,
            "country_id": st.country_id,
            "country_name": country.name if country else st.country_id,
            "coastal": st.coastal,
            "health": round(st.health, 2),
            "education_access": round(st.education_access, 2),
            "population": round(pop_total, 0),
            "cash": 0.0,
            "deposits": 0.0,
            "bond_balance": 0.0,
            "bond_matured_face": 0.0,
            "bond_locked_face": 0.0,
            "tax_revenue": round(float(getattr(st, "weekly_collected_tax", 0.0) or 0.0), 2),
            "weekly_tax_revenue": round(float(getattr(st, "weekly_collected_tax", 0.0) or 0.0), 2),
            "weekly_operating_cost": round(gov.weekly_operating_cost, 2),
            "weekly_regional_spend": round(float(getattr(gov, "weekly_regional_spend", 0.0) or 0.0), 2),
            "operation_fill_ratio": round(gov.operation_fill_ratio, 2),
            "last_construction_fill": round(gov.last_construction_fill, 2),
            "bond_pending_issue": 0.0,
            "bond_sold_ratio": 1.0,
            "bond_rate": 0.0,
            "fiscal_mode": "central",
            "infra_push": stance in ("export_logistics", "growth"),
            "infra_push_reasons": [],
            "infra_push_reason_labels": [],
            "allocation_note": getattr(gov, "allocation_note", "") or "",
            "allocated": dict(getattr(gov, "allocated_expansions", None) or {}),
            "allocated_reasons": dict(getattr(gov, "allocated_reasons", None) or {}),
            "stance": stance,
            "stance_label": REGIONAL_INVESTMENT_STANCES.get(stance, ""),
            "focused": bool(country and st.id in (getattr(country, "regional_focus_states", None) or [])),
            "frozen": bool(country and st.id in (getattr(country, "regional_frozen_states", None) or [])),
            "bond_capacity_remaining": 0.0,
            "infra_bond_bonus_capacity": 0.0,
            "infra_bond_capacity_remaining": 0.0,
            "services": services,
            "facilities": facilities,
            "facility_levels": total_levels,
            "projects": projects,
            "private_facility_count": private_fac_count,
            "companies_count": companies_home,
        }

    def get_market_report(self, state_id: str, item: str) -> Dict[str, Any]:
        market = self.markets.get(market_key(state_id, item)) or self.labor_markets.get(market_key(state_id, item))
        if not market:
            return {}
        return {
            "state_id": state_id,
            "item": item,
            "price": round(market_settlement_price(market), 2),
            "presettle_buy_volume": round(market_presettle_buy_volume(market), 2),
            "presettle_sell_volume": round(market_presettle_sell_volume(market), 2),
            "traded_volume": round(market_traded_volume(market), 2),
            "buy_orders": len(market.buy_orders),
            "sell_orders": len(market.sell_orders),
        }

    def get_stock_market_report(self, issuer_id: str) -> Dict[str, Any]:
        market = self.stock_markets.get(issuer_id)
        if not market:
            return {}
        label, category, country_id = describe_stock_issuer(self, issuer_id)
        issuer = (
            self.companies.get(issuer_id)
            or self.banks.get(issuer_id.replace("bank_", "", 1) if issuer_id.startswith("bank_") else issuer_id)
            or self.investment_banks.get(issuer_id.replace("ib_", "", 1) if issuer_id.startswith("ib_") else issuer_id)
        )
        shares = getattr(issuer, "stock_shares", 0.0) if issuer else 0.0
        profile = stock_issuer_valuation_profile(self, issuer_id)
        price, ref, _pct = weekly_close_quote(_stock_weekly_prices(self, issuer_id))
        if price <= 1e-12:
            price = float(market.current_price or 0.0)
            ref = price
        realized = (price / ref - 1.0) if ref > 1e-9 else 0.0
        return {
            "issuer_id": issuer_id,
            "name": label,
            "category": category,
            "country_id": country_id,
            "price": round(price, 4),
            "fair_price": round(float(stock_issuer_fair_price(self, issuer_id) or 0.0), 4),
            "presettle_buy_volume": round(market_presettle_buy_volume(market), 2),
            "presettle_sell_volume": round(market_presettle_sell_volume(market), 2),
            "traded_volume": round(market_traded_volume(market), 2),
            "buy_orders": len(market.buy_orders),
            "sell_orders": len(market.sell_orders),
            "price_change": round(realized, 6),
            "shares": round(shares, 2),
            "market_cap": round(shares * market.current_price, 2),
            "book_value": round(float(profile.get("book_value", 0.0) or 0.0), 2),
            "pbr": round(float(profile.get("pbr", 99.0) or 99.0), 2),
            "per": round(float(profile.get("per", 99.0) or 99.0), 2),
            "psg": round(float(profile.get("psg", 99.0) or 99.0), 2),
        }

    def get_bond_market_report(self, market_key_id: str) -> Dict[str, Any]:
        market = self.bond_markets.get(market_key_id)
        if not market:
            return {}
        label, category, country_id = describe_bond_market(self, market_key_id)
        country = self.countries.get(country_id) if country_id else None
        base_rate = country_base_rate(country) if country else 3.5
        spread = bond_market_current_spread(market, base_rate)
        last_chg = (
            float(market.rate_change_history[-1])
            if market.rate_change_history else 0.0)
        return {
            "market_key": market_key_id,
            "name": label,
            "category": category,
            "country_id": country_id,
            "interest_rate": round(market.current_interest_rate, FINANCE_PRICE_DECIMALS),
            "base_rate": round(base_rate, FINANCE_PRICE_DECIMALS),
            "spread": round(spread, FINANCE_PRICE_DECIMALS),
            "spread_change_bp": round(last_chg * 100.0, 2),
            "presettle_buy_volume": round(market_presettle_buy_volume(market), 2),
            "presettle_sell_volume": round(market_presettle_sell_volume(market), 2),
            "traded_volume": round(market_traded_volume(market), 2),
            "buy_orders": len(market.buy_orders),
            "sell_orders": len(market.sell_orders),
            "rate_change": round(last_chg, 4),
        }

    def get_trade_report(self, country_id: str = "", company_id: str = "") -> Dict[str, Any]:
        """국가·기업 무역 현황. country_id 지정 시 세계 모든 주체의 해당국 수출·수입 포함."""
        companies: List[Dict[str, Any]] = []
        export_routes: List[Dict[str, Any]] = []
        import_routes: List[Dict[str, Any]] = []
        domestic_routes: List[Dict[str, Any]] = []
        summary: Dict[str, Any] = {
            "total_routes": 0,
            "domestic_routes": 0,
            "foreign_routes": 0,
            "export_routes": 0,
            "import_routes": 0,
            "total_qty": 0.0,
            "foreign_qty": 0.0,
            "export_qty": 0.0,
            "import_qty": 0.0,
            "export_facility_levels": 0,
            "pending_export_qty": 0.0,
            "in_transit_qty": 0.0,
            "by_product": {},
            "by_product_export": {},
            "by_product_import": {},
            "by_partner_export": {},
            "by_partner_import": {},
        }
        by_product: Dict[str, Dict[str, float]] = defaultdict(
            lambda: {"qty": 0.0, "routes": 0.0, "value": 0.0})
        by_product_export: Dict[str, Dict[str, float]] = defaultdict(
            lambda: {"qty": 0.0, "routes": 0.0, "value": 0.0})
        by_product_import: Dict[str, Dict[str, float]] = defaultdict(
            lambda: {"qty": 0.0, "routes": 0.0, "value": 0.0})
        by_partner_export: Dict[str, Dict[str, float]] = defaultdict(
            lambda: {"qty": 0.0, "routes": 0.0, "value": 0.0})
        by_partner_import: Dict[str, Dict[str, float]] = defaultdict(
            lambda: {"qty": 0.0, "routes": 0.0, "value": 0.0})

        if country_id:
            gdp = country_gdp_breakdown(self, country_id)
            summary["gdp_trade"] = {
                "exports": round(gdp.get("exports", 0.0), 2),
                "imports": round(gdp.get("imports", 0.0), 2),
                "net_exports": round(gdp.get("net_exports", 0.0), 2),
                "export_facility_settled": round(gdp.get("export_facility_settled", 0.0), 2),
                "export_facility_pending": round(gdp.get("export_facility_pending", 0.0), 2),
                "export_facility_transit": round(gdp.get("export_facility_transit", 0.0), 2),
                "export_facility_total": round(gdp.get("export_facility_total", 0.0), 2),
                "market_trade_exports": round(gdp.get("market_trade_exports", 0.0), 2),
                "market_trade_imports": round(gdp.get("market_trade_imports", 0.0), 2),
            }
            for co in self.companies.values():
                if co.type == "물류 기업":
                    continue
                co_home = self.states.get(co.home_state)
                if not co_home or co_home.country_id != country_id:
                    continue
                for fac in co.facilities:
                    spec = FACILITY_SPECS.get(fac.name, {})
                    if facility_is_export_only(spec):
                        summary["export_facility_levels"] += fac.active_levels()
                for ship in getattr(co, "pending_export_shipments", []):
                    summary["pending_export_qty"] += float(ship.get("qty", 0.0))

        def _route_prices(route: Dict[str, Any], co_home_state: str) -> Tuple[float, float, Any, Any]:
            return _resolve_trade_route_prices(self, route, co_home_state)

        def _add_bucket(bucket: Dict[str, Dict[str, float]], key: str, qty: float, value: float) -> None:
            if not key:
                key = "기타"
            bucket[key]["qty"] += qty
            bucket[key]["routes"] += 1
            bucket[key]["value"] += value

        for co in self.companies.values():
            if co.type != "물류 기업":
                continue
            if company_id and co.id != company_id:
                continue
            st = self.states.get(co.home_state)
            co_country = st.country_id if st else ""

            matched_routes: List[Dict[str, Any]] = []
            for route in getattr(co, "active_trade_routes", []):
                price_a, price_b, home, dest = _route_prices(route, co.home_state)
                dest_country_id = (
                    dest.country_id if dest else str(route.get("dest_country", "") or "")
                )
                home_country_id = home.country_id if home else ""
                dest_country = self.countries.get(dest_country_id)
                home_country = self.countries.get(home_country_id)
                ordered = float(route.get("ordered_qty", route.get("qty", 0.0)) or 0.0)
                actual = float(route.get("actual_qty", 0.0) or 0.0)
                is_foreign = bool(route.get("is_foreign"))
                from_export = bool(route.get("from_export_facility"))
                export_value = actual * max(0.0, price_a)
                import_value = actual * max(0.0, price_a)

                is_export = bool(
                    country_id and is_foreign and home_country_id == country_id and actual > 1e-9
                )
                is_import = bool(
                    country_id and is_foreign and dest_country_id == country_id and actual > 1e-9
                )
                is_domestic_here = bool(
                    country_id
                    and not is_foreign
                    and home_country_id == country_id
                    and dest_country_id == country_id
                    and actual > 1e-9
                )
                # 국가 필터: 해당국 수출·수입·국내 이동 또는 (필터 없을 때) 전부 본국 물류
                if country_id:
                    if not (is_export or is_import or is_domestic_here):
                        continue
                elif company_id:
                    pass
                else:
                    # 전체 조회는 모든 체결 노선
                    pass

                partner_name = ""
                partner_id = ""
                flow = "domestic"
                trade_value = import_value if is_import and not is_export else export_value
                if is_export:
                    flow = "export"
                    partner_id = dest_country_id
                    partner_name = dest_country.name if dest_country else dest_country_id
                    trade_value = export_value
                elif is_import:
                    flow = "import"
                    partner_id = home_country_id
                    partner_name = home_country.name if home_country else home_country_id
                    trade_value = import_value

                route_row = {
                    "company_id": co.id,
                    "company_name": co.name,
                    "company_country_id": co_country,
                    "company_country_name": (
                        self.countries[co_country].name
                        if co_country in self.countries else co_country
                    ),
                    "producer_company_id": route.get("producer_company_id", ""),
                    "producer_company_name": (
                        self.companies[route["producer_company_id"]].name
                        if route.get("producer_company_id") in self.companies else ""
                    ),
                    "home_state_id": route.get("home_state", co.home_state),
                    "home_state_name": home.name if home else route.get("home_state", co.home_state),
                    "home_country_id": home_country_id,
                    "home_country_name": home_country.name if home_country else home_country_id,
                    "dest_state_id": route.get("dest_state", ""),
                    "dest_state_name": dest.name if dest else route.get("dest_state", ""),
                    "dest_country_id": dest_country_id,
                    "dest_country_name": dest_country.name if dest_country else dest_country_id,
                    "partner_id": partner_id,
                    "partner_name": partner_name,
                    "product": route.get("product", ""),
                    "ordered_qty": round(ordered, 2),
                    "actual_qty": round(actual, 2),
                    "fill_ratio": round(actual / max(ordered, 1e-9), 3),
                    "is_foreign": is_foreign,
                    "flow": flow,
                    "from_export_facility": from_export,
                    "status": "settled",
                    "supply_mode": "수출시설" if from_export else "물류",
                    "export_value": round(export_value, 2),
                    "import_value": round(import_value, 2),
                    "trade_value": round(trade_value, 2),
                    "price_a": round(price_a, 2),
                    "price_b": round(price_b, 2),
                }
                matched_routes.append(route_row)

                summary["total_routes"] += 1
                summary["total_qty"] += actual
                prod = route_row["product"] or "기타"
                _add_bucket(by_product, prod, actual, trade_value)

                if is_foreign:
                    summary["foreign_routes"] += 1
                    summary["foreign_qty"] += actual
                else:
                    summary["domestic_routes"] += 1

                if is_export:
                    summary["export_routes"] += 1
                    summary["export_qty"] += actual
                    export_routes.append(route_row)
                    _add_bucket(by_product_export, prod, actual, export_value)
                    _add_bucket(
                        by_partner_export,
                        partner_name or partner_id or "기타",
                        actual,
                        export_value,
                    )
                if is_import:
                    summary["import_routes"] += 1
                    summary["import_qty"] += actual
                    import_routes.append(route_row)
                    _add_bucket(by_product_import, prod, actual, import_value)
                    _add_bucket(
                        by_partner_import,
                        partner_name or partner_id or "기타",
                        actual,
                        import_value,
                    )
                if is_domestic_here or (not country_id and not is_foreign):
                    domestic_routes.append(route_row)

            # 운송중: 국가 필터 시 본국 물류 + 해당국 경유 노선이 있는 외국 물류
            in_transit = sum(
                float(x.get("qty", 0.0) or 0.0)
                for x in getattr(co, "in_transit_trade_inventory", [])
            )
            if country_id:
                if co_country == country_id:
                    summary["in_transit_qty"] += in_transit
            else:
                summary["in_transit_qty"] += in_transit

            if matched_routes or (not country_id) or (co_country == country_id):
                companies.append({
                    "company_id": co.id,
                    "company_name": co.name,
                    "home_state_id": co.home_state,
                    "home_state_name": st.name if st else co.home_state,
                    "country_id": co_country,
                    "country_name": (
                        self.countries[co_country].name
                        if co_country in self.countries else co_country
                    ),
                    "routes": matched_routes,
                    "in_transit_qty": round(in_transit, 2),
                })

            # 수출 시설 직수출 — 운송중(미체결) 해외 물량 (세계 모든 물류)
            if country_id:
                for route in getattr(co, "in_transit_trade_inventory", []) or []:
                    if not route.get("from_export_facility") or not route.get("is_foreign"):
                        continue
                    qty = float(route.get("qty", route.get("actual_qty", 0.0)) or 0.0)
                    if qty <= 1e-9:
                        continue
                    price_a, price_b, home, dest = _route_prices(route, co.home_state)
                    home_country_id = home.country_id if home else ""
                    if home_country_id != country_id:
                        continue
                    dest_country_id = (
                        dest.country_id if dest else str(route.get("dest_country", "") or "")
                    )
                    dest_country = self.countries.get(dest_country_id)
                    producer_id = str(route.get("producer_company_id", "") or "")
                    producer = self.companies.get(producer_id)
                    export_value = qty * max(0.0, price_a)
                    partner_name = dest_country.name if dest_country else dest_country_id
                    prod = str(route.get("product", "") or "기타")
                    route_row = {
                        "company_id": co.id,
                        "company_name": co.name,
                        "company_country_id": co_country,
                        "company_country_name": (
                            self.countries[co_country].name
                            if co_country in self.countries else co_country
                        ),
                        "producer_company_id": producer_id,
                        "producer_company_name": producer.name if producer else "",
                        "home_state_id": route.get("home_state", ""),
                        "home_state_name": home.name if home else route.get("home_state", ""),
                        "home_country_id": home_country_id,
                        "home_country_name": (
                            self.countries[home_country_id].name
                            if home_country_id in self.countries else home_country_id
                        ),
                        "dest_state_id": route.get("dest_state", ""),
                        "dest_state_name": dest.name if dest else route.get("dest_state", ""),
                        "dest_country_id": dest_country_id,
                        "dest_country_name": partner_name,
                        "partner_id": dest_country_id,
                        "partner_name": partner_name,
                        "product": prod,
                        "ordered_qty": round(qty, 2),
                        "actual_qty": round(qty, 2),
                        "fill_ratio": 0.0,
                        "is_foreign": True,
                        "flow": "export",
                        "from_export_facility": True,
                        "status": "in_transit",
                        "supply_mode": "수출시설·운송중",
                        "export_value": round(export_value, 2),
                        "import_value": 0.0,
                        "trade_value": round(export_value, 2),
                        "price_a": round(price_a, 2),
                        "price_b": round(price_b, 2),
                    }
                    # 목록에는 보여주되, 수출 물량·품목·상대국 집계에는 넣지 않음
                    # (매수→도착 운송중은 체결 시에만 실제 수출로 계상)
                    export_routes.append(route_row)

        # 수출 시설 산출 대기(물류 미배정)
        export_facilities: List[Dict[str, Any]] = []
        if country_id:
            fac_agg: Dict[str, Dict[str, Any]] = {}
            for co in self.companies.values():
                if co.type == "물류 기업":
                    continue
                co_home = self.states.get(co.home_state)
                export_levels = 0
                for fac in co.facilities:
                    spec = FACILITY_SPECS.get(fac.name, {})
                    if facility_is_export_only(spec):
                        export_levels += fac.active_levels()
                pending_rows: List[Dict[str, Any]] = []
                for ship in getattr(co, "pending_export_shipments", []) or []:
                    qty = float(ship.get("qty", 0.0) or 0.0)
                    if qty <= 1e-9:
                        continue
                    source = self.states.get(ship.get("source_state", ""))
                    if not source or source.country_id != country_id:
                        continue
                    product = str(ship.get("product", "") or "기타")
                    price = float(ship.get("source_price", 0.0) or 0.0)
                    if price <= 1e-12:
                        mk = self.markets.get(market_key(source.id, product))
                        if mk:
                            price = float(
                                market_goods_labor_price(mk) or mk.current_price or 0.0)
                    export_value = qty * max(0.0, price)
                    # 이번 주 의도했던 도착지(표시용, 미확정)
                    intended_sid = str(ship.get("_pending_dest_state", "") or "")
                    intended_cid = str(ship.get("_pending_dest_country", "") or "")
                    intended_state = self.states.get(intended_sid)
                    intended_country = self.countries.get(intended_cid)
                    dest_state_name = intended_state.name if intended_state else "—"
                    dest_country_name = (
                        intended_country.name if intended_country
                        else (intended_cid or "대기"))
                    partner_label = dest_country_name if intended_cid else "대기"
                    route_row = {
                        "company_id": "",
                        "company_name": "(운송 대기)",
                        "company_country_id": "",
                        "company_country_name": "",
                        "producer_company_id": co.id,
                        "producer_company_name": co.name,
                        "home_state_id": source.id,
                        "home_state_name": source.name,
                        "home_country_id": country_id,
                        "home_country_name": (
                            self.countries[country_id].name
                            if country_id in self.countries else country_id
                        ),
                        "dest_state_id": intended_sid,
                        "dest_state_name": dest_state_name,
                        "dest_country_id": intended_cid,
                        "dest_country_name": dest_country_name,
                        "partner_id": intended_cid,
                        "partner_name": partner_label,
                        "product": product,
                        "ordered_qty": round(qty, 2),
                        "actual_qty": round(qty, 2),
                        "fill_ratio": 0.0,
                        "is_foreign": bool(ship.get("_pending_is_foreign", True)),
                        "flow": "export",
                        "from_export_facility": True,
                        "status": "pending",
                        "supply_mode": "수출시설·대기",
                        "pending_reason": str(ship.get("_pending_reason", "") or "물류 배차 대기"),
                        "export_value": round(export_value, 2),
                        "import_value": 0.0,
                        "trade_value": round(export_value, 2),
                        "price_a": round(price, 2),
                        "price_b": 0.0,
                    }
                    # 표(무역로 목록)에는 대기 화물을 보여주되, 실제 수출 물량/노선/
                    # 상대국·품목 집계에는 넣지 않는다(대기는 미체결 → 이중 계상 방지).
                    export_routes.append(route_row)
                    pending_rows.append(route_row)

                if export_levels > 0 or pending_rows or (
                    co_home and co_home.country_id == country_id
                    and any(
                        facility_is_export_only(FACILITY_SPECS.get(f.name, {}))
                        for f in co.facilities
                    )
                ):
                    if not co_home or co_home.country_id != country_id:
                        if not pending_rows:
                            continue
                    settled_value = sum(
                        float(r.get("export_value", 0.0) or 0.0)
                        for r in export_routes
                        if r.get("from_export_facility")
                        and r.get("status") == "settled"
                        and r.get("producer_company_id") == co.id
                    )
                    transit_value = sum(
                        float(r.get("export_value", 0.0) or 0.0)
                        for r in export_routes
                        if r.get("from_export_facility")
                        and r.get("status") == "in_transit"
                        and r.get("producer_company_id") == co.id
                    )
                    pending_value = sum(
                        float(r.get("export_value", 0.0) or 0.0) for r in pending_rows
                    )
                    export_facilities.append({
                        "company_id": co.id,
                        "company_name": co.name,
                        "home_state_id": co.home_state,
                        "home_state_name": co_home.name if co_home else co.home_state,
                        "export_facility_levels": export_levels,
                        "pending_qty": round(
                            sum(float(r.get("actual_qty", 0.0) or 0.0) for r in pending_rows),
                            2,
                        ),
                        "pending_value": round(pending_value, 2),
                        "settled_value": round(settled_value, 2),
                        "transit_value": round(transit_value, 2),
                        # 표시 합계 = 실제 주간 수출(체결). 운송·대기는 재고 참고용.
                        "total_value": round(settled_value, 2),
                    })
            export_facilities.sort(key=lambda r: -float(r.get("total_value", 0.0)))

        def _pack_buckets(src: Dict[str, Dict[str, float]]) -> Dict[str, Dict[str, Any]]:
            return {
                k: {
                    "qty": round(v["qty"], 2),
                    "routes": int(v["routes"]),
                    "value": round(v["value"], 2),
                }
                for k, v in sorted(src.items(), key=lambda kv: -kv[1]["value"])
            }

        summary["by_product"] = _pack_buckets(by_product)
        summary["by_product_export"] = _pack_buckets(by_product_export)
        summary["by_product_import"] = _pack_buckets(by_product_import)
        summary["by_partner_export"] = _pack_buckets(by_partner_export)
        summary["by_partner_import"] = _pack_buckets(by_partner_import)
        summary["pending_export_qty"] = round(summary["pending_export_qty"], 2)
        summary["in_transit_qty"] = round(summary["in_transit_qty"], 2)
        summary["total_qty"] = round(summary["total_qty"], 2)
        summary["foreign_qty"] = round(summary["foreign_qty"], 2)
        summary["export_qty"] = round(summary["export_qty"], 2)
        summary["import_qty"] = round(summary["import_qty"], 2)

        export_routes.sort(key=lambda r: -r.get("trade_value", 0.0))
        import_routes.sort(key=lambda r: -r.get("trade_value", 0.0))
        domestic_routes.sort(key=lambda r: -r.get("trade_value", 0.0))

        country_name = ""
        if country_id:
            country = self.countries.get(country_id)
            country_name = country.name if country else country_id
        return {
            "country_id": country_id,
            "country_name": country_name,
            "week": self.week,
            "total_routes": summary["total_routes"],
            "summary": summary,
            "product_history": (
                country_trade_product_history_payload(self, country_id)
                if country_id else []
            ),
            "companies": companies,
            "export_facilities": export_facilities,
            "export_routes": export_routes,
            "import_routes": import_routes,
            "domestic_routes": domestic_routes,
        }

    # ------------------------------------------------------------------
    # 부동산 시장 (2.txt)
    # ------------------------------------------------------------------
    def _init_real_estate_markets(self) -> None:
        """건물 RE 시장 생성 및 시드 (토지·미개간 토지 폐지)."""
        for sid, st in self.states.items():
            st.land_capacity = 0.0
            st.land_used = 0.0
            st.vacant_land = 0.0
            for kind in RE_KINDS:
                key = re_market_key(sid, kind)
                if kind == "housing":
                    base = 4200.0
                elif kind == "multi_family":
                    base = 6600.0
                else:
                    base = 6000.0
                rem = RealEstateMarketState(sid, kind, base)
                self.real_estate_markets[key] = rem
            country = self.countries.get(st.country_id)
            if country is not None:
                ensure_actor_re_holdings(country)

        for co in self.companies.values():
            for fac in co.facilities:
                levels = max(0, int(fac.level or 0))
                if levels <= 0:
                    continue
                if FACILITY_SPECS.get(fac.name, {}).get("office"):
                    continue
                kind = facility_re_kind(fac.name)
                if kind in RE_KINDS:
                    actor_re_add(co, fac.state_id, kind, float(levels))
                    rem = self.real_estate_markets.get(re_market_key(fac.state_id, kind))
                    if rem:
                        rem.stock_outstanding += float(levels)
            office_lv = max(0, int(getattr(co, "office_levels", 0) or 0))
            if office_lv > 0:
                sid = co.home_state
                actor_re_add(co, sid, "mixed_use", float(office_lv))
                rem = self.real_estate_markets.get(re_market_key(sid, "mixed_use"))
                if rem:
                    rem.stock_outstanding += float(office_lv)
            if co.type == "건설 기업":
                convert_builder_re_facilities_to_holdings(co, self)
        for rem in self.real_estate_markets.values():
            re_update_fair_values(self, rem)
            rem.current_price = max(rem.fair_value, rem.replacement_cost * 0.9, rem.current_price)
            rem.last_current_price = rem.current_price
        self._seed_initial_re_ownership()

    def _seed_pop_weights(self, pops: List[Any], kind: str) -> List[float]:
        edu_w = RE_SEED_POP_WEIGHT.get(kind, RE_SEED_POP_WEIGHT.get("housing", {}))
        age_lo, age_hi = RE_SEED_POP_AGE_WEIGHT.get(kind, (30.0, 60.0))
        age_mid = 0.5 * (age_lo + age_hi)
        weights = []
        for pop in pops:
            shares = pop_normalize_edu_shares(getattr(pop, "edu_shares", None))
            w_edu = sum(float(edu_w.get(q, 0.2)) * shares.get(q, 0.0) for q in POP_QUALIFICATION_ORDER)
            size = max(1.0, float(pop.total_population() or 1.0))
            wealth = max(1.0, float(getattr(pop, "wealth", 0.0) or 0.0))
            age = pop_mean_age(pop, self)
            # 선호 연령대에 가까울수록 가중↑ + 나이대 자산 프리셋(청소년 0)
            age_w = math.exp(-((age - age_mid) / max(age_hi - age_lo, 5.0)) ** 2)
            preset_w = pop_asset_seed_weight(age, kind)
            weights.append(max(0.0, w_edu) * size * math.sqrt(wealth) * age_w * preset_w)
        if sum(weights) <= 1e-12:
            return pop_ownership_seed_weights(self, pops, kind)
        return weights

    def _seed_initial_re_ownership(self) -> None:
        """중앙·주·IB·POP·건설사에 건물 RE 시드 (토지 폐지)."""
        for sid, st in self.states.items():
            country = self.countries.get(st.country_id)
            if not country:
                continue
            pops = list(st.pops or [])
            ibs = [ib for ib in self.investment_banks.values() if ib.country_id == st.country_id]
            builders = [
                co for co in self.companies.values()
                if co.type == "건설 기업" and co.home_state == sid
            ]

            def _xfer_from_state(kind: str, dst: Any, qty: float) -> float:
                q = min(qty, actor_re_qty(st, sid, kind))
                if q <= 1e-9:
                    return 0.0
                actor_re_add(st, sid, kind, -q)
                actor_re_add(dst, sid, kind, q)
                return q

            # 토지(wild_land/land) 시드 제거 — 건물만 시드

            # 건물: 기존 기업 보유분 기준으로 IB·POP 몫 이전 + 부족분 스톡 생성
            for kind in RE_BUILDABLE_KINDS:
                shares_b = RE_SEED_BUILDING_SHARES.get(kind, {})
                rem = self.real_estate_markets.get(re_market_key(sid, kind))
                if not rem:
                    continue
                # 현재 기업 보유 합
                cos = [c for c in self.companies.values()
                       if any(f.state_id == sid for f in c.facilities) or c.home_state == sid]
                co_held = sum(actor_re_qty(c, sid, kind) for c in cos)
                preset_b = float((getattr(st, "preset_buildings", {}) or {}).get(kind, 0.0) or 0.0)
                if co_held <= 1e-6:
                    # 프리셋 건물량 우선, 없으면 소량 기본 시드
                    seed_stock = preset_b if preset_b > 1e-9 else max(
                        2.0, rem.stock_outstanding * 0.3 if rem.stock_outstanding > 0 else 4.0)
                    rem.stock_outstanding = max(rem.stock_outstanding, seed_stock)
                    actor_re_add(st, sid, kind, seed_stock)
                    co_held = seed_stock
                    pool_src = st
                else:
                    pool_src = None
                    # 프리셋이 기업 보유보다 크면 주 물량으로 보충 후 배분
                    if preset_b > co_held + 1e-9:
                        extra = preset_b - co_held
                        actor_re_add(st, sid, kind, extra)
                        rem.stock_outstanding = max(rem.stock_outstanding, preset_b)
                        pool_src = st
                        co_held = preset_b
                total = max(co_held, rem.stock_outstanding, preset_b)
                tgt_co = total * float(shares_b.get("company", 0.3))
                tgt_ib = total * float(shares_b.get("ib", 0.3))
                tgt_pop = total * float(shares_b.get("pop", 0.4))
                # 기업 과다분 → IB/POP
                if pool_src is st:
                    avail = actor_re_qty(st, sid, kind)
                    ib_q = min(avail, tgt_ib)
                    if ibs and ib_q > 1e-9:
                        each = ib_q / len(ibs)
                        for ib in ibs:
                            q = min(each, actor_re_qty(st, sid, kind))
                            actor_re_add(st, sid, kind, -q)
                            actor_re_add(ib, sid, kind, q)
                    pop_q = min(actor_re_qty(st, sid, kind), tgt_pop)
                    if pops and pop_q > 1e-9:
                        weights = self._seed_pop_weights(pops, kind)
                        tw = sum(weights) or float(len(pops))
                        for pop, w in zip(pops, weights):
                            q = min(pop_q * (w / tw), actor_re_qty(st, sid, kind))
                            actor_re_add(st, sid, kind, -q)
                            actor_re_add(pop, sid, kind, q)
                else:
                    # 기업 holdings에서 이전
                    surplus = max(0.0, co_held - tgt_co)
                    if surplus > 1e-9 and cos:
                        per_co = surplus / len(cos)
                        moved_ib = 0.0
                        moved_pop = 0.0
                        need_ib, need_pop = tgt_ib, tgt_pop
                        for co in cos:
                            give = min(per_co, actor_re_qty(co, sid, kind))
                            if give <= 1e-9:
                                continue
                            if need_ib > 1e-9 and ibs:
                                qi = min(give * 0.5, need_ib / max(len(ibs), 1))
                                for ib in ibs:
                                    take = min(qi, give)
                                    if take <= 1e-9:
                                        break
                                    actor_re_add(co, sid, kind, -take)
                                    actor_re_add(ib, sid, kind, take)
                                    give -= take
                                    need_ib -= take
                                    moved_ib += take
                            if need_pop > 1e-9 and pops and give > 1e-9:
                                weights = self._seed_pop_weights(pops, kind)
                                tw = sum(weights) or float(len(pops))
                                chunk = min(give, need_pop)
                                for pop, w in zip(pops, weights):
                                    take = min(chunk * (w / tw), actor_re_qty(co, sid, kind))
                                    if take <= 1e-9:
                                        continue
                                    actor_re_add(co, sid, kind, -take)
                                    actor_re_add(pop, sid, kind, take)
                                    need_pop -= take
                                    moved_pop += take
                rem.stock_outstanding = max(
                    rem.stock_outstanding,
                    sum(actor_re_qty(a, sid, kind) for a in [*self.companies.values(), *ibs, *pops, country, st]),
                )
                # 워밍업 시드 잔여: 주 정부·중앙정부 보유분 → 인구·금투
                self._flush_gov_re_to_private(st, country, sid, kind, pops, ibs)
                rem.stock_outstanding = max(
                    rem.stock_outstanding,
                    sum(actor_re_qty(a, sid, kind) for a in [*self.companies.values(), *ibs, *pops]),
                )

    def company_reserve_land_for_construction(
        self, co: "Company", fac: Facility, stages: int,
    ) -> int:
        """토지 시스템 폐지 — 착공에 토지 확보 불필요. 요청 단계를 그대로 반환."""
        return max(0, int(stages or 0))

    def on_office_stage_completed(self, co: "Company", stages: int = 1) -> None:
        """사무 시설 완공 → 다용도 RE 스톡·보유 동기화."""
        if stages <= 0:
            return
        sid = co.home_state
        rem = self.real_estate_markets.get(re_market_key(sid, "mixed_use"))
        if rem:
            rem.stock_outstanding += float(stages)
        actor_re_add(co, sid, "mixed_use", float(stages))

    def on_facility_stage_completed(
        self,
        co: "Company",
        fac: Facility,
        stages: int = 1,
        list_primary: bool = True,
    ) -> None:
        """완공 시 RE 스톡 동기화 + 분양/보유 결정."""
        kind = facility_re_kind(fac.name)
        if not kind or stages <= 0:
            return
        sid = fac.state_id
        if kind in RE_KINDS and kind not in RE_LAND_KINDS:
            rem = self.real_estate_markets.get(re_market_key(sid, kind))
            if rem:
                rem.stock_outstanding += float(stages)
            # 건설사 주거·다세대·다용도: 시설로 운영하지 않고 부동산으로만 소유 → 의뢰 인도
            if co.type == "건설 기업" and kind in RE_BUILDABLE_KINDS:
                fac.level = max(0, int(fac.level or 0) - int(stages))
                fac.closed_levels = min(int(fac.closed_levels or 0), fac.level)
                key = re_holdings_key(sid, kind)
                if list_primary:
                    # 의뢰 인도 대기 (시장 분양 매도 없음)
                    co.re_pending_listing[key] = (
                        float(co.re_pending_listing.get(key, 0.0) or 0.0)
                        + float(stages)
                    )
                else:
                    actor_re_add(co, sid, kind, float(stages))
                return
            # 일반 기업시설 완공: 보유(운영), 이후 시장에서 매매 가능
            actor_re_add(co, sid, kind, float(stages))

    def cheat_instant_complete_all_construction(self) -> Dict[str, Any]:
        """개발 치트: 건설중(UC) 기업·부동산·지방/중앙 정부·자영 시설을 즉시 완공."""
        stats = {
            "company_stages": 0,
            "re_stages": 0,
            "office_stages": 0,
            "public_stages": 0,
            "public_infra_stages": 0,
            "central_stages": 0,
            "self_emp_stages": 0,
        }
        for co in list(self.companies.values()):
            while int(getattr(co, "office_under_construction", 0) or 0) > 0:
                co.office_levels = int(getattr(co, "office_levels", 0) or 0) + 1
                co.office_under_construction = (
                    int(co.office_under_construction) - 1)
                co.office_construction_progress = 0.0
                self.on_office_stage_completed(co, 1)
                stats["office_stages"] += 1
            reset_office_construction_funding(co)
            reset_office_construction_funding(co)
            for fac in list(getattr(co, "facilities", []) or []):
                is_re = False
                try:
                    is_re = bool(is_builder_re_facility(co, fac))
                except Exception:
                    is_re = False
                guard = 0
                while int(getattr(fac, "under_construction", 0) or 0) > 0 and guard < 10000:
                    guard += 1
                    before = int(fac.under_construction)
                    try:
                        co._finalize_facility_stage_completion(fac, self)
                    except Exception:
                        fac.level = int(getattr(fac, "level", 0) or 0) + 1
                        fac.under_construction = max(0, before - 1)
                        fac.construction_progress = 0.0
                        fac.pending_bond_issue = 0.0
                        self.on_facility_stage_completed(co, fac, 1)
                    if int(getattr(fac, "under_construction", 0) or 0) >= before:
                        fac.under_construction = max(0, before - 1)
                        fac.construction_progress = 0.0
                        fac.pending_bond_issue = 0.0
                    if is_re:
                        stats["re_stages"] += 1
                    else:
                        stats["company_stages"] += 1

        for st in self.states.values():
            gov = getattr(st, "local_government", None)
            if gov is None:
                continue
            infra = getattr(st, "infrastructure", None)
            remove_ids: List[int] = []
            for fac in list(getattr(gov, "public_facilities", []) or []):
                uc0 = int(getattr(fac, "under_construction", 0) or 0)
                if uc0 <= 0:
                    continue
                service = ""
                try:
                    service = str(gov._service_key_for_facility(fac.name) or "")
                except Exception:
                    service = ""
                while int(getattr(fac, "under_construction", 0) or 0) > 0:
                    fac.construction_progress = 0.0
                    fac.pending_bond_issue = 0.0
                    if service in PUBLIC_INFRASTRUCTURE_SERVICES:
                        gov._complete_infrastructure_stage(fac, infra, self)
                        fac.under_construction = max(
                            0, int(fac.under_construction) - 1)
                        if int(getattr(fac, "under_construction_signal", 0) or 0) > 0:
                            fac.under_construction_signal -= 1
                        stats["public_infra_stages"] += 1
                        if fac.under_construction <= 0:
                            remove_ids.append(id(fac))
                            break
                    else:
                        fac.level = int(getattr(fac, "level", 0) or 0) + 1
                        fac.under_construction = max(
                            0, int(fac.under_construction) - 1)
                        if int(getattr(fac, "under_construction_signal", 0) or 0) > 0:
                            fac.under_construction_signal -= 1
                        stats["public_stages"] += 1
            if remove_ids:
                gov.public_facilities = [
                    f for f in gov.public_facilities if id(f) not in remove_ids
                ]

        for country in self.countries.values():
            for fac in list(getattr(country, "central_facilities", None) or []):
                while int(getattr(fac, "under_construction", 0) or 0) > 0:
                    fac.construction_progress = 0.0
                    fac.level = int(getattr(fac, "level", 0) or 0) + 1
                    fac.under_construction = max(0, int(fac.under_construction) - 1)
                    if int(getattr(fac, "under_construction_signal", 0) or 0) > 0:
                        fac.under_construction_signal -= 1
                    stats["central_stages"] += 1

        for st in self.states.values():
            for sector_obj in (getattr(st, "self_employed", None) or {}).values():
                for fac in list(getattr(sector_obj, "facilities", []) or []):
                    while int(getattr(fac, "under_construction", 0) or 0) > 0:
                        fac.level = int(getattr(fac, "level", 0) or 0) + 1
                        fac.under_construction = max(
                            0, int(fac.under_construction) - 1)
                        fac.construction_progress = 0.0
                        stats["self_emp_stages"] += 1

        stats["total_stages"] = sum(
            v for k, v in stats.items() if k != "total_stages")
        return {"ok": True, "stats": dict(stats)}

    def cheat_set_market_price(
        self,
        target: str = "",
        price: Optional[float] = None,
        kind: str = "",
        country_id: str = "",
        state_id: str = "",
    ) -> Dict[str, Any]:
        """개발 치트: 상품·주식·채권·노동·부동산 시세 조회/설정."""
        return cheat_set_market_price(
            self,
            target=target,
            price=price,
            kind=kind,
            country_id=country_id,
            state_id=state_id,
        )

    def _settle_real_estate_operators(self) -> None:
        """POP/IB/정부 소유 건물: 서비스 매도·투입 매수 후 지분 비율 배분."""
        for sid, st in self.states.items():
            for kind, service in RE_SERVICE_OUTPUT.items():
                rem = self.real_estate_markets.get(re_market_key(sid, kind))
                if rem is None:
                    continue
                fac_name = RE_KIND_FACILITY.get(kind)
                spec = FACILITY_SPECS.get(fac_name, {}) if fac_name else {}
                # 소유자 지분 (기업 다용도=사무 사용분은 제외)
                owners: List[Tuple[Any, float]] = []
                for pop in st.pops:
                    q = actor_re_qty(pop, sid, kind)
                    if q > 1e-9:
                        owners.append((pop, q))
                for ib in self.investment_banks.values():
                    if ib.country_id != st.country_id:
                        continue
                    q = actor_re_qty(ib, sid, kind)
                    if q > 1e-9:
                        owners.append((ib, q))
                country = self.countries.get(st.country_id)
                if country is not None:
                    q = actor_re_qty(country, sid, kind)
                    if q > 1e-9:
                        owners.append((country, q))
                q_st = actor_re_qty(st, sid, kind)
                if q_st > 1e-9:
                    owners.append((st, q_st))
                total_q = sum(q for _, q in owners)
                if total_q <= 1e-9:
                    continue
                # 서비스 시장 전주 체결가 기준 순익 근사
                svc_mk = self.markets.get(market_key(sid, service))
                if not svc_mk:
                    continue
                out_qty = float(spec.get("output_qty", 0) or 0) * total_q
                price = market_goods_labor_price(svc_mk)
                revenue = out_qty * price * clamp(rem.utilization, 0.15, 1.0)
                cost = 0.0
                for inp, iq in (spec.get("inputs") or {}).items():
                    imk = self.markets.get(market_key(sid, inp))
                    ip = market_goods_labor_price(imk) if imk else PRODUCT_BASE_PRICES.get(inp, 10.0)
                    cost += float(iq) * total_q * ip
                fee = revenue * RE_OPERATOR_FEE
                noi = max(0.0, revenue - cost - fee)
                # 서비스/투입 주문은 _collect 단계에서 별도 제출
                for owner, q in owners:
                    share = q / total_q
                    payout = noi * share
                    if payout <= 1e-9:
                        continue
                    if isinstance(owner, POP):
                        owner.cash += payout
                        owner.passive_income += payout
                        owner.weekly_income += payout
                        pop_record_income(owner, "부동산 임대소득", payout)
                    elif isinstance(owner, InvestmentBank):
                        owner.cash += payout
                        owner.weekly_dividend_income += payout
                    elif isinstance(owner, Country):
                        owner.treasury += payout
                    elif isinstance(owner, State):
                        gov = getattr(owner, "local_government", None)
                        if gov is not None:
                            gov.cash = float(getattr(gov, "cash", 0.0) or 0.0) + payout

    def _collect_re_operator_service_orders(self) -> None:
        """POP/IB/정부·미분양 소유분 서비스 매도·투입 매수 주문.

        매도량은 가동률(utilization)만큼만 — 공실 전량 덤핑으로 시세가 붕괴하지 않게 한다.
        호가 원가는 재조달·캡레이트 자본비 포함(re_service_unit_cost).
        기업 다용도는 사무 슬롯으로 쓰이므로 임대 매도에서 제외한다.
        """
        for sid, st in self.states.items():
            for kind, service in RE_SERVICE_OUTPUT.items():
                rem = self.real_estate_markets.get(re_market_key(sid, kind))
                if rem is None:
                    continue
                fac_name = RE_KIND_FACILITY.get(kind)
                spec = FACILITY_SPECS.get(fac_name, {}) if fac_name else {}
                total_q = 0.0
                for pop in st.pops:
                    total_q += actor_re_qty(pop, sid, kind)
                for ib in self.investment_banks.values():
                    if ib.country_id == st.country_id:
                        total_q += actor_re_qty(ib, sid, kind)
                country = self.countries.get(st.country_id)
                if country is not None:
                    total_q += actor_re_qty(country, sid, kind)
                total_q += actor_re_qty(st, sid, kind)
                hkey = re_holdings_key(sid, kind)
                for co in self.companies.values():
                    if isinstance(co, RetailCompany):
                        continue
                    pending = float(
                        (getattr(co, "re_pending_listing", None) or {}).get(hkey, 0.0)
                        or 0.0)
                    total_q += pending
                    if kind == "mixed_use":
                        continue
                    total_q += actor_re_qty(co, sid, kind)
                if total_q <= 1e-9:
                    continue
                util = clamp(float(getattr(rem, "utilization", 1.0) or 1.0), 0.15, 1.0)
                active_q = total_q * util
                out_qty = float(spec.get("output_qty", 0) or 0) * active_q
                svc_mk = self.markets.get(market_key(sid, service))
                if svc_mk and out_qty > 1e-9:
                    unit_cost = re_service_unit_cost(self, sid, kind)
                    svc_mk.sell_orders.append(
                        SellOrder(
                            f"re_op_{sid}_{kind}", out_qty, 1,
                            unit_cost=unit_cost,
                            ask_price=company_product_ask_price(
                                None, service, sid, self.markets, self.labor_markets,
                                unit_cost=unit_cost,
                                tech_level=1,
                                states=self.states,
                                world=self,
                                advance=True,
                                path_owner="re",
                            )[0],
                        ))
                for inp, iq in (spec.get("inputs") or {}).items():
                    need = float(iq) * active_q
                    if need <= 1e-9:
                        continue
                    imk = self.markets.get(market_key(sid, inp))
                    if imk:
                        imk.buy_orders.append(BuyOrder(f"re_op_{sid}_{kind}", need))

    def _collect_pop_farm_orders(self) -> None:
        """POP 자영농: 노동 가능 인구를 상한으로 시장 잔여 수요에 맞춰 생산."""
        for st in self.states.values():
            farm_sector = (st.self_employed or {}).get("farm")
            actor = self_employed_actor_id(st.id, "farm")
            pop_caps: List[Tuple["POP", float]] = []
            total_cap = 0.0
            for pop in st.pops:
                unemp = float(getattr(pop, "adult_unemployed", 0.0) or 0.0)
                self_emp = float(getattr(pop, "adult_self_employed", 0.0) or 0.0)
                farm_q = max(0.0, (unemp + self_emp) * 0.35)
                if farm_q < 0.25:
                    pop.farm_land[st.id] = 0.0
                    continue
                pop_caps.append((pop, farm_q))
                total_cap += farm_q
            agri_gap = self_emp_product_market_gap(
                self, st, "농업 상품", exclude_actor=actor, prefer_live=True)
            meat_gap = self_emp_product_market_gap(
                self, st, "축산품", exclude_actor=actor, prefer_live=True)
            out_per = RE_POP_FARM_OUTPUT_QTY * float(SELF_EMP_OUTPUT_MULTIPLIER)
            agri_need_q = agri_gap / max(out_per, 1e-9)
            meat_need_q = meat_gap / max(out_per * 0.75, 1e-9)
            desired = agri_need_q + meat_need_q
            remaining = min(total_cap, desired)
            assigned: List[Tuple["POP", float]] = []
            for pop, cap in sorted(pop_caps, key=lambda row: -row[1]):
                if remaining <= 1e-9:
                    pop.farm_land[st.id] = 0.0
                    continue
                take = min(cap, remaining)
                pop.farm_land[st.id] = take
                assigned.append((pop, take))
                remaining -= take
            total_farm = 0.0
            for pop, farm_q in assigned:
                total_farm += farm_q
                ltype, lqty = RE_POP_FARM_LABOR
                lm = self.labor_markets.get(market_key(st.id, ltype))
                if lm:
                    lm.buy_orders.append(BuyOrder(actor, float(lqty) * farm_q))
                for item, qty in RE_POP_FARM_INPUTS.items():
                    mk = self.markets.get(market_key(st.id, item))
                    if mk:
                        mk.buy_orders.append(BuyOrder(actor, float(qty) * farm_q))
            if farm_sector is not None:
                farm_sector.rental_ordered = 0.0
                farm_sector.rental_filled = total_farm
                if total_farm > 1e-9 and desired > 1e-9:
                    agri_out = out_per * total_farm * (agri_need_q / desired)
                    meat_out = out_per * 0.75 * total_farm * (meat_need_q / desired)
                    for product, out in (("농업 상품", agri_out), ("축산품", meat_out)):
                        if out <= 1e-9:
                            continue
                        mk = market_key(st.id, product)
                        farm_sector.planned_output[mk] = (
                            farm_sector.planned_output.get(mk, 0.0) + out)
                        m = self.markets.get(mk)
                        if m:
                            ask, uc = self_emp_sector_product_ask(
                                self, st.id, product,
                                sector_key="farm", tech_level=1, advance=True,
                            )
                            m.sell_orders.append(
                                SellOrder(actor, out, 1, ask_price=ask, unit_cost=uc))

